def replay_history_end_utc_for_days(days: Iterable[str]) -> str:
    """Return the exclusive history end required for replay decision bars."""

    required_end = datetime.fromisoformat(HTF_LOOKBACK_END).date()
    for raw_day in days:
        text = str(raw_day or "").strip()
        if not text:
            continue
        if len(text) == 10:
            day = datetime.fromisoformat(text).date()
        else:
            normalized = text[:-1] + "+00:00" if text.endswith("Z") else text
            parsed = datetime.fromisoformat(normalized)
            if parsed.tzinfo is not None:
                parsed = parsed.astimezone(timezone.utc)
            day = parsed.date()
        required_end = max(required_end, day + timedelta(days=1))
    return required_end.isoformat()

