@dataclass(frozen=True)
class SourceSpec:
    symbol: str
    mapped_symbol: str
    timeframe: str
    path: Path
    source_family: str
    source_broker: str
    source_role: str
    start_utc: str | None = None
    end_utc: str | None = None
    row_count: int | None = None
    sha256: str | None = None
    export_tool: str | None = None
    manifest_path: str | None = None
    source_server_redacted: str | None = None
    source_server_hash: str | None = None
    source_account_redacted: str | None = None
    source_account_hash: str | None = None
    diagnostic_fallback_only: bool = False
    source_truth_scope: str = SOURCE_TRUTH_SCOPE
    not_redacted_account_native: bool = True
    replaces_missing_frozen_path_source: bool = False
    broker_lifecycle_truth_satisfied: bool = False
    ordered_tick_truth_satisfied: bool = False


@dataclass(frozen=True)
class ResolvedSource:
    spec: SourceSpec
    rows: tuple[dict[str, Any], ...]
    rows_by_day: Mapping[str, tuple[dict[str, Any], ...]]
    sha256: str
    day_counts: Mapping[str, int]
    selected_status: str
    min_required_rows_per_day: int
    source_gaps: tuple[str, ...] = ()
    component_source_labels: tuple[dict[str, Any], ...] = ()
    day_source_authority: Mapping[str, Mapping[str, Any]] = field(
        default_factory=dict
    )

    def source_label(self) -> dict[str, Any]:
        return {
            "symbol": self.spec.symbol,
            "mapped_symbol": self.spec.mapped_symbol,
            "timeframe": self.spec.timeframe,
            "path": str(self.spec.path),
            "source_family": self.spec.source_family,
            "source_broker": self.spec.source_broker,
            "source_role": self.spec.source_role,
            "source_truth_scope": self.spec.source_truth_scope,
            "not_redacted_account_native": self.spec.not_redacted_account_native,
            "replaces_missing_frozen_path_source": self.spec.replaces_missing_frozen_path_source,
            "broker_lifecycle_truth_satisfied": self.spec.broker_lifecycle_truth_satisfied,
            "ordered_tick_truth_satisfied": self.spec.ordered_tick_truth_satisfied,
            "diagnostic_fallback_only": self.spec.diagnostic_fallback_only,
            "start_utc": self.spec.start_utc,
            "end_utc": self.spec.end_utc,
            "row_count": self.spec.row_count if self.spec.row_count is not None else len(self.rows),
            "sha256": self.sha256,
            "source_sha256": self.sha256,
            "export_tool": self.spec.export_tool,
            "manifest_path": self.spec.manifest_path,
            "source_server_redacted": self.spec.source_server_redacted,
            "source_server_hash": self.spec.source_server_hash,
            "source_account_redacted": self.spec.source_account_redacted,
            "source_account_hash": self.spec.source_account_hash,
            "selected_status": self.selected_status,
            "source_gaps": list(self.source_gaps),
            "day_source_authority_count": len(self.day_source_authority),
        }


def m1_symbol_day_source_authority(
    *,
    symbol: str,
    trading_day: str,
    m1_row_count: int,
    m15_row_count: int,
    source_day_sha256: str | None = None,
    source_path: str | None = None,
    source_family: str | None = None,
    source_file_sha256: str | None = None,
    absolute_min_rows: int = M1_MIN_ROWS_PER_DAY,
) -> dict[str, Any]:
    """Build immutable M1 replay authority for one symbol and trading day."""

    m1_rows = max(0, int(m1_row_count))
    m15_rows = max(0, int(m15_row_count))
    absolute_floor = max(1, int(absolute_min_rows))
    expected_rows = m15_rows * M1_EXPECTED_ROWS_PER_M15_BAR
    session_floor = (
        max(1, math.ceil(expected_rows * M1_MIN_SESSION_COVERAGE_RATIO))
        if m15_rows
        else None
    )
    effective_floor = (
        min(absolute_floor, session_floor)
        if session_floor is not None
        else absolute_floor
    )
    coverage_ratio = m1_rows / expected_rows if expected_rows else None

    if m1_rows == 0 and m15_rows == 0:
        status = "ftmo_verified_no_session_day"
        session_status = "ftmo_verified_no_session_day"
        diagnostic_only = False
        gaps: list[str] = []
        path_replay_allowed = False
        terminal_close_allowed = False
        effective_floor = 0
    elif m15_rows == 0:
        status = "m1_populated_m15_session_reference_missing"
        session_status = "m15_session_reference_missing"
        diagnostic_only = True
        gaps = ["m1_populated_m15_session_reference_missing"]
        path_replay_allowed = False
        terminal_close_allowed = False
    elif m1_rows >= effective_floor:
        session_scaled = effective_floor < absolute_floor
        status = (
            "selected_day_source_meets_session_scaled_floor"
            if session_scaled
            else "selected_day_source_meets_absolute_floor"
        )
        session_status = (
            "redacted_accountortened_or_partial_session_reference"
            if session_scaled
            else "ftmo_regular_session_reference"
        )
        diagnostic_only = False
        gaps = []
        path_replay_allowed = True
        terminal_close_allowed = True
    else:
        status = "selected_day_source_below_session_scaled_floor"
        session_status = (
            "redacted_accountortened_or_partial_session_reference"
            if effective_floor < absolute_floor
            else "ftmo_regular_session_reference"
        )
        diagnostic_only = True
        gaps = ["m1_symbol_day_below_session_scaled_floor"]
        path_replay_allowed = False
        terminal_close_allowed = False

    source_day_hash = str(source_day_sha256 or "").strip() or stable_sha256(
        {
            "symbol": str(symbol),
            "trading_day": str(trading_day),
            "m1_row_count": m1_rows,
            "m15_row_count": m15_rows,
            "source_file_sha256": source_file_sha256,
        }
    )
    payload = {
        "schema": SOURCE_DAY_AUTHORITY_SCHEMA,
        "symbol": str(symbol),
        "timeframe": "M1",
        "trading_day": str(trading_day),
        "source_day_sha256": source_day_hash,
        "source_path": source_path,
        "source_family": source_family,
        "source_file_sha256": source_file_sha256,
        "status": status,
        "source_session_status": session_status,
        "diagnostic_fallback_only": diagnostic_only,
        "source_gaps": gaps,
        "m1_row_count": m1_rows,
        "m15_row_count": m15_rows,
        "absolute_min_rows": absolute_floor,
        "session_scaled_min_rows": session_floor,
        "effective_min_rows": effective_floor,
        "expected_m1_rows_from_m15_session": expected_rows,
        "m1_to_m15_expected_coverage_ratio": (
            round(coverage_ratio, 8) if coverage_ratio is not None else None
        ),
        "session_scaled_floor_applied": bool(
            session_floor is not None and effective_floor < absolute_floor
        ),
        "path_replay_allowed": path_replay_allowed,
        "terminal_lifecycle_close_allowed": terminal_close_allowed,
        "headline_fill_authority_allowed": False,
        "diagnostic_replay_allowed": bool(m1_rows),
    }
    return source_day_authority_with_updates(payload)


def source_day_authority_with_updates(
    authority: Mapping[str, Any],
    **updates: Any,
) -> dict[str, Any]:
    """Return a rehashed immutable source-day authority disposition."""

    payload = {
        key: value
        for key, value in dict(authority).items()
        if key
        not in {
            "source_day_authority_id",
            "source_day_authority_hash_sha256",
            "authority_scope",
        }
    }
    payload.update(updates)
    authority_hash = stable_sha256(payload)
    return {
        **payload,
        "source_day_authority_id": f"source_day:{authority_hash[:24]}",
        "source_day_authority_hash_sha256": authority_hash,
    }


def resolved_source_day_authority(
    source: ResolvedSource,
    day: str,
) -> dict[str, Any]:
    """Return the narrowest source authority for one replay trading day."""

    explicit = source.day_source_authority.get(str(day))
    if isinstance(explicit, Mapping):
        return {
            **dict(explicit),
            "trading_day": str(day),
            "authority_scope": "symbol_day",
            "source_gaps": list(explicit.get("source_gaps") or ()),
            "diagnostic_fallback_only": bool(
                explicit.get("diagnostic_fallback_only")
            ),
        }
    fallback = {
        "schema": SOURCE_DAY_AUTHORITY_SCHEMA,
        "symbol": source.spec.symbol,
        "timeframe": source.spec.timeframe,
        "trading_day": str(day),
        "authority_scope": "whole_resolved_source_fallback",
        "status": source.selected_status,
        "source_gaps": list(source.source_gaps),
        "diagnostic_fallback_only": bool(
            source.spec.diagnostic_fallback_only
        ),
        "path_replay_allowed": not source.spec.diagnostic_fallback_only,
        "terminal_lifecycle_close_allowed": not source.spec.diagnostic_fallback_only,
    }
    authority_hash = stable_sha256(fallback)
    return {
        **fallback,
        "source_day_authority_id": f"source_day:{authority_hash[:24]}",
        "source_day_authority_hash_sha256": authority_hash,
    }


