class SimulatedBroker:
    """Replay-only broker/account adapter with broker mutation disabled."""

    broker_mutation_enabled = False
    broker_history_truth_satisfied = False
    evidence_class = SIM_EVIDENCE_CLASS

    def __init__(self, account: AccountState | None = None):
        self.account = account or AccountState()
        self.order_send_attempts = 0

    def get_account_balance(self) -> float:
        return self.account.balance

    def get_account_equity(self) -> float:
        return self.account.equity

    def get_positions(self, symbol: str | None = None) -> list[dict[str, Any]]:
        asof = datetime.now(timezone.utc)
        rows = self.account.open_snapshot(asof)
        if symbol:
            return [row for row in rows if row.get("symbol") == symbol]
        return rows

    def get_pending_orders(self, symbol: str | None = None) -> list[dict[str, Any]]:
        asof = datetime.now(timezone.utc)
        rows = self.account.pending_snapshot(asof)
        if symbol:
            return [row for row in rows if row.get("symbol") == symbol]
        return rows

    def order_send(self, request: Mapping[str, Any]) -> Any:
        self.order_send_attempts += 1
        raise RuntimeError("SimulatedBroker is replay-only; broker mutation is disabled")

    def mutation_boundary(self) -> dict[str, Any]:
        return {
            "broker_adapter": "SimulatedBroker",
            "broker_mutation_enabled": False,
            "broker_account_order_history_deal_position_mutation": False,
            "broker_history_truth_satisfied": False,
            "evidence_class": self.evidence_class,
            "order_send_attempts": self.order_send_attempts,
        }


@dataclass(frozen=True)
class CampaignConfig:
    name: str
    phase: str
    days: tuple[str, ...]
    pending_expiry_minutes: int
    use_repaired_pending_expiry: bool
    profile: str = ""
    partial_be_runner: bool = True
    max_candidates_per_symbol_window: int = 0
    run_smoke_subset: bool = False
    materialize_packet_sidecars: bool = True
    materialize_semantic_diagnostics: bool = False
    candidate_ledger_packet_max_bytes: int = 20_000
    scorecard_ledger_packet_max_bytes: int = 20_000
    compact_scorecard_symbol_risk_config: bool = False
    scorecard_probe_row_limit: int | None = None


def utc_now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def _replay_profile_stage(stage_profiler: Any | None, name: str) -> Any:
    if stage_profiler is None:
        return nullcontext()
    return stage_profiler.stage(name)


def _replay_profile_call(
    stage_profiler: Any | None,
    name: str,
    *,
    amount: int = 1,
) -> None:
    if stage_profiler is not None:
        stage_profiler.count_call(name, amount=amount)


def _replay_profile_timing_start(stage_profiler: Any | None) -> int | None:
    start = getattr(stage_profiler, "start_timing", None)
    return start() if callable(start) else None


def _replay_profile_timing_record(
    stage_profiler: Any | None,
    name: str,
    started_ns: int | None,
) -> None:
    record = getattr(stage_profiler, "record_timing", None)
    if callable(record) and started_ns is not None:
        record(name, started_ns=started_ns)


def iso(dt: datetime | None) -> str | None:
    if dt is None:
        return None
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc).isoformat()


def _stable_sha256_material(payload: Any) -> str:
    return json.dumps(
        payload,
        sort_keys=True,
        separators=(",", ":"),
        default=str,
    )


def _stable_sha256_uncached(payload: Any) -> str:
    material = _stable_sha256_material(payload)
    return hashlib.sha256(material.encode("utf-8")).hexdigest()


def stable_sha256(payload: Any) -> str:
    active_cache_var = globals().get("_ACTIVE_CAMPAIGN_EXACT_CACHE")
    cache = active_cache_var.get() if active_cache_var is not None else None
    if cache is not None:
        return cache.exact_sha256(payload)
    return _stable_sha256_uncached(payload)


class CampaignExactCacheError(RuntimeError):
    """Fail-closed campaign-cache identity or mutation error."""


def _campaign_cache_projection(value: Any) -> Any:
    if isinstance(value, SchedulerV4Config):
        return asdict(value)
    if isinstance(value, TimeframeState):
        return value.model_dump(mode="json")
    return value


def _exact_hash_cache_scalar(value: Any) -> Any:
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    return type(value).__name__


def _exact_hash_cache_key(value: Any) -> tuple[Any, ...] | None:
    projected = _campaign_cache_projection(value)
    if isinstance(projected, Mapping):
        return (
            "mapping",
            _exact_hash_cache_scalar(projected.get("schema")),
            _exact_hash_cache_scalar(projected.get("schema_version")),
            _exact_hash_cache_scalar(projected.get("candidate_id")),
            _exact_hash_cache_scalar(projected.get("decision_time_utc")),
            _exact_hash_cache_scalar(projected.get("packet_sidecar_id")),
            _exact_hash_cache_scalar(projected.get("type")),
            _exact_hash_cache_scalar(projected.get("scope")),
            len(projected),
        )
    if isinstance(projected, (list, tuple)):
        return (
            type(projected).__name__,
            len(projected),
            _exact_hash_cache_scalar(projected[0]) if projected else None,
            _exact_hash_cache_scalar(projected[-1]) if projected else None,
        )
    return None


@dataclass
class CampaignExactCache:
    """Strongly bound exact projections reused only inside one replay profile.

    The cache retains the actual configuration object, not an ``id()``-only
    key.  Full configuration, risk-source, and cached-output roots are checked
    at every chunk boundary.  Hot calls therefore pay only a strong-reference
    check while in-flight mutation still fails closed between chunks.
    """

    config: Mapping[str, Any]
    config_root_sha256: str
    risk_profile_path: str
    risk_profile_sha256: str
    expected_risk_profile_sha256: str
    risk_profile_payload_root_sha256: str
    _risk_profile_payload: Mapping[str, Any]
    risk_profile_source: str
    scheduler_projection: dict[str, Any] | None = None
    typed_scheduler_projection: SchedulerV4Config | None = None
    risk_pct_by_symbol: dict[str, tuple[float, str]] = field(default_factory=dict)
    risk_limits_by_symbol: dict[str, dict[str, Any]] = field(default_factory=dict)
    replay_symbol_configs: dict[str, dict[str, Any]] = field(default_factory=dict)
    broker_symbol_configs: dict[str, dict[str, Any]] = field(default_factory=dict)
    _timeframe_state_by_symbol_timeframe: dict[
        tuple[str, str], dict[str, Any]
    ] = field(default_factory=dict)
    timeframe_state_hits: Counter[str] = field(default_factory=Counter)
    timeframe_state_misses: Counter[str] = field(default_factory=Counter)
    timeframe_state_builds: Counter[str] = field(default_factory=Counter)
    timeframe_state_evictions: Counter[str] = field(default_factory=Counter)
    miss_counts: Counter[str] = field(default_factory=Counter)
    _output_roots: dict[str, tuple[Any, str]] = field(default_factory=dict)
    _exact_hash_cache: OrderedDict[
        tuple[Any, ...],
        tuple[tuple[str, str], ...],
    ] = field(default_factory=OrderedDict)
    _exact_hash_cache_entry_count: int = 0
    exact_hash_hits: int = 0
    exact_hash_misses: int = 0
    closed: bool = False

    @classmethod
    def from_config(
        cls,
        config: Mapping[str, Any],
        *,
        expected_risk_profile_sha256: str | None = None,
    ) -> "CampaignExactCache":
        if not isinstance(config, Mapping):
            raise CampaignExactCacheError("config_not_mapping")
        payload, source, path, source_sha256 = _load_bound_risk_profile_payload(
            config
        )
        expected_sha256 = str(expected_risk_profile_sha256 or source_sha256)
        if expected_sha256 != source_sha256:
            raise CampaignExactCacheError(
                "risk_profile_expected_sha256_mismatch"
            )
        private_payload = copy.deepcopy(dict(payload))
        cache = cls(
            config=config,
            config_root_sha256=stable_sha256(config),
            risk_profile_path=str(path),
            risk_profile_sha256=source_sha256,
            expected_risk_profile_sha256=expected_sha256,
            risk_profile_payload_root_sha256=stable_sha256(private_payload),
            _risk_profile_payload=private_payload,
            risk_profile_source=source,
        )
        _register_campaign_exact_cache(cache)
        return cache

    @property
    def risk_profile_payload(self) -> dict[str, Any]:
        return copy.deepcopy(dict(self._risk_profile_payload))

    def _require_config(self, config: Mapping[str, Any]) -> None:
        if self.closed:
            raise CampaignExactCacheError("cache_closed")
        if config is not self.config:
            raise CampaignExactCacheError("config_reference_mismatch")

    def _bind_output(self, key: str, value: Any) -> Any:
        self._output_roots[key] = (
            value,
            stable_sha256(_campaign_cache_projection(value)),
        )
        return value

    def exact_sha256(self, value: Any) -> str:
        """Reuse only a full-equality-matching hash preimage within this campaign."""

        self._require_config(self.config)
        cache_key = _exact_hash_cache_key(value)
        if cache_key is None:
            return _stable_sha256_uncached(value)
        canonical_preimage = _stable_sha256_material(value)
        cached_variants = self._exact_hash_cache.get(cache_key, ())
        for cached_preimage, cached_digest in cached_variants:
            if canonical_preimage == cached_preimage:
                self.exact_hash_hits += 1
                self._exact_hash_cache.move_to_end(cache_key)
                return cached_digest
        self.exact_hash_misses += 1
        digest = _stable_sha256_uncached(value)
        replacement_variants = (
            (canonical_preimage, digest),
            *tuple(
                variant
                for variant in cached_variants
                if variant[0] != canonical_preimage
            )[:31],
        )
        self._exact_hash_cache_entry_count += (
            len(replacement_variants) - len(cached_variants)
        )
        self._exact_hash_cache[cache_key] = replacement_variants
        self._exact_hash_cache.move_to_end(cache_key)
        while self._exact_hash_cache_entry_count > 1024:
            _, evicted = self._exact_hash_cache.popitem(last=False)
            self._exact_hash_cache_entry_count -= len(evicted)
        return digest

    @staticmethod
    def _symbol_key(symbol: Any) -> str:
        return "<NONE>" if symbol is None else str(symbol)

    def scheduler_config(self, config: Mapping[str, Any]) -> dict[str, Any]:
        self._require_config(config)
        if self.scheduler_projection is None:
            self.miss_counts["scheduler_config"] += 1
            self.scheduler_projection = self._bind_output(
                "scheduler_config",
                _scheduler_config_uncached(config),
            )
        return self.scheduler_projection

    def typed_scheduler_config(
        self,
        config: Mapping[str, Any],
    ) -> SchedulerV4Config:
        self._require_config(config)
        if self.typed_scheduler_projection is None:
            self.miss_counts["typed_scheduler_config"] += 1
            self.typed_scheduler_projection = self._bind_output(
                "typed_scheduler_config",
                SchedulerV4Config.from_mapping(self.scheduler_config(config)),
            )
        return self.typed_scheduler_projection

    def risk_pct(
        self,
        config: Mapping[str, Any],
        symbol: Any,
    ) -> tuple[float, str]:
        self._require_config(config)
        key = self._symbol_key(symbol)
        if key not in self.risk_pct_by_symbol:
            self.miss_counts["risk_pct"] += 1
            value = _risk_pct_for_symbol_uncached(
                config,
                symbol,
                profile_override=(
                    self._risk_profile_payload,
                    self.risk_profile_source,
                ),
            )
            self.risk_pct_by_symbol[key] = self._bind_output(
                f"risk_pct:{key}",
                value,
            )
        return self.risk_pct_by_symbol[key]

    def risk_limits(
        self,
        config: Mapping[str, Any],
        symbol: Any,
    ) -> dict[str, Any]:
        self._require_config(config)
        key = self._symbol_key(symbol)
        if key not in self.risk_limits_by_symbol:
            self.miss_counts["risk_limits"] += 1
            self.risk_limits_by_symbol[key] = self._bind_output(
                f"risk_limits:{key}",
                _configured_runtime_risk_limits_uncached(
                    config,
                    symbol=symbol,
                ),
            )
        return self.risk_limits_by_symbol[key]

    def replay_symbol_config(
        self,
        config: Mapping[str, Any],
        symbol: str,
    ) -> dict[str, Any]:
        self._require_config(config)
        key = str(symbol)
        if key not in self.replay_symbol_configs:
            self.miss_counts["replay_symbol_config"] += 1
            self.replay_symbol_configs[key] = self._bind_output(
                f"replay_symbol_config:{key}",
                _replay_symbol_config_uncached(config, symbol),
            )
        return self.replay_symbol_configs[key]

    def broker_symbol_config(
        self,
        config: Mapping[str, Any],
        symbol: str,
    ) -> dict[str, Any]:
        self._require_config(config)
        key = str(symbol)
        if key not in self.broker_symbol_configs:
            self.miss_counts["broker_symbol_config"] += 1
            self.broker_symbol_configs[key] = self._bind_output(
                f"broker_symbol_config:{key}",
                _broker_symbol_config_uncached(config, symbol),
            )
        return self.broker_symbol_configs[key]

    def closed_timeframe_state(
        self,
        config: Mapping[str, Any],
        *,
        timeframe: str,
        symbol: str,
        candles: Sequence[Mapping[str, Any]],
        source_identity: Mapping[str, Any],
        build_parameters: Mapping[str, Any],
        side_effect_writes_enabled: bool,
        builder: Callable[[], TimeframeState],
    ) -> TimeframeState:
        """Return a private, root-checked closed D1/H4/H1 state."""

        self._require_config(config)
        timeframe_key = str(timeframe).upper()
        if timeframe_key not in {"D1", "H4", "H1"}:
            raise CampaignExactCacheError(
                "closed_timeframe_state_scope_invalid"
            )
        error_prefix = timeframe_key.lower()
        if side_effect_writes_enabled or build_parameters.get(
            "shadow_logging_enabled"
        ) is not False:
            raise CampaignExactCacheError(
                f"{error_prefix}_market_state_side_effects_must_be_disabled"
            )
        expected_source_fields = {
            "source_path",
            "source_hash",
            "source_broker",
            "source_role",
            "requested_count",
            "returned_count",
            "latest_closed_time",
        }
        if set(source_identity) != expected_source_fields:
            raise CampaignExactCacheError(
                f"{error_prefix}_source_identity_invalid"
            )
        selected_row_count = len(candles)
        requested_count = source_identity.get("requested_count")
        returned_count = source_identity.get("returned_count")
        source_path = str(source_identity.get("source_path") or "")
        source_hash = str(source_identity.get("source_hash") or "")
        source_broker = str(source_identity.get("source_broker") or "")
        source_role = str(source_identity.get("source_role") or "")
        latest_closed_time = str(
            source_identity.get("latest_closed_time") or ""
        )
        actual_latest_time = str(
            first_present(
                candles[-1].get("time_utc") if candles else None,
                candles[-1].get("time") if candles else None,
            )
            or ""
        )
        if (
            not source_path
            or len(source_hash) != 64
            or any(char not in "009abcdef" for char in source_hash)
            or not source_broker
            or not source_role
            or type(requested_count) is not int
            or requested_count <= 0
            or type(returned_count) is not int
            or returned_count != selected_row_count
            or selected_row_count <= 0
            or latest_closed_time != actual_latest_time
        ):
            raise CampaignExactCacheError(
                f"{error_prefix}_source_identity_invalid"
            )
        build_projection = {
            "min_bars": build_parameters.get("min_bars"),
            "fvg_min_gap": build_parameters.get("fvg_min_gap"),
            "tf_name": build_parameters.get("tf_name"),
            "detector_mode": build_parameters.get("detector_mode"),
            "detector_dead_zone_divisor": build_parameters.get(
                "detector_dead_zone_divisor"
            ),
            "shadow_symbol": build_parameters.get("shadow_symbol"),
            "shadow_logging_enabled": build_parameters.get(
                "shadow_logging_enabled"
            ),
            "side_effect_writes_enabled": side_effect_writes_enabled,
        }
        if (
            build_projection["tf_name"] != timeframe_key
            or build_projection["shadow_symbol"] != str(symbol)
            or build_projection["shadow_logging_enabled"] is not False
            or build_projection["side_effect_writes_enabled"] is not False
        ):
            raise CampaignExactCacheError(
                f"{error_prefix}_build_projection_invalid"
            )
        base_identity = {
            "schema": (
                "gtos.replay_acceleration.closed_timeframe_state_cache.v1"
            ),
            "symbol": str(symbol),
            "timeframe": timeframe_key,
            "source_path": source_path,
            "source_sha256": source_hash,
            "source_broker": source_broker,
            "source_role": source_role,
            "build_projection": build_projection,
        }
        request_identity = {
            "requested_count": requested_count,
            "selected_row_count": selected_row_count,
            "latest_closed_time": latest_closed_time,
        }
        symbol_key = str(symbol)
        cache_key = (symbol_key, timeframe_key)
        output_key = f"closed_timeframe_state:{symbol_key}:{timeframe_key}"
        existing = self._timeframe_state_by_symbol_timeframe.get(cache_key)
        if existing is not None:
            existing_base = existing.get("base_identity")
            existing_request = existing.get("request_identity")
            same_base = existing_base == base_identity
            same_endpoint = (
                isinstance(existing_request, Mapping)
                and existing_request.get("requested_count")
                == request_identity["requested_count"]
                and existing_request.get("selected_row_count")
                == request_identity["selected_row_count"]
                and existing_request.get("latest_closed_time")
                == request_identity["latest_closed_time"]
            )
            if same_base and same_endpoint:
                payload = existing.get("payload")
                expected_root = existing.get("payload_root_sha256")
                bound_output = self._output_roots.get(output_key)
                if (
                    not isinstance(payload, TimeframeState)
                    or not isinstance(expected_root, str)
                    or len(expected_root) != 64
                    or bound_output is None
                    or bound_output[0] is not payload
                    or bound_output[1] != expected_root
                ):
                    raise CampaignExactCacheError(
                        "cached_output_mutated:closed_timeframe_state:"
                        f"{timeframe_key}"
                    )
                self.timeframe_state_hits[timeframe_key] += 1
                return payload.model_copy(deep=True)
            self.timeframe_state_evictions[timeframe_key] += 1
            self._timeframe_state_by_symbol_timeframe.pop(cache_key, None)
            self._output_roots.pop(output_key, None)

        self.timeframe_state_misses[timeframe_key] += 1
        built = builder()
        if not isinstance(built, TimeframeState):
            raise CampaignExactCacheError(
                f"{error_prefix}_builder_result_invalid"
            )
        self.timeframe_state_builds[timeframe_key] += 1
        private_payload = built.model_copy(deep=True)
        payload_root = stable_sha256(private_payload.model_dump(mode="json"))
        self._timeframe_state_by_symbol_timeframe[cache_key] = {
            "base_identity": base_identity,
            "request_identity": request_identity,
            "payload": private_payload,
            "payload_root_sha256": payload_root,
        }
        self._bind_output(output_key, private_payload)
        return built

    def d1_timeframe_state(
        self,
        config: Mapping[str, Any],
        **kwargs: Any,
    ) -> TimeframeState:
        """Compatibility wrapper for the first Task 4 D1 tracer."""

        return self.closed_timeframe_state(
            config,
            timeframe="D1",
            **kwargs,
        )

    def market_state_cache_audit(self) -> dict[str, int]:
        audit: dict[str, int] = {}
        for timeframe in ("D1", "H4", "H1"):
            active = (
                self.timeframe_state_hits[timeframe]
                or self.timeframe_state_misses[timeframe]
                or any(
                    key_timeframe == timeframe
                    for _symbol, key_timeframe in (
                        self._timeframe_state_by_symbol_timeframe
                    )
                )
            )
            if not active:
                continue
            prefix = timeframe.lower()
            audit[f"{prefix}_hits"] = int(
                self.timeframe_state_hits[timeframe]
            )
            audit[f"{prefix}_misses"] = int(
                self.timeframe_state_misses[timeframe]
            )
            audit[f"{prefix}_builds"] = int(
                self.timeframe_state_builds[timeframe]
            )
            audit[f"{prefix}_evictions"] = int(
                self.timeframe_state_evictions[timeframe]
            )
            audit[f"{prefix}_entries"] = sum(
                int(key_timeframe == timeframe)
                for _symbol, key_timeframe in (
                    self._timeframe_state_by_symbol_timeframe
                )
            )
        return audit

    def validate_boundary(self, config: Mapping[str, Any]) -> None:
        self._require_config(config)
        if stable_sha256(config) != self.config_root_sha256:
            raise CampaignExactCacheError("config_root_mismatch")
        path, source_sha256 = _risk_profile_file_binding(config)
        if (
            str(path) != self.risk_profile_path
            or source_sha256 != self.risk_profile_sha256
            or source_sha256 != self.expected_risk_profile_sha256
        ):
            raise CampaignExactCacheError("risk_profile_binding_mismatch")
        if (
            stable_sha256(self._risk_profile_payload)
            != self.risk_profile_payload_root_sha256
        ):
            raise CampaignExactCacheError("risk_profile_payload_root_mismatch")
        for key, (value, expected_root) in self._output_roots.items():
            if stable_sha256(_campaign_cache_projection(value)) != expected_root:
                raise CampaignExactCacheError(f"cached_output_mutated:{key}")

    def audit(self, config: Mapping[str, Any]) -> dict[str, Any]:
        self.validate_boundary(config)
        audit = {
            "schema": "gtos.replay_acceleration.campaign_exact_cache.v1",
            "status": "exact_cache_boundary_valid",
            "config_root_sha256": self.config_root_sha256,
            "risk_profile_path": self.risk_profile_path,
            "risk_profile_sha256": self.risk_profile_sha256,
            "expected_risk_profile_sha256": (
                self.expected_risk_profile_sha256
            ),
            "risk_profile_payload_root_sha256": (
                self.risk_profile_payload_root_sha256
            ),
            "miss_counts": {
                key: int(value) for key, value in sorted(self.miss_counts.items())
            },
            "cached_symbol_counts": {
                "risk_pct": len(self.risk_pct_by_symbol),
                "risk_limits": len(self.risk_limits_by_symbol),
                "replay_symbol_config": len(self.replay_symbol_configs),
                "broker_symbol_config": len(self.broker_symbol_configs),
            },
            "live_broker_authority": False,
            "broker_mutation_enabled": False,
        }
        market_state_cache = self.market_state_cache_audit()
        if market_state_cache:
            audit["shared_market_state_cache"] = market_state_cache
        return audit

    def close(self) -> None:
        self.scheduler_projection = None
        self.typed_scheduler_projection = None
        self.risk_pct_by_symbol.clear()
        self.risk_limits_by_symbol.clear()
        self.replay_symbol_configs.clear()
        self.broker_symbol_configs.clear()
        self._timeframe_state_by_symbol_timeframe.clear()
        self._output_roots.clear()
        self._exact_hash_cache.clear()
        self._exact_hash_cache_entry_count = 0
        self._risk_profile_payload = {}
        self.closed = True


_ACTIVE_CAMPAIGN_EXACT_CACHE: ContextVar[CampaignExactCache | None] = ContextVar(
    "gtos_replay_campaign_exact_cache",
    default=None,
)
_OWNED_CAMPAIGN_EXACT_CACHES: ContextVar[
    list[CampaignExactCache] | None
] = ContextVar("gtos_owned_campaign_exact_caches", default=None)


def _register_campaign_exact_cache(cache: CampaignExactCache) -> None:
    owner = _OWNED_CAMPAIGN_EXACT_CACHES.get()
    if owner is not None:
        owner.append(cache)


@contextmanager
def own_campaign_exact_caches() -> Iterable[list[CampaignExactCache]]:
    if _OWNED_CAMPAIGN_EXACT_CACHES.get() is not None:
        raise CampaignExactCacheError("nested_cache_owner_forbidden")
    owned: list[CampaignExactCache] = []
    token = _OWNED_CAMPAIGN_EXACT_CACHES.set(owned)
    try:
        yield owned
    finally:
        for cache in reversed(owned):
            cache.close()
        _OWNED_CAMPAIGN_EXACT_CACHES.reset(token)


def active_campaign_exact_cache() -> CampaignExactCache | None:
    return _ACTIVE_CAMPAIGN_EXACT_CACHE.get()


@contextmanager
def activate_campaign_exact_cache(
    cache: CampaignExactCache,
    config: Mapping[str, Any],
) -> Iterable[CampaignExactCache]:
    if active_campaign_exact_cache() is not None:
        raise CampaignExactCacheError("nested_cache_activation_forbidden")
    cache.validate_boundary(config)
    token = _ACTIVE_CAMPAIGN_EXACT_CACHE.set(cache)
    try:
        yield cache
        cache.validate_boundary(config)
    except BaseException:
        cache.close()
        raise
    finally:
        _ACTIVE_CAMPAIGN_EXACT_CACHE.reset(token)


def _campaign_exact_cache_scope(function: Any) -> Any:
    @wraps(function)
    def wrapped(*args: Any, **kwargs: Any) -> Any:
        cache = kwargs.get("campaign_exact_cache")
        if cache is None:
            return function(*args, **kwargs)
        config = kwargs.get("config")
        if not isinstance(cache, CampaignExactCache):
            raise CampaignExactCacheError("campaign_exact_cache_invalid")
        if not isinstance(config, Mapping):
            raise CampaignExactCacheError("campaign_exact_cache_config_missing")
        with activate_campaign_exact_cache(cache, config):
            return function(*args, **kwargs)

    return wrapped


def json_safe(payload: Any) -> Any:
    return json.loads(json.dumps(payload, sort_keys=True, default=str))


def build_lossless_semantic_order_preimage(
    *,
    campaign: str,
    profile: str,
    decision_window_id: str,
    canonical_replay_candidate_instance_key: str,
    candidate_id: str,
    simulated_order_id: str,
    decision_time_utc: str,
    trading_day: str,
    execution_manager_packet: Mapping[str, Any],
    broker_order_lifecycle_capture_v4_packet: Mapping[str, Any],
) -> dict[str, Any]:
    """Materialize an exact, owner-bound order packet preimage."""

    owner_values = {
        "campaign": campaign,
        "profile": profile,
        "decision_window_id": decision_window_id,
        "canonical_replay_candidate_instance_key": (
            canonical_replay_candidate_instance_key
        ),
        "candidate_id": candidate_id,
        "simulated_order_id": simulated_order_id,
        "decision_time_utc": decision_time_utc,
    }
    if any(type(value) is not str or not value.strip() for value in owner_values.values()):
        raise ValueError("semantic_order_preimage_owner_incomplete")
    try:
        parsed_day = date.fromisoformat(trading_day)
    except (TypeError, ValueError):
        raise ValueError("semantic_order_preimage_trading_day_invalid") from None
    if parsed_day.isoformat() != trading_day:
        raise ValueError("semantic_order_preimage_trading_day_invalid")
    if not isinstance(execution_manager_packet, Mapping) or not isinstance(
        broker_order_lifecycle_capture_v4_packet,
        Mapping,
    ):
        raise ValueError("semantic_order_preimage_packet_invalid")

    payload = {
        "execution_manager_packet": copy.deepcopy(
            dict(execution_manager_packet)
        ),
        "broker_order_lifecycle_capture_v4_packet": copy.deepcopy(
            dict(broker_order_lifecycle_capture_v4_packet)
        ),
    }
    payload_text = json.dumps(
        payload,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
        allow_nan=True,
    )
    payload_root = hashlib.sha256(payload_text.encode("ascii")).hexdigest()
    sidecar_id = stable_sha256(
        {
            "campaign": campaign,
            "candidate_id": candidate_id,
            "simulated_order_id": simulated_order_id,
            "type": "execution_manager_v4",
        }
    )
    return {
        "schema": "gtos.replay_acceleration.semantic_order_preimage.v1",
        "trading_day": trading_day,
        "execution_packet_sidecar_id": sidecar_id,
        "sidecar_payload_canonical_json": payload_text,
        "sidecar_payload_sha256": payload_root,
        "semantic_execution_manager_packet_sha256": stable_sha256(
            payload["execution_manager_packet"]
        ),
        "owner": {
            **owner_values,
            "payload_root_sha256": payload_root,
        },
    }


def materialize_semantic_selected_order_preimage(
    *,
    ledgers: MutableMapping[str, list[dict[str, Any]]],
    campaign: CampaignConfig,
    execution_identity_fields: Mapping[str, Any],
    candidate_id: str,
    simulated_order_id: str,
    decision_time_utc: str,
    trading_day: str,
    selected_order_sequence: int,
    producer_order_stream_index: int,
    producer_order_row: Mapping[str, Any],
    execution_manager_packet: Mapping[str, Any],
    broker_order_lifecycle_capture_v4_packet: Mapping[str, Any],
) -> dict[str, Any]:
    """Persist an out-of-band lossless preimage for one primary order."""

    if type(selected_order_sequence) is not int or selected_order_sequence < 1:
        raise ValueError("semantic_order_preimage_sequence_invalid")
    if (
        type(producer_order_stream_index) is not int
        or producer_order_stream_index < 0
        or not isinstance(producer_order_row, Mapping)
    ):
        raise ValueError("semantic_order_preimage_primary_order_invalid")
    order_ledger = ledgers.get("order")
    if (
        not isinstance(order_ledger, list)
        or producer_order_stream_index >= len(order_ledger)
        or order_ledger[producer_order_stream_index] is not producer_order_row
    ):
        raise ValueError(
            "semantic_order_preimage_primary_order_identity_mismatch"
        )
    preimage = build_lossless_semantic_order_preimage(
        campaign=campaign.name,
        profile=campaign.profile or campaign.phase,
        decision_window_id=str(
            execution_identity_fields.get("decision_window_id") or ""
        ),
        canonical_replay_candidate_instance_key=str(
            execution_identity_fields.get(
                "canonical_replay_candidate_instance_key"
            )
            or ""
        ),
        candidate_id=candidate_id,
        simulated_order_id=simulated_order_id,
        decision_time_utc=decision_time_utc,
        trading_day=trading_day,
        execution_manager_packet=execution_manager_packet,
        broker_order_lifecycle_capture_v4_packet=(
            broker_order_lifecycle_capture_v4_packet
        ),
    )
    preimage.update(
        {
            "semantic_order_preimage_id": stable_sha256(
                {
                    **preimage["owner"],
                    "trading_day": trading_day,
                    "type": "semantic_order_preimage",
                }
            ),
            "selected_order_attempt_primary": True,
            "selected_order_sequence": selected_order_sequence,
            "producer_order_stream_index": producer_order_stream_index,
            "producer_order_row_sha256": stable_sha256(producer_order_row),
        }
    )
    ledgers.setdefault("semantic_order_preimage", []).append(preimage)
    return preimage


def build_semantic_state_checkpoint(
    *,
    campaign: str,
    profile: str,
    trading_day: str,
    boundary: str,
    account: AccountState,
    broker: SimulatedBroker,
    selected_order_sequence: int,
) -> dict[str, Any]:
    """Capture the reducer state and its complete hash preimage.

    The preimage is diagnostic-only and is bound by the semantic-source
    manifest.  Persisting it lets an independent verifier recompute the opaque
    account root and prove that any cross-clock difference is confined to
    explicitly normalized closed-trade runtime provenance.
    """

    if boundary not in {"pre_day", "post_day"}:
        raise ValueError("semantic_state_checkpoint_boundary_invalid")
    if type(selected_order_sequence) is not int or selected_order_sequence < 0:
        raise ValueError("semantic_state_checkpoint_sequence_invalid")
    try:
        parsed_day = date.fromisoformat(trading_day)
    except (TypeError, ValueError):
        raise ValueError("semantic_state_checkpoint_trading_day_invalid") from None
    if parsed_day.isoformat() != trading_day:
        raise ValueError("semantic_state_checkpoint_trading_day_invalid")

    account_payload = json_safe(asdict(account))
    event_queue_payload = account_payload.get("event_queue", [])
    reservation_payload = {
        key: account_payload.get(key)
        for key in (
            "accepted_risk_orders_by_day",
            "accepted_risk_pct_by_day",
            "accepted_risk_orders_by_day_session",
            "accepted_risk_pct_by_day_session",
            "accepted_risk_orders_by_day_decision_time",
            "accepted_risk_pct_by_day_decision_time",
            "accepted_risk_orders_by_day_decision_cluster_side",
            "accepted_risk_pct_by_day_decision_cluster_side",
            "pending_orders",
            "open_positions",
        )
    }
    state_projection = {
        "schema": "gtos.replay_acceleration.pre_day_state.v1",
        "account_root_sha256": stable_sha256(account_payload),
        "broker_root_sha256": stable_sha256(broker.mutation_boundary()),
        "event_queue_root_sha256": stable_sha256(event_queue_payload),
        "reservation_root_sha256": stable_sha256(reservation_payload),
        "selected_order_sequence": selected_order_sequence,
    }
    return {
        "schema": "gtos.replay_acceleration.semantic_state_checkpoint.v1",
        "campaign": campaign,
        "profile": profile,
        "trading_day": trading_day,
        "boundary": boundary,
        "account_preimage": account_payload,
        "state_projection": state_projection,
        "state_root_sha256": stable_sha256(state_projection),
    }


def file_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    if path.suffix == ".gz":
        with gzip.open(path, "rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(chunk)
    else:
        with path.open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(chunk)
    return digest.hexdigest()


def atomic_write_json(path: Path, payload: Mapping[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(f".{os.getpid()}.tmp")
    tmp.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    os.replace(tmp, path)


def atomic_write_jsonl(path: Path, rows: Iterable[Mapping[str, Any]]) -> int:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(f".{os.getpid()}.tmp")
    count = 0
    with tmp.open("w", encoding="utf-8") as handle:
        for row in rows:
            handle.write(json.dumps(dict(row), sort_keys=True, default=str) + "\n")
            count += 1
    os.replace(tmp, path)
    return count


def load_json(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text(encoding="utf-8"))


def load_jsonl(path: Path) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    if not path.exists():
        return rows
    attempts = 3
    for attempt in range(1, attempts + 1):
        rows = []
        try:
            if path.suffix == ".gz":
                handle_cm = gzip.open(path, "rt", encoding="utf-8")
            else:
                handle_cm = path.open("r", encoding="utf-8")
            with handle_cm as handle:
                for line in handle:
                    if line.strip():
                        rows.append(json.loads(line))
            return rows
        except OSError as exc:
            retryable = isinstance(exc, TimeoutError) or exc.errno in {11, 35, 60}
            if not retryable or attempt >= attempts:
                raise
            time.sleep(0.25 * attempt)
    return rows


def load_config(path: Path = Path("config/agent_config.yaml")) -> dict[str, Any]:
    if not path.exists():
        return {}
    try:
        import yaml  # type: ignore
    except Exception:
        return {}
    with path.open("r", encoding="utf-8") as handle:
        payload = yaml.safe_load(handle) or {}
    return payload if isinstance(payload, dict) else {}


def git_value(args: list[str]) -> str | None:
    try:
        result = subprocess.run(
            ["git", *args],
            check=True,
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )
    except Exception:
        return None
    return result.stdout.strip() or None


def parse_row_time(row: Mapping[str, Any]) -> datetime | None:
    for key in CSV_TIME_KEYS:
        if key in row and row.get(key) not in (None, ""):
            return parse_utc(row.get(key))
    return None


def compact_source_records_field(value: Any) -> tuple[float | str | None, dict[str, Any]]:
    if value in (None, ""):
        return None, {}
    if isinstance(value, (list, tuple, set)):
        material = json.dumps(list(value)[:5], sort_keys=True, default=str)
        return float(len(value)), {
            "source_records_compacted": True,
            "source_records_original_type": type(value).__name__,
            "source_records_original_count": len(value),
            "source_records_sample_hash_sha256": hashlib.sha256(
                material.encode("utf-8")
            ).hexdigest(),
        }
    if isinstance(value, Mapping):
        source_keys = sorted(str(key) for key in value.keys())
        return float(len(value)), {
            "source_records_compacted": True,
            "source_records_original_type": "mapping",
            "source_records_original_count": len(value),
            "source_records_sample_hash_sha256": hashlib.sha256(
                "\n".join(source_keys[:100]).encode("utf-8")
            ).hexdigest(),
            "source_records_key_sample": source_keys[:20],
        }
    try:
        return float(value), {}
    except (TypeError, ValueError):
        text = str(value)
    if len(text) > 128 or text[:1] in {"[", "{"}:
        return 0.0, {
            "source_records_compacted": True,
            "source_records_original_type": "text",
            "source_records_original_text_bytes": len(text.encode("utf-8")),
            "source_records_original_hash_sha256": hashlib.sha256(
                text.encode("utf-8")
            ).hexdigest(),
        }
    return text, {}


def normalize_row(row: Mapping[str, Any], *, symbol: str) -> dict[str, Any] | None:
    ts = parse_row_time(row)
    if ts is None:
        return None
    out = {
        "time": iso(ts),
        "time_utc": iso(ts),
        "symbol": symbol,
    }
    for key in ("open", "high", "low", "close", "volume"):
        try:
            out[key] = float(row.get(key, 0.0))
        except (TypeError, ValueError):
            out[key] = 0.0
    for key in ("source_records", "num_trades", "bid_volume", "ask_volume"):
        if key in row:
            if key == "source_records":
                compacted, metadata = compact_source_records_field(row.get(key))
                if compacted is not None:
                    out[key] = compacted
                out.update(metadata)
                continue
            try:
                out[key] = float(row.get(key, 0.0))
            except (TypeError, ValueError):
                out[key] = row.get(key)
    return out


def load_csv_rows(
    path: Path,
    *,
    symbol: str,
    source_batch_lease: VerifiedSourceBatchLease | None = None,
    source_partition: Mapping[str, Any] | None = None,
) -> tuple[dict[str, Any], ...]:
    if source_batch_lease is None:
        if source_partition is not None:
            raise TypeError("source_partition_requires_verified_source_batch_lease")
        if not path.exists():
            return ()
        handle_context = path.open("r", newline="", encoding="utf-8")
    else:
        if type(source_batch_lease) is not VerifiedSourceBatchLease:
            raise TypeError("verified_source_batch_lease_required")
        handle_context = source_batch_lease._open_text(
            source_path=path,
            symbol=symbol,
            partition_identity=source_partition,
        )
    with handle_context as handle:
        rows = [normalize_row(row, symbol=symbol) for row in csv.DictReader(handle)]
    return tuple(row for row in rows if row is not None)


def load_tick_rows(path: Path, *, symbol: str) -> tuple[dict[str, Any], ...]:
    if not path.exists():
        return ()
    rows: list[dict[str, Any]] = []
    if path.suffix == ".gz":
        handle_cm = gzip.open(path, "rt", encoding="utf-8")
    else:
        handle_cm = path.open("r", encoding="utf-8")
    with handle_cm as handle:
        for line in handle:
            if not line.strip():
                continue
            try:
                payload = json.loads(line)
            except json.JSONDecodeError:
                continue
            if not isinstance(payload, dict):
                continue
            ts = parse_row_time(payload)
            if ts is None:
                continue
            payload = dict(payload)
            payload["time"] = iso(ts)
            payload["time_utc"] = iso(ts)
            payload["symbol"] = symbol
            rows.append(payload)
    rows.sort(key=lambda row: str(row.get("time_utc") or row.get("time")))
    return tuple(rows)


def load_tick_rows_between(
    path: Path,
    *,
    symbol: str,
    after: datetime,
    until: datetime,
) -> tuple[dict[str, Any], ...]:
    if not path.exists():
        return ()
    rows: list[dict[str, Any]] = []
    if path.suffix == ".gz":
        handle_cm = gzip.open(path, "rt", encoding="utf-8")
    else:
        handle_cm = path.open("r", encoding="utf-8")
    with handle_cm as handle:
        for line in handle:
            if not line.strip():
                continue
            try:
                payload = json.loads(line)
            except json.JSONDecodeError:
                continue
            if not isinstance(payload, dict):
                continue
            ts = parse_row_time(payload)
            if ts is None:
                continue
            if ts > until:
                break
            if not (after < ts <= until):
                continue
            payload = dict(payload)
            payload["time"] = iso(ts)
            payload["time_utc"] = iso(ts)
            payload["symbol"] = symbol
            rows.append(payload)
    rows.sort(key=lambda row: str(row.get("time_utc") or row.get("time")))
    return tuple(rows)


@dataclass(frozen=True)
class TickFileOffsetIndex:
    path: Path
    times: tuple[datetime, ...]
    offsets: tuple[int, ...]
    stride: int


def build_tick_file_offset_index(path: Path, *, stride: int = 1000) -> TickFileOffsetIndex:
    times: list[datetime] = []
    offsets: list[int] = []
    if not path.exists():
        return TickFileOffsetIndex(path=path, times=(), offsets=(), stride=stride)
    valid_rows = 0
    with path.open("rb") as handle:
        while True:
            offset = handle.tell()
            line = handle.readline()
            if not line:
                break
            if not line.strip():
                continue
            try:
                payload = json.loads(line)
            except json.JSONDecodeError:
                continue
            if not isinstance(payload, dict):
                continue
            ts = parse_row_time(payload)
            if ts is None:
                continue
            if valid_rows % max(1, stride) == 0:
                times.append(ts)
                offsets.append(offset)
            valid_rows += 1
    return TickFileOffsetIndex(path=path, times=tuple(times), offsets=tuple(offsets), stride=stride)


def load_tick_rows_between_indexed(
    path: Path,
    *,
    symbol: str,
    after: datetime,
    until: datetime,
    index: TickFileOffsetIndex,
) -> tuple[dict[str, Any], ...]:
    if not path.exists():
        return ()
    start_offset = 0
    if index.times and index.offsets:
        offset_index = max(0, bisect.bisect_right(index.times, after) - 1)
        start_offset = index.offsets[offset_index]
    rows: list[dict[str, Any]] = []
    with path.open("rb") as handle:
        handle.seek(start_offset)
        for line in handle:
            if not line.strip():
                continue
            try:
                payload = json.loads(line)
            except json.JSONDecodeError:
                continue
            if not isinstance(payload, dict):
                continue
            ts = parse_row_time(payload)
            if ts is None:
                continue
            if ts > until:
                break
            if not (after < ts <= until):
                continue
            payload = dict(payload)
            payload["time"] = iso(ts)
            payload["time_utc"] = iso(ts)
            payload["symbol"] = symbol
            rows.append(payload)
    rows.sort(key=lambda row: str(row.get("time_utc") or row.get("time")))
    return tuple(rows)


def load_source_rows(path: Path, *, symbol: str, timeframe: str) -> tuple[dict[str, Any], ...]:
    if str(timeframe).upper() == "TICK":
        return load_tick_rows(path, symbol=symbol)
    return load_csv_rows(path, symbol=symbol)


def rows_by_day(rows: Iterable[Mapping[str, Any]]) -> dict[str, tuple[dict[str, Any], ...]]:
    grouped: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for row in rows:
        ts = parse_row_time(row)
        if ts is None:
            continue
        grouped[ts.date().isoformat()].append(dict(row))
    event = {
        day: tuple(sorted(items, key=lambda item: str(item.get("time_utc") or item.get("time"))))
        for day, items in grouped.items()
    }
    return event


def source_spec_covers_day(spec: SourceSpec, day: str) -> bool:
    day_start = parse_utc(f"{day}T00:00:00+00:00")
    if day_start is None:
        return False
    day_end = day_start + timedelta(days=1)
    start = parse_utc(spec.start_utc)
    end = parse_utc(spec.end_utc)
    if start is None or end is None:
        return False
    return start <= day_start and end >= day_end


def verified_no_session_day_label(
    sources: Mapping[str, ResolvedSource],
    day: str,
) -> dict[str, Any] | None:
    m1 = sources.get("M1")
    m15 = sources.get("M15")
    if m1 is None or m15 is None:
        return None
    if int(m1.day_counts.get(day, -1)) != 0:
        return None
    if m15.rows_by_day.get(day, ()):
        return None
    for label in m1.component_source_labels:
        if (
            label.get("trading_day") == day
            and label.get("source_session_status") == "ftmo_verified_no_session_day"
        ):
            return dict(label)
    return None


def calendar_no_session_breadth_guard(
    *,
    config: Mapping[str, Any],
    sources: Mapping[str, Mapping[str, ResolvedSource]],
    day: str,
) -> dict[str, Any]:
    runtime = config.get("gtos_vnext_runtime") if isinstance(config, Mapping) else {}
    runtime = runtime if isinstance(runtime, Mapping) else {}
    enabled = bool(
        runtime.get(
            "scheduler_v4_best_trade_allocator_calendar_no_session_breadth_guard_enabled",
            False,
        )
    )
    min_symbols = max(
        1,
        int(
            safe_float(
                runtime.get(
                    "scheduler_v4_best_trade_allocator_calendar_no_session_breadth_guard_min_symbols",
                    1,
                ),
                1,
            )
        ),
    )
    labels = [
        {
            "symbol": symbol,
            **label,
        }
        for symbol, symbol_sources in sorted(sources.items())
        if (label := verified_no_session_day_label(symbol_sources, day)) is not None
    ]
    active = enabled and len(labels) >= min_symbols
    return {
        "enabled": enabled,
        "active": active,
        "trading_day": day,
        "min_symbols": min_symbols,
        "no_session_symbol_count": len(labels),
        "no_session_symbols": [str(label.get("symbol")) for label in labels],
        "no_session_labels": labels,
        "reason": (
            "calendar_no_session_breadth_guard_active"
            if active
            else "calendar_no_session_breadth_guard_inactive"
        ),
        "source_boundary": SOURCE_BOUND_EVIDENCE_CLASS,
    }


def rows_for_day(rows: Iterable[Mapping[str, Any]], day: str) -> tuple[dict[str, Any], ...]:
    return rows_by_day(rows).get(day, ())


def rows_until(rows: Iterable[Mapping[str, Any]], asof: datetime) -> tuple[dict[str, Any], ...]:
    selected: list[dict[str, Any]] = []
    for row in rows:
        ts = parse_row_time(row)
        if ts is not None and ts <= asof:
            selected.append(dict(row))
    selected.sort(key=lambda item: str(item.get("time_utc") or item.get("time")))
    return tuple(selected)


def closed_bar_rows_until(
    rows: Iterable[Mapping[str, Any]],
    *,
    timeframe: str,
    asof: datetime,
    max_rows: int | None = None,
) -> tuple[dict[str, Any], ...]:
    rows_tuple = rows if isinstance(rows, tuple) else tuple(rows)
    if not rows_tuple:
        return ()
    tf_name = str(timeframe).upper()
    minutes = TIMEFRAME_MINUTES.get(tf_name, 0)
    close_delta = timedelta(minutes=minutes)
    cache_key = (id(rows_tuple), len(rows_tuple), minutes)
    cacheable = isinstance(rows, tuple)
    cached = _CLOSED_BAR_INDEX_CACHE.get(cache_key) if cacheable else None
    if cached is None or cached[0] is not rows_tuple:
        pairs: list[tuple[datetime, dict[str, Any]]] = []
        for row in rows_tuple:
            ts = parse_row_time(row)
            if ts is not None:
                pairs.append((ts + close_delta, dict(row)))
        pairs.sort(key=lambda item: item[0])
        cached = (
            rows_tuple,
            tuple(close_ts for close_ts, _ in pairs),
            tuple(row for _, row in pairs),
        )
        if cacheable:
            _CLOSED_BAR_INDEX_CACHE[cache_key] = cached
    _source_rows, close_times, sorted_rows = cached
    cutoff = asof + timedelta(seconds=2)
    end_idx = bisect.bisect_right(close_times, cutoff)
    if max_rows is not None and max_rows > 0:
        start_idx = max(0, end_idx - int(max_rows))
        return sorted_rows[start_idx:end_idx]
    return sorted_rows[:end_idx]


def rows_after_until(
    rows: Iterable[Mapping[str, Any]],
    *,
    after: datetime,
    until: datetime,
) -> tuple[dict[str, Any], ...]:
    selected: list[dict[str, Any]] = []
    for row in rows:
        ts = parse_row_time(row)
        if ts is not None and after < ts <= until:
            selected.append(dict(row))
    selected.sort(key=lambda item: str(item.get("time_utc") or item.get("time")))
    return tuple(selected)


_CLOSED_BAR_INDEX_CACHE: dict[
    tuple[int, int, int],
    tuple[
        tuple[Mapping[str, Any], ...],
        tuple[datetime, ...],
        tuple[dict[str, Any], ...],
    ],
] = {}
_ROW_TIME_INDEX_CACHE: dict[
    tuple[int, int],
    tuple[tuple[dict[str, Any], ...], tuple[datetime, ...], tuple[dict[str, Any], ...]],
] = {}


def clear_replay_row_index_caches() -> None:
    _CLOSED_BAR_INDEX_CACHE.clear()
    _ROW_TIME_INDEX_CACHE.clear()


def replay_source_cache_counts() -> dict[str, int]:
    tick_query_cache = globals().get("_PREDECISION_TICK_QUERY_CACHE")
    return {
        "closed_bar_index": len(_CLOSED_BAR_INDEX_CACHE),
        "row_time_index": len(_ROW_TIME_INDEX_CACHE),
        "predecision_tick_query": (
            len(tick_query_cache) if isinstance(tick_query_cache, dict) else 0
        ),
    }


def clear_replay_source_caches() -> None:
    clear_replay_row_index_caches()
    tick_query_cache = globals().get("_PREDECISION_TICK_QUERY_CACHE")
    if isinstance(tick_query_cache, dict):
        tick_query_cache.clear()


def rows_after_until_indexed(
    rows: tuple[dict[str, Any], ...],
    *,
    after: datetime,
    until: datetime,
) -> tuple[dict[str, Any], ...]:
    if not rows:
        return ()
    cache_key = (id(rows), len(rows))
    cached = _ROW_TIME_INDEX_CACHE.get(cache_key)
    if cached is None or cached[0] is not rows:
        pairs: list[tuple[datetime, dict[str, Any]]] = []
        for row in rows:
            ts = parse_row_time(row)
            if ts is not None:
                pairs.append((ts, dict(row)))
        pairs.sort(key=lambda item: item[0])
        cached = (
            rows,
            tuple(ts for ts, _ in pairs),
            tuple(row for _, row in pairs),
        )
        _ROW_TIME_INDEX_CACHE[cache_key] = cached
    _source_rows, times, sorted_rows = cached
    start_idx = bisect.bisect_right(times, after)
    end_idx = bisect.bisect_right(times, until)
    return sorted_rows[start_idx:end_idx]


def rows_after_until_by_day(
    rows_by_day_input: Mapping[str, Iterable[Mapping[str, Any]]],
    *,
    after: datetime,
    until: datetime,
) -> tuple[dict[str, Any], ...]:
    selected: list[dict[str, Any]] = []
    cursor = after.date()
    end_day = until.date()
    while cursor <= end_day:
        day_rows = rows_by_day_input.get(cursor.isoformat(), ())
        if isinstance(day_rows, tuple):
            selected.extend(rows_after_until_indexed(day_rows, after=after, until=until))
            cursor = cursor + timedelta(days=1)
            continue
        selected.extend(
            rows_after_until(
                day_rows,
                after=after,
                until=until,
            )
        )
        cursor = cursor + timedelta(days=1)
    selected.sort(key=lambda item: str(item.get("time_utc") or item.get("time")))
    return tuple(selected)


@dataclass(frozen=True)
class PathTruthQuery:
    rows: tuple[dict[str, Any], ...]
    metadata: dict[str, Any]


class LazyTickRowsByDay:
    """Window-scoped tick lookup that avoids loading all tick exports at once."""

    lookup_mode = "lazy_tick_window_stream"

    def __init__(self, *, symbol: str, specs: Iterable[SourceSpec]):
        self.symbol = symbol
        self.specs = tuple(specs)
        self.max_cached_rows = int(os.environ.get("GTOS_LAZY_TICK_CACHE_MAX_ROWS", "100000"))
        self.max_cached_file_rows = int(os.environ.get("GTOS_LAZY_TICK_CACHE_MAX_FILE_ROWS", "0"))
        self.offset_index_stride = int(os.environ.get("GTOS_LAZY_TICK_OFFSET_INDEX_STRIDE", "1000"))
        self._cache: OrderedDict[Path, tuple[dict[str, Any], ...]] = OrderedDict()
        self._offset_indexes: OrderedDict[Path, TickFileOffsetIndex] = OrderedDict()
        self._cached_rows = 0
        self.last_validation_events: tuple[dict[str, Any], ...] = ()

    def _overlaps(self, spec: SourceSpec, *, after: datetime, until: datetime) -> bool:
        start = parse_utc(spec.start_utc)
        end = parse_utc(spec.end_utc)
        if start is None or end is None:
            return True
        return start <= until and end > after

    def _validate_spec_hash(self, spec: SourceSpec) -> tuple[bool, dict[str, Any]]:
        event: dict[str, Any] = {
            "path": str(spec.path),
            "manifest_sha256": spec.sha256,
            "sha_validation_status": "not_checked",
        }
        try:
            actual_sha = file_sha256_cached(spec.path)
        except OSError as exc:
            event["sha_validation_status"] = "validation_failed"
            event["sha_validation_error"] = str(exc)
            return False, event
        event["actual_sha256"] = actual_sha
        if spec.sha256 and actual_sha != spec.sha256:
            event["sha_validation_status"] = "sha256_mismatch"
            return False, event
        event["sha_validation_status"] = "validated_file_hash_match"
        return True, event

    def _rows_for_spec(self, spec: SourceSpec) -> tuple[dict[str, Any], ...]:
        path = spec.path
        cached = self._cache.pop(path, None)
        if cached is not None:
            self._cache[path] = cached
            return cached
        rows = load_tick_rows(path, symbol=self.symbol)
        self._cache[path] = rows
        self._cached_rows += len(rows)
        while len(self._cache) > 1 and self._cached_rows > self.max_cached_rows:
            _old_path, old_rows = self._cache.popitem(last=False)
            self._cached_rows -= len(old_rows)
        return rows

    def _filter_cached_rows(
        self,
        rows: Iterable[Mapping[str, Any]],
        *,
        after: datetime,
        until: datetime,
    ) -> tuple[dict[str, Any], ...]:
        selected: list[dict[str, Any]] = []
        for row in rows:
            ts = parse_row_time(row)
            if ts is not None and after < ts <= until:
                selected.append(dict(row))
        selected.sort(
            key=lambda row: str(
                row.get("time_utc") or row.get("ts_utc") or row.get("time")
            )
        )
        return tuple(selected)

    def _offset_index_for_spec(self, spec: SourceSpec) -> TickFileOffsetIndex:
        path = spec.path
        cached = self._offset_indexes.pop(path, None)
        if cached is not None:
            self._offset_indexes[path] = cached
            return cached
        index = build_tick_file_offset_index(path, stride=self.offset_index_stride)
        self._offset_indexes[path] = index
        return index

    def query(self, *, after: datetime, until: datetime) -> tuple[tuple[dict[str, Any], ...], list[str]]:
        rows: list[dict[str, Any]] = []
        days: set[str] = set()
        seen: set[tuple[Any, Any, Any, Any, Any]] = set()
        validation_events: list[dict[str, Any]] = []
        for spec in self.specs:
            if not self._overlaps(spec, after=after, until=until):
                continue
            valid_hash, validation_event = self._validate_spec_hash(spec)
            validation_events.append(validation_event)
            if not valid_hash:
                continue
            spec_rows = int(spec.row_count or 0)
            if spec_rows > self.max_cached_file_rows and spec.path.suffix != ".gz":
                window_rows = load_tick_rows_between_indexed(
                    spec.path,
                    symbol=self.symbol,
                    after=after,
                    until=until,
                    index=self._offset_index_for_spec(spec),
                )
            elif spec_rows > self.max_cached_file_rows:
                window_rows = load_tick_rows_between(
                    spec.path,
                    symbol=self.symbol,
                    after=after,
                    until=until,
                )
            else:
                window_rows = self._filter_cached_rows(
                    self._rows_for_spec(spec),
                    after=after,
                    until=until,
                )
            for row in window_rows:
                key = (
                    row.get("time_utc") or row.get("time"),
                    row.get("bid"),
                    row.get("ask"),
                    row.get("last"),
                    row.get("volume"),
                )
                if key in seen:
                    continue
                seen.add(key)
                ts = parse_row_time(row)
                if ts is not None:
                    days.add(ts.date().isoformat())
                rows.append(row)
        rows.sort(
            key=lambda row: str(
                row.get("time_utc") or row.get("ts_utc") or row.get("time")
            )
        )
        self.last_validation_events = tuple(validation_events)
        return tuple(rows), sorted(days)

    def get(self, day: str, default: Any = None) -> Any:
        try:
            start = datetime.fromisoformat(day).replace(tzinfo=timezone.utc)
        except ValueError:
            return default
        rows, _days = self.query(after=start - timedelta(microseconds=1), until=start + timedelta(days=1))
        return rows or default


class PathTruthIndex:
    """Indexed postdecision path lookup for M1/tick replay labels."""

    lookup_mode = "day_time_bisect_index"

    def __init__(self, source: ResolvedSource):
        self.source = source

    def query(self, *, after: datetime, until: datetime) -> PathTruthQuery:
        if hasattr(self.source.rows_by_day, "query"):
            rows, days = self.source.rows_by_day.query(after=after, until=until)  # type: ignore[attr-defined]
            lookup_mode = getattr(self.source.rows_by_day, "lookup_mode", self.lookup_mode)
        else:
            rows = rows_after_until_by_day(
                self.source.rows_by_day,
                after=after,
                until=until,
            )
            days = []
            cursor = after.date()
            end_day = until.date()
            while cursor <= end_day:
                day = cursor.isoformat()
                if self.source.rows_by_day.get(day):
                    days.append(day)
                cursor = cursor + timedelta(days=1)
            lookup_mode = self.lookup_mode
        requested_days: list[str] = []
        cursor = (after + timedelta(microseconds=1)).date()
        end_day = until.date()
        while cursor <= end_day:
            requested_days.append(cursor.isoformat())
            cursor = cursor + timedelta(days=1)
        day_authorities = {
            day: resolved_source_day_authority(self.source, day)
            for day in requested_days
        }
        query_source_gaps = list(
            dict.fromkeys(
                str(gap)
                for authority in day_authorities.values()
                for gap in authority.get("source_gaps") or ()
                if str(gap or "").strip()
            )
        )
        return PathTruthQuery(
            rows=rows,
            metadata={
                "path_index_lookup_mode": lookup_mode,
                "path_index_timeframe": self.source.spec.timeframe,
                "path_index_source_path": str(self.source.spec.path),
                "path_index_source_sha256": self.source.sha256,
                "path_index_rows_returned": len(rows),
                "path_index_requested_days": requested_days,
                "path_index_days_touched": days,
                "path_index_days_missing": sorted(
                    set(requested_days) - set(days)
                ),
                "path_index_day_source_authority": day_authorities,
                "path_index_query_source_gaps": query_source_gaps,
                "path_index_query_diagnostic_fallback_only": any(
                    authority.get("diagnostic_fallback_only") is True
                    for authority in day_authorities.values()
                ),
                "path_index_ordered_tick_truth": (
                    self.source.spec.ordered_tick_truth_satisfied is True
                ),
                "lazy_tick_source_validation_events": list(
                    getattr(self.source.rows_by_day, "last_validation_events", ())
                ),
            },
        )


PathTruthQueryCacheKey = tuple[int, str, str]
PathTruthQueryCacheValue = tuple[ResolvedSource, PathTruthQuery]


def cached_path_truth_query(
    source: ResolvedSource,
    *,
    after: datetime,
    until: datetime,
    query_cache: MutableMapping[
        PathTruthQueryCacheKey,
        PathTruthQueryCacheValue,
    ]
    | None,
) -> PathTruthQuery:
    """Reuse one immutable source window across candidate geometries."""

    if query_cache is None:
        return PathTruthIndex(source).query(after=after, until=until)
    key = (
        id(source),
        iso(after) or "",
        iso(until) or "",
    )
    cached = query_cache.get(key)
    if cached is None:
        query = PathTruthIndex(source).query(after=after, until=until)
        query_cache[key] = (source, query)
        return query
    cached_source, query = cached
    if cached_source is not source:
        raise RuntimeError("path_truth_query_cache_source_identity_collision")
    return query


def export_roots(repo_root: Path | str = Path(".")) -> tuple[Path, ...]:
    root = Path(repo_root)
    candidates = [
        root / "data/mt5_research_exports",
        root / ROUTE_DIR / "ftmo_research_exports",
    ]
    env_value = os.environ.get("GTOS_FTMO_MT5_EXPORT_ROOT")
    if env_value:
        candidates.insert(0, Path(env_value))
    return tuple(dict.fromkeys(candidates))


def redact_identifier(value: Any) -> str | None:
    text = str(value or "").strip()
    if not text:
        return None
    if len(text) <= 4:
        return "redacted"
    return f"redacted:{text[:2]}...{text[-2:]}"


def hash_identifier(value: Any) -> str | None:
    text = str(value or "").strip()
    if not text:
        return None
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def first_present(*values: Any) -> Any:
    for value in values:
        if value not in (None, "", [], {}):
            return value
    return None


def lifecycle_root_allowed_value(root_authority: Mapping[str, Any] | None) -> Any:
    """Flatten lifecycle-root authority without treating non-applicable roots as blocked."""

    root_authority = root_authority if isinstance(root_authority, Mapping) else {}
    failures = root_authority.get("failures")
    if failures in (None, "", [], {}):
        failure_items: tuple[Any, ...] = ()
    elif isinstance(failures, str):
        failure_items = tuple(item for item in failures.split(",") if item.strip())
    elif isinstance(failures, (list, tuple, set)):
        failure_items = tuple(failures)
    else:
        failure_items = (failures,)
    if root_authority.get("applies") is False and not failure_items:
        return True
    return first_present(
        root_authority.get("allowed"),
        root_authority.get("package_lifecycle_root_authority_allowed"),
    )


def package_marketable_entry_guard_attribution_fields(
    *surfaces: Mapping[str, Any] | None,
    prefix: str = "",
) -> dict[str, Any]:
    """Lift marketable-limit guard evidence from scheduler/finalizer surfaces."""

    surface_chain: list[Mapping[str, Any]] = []
    for surface in surfaces:
        if not isinstance(surface, Mapping):
            continue
        surface_chain.append(surface)
        components = surface.get("score_components")
        if isinstance(components, Mapping):
            surface_chain.append(components)
            decision_inputs = components.get("candidate_decision_inputs")
            if isinstance(decision_inputs, Mapping):
                surface_chain.append(decision_inputs)
        guard = first_present(
            surface.get("package_marketable_entry_guard"),
            surface.get("risk_finalizer_package_marketable_entry_guard"),
            surface.get("finalizer_primary_probe_package_marketable_entry_guard"),
        )
        if isinstance(guard, Mapping):
            surface_chain.append(guard)
            replay_route = first_present(
                guard.get("replay_route"),
                guard.get("package_marketable_entry_guard_replay_route"),
            )
            if isinstance(replay_route, Mapping):
                surface_chain.append(replay_route)
        replay_route = first_present(
            surface.get("package_marketable_entry_guard_replay_route"),
            surface.get("package_marketable_entry_guard_route"),
            surface.get("risk_finalizer_package_marketable_entry_guard_replay_route"),
            surface.get("finalizer_primary_probe_package_marketable_entry_guard_replay_route"),
        )
        if isinstance(replay_route, Mapping):
            surface_chain.append(replay_route)

    def _first_key(*keys: str) -> Any:
        for surface in surface_chain:
            for key in keys:
                value = surface.get(key)
                if value not in (None, "", [], {}):
                    return value
        return None

    def _list_value(value: Any) -> list[Any]:
        if value in (None, "", [], {}):
            return []
        if isinstance(value, Sequence) and not isinstance(
            value, (str, bytes, bytearray)
        ):
            return list(value)
        return [value]

    guard = _first_key(
        "package_marketable_entry_guard",
        "risk_finalizer_package_marketable_entry_guard",
        "finalizer_primary_probe_package_marketable_entry_guard",
    )
    guard = guard if isinstance(guard, Mapping) else guard
    guard_map = guard if isinstance(guard, Mapping) else {}
    replay_route = first_present(
        _first_key(
            "package_marketable_entry_guard_replay_route",
            "package_marketable_entry_guard_route",
            "risk_finalizer_package_marketable_entry_guard_replay_route",
            "finalizer_primary_probe_package_marketable_entry_guard_replay_route",
        ),
        guard_map.get("replay_route"),
        guard_map.get("package_marketable_entry_guard_replay_route"),
    )
    replay_route_map = replay_route if isinstance(replay_route, Mapping) else {}
    route_failures = _list_value(
        first_present(
            _first_key(
                "package_marketable_entry_guard_route_failures",
                "risk_finalizer_package_marketable_entry_guard_route_failures",
                "finalizer_primary_probe_package_marketable_entry_guard_route_failures",
            ),
            replay_route_map.get("route_failures"),
            replay_route_map.get("failures"),
            guard_map.get("route_failures"),
            guard_map.get("failures"),
        )
    )
    return {
        f"{prefix}predecision_limit_fillability": _first_key(
            "predecision_limit_fillability",
            "risk_finalizer_predecision_limit_fillability",
            "finalizer_primary_probe_predecision_limit_fillability",
        ),
        f"{prefix}limit_marketable_at_decision": _first_key(
            "limit_marketable_at_decision",
            "risk_finalizer_limit_marketable_at_decision",
            "finalizer_primary_probe_limit_marketable_at_decision",
        ),
        f"{prefix}package_marketable_entry_guard": (
            dict(guard) if isinstance(guard, Mapping) else guard
        ),
        f"{prefix}package_marketable_entry_guard_status": _first_key(
            "package_marketable_entry_guard_status",
            "risk_finalizer_package_marketable_entry_guard_status",
            "finalizer_primary_probe_package_marketable_entry_guard_status",
        )
        or guard_map.get("status"),
        f"{prefix}package_marketable_entry_guard_reason": first_present(
            _first_key(
                "package_marketable_entry_guard_reason",
                "risk_finalizer_package_marketable_entry_guard_reason",
                "finalizer_primary_probe_package_marketable_entry_guard_reason",
            ),
            guard_map.get("reason"),
        ),
        f"{prefix}package_marketable_entry_guard_original_reason": first_present(
            _first_key(
                "package_marketable_entry_guard_original_reason",
                "risk_finalizer_package_marketable_entry_guard_original_reason",
                "finalizer_primary_probe_package_marketable_entry_guard_original_reason",
            ),
            guard_map.get("original_reason"),
        ),
        f"{prefix}package_marketable_entry_guard_replay_route_allowed": first_present(
            _first_key(
                "package_marketable_entry_guard_replay_route_allowed",
                "risk_finalizer_package_marketable_entry_guard_replay_route_allowed",
                "finalizer_primary_probe_package_marketable_entry_guard_replay_route_allowed",
            ),
            guard_map.get("replay_route_allowed"),
            replay_route_map.get("replay_route_allowed"),
        ),
        f"{prefix}package_marketable_entry_guard_immediate_marketable_limit_route_allowed": first_present(
            _first_key(
                "package_marketable_entry_guard_immediate_marketable_limit_route_allowed",
                "risk_finalizer_package_marketable_entry_guard_immediate_marketable_limit_route_allowed",
                "finalizer_primary_probe_package_marketable_entry_guard_immediate_marketable_limit_route_allowed",
            ),
            guard_map.get("immediate_marketable_limit_route_allowed"),
            replay_route_map.get("immediate_marketable_limit_route_allowed"),
        ),
        f"{prefix}package_marketable_entry_guard_route_allowed": first_present(
            _first_key(
                "package_marketable_entry_guard_route_allowed",
                "risk_finalizer_package_marketable_entry_guard_route_allowed",
                "finalizer_primary_probe_package_marketable_entry_guard_route_allowed",
            ),
            guard_map.get("route_allowed"),
            replay_route_map.get("route_allowed"),
            replay_route_map.get("allowed"),
        ),
        f"{prefix}package_marketable_entry_guard_route_failures": route_failures,
        f"{prefix}package_marketable_entry_guard_replay_route": (
            dict(replay_route) if isinstance(replay_route, Mapping) else replay_route
        ),
    }


