INVALID_STABLE_MEMBER_AXIS_IDS = frozenset(
    {
        "none",
        "null",
        "unknown",
        "missing",
        "unset",
        "unavailable",
        "n/a",
        "na",
    }
)


def _stable_member_axis_id(value: Any) -> bool:
    if not isinstance(value, str):
        return False
    text = value.strip()
    return bool(
        text
        and text == value
        and len(text) <= 512
        and text.lower() not in INVALID_STABLE_MEMBER_AXIS_IDS
        and text.isprintable()
        and not any(character.isspace() for character in text)
        and any(character.isalnum() for character in text)
    )


def _stable_member_axis_id_collection(value: Any) -> bool:
    if isinstance(value, str):
        return _stable_member_axis_id(value)
    if isinstance(value, (bytes, bytearray, Mapping)):
        return False
    if isinstance(value, Sequence):
        return any(_stable_member_axis_id(item) for item in value)
    return False


def package_member_axis_source_bound_identity_present(
    *surfaces: Mapping[str, Any] | None,
) -> bool:
    pending: list[Mapping[str, Any]] = [
        surface for surface in surfaces if isinstance(surface, Mapping)
    ]
    seen: set[int] = set()
    while pending:
        surface = pending.pop(0)
        marker = id(surface)
        if marker in seen:
            continue
        seen.add(marker)
        for field in PACKAGE_MEMBER_AXIS_ID_ALIASES:
            if _stable_member_axis_id_collection(surface.get(field)):
                return True
        for nested_key in (
            "source_bound_fields",
            "candidate_decision_inputs",
            "scheduler_candidate_decision_inputs",
            "decision_inputs",
            "score_components",
            "scheduler_score_components",
        ):
            nested = surface.get(nested_key)
            if isinstance(nested, Mapping):
                pending.append(nested)
    return False


def selected_package_bridge_signed_source_bound_authority_allowed(
    surface: Mapping[str, Any],
) -> bool:
    """Treat selected-bridge source-bound aliases as executable only when signed.

    The bridge alias is still useful provenance, but it is not a standalone
    execution contract. V142 showed stale packet/candidate namespaces carrying
    this alias with missing signed instance identity; keep those rows diagnostic
    until the exact signed bridge materialization proof is present.
    """

    if not isinstance(surface, Mapping):
        return False
    if not _runtime_bool(
        surface.get("selected_package_bridge_source_bound_candidate_use_allowed"),
        False,
    ):
        return False
    open_authority = surface.get("ultimate_candidate_package_open_reduced_risk_authority")
    open_authority = open_authority if isinstance(open_authority, Mapping) else {}
    attribution = package_new_entry_authority_attribution_fields(
        open_authority,
        surface,
    )
    payload = attribution.get("package_new_entry_authority_payload")
    if (
        attribution.get("package_new_entry_authority_valid") is not True
        or not isinstance(payload, Mapping)
    ):
        return False
    if payload.get("authority_family") != "selected_package_bridge_replay_materialization":
        return False
    candidate_id = str(payload.get("candidate_id") or "").strip()
    decision_time = str(payload.get("decision_time_utc") or "").strip()
    expected_instance_key = (
        f"{candidate_id}@@{decision_time}" if candidate_id and decision_time else ""
    )
    return bool(
        expected_instance_key
        and payload.get("canonical_replay_candidate_instance_key")
        == expected_instance_key
        and payload.get("source_bound_replay_candidate_instance_key")
        == expected_instance_key
        and payload.get("candidate_instance_identity_status") == "materialized"
        and payload.get("source_bound_package_candidate_use_allowed") is True
    )


def package_authority_validation_surfaces(
    *surfaces: Mapping[str, Any] | None,
) -> list[Mapping[str, Any]]:
    """Return direct and nested package authority surfaces without duplication."""

    authority_surfaces: list[Mapping[str, Any]] = []
    seen: set[int] = set()

    def add(surface: Mapping[str, Any] | None) -> None:
        if not isinstance(surface, Mapping):
            return
        surface_id = id(surface)
        if surface_id in seen:
            return
        seen.add(surface_id)
        authority_surfaces.append(surface)
        for field in (
            "scheduler_candidate_decision_inputs",
            "candidate_decision_inputs",
            "decision_inputs",
            "ultimate_candidate_package_open_reduced_risk_authority",
            "ultimate_candidate_package_reduce_risk_authority",
            "ultimate_candidate_package_reduced_risk_authority",
            "selector_reduced_risk_new_position_signed_authority",
        ):
            nested = surface.get(field)
            if isinstance(nested, Mapping):
                add(nested)
        score_components = surface.get("score_components")
        if isinstance(score_components, Mapping):
            add(score_components)
            component_inputs = score_components.get("candidate_decision_inputs")
            if isinstance(component_inputs, Mapping):
                add(component_inputs)

    for surface in surfaces:
        add(surface)
    return authority_surfaces


def source_bound_router_refusal_signed_namespace_authority_valid(
    *surfaces: Mapping[str, Any] | None,
) -> bool:
    """Return whether a source-bound router-refusal replay row is signed.

    Source-bound router-refusal materialization may remain scoreable diagnostic
    evidence, but executable namespace aliases need an exact signed new-entry
    contract. This mirrors the route verifier contract so candidate/missed packet
    surfaces cannot advertise executable authority from stale bool aliases.
    """

    return any(
        bool(
            package_source_bound_identity_proof_detail(surface).get(
                "signed_same_instance_valid"
            )
        )
        for surface in surfaces
        if isinstance(surface, Mapping)
    )


def source_bound_router_refusal_unsigned_namespace_block_reason(
    *surfaces: Mapping[str, Any] | None,
    selector_reason: Any = None,
) -> str | None:
    """Block executable aliases for unsigned source-bound router-refusal rows."""

    reasons = {
        str(selector_reason or "").strip(),
    }
    families: set[str] = set()
    for surface in package_authority_validation_surfaces(*surfaces):
        for field in (
            "selector_reason",
            "effective_selector_reason",
            "scheduler_materialization_selector_reason",
            "package_new_entry_authority_selector_reason",
            "replay_candidate_use_allowed_now_reason",
            "package_replay_executable_candidate_use_allowed_reason",
            "package_replay_order_executable_candidate_use_allowed_reason",
        ):
            reasons.add(str(surface.get(field) or "").strip())
        for field in (
            "package_open_reduced_authority_family",
            "open_reduced_soft_authority_family",
            "package_new_entry_authority_authority_family",
            "authority_family",
        ):
            families.add(str(surface.get(field) or "").strip())
        for field in (
            "ultimate_candidate_package_open_reduced_risk_authority",
            "ultimate_candidate_package_reduce_risk_authority",
            "ultimate_candidate_package_reduced_risk_authority",
            "selector_reduced_risk_new_position_signed_authority",
        ):
            nested = surface.get(field)
            if not isinstance(nested, Mapping):
                continue
            for nested_field in (
                "selector_reason",
                "original_selector_reason",
                "package_new_entry_authority_selector_reason",
            ):
                reasons.add(str(nested.get(nested_field) or "").strip())
            families.add(str(nested.get("authority_family") or "").strip())
    reasons.discard("")
    families.discard("")
    source_bound_router_refusal = bool(
        SOURCE_BOUND_ROUTER_REFUSAL_OPEN_REDUCED_REASON in reasons
        or any(
            SOURCE_BOUND_ROUTER_REFUSAL_OPEN_REDUCED_REASON in reason
            for reason in reasons
        )
    )
    if not source_bound_router_refusal:
        return None
    if source_bound_router_refusal_signed_namespace_authority_valid(*surfaces):
        return None
    return "source_bound_router_refusal_requires_signed_new_entry_authority"


def package_source_bound_or_admission_alias_allowed(
    *surfaces: Mapping[str, Any] | None,
) -> bool:
    for surface in surfaces:
        if not isinstance(surface, Mapping):
            continue
        if _owner_approved_family_root_admission_detail(surface).get("allowed") is True:
            return True
    for surface in surfaces:
        if not isinstance(surface, Mapping):
            continue
        proof = package_source_bound_identity_proof_detail(surface)
        if proof.get("signed_same_instance_valid"):
            return True
        if proof.get("boolean_alias_present") and (
            (
                proof.get("exact_member_axis_present")
                and package_member_axis_source_bound_identity_present(surface)
            )
            or proof.get("exact_signing_bootstrap_allowed")
        ):
            return True
    for surface in surfaces:
        if not isinstance(surface, Mapping):
            continue
        if selected_package_bridge_signed_source_bound_authority_allowed(surface):
            return True
    return False


def signed_new_entry_source_bound_alias_repair_allowed(
    validation: Mapping[str, Any] | None,
    *surfaces: Mapping[str, Any] | None,
) -> bool:
    """Repair stale signed-authority packets when current row aliases prove source-bound use."""

    validation = validation if isinstance(validation, Mapping) else {}
    failures = tuple(
        str(failure or "").strip()
        for failure in (validation.get("failures") or ())
        if str(failure or "").strip()
    )
    return bool(
        failures == ("source_bound_package_candidate_use_not_allowed",)
        and package_source_bound_or_admission_alias_allowed(*surfaces)
    )


SIGNED_NEW_ENTRY_STALE_PROJECTION_REPAIRABLE_FAILURES = frozenset(
    {
        "source_bound_package_candidate_use_not_allowed",
        "broker_cost_packet_not_passed",
        "broker_calibrated_cost_authority_missing",
        "source_bound_cost_authority_missing",
        "fill_probability_missing",
        "expected_net_r_source_missing",
        "probability_source_missing",
        "fill_probability_source_missing",
        "source_completeness_source_missing",
        "candidate_decision_quality_source_boundary_missing",
        "router_refusal_execution_fillability_missing",
        "router_refusal_expected_net_r_below_floor",
        "router_refusal_probability_below_floor",
        "router_refusal_fill_probability_below_floor",
        "router_refusal_source_completeness_below_floor",
    }
)


def signed_new_entry_stale_projection_repair_allowed(
    validation: Mapping[str, Any] | None,
    *surfaces: Mapping[str, Any] | None,
    selector_reason: Any = None,
) -> bool:
    """Permit restamping stale projection packets from current predecision truth.

    This is intentionally narrower than source-bound alias repair. It only
    handles signed authority packets stamped before later consumers materialized
    broker-cost, fillability, and quality provenance. Terminal failures still
    fail closed.
    """

    validation = validation if isinstance(validation, Mapping) else {}
    failures = tuple(
        str(failure or "").strip()
        for failure in (validation.get("failures") or ())
        if str(failure or "").strip()
    )
    if not failures:
        return False
    if any(
        failure not in SIGNED_NEW_ENTRY_STALE_PROJECTION_REPAIRABLE_FAILURES
        for failure in failures
    ):
        return False
    current_row: dict[str, Any] = {}
    for surface in surfaces:
        if isinstance(surface, Mapping):
            current_row.update(dict(surface))
    if not package_source_bound_or_admission_alias_allowed(*surfaces, current_row):
        return False
    pretrade_packet = normalized_pretrade_cost_packet_from_packets(current_row)
    if not pretrade_cost_packet_current_executable(pretrade_packet):
        return False
    quality_fields = candidate_decision_quality_fields(current_row, current_row)
    field_sources = quality_fields.get("candidate_decision_quality_field_sources")
    field_sources = field_sources if isinstance(field_sources, Mapping) else {}
    for field in (
        "expected_net_r",
        "probability",
        "fill_probability",
        "source_completeness",
    ):
        source_text = str(field_sources.get(field) or "").lower()
        if not source_text:
            return False
        if any(
            marker in source_text
            for marker in ("inferred", "heuristic", "fallback", "default")
        ):
            return False
    boundary = str(
        quality_fields.get("candidate_decision_quality_source_boundary") or ""
    ).lower().replace("-", "_").replace(" ", "_")
    if "predecision" not in boundary or "no_outcome" not in boundary:
        return False
    for key in (
        "expected_net_r",
        "probability",
        "fill_probability",
        "source_completeness",
    ):
        value = safe_float(quality_fields.get(key), math.nan)
        if not math.isfinite(value):
            return False
    router_failures = _signed_router_refusal_surface_floor_failures(
        {**current_row, **quality_fields},
        selector_reason,
    )
    return not router_failures


def source_bound_alias_repaired_signed_validation(
    validation: Mapping[str, Any],
) -> dict[str, Any]:
    repaired = dict(validation)
    repaired["valid"] = True
    repaired["status"] = "valid_signed_predecision_new_entry_authority"
    repaired["failures"] = ()
    repaired["source_bound_candidate_use_allowed_rederived_from_alias"] = True
    repaired["source_bound_candidate_use_allowed_rederived_reason"] = (
        "current_row_package_source_bound_alias_allowed"
    )
    return repaired


def stale_projection_repaired_signed_validation(
    validation: Mapping[str, Any],
) -> dict[str, Any]:
    repaired = source_bound_alias_repaired_signed_validation(validation)
    repaired["stale_projection_repaired_from_current_predecision_truth"] = True
    repaired["stale_projection_repair_reason"] = (
        "current_row_predecision_quality_cost_fillability_sources_valid"
    )
    return repaired


PACKAGE_REPLAY_AUTHORITY_SCOPE_BOOLEAN_FIELDS = (
    "package_replay_candidate_use_allowed",
    "source_bound_package_candidate_use_allowed",
    "ultimate_package_source_bound_candidate_use_allowed",
    "package_replay_source_bound_candidate_use_allowed",
    "ultimate_package_effective_source_bound_candidate_use_allowed",
    "ultimate_package_admission_candidate_use_allowed",
    "package_source_bound_admission_diagnostic",
    "source_bound_r_additive_allowed",
    "ultimate_package_open_reduced_authority_allowed",
    "ultimate_package_reduce_risk_authority_allowed",
    "package_new_entry_authority_valid",
)


PACKAGE_REPLAY_AUTHORITY_SCOPE_COUNT_FIELDS = (
    "ultimate_package_admission_sleeve_match_count",
    "ultimate_package_effective_admission_count",
    "admission_sleeve_match_count",
)


PACKAGE_REPLAY_AUTHORITY_SCOPE_NONEMPTY_FIELDS = (
    "ultimate_package_matched_sleeve_ids",
    "ultimate_package_admission_sleeve_ids",
    "selected_package_bridge_matched_sleeve_ids",
)


PACKAGE_REPLAY_AUTHORITY_SCOPE_MAPPING_FIELDS = (
    "ultimate_candidate_package",
    "ultimate_candidate_package_shadow",
    "ultimate_candidate_package_open_reduced_risk_authority",
    "ultimate_candidate_package_reduce_risk_authority",
    "ultimate_candidate_package_reduced_risk_authority",
    "package_new_entry_authority_payload",
    "package_source_bound_admission_diagnostic",
)


def package_replay_authority_scope_present(
    *surfaces: Mapping[str, Any] | None,
) -> bool:
    """Return true only for rows that carry real package/replay authority lineage.

    Broad action selectors such as ``open-reduced-risk`` still require action
    intent reconciliation elsewhere, but they are not enough to make package
    executable authority mandatory. Generic executable flags such as
    ``package_replay_executable_candidate_use_allowed`` and
    ``replay_candidate_use_allowed_now`` prove order materialization only after
    another surface has established package source/admission lineage. This keeps
    bridge-flattened replay flags from becoming hard source-bound package blocks
    on ordinary selected scheduler rows.
    """

    pending: list[Mapping[str, Any]] = [
        surface for surface in surfaces if isinstance(surface, Mapping)
    ]
    seen: set[int] = set()
    while pending:
        surface = pending.pop(0)
        surface_id = id(surface)
        if surface_id in seen:
            continue
        seen.add(surface_id)
        if package_source_bound_or_admission_alias_allowed(surface):
            return True
        if any(
            _runtime_bool(surface.get(field), False)
            for field in PACKAGE_REPLAY_AUTHORITY_SCOPE_BOOLEAN_FIELDS
        ):
            return True
        if selected_package_bridge_signed_source_bound_authority_allowed(surface):
            return True
        if any(
            safe_float(surface.get(field), 0.0) > 0.0
            for field in PACKAGE_REPLAY_AUTHORITY_SCOPE_COUNT_FIELDS
        ):
            return True
        for field in PACKAGE_REPLAY_AUTHORITY_SCOPE_NONEMPTY_FIELDS:
            value = surface.get(field)
            if isinstance(value, (str, bytes, bytearray)):
                if str(value or "").strip():
                    return True
            elif isinstance(value, Sequence) and value:
                return True
        for field in PACKAGE_REPLAY_AUTHORITY_SCOPE_MAPPING_FIELDS:
            value = surface.get(field)
            if isinstance(value, Mapping) and value:
                return True
        selector_reason = str(
            first_present(
                surface.get("scheduler_materialization_selector_reason"),
                surface.get("effective_selector_reason"),
                surface.get("package_new_entry_authority_selector_reason"),
                surface.get("selector_reason"),
                surface.get("reason"),
                "",
            )
            or ""
        ).lower()
        if "ultimate_candidate_package" in selector_reason:
            return True
        selector_packet = surface.get("selector_packet")
        if isinstance(selector_packet, Mapping):
            pending.append(selector_packet)
            selector_components = selector_packet.get("component_scores")
            if isinstance(selector_components, Mapping):
                pending.append(selector_components)
        for nested_key in (
            "component_scores",
            "score_components",
            "candidate_decision_inputs",
            "scheduler_candidate_decision_inputs",
            "decision_inputs",
        ):
            nested = surface.get(nested_key)
            if isinstance(nested, Mapping):
                pending.append(nested)
        for nested_key in PACKAGE_REPLAY_AUTHORITY_SCOPE_MAPPING_FIELDS:
            nested = surface.get(nested_key)
            if isinstance(nested, Mapping):
                pending.append(nested)
    return False


def scorecard_has_final_selected_candidate(row: Mapping[str, Any]) -> bool:
    if first_present(row.get("selected_candidate_id")) is not None:
        return True
    selected_ids = row.get("selected_candidate_ids")
    if isinstance(selected_ids, (str, bytes, bytearray)):
        return bool(str(selected_ids or "").strip())
    if isinstance(selected_ids, Sequence):
        return any(first_present(item) is not None for item in selected_ids)
    return False


def scorecard_no_final_selection_candidate_authority_scrub_fields(
    row: Mapping[str, Any],
) -> dict[str, Any]:
    """Keep zero-trade scorecards window-scoped, not executable-candidate scoped."""

    if scorecard_has_final_selected_candidate(row):
        return {}
    updates: dict[str, Any] = {}
    scrubbed_fields: list[str] = []
    atomic_reported_authority: dict[str, Any] = {}
    atomic_reported_authority_source = ""
    for prefix in (
        "risk_finalizer_best_package_probe_",
        "finalizer_primary_probe_",
        "risk_finalizer_",
        "pre_risk_finalizer_",
    ):
        surface = {
            key[len(prefix) :]: value
            for key, value in row.items()
            if isinstance(key, str) and key.startswith(prefix)
        }
        if not surface:
            continue
        attribution = package_new_entry_authority_attribution_fields(
            surface,
            validate_against_outer_projection=False,
        )
        if attribution.get("package_new_entry_authority_valid") is True:
            atomic_reported_authority = attribution
            atomic_reported_authority_source = prefix.rstrip("_")
            break
    nonrequired_root_authority = bool(
        row.get("package_new_entry_authority_required") is False
        or str(row.get("package_new_entry_authority_status") or "").strip()
        == "not_required_for_selector_action_or_action_intent"
    )
    candidate_authority_fields = list(
        SCORECARD_NO_FINAL_SELECTION_CANDIDATE_AUTHORITY_FIELDS
    )
    for field in row:
        if (
            str(field).startswith(
                (
                    "package_new_entry_authority_",
                    "materialized_package_new_entry_authority_",
                )
            )
            or field == "expected_package_new_entry_authority_hash_sha256"
            or field in PACKAGE_REPLAY_AUTHORITY_SCOPE_MAPPING_FIELDS
        ):
            candidate_authority_fields.append(field)
    for field in dict.fromkeys(candidate_authority_fields):
        if field not in row:
            continue
        value = row.get(field)
        if value is None:
            continue
        reported_field = f"scorecard_reported_{field}"
        authority_projection_field = bool(
            str(field).startswith("package_new_entry_authority_")
            or field == "expected_package_new_entry_authority_hash_sha256"
        )
        retain_reported_value = not (
            (atomic_reported_authority or nonrequired_root_authority)
            and authority_projection_field
        )
        if (
            retain_reported_value
            and reported_field not in row
            and reported_field not in updates
        ):
            updates[reported_field] = copy.deepcopy(value)
        updates[field] = None
        scrubbed_fields.append(field)
    if atomic_reported_authority:
        for field in row:
            if str(field).startswith(
                "scorecard_reported_package_new_entry_authority_"
            ) or field == (
                "scorecard_reported_expected_package_new_entry_authority_hash_sha256"
            ):
                updates[field] = None
        updates.update(
            {
                f"scorecard_reported_{field}": copy.deepcopy(value)
                for field, value in atomic_reported_authority.items()
            }
        )
        updates["scorecard_reported_package_new_entry_authority_atomic_source"] = (
            atomic_reported_authority_source
        )
        updates[
            "scorecard_reported_package_new_entry_authority_atomic_projection"
        ] = True
    elif nonrequired_root_authority:
        for field in row:
            if str(field).startswith(
                "scorecard_reported_package_new_entry_authority_"
            ) or field == (
                "scorecard_reported_expected_package_new_entry_authority_hash_sha256"
            ):
                updates[field] = None
        updates.update(
            {
                "scorecard_reported_package_new_entry_authority_required": False,
                "scorecard_reported_package_new_entry_authority_valid": False,
                "scorecard_reported_package_new_entry_authority_status": (
                    "not_required_for_selector_action_or_action_intent"
                ),
                "scorecard_reported_package_new_entry_authority_failures": [],
                "scorecard_reported_package_new_entry_authority_nonrequired_state_canonicalized": True,
            }
        )
    if scrubbed_fields:
        updates["scorecard_no_final_selection_candidate_authority_scrubbed"] = True
        updates["scorecard_no_final_selection_scrubbed_fields"] = sorted(
            set(scrubbed_fields)
        )
    updates["executable_finalized"] = False
    updates["risk_finalizer_executable_finalized"] = False
    updates["finalizer_primary_probe_executable_finalized"] = False
    updates.update(
        {
            "runtime_quality_contract_schema_version": (
                "runtime_candidate_quality_contract_v2"
            ),
            "runtime_quality_contract_surface": "scorecard_probe_reported_only",
            "runtime_quality_contract_status": (
                "no_selected_candidate_probe_quality_reported_only"
            ),
            "runtime_quality_contract_selected_top_level_truth": False,
            "runtime_quality_contract_candidate_instance_key": None,
            "runtime_quality_contract_candidate_instance_binding_status": (
                "no_final_selected_candidate"
            ),
        }
    )
    return updates


def scorecard_probe_quality_backfill_fields(row: Mapping[str, Any]) -> dict[str, Any]:
    """Expose no-selected scorecard quality from the finalizer probe.

    Candidate/order/trade ledgers already carry these quality fields. Scorecard
    rows with no final selected candidate still need the probe quality surfaced
    explicitly so parity audits do not confuse present probe evidence for
    missing candidate quality.
    """

    selected_ids = row.get("selected_candidate_ids")
    selected_ids = selected_ids if isinstance(selected_ids, Sequence) else []
    has_selected_candidate = bool(
        str(row.get("selected_candidate_id") or "").strip()
        or any(str(candidate_id or "").strip() for candidate_id in selected_ids)
    )
    if has_selected_candidate:
        return {}
    updates: dict[str, Any] = {}
    backfilled_fields: list[str] = []
    risk_expression_backfill_surfaces: list[dict[str, Any]] = []
    for source_prefix in (
        "finalizer_primary_probe_",
        "risk_finalizer_",
        "pre_risk_finalizer_",
    ):
        surface = {
            key[len(source_prefix) :]: value
            for key, value in row.items()
            if isinstance(key, str) and key.startswith(source_prefix)
        }
        if surface:
            risk_expression_backfill_surfaces.append(surface)
    risk_expression_backfill_fields = risk_expression_proof_fields_from_surfaces(
        *risk_expression_backfill_surfaces,
        row,
    )
    for target_field, source_fields in SCORECARD_PROBE_QUALITY_BACKFILL_FIELDS.items():
        if isinstance(source_fields, str):
            source_fields = (source_fields,)
        reported_field = f"scorecard_reported_{target_field}"
        if first_present(row.get(reported_field)) is not None:
            continue
        source_value = first_present(*(row.get(source_field) for source_field in source_fields))
        if source_value is None:
            source_value = first_present(row.get(target_field))
        if source_value is None:
            continue
        updates[reported_field] = source_value
        backfilled_fields.append(reported_field)
    for target_field in RISK_EXPRESSION_PROOF_LEDGER_KEYS:
        reported_field = f"scorecard_reported_{target_field}"
        if first_present(row.get(reported_field), updates.get(reported_field)) is not None:
            continue
        source_value = first_present(
            row.get(f"finalizer_primary_probe_{target_field}"),
            row.get(f"risk_finalizer_{target_field}"),
            row.get(f"pre_risk_finalizer_{target_field}"),
            risk_expression_backfill_fields.get(target_field),
            row.get(target_field),
        )
        if source_value is None:
            continue
        updates[reported_field] = source_value
        backfilled_fields.append(reported_field)
    context_backfilled_fields: list[str] = []
    for target_field, source_fields in SCORECARD_PROBE_CONTEXT_BACKFILL_FIELDS.items():
        reported_field = f"scorecard_reported_{target_field}"
        if first_present(row.get(reported_field)) is not None:
            continue
        source_value = first_present(*(row.get(source_field) for source_field in source_fields))
        if source_value is None:
            continue
        updates[reported_field] = source_value
        context_backfilled_fields.append(reported_field)
    merged = {**dict(row), **updates}
    candidate_quality = first_present(
        merged.get("scorecard_reported_candidate_decision_quality")
    )
    if not isinstance(candidate_quality, Mapping):
        quality_reported_fields = {
            f"scorecard_reported_{field}"
            for field in SCORECARD_PROBE_QUALITY_BACKFILL_FIELDS
        }
        quality_source = {
            key.replace("scorecard_reported_", "", 1): value
            for key, value in merged.items()
            if isinstance(key, str)
            and key in quality_reported_fields
            and key != "scorecard_reported_candidate_decision_quality"
        }
        nested_quality = candidate_decision_quality_envelope(quality_source)
        if nested_quality:
            updates["scorecard_reported_candidate_decision_quality"] = nested_quality
    if (
        not backfilled_fields
        and not context_backfilled_fields
        and "scorecard_reported_candidate_decision_quality" not in updates
    ):
        return {}
    if backfilled_fields or "scorecard_reported_candidate_decision_quality" in updates:
        updates.update(
            {
                "scorecard_quality_backfill_status": (
                    "finalizer_primary_probe_quality_backfilled"
                ),
                "scorecard_quality_backfill_source": "risk_finalizer_primary_probe",
                "scorecard_quality_backfilled_fields": backfilled_fields,
            }
        )
    if context_backfilled_fields:
        updates.update(
            {
                "scorecard_context_backfill_status": (
                    "finalizer_primary_probe_context_backfilled"
                ),
                "scorecard_context_backfill_source": "risk_finalizer_primary_probe",
                "scorecard_context_backfilled_fields": context_backfilled_fields,
            }
        )
    if updates.get("scorecard_reported_package_new_entry_authority_valid") is not None:
        authority_identity_fields = [
            key
            for key in updates
            if key.startswith("scorecard_reported_package_new_entry_authority_")
            and (
                "candidate_id" in key
                or "candidate_instance" in key
                or "decision_time_utc" in key
            )
        ]
        if authority_identity_fields:
            updates["scorecard_reported_package_new_entry_authority_identity_status"] = (
                "window_level_signed_package_probe_identity_reported"
            )
            updates[
                "scorecard_reported_package_new_entry_authority_identity_fields"
            ] = sorted(authority_identity_fields)
    return updates


def scorecard_source_boundary_backfill_fields(row: Mapping[str, Any]) -> dict[str, Any]:
    """Classify zero-trade scorecard rows as scheduler-window evidence.

    Rows with a selected/probed candidate get candidate-level provenance from
    the selected option or finalizer probe. A zero-trade window still has
    predecision scheduler evidence, but no candidate identity to backfill from;
    leave quality/identity empty and only classify the source boundary.
    """

    selected_ids = row.get("selected_candidate_ids")
    selected_ids = selected_ids if isinstance(selected_ids, Sequence) else []
    has_selected_candidate = bool(
        str(row.get("selected_candidate_id") or "").strip()
        or any(str(candidate_id or "").strip() for candidate_id in selected_ids)
    )
    if has_selected_candidate:
        return {}
    boundary = first_present(
        row.get("source_boundary"),
        row.get("selected_scheduler_source_boundary"),
        row.get("pre_risk_finalizer_source_boundary"),
        row.get("finalizer_primary_probe_source_boundary"),
        row.get("candidate_decision_quality_source_boundary"),
        row.get("selected_scheduler_candidate_decision_quality_source_boundary"),
        row.get("pre_risk_finalizer_candidate_decision_quality_source_boundary"),
        row.get("finalizer_primary_probe_candidate_decision_quality_source_boundary"),
        SCORECARD_NO_SELECTED_SOURCE_BOUNDARY,
    )
    updates: dict[str, Any] = {}
    if first_present(row.get("source_boundary")) is None:
        updates["source_boundary"] = boundary
    if first_present(row.get("candidate_decision_quality_source_boundary")) is None:
        updates["candidate_decision_quality_source_boundary"] = boundary
    if updates:
        updates["scorecard_source_boundary_backfill_status"] = (
            "zero_trade_scheduler_window_boundary_materialized"
        )
        updates["scorecard_source_boundary_backfill_source"] = (
            "scheduler_window_no_selected_candidate"
        )
    return updates


def scorecard_source_required_lifecycle_probe_fields(
    probe_rows: Iterable[Mapping[str, Any]],
) -> dict[str, Any]:
    """Expose source-required lifecycle probes on scorecard rows."""

    source_required_rows: list[Mapping[str, Any]] = []
    reason_counts: Counter[str] = Counter()
    status_counts: Counter[str] = Counter()
    risk_decision_counts: Counter[str] = Counter()
    selected_count = 0
    risk_admitted_count = 0
    blocked_count = 0
    diagnostic_count = 0
    blocker_family_counts: Counter[str] = Counter()
    for row in probe_rows:
        if not isinstance(row, Mapping):
            continue
        text_values = [
            str(row.get(key) or "")
            for key in (
                "risk_decision_reason",
                "status",
                "risk_finalizer_reason",
                "order_materialization_authority_block_reason",
                "execution_manager_replay_admission_status",
                "execution_manager_replay_blocking_reasons",
                "execution_manager_live_promotion_blocker_reasons",
            )
        ]
        source_required = bool(
            _runtime_bool(row.get("source_required_lifecycle_origin"), False)
            or _runtime_bool(
                row.get("source_required_lifecycle_gap_diagnostic_only"),
                False,
            )
            or _runtime_bool(
                row.get(
                    "execution_manager_source_required_package_risk_lifecycle_reconcile_applied"
                ),
                False,
            )
            or any(
                "source_required" in value
                or "lifecycle_source_gap" in value
                or "lifecycle_gap_diagnostic" in value
                for value in text_values
            )
        )
        if not source_required:
            continue
        source_required_rows.append(row)
        if row.get("selected") is True:
            selected_count += 1
        if row.get("risk_admitted") is True:
            risk_admitted_count += 1
        reason = str(row.get("risk_decision_reason") or "unknown")
        status = str(row.get("status") or "unknown")
        risk_decision = str(row.get("risk_decision") or "unknown")
        reason_counts[reason] += 1
        status_counts[status] += 1
        risk_decision_counts[risk_decision] += 1
        if (
            "source_required" in reason
            or "lifecycle_source_gap" in reason
            or "lifecycle_gap_diagnostic" in reason
            or status in {"blocked", "rejected", "risk_rejected"}
            or risk_decision in {"hold", "reject"}
        ):
            blocked_count += 1
        if row.get("source_required_lifecycle_gap_diagnostic_only") is True:
            diagnostic_count += 1
        taxonomy = runtime_source_required_blocker_taxonomy_fields(row)
        blocker_family_counts[
            str(taxonomy["source_required_runtime_blocker_family"])
        ] += 1
    return {
        "source_required_lifecycle_probe_count": len(source_required_rows),
        "source_required_lifecycle_selected_probe_count": selected_count,
        "source_required_lifecycle_risk_admitted_probe_count": risk_admitted_count,
        "source_required_lifecycle_blocked_probe_count": blocked_count,
        "source_required_lifecycle_gap_diagnostic_probe_count": diagnostic_count,
        "source_required_lifecycle_probe_reason_counts": dict(reason_counts),
        "source_required_lifecycle_probe_status_counts": dict(status_counts),
        "source_required_lifecycle_probe_risk_decision_counts": dict(
            risk_decision_counts
        ),
        "source_required_runtime_blocker_family_counts": dict(
            blocker_family_counts
        ),
    }


def runtime_source_required_blocker_taxonomy_fields(
    row: Mapping[str, Any],
) -> dict[str, Any]:
    """Separate source absence from lifecycle, cost, and signed-route blocks."""

    source_status = str(row.get("source_completeness_status") or "").lower()
    source_completeness = safe_float(row.get("source_completeness"), math.nan)
    explicit_missing_source_fields = first_present(
        row.get("missing_source_fields"),
        row.get("source_required_missing_fields"),
        row.get("source_completeness_missing_fields"),
    )
    explicit_missing_source_fields = [
        str(item)
        for item in (
            explicit_missing_source_fields
            if isinstance(explicit_missing_source_fields, (list, tuple, set))
            else [explicit_missing_source_fields]
        )
        if item not in (None, "")
    ]
    exact_missing_source = bool(
        explicit_missing_source_fields
        or (
            math.isfinite(source_completeness)
            and source_completeness < 0.95
        )
        or any(
            token in source_status
            for token in (
                "missing",
                "source_required",
                "incomplete",
                "snapshot_incomplete",
                "prospective_capture",
            )
        )
    )
    cost_status = str(row.get("pretrade_cost_packet_status") or "").upper()
    cost_gap_status = str(row.get("cost_source_gap_status") or "")
    cost_authority = str(
        first_present(row.get("cost_authority"), row.get("execution_cost_authority"))
        or ""
    )
    cost_blocker = bool(
        (cost_status and cost_status not in {"PASSED", "PASS", "OK"})
        or (
            cost_gap_status
            and cost_gap_status != "source_bound_cost_authority_present"
        )
        or (
            cost_authority
            and cost_authority
            not in {"broker_calibrated_replay_cost", "broker_pretrade_cost_only"}
        )
        or _runtime_bool(row.get("candidate_cost_r_fallback_is_authority"), False)
    )
    signed_status = str(row.get("package_new_entry_authority_status") or "")
    signed_valid_value = row.get("package_new_entry_authority_valid")
    signed_failures = row.get("package_new_entry_authority_failures")
    lifecycle_reconciled = any(
        _runtime_bool(row.get(field), False)
        for field in (
            "source_required_package_risk_lifecycle_reconcile_applied",
            "execution_manager_source_required_package_risk_lifecycle_reconcile_applied",
            "same_symbol_lifecycle_permission_reconcile_applied",
            "execution_manager_same_symbol_lifecycle_permission_reconcile_applied",
        )
    )
    signed_authority_blocker = bool(
        signed_valid_value is False
        or (
            signed_status
            and signed_status != "valid_signed_predecision_new_entry_authority"
        )
        or bool(signed_failures)
        or (
            lifecycle_reconciled
            and row.get("source_required_replay_signed_package_authority_valid")
            is False
        )
    )
    reason_text = " ".join(
        str(row.get(key) or "")
        for key in (
            "risk_decision_reason",
            "status",
            "order_materialization_authority_block_reason",
            "execution_manager_replay_admission_status",
            "execution_manager_replay_blocking_reasons",
            "execution_manager_live_promotion_blocker_reasons",
        )
    ).lower()
    lifecycle_blocker = bool(
        (
            _runtime_bool(row.get("source_required_lifecycle_origin"), False)
            and not lifecycle_reconciled
        )
        or "lifecycle" in reason_text
        or "pending_replacement" in reason_text
        or "close_reverse" in reason_text
    )
    if exact_missing_source:
        family = "exact_missing_source"
    elif cost_blocker:
        family = "cost_authority"
    elif signed_authority_blocker:
        family = "signed_route_authority"
    elif lifecycle_blocker:
        family = "lifecycle_authority"
    else:
        family = "unclassified_source_required"
    return {
        "source_required_runtime_taxonomy_schema_version": (
            "source_required_runtime_blocker_taxonomy_v1"
        ),
        "source_required_runtime_blocker_family": family,
        "source_required_exact_missing_source": exact_missing_source,
        "source_required_exact_missing_source_fields": explicit_missing_source_fields,
        "source_required_lifecycle_blocker": lifecycle_blocker,
        "source_required_lifecycle_reconciled": lifecycle_reconciled,
        "source_required_cost_authority_blocker": cost_blocker,
        "source_required_signed_route_authority_blocker": signed_authority_blocker,
    }


def open_reduced_authority_from_surfaces(
    *,
    option: Mapping[str, Any] | None = None,
    decision_inputs: Mapping[str, Any] | None = None,
    components: Mapping[str, Any] | None = None,
    package_authority: Mapping[str, Any] | None = None,
    row: Mapping[str, Any] | None = None,
    packets: Mapping[str, Any] | None = None,
) -> tuple[dict[str, Any], Any, Any]:
    """Normalize explicit package authority for `open-reduced-risk` entries."""

    option = option if isinstance(option, Mapping) else {}
    decision_inputs = (
        decision_inputs if isinstance(decision_inputs, Mapping) else {}
    )
    components = components if isinstance(components, Mapping) else {}
    package_authority = (
        package_authority if isinstance(package_authority, Mapping) else {}
    )
    row = row if isinstance(row, Mapping) else {}
    packets = packets if isinstance(packets, Mapping) else {}
    selector_packet = packets.get("selector_packet")
    selector_packet = selector_packet if isinstance(selector_packet, Mapping) else {}
    selector_components = selector_packet.get("component_scores")
    selector_components = (
        selector_components if isinstance(selector_components, Mapping) else {}
    )
    authority = first_present(
        option.get("ultimate_candidate_package_open_reduced_risk_authority"),
        decision_inputs.get("ultimate_candidate_package_open_reduced_risk_authority"),
        row.get("ultimate_candidate_package_open_reduced_risk_authority"),
        packets.get("ultimate_candidate_package_open_reduced_risk_authority"),
        package_authority.get("ultimate_candidate_package_open_reduced_risk_authority"),
        components.get("ultimate_candidate_package_open_reduced_risk_authority"),
        selector_components.get(
            "ultimate_candidate_package_open_reduced_risk_authority"
        ),
    )
    authority = dict(authority) if isinstance(authority, Mapping) else {}
    allowed = first_present(
        authority.get("allowed"),
        option.get("package_open_reduced_authority_allowed"),
        decision_inputs.get("package_open_reduced_authority_allowed"),
        row.get("package_open_reduced_authority_allowed"),
        row.get("ultimate_package_open_reduced_authority_allowed"),
        packets.get("package_open_reduced_authority_allowed"),
        packets.get("ultimate_package_open_reduced_authority_allowed"),
        package_authority.get("package_open_reduced_authority_allowed"),
        package_authority.get("allowed"),
        components.get("package_open_reduced_authority_allowed"),
    )
    family = first_present(
        authority.get("authority_family"),
        option.get("package_open_reduced_authority_family"),
        decision_inputs.get("package_open_reduced_authority_family"),
        row.get("package_open_reduced_authority_family"),
        packets.get("package_open_reduced_authority_family"),
        package_authority.get("package_open_reduced_authority_family"),
        package_authority.get("authority_family"),
        components.get("package_open_reduced_authority_family"),
    )
    if not authority and (allowed is not None or family is not None):
        authority = {
            "allowed": allowed,
            "authority_family": family,
        }
    elif authority:
        authority.setdefault("allowed", allowed)
        authority.setdefault("authority_family", family)
    if authority and (
        authority.get("current_config_allowed") is False
        or first_present(authority.get("config_block_reason")) is not None
    ):
        authority["allowed"] = False
        allowed = False
        return authority, allowed, family
    if (
        authority
        and authority.get("allowed") is not True
        and _runtime_bool(
            authority.get("ultimate_package_soft_admission_override_allowed"),
            False,
        )
        and package_open_reduced_soft_admission_override_allowed(authority)
    ):
        soft_family = package_authority_primary_family(
            authority,
            authority.get("authority_family"),
            authority.get("selector_reason"),
        )
        if soft_family:
            authority["allowed"] = True
            authority["applies"] = True
            authority["authority_family"] = soft_family
            authority.setdefault(
                "authority_source",
                "derived_from_soft_open_reduced_package_authority",
            )
            allowed = True
            family = soft_family
    return authority, allowed, family


