SIGNED_REDUCED_PACKAGE_NEW_ENTRY_AUTHORITY_BLOCK_PREFIX = (
    "selector_reduced_package_new_entry_signed_authority_invalid"
)
SIGNED_REDUCED_PACKAGE_NEW_ENTRY_ACTIONS = REDUCED_RISK_SIGNED_NEW_ENTRY_ACTION_INTENTS


def reduced_package_new_entry_authority_surface_present(
    *surfaces: Mapping[str, Any] | None,
    authority: Mapping[str, Any] | None = None,
    allowed: Any = None,
    family: Any = None,
) -> bool:
    if isinstance(authority, Mapping) and authority:
        return True
    if allowed not in (None, "") or family not in (None, ""):
        return True
    field_names = (
        "ultimate_candidate_package_open_reduced_risk_authority",
        "ultimate_candidate_package_reduce_risk_authority",
        "ultimate_candidate_package_reduced_risk_authority",
        "package_open_reduced_authority_allowed",
        "package_reduce_risk_authority_allowed",
        "ultimate_package_open_reduced_authority_allowed",
        "ultimate_package_reduce_risk_authority_allowed",
        "package_open_reduced_authority_family",
        "package_reduce_risk_authority_family",
        "package_new_entry_authority_valid",
        "package_new_entry_authority_status",
        "package_new_entry_authority_hash_sha256",
        "expected_package_new_entry_authority_hash_sha256",
    )
    for surface in surfaces:
        if not isinstance(surface, Mapping):
            continue
        for field_name in field_names:
            if surface.get(field_name) not in (None, "", [], {}):
                return True
    return False


def reduced_selector_action_for_authority_surfaces(
    action: Any,
    reason: Any,
    action_intent: Any = None,
    *surfaces: Mapping[str, Any] | None,
) -> str:
    raw_action = str(action or "").strip().lower()
    normalized = normalize_selector_action_for_reason(action, reason, action_intent)
    reduce_fields = (
        "ultimate_candidate_package_reduce_risk_authority",
        "ultimate_candidate_package_reduced_risk_authority",
        "package_reduce_risk_authority_allowed",
        "ultimate_package_reduce_risk_authority_allowed",
        "package_reduce_risk_authority_family",
    )
    open_fields = (
        "ultimate_candidate_package_open_reduced_risk_authority",
        "package_open_reduced_authority_allowed",
        "ultimate_package_open_reduced_authority_allowed",
        "package_open_reduced_authority_family",
    )

    def _has_any_field(surface: Mapping[str, Any], fields: tuple[str, ...]) -> bool:
        signed_authority_field = str(
            first_present(
                surface.get("package_new_entry_authority_authority_field"),
                surface.get("authority_field"),
            )
            or ""
        ).lower()
        if fields == reduce_fields and (
            "reduce_risk" in signed_authority_field
            or "reduce-risk" in signed_authority_field
        ) and "open_reduced" not in signed_authority_field:
            return True
        if fields == open_fields and (
            "open_reduced" in signed_authority_field
            or "open-reduced" in signed_authority_field
        ):
            return True
        for field_name in fields:
            if surface.get(field_name) not in (None, "", [], {}):
                return True
        direct_components = surface.get("component_scores")
        if isinstance(direct_components, Mapping) and _has_any_field(
            direct_components,
            fields,
        ):
            return True
        selector_packet = surface.get("selector_packet")
        if isinstance(selector_packet, Mapping):
            selector_components = selector_packet.get("component_scores")
            if isinstance(selector_components, Mapping) and _has_any_field(
                selector_components,
                fields,
            ):
                return True
        return False

    def _surface_chain() -> list[Mapping[str, Any]]:
        chain: list[Mapping[str, Any]] = []
        seen: set[int] = set()

        def add(surface: Mapping[str, Any] | None) -> None:
            if not isinstance(surface, Mapping):
                return
            marker = id(surface)
            if marker in seen:
                return
            seen.add(marker)
            chain.append(surface)
            for nested_key in (
                "score_components",
                "candidate_decision_inputs",
                "selector_packet",
                "component_scores",
            ):
                nested = surface.get(nested_key)
                if isinstance(nested, Mapping):
                    add(nested)
            selector_packet = surface.get("selector_packet")
            if isinstance(selector_packet, Mapping):
                selector_components = selector_packet.get("component_scores")
                if isinstance(selector_components, Mapping):
                    add(selector_components)
            for authority_key in (
                "ultimate_candidate_package_open_reduced_risk_authority",
                "ultimate_candidate_package_reduce_risk_authority",
                "ultimate_candidate_package_reduced_risk_authority",
            ):
                authority = surface.get(authority_key)
                if isinstance(authority, Mapping):
                    add(authority)

        for surface in surfaces:
            add(surface if isinstance(surface, Mapping) else None)
        return chain

    def _intent_allows(candidate_action: str, surface: Mapping[str, Any]) -> bool:
        intent = str(
            first_present(
                action_intent,
                surface.get("scheduler_materialization_action_intent"),
                surface.get("package_new_entry_authority_target_action_intent"),
                surface.get("action_intent"),
            )
            or ""
        ).strip()
        if not intent:
            return True
        if candidate_action == "open-reduced-risk":
            return intent in SELECTOR_OPEN_REDUCED_RISK_ALLOWED_ACTION_INTENTS
        if candidate_action == "reduce-risk":
            return intent in SELECTOR_REDUCE_RISK_ALLOWED_ACTION_INTENTS
        return False

    def _authority_payload_allowed(
        surface: Mapping[str, Any],
        candidate_action: str,
    ) -> bool:
        authority_key = (
            "ultimate_candidate_package_open_reduced_risk_authority"
            if candidate_action == "open-reduced-risk"
            else "ultimate_candidate_package_reduce_risk_authority"
        )
        payload = surface.get(authority_key)
        payload = payload if isinstance(payload, Mapping) else {}
        status_text = str(
            first_present(
                surface.get("package_new_entry_authority_status"),
                payload.get("status"),
                payload.get("authority_status"),
            )
            or ""
        ).strip().lower()
        if _runtime_bool(
            first_present(
                surface.get("package_new_entry_authority_valid"),
                payload.get("valid"),
                payload.get("authority_valid"),
            ),
            False,
        ):
            return True
        if (
            "valid" in status_text
            and "invalid" not in status_text
            and "refused" not in status_text
            and "blocked" not in status_text
        ):
            return True
        if candidate_action == "open-reduced-risk":
            return _runtime_bool(
                first_present(
                    payload.get("allowed"),
                    payload.get("current_config_allowed"),
                    surface.get("package_open_reduced_authority_allowed"),
                    surface.get("ultimate_package_open_reduced_authority_allowed"),
                    surface.get("package_replay_order_executable_candidate_use_allowed"),
                    surface.get("package_replay_executable_candidate_use_allowed"),
                ),
                False,
            )
        return _runtime_bool(
            first_present(
                payload.get("allowed"),
                payload.get("current_config_allowed"),
                surface.get("package_reduce_risk_authority_allowed"),
                surface.get("ultimate_package_reduce_risk_authority_allowed"),
                surface.get("package_replay_order_executable_candidate_use_allowed"),
                surface.get("package_replay_executable_candidate_use_allowed"),
            ),
            False,
        )

    def _signed_or_materialized_action() -> str | None:
        action_fields = (
            "package_new_entry_authority_selector_action",
            "materialized_package_new_entry_authority_selector_action",
            "scheduler_materialization_selector_action",
            "scheduler_materialization_effective_selector_action",
            "effective_selector_action",
        )
        for surface in _surface_chain():
            for field_name in action_fields:
                candidate_action = str(surface.get(field_name) or "").strip().lower()
                if candidate_action not in {"open-reduced-risk", "reduce-risk"}:
                    continue
                if not _intent_allows(candidate_action, surface):
                    continue
                if _authority_payload_allowed(surface, candidate_action):
                    return candidate_action
        return None

    has_reduce_authority = any(
        _has_any_field(surface, reduce_fields)
        for surface in surfaces
        if isinstance(surface, Mapping)
    )
    has_open_authority = any(
        _has_any_field(surface, open_fields)
        for surface in surfaces
        if isinstance(surface, Mapping)
    )
    if raw_action == "open-reduced-risk":
        return "open-reduced-risk"
    if raw_action == "reduce-risk" and has_reduce_authority and not has_open_authority:
        return "reduce-risk"
    signed_or_materialized_action = _signed_or_materialized_action()
    if raw_action not in RISK_BEARING_SELECTOR_ACTIONS and signed_or_materialized_action:
        return signed_or_materialized_action
    reason_text = str(reason or "").strip().lower()
    if raw_action not in RISK_BEARING_SELECTOR_ACTIONS:
        if has_open_authority and (
            "open_reduced" in reason_text
            or "open-reduced" in reason_text
            or "open reduced" in reason_text
        ):
            return "open-reduced-risk"
        if has_reduce_authority and (
            "reduce_risk" in reason_text
            or "reduce-risk" in reason_text
            or "reduce risk" in reason_text
        ):
            return "reduce-risk"
    if normalized == "open-reduced-risk" and has_open_authority:
        return "open-reduced-risk"
    if not raw_action and has_open_authority and not has_reduce_authority:
        return "open-reduced-risk"
    if not raw_action and has_reduce_authority and not has_open_authority:
        return "reduce-risk"
    return normalized
