def canonicalize_hash_bound_package_new_entry_authority_projection(
    authority: Mapping[str, Any],
    *,
    current_identity: Mapping[str, str] | None = None,
) -> tuple[dict[str, Any], tuple[str, ...]]:
    """Rebuild mutable projections from one immutable signed payload."""

    original = dict(authority) if isinstance(authority, Mapping) else {}
    payload = original.get("package_new_entry_authority_payload")
    if not isinstance(payload, Mapping):
        return original, ("authority_payload_missing",)
    payload_hash = package_new_entry_authority_payload_hash_sha256(payload)
    authority_hash = str(
        original.get(PACKAGE_NEW_ENTRY_AUTHORITY_HASH_FIELD) or ""
    ).strip()
    expected_hash = str(
        original.get("expected_package_new_entry_authority_hash_sha256") or ""
    ).strip()
    if not (
        is_sha256(authority_hash)
        and is_sha256(expected_hash)
        and authority_hash == expected_hash == payload_hash
    ):
        return original, ("authority_payload_hash_invalid",)

    projected = dict(original)
    for projection_field, payload_field in (
        PACKAGE_NEW_ENTRY_AUTHORITY_IMMUTABLE_PAYLOAD_PROJECTION_FIELDS
    ):
        if payload_field in payload:
            projected[projection_field] = copy.deepcopy(payload[payload_field])
    projected["package_new_entry_authority_valid"] = True
    projected["package_new_entry_authority_status"] = (
        "valid_signed_predecision_new_entry_authority"
    )
    projected["package_new_entry_authority_failures"] = []
    failures = tuple(
        package_new_entry_authority_immutable_payload_failures(
            projected,
            current_identity=current_identity,
        )
    )
    if failures:
        return original, failures
    projected[
        "package_new_entry_authority_projection_canonicalized_from_hash_bound_payload"
    ] = True
    return projected, ()


def _finalize_ultimate_package_effective_executable_authority_fields(
    row: MutableMapping[str, Any],
    *,
    demote_final_blocked_claim_aliases: bool = False,
) -> bool:
    """Recompute effective executable authority from the row's final aliases."""

    transfer_status = str(
        row.get("package_replay_order_executable_transfer_status") or ""
    ).strip()
    transfer_blocked = transfer_status in {
        "final_blocked",
        "not_order_executable",
        "terminal_lifecycle_deferred_source_gap",
        "unbound_without_final_blocker",
    }
    if transfer_blocked and demote_final_blocked_claim_aliases:
        if _runtime_bool(
            row.get("ultimate_package_effective_executable_authority_allowed"),
            False,
        ):
            row["ultimate_package_pre_finalization_executable_authority_allowed"] = (
                True
            )
        row_provenance_fields_present = {
            field
            for field in FINAL_SERIALIZATION_EFFECTIVE_EXECUTABLE_PROVENANCE_FIELDS
            if field in row
        }
        for field in row_provenance_fields_present:
            value = row.get(field)
            generated_final_provenance = bool(
                str(value or "").startswith("final_transfer_blocked:")
                or (
                    field.endswith("authority_source")
                    and value == "package_replay_order_executable_transfer_status"
                )
            )
            if value not in (None, "", [], {}) and not generated_final_provenance:
                row.setdefault(f"{field}_pre_finalization", value)
        for field in FINAL_SERIALIZATION_EFFECTIVE_EXECUTABLE_CLAIM_FIELDS:
            value = row.get(field)
            if _runtime_bool(value, False):
                row.setdefault(f"{field}_pre_finalization", value)
            row[field] = False
        final_blocker_reason = first_present(
            row.get("package_replay_order_executable_final_blocker_reason"),
            transfer_status,
        )
        if "package_replay_executable_candidate_use_allowed_reason" in (
            row_provenance_fields_present
        ):
            row["package_replay_executable_candidate_use_allowed_reason"] = (
                f"final_transfer_blocked:{final_blocker_reason}"
            )
        if "package_replay_executable_authority_source" in row_provenance_fields_present:
            row["package_replay_executable_authority_source"] = (
                "package_replay_order_executable_transfer_status"
            )
        row["package_replay_order_executable_candidate_use_allowed_reason"] = (
            f"final_transfer_blocked:{final_blocker_reason}"
        )
        row["package_replay_order_executable_authority_source"] = (
            "package_replay_order_executable_transfer_status"
        )
        if "replay_candidate_use_allowed_now_reason" in row_provenance_fields_present:
            row["replay_candidate_use_allowed_now_reason"] = (
                f"final_transfer_blocked:{final_blocker_reason}"
            )
        row["package_replay_effective_executable_alias_reconciliation_status"] = (
            "final_blocked_aliases_demoted_preserving_signed_predecision_envelope"
        )
        nested_demoted_paths: list[str] = []
        nested_surfaces: list[tuple[str, MutableMapping[str, Any]]] = []
        seen_nested_surfaces: set[int] = set()

        def add_nested_surface(
            path: str,
            value: Any,
        ) -> None:
            if not isinstance(value, MutableMapping):
                return
            if id(value) in seen_nested_surfaces:
                return
            seen_nested_surfaces.add(id(value))
            nested_surfaces.append((path, value))

        for surface_field in FINAL_SERIALIZATION_EFFECTIVE_EXECUTABLE_ALIAS_SURFACES:
            surface = row.get(surface_field)
            add_nested_surface(surface_field, surface)
            if surface_field == "score_components" and isinstance(
                surface,
                Mapping,
            ):
                add_nested_surface(
                    "score_components.candidate_decision_inputs",
                    surface.get("candidate_decision_inputs"),
                )

        for surface_path, surface in nested_surfaces:
            demoted_fields: list[str] = []
            surface_provenance_fields_present = {
                field
                for field in FINAL_SERIALIZATION_EFFECTIVE_EXECUTABLE_PROVENANCE_FIELDS
                if field in surface
            }
            for field in surface_provenance_fields_present:
                value = surface.get(field)
                generated_final_provenance = bool(
                    str(value or "").startswith("final_transfer_blocked:")
                    or (
                        field.endswith("authority_source")
                        and value == "package_replay_order_executable_transfer_status"
                    )
                )
                if value not in (None, "", [], {}) and not generated_final_provenance:
                    surface.setdefault(f"{field}_pre_finalization", value)
                    row.setdefault(f"{field}_pre_finalization", value)
            for field in FINAL_SERIALIZATION_EFFECTIVE_EXECUTABLE_CLAIM_FIELDS:
                if field not in surface:
                    continue
                value = surface.get(field)
                if _runtime_bool(value, False):
                    surface.setdefault(f"{field}_pre_finalization", value)
                    demoted_fields.append(field)
                surface[field] = False
            if not demoted_fields:
                continue
            if (
                "package_replay_order_executable_candidate_use_allowed"
                in demoted_fields
            ):
                row.setdefault(
                    "package_replay_order_executable_candidate_use_allowed_pre_finalization",
                    True,
                )
            if "package_replay_executable_candidate_use_allowed_reason" in (
                surface_provenance_fields_present
            ):
                surface["package_replay_executable_candidate_use_allowed_reason"] = (
                    f"final_transfer_blocked:{final_blocker_reason}"
                )
            if "package_replay_executable_authority_source" in (
                surface_provenance_fields_present
            ):
                surface["package_replay_executable_authority_source"] = (
                    "package_replay_order_executable_transfer_status"
                )
            surface[
                "package_replay_order_executable_candidate_use_allowed_reason"
            ] = f"final_transfer_blocked:{final_blocker_reason}"
            surface["package_replay_order_executable_authority_source"] = (
                "package_replay_order_executable_transfer_status"
            )
            if "replay_candidate_use_allowed_now_reason" in (
                surface_provenance_fields_present
            ):
                surface["replay_candidate_use_allowed_now_reason"] = (
                    f"final_transfer_blocked:{final_blocker_reason}"
                )
            surface[
                "package_replay_effective_executable_alias_reconciliation_status"
            ] = (
                "final_blocked_aliases_demoted_preserving_signed_predecision_envelope"
            )
            nested_demoted_paths.extend(
                f"{surface_path}.{field}" for field in demoted_fields
            )
        if nested_demoted_paths:
            row["package_replay_nested_effective_executable_aliases_demoted"] = (
                sorted(dict.fromkeys(nested_demoted_paths))
            )
    executable_alias_values = [
        row.get(field)
        for field in (
            "package_replay_candidate_use_allowed",
            "package_replay_executable_candidate_use_allowed",
            "replay_candidate_use_allowed_now",
            "ledger_namespace_synthesized_executable_candidate_use_allowed",
        )
        if row.get(field) is not None
    ]
    order_executable_allowed = _runtime_bool(
        first_present(
            row.get("package_replay_order_executable_candidate_use_allowed"),
            row.get(
                "package_new_entry_authority_package_replay_order_executable_candidate_use_allowed"
            ),
        ),
        False,
    )
    effective_executable_authority_allowed = bool(
        package_source_bound_or_admission_alias_allowed(row)
        and executable_alias_values
        and all(_runtime_bool(value, False) for value in executable_alias_values)
        and order_executable_allowed
        and not transfer_blocked
    )
    if (
        _runtime_bool(
            row.get("ultimate_package_effective_executable_authority_allowed"),
            False,
        )
        and not effective_executable_authority_allowed
    ):
        row["ultimate_package_pre_finalization_executable_authority_allowed"] = True
    row["ultimate_package_effective_executable_authority_allowed"] = (
        effective_executable_authority_allowed
    )
    row["ultimate_package_effective_executable_authority_status"] = (
        "finalized_concrete_authority_allowed"
        if effective_executable_authority_allowed
        else "finalized_non_executable_diagnostic"
    )
    return effective_executable_authority_allowed


def normalize_candidate_cost_alias_fields(row: dict[str, Any]) -> dict[str, Any]:
    """Make terminal candidate cost aliases exact while preserving conflicts."""

    if not isinstance(row, dict):
        return row
    expected_cost_r = first_present(
        row.get("expected_cost_r"),
        row.get("cost_r"),
    )
    if expected_cost_r not in (None, ""):
        existing_cost_r = row.get("cost_r")
        if (
            existing_cost_r not in (None, "")
            and not math.isclose(
                safe_float(existing_cost_r),
                safe_float(expected_cost_r),
                rel_tol=0.0,
                abs_tol=1e-12,
            )
        ):
            row["candidate_cost_alias_conflict"] = {
                "expected_cost_r": expected_cost_r,
                "cost_r": existing_cost_r,
            }
        row["expected_cost_r"] = expected_cost_r
        row["cost_r"] = expected_cost_r
        row["candidate_cost_alias_status"] = "materialized_exact_alias"
    return row


def normalize_package_new_entry_authority_ledger_row(
    row: dict[str, Any],
    *,
    final_serialization_boundary: bool = True,
) -> dict[str, Any]:
    """Keep package authority fields atomic on emitted ledger rows."""

    if not isinstance(row, dict):
        return row

    normalize_candidate_cost_alias_fields(row)
    prior_provisional_marker_strip_count = int(
        safe_float(
            row.get("package_new_entry_authority_provisional_marker_strip_count"),
            0.0,
        )
    )
    provisional_marker_strip_count = (
        strip_provisional_package_new_entry_authority_markers(row)
    )
    _preserve_package_replay_time_aliases(row)
    _preserve_selector_materialization_original_fields(row)
    admission_selector_action = first_present(
        row.get("scheduler_materialization_selector_action"),
        row.get("materialized_package_selector_action"),
        row.get("materialized_selector_action"),
        row.get("package_new_entry_authority_selector_action"),
        row.get("effective_selector_action_before_risk_expression"),
        row.get("scheduler_materialization_original_selector_action"),
        row.get("raw_selector_action"),
        row.get("selector_action"),
    )
    admission_selector_reason = first_present(
        row.get("scheduler_materialization_selector_reason"),
        row.get("materialized_selector_reason"),
        row.get("package_new_entry_authority_selector_reason"),
        row.get("raw_selector_reason"),
        row.get("selector_reason"),
    )
    admission_action_intent = first_present(
        row.get("scheduler_materialization_action_intent"),
        row.get("effective_action_intent"),
        row.get("package_new_entry_authority_target_action_intent"),
        row.get("action_intent"),
        "new_position",
    )
    admission_authority_validation = reduced_package_new_entry_authority_validation(
        row,
        selector_action=admission_selector_action,
        selector_reason=admission_selector_reason,
        action_intent=admission_action_intent,
    )
    existing_signed_attribution = package_new_entry_authority_attribution_fields(row)
    if (
        admission_authority_validation.get("required") is False
        and existing_signed_attribution.get("package_new_entry_authority_valid")
        is not True
        and not package_new_entry_authority_signed_claim_present(row)
    ):
        row["package_new_entry_authority_required"] = False
        row["package_new_entry_authority_valid"] = False
        row["package_new_entry_authority_status"] = (
            "not_required_for_selector_action_or_action_intent"
        )
        row["package_new_entry_authority_failures"] = []
        row["package_new_entry_authority_projection_failures"] = []
        row["package_new_entry_authority_nonrequired_state_canonicalized"] = True
    for diagnostic_surface in (
        row,
        row.get("candidate_decision_inputs"),
        row.get("scheduler_candidate_decision_inputs"),
        row.get("selected_scheduler_candidate_decision_inputs"),
        row.get("selected_scheduler_decision_inputs"),
    ):
        if not isinstance(diagnostic_surface, dict):
            continue
        if (
            diagnostic_surface.get("package_new_entry_authority_required") is False
            and str(
                diagnostic_surface.get("package_new_entry_authority_status") or ""
            ).strip()
            == "not_required_for_selector_action_or_action_intent"
            and not package_new_entry_authority_signed_claim_present(
                diagnostic_surface
            )
        ):
            diagnostic_surface["package_new_entry_authority_valid"] = False
            diagnostic_surface["package_new_entry_authority_failures"] = []
            diagnostic_surface["package_new_entry_authority_projection_failures"] = []
    if (
        row.get("scheduler_materialization_selector_action") in (None, "")
        and admission_selector_action not in (None, "")
    ):
        row["scheduler_materialization_selector_action"] = admission_selector_action
        row["scheduler_materialization_selector_action_source"] = (
            "canonical_admission_action_before_runtime_risk_expression"
        )
    runtime_public_risk_fields = runtime_risk_public_authority_fields(row)
    if runtime_public_risk_fields:
        row.update(runtime_public_risk_fields)
    risk_authority = row.get("risk_authority")
    if isinstance(risk_authority, Mapping):
        nested_risk_authority_status = first_present(
            risk_authority.get("risk_authority_status"),
            risk_authority.get("status"),
        )
        if nested_risk_authority_status not in (None, ""):
            existing_risk_authority_status = row.get("risk_authority_status")
            if existing_risk_authority_status != nested_risk_authority_status:
                row["risk_authority_status"] = nested_risk_authority_status
            row["risk_authority_status_source"] = (
                "risk_authority.risk_authority_status"
            )
        for key, value in signed_soft_transfer_displacement_trace_fields(
            risk_authority
        ).items():
            if row.get(key) in (None, "", [], {}):
                row[key] = value
    diagnostic_fill_scope = bool(
        row.get("diagnostic_fill_only") is True
        or str(row.get("package_execution_result_scope") or "")
        == "diagnostic_counterfactual_only"
        or (
            row.get("fill_realism_executable") is False
            and str(row.get("fill_realism_class") or "").strip()
            not in {"", "not_filled"}
        )
    )
    if diagnostic_fill_scope:
        row["diagnostic_fill_only"] = True
        row["fill_realism_executable"] = False
        row["package_execution_result_scope"] = "diagnostic_counterfactual_only"
    ladder = risk_expression_ladder_payload(row)
    if ladder:
        row["risk_expression_ladder"] = ladder
        row["risk_expression_ladder_tier"] = ladder.get("ladder_tier")
        row["risk_expression_ladder_tier_causes"] = list(
            ladder.get("tier_causes") or []
        )
    candidate_owned_missed_authority = (
        _reconcile_candidate_owned_missed_new_entry_authority(row)
    )
    if candidate_owned_missed_authority:
        row.update(candidate_owned_missed_authority)
    pre_attribution_transfer_status = str(
        row.get("package_replay_order_executable_transfer_status") or ""
    ).strip()
    blocked_final_serialization = bool(
        final_serialization_boundary
        and pre_attribution_transfer_status
        in {
            "final_blocked",
            "not_order_executable",
            "terminal_lifecycle_deferred_source_gap",
            "unbound_without_final_blocker",
        }
    )
    if blocked_final_serialization:
        designated_authority_field = str(
            row.get("package_new_entry_authority_authority_field") or ""
        ).strip()
        designated_authority = row.get(designated_authority_field)
        if designated_authority_field and isinstance(
            designated_authority,
            Mapping,
        ):
            (
                canonical_designated_authority,
                designated_projection_failures,
            ) = canonicalize_hash_bound_package_new_entry_authority_projection(
                designated_authority,
                current_identity=_signed_package_new_entry_current_identity(row),
            )
            if not designated_projection_failures:
                row[designated_authority_field] = canonical_designated_authority
                row[
                    "package_new_entry_authority_designated_projection_canonicalized_at_final_blocked_serialization"
                ] = True
            else:
                row[
                    "package_new_entry_authority_designated_projection_canonicalization_failures"
                ] = list(designated_projection_failures)
    attribution = package_new_entry_authority_attribution_fields(
        row,
        validate_against_outer_projection=not blocked_final_serialization,
    )
    if attribution:
        row.update(attribution)
    if blocked_final_serialization and _runtime_bool(
        attribution.get("package_new_entry_authority_valid"),
        False,
    ):
        row[
            "package_new_entry_authority_intrinsic_validation_at_final_blocked_serialization"
        ] = True
    _reconcile_rederived_package_replay_candidate_false_alias(row)
    transfer_fields = package_order_executable_final_blocker_fields(row)
    if transfer_fields:
        row.update(transfer_fields)
        if row.get("package_replay_order_executable_transfer_status") in {
            "final_blocked",
            "trade_bound",
            "order_bound",
        } or row.get("risk_decision") not in (None, ""):
            refreshed_ladder = risk_expression_ladder_payload(
                row,
                force_recompute=True,
            )
            if refreshed_ladder:
                row["risk_expression_ladder"] = refreshed_ladder
                row["risk_expression_ladder_tier"] = refreshed_ladder.get(
                    "ladder_tier"
                )
                row["risk_expression_ladder_tier_causes"] = list(
                    refreshed_ladder.get("tier_causes") or []
                )
                row["risk_expression_ladder_finalized_after_guards"] = True
                row["risk_expression_ladder_refresh_reason"] = refreshed_ladder.get(
                    "refresh_reason"
                )
    _finalize_ultimate_package_effective_executable_authority_fields(row)
    if "missed_non_executable_diagnostic_reason" in row:
        transfer_status = str(
            row.get("package_replay_order_executable_transfer_status") or ""
        )
        final_blocker_reason = row.get(
            "package_replay_order_executable_final_blocker_reason"
        )
        final_blocker_class = row.get(
            "package_replay_order_executable_final_blocker_class"
        )
        final_blocker_source = row.get(
            "package_replay_order_executable_final_blocker_source"
        )
        bound_order_id = row.get("package_replay_order_executable_bound_order_id")
        bound_trade_id = row.get("package_replay_order_executable_bound_trade_id")
        terminal_binding_status = row.get("package_replay_terminal_binding_status")
        terminal_bound_order_id = row.get("package_replay_terminal_bound_order_id")
        terminal_bound_trade_id = row.get("package_replay_terminal_bound_trade_id")
        terminal_deferred_order_id = row.get(
            "package_replay_terminal_deferred_order_id"
        )
        terminal_deferred_trade_id = row.get(
            "package_replay_terminal_deferred_trade_id"
        )
        if transfer_status:
            row["missed_package_replay_order_executable_transfer_status"] = (
                transfer_status
            )
            row["missed_package_replay_order_executable_final_blocker_class"] = (
                final_blocker_class
            )
            row["missed_package_replay_order_executable_final_blocker_reason"] = (
                final_blocker_reason
            )
            row["missed_package_replay_order_executable_final_blocker_source"] = (
                final_blocker_source
            )
            row["missed_package_replay_order_executable_bound_order_id"] = (
                bound_order_id
            )
            row["missed_package_replay_order_executable_bound_trade_id"] = (
                bound_trade_id
            )
            row["missed_package_replay_terminal_binding_status"] = (
                terminal_binding_status
            )
            row["missed_package_replay_terminal_bound_order_id"] = (
                terminal_bound_order_id
            )
            row["missed_package_replay_terminal_bound_trade_id"] = (
                terminal_bound_trade_id
            )
            row["missed_package_replay_terminal_deferred_order_id"] = (
                terminal_deferred_order_id
            )
            row["missed_package_replay_terminal_deferred_trade_id"] = (
                terminal_deferred_trade_id
            )
        if (
            final_blocker_reason not in (None, "")
            and transfer_status
            in {
                "final_blocked",
                "not_order_executable",
                "terminal_lifecycle_deferred_source_gap",
                "unbound_without_final_blocker",
            }
            and row.get("missed_non_executable_diagnostic_reason")
            in {
                "package_replay_order_executable_authority_missing",
                "cost_passed_broker_authority_without_execution_bound_order_path",
            }
        ):
            row["missed_non_executable_diagnostic_reason"] = final_blocker_reason
            row["missed_opportunity_execution_bound_order_authority_missing"] = False
            row["missed_package_replay_order_executable_attribution_repaired"] = True
        if transfer_status in {"order_bound", "trade_bound"}:
            order_bound = bool(bound_order_id not in (None, "") or bound_trade_id not in (None, ""))
            row["missed_opportunity_execution_bound_order_authority"] = order_bound
            if order_bound:
                row["missed_opportunity_execution_bound_order_authority_missing"] = (
                    False
                )
        _sync_missed_package_order_executable_authority_fields(row)
    materialized_selector_reason = first_present(
        row.get("scheduler_materialization_selector_reason"),
        row.get("package_new_entry_authority_selector_reason"),
        row.get("effective_selector_reason"),
        row.get("selector_reason"),
    )
    materialized_selector_action = reduced_selector_action_for_authority_surfaces(
        first_present(
            row.get("scheduler_materialization_selector_action"),
            row.get("package_new_entry_authority_selector_action"),
            row.get("effective_selector_action"),
            row.get("selector_action"),
        ),
        materialized_selector_reason,
        row.get("scheduler_materialization_action_intent")
        or row.get("package_new_entry_authority_target_action_intent"),
        row,
    )
    if materialized_selector_action not in (None, ""):
        original_action = row.get("selector_action")
        if original_action not in (None, ""):
            row.setdefault("raw_selector_action", original_action)
        if (
            original_action not in (None, "")
            and original_action != materialized_selector_action
        ):
            row.setdefault("selector_action_origin", original_action)
            row["selector_action_materialized_from_scheduler"] = True
        canonical_original_action = first_present(
            row.get("scheduler_materialization_original_selector_action"),
            row.get("selector_action_origin"),
            row.get("raw_selector_action"),
        )
        if canonical_original_action not in (None, ""):
            row["raw_selector_action"] = canonical_original_action
        if (
            canonical_original_action not in (None, "")
            and canonical_original_action != materialized_selector_action
        ):
            row.setdefault(
                "scheduler_materialization_original_selector_action",
                canonical_original_action,
            )
            row.setdefault("selector_action_origin", canonical_original_action)
            row["selector_action_materialized_from_scheduler"] = True
        if canonical_original_action not in (None, ""):
            row["selector_action"] = canonical_original_action
        elif original_action not in (None, ""):
            row["selector_action"] = original_action
        else:
            row["selector_action"] = materialized_selector_action
        row["effective_selector_action"] = materialized_selector_action
        row["materialized_selector_action"] = materialized_selector_action
        package_authority_action = row.get("package_new_entry_authority_selector_action")
        if (
            package_authority_action not in (None, "")
            and package_authority_action != materialized_selector_action
        ):
            row.setdefault(
                "package_new_entry_authority_selector_action_origin",
                package_authority_action,
            )
            row[
                "package_new_entry_authority_selector_action_materialized_from_scheduler"
            ] = True
            row["package_new_entry_authority_selector_action_conflict"] = True
            row["materialized_package_new_entry_authority_selector_action"] = (
                materialized_selector_action
            )
        elif package_authority_action not in (None, ""):
            row["materialized_package_new_entry_authority_selector_action"] = (
                materialized_selector_action
            )
        original_admission_risk_class = row.get("admission_risk_class")
        if (
            original_admission_risk_class not in (None, "")
            and original_admission_risk_class != materialized_selector_action
        ):
            row.setdefault("admission_risk_class_origin", original_admission_risk_class)
        row["admission_risk_class"] = materialized_selector_action
        row["effective_admission_risk_class"] = materialized_selector_action
    elif row.get("effective_selector_action") in (None, "") and row.get(
        "selector_action"
    ) not in (None, ""):
        row["effective_selector_action"] = row.get("selector_action")

    if materialized_selector_reason not in (None, ""):
        original_reason = row.get("selector_reason")
        if original_reason not in (None, ""):
            row.setdefault("raw_selector_reason", original_reason)
        if (
            original_reason not in (None, "")
            and original_reason != materialized_selector_reason
        ):
            row.setdefault("selector_reason_origin", original_reason)
        canonical_original_reason = first_present(
            row.get("scheduler_materialization_original_selector_reason"),
            row.get("selector_reason_origin"),
            row.get("raw_selector_reason"),
        )
        if canonical_original_reason not in (None, ""):
            row["raw_selector_reason"] = canonical_original_reason
            row["selector_reason"] = canonical_original_reason
        elif original_reason not in (None, ""):
            row["selector_reason"] = original_reason
        else:
            row["selector_reason"] = materialized_selector_reason
        row["effective_selector_reason"] = materialized_selector_reason
        row["materialized_selector_reason"] = materialized_selector_reason
        package_authority_reason = row.get("package_new_entry_authority_selector_reason")
        if (
            package_authority_reason not in (None, "")
            and package_authority_reason != materialized_selector_reason
        ):
            row.setdefault(
                "package_new_entry_authority_selector_reason_origin",
                package_authority_reason,
            )
            row[
                "package_new_entry_authority_selector_reason_materialized_from_scheduler"
            ] = True
            row["package_new_entry_authority_selector_reason_conflict"] = True
            row["materialized_package_new_entry_authority_selector_reason"] = (
                materialized_selector_reason
            )
        elif package_authority_reason not in (None, ""):
            row["materialized_package_new_entry_authority_selector_reason"] = (
                materialized_selector_reason
            )
    elif row.get("effective_selector_reason") in (None, "") and row.get(
        "selector_reason"
    ) not in (None, ""):
        row["effective_selector_reason"] = row.get("selector_reason")
    if (
        row.get("missed_effective_authority_status")
        == "non_executable_diagnostic_raw_intent_preserved"
    ):
        diagnostic_scheduler_materialized_action = first_present(
            row.get("scheduler_materialization_selector_action"),
            row.get("materialized_selector_action"),
            materialized_selector_action,
        )
        diagnostic_scheduler_materialized_reason = first_present(
            row.get("scheduler_materialization_selector_reason"),
            row.get("materialized_selector_reason"),
            materialized_selector_reason,
        )
        row["selector_action"] = "reject"
        row["effective_selector_action"] = "reject"
        row["materialized_selector_action"] = "reject"
        if diagnostic_scheduler_materialized_action not in (None, ""):
            row["scheduler_materialization_selector_action"] = (
                diagnostic_scheduler_materialized_action
            )
        else:
            row["scheduler_materialization_selector_action"] = "reject"
        row["admission_risk_class"] = "reject"
        row["effective_admission_risk_class"] = "reject"
        diagnostic_reason = first_present(
            row.get("missed_effective_authority_reason"),
            row.get("missed_non_executable_diagnostic_reason"),
            row.get("selector_reason"),
            "missed_opportunity_non_executable_diagnostic",
        )
        row.update(
            non_executable_missed_replay_authority_flag_overrides(
                row,
                reason=diagnostic_reason,
            )
        )
        row["selector_reason"] = diagnostic_reason
        row["effective_selector_reason"] = diagnostic_reason
        row["materialized_selector_reason"] = diagnostic_reason
        if diagnostic_scheduler_materialized_reason not in (None, ""):
            row["scheduler_materialization_selector_reason"] = (
                diagnostic_scheduler_materialized_reason
            )
        else:
            row["scheduler_materialization_selector_reason"] = diagnostic_reason
        row["risk_pct"] = 0.0
        row["approved_risk_pct"] = 0.0
        row["scheduler_approved_risk_pct"] = 0.0
        row["final_approved_risk_pct"] = 0.0
        row["effective_risk_pct"] = 0.0
    else:
        apply_risk_expression_effective_action_fields(row)
    _preserve_selector_materialization_original_fields(row)
    ladder = risk_expression_ladder_payload(row)
    if ladder:
        row["risk_expression_ladder"] = ladder
        row["risk_expression_ladder_tier"] = ladder.get("ladder_tier")
        row["risk_expression_ladder_tier_causes"] = list(
            ladder.get("tier_causes") or []
        )
    if "missed_non_executable_diagnostic_reason" in row:
        _sync_missed_package_order_executable_authority_fields(row)
    # Late missed-row demotion mutates executable aliases. Recompute only after
    # every lifecycle/order diagnostic override has reached its final value.
    _finalize_ultimate_package_effective_executable_authority_fields(
        row,
        demote_final_blocked_claim_aliases=final_serialization_boundary,
    )
    scorecard_window_row = bool(
        str(row.get("candidate_set_id") or "").startswith(
            "timewarp_candidate_set:"
        )
        and "scheduler_packet" in row
        and "candidate_count" in row
    )
    if (
        final_serialization_boundary
        and scorecard_window_row
        and not scorecard_has_final_selected_candidate(row)
    ):
        row.update(scorecard_no_final_selection_candidate_authority_scrub_fields(row))
        _finalize_ultimate_package_effective_executable_authority_fields(
            row,
            demote_final_blocked_claim_aliases=True,
        )
    nonrequired_poi_alias_fields = (
        "package_new_entry_authority_poi_id",
        "package_new_entry_authority_poi_state_hash_sha256",
        "package_new_entry_authority_poi_state_source",
        "selected_package_new_entry_authority_poi_id",
        "selected_package_new_entry_authority_poi_state_hash_sha256",
        "selected_package_new_entry_authority_poi_state_source",
    )
    nonrequired_poi_alias_strip_count = 0
    for authority_surface in (
        row,
        row.get("candidate_decision_inputs"),
        row.get("scheduler_candidate_decision_inputs"),
        row.get("selected_scheduler_candidate_decision_inputs"),
        row.get("selected_scheduler_decision_inputs"),
        row.get("package_new_entry_authority_payload"),
        row.get("selected_package_new_entry_authority_payload"),
    ):
        if not isinstance(authority_surface, dict):
            continue
        explicit_required = any(
            authority_surface.get(field) is True
            for field in (
                "poi_state_required",
                "package_new_entry_authority_poi_state_required",
                "selected_package_new_entry_authority_poi_state_required",
            )
        )
        explicit_nonrequired = any(
            authority_surface.get(field) is False
            for field in (
                "poi_state_required",
                "package_new_entry_authority_poi_state_required",
                "selected_package_new_entry_authority_poi_state_required",
                "package_new_entry_authority_required",
            )
        )
        state_present = any(
            isinstance(authority_surface.get(field), Mapping)
            and bool(authority_surface.get(field))
            for field in (
                "poi_state",
                "package_new_entry_authority_poi_state",
                "selected_package_new_entry_authority_poi_state",
            )
        )
        if not explicit_nonrequired or explicit_required or state_present:
            continue
        for field in nonrequired_poi_alias_fields:
            if authority_surface.get(field) not in (None, ""):
                nonrequired_poi_alias_strip_count += 1
                authority_surface[field] = None
    if nonrequired_poi_alias_strip_count:
        row["package_new_entry_authority_nonrequired_poi_alias_strip_count"] = (
            nonrequired_poi_alias_strip_count
        )
        row["package_new_entry_authority_nonrequired_poi_alias_status"] = (
            "stale_nonrequired_aliases_scrubbed"
        )
    if provisional_marker_strip_count:
        row["package_new_entry_authority_provisional_marker_strip_count"] = (
            prior_provisional_marker_strip_count + provisional_marker_strip_count
        )
        row["package_new_entry_authority_provisional_marker_strip_status"] = (
            "stripped_at_ledger_serialization_boundary"
        )
    return row


GENERIC_PACKAGE_ORDER_EXECUTABLE_MISSING_REASONS = {
    "package_replay_order_executable_authority_missing",
    "missing_package_order_executable_authority",
    "not_order_executable_missed_opportunity",
}


def _package_order_executable_concrete_false_reason(row: Mapping[str, Any]) -> tuple[Any, Any, Any]:
    """Return the most concrete pre-order blocker for false package order authority."""

    scheduler_skip_reason = row.get("scheduler_materialization_skip_reason")
    replay_allowed_reason = row.get("replay_candidate_use_allowed_now_reason")
    package_allowed_reason = row.get("package_replay_executable_candidate_use_allowed_reason")
    risk_reason = first_present(
        row.get("risk_decision_reason"),
        row.get("effective_selector_reason"),
        row.get("selector_reason"),
    )
    if scheduler_skip_reason not in (None, ""):
        return scheduler_skip_reason, "selector_materialization", "scheduler_materialization_skip_reason"
    if replay_allowed_reason not in (None, ""):
        return replay_allowed_reason, "package_authority", "replay_candidate_use_allowed_now_reason"
    if package_allowed_reason not in (None, "") and str(package_allowed_reason) not in GENERIC_PACKAGE_ORDER_EXECUTABLE_MISSING_REASONS:
        return package_allowed_reason, "package_authority", "package_replay_executable_candidate_use_allowed_reason"
    if risk_reason not in (None, "") and str(risk_reason) not in GENERIC_PACKAGE_ORDER_EXECUTABLE_MISSING_REASONS:
        return risk_reason, "risk_finalizer", "risk_or_selector_reason"
    return None, None, None


def _sync_missed_package_order_executable_authority_fields(row: dict[str, Any]) -> None:
    """Mirror final package-order authority into missed-row proof fields."""

    if not isinstance(row, dict):
        return
    order_allowed = first_present(
        row.get("missed_package_replay_order_executable_candidate_use_allowed"),
        row.get("package_replay_order_executable_candidate_use_allowed"),
        row.get(
            "package_new_entry_authority_package_replay_order_executable_candidate_use_allowed"
        ),
        row.get("scorecard_reported_package_replay_order_executable_candidate_use_allowed"),
        row.get("selected_scheduler_package_replay_order_executable_candidate_use_allowed"),
        row.get("scheduler_option_package_replay_order_executable_candidate_use_allowed"),
        row.get("finalizer_primary_probe_package_replay_order_executable_candidate_use_allowed"),
        row.get(
            "risk_finalizer_best_package_probe_package_replay_order_executable_candidate_use_allowed"
        ),
        row.get("risk_finalizer_package_replay_order_executable_candidate_use_allowed"),
    )
    order_reason = first_present(
        row.get("missed_package_replay_order_executable_candidate_use_allowed_reason"),
        row.get("package_replay_order_executable_candidate_use_allowed_reason"),
        row.get(
            "package_new_entry_authority_package_replay_order_executable_candidate_use_allowed_reason"
        ),
        row.get("scorecard_reported_package_replay_order_executable_candidate_use_allowed_reason"),
        row.get("selected_scheduler_package_replay_order_executable_candidate_use_allowed_reason"),
        row.get("scheduler_option_package_replay_order_executable_candidate_use_allowed_reason"),
        row.get("finalizer_primary_probe_package_replay_order_executable_candidate_use_allowed_reason"),
        row.get(
            "risk_finalizer_best_package_probe_package_replay_order_executable_candidate_use_allowed_reason"
        ),
        row.get("risk_finalizer_package_replay_order_executable_candidate_use_allowed_reason"),
    )
    order_source = first_present(
        row.get("missed_package_replay_order_executable_authority_source"),
        row.get("package_replay_order_executable_authority_source"),
        row.get("package_new_entry_authority_package_replay_order_executable_authority_source"),
        row.get("selected_scheduler_package_replay_order_executable_authority_source"),
        row.get("scheduler_option_package_replay_order_executable_authority_source"),
        row.get("risk_finalizer_package_replay_order_executable_authority_source"),
    )
    if order_allowed is None:
        return
    if order_allowed is False:
        blocker_resolution = row.get(
            "package_replay_order_executable_blocker_resolution"
        )
        if isinstance(blocker_resolution, Mapping):
            resolved_reason = blocker_resolution.get("primary_reason")
            resolved_family = blocker_resolution.get("primary_family")
            resolved_source = _named_order_blocker_resolution_source(
                blocker_resolution.get("primary_source")
            )
            if resolved_reason not in (None, ""):
                row["package_replay_order_executable_final_blocker_reason"] = (
                    resolved_reason
                )
                row["package_replay_order_executable_final_blocker_class"] = (
                    resolved_family
                    or _order_executable_blocker_class(resolved_reason)
                )
                row["package_replay_order_executable_final_blocker_source"] = (
                    resolved_source
                    or "package_replay_order_executable_blocker_resolution"
                )
                row["package_replay_order_executable_final_co_blockers"] = list(
                    blocker_resolution.get("co_blockers") or []
                )
        concrete_reason = concrete_class = concrete_source = None
        if str(order_reason or "") in GENERIC_PACKAGE_ORDER_EXECUTABLE_MISSING_REASONS:
            concrete_reason, concrete_class, concrete_source = (
                _package_order_executable_concrete_false_reason(row)
            )
        if concrete_reason not in (None, ""):
            order_reason = concrete_reason
            order_source = concrete_source
            row["package_replay_order_executable_candidate_use_allowed_reason"] = (
                concrete_reason
            )
            row["package_replay_order_executable_final_blocker_reason"] = (
                concrete_reason
            )
            row["package_replay_order_executable_final_blocker_class"] = (
                concrete_class
            )
            row["package_replay_order_executable_final_blocker_source"] = (
                concrete_source
            )
            row.setdefault(
                "package_replay_order_executable_transfer_status",
                "not_order_executable",
            )
        row["missed_opportunity_execution_bound_order_authority"] = False
        row["missed_opportunity_execution_bound_order_authority_missing"] = False
        if row.get("missed_non_executable_diagnostic_reason") in (
            None,
            "",
            "package_replay_order_executable_authority_missing",
            "cost_passed_broker_authority_without_execution_bound_order_path",
        ):
            row["missed_non_executable_diagnostic_reason"] = (
                order_reason or "package_replay_order_executable_authority_false"
            )
        row["missed_package_replay_order_executable_attribution_repaired"] = True
    row["missed_package_replay_order_executable_candidate_use_allowed"] = (
        order_allowed
    )
    if order_reason not in (None, ""):
        row["missed_package_replay_order_executable_candidate_use_allowed_reason"] = (
            order_reason
        )
        if row.get("missed_package_replay_order_executable_final_blocker_reason") in (
            None,
            "",
            "package_replay_order_executable_authority_missing",
        ):
            row["missed_package_replay_order_executable_final_blocker_reason"] = (
                order_reason
            )
    if (
        order_allowed is False
        and row.get("package_replay_order_executable_final_blocker_class")
        not in (None, "")
        and row.get("missed_package_replay_order_executable_final_blocker_class")
        in (None, "", "fill_realism")
    ):
        row["missed_package_replay_order_executable_final_blocker_class"] = row.get(
            "package_replay_order_executable_final_blocker_class"
        )
    if order_source not in (None, ""):
        row["missed_package_replay_order_executable_authority_source"] = order_source
        if row.get("missed_package_replay_order_executable_final_blocker_source") in (
            None,
            "",
            "package_replay_order_executable_candidate_use_allowed",
        ):
            row["missed_package_replay_order_executable_final_blocker_source"] = (
                order_source
            )
    if (
        order_allowed is False
        and row.get("missed_package_replay_order_executable_transfer_status") in (
            None,
            "",
        )
    ):
        row["missed_package_replay_order_executable_transfer_status"] = (
            "not_order_executable"
        )


def _package_new_entry_authority_surface_value(
    surface: Mapping[str, Any],
    key: str,
) -> Any:
    if key in surface:
        return surface.get(key)
    alias = PACKAGE_NEW_ENTRY_AUTHORITY_VALIDATION_KEY_ALIASES.get(key)
    if alias:
        aliases = alias if isinstance(alias, (tuple, list)) else (alias,)
        for alias_key in aliases:
            if alias_key in surface:
                return surface.get(alias_key)
    return None


