def sync_package_order_authority_into_scheduler_decision_inputs(
    row: MutableMapping[str, Any] | None,
    *,
    candidate: Mapping[str, Any] | None = None,
    packets: Mapping[str, Any] | None = None,
    components: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Keep package-order authority identical on row and scheduler inputs."""

    if not isinstance(row, MutableMapping):
        return dict(components) if isinstance(components, Mapping) else {}
    candidate_surface = candidate if isinstance(candidate, Mapping) else {}
    packet_surface = packets if isinstance(packets, Mapping) else {}
    component_surface = components if isinstance(components, Mapping) else {}
    component_inputs = component_surface.get("candidate_decision_inputs")
    component_inputs = component_inputs if isinstance(component_inputs, Mapping) else {}
    scheduler_inputs = row.get("scheduler_candidate_decision_inputs")
    scheduler_inputs = scheduler_inputs if isinstance(scheduler_inputs, Mapping) else {}
    candidate_inputs = row.get("candidate_decision_inputs")
    candidate_inputs = candidate_inputs if isinstance(candidate_inputs, Mapping) else {}
    decision_inputs: dict[str, Any] = dict(component_inputs)
    decision_inputs.update(candidate_inputs)
    decision_inputs.update(scheduler_inputs)

    def present(value: Any) -> bool:
        return value is not None and value != ""

    def copy_value(value: Any) -> Any:
        if isinstance(value, Mapping):
            return dict(value)
        if isinstance(value, list):
            return list(value)
        if isinstance(value, tuple):
            return tuple(value)
        return value

    candidate_truth_surfaces = (
        candidate_surface,
        packet_surface,
        component_inputs,
        component_surface,
        row,
    )
    row_truth_surfaces = (
        row,
        component_inputs,
        component_surface,
        candidate_surface,
        packet_surface,
    )
    signed_attribution_keys = set(PACKAGE_NEW_ENTRY_AUTHORITY_ATTRIBUTION_KEYS)
    signed_authority_object_keys = {
        "ultimate_candidate_package_open_reduced_risk_authority",
        "ultimate_candidate_package_reduce_risk_authority",
        "ultimate_candidate_package_reduced_risk_authority",
    }
    row_has_valid_signed_authority = _runtime_bool(
        row.get("package_new_entry_authority_valid"),
        False,
    )
    for key in ORDER_MATERIALIZATION_PACKAGE_AUTHORITY_COUPLED_KEYS:
        surfaces = (
            row_truth_surfaces
            if key in signed_attribution_keys
            or (row_has_valid_signed_authority and key in signed_authority_object_keys)
            else candidate_truth_surfaces
        )
        for surface in surfaces:
            if not isinstance(surface, Mapping):
                continue
            if key not in surface:
                continue
            value = surface.get(key)
            if present(value):
                copied_value = copy_value(value)
                row[key] = copied_value
                decision_inputs[key] = copy_value(value)
                break

    if _runtime_bool(row.get("package_new_entry_authority_valid"), False):
        for key in (
            "candidate_decision_quality",
            "candidate_decision_quality_field_sources",
            "candidate_decision_quality_source_boundary",
            "candidate_decision_quality_alias_status",
            "candidate_decision_quality_alias_mismatches",
            "candidate_decision_quality_provenance_failures",
            "expected_net_r",
            "candidate_expected_net_r",
            "probability",
            "candidate_probability",
            "confidence",
            "candidate_confidence",
            "scheduler_confidence",
            "fill_probability",
            "candidate_fill_probability",
            "entry_quality_fill_probability",
            "limit_fillability_probability",
            "predecision_limit_fillability_probability",
            "execution_fill_probability",
            "execution_fill_probability_source",
            "execution_fill_probability_source_time_utc",
            "execution_fill_probability_source_boundary",
            "execution_fill_probability_authority_class",
            "execution_fill_probability_authority_hash_sha256",
            "execution_fillability_signed_value_selected",
            "execution_fillability_atomic_surface",
            "execution_fillability_atomic_failure",
            "execution_fillability_atomic_conflicts",
            "source_completeness",
            "source_completeness_status",
            "selected_policy_for_expected_net_r",
            "selected_policy_expected_net_calibration_status",
            "selected_policy_expected_net_calibrated",
            "selected_policy_expected_net_calibration_required",
            "selected_policy_expected_net_calibration_source",
            "selected_policy_expected_net_calibration_source_boundary",
            "selected_policy_expected_net_calibration_hash",
            "pretrade_cost_packet_status",
            "cost_source_gap_status",
            "cost_authority",
            "candidate_cost_r_fallback_is_authority",
            "expected_cost_r",
            "cost_atomic_conflicts",
        ):
            if key in row:
                decision_inputs[key] = copy_value(row.get(key))

    if decision_inputs:
        row["scheduler_candidate_decision_inputs"] = dict(decision_inputs)
        score_components = dict(component_surface)
        row_score_components = row.get("score_components")
        if isinstance(row_score_components, Mapping):
            score_components.update(row_score_components)
        score_components["candidate_decision_inputs"] = dict(decision_inputs)
        row["score_components"] = score_components
        return score_components
    return dict(component_surface)


def package_fill_floor_unresolved_failure_values(
    *surfaces: Mapping[str, Any] | None,
) -> list[str]:
    failures: list[str] = []

    def add(value: Any) -> None:
        for item in _list_text_values(value):
            if item:
                failures.append(item)

    for surface in surfaces:
        if not isinstance(surface, Mapping):
            continue
        for field in (
            "package_fill_floor_unresolved_failures",
            "package_fill_floor_authority_unresolved_failures",
            "scheduler_option_package_fill_floor_authority_unresolved_failures",
            "selected_scheduler_package_fill_floor_authority_unresolved_failures",
            "pre_risk_finalizer_scheduler_option_package_fill_floor_authority_unresolved_failures",
            "risk_finalizer_scheduler_option_package_fill_floor_authority_unresolved_failures",
            "finalizer_primary_probe_scheduler_option_package_fill_floor_authority_unresolved_failures",
            "package_new_entry_authority_package_fill_floor_authority_unresolved_failures",
            "package_risk_expression_fill_floor_unresolved_failures",
            "unresolved_fill_floor_failures",
        ):
            add(surface.get(field))
        for nested_key, nested_fields in (
            (
                "selector_reduce_risk_package_fill_floor_authority",
                ("unresolved_failures", "authority_failures", "failures"),
            ),
            (
                "selector_reduce_risk_package_replay_executable_authority",
                (
                    "fill_floor_unresolved_failures",
                    "package_fill_floor_authority_unresolved_failures",
                ),
            ),
            (
                "risk_expression_ladder",
                (
                    "fill_floor_unresolved_failures",
                    "package_fill_floor_authority_unresolved_failures",
                ),
            ),
        ):
            nested = surface.get(nested_key)
            nested = nested if isinstance(nested, Mapping) else {}
            for field in nested_fields:
                add(nested.get(field))
    return list(dict.fromkeys(failures))


