def order_materialization_authority_candidate_surface(
    *,
    candidate: Mapping[str, Any],
    packets: Mapping[str, Any],
    scheduler_option: Mapping[str, Any] | None,
    risk_authority: Mapping[str, Any] | None,
    config: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Bind selected scheduler authority to the order-materialization guard.

    Scheduler/finalizer probes can carry exact-instance signed package authority
    that is absent from the raw candidate row. Order materialization must
    consume that existing signed authority, not mint new authority and not let a
    stale flattened row fail a selected exact-instance option.
    """

    original_candidate = dict(candidate if isinstance(candidate, Mapping) else {})
    base = dict(original_candidate)
    packets = packets if isinstance(packets, Mapping) else {}
    option = scheduler_option if isinstance(scheduler_option, Mapping) else {}
    risk_authority = risk_authority if isinstance(risk_authority, Mapping) else {}
    components = option.get("score_components")
    components = components if isinstance(components, Mapping) else {}
    component_decision_inputs = components.get("candidate_decision_inputs")
    component_decision_inputs = (
        component_decision_inputs
        if isinstance(component_decision_inputs, Mapping)
        else {}
    )
    component_scheduler_decision_inputs = components.get(
        "scheduler_candidate_decision_inputs"
    )
    component_scheduler_decision_inputs = (
        component_scheduler_decision_inputs
        if isinstance(component_scheduler_decision_inputs, Mapping)
        else {}
    )
    decision_inputs: dict[str, Any] = {}
    for generic_surface in (
        packets.get("candidate_decision_inputs"),
        candidate.get("candidate_decision_inputs"),
        option.get("candidate_decision_inputs"),
        component_decision_inputs,
    ):
        if isinstance(generic_surface, Mapping):
            decision_inputs.update(generic_surface)
    scheduler_decision_inputs: dict[str, Any] = {}
    for scheduler_surface in (
        packets.get("scheduler_candidate_decision_inputs"),
        candidate.get("scheduler_candidate_decision_inputs"),
        component_scheduler_decision_inputs,
        option.get("scheduler_candidate_decision_inputs"),
    ):
        if isinstance(scheduler_surface, Mapping):
            scheduler_decision_inputs.update(scheduler_surface)
    decision_inputs.update(scheduler_decision_inputs)
    signed_new_entry_authority = components.get(
        "selector_reduced_risk_new_position_signed_authority"
    )
    signed_new_entry_authority = (
        signed_new_entry_authority
        if isinstance(signed_new_entry_authority, Mapping)
        else {}
    )
    option_quality = (
        scheduler_option_probe_quality_fields(
            option,
            candidate=base,
            packets=packets,
            config=config,
        )
        if option
        else {}
    )
    for fill_floor_key in (
        "scheduler_option_package_fill_floor_authority_allowed",
        "scheduler_option_package_fill_floor_authority_failures",
        "scheduler_option_package_fill_floor_authority_raw_failures",
        "scheduler_option_package_fill_floor_authority_resolved_failures",
        "scheduler_option_package_fill_floor_authority_unresolved_failures",
    ):
        for fill_floor_surface in (
            option,
            option_quality,
            scheduler_decision_inputs,
            decision_inputs,
            risk_authority,
            original_candidate,
        ):
            if fill_floor_key in fill_floor_surface:
                base[fill_floor_key] = copy.deepcopy(
                    fill_floor_surface[fill_floor_key]
                )
                break
    surfaces = (
        signed_new_entry_authority,
        scheduler_decision_inputs,
        decision_inputs,
        option,
        option_quality,
        risk_authority,
    )
    lifecycle_alias_fields = scheduler_lifecycle_authority_alias_fields(
        decision_inputs,
        option,
        option_quality,
        risk_authority,
        packets,
        original_candidate,
    )
    package_authority_attribution = package_new_entry_authority_attribution_fields(
        original_candidate,
        signed_new_entry_authority,
        scheduler_decision_inputs,
        decision_inputs,
        option,
        option_quality,
        risk_authority,
    )
    package_authority_locked = _runtime_bool(
        package_authority_attribution.get("package_new_entry_authority_valid"),
        False,
    )
    for key in ORDER_MATERIALIZATION_AUTHORITY_OVERRIDE_KEYS:
        if package_authority_locked and key in (
            ORDER_MATERIALIZATION_PACKAGE_AUTHORITY_COUPLED_KEYS
        ):
            continue
        value = first_present(
            *(surface.get(key) for surface in surfaces if isinstance(surface, Mapping))
        )
        if value not in (None, ""):
            base[key] = value
    for key, value in lifecycle_alias_fields.items():
        if value not in (None, "", [], {}):
            base[key] = value
    marketable_route_surface_chain = (
        (risk_authority, "current_runtime_risk_authority"),
        (option_quality, "selected_scheduler_option_quality"),
        (option, "selected_scheduler_option"),
        (scheduler_decision_inputs, "scheduler_candidate_decision_inputs"),
        (decision_inputs, "selected_candidate_decision_inputs"),
        (packets, "candidate_packets"),
        (original_candidate, "original_candidate"),
    )
    selected_marketable_route_surface: Mapping[str, Any] = {}
    selected_marketable_route_source = None
    selected_marketable_route: Mapping[str, Any] = {}
    for route_surface, route_source in marketable_route_surface_chain:
        route_value = route_surface.get(
            "package_marketable_entry_guard_replay_route"
        )
        if isinstance(route_value, Mapping) and route_value:
            selected_marketable_route_surface = route_surface
            selected_marketable_route_source = route_source
            selected_marketable_route = route_value
            break
    if selected_marketable_route:
        base["package_marketable_entry_guard_replay_route"] = copy.deepcopy(
            selected_marketable_route
        )
        base["order_materialization_marketable_route_authority_source"] = (
            selected_marketable_route_source
        )
        atomic_route_values = {
            "package_marketable_entry_guard_replay_route_allowed": first_present(
                selected_marketable_route_surface.get(
                    "package_marketable_entry_guard_replay_route_allowed"
                ),
                selected_marketable_route.get("allowed"),
            ),
            "package_marketable_entry_guard_immediate_marketable_limit_route_allowed": first_present(
                selected_marketable_route_surface.get(
                    "package_marketable_entry_guard_immediate_marketable_limit_route_allowed"
                ),
                selected_marketable_route.get(
                    "immediate_marketable_limit_route_allowed"
                ),
            ),
            "package_marketable_entry_guard_route_allowed": first_present(
                selected_marketable_route_surface.get(
                    "package_marketable_entry_guard_route_allowed"
                ),
                selected_marketable_route.get("allowed"),
            ),
        }
        for key, value in atomic_route_values.items():
            if value not in (None, ""):
                base[key] = copy.deepcopy(value)
    atomic_route_keys = {
        "package_marketable_entry_guard_replay_route",
        "package_marketable_entry_guard_replay_route_allowed",
        "package_marketable_entry_guard_immediate_marketable_limit_route_allowed",
        "package_marketable_entry_guard_route_allowed",
    }
    for key in ORDER_MATERIALIZATION_MARKETABLE_ROUTE_KEYS:
        if key in atomic_route_keys:
            continue
        value = first_present(
            risk_authority.get(key),
            option_quality.get(key),
            option.get(key),
            scheduler_decision_inputs.get(key),
            decision_inputs.get(key),
            packets.get(key),
            original_candidate.get(key),
        )
        if value not in (None, "", [], {}):
            base[key] = copy.deepcopy(value)
    selected_marketable_route_allowed = bool(
        _runtime_bool(
            base.get(
                "package_marketable_entry_guard_immediate_marketable_limit_route_allowed"
            ),
            False,
        )
        and _runtime_bool(
            base.get("package_marketable_entry_guard_route_allowed"),
            False,
        )
        and _runtime_bool(
            first_present(
                selected_marketable_route.get(
                    "immediate_marketable_limit_route_allowed"
                ),
                selected_marketable_route.get("route_allowed"),
                selected_marketable_route.get("allowed"),
            ),
            False,
        )
    )
    selected_marketable_route_session = configured_execution_session_token(
        selected_marketable_route.get("route_session")
    )
    if selected_marketable_route_allowed and selected_marketable_route_session:
        current_applied_session = configured_execution_session_token(
            base.get("route_session_applied")
        )
        if current_applied_session is None:
            base["route_session_applied"] = selected_marketable_route_session
            base[
                "order_materialization_execution_session_projected_from_marketable_route"
            ] = True
            base["order_materialization_execution_session_projection_source"] = (
                "package_marketable_entry_guard_replay_route.route_session"
            )
    execution_session = authority_execution_session_fields(
        base,
        decision_time_utc=first_present(
            base.get("decision_time_utc"),
            base.get("candle_close_utc"),
            option.get("decision_time_utc"),
        ),
    )
    for key, value in execution_session.items():
        if value not in (None, "", [], {}):
            base[key] = copy.deepcopy(value)
    if (
        base.get("route_session_applied") in (None, "")
        and execution_session.get("authority_session") not in (None, "")
        and execution_session.get("authority_session_source")
        != "route_session_fallback"
    ):
        base["route_session_applied"] = execution_session.get(
            "authority_session"
        )
    if package_authority_locked:
        selected_authority_surfaces = (
            original_candidate,
            signed_new_entry_authority,
            option,
            option_quality,
            risk_authority,
            packets,
            scheduler_decision_inputs,
            decision_inputs,
        )

        def selected_authority_pair(
            value_key: str,
            reason_key: str,
        ) -> tuple[Any, Any]:
            seen: list[tuple[Any, Any]] = []
            for surface in selected_authority_surfaces:
                if not isinstance(surface, Mapping):
                    continue
                value = surface.get(value_key)
                reason = surface.get(reason_key)
                if value not in (None, ""):
                    seen.append((value, reason))
            if not seen:
                return None, None
            value, reason = seen[0]
            if (
                value is False
                and explicit_package_false_reason_can_be_rederived(
                    reason,
                    *selected_authority_surfaces,
                )
            ):
                for later_value, later_reason in seen[1:]:
                    if later_value is True:
                        return later_value, later_reason
            return value, reason

        for value_key, reason_key in (
            (
                "package_replay_executable_candidate_use_allowed",
                "package_replay_executable_candidate_use_allowed_reason",
            ),
            (
                "replay_candidate_use_allowed_now",
                "replay_candidate_use_allowed_now_reason",
            ),
        ):
            authority_value, authority_reason = selected_authority_pair(
                value_key,
                reason_key,
            )
            if authority_value not in (None, ""):
                base[value_key] = authority_value
            if authority_reason not in (None, ""):
                base[reason_key] = authority_reason
        signed_order_allowed = package_authority_attribution.get(
            "package_new_entry_authority_package_replay_order_executable_candidate_use_allowed"
        )
        signed_order_reason = package_authority_attribution.get(
            "package_new_entry_authority_package_replay_order_executable_candidate_use_allowed_reason"
        )
        signed_order_source = package_authority_attribution.get(
            "package_new_entry_authority_package_replay_order_executable_authority_source"
        )
        current_order_denial: tuple[Any, Any, Any] | None = None
        for current_surface, current_surface_label, require_current_validity in (
            (
                scheduler_decision_inputs,
                "scheduler_candidate_decision_inputs",
                False,
            ),
            (
                component_scheduler_decision_inputs,
                "score_components.scheduler_candidate_decision_inputs",
                False,
            ),
            (original_candidate, "current_candidate", False),
            (decision_inputs, "selected_candidate_decision_inputs", False),
            (option, "selected_scheduler_option", False),
            (option_quality, "selected_scheduler_option_quality", False),
            (risk_authority, "current_runtime_risk_authority", True),
        ):
            if not isinstance(current_surface, Mapping):
                continue
            if require_current_validity:
                current_signed_status = str(
                    current_surface.get("package_new_entry_authority_status") or ""
                ).strip()
                current_signed_failures = _list_text_values(
                    current_surface.get("package_new_entry_authority_failures")
                )
                if (
                    current_surface.get("package_new_entry_authority_valid") is False
                    or current_signed_failures
                    or current_signed_status
                    not in {"", "valid_signed_predecision_new_entry_authority"}
                ):
                    continue
            current_allowed = current_surface.get(
                "package_replay_order_executable_candidate_use_allowed"
            )
            if current_allowed in (None, "") or _runtime_bool(
                current_allowed,
                True,
            ):
                continue
            current_order_denial = (
                False,
                first_present(
                    current_surface.get(
                        "package_replay_order_executable_candidate_use_allowed_reason"
                    ),
                    "current_order_materialization_authority_denied",
                ),
                first_present(
                    current_surface.get(
                        "package_replay_order_executable_authority_source"
                    ),
                    current_surface_label,
                ),
            )
            break
        signed_order_denied = bool(
            signed_order_allowed not in (None, "")
            and not _runtime_bool(signed_order_allowed, True)
        )
        if signed_order_denied or current_order_denial is None:
            effective_order_allowed = signed_order_allowed
            effective_order_reason = signed_order_reason
            effective_order_source = signed_order_source
        else:
            (
                effective_order_allowed,
                effective_order_reason,
                effective_order_source,
            ) = current_order_denial
            base[
                "order_materialization_current_denial_preserved_over_signed_allow"
            ] = True
        base["package_replay_order_executable_candidate_use_allowed"] = (
            effective_order_allowed
        )
        base["package_replay_order_executable_candidate_use_allowed_reason"] = (
            effective_order_reason
        )
        base["package_replay_order_executable_authority_source"] = (
            effective_order_source
        )
        unresolved_fill_floor_failures = package_fill_floor_unresolved_failure_values(
            base,
            original_candidate,
            option,
            option_quality,
            risk_authority,
            packets,
            decision_inputs,
            signed_new_entry_authority,
        )
        if unresolved_fill_floor_failures:
            unresolved_reason = (
                "package_fill_floor_unresolved_executable_authority:"
                + ",".join(unresolved_fill_floor_failures)
            )
            base["package_fill_floor_authority_unresolved_failures"] = (
                unresolved_fill_floor_failures
            )
            base["scheduler_option_package_fill_floor_authority_unresolved_failures"] = (
                unresolved_fill_floor_failures
            )
            base["package_replay_order_executable_candidate_use_allowed"] = False
            base["package_replay_order_executable_candidate_use_allowed_reason"] = (
                unresolved_reason
            )
            base["package_replay_order_executable_authority_source"] = (
                "scheduler_package_fill_floor_authority"
            )
    if package_authority_locked:
        base.update(package_authority_attribution)
        signed_execution_projection = (
            package_new_entry_authority_execution_projection_fields(
                package_authority_attribution
            )
        )
        if signed_execution_projection:
            base.update(copy.deepcopy(signed_execution_projection))
            base[
                "order_materialization_signed_execution_projection_applied"
            ] = True
        authority_hash = str(
            package_authority_attribution.get("package_new_entry_authority_hash_sha256")
            or ""
        ).strip()
        authority_field = str(
            package_authority_attribution.get("package_new_entry_authority_authority_field")
            or ""
        ).strip()
        if authority_field:
            for surface in (
                original_candidate,
                signed_new_entry_authority,
                decision_inputs,
                option,
                option_quality,
                risk_authority,
            ):
                if not isinstance(surface, Mapping):
                    continue
                surface_attribution = package_new_entry_authority_attribution_fields(surface)
                if not (
                    _runtime_bool(
                        surface_attribution.get("package_new_entry_authority_valid"),
                        False,
                    )
                    and str(
                        surface_attribution.get("package_new_entry_authority_hash_sha256")
                        or ""
                    ).strip()
                    == authority_hash
                ):
                    continue
                authority = surface.get(authority_field)
                if isinstance(authority, Mapping):
                    base[authority_field] = dict(authority)
                    break
        open_authority = base.get("ultimate_candidate_package_open_reduced_risk_authority")
        if isinstance(open_authority, Mapping):
            if open_authority.get("allowed") not in (None, ""):
                base["package_open_reduced_authority_allowed"] = open_authority.get(
                    "allowed"
                )
                base["ultimate_package_open_reduced_authority_allowed"] = (
                    open_authority.get("allowed")
                )
            if open_authority.get("authority_family") not in (None, ""):
                base["package_open_reduced_authority_family"] = open_authority.get(
                    "authority_family"
                )
        reduce_authority = first_present(
            base.get("ultimate_candidate_package_reduce_risk_authority"),
            base.get("ultimate_candidate_package_reduced_risk_authority"),
        )
        if isinstance(reduce_authority, Mapping):
            if reduce_authority.get("allowed") not in (None, ""):
                base["package_reduce_risk_authority_allowed"] = reduce_authority.get(
                    "allowed"
                )
                base["ultimate_package_reduce_risk_authority_allowed"] = (
                    reduce_authority.get("allowed")
                )
            if reduce_authority.get("authority_family") not in (None, ""):
                base["package_reduce_risk_authority_family"] = reduce_authority.get(
                    "authority_family"
                )
    finalizer_selector_action = first_present(
        risk_authority.get("selector_action_for_finalizer"),
        risk_authority.get("scheduler_materialization_selector_action"),
        risk_authority.get("effective_selector_action"),
        risk_authority.get("selector_action"),
    )
    if finalizer_selector_action not in (None, ""):
        finalizer_selector_reason = first_present(
            risk_authority.get("scheduler_materialization_selector_reason"),
            risk_authority.get("effective_selector_reason"),
            risk_authority.get("selector_reason_for_finalizer"),
            risk_authority.get("selector_reason"),
            effective_selector_reason_for_authority(
                base,
                {**dict(packets), **dict(option_quality)},
                packets.get("selector_packet")
                if isinstance(packets.get("selector_packet"), Mapping)
                else {},
            ),
        )
        normalized_finalizer_selector_action = normalize_selector_action_for_reason(
            finalizer_selector_action,
            str(finalizer_selector_reason or "").strip(),
        )
        if normalized_finalizer_selector_action not in (None, ""):
            original_selector_action = first_present(
                base.get("selector_action_origin"),
                base.get("selector_action"),
            )
            if (
                original_selector_action not in (None, "")
                and original_selector_action != normalized_finalizer_selector_action
            ):
                base["selector_action_origin"] = original_selector_action
                base["selector_action_materialized_from_scheduler"] = True
            base["scheduler_materialization_selector_action"] = (
                normalized_finalizer_selector_action
            )
            base["effective_selector_action"] = normalized_finalizer_selector_action
        if finalizer_selector_reason not in (None, ""):
            original_selector_reason = first_present(
                base.get("selector_reason_origin"),
                base.get("selector_reason"),
            )
            if (
                original_selector_reason not in (None, "")
                and original_selector_reason != finalizer_selector_reason
            ):
                base["selector_reason_origin"] = original_selector_reason
            base["scheduler_materialization_selector_reason"] = (
                finalizer_selector_reason
            )
            base["effective_selector_reason"] = finalizer_selector_reason
    materialized_action = normalize_scheduler_action_intent(
        first_present(
            lifecycle_alias_fields.get("scheduler_materialization_action_intent"),
            base.get("scheduler_materialization_action_intent"),
            option.get("scheduler_materialization_action_intent"),
            decision_inputs.get("scheduler_materialization_action_intent"),
            option.get("effective_action_intent"),
            decision_inputs.get("effective_action_intent"),
            option.get("action_class"),
        )
    )
    if materialized_action:
        action = materialized_action
        if action:
            for key in (
                "scheduler_materialization_action_intent",
                "action_intent",
                "lifecycle_action",
                "same_symbol_lifecycle_action",
                "gtos_vnext_same_symbol_lifecycle_action",
            ):
                base[key] = action
    selector_packet = packets.get("selector_packet")
    selector_packet = selector_packet if isinstance(selector_packet, Mapping) else {}
    selected_selector_reason = effective_selector_reason_for_authority(
        base,
        {**dict(packets), **dict(option_quality)},
        selector_packet,
    )
    selected_selector_action = normalize_selector_action_for_reason(
        first_present(
            base.get("scheduler_materialization_selector_action"),
            base.get("selector_action"),
            option.get("selector_action"),
            option_quality.get("selector_action"),
            selector_packet.get("action"),
        ),
        selected_selector_reason,
    )
    selected_action_intent = normalize_scheduler_action_intent(
        first_present(
            base.get("scheduler_materialization_action_intent"),
            base.get("action_intent"),
            base.get("lifecycle_action"),
            option.get("action_class"),
        )
    )
    if (
        base.get("replay_candidate_use_allowed_now") in (None, "")
        and _runtime_bool(
            base.get("package_replay_executable_candidate_use_allowed"),
            False,
        )
        and selected_selector_action in RISK_BEARING_SELECTOR_ACTIONS
        and selected_action_intent in SCHEDULER_ACTION_INTENTS
    ):
        base["replay_candidate_use_allowed_now"] = True
        base["replay_candidate_use_allowed_now_reason"] = first_present(
            base.get("package_replay_executable_candidate_use_allowed_reason"),
            "selected_scheduler_order_materialization_authority_executable",
        )
    for key in ORDER_MATERIALIZATION_AUTHORITY_FILL_KEYS:
        if base.get(key) not in (None, ""):
            continue
        value = first_present(
            *(surface.get(key) for surface in surfaces if isinstance(surface, Mapping))
        )
        if value not in (None, ""):
            base[key] = value
    return base


def same_symbol_replay_exposure_ledger_fields(
    *surfaces: Mapping[str, Any] | None,
    synthesize_empty: bool = True,
) -> dict[str, Any]:
    """Preserve predecision same-symbol exposure context across replay ledgers."""

    lifecycle_alias_fields = scheduler_lifecycle_authority_alias_fields(*surfaces)
    context: Any = None
    context_source: str | None = None
    risk_pct: Any = None
    searched: list[tuple[str, Mapping[str, Any]]] = []
    for index, surface in enumerate(surfaces):
        if not isinstance(surface, Mapping):
            continue
        searched.append((f"surface_{index}", surface))
        for key in (
            "selected_scheduler_same_symbol_replay_exposure_context",
            "pre_risk_finalizer_same_symbol_replay_exposure_context",
        ):
            value = surface.get(key)
            if isinstance(value, Mapping):
                searched.append((f"surface_{index}.{key}", value))
        components = surface.get("score_components")
        if isinstance(components, Mapping):
            searched.append((f"surface_{index}.score_components", components))
            decision_inputs = components.get("candidate_decision_inputs")
            if isinstance(decision_inputs, Mapping):
                searched.append(
                    (
                        f"surface_{index}.score_components.candidate_decision_inputs",
                        decision_inputs,
                    )
                )
    for source, surface in searched:
        if context in (None, "", {}, []):
            value = first_present(
                surface.get("same_symbol_replay_exposure_context"),
                surface.get("selected_scheduler_same_symbol_replay_exposure_context"),
                surface.get("pre_risk_finalizer_same_symbol_replay_exposure_context"),
            )
            if value not in (None, "", {}, []):
                context = dict(value) if isinstance(value, Mapping) else value
                context_source = source
        if risk_pct in (None, ""):
            value = surface.get("same_symbol_lifecycle_exposure_risk_pct")
            if value not in (None, ""):
                risk_pct = value
    context_status = "source_observed" if isinstance(context, Mapping) else "missing"
    context_synthesized = False
    if not isinstance(context, Mapping) and synthesize_empty:
        symbol = first_present(
            *(surface.get("symbol") for surface in surfaces if isinstance(surface, Mapping))
        )
        side = first_present(
            *(
                surface.get("side") or surface.get("direction")
                for surface in surfaces
                if isinstance(surface, Mapping)
            )
        )
        if symbol not in (None, "") or side not in (None, ""):
            context = {
                "symbol": symbol,
                "side": side,
                "same_side_open_count": 0,
                "same_side_open_ids": [],
                "same_side_open_risk_pct": 0.0,
                "same_side_pending_count": 0,
                "same_side_pending_ids": [],
                "same_side_pending_order_ids": [],
                "same_side_pending_risk_pct": 0.0,
                "opposite_open_count": 0,
                "opposite_open_ids": [],
                "opposite_open_risk_pct": 0.0,
                "opposite_pending_count": 0,
                "opposite_pending_ids": [],
                "opposite_pending_order_ids": [],
                "opposite_pending_risk_pct": 0.0,
            }
            context_status = "synthesized_empty_no_same_symbol_exposure_source"
            context_source = "canonical_replay_context_envelope_synthesized_empty"
            context_synthesized = True
    selected_context = first_present(
        lifecycle_alias_fields.get("same_symbol_replay_exposure_context"),
        context,
    )
    def first_surface_field(*keys: str) -> Any:
        return first_present(
            *(
                surface.get(key)
                for surface in surfaces
                if isinstance(surface, Mapping)
                for key in keys
            )
        )

    envelope = {
        "candidate_id": first_surface_field("candidate_id", "selected_candidate_id"),
        "decision_time_utc": first_surface_field(
            "decision_time_utc",
            "asof_utc",
            "candle_close_utc",
            "source_candle_time_utc",
        ),
        "canonical_replay_candidate_instance_key": first_surface_field(
            "canonical_replay_candidate_instance_key",
            "risk_finalizer_probe_instance_key",
            "source_bound_replay_candidate_instance_key",
        ),
        "symbol": first_surface_field("symbol", "instrument"),
        "side": first_surface_field("side", "direction"),
        "timeframe": first_surface_field(
            "timeframe",
            "market_timeframe",
            "decision_timeframe",
            "source_timeframe",
        ),
        "session_bucket": first_surface_field(
            "session_bucket",
            "session",
            "route_session",
        ),
        "same_symbol_replay_exposure_context": selected_context,
        "same_symbol_replay_exposure_context_status": context_status,
        "same_symbol_replay_exposure_context_source": context_source,
        "source_boundary": first_surface_field(
            "canonical_replay_context_source_boundary",
            "source_boundary",
            "candidate_decision_quality_source_boundary",
        ),
        "uses_outcome_fields": False,
    }
    envelope = {
        key: value
        for key, value in envelope.items()
        if value not in (None, "", [], {})
    }
    envelope_hash = stable_sha256(envelope) if envelope else None
    return {
        "same_symbol_replay_exposure_context": selected_context,
        "same_symbol_replay_exposure_context_source": context_source,
        "same_symbol_replay_exposure_context_status": context_status,
        "same_symbol_replay_exposure_context_synthesized_empty": context_synthesized,
        "canonical_replay_context_envelope": envelope if envelope else None,
        "canonical_replay_context_envelope_hash_sha256": envelope_hash,
        "canonical_replay_context_envelope_shape_hash_sha256": (
            stable_sha256(sorted(envelope.keys())) if envelope else None
        ),
        "canonical_replay_context_source_boundary": first_surface_field(
            "canonical_replay_context_source_boundary",
            "source_boundary",
            "candidate_decision_quality_source_boundary",
        ),
        "canonical_replay_context_projection_status": (
            "materialized" if envelope else "missing_context_envelope_inputs"
        ),
        "same_symbol_lifecycle_exposure_risk_pct": first_present(
            lifecycle_alias_fields.get("same_symbol_lifecycle_exposure_risk_pct"),
            risk_pct,
        ),
        "same_side_pending_ids": lifecycle_alias_fields.get("same_side_pending_ids"),
        "same_side_pending_order_ids": lifecycle_alias_fields.get(
            "same_side_pending_order_ids"
        ),
        "opposite_pending_ids": lifecycle_alias_fields.get("opposite_pending_ids"),
        "opposite_pending_order_ids": lifecycle_alias_fields.get(
            "opposite_pending_order_ids"
        ),
        "same_side_pending_risk_pct": lifecycle_alias_fields.get(
            "same_side_pending_risk_pct"
        ),
        "opposite_pending_risk_pct": lifecycle_alias_fields.get(
            "opposite_pending_risk_pct"
        ),
    }


def scheduler_replacement_reallocation_quality_ledger_fields(
    *surfaces: Mapping[str, Any] | None,
) -> dict[str, Any]:
    """Project scheduler replacement/reallocation quality onto replay ledgers."""

    searched: list[Mapping[str, Any]] = []
    for surface in surfaces:
        if not isinstance(surface, Mapping):
            continue
        searched.append(surface)
        components = surface.get("score_components")
        if isinstance(components, Mapping):
            searched.append(components)
            for key in (
                "candidate_decision_inputs",
                "scheduler_candidate_decision_inputs",
                "decision_inputs",
            ):
                nested = components.get(key)
                if isinstance(nested, Mapping):
                    searched.append(nested)
        for key in (
            "candidate_decision_inputs",
            "scheduler_candidate_decision_inputs",
            "decision_inputs",
        ):
            nested = surface.get(key)
            if isinstance(nested, Mapping):
                searched.append(nested)

    diagnostic: Mapping[str, Any] | None = None
    for surface in searched:
        raw = surface.get("replacement_reallocation_quality")
        if isinstance(raw, Mapping):
            diagnostic = raw
            break
    package_displacement_quality: Mapping[str, Any] | None = None
    for surface in searched:
        raw = surface.get("package_displacement_quality")
        if isinstance(raw, Mapping):
            package_displacement_quality = raw
            break
    pending_replacement: Mapping[str, Any] | None = None
    for surface in searched:
        raw = surface.get("pending_replacement_diagnostic")
        if isinstance(raw, Mapping):
            pending_replacement = raw
            break
    out: dict[str, Any] = {}
    if isinstance(diagnostic, Mapping):
        out["replacement_reallocation_quality"] = dict(diagnostic)
    if isinstance(package_displacement_quality, Mapping):
        out["package_displacement_quality"] = dict(package_displacement_quality)
    def first_field(*keys: str) -> Any:
        return first_present(
            *(surface.get(key) for key in keys for surface in searched)
        )

    score = first_present(
        first_field("replacement_reallocation_quality_score"),
        first_field("risk_admitted_scheduler_reallocation_score"),
        diagnostic.get("score") if isinstance(diagnostic, Mapping) else None,
        diagnostic.get("risk_admitted_scheduler_reallocation_score")
        if isinstance(diagnostic, Mapping)
        else None,
    )
    if score not in (None, ""):
        out["replacement_reallocation_quality_score"] = score
        out["risk_admitted_scheduler_reallocation_score"] = score
    eligible = first_present(
        first_field(
            "replacement_reallocation_quality_eligible",
            "risk_admitted_scheduler_reallocation_eligible",
        ),
        diagnostic.get("eligible_for_reallocation_promotion")
        if isinstance(diagnostic, Mapping)
        else None,
        diagnostic.get("risk_admitted_scheduler_reallocation_eligible")
        if isinstance(diagnostic, Mapping)
        else None,
    )
    if eligible not in (None, ""):
        out["replacement_reallocation_quality_eligible"] = eligible
        out["risk_admitted_scheduler_reallocation_eligible"] = eligible
    hard_failures = first_present(
        first_field(
            "replacement_reallocation_quality_hard_gate_failures",
            "risk_admitted_scheduler_reallocation_hard_failures",
        ),
        diagnostic.get("hard_gate_failures") if isinstance(diagnostic, Mapping) else None,
        diagnostic.get("risk_admitted_scheduler_reallocation_hard_failures")
        if isinstance(diagnostic, Mapping)
        else None,
    )
    if hard_failures not in (None, ""):
        normalized_hard_failures = list(
            hard_failures if isinstance(hard_failures, (list, tuple, set)) else [hard_failures]
        )
        out["replacement_reallocation_quality_hard_gate_failures"] = normalized_hard_failures
        out["risk_admitted_scheduler_reallocation_hard_failures"] = (
            normalized_hard_failures
        )
    for target_key, diagnostic_key in (
        ("replacement_release_quality_score", "replacement_release_quality_score"),
        ("replacement_release_bonus", "replacement_release_bonus"),
        ("replacement_reallocation_base_expected_transfer_score", "base_expected_transfer_score"),
        (
            "replacement_reallocation_risk_cap_adjusted_expected_transfer_score",
            "risk_cap_adjusted_expected_transfer_score",
        ),
        ("replacement_reallocation_stop_hazard_status", "stop_hazard_status"),
        ("replacement_reallocation_stop_hazard_quality_penalty", "stop_hazard_quality_penalty"),
        (
            "replacement_reallocation_guard_penalty_reasons",
            "guard_penalty_reasons",
        ),
        (
            "replacement_reallocation_raw_hard_gate_failures",
            "raw_hard_gate_failures",
        ),
        (
            "replacement_reallocation_soft_guard_allowed",
            "soft_guard_reallocation_allowed",
        ),
        ("replacement_reallocation_usable_release_candidate_count", "usable_release_candidate_count"),
        ("replacement_reallocation_selected_release_pending_id", "selected_release_pending_id"),
        ("replacement_reallocation_selected_release_reason", "selected_release_reason"),
        ("replacement_reallocation_used_pending_id_count", "used_pending_id_count"),
        ("replacement_reallocation_quality_source_boundary", "source_boundary"),
        ("replacement_reallocation_quality_uses_outcome_fields", "uses_outcome_fields"),
    ):
        value = first_present(
            first_field(target_key),
            diagnostic.get(diagnostic_key) if isinstance(diagnostic, Mapping) else None,
            first_field(diagnostic_key),
        )
        if value not in (None, ""):
            out[target_key] = value
    if isinstance(diagnostic, Mapping) and "raw_hard_gate_failures" in diagnostic:
        raw_hard_failures = diagnostic.get("raw_hard_gate_failures")
        out["replacement_reallocation_raw_hard_gate_failures"] = [
            str(item)
            for item in (
                raw_hard_failures
                if isinstance(raw_hard_failures, (list, tuple, set))
                else [raw_hard_failures]
            )
            if item not in (None, "")
        ]
    if isinstance(pending_replacement, Mapping):
        release_candidates = pending_replacement.get("release_candidates")
        if isinstance(release_candidates, Sequence) and not isinstance(
            release_candidates,
            (str, bytes, bytearray),
        ):
            out["pending_replacement_release_candidate_count"] = len(
                [row for row in release_candidates if isinstance(row, Mapping)]
            )
    if out:
        out.setdefault("replacement_reallocation_quality_projection_status", "materialized")
    return out


def selected_scheduler_replacement_reallocation_quality_ledger_fields(
    *surfaces: Mapping[str, Any] | None,
) -> dict[str, Any]:
    """Expose selected-scheduler replacement quality without changing authority."""

    return {
        f"selected_scheduler_{key}": value
        for key, value in scheduler_replacement_reallocation_quality_ledger_fields(
            *surfaces
        ).items()
    }


def scheduler_replay_truth_projection_fields(
    *surfaces: Mapping[str, Any] | None,
    selected_scheduler_alias: bool = False,
    synthesize_empty_context: bool = True,
) -> dict[str, Any]:
    """Project canonical replay context and replacement quality onto ledger rows."""

    out = same_symbol_replay_exposure_ledger_fields(
        *surfaces,
        synthesize_empty=synthesize_empty_context,
    )
    replacement_fields = scheduler_replacement_reallocation_quality_ledger_fields(
        *surfaces
    )
    out.update(replacement_fields)
    if selected_scheduler_alias and replacement_fields:
        out.update(
            {
                f"selected_scheduler_{key}": value
                for key, value in replacement_fields.items()
            }
        )
    return out


