def signed_soft_transfer_displacement_trace_fields(
    surface: Mapping[str, Any] | None,
) -> dict[str, Any]:
    """Carry signed soft-transfer proof without widening replay authority."""

    surface = surface if isinstance(surface, Mapping) else {}
    out: dict[str, Any] = {}
    list_proof_keys = {
        "risk_finalizer_signed_soft_transfer_displacement_failures",
        "risk_finalizer_signed_soft_transfer_displacement_soft_reason_tokens",
    }
    for key in SIGNED_SOFT_TRANSFER_DISPLACEMENT_TRACE_KEYS:
        if key not in surface:
            continue
        value = surface.get(key)
        if key in list_proof_keys:
            out[key] = list(value or [])
            continue
        if value not in (None, "", [], {}):
            out[key] = value
    return out


