def risk_expression_proof_fields_from_surfaces(
    *surfaces: Mapping[str, Any] | None,
    prefix: str = "",
) -> dict[str, Any]:
    out: dict[str, Any] = {}
    expanded_surfaces: list[Mapping[str, Any]] = []
    for surface in surfaces:
        if not isinstance(surface, Mapping):
            continue
        expanded_surfaces.append(surface)
        nested_risk_authority = surface.get("risk_authority")
        if isinstance(nested_risk_authority, Mapping):
            expanded_surfaces.append(nested_risk_authority)
    for key in RISK_EXPRESSION_PROOF_LEDGER_KEYS:
        if key == "package_risk_expression_execution_fill_probability":
            value, _fill_source, _fill_authority = (
                source_bound_execution_fill_probability_with_source(
                    *expanded_surfaces
                )
            )
        else:
            value = first_present(*(surface.get(key) for surface in expanded_surfaces))
        if value in (None, ""):
            for surface in expanded_surfaces:
                ladder = risk_expression_ladder_payload(surface)
                if not ladder:
                    continue
                tier = _canonical_risk_expression_tier(ladder.get("ladder_tier"))
                tier_causes = _list_text_values(ladder.get("tier_causes"))
                if key == "risk_expression_ladder":
                    value = ladder
                elif key == "risk_expression_ladder_tier":
                    value = tier or ladder.get("ladder_tier")
                elif key == "risk_expression_ladder_tier_causes":
                    value = tier_causes
                elif key == "package_risk_expression_ladder":
                    value = tier or ladder.get("ladder_tier")
                elif key == "package_risk_expression_full_risk_allowed":
                    value = tier == "full"
                elif key == "package_risk_expression_full_risk_applied":
                    value = tier == "full"
                elif key == "package_risk_expression_full_risk_pre_control_allowed":
                    value = tier == "full"
                elif key == "package_risk_expression_full_risk_pre_control_applied":
                    value = tier == "full"
                elif key == "package_risk_expression_full_risk_failures":
                    value = [] if tier == "full" else tier_causes
                elif key == "package_risk_expression_signed_authority_valid":
                    value = first_present(
                        ladder.get("signed_authority_valid"),
                        surface.get("package_new_entry_authority_valid"),
                        surface.get("package_new_entry_authority_status")
                        in {
                            "valid",
                            "valid_package_new_entry_authority",
                            "valid_signed_predecision_new_entry_authority",
                        },
                    )
                elif key == "full_risk_allowed":
                    value = tier == "full"
                elif key == "full_risk_applied":
                    value = tier == "full"
                elif key == "full_risk_pre_control_allowed":
                    value = tier == "full"
                elif key == "full_risk_pre_control_applied":
                    value = tier == "full"
                elif key == "full_risk_failures":
                    value = [] if tier == "full" else tier_causes
                elif key == "package_risk_expression_expected_net_r":
                    value = first_present(
                        surface.get("expected_net_r"),
                        surface.get("candidate_expected_net_r"),
                    )
                elif key == "package_risk_expression_probability":
                    value = first_present(
                        surface.get("probability"),
                        surface.get("candidate_probability"),
                    )
                elif key == "package_risk_expression_execution_fill_probability":
                    value, _fill_source, _fill_authority = (
                        source_bound_execution_fill_probability_with_source(surface)
                    )
                elif (
                    key
                    == "package_risk_expression_execution_fill_probability_full_risk_floor"
                ):
                    value = first_present(
                        ladder.get("execution_fill_probability_full_risk_floor"),
                        ladder.get("fill_probability_full_risk_floor"),
                        surface.get(
                            "package_risk_expression_execution_fill_probability_full_risk_floor"
                        ),
                        surface.get(
                            "risk_expression_ladder_execution_fill_probability_full_risk_floor"
                        ),
                    )
                elif (
                    key
                    == "package_risk_expression_raw_execution_fillability_below_full_risk_floor"
                ):
                    value = first_present(
                        ladder.get("raw_execution_fillability_below_full_risk_floor"),
                        surface.get(
                            "package_risk_expression_raw_execution_fillability_below_full_risk_floor"
                        ),
                    )
                elif (
                    key
                    == "package_risk_expression_fill_floor_route_resolved_for_full_risk"
                ):
                    value = first_present(
                        ladder.get("fill_floor_route_resolved_for_full_risk"),
                        surface.get(
                            "package_risk_expression_fill_floor_route_resolved_for_full_risk"
                        ),
                    )
                elif (
                    key
                    == "package_risk_expression_route_resolution_full_risk_bypass_allowed"
                ):
                    value = first_present(
                        ladder.get("route_resolution_full_risk_bypass_allowed"),
                        surface.get(
                            "package_risk_expression_route_resolution_full_risk_bypass_allowed"
                        ),
                    )
                elif key == "package_risk_expression_fill_floor_resolved":
                    value = first_present(
                        ladder.get("fill_floor_resolved"),
                        ladder.get("fill_floor_resolved_or_empty"),
                        surface.get("package_risk_expression_fill_floor_resolved"),
                        surface.get("fill_floor_resolved"),
                    )
                elif key == "package_risk_expression_fill_floor_authority_allowed":
                    value = first_present(
                        ladder.get("fill_floor_authority_allowed"),
                        surface.get(
                            "package_risk_expression_fill_floor_authority_allowed"
                        ),
                        surface.get("package_fill_floor_authority_allowed"),
                    )
                elif (
                    key
                    == "package_risk_expression_fill_floor_unresolved_failures"
                ):
                    value = first_present(
                        ladder.get("unresolved_fill_floor_failures"),
                        surface.get(
                            "package_risk_expression_fill_floor_unresolved_failures"
                        ),
                        surface.get("package_fill_floor_unresolved_failures"),
                    )
                elif key == "package_risk_expression_source_completeness":
                    value = surface.get("source_completeness")
                elif key == "package_risk_expression_scheduler_rank":
                    value = first_present(
                        ladder.get("scheduler_rank"),
                        ladder.get("package_risk_expression_scheduler_rank"),
                        surface.get("scheduler_rank"),
                        surface.get("rank"),
                    )
                elif key == "package_risk_expression_scheduler_rank_source":
                    value = first_present(
                        ladder.get("scheduler_rank_source"),
                        ladder.get("package_risk_expression_scheduler_rank_source"),
                        surface.get("scheduler_rank_source"),
                    )
                elif key == "package_risk_expression_finalizer_selected_rank":
                    value = first_present(
                        ladder.get("finalizer_selected_rank"),
                        ladder.get("package_risk_expression_finalizer_selected_rank"),
                        surface.get("risk_finalizer_selected_rank"),
                    )
                elif key == "package_risk_expression_finalizer_transfer_rank":
                    value = first_present(
                        ladder.get("finalizer_transfer_rank"),
                        ladder.get("package_risk_expression_finalizer_transfer_rank"),
                        surface.get("risk_finalizer_transfer_rank"),
                    )
                elif key == "package_risk_expression_original_scheduler_rank":
                    value = first_present(
                        ladder.get("original_scheduler_rank"),
                        ladder.get("package_risk_expression_original_scheduler_rank"),
                        surface.get("scheduler_original_preserved_rank"),
                        surface.get("scheduler_preserved_rank"),
                    )
                elif key == "package_risk_expression_finalizer_rank_override_allowed":
                    value = first_present(
                        ladder.get("finalizer_rank_override_allowed"),
                        ladder.get(
                            "package_risk_expression_finalizer_rank_override_allowed"
                        ),
                        surface.get("risk_finalizer_transfer_dominates_original_allowed"),
                    )
                elif (
                    key
                    == "package_risk_expression_finalizer_rank_override_block_reason"
                ):
                    value = first_present(
                        ladder.get("finalizer_rank_override_block_reason"),
                        ladder.get(
                            "package_risk_expression_finalizer_rank_override_block_reason"
                        ),
                    )
                elif key == "risk_pct_basis":
                    value = first_present(
                        surface.get("risk_pct_basis"),
                        surface.get("risk_reduction_basis_pct"),
                    )
                elif key == "risk_pct_basis_source":
                    value = first_present(
                        surface.get("risk_pct_basis_source"),
                        "risk_reduction_basis_pct",
                    )
                elif key == "risk_pct_final_source":
                    value = surface.get("risk_pct_final_source")
                elif key == "risk_pct_provenance":
                    value = surface.get("risk_pct_provenance")
                if value not in (None, ""):
                    break
        if isinstance(value, tuple):
            value = list(value)
        if key in {
            "risk_expression_ladder_tier_causes",
            "package_risk_expression_full_risk_failures",
            "package_risk_expression_fill_floor_unresolved_failures",
            "full_risk_failures",
        } and isinstance(value, Sequence) and not isinstance(
            value,
            (str, bytes, bytearray),
        ):
            value = list(value)
        if value not in (None, ""):
            out[f"{prefix}{key}"] = value
    return out


def runtime_risk_public_authority_fields(
    surface: Mapping[str, Any] | None,
) -> dict[str, Any]:
    """Bind public final-risk fields to executable runtime risk authority."""

    surface = surface if isinstance(surface, Mapping) else {}
    risk_authority = surface.get("risk_authority")
    risk_authority = risk_authority if isinstance(risk_authority, Mapping) else {}
    atom = first_present(
        risk_authority.get("canonical_executable_final_risk_atom"),
        surface.get("canonical_executable_final_risk_atom"),
    )
    atom = atom if isinstance(atom, Mapping) else {}
    atom_hash = str(atom.get("atom_hash_sha256") or "").strip()
    atom_hash_payload = dict(atom)
    atom_hash_payload.pop("atom_hash_sha256", None)
    atom_valid = bool(
        atom.get("schema_version") == CANONICAL_EXECUTABLE_FINAL_RISK_ATOM_SCHEMA
        and is_sha256(atom_hash)
        and stable_sha256(atom_hash_payload) == atom_hash
        and math.isfinite(safe_float(atom.get("final_risk_pct"), math.nan))
    )
    decision = str(
        first_present(
            risk_authority.get("risk_decision"),
            surface.get("risk_decision"),
        )
        or ""
    ).strip()
    nested_values = {
        key: safe_float(risk_authority.get(key), math.nan)
        for key in CANONICAL_EXECUTABLE_FINAL_RISK_TRIO
    }
    finite_nested_values = {
        key: value
        for key, value in nested_values.items()
        if math.isfinite(value)
    }
    source = ""
    runtime_final = None
    if atom_valid:
        runtime_final = atom.get("final_risk_pct")
        source = "canonical_executable_final_risk_atom"
    elif (
        decision in {"trade", "reduce-risk", "open-reduced-risk"}
        and nested_values["runtime_final_risk_pct"] > 0.0
    ):
        runtime_final = risk_authority.get("runtime_final_risk_pct")
        source = "nested_runtime_final_risk_pct"
    elif (
        decision in {"trade", "reduce-risk", "open-reduced-risk"}
        and nested_values["final_approved_risk_pct"] > 0.0
    ):
        runtime_final = risk_authority.get("final_approved_risk_pct")
        source = "legacy_nested_executable_final_approved_risk_pct"
    elif risk_authority.get("runtime_final_risk_pct") not in (None, ""):
        runtime_final = risk_authority.get("runtime_final_risk_pct")
        source = "nested_runtime_final_risk_pct"
    elif risk_authority.get("final_approved_risk_pct") not in (None, ""):
        runtime_final = risk_authority.get("final_approved_risk_pct")
        source = "nested_final_approved_risk_pct"
    elif surface.get("final_approved_risk_pct") not in (None, ""):
        runtime_final = surface.get("final_approved_risk_pct")
        source = "row_final_approved_risk_pct"
    elif surface.get("runtime_final_risk_pct") not in (None, ""):
        runtime_final = surface.get("runtime_final_risk_pct")
        source = "row_runtime_final_risk_pct"

    runtime_final_pct = safe_float(runtime_final, math.nan)
    if not math.isfinite(runtime_final_pct):
        return {}

    runtime_final_pct = round(max(0.0, runtime_final_pct), 12)
    existing_final = surface.get("final_approved_risk_pct")
    existing_final_pct = safe_float(existing_final, math.nan)
    repaired = bool(
        math.isfinite(existing_final_pct)
        and abs(existing_final_pct - runtime_final_pct) > 1e-12
    )
    conflicting_nested_fields = sorted(
        key
        for key, value in finite_nested_values.items()
        if abs(value - runtime_final_pct) > 1e-12
    )
    out: dict[str, Any] = {
        "final_approved_risk_pct": runtime_final_pct,
        "approved_risk_pct": runtime_final_pct,
        "runtime_final_risk_pct": runtime_final_pct,
        "risk_authority_public_final_risk_pct_source": source,
        "risk_authority_public_final_risk_pct_repaired": repaired,
        "risk_authority_public_final_risk_atom_present": bool(atom),
        "risk_authority_public_final_risk_atom_valid": atom_valid,
        "risk_authority_public_final_risk_pct_conflict": bool(
            conflicting_nested_fields
        ),
        "risk_authority_public_final_risk_pct_conflicting_nested_fields": (
            conflicting_nested_fields
        ),
    }
    if atom:
        out["canonical_executable_final_risk_atom"] = dict(atom)
        out["canonical_executable_final_risk_atom_hash_sha256"] = atom_hash or None
    if repaired:
        out["risk_authority_public_final_risk_pct_original"] = existing_final
    return out


def full_risk_counterfactual_ledger_fields(
    risk_authority: Mapping[str, Any] | None,
    *,
    risk_cash: float,
    net_proxy_r: float,
) -> dict[str, Any]:
    risk_authority = risk_authority if isinstance(risk_authority, Mapping) else {}
    basis_pct = safe_float(risk_authority.get("risk_reduction_basis_pct"), 0.0)
    actual_pct = safe_float(
        first_present(
            risk_authority.get("runtime_final_risk_pct"),
            risk_authority.get("final_approved_risk_pct"),
        ),
        0.0,
    )
    factor = risk_authority.get("risk_reduction_factor")
    try:
        factor_value = float(factor)
    except (TypeError, ValueError):
        factor_value = (actual_pct / basis_pct) if basis_pct > 0.0 else 0.0
    applicable = bool(
        risk_cash > 0.0
        and basis_pct > 0.0
        and actual_pct > 0.0
        and actual_pct < basis_pct
        and factor_value > 0.0
    )
    full_risk_cash = round(risk_cash / factor_value, 8) if applicable else risk_cash
    full_pnl_cash = round(full_risk_cash * net_proxy_r, 8)
    return {
        "full_risk_counterfactual_applicable": applicable,
        "full_risk_counterfactual_authority": (
            "replay_diagnostic_same_path_scaled_to_risk_reduction_basis_no_broker_authority"
        ),
        "full_risk_counterfactual_live_broker_authority": False,
        "full_risk_counterfactual_final_selection_claim": False,
        "full_risk_counterfactual_risk_pct": round(basis_pct, 12) if applicable else actual_pct,
        "full_risk_counterfactual_actual_risk_pct": actual_pct,
        "full_risk_counterfactual_risk_reduction_factor": round(factor_value, 12),
        "full_risk_counterfactual_risk_cash": full_risk_cash,
        "full_risk_counterfactual_pnl_cash": full_pnl_cash,
        "full_risk_counterfactual_pnl_cash_delta": round(full_pnl_cash - (risk_cash * net_proxy_r), 8),
        "full_risk_counterfactual_net_proxy_r": net_proxy_r,
    }


def risk_pct_from_config(config: Mapping[str, Any]) -> float:
    try:
        return float(((config.get("risk") or {}).get("risk_per_trade_pct")))
    except (TypeError, ValueError, AttributeError):
        return DEFAULT_RISK_PCT


def _normalize_risk_symbol(symbol: Any) -> str:
    return str(symbol or "").strip().upper().replace(".", "_")


def _risk_symbol_candidates(symbol: Any) -> tuple[str, ...]:
    raw = str(symbol or "").strip()
    candidates: list[str] = []
    for value in (
        raw,
        FTMO_SYMBOL_MAP.get(raw, raw),
        raw.replace("_cash", ".cash").replace("_CASH", ".cash"),
    ):
        normalized = _normalize_risk_symbol(value)
        if normalized and normalized not in candidates:
            candidates.append(normalized)
        if normalized.endswith("_CASH"):
            without_cash = normalized.removesuffix("_CASH")
            if without_cash and without_cash not in candidates:
                candidates.append(without_cash)
        elif normalized:
            with_cash = f"{normalized}_CASH"
            if with_cash not in candidates:
                candidates.append(with_cash)
    return tuple(candidates)


def _display_path(path: Path) -> str:
    try:
        return str(path.relative_to(REPO_ROOT))
    except ValueError:
        return str(path)


def _resolved_risk_profile_path(config: Mapping[str, Any]) -> Path:
    runtime = config.get("gtos_vnext_runtime") if isinstance(config, Mapping) else {}
    runtime = runtime if isinstance(runtime, Mapping) else {}
    raw_path = (
        runtime.get("timewarp_replay_risk_profile_path")
        or runtime.get("broker_profile_path")
        or DEFAULT_TIMEWARP_REPLAY_RISK_PROFILE_PATH
    )
    profile_path = Path(str(raw_path))
    if not profile_path.is_absolute():
        profile_path = REPO_ROOT / profile_path
    return profile_path


def _risk_profile_file_binding(
    config: Mapping[str, Any],
) -> tuple[Path, str]:
    profile_path = _resolved_risk_profile_path(config)
    if not profile_path.is_file() or profile_path.is_symlink():
        raise CampaignExactCacheError("risk_profile_regular_file_missing")
    return profile_path, file_sha256(profile_path)


def _load_bound_risk_profile_payload(
    config: Mapping[str, Any],
) -> tuple[Mapping[str, Any], str, Path, str]:
    profile_path, source_sha256 = _risk_profile_file_binding(config)
    try:
        import yaml  # type: ignore

        payload = yaml.safe_load(profile_path.read_text(encoding="utf-8")) or {}
    except Exception as exc:  # noqa: BLE001 - exact cache must fail closed.
        raise CampaignExactCacheError("risk_profile_parse_failed") from exc
    if not isinstance(payload, Mapping):
        raise CampaignExactCacheError("risk_profile_payload_not_mapping")
    if file_sha256(profile_path) != source_sha256:
        raise CampaignExactCacheError("risk_profile_changed_during_load")
    return payload, _display_path(profile_path), profile_path, source_sha256


@lru_cache(maxsize=8)
def _load_risk_profile_payload(profile_path_text: str) -> tuple[Mapping[str, Any], str]:
    profile_path = Path(profile_path_text)
    if not profile_path.exists():
        return {}, _display_path(profile_path)
    try:
        import yaml  # type: ignore

        with profile_path.open(encoding="utf-8") as handle:
            payload = yaml.safe_load(handle) or {}
        if not isinstance(payload, Mapping):
            return {}, _display_path(profile_path)
        source = _display_path(profile_path)
        return payload, source
    except Exception:  # noqa: BLE001 - risk profile falls back to global config.
        return {}, _display_path(profile_path)


def _profile_risk_payload(config: Mapping[str, Any]) -> tuple[Mapping[str, Any], str]:
    profile_path = _resolved_risk_profile_path(config)
    return _load_risk_profile_payload(str(profile_path))


def _risk_pct_for_symbol_uncached(
    config: Mapping[str, Any],
    symbol: Any,
    *,
    profile_override: tuple[Mapping[str, Any], str] | None = None,
) -> tuple[float, str]:
    default = risk_pct_from_config(config)
    symbol_candidates = _risk_symbol_candidates(symbol)

    inline = config.get("timewarp_replay_symbol_risk_pct") if isinstance(config, Mapping) else {}
    inline = inline if isinstance(inline, Mapping) else {}
    for key, value in inline.items():
        if _normalize_risk_symbol(key) in symbol_candidates:
            try:
                return float(value), f"config:timewarp_replay_symbol_risk_pct.{key}"
            except (TypeError, ValueError):
                break

    profile, source = (
        profile_override
        if profile_override is not None
        else _profile_risk_payload(config)
    )
    instruments = profile.get("instruments") if isinstance(profile, Mapping) else {}
    instruments = instruments if isinstance(instruments, Mapping) else {}
    for key, payload in instruments.items():
        if _normalize_risk_symbol(key) not in symbol_candidates:
            continue
        payload = payload if isinstance(payload, Mapping) else {}
        risk = payload.get("risk")
        risk = risk if isinstance(risk, Mapping) else {}
        try:
            return float(risk["risk_per_trade_pct"]), f"{source}:instruments.{key}.risk.risk_per_trade_pct"
        except (KeyError, TypeError, ValueError):
            break
    profile_risk = profile.get("risk") if isinstance(profile, Mapping) else {}
    profile_risk = profile_risk if isinstance(profile_risk, Mapping) else {}
    try:
        return float(profile_risk["risk_per_trade_pct"]), f"{source}:risk.risk_per_trade_pct"
    except (KeyError, TypeError, ValueError):
        pass
    return default, "config/agent_config.yaml:risk.risk_per_trade_pct"


def risk_pct_for_symbol(config: Mapping[str, Any], symbol: Any) -> tuple[float, str]:
    cache = active_campaign_exact_cache()
    if cache is not None:
        return cache.risk_pct(config, symbol)
    return _risk_pct_for_symbol_uncached(config, symbol)


def clock_time_to_utc_minutes(value: Any) -> int | None:
    text = str(value or "").strip()
    if not text:
        return None
    parts = text.split(":")
    if len(parts) < 2:
        return None
    try:
        hour = int(parts[0])
        minute = int(parts[1])
    except ValueError:
        return None
    if hour < 0 or hour > 23 or minute < 0 or minute > 59:
        return None
    return hour * 60 + minute


def session_start_minutes_by_session(kill_zones: Any) -> dict[str, int]:
    if not isinstance(kill_zones, Mapping):
        return {}
    starts: dict[str, int] = {}
    for raw_name, raw_window in kill_zones.items():
        if not isinstance(raw_window, Mapping):
            continue
        start_minutes = clock_time_to_utc_minutes(raw_window.get("start_utc"))
        if start_minutes is None:
            continue
        name = str(raw_name or "").strip().lower()
        if name:
            starts[name] = start_minutes
            starts[f"in_{name}_timewarp_configured_session"] = start_minutes
    return starts


def normalize_session_start_minutes_by_session(raw: Any) -> dict[str, int]:
    if not isinstance(raw, Mapping):
        return {}
    starts: dict[str, int] = {}
    for raw_name, raw_value in raw.items():
        name = str(raw_name or "").strip().lower()
        if not name:
            continue
        start_minutes = (
            int(safe_float(raw_value, -1))
            if isinstance(raw_value, (int, float, str))
            and str(raw_value).strip()
            and str(raw_value).strip().replace(".", "", 1).lstrip("-").isdigit()
            else clock_time_to_utc_minutes(raw_value)
        )
        if start_minutes is None or start_minutes < 0 or start_minutes >= 24 * 60:
            continue
        starts[name] = start_minutes
        starts[f"in_{name}_timewarp_configured_session"] = start_minutes
    return starts


