def scheduler_terminal_vs_soft_guard_fields(
    *sources: Mapping[str, Any],
) -> dict[str, Any]:
    def first_field(key: str) -> Any:
        for source in sources:
            if not isinstance(source, Mapping):
                continue
            value = source.get(key)
            if value not in (None, "", [], {}):
                return value
        return None

    contract = first_field("scheduler_terminal_vs_soft_guard")
    contract_map = contract if isinstance(contract, Mapping) else {}
    terminal_vetoes = _list_text_values(
        first_present(
            first_field("terminal_vetoes"),
            first_field("scheduler_terminal_vetoes"),
            contract_map.get("terminal_vetoes"),
            first_field("reallocation_soft_guard_pool_terminal_vetoes"),
        )
    )
    soft_vetoes = _list_text_values(
        first_present(
            first_field("reallocation_soft_guard_vetoes"),
            first_field("scheduler_reallocation_soft_guard_vetoes"),
            contract_map.get("soft_guard_vetoes"),
        )
    )
    pool_eligible = _runtime_bool(
        first_present(
            first_field("reallocation_soft_guard_pool_eligible"),
            contract_map.get("pool_eligible"),
        ),
        False,
    )
    pool_status = str(
        first_present(
            first_field("reallocation_soft_guard_pool_status"),
            contract_map.get("pool_status"),
            "eligible" if pool_eligible else "not_applicable",
        )
        or ""
    )
    pool_reason = str(
        first_present(
            first_field("reallocation_soft_guard_pool_reason"),
            contract_map.get("pool_reason"),
            "cost_passed_source_complete_signed_soft_guard_reallocation"
            if pool_eligible
            else "no_soft_guard_contract",
        )
        or ""
    )
    return {
        "scheduler_terminal_vs_soft_guard": dict(contract_map) if contract_map else None,
        "terminal_vetoes": terminal_vetoes,
        "scheduler_terminal_vetoes": terminal_vetoes,
        "reallocation_soft_guard_vetoes": soft_vetoes,
        "scheduler_reallocation_soft_guard_vetoes": soft_vetoes,
        "reallocation_soft_guard_pool_eligible": pool_eligible,
        "reallocation_soft_guard_pool_status": pool_status,
        "reallocation_soft_guard_pool_reason": pool_reason,
        "reallocation_soft_guard_pool_terminal_vetoes": terminal_vetoes,
    }


