def selected_policy_executable_quality_gate_fields(
    *sources: Mapping[str, Any],
    runtime: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Causal selected-policy admission gate using predecision quality only."""

    runtime = runtime if isinstance(runtime, Mapping) else {}

    def first_field(*keys: str) -> Any:
        for source in sources:
            if not isinstance(source, Mapping):
                continue
            for key in keys:
                variants = (key,)
                if not key.startswith("finalizer_primary_probe_"):
                    variants = (
                        key,
                        f"finalizer_primary_probe_{key}",
                    )
                for variant in variants:
                    value = source.get(variant)
                    if value not in (None, "", [], {}):
                        return value
        return None

    enabled = _runtime_bool(
        runtime.get(
            "scheduler_v4_best_trade_allocator_selected_policy_executable_quality_gate_enabled"
        ),
        True,
    )
    selected_policy = str(
        first_field(
            "selected_policy_for_expected_net_r",
            "selected_policy",
            "selected_execution_policy",
            "dynamic_geometry_policy",
        )
        or ""
    ).strip()
    calibration_status = str(
        first_field("selected_policy_expected_net_calibration_status") or ""
    ).strip()
    selected_policy_evidence_present = first_field(
        "selected_policy_for_expected_net_r",
        "selected_policy_expected_net_calibration_status",
        "selected_policy_expected_net_calibrated",
        "selected_policy_expected_net_calibration_required",
        "selected_policy_expected_net_r",
        "candidate_selected_policy_expected_net_r",
    ) is not None
    calibrated = _runtime_bool(
        first_field("selected_policy_expected_net_calibrated"),
        "calibrated" in calibration_status.lower(),
    )
    calibration_required = _runtime_bool(
        first_present(
            first_field("selected_policy_expected_net_calibration_required"),
            selected_policy_evidence_present,
        ),
        False,
    )
    applies = bool(
        enabled
        and (
            selected_policy_evidence_present
            or calibrated
            or calibration_required
        )
    )
    expected_net_r = safe_float(
        first_field(
            "selected_policy_expected_net_r",
            "candidate_selected_policy_expected_net_r",
            "selected_policy_executable_quality_expected_net_r",
            "candidate_expected_net_r",
            "expected_net_r",
        ),
        math.nan,
    )
    execution_fill_probability = safe_float(
        first_field(
            "execution_fill_probability",
            "risk_finalizer_execution_fill_probability",
            "causal_finalizer_candidate_fill_probability",
            "selected_policy_executable_quality_execution_fill_probability",
        ),
        math.nan,
    )
    limit_fill_probability = safe_float(
        first_field(
            "predecision_stop_hazard_guard_limit_fill_probability",
            "predecision_limit_fillability_probability",
            "limit_fillability_probability",
            "candidate_fill_probability",
            "fill_probability",
            "selected_policy_executable_quality_limit_fill_probability",
        ),
        math.nan,
    )
    unit_risk_atr = safe_float(
        first_field(
            "predecision_stop_hazard_guard_unit_risk_atr",
            "scheduler_option_predecision_stop_hazard_guard_unit_risk_atr",
            "selected_scheduler_replacement_reallocation_stop_hazard_unit_risk_atr",
            "selected_policy_executable_quality_unit_risk_atr",
        ),
        math.nan,
    )
    distance_to_limit_risk = safe_float(
        first_field(
            "predecision_stop_hazard_guard_distance_to_limit_risk",
            "scheduler_option_predecision_stop_hazard_guard_distance_to_limit_risk",
            "selected_scheduler_replacement_reallocation_stop_hazard_distance_to_limit_risk",
            "selected_policy_executable_quality_distance_to_limit_risk",
        ),
        math.nan,
    )
    pressure_score = safe_float(
        first_field(
            "predecision_stop_hazard_guard_pressure_score",
            "scheduler_option_predecision_stop_hazard_guard_pressure_score",
            "selected_scheduler_replacement_reallocation_stop_hazard_pressure_score",
            "selected_policy_executable_quality_pressure_score",
        ),
        math.nan,
    )
    pressure_raw_triggered = _runtime_bool(
        first_field(
            "predecision_stop_hazard_guard_pressure_triggered",
            "scheduler_option_predecision_stop_hazard_guard_pressure_triggered",
            "selected_scheduler_replacement_reallocation_stop_hazard_pressure_triggered",
            "selected_policy_executable_quality_pressure_raw_triggered",
        ),
        False,
    )
    pressure_score_triggered = _runtime_bool(
        first_field(
            "predecision_stop_hazard_guard_pressure_score_triggered",
            "scheduler_option_predecision_stop_hazard_guard_pressure_score_triggered",
            "selected_scheduler_replacement_reallocation_stop_hazard_pressure_score_triggered",
            "selected_policy_executable_quality_pressure_score_triggered",
        ),
        False,
    )
    pressure_suppressed_reason = str(
        first_field(
            "predecision_stop_hazard_guard_pressure_suppressed_reason",
            "scheduler_option_predecision_stop_hazard_guard_pressure_suppressed_reason",
            "selected_scheduler_replacement_reallocation_stop_hazard_pressure_suppressed_reason",
            "selected_policy_executable_quality_pressure_suppressed_reason",
        )
        or ""
    ).strip()
    risk_cap_applied = _runtime_bool(
        first_field(
            "predecision_stop_hazard_guard_risk_cap_applied",
            "scheduler_option_predecision_stop_hazard_guard_risk_cap_applied",
            "selected_scheduler_replacement_reallocation_stop_hazard_risk_cap_applied",
            "selected_policy_executable_quality_risk_cap_applied",
        ),
        False,
    )
    risk_cap_pct = safe_float(
        first_field(
            "predecision_stop_hazard_guard_risk_cap_pct",
            "scheduler_option_predecision_stop_hazard_guard_risk_cap_pct",
            "selected_scheduler_replacement_reallocation_stop_hazard_risk_cap_pct",
            "selected_policy_executable_quality_risk_cap_pct",
        ),
        math.nan,
    )
    reallocation_quality_score = safe_float(
        first_field(
            "selected_policy_executable_quality_reallocation_score",
            "risk_finalizer_selected_policy_executable_quality_reallocation_score",
            "selected_execution_policy_replay_selected_policy_executable_quality_reallocation_score",
            "risk_admitted_scheduler_reallocation_score",
            "replacement_reallocation_quality_score",
            "selected_scheduler_replacement_reallocation_quality_score",
        ),
        math.nan,
    )
    source_completeness = safe_float(
        first_field("source_completeness", "candidate_source_completeness"),
        math.nan,
    )
    source_status = str(first_field("source_completeness_status") or "").lower()
    cost_status = str(first_field("pretrade_cost_packet_status") or "").upper()
    cost_source_gap_status = str(first_field("cost_source_gap_status") or "")
    cost_authority = str(
        first_field("cost_authority", "execution_cost_authority") or ""
    )
    cost_fallback_authority = _runtime_bool(
        first_field("candidate_cost_r_fallback_is_authority"),
        False,
    )
    signed_authority_valid = _runtime_bool(
        first_field("package_new_entry_authority_valid"),
        False,
    )
    signed_authority_status = str(
        first_field("package_new_entry_authority_status") or ""
    ).strip()
    signed_authority_failures_raw = first_field(
        "package_new_entry_authority_failures"
    )
    signed_authority_failures = list(
        signed_authority_failures_raw
        if isinstance(signed_authority_failures_raw, (list, tuple, set))
        else [signed_authority_failures_raw]
        if signed_authority_failures_raw not in (None, "")
        else []
    )
    signed_authority_uses_outcome_fields = _runtime_bool(
        first_field("package_new_entry_authority_uses_outcome_fields"),
        False,
    )
    package_order_executable = _runtime_bool(
        first_field(
            "package_replay_order_executable_candidate_use_allowed",
            "package_new_entry_authority_package_replay_order_executable_candidate_use_allowed",
        ),
        False,
    )
    package_order_executable_reason = str(
        first_field(
            "package_replay_order_executable_candidate_use_allowed_reason",
            "package_new_entry_authority_package_replay_order_executable_candidate_use_allowed_reason",
        )
        or ""
    ).strip()
    package_order_executable_source = str(
        first_field(
            "package_replay_order_executable_authority_source",
            "package_new_entry_authority_package_replay_order_executable_authority_source",
        )
        or ""
    ).strip()
    explicit_route_resolution = _runtime_bool(
        first_field(
            "package_risk_expression_fill_floor_route_resolved_for_full_risk",
            "package_risk_expression_route_resolution_full_risk_bypass_allowed",
            "package_fill_floor_authority_valid",
            "package_new_entry_authority_package_fill_floor_authority_allowed",
        ),
        False,
    )
    signed_order_executable_route_resolved = bool(
        explicit_route_resolution
        or (
            package_order_executable
            and package_order_executable_reason
            == "package_candidate_and_signed_new_entry_authority_executable"
            and package_order_executable_source
            == "package_replay_executable_and_signed_new_entry_authority"
        )
    )
    lifecycle_authority_blocked = bool(
        (
            _runtime_bool(first_field("source_required_lifecycle_origin"), False)
            and not _runtime_bool(
                first_field(
                    "source_required_package_risk_lifecycle_reconcile_applied",
                    "execution_manager_source_required_package_risk_lifecycle_reconcile_applied",
                ),
                False,
            )
        )
        or str(
            first_field("package_replay_order_executable_final_blocker_class") or ""
        )
        in {"lifecycle", "lifecycle_authority"}
        or str(first_field("package_replay_order_executable_transfer_status") or "")
        == "terminal_lifecycle_deferred_source_gap"
        or _runtime_bool(first_field("execution_manager_replay_should_block"), False)
    )

    replacement_projection = scheduler_replacement_reallocation_quality_ledger_fields(
        *sources
    )
    reallocation_base_expected_transfer_score = safe_float(
        first_present(
            first_field("replacement_reallocation_base_expected_transfer_score"),
            replacement_projection.get(
                "replacement_reallocation_base_expected_transfer_score"
            ),
        ),
        math.nan,
    )
    reallocation_risk_cap_adjusted_expected_transfer_score = safe_float(
        first_present(
            first_field(
                "replacement_reallocation_risk_cap_adjusted_expected_transfer_score"
            ),
            replacement_projection.get(
                "replacement_reallocation_risk_cap_adjusted_expected_transfer_score"
            ),
        ),
        math.nan,
    )
    reallocation_stop_hazard_quality_penalty = safe_float(
        first_present(
            first_field("replacement_reallocation_stop_hazard_quality_penalty"),
            replacement_projection.get(
                "replacement_reallocation_stop_hazard_quality_penalty"
            ),
        ),
        math.nan,
    )
    reallocation_stop_hazard_status = str(
        first_present(
            first_field("replacement_reallocation_stop_hazard_status"),
            replacement_projection.get("replacement_reallocation_stop_hazard_status"),
        )
        or ""
    ).strip().lower()

    projected_raw_reallocation_hard_failures = replacement_projection.get(
        "replacement_reallocation_raw_hard_gate_failures"
    )
    raw_reallocation_hard_failures_present = (
        "replacement_reallocation_raw_hard_gate_failures" in replacement_projection
    )
    raw_reallocation_hard_failures: list[str] = [
        str(item)
        for item in (
            projected_raw_reallocation_hard_failures
            if isinstance(
                projected_raw_reallocation_hard_failures,
                (list, tuple, set),
            )
            else [projected_raw_reallocation_hard_failures]
        )
        if item not in (None, "")
    ]
    reallocation_soft_guard_allowed = _runtime_bool(
        replacement_projection.get("replacement_reallocation_soft_guard_allowed"),
        False,
    )
    pending_surfaces: list[Mapping[str, Any]] = [
        source for source in sources if isinstance(source, Mapping)
    ]
    for source in list(pending_surfaces):
        components = source.get("score_components")
        if isinstance(components, Mapping):
            pending_surfaces.append(components)
        for key in (
            "candidate_decision_inputs",
            "scheduler_candidate_decision_inputs",
            "decision_inputs",
        ):
            nested = source.get(key)
            if isinstance(nested, Mapping):
                pending_surfaces.append(nested)
    for surface in pending_surfaces:
        diagnostic = surface.get("replacement_reallocation_quality")
        if not isinstance(diagnostic, Mapping):
            continue
        if "raw_hard_gate_failures" in diagnostic:
            raw_reallocation_hard_failures_present = True
            raw = diagnostic.get("raw_hard_gate_failures")
            raw_reallocation_hard_failures = [
                str(item)
                for item in (
                    raw if isinstance(raw, (list, tuple, set)) else [raw]
                )
                if item not in (None, "")
            ]
        reallocation_soft_guard_allowed = _runtime_bool(
            diagnostic.get("soft_guard_reallocation_allowed"),
            reallocation_soft_guard_allowed,
        )
        break
    min_execution_fill = safe_float(
        runtime.get(
            "scheduler_v4_best_trade_allocator_selected_policy_gate_min_execution_fill_probability"
        ),
        0.55,
    )
    min_limit_fill = safe_float(
        runtime.get(
            "scheduler_v4_best_trade_allocator_selected_policy_gate_min_limit_fill_probability"
        ),
        0.45,
    )
    pressure_floor = safe_float(
        runtime.get(
            "scheduler_v4_best_trade_allocator_selected_policy_gate_pressure_score_floor"
        ),
        0.80,
    )
    pressure_limit_fill_floor = safe_float(
        runtime.get(
            "scheduler_v4_best_trade_allocator_selected_policy_gate_pressure_limit_fill_floor"
        ),
        0.70,
    )
    min_unit_risk_atr = safe_float(
        runtime.get(
            "scheduler_v4_best_trade_allocator_selected_policy_gate_min_unit_risk_atr"
        ),
        0.35,
    )
    max_distance_to_limit_risk = safe_float(
        runtime.get(
            "scheduler_v4_best_trade_allocator_selected_policy_gate_max_distance_to_limit_risk"
        ),
        1.50,
    )
    min_reallocation_quality = safe_float(
        runtime.get(
            "scheduler_v4_best_trade_allocator_selected_policy_gate_min_reallocation_quality_score"
        ),
        0.0,
    )
    pressure_requires_base_fragility = _runtime_bool(
        first_present(
            runtime.get(
                "scheduler_v4_best_trade_allocator_selected_policy_gate_stop_hazard_pressure_requires_base_fragility"
            ),
            runtime.get(
                "scheduler_v4_best_trade_allocator_predecision_stop_hazard_pressure_requires_base_fragility"
            ),
        ),
        True,
    )
    failures: list[str] = []
    pressure_hazard = False
    if applies:
        if calibration_required and not calibrated:
            failures.append("selected_policy_expected_net_not_calibrated")
        if not math.isfinite(expected_net_r) or expected_net_r <= 0.0:
            failures.append("selected_policy_expected_net_not_positive")
        if cost_status and cost_status not in {"PASSED", "PASS", "OK"}:
            failures.append("broker_cost_status")
        if cost_source_gap_status and cost_source_gap_status != (
            "source_bound_cost_authority_present"
        ):
            failures.append("broker_cost_source_gap")
        if cost_authority and cost_authority != "broker_calibrated_replay_cost":
            failures.append("broker_cost_authority")
        if cost_fallback_authority:
            failures.append("broker_cost_fallback_authority")
        if (
            math.isfinite(source_completeness)
            and source_completeness < 0.95
        ) or any(
            token in source_status
            for token in (
                "missing",
                "degraded",
                "gap",
                "source_required",
                "incomplete",
                "prospective_capture",
                "snapshot_incomplete",
            )
        ):
            failures.append("source_completeness")
        if (
            math.isfinite(execution_fill_probability)
            and execution_fill_probability < min_execution_fill
        ):
            failures.append("selected_policy_execution_fill_probability")
        if (
            math.isfinite(limit_fill_probability)
            and limit_fill_probability < min_limit_fill
        ):
            failures.append("selected_policy_limit_fill_probability")
        benign_pressure_suppressed = bool(
            pressure_requires_base_fragility
            and pressure_suppressed_reason
            == "stop_hazard_pressure_requires_base_fragility"
        )
        pressure_hazard = bool(
            pressure_raw_triggered
            or (
                not benign_pressure_suppressed
                and (
                    pressure_score_triggered
                    or (
                        math.isfinite(pressure_score)
                        and pressure_score >= pressure_floor
                    )
                    or pressure_suppressed_reason
                )
            )
        )
        if pressure_hazard:
            if not risk_cap_applied:
                if pressure_suppressed_reason and not pressure_raw_triggered:
                    failures.append(
                        "selected_policy_stop_hazard_pressure_suppressed_uncapped"
                    )
                else:
                    failures.append("selected_policy_stop_hazard_pressure_uncapped")
            if (
                math.isfinite(limit_fill_probability)
                and limit_fill_probability < pressure_limit_fill_floor
            ):
                failures.append(
                    "selected_policy_pressure_limit_fill_probability"
                )
        if math.isfinite(unit_risk_atr) and unit_risk_atr < min_unit_risk_atr:
            failures.append("selected_policy_stop_unit_risk_atr_below_floor")
        if (
            math.isfinite(distance_to_limit_risk)
            and distance_to_limit_risk > max_distance_to_limit_risk
        ):
            failures.append("selected_policy_distance_to_limit_risk_above_floor")
        if (
            math.isfinite(reallocation_quality_score)
            and reallocation_quality_score < min_reallocation_quality
        ):
            failures.append("selected_policy_reallocation_quality_score")
    original_failures = list(failures)
    soft_stop_pressure_failure_names = {
        "selected_policy_pressure_limit_fill_probability",
        "selected_policy_reallocation_quality_score",
    }
    retained_soft_stop_pressure_conditions = [
        failure
        for failure in original_failures
        if failure in soft_stop_pressure_failure_names
    ]
    non_soft_failures = [
        failure
        for failure in original_failures
        if failure not in soft_stop_pressure_failure_names
    ]
    bad_source_status = any(
        token in source_status
        for token in (
            "missing",
            "degraded",
            "gap",
            "source_required",
            "incomplete",
            "prospective_capture",
            "snapshot_incomplete",
        )
    )
    cost_source_clean = bool(
        cost_status in {"PASSED", "PASS", "OK"}
        and cost_source_gap_status == "source_bound_cost_authority_present"
        and cost_authority == "broker_calibrated_replay_cost"
        and not cost_fallback_authority
    )
    source_complete = bool(
        math.isfinite(source_completeness)
        and source_completeness >= 0.95
        and not bad_source_status
    )
    signed_route_clean = bool(
        signed_authority_valid
        and signed_authority_status == "valid_signed_predecision_new_entry_authority"
        and not signed_authority_failures
        and not signed_authority_uses_outcome_fields
        and package_order_executable
        and signed_order_executable_route_resolved
        and not lifecycle_authority_blocked
    )
    score_matches_soft_stop_pressure_penalty = bool(
        math.isfinite(reallocation_quality_score)
        and math.isfinite(reallocation_risk_cap_adjusted_expected_transfer_score)
        and math.isfinite(reallocation_stop_hazard_quality_penalty)
        and math.isclose(
            reallocation_quality_score,
            reallocation_risk_cap_adjusted_expected_transfer_score
            - reallocation_stop_hazard_quality_penalty,
            rel_tol=1e-9,
            abs_tol=1e-6,
        )
    )
    reallocation_failure_present = (
        "selected_policy_reallocation_quality_score" in original_failures
    )
    reallocation_soft_penalty_only = bool(
        not reallocation_failure_present
        or (
            raw_reallocation_hard_failures_present
            and not raw_reallocation_hard_failures
            and reallocation_soft_guard_allowed
            and reallocation_stop_hazard_status == "capped"
            and math.isfinite(reallocation_base_expected_transfer_score)
            and reallocation_base_expected_transfer_score
            > min_reallocation_quality
            and math.isfinite(
                reallocation_risk_cap_adjusted_expected_transfer_score
            )
            and reallocation_risk_cap_adjusted_expected_transfer_score
            > min_reallocation_quality
            and reallocation_stop_hazard_quality_penalty > 0.0
            and score_matches_soft_stop_pressure_penalty
        )
    )
    soft_stop_pressure_override_blockers: list[str] = []
    if retained_soft_stop_pressure_conditions:
        if non_soft_failures:
            soft_stop_pressure_override_blockers.append(
                "non_soft_executable_quality_failure_present"
            )
        if not risk_cap_applied:
            soft_stop_pressure_override_blockers.append(
                "predecision_stop_pressure_risk_cap_not_applied"
            )
        if not math.isfinite(risk_cap_pct) or risk_cap_pct <= 0.0:
            soft_stop_pressure_override_blockers.append(
                "predecision_stop_pressure_risk_cap_not_positive"
            )
        if not cost_source_clean:
            soft_stop_pressure_override_blockers.append(
                "broker_cost_or_cost_source_authority_not_clean"
            )
        if not source_complete:
            soft_stop_pressure_override_blockers.append(
                "candidate_source_completeness_not_clean"
            )
        if not signed_route_clean:
            soft_stop_pressure_override_blockers.append(
                "signed_order_executable_route_not_resolved"
            )
        if lifecycle_authority_blocked:
            soft_stop_pressure_override_blockers.append(
                "runtime_lifecycle_authority_blocked"
            )
        if not reallocation_soft_penalty_only:
            soft_stop_pressure_override_blockers.append(
                "negative_reallocation_not_proven_soft_stop_pressure_penalty_only"
            )
    soft_stop_pressure_override_applied = bool(
        applies
        and retained_soft_stop_pressure_conditions
        and not soft_stop_pressure_override_blockers
    )
    if soft_stop_pressure_override_applied:
        failures = [
            failure
            for failure in failures
            if failure not in soft_stop_pressure_failure_names
        ]
    soft_cap_executable_transfer_contract_allowed = bool(
        soft_stop_pressure_override_applied
        and reallocation_failure_present
        and math.isfinite(reallocation_quality_score)
        and reallocation_quality_score < min_reallocation_quality
        and risk_cap_applied
        and math.isfinite(risk_cap_pct)
        and risk_cap_pct > 0.0
        and raw_reallocation_hard_failures_present
        and not raw_reallocation_hard_failures
        and reallocation_soft_guard_allowed
        and reallocation_stop_hazard_status == "capped"
        and math.isfinite(reallocation_base_expected_transfer_score)
        and reallocation_base_expected_transfer_score > min_reallocation_quality
        and math.isfinite(reallocation_risk_cap_adjusted_expected_transfer_score)
        and reallocation_risk_cap_adjusted_expected_transfer_score
        > min_reallocation_quality
        and cost_source_clean
        and source_complete
        and signed_route_clean
    )
    status = (
        "disabled"
        if not enabled
        else "not_applicable"
        if not applies
        else "blocked"
        if failures
        else "passed"
    )
    return {
        "selected_policy_executable_quality_gate_enabled": enabled,
        "selected_policy_executable_quality_gate_applies": applies,
        "selected_policy_executable_quality_gate_status": status,
        "selected_policy_executable_quality_gate_failures": failures,
        "selected_policy_executable_quality_gate_original_failures": (
            original_failures
        ),
        "selected_policy_executable_quality_gate_retained_soft_conditions": (
            retained_soft_stop_pressure_conditions
        ),
        "selected_policy_executable_quality_gate_soft_stop_pressure_override_applied": (
            soft_stop_pressure_override_applied
        ),
        "selected_policy_executable_quality_gate_soft_stop_pressure_override_reason": (
            SOFT_CAP_EXECUTABLE_TRANSFER_CONTRACT_REASON
            if soft_stop_pressure_override_applied
            else None
        ),
        "selected_policy_executable_quality_gate_soft_stop_pressure_override_blockers": (
            soft_stop_pressure_override_blockers
        ),
        "selected_policy_executable_quality_gate_source_boundary": (
            SELECTED_POLICY_EXECUTABLE_QUALITY_SOURCE_BOUNDARY
        ),
        "selected_policy_executable_quality_gate_uses_outcome_fields": False,
        "soft_cap_executable_transfer_contract_allowed": (
            soft_cap_executable_transfer_contract_allowed
        ),
        "soft_cap_executable_transfer_contract_reason": (
            SOFT_CAP_EXECUTABLE_TRANSFER_CONTRACT_REASON
            if soft_cap_executable_transfer_contract_allowed
            else None
        ),
        "soft_cap_executable_transfer_contract_blockers": (
            soft_stop_pressure_override_blockers
        ),
        "soft_cap_executable_transfer_contract_source_boundary": (
            SOFT_CAP_EXECUTABLE_TRANSFER_CONTRACT_SOURCE_BOUNDARY
        ),
        "soft_cap_executable_transfer_contract_uses_outcome_fields": False,
        "selected_policy_executable_quality_selected_policy": selected_policy or None,
        "selected_policy_executable_quality_expected_net_r": (
            expected_net_r if math.isfinite(expected_net_r) else None
        ),
        "selected_policy_executable_quality_calibrated": calibrated,
        "selected_policy_executable_quality_calibration_status": (
            calibration_status or None
        ),
        "selected_policy_executable_quality_execution_fill_probability": (
            execution_fill_probability
            if math.isfinite(execution_fill_probability)
            else None
        ),
        "selected_policy_executable_quality_limit_fill_probability": (
            limit_fill_probability if math.isfinite(limit_fill_probability) else None
        ),
        "selected_policy_executable_quality_unit_risk_atr": (
            unit_risk_atr if math.isfinite(unit_risk_atr) else None
        ),
        "selected_policy_executable_quality_distance_to_limit_risk": (
            distance_to_limit_risk if math.isfinite(distance_to_limit_risk) else None
        ),
        "selected_policy_executable_quality_pressure_score": (
            pressure_score if math.isfinite(pressure_score) else None
        ),
        "selected_policy_executable_quality_pressure_triggered": pressure_hazard
        if applies
        else False,
        "selected_policy_executable_quality_pressure_raw_triggered": (
            pressure_raw_triggered if applies else False
        ),
        "selected_policy_executable_quality_pressure_score_triggered": (
            pressure_score_triggered if applies else False
        ),
        "selected_policy_executable_quality_pressure_suppressed_reason": (
            pressure_suppressed_reason if applies and pressure_suppressed_reason else None
        ),
        "selected_policy_executable_quality_pressure_requires_base_fragility": (
            pressure_requires_base_fragility
        ),
        "selected_policy_executable_quality_risk_cap_applied": risk_cap_applied,
        "selected_policy_executable_quality_risk_cap_pct": (
            risk_cap_pct if math.isfinite(risk_cap_pct) else None
        ),
        "selected_policy_executable_quality_reallocation_score": (
            reallocation_quality_score
            if math.isfinite(reallocation_quality_score)
            else None
        ),
        "selected_policy_executable_quality_reallocation_base_expected_transfer_score": (
            reallocation_base_expected_transfer_score
            if math.isfinite(reallocation_base_expected_transfer_score)
            else None
        ),
        "selected_policy_executable_quality_reallocation_risk_cap_adjusted_expected_transfer_score": (
            reallocation_risk_cap_adjusted_expected_transfer_score
            if math.isfinite(reallocation_risk_cap_adjusted_expected_transfer_score)
            else None
        ),
        "selected_policy_executable_quality_reallocation_stop_hazard_status": (
            reallocation_stop_hazard_status or None
        ),
        "selected_policy_executable_quality_reallocation_stop_hazard_quality_penalty": (
            reallocation_stop_hazard_quality_penalty
            if math.isfinite(reallocation_stop_hazard_quality_penalty)
            else None
        ),
        "selected_policy_executable_quality_reallocation_raw_hard_failures_present": (
            raw_reallocation_hard_failures_present
        ),
        "selected_policy_executable_quality_reallocation_raw_hard_failures": (
            raw_reallocation_hard_failures
        ),
        "selected_policy_executable_quality_reallocation_soft_guard_allowed": (
            reallocation_soft_guard_allowed
        ),
        "selected_policy_executable_quality_reallocation_score_matches_soft_stop_pressure_penalty": (
            score_matches_soft_stop_pressure_penalty
        ),
        "selected_policy_executable_quality_reallocation_soft_penalty_only": (
            reallocation_soft_penalty_only
        ),
        "selected_policy_executable_quality_cost_source_clean": cost_source_clean,
        "selected_policy_executable_quality_source_complete": source_complete,
        "selected_policy_executable_quality_signed_authority_valid": (
            signed_authority_valid
        ),
        "selected_policy_executable_quality_signed_authority_status": (
            signed_authority_status or None
        ),
        "selected_policy_executable_quality_signed_authority_failures": (
            signed_authority_failures
        ),
        "selected_policy_executable_quality_package_order_executable": (
            package_order_executable
        ),
        "selected_policy_executable_quality_signed_order_executable_route_resolved": (
            signed_order_executable_route_resolved
        ),
        "selected_policy_executable_quality_lifecycle_authority_blocked": (
            lifecycle_authority_blocked
        ),
        "selected_policy_executable_quality_min_execution_fill_probability": (
            min_execution_fill
        ),
        "selected_policy_executable_quality_min_limit_fill_probability": (
            min_limit_fill
        ),
        "selected_policy_executable_quality_pressure_score_floor": pressure_floor,
        "selected_policy_executable_quality_pressure_limit_fill_floor": (
            pressure_limit_fill_floor
        ),
        "selected_policy_executable_quality_min_unit_risk_atr": min_unit_risk_atr,
        "selected_policy_executable_quality_max_distance_to_limit_risk": (
            max_distance_to_limit_risk
        ),
        "selected_policy_executable_quality_min_reallocation_quality_score": (
            min_reallocation_quality
        ),
    }


def consume_soft_cap_executable_transfer_fields(
    selected_policy_quality_gate: Mapping[str, Any] | None,
    *,
    reallocation_score: Any,
    reallocation_eligible: bool,
    reallocation_hard_failures: Iterable[Any] | None,
) -> dict[str, Any]:
    """Consume only the synthetic negative mixed-score failure for a valid cap."""

    selected_policy_quality_gate = (
        selected_policy_quality_gate
        if isinstance(selected_policy_quality_gate, Mapping)
        else {}
    )
    score = safe_float(reallocation_score, math.nan)
    hard_failures = list(
        dict.fromkeys(
            str(item)
            for item in (reallocation_hard_failures or [])
            if str(item or "").strip()
        )
    )
    contract_allowed = _runtime_bool(
        selected_policy_quality_gate.get(
            "soft_cap_executable_transfer_contract_allowed"
        ),
        False,
    )
    terminal_hard_failures = [
        failure
        for failure in hard_failures
        if failure != SOFT_CAP_SYNTHETIC_SCORE_FAILURE
    ]
    consumed = bool(
        contract_allowed
        and math.isfinite(score)
        and score < 0.0
        and not terminal_hard_failures
    )
    removed_failures: list[str] = []
    if consumed and SOFT_CAP_SYNTHETIC_SCORE_FAILURE in hard_failures:
        removed_failures.append(SOFT_CAP_SYNTHETIC_SCORE_FAILURE)
        hard_failures = [
            failure
            for failure in hard_failures
            if failure != SOFT_CAP_SYNTHETIC_SCORE_FAILURE
        ]
    effective_eligible = (
        not hard_failures if consumed else bool(reallocation_eligible)
    )
    return {
        "soft_cap_executable_transfer_consumed": consumed,
        "soft_cap_executable_transfer_consumed_reason": (
            SOFT_CAP_EXECUTABLE_TRANSFER_CONSUMED_REASON if consumed else None
        ),
        "soft_cap_executable_transfer_negative_mixed_score_preserved": (
            score if consumed else None
        ),
        "soft_cap_executable_transfer_removed_synthetic_hard_failures": (
            removed_failures
        ),
        "soft_cap_executable_transfer_effective_reallocation_eligible": (
            effective_eligible
        ),
        "soft_cap_executable_transfer_effective_reallocation_hard_failures": (
            hard_failures
        ),
        "soft_cap_executable_transfer_source_boundary": (
            SOFT_CAP_EXECUTABLE_TRANSFER_CONTRACT_SOURCE_BOUNDARY
        ),
        "soft_cap_executable_transfer_uses_outcome_fields": False,
    }


def scheduler_option_soft_veto_replay_probe_detail(
    option: Mapping[str, Any],
    *,
    candidate: Mapping[str, Any],
    packets: Mapping[str, Any],
    ineligibility_detail: Mapping[str, Any],
    min_trade_score: float,
    runtime: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Allow finalizer risk-probe for package rows blocked by soft quality floors.

    This does not execute hard-vetoed rows. Cost authority, source gaps,
    no-leak/source hard vetoes, invalid actions, and lifecycle blockers remain
    finalizer-ineligible.
    """

    failures: list[str] = []
    status = str(ineligibility_detail.get("status") or "")
    package_reduce_risk_replay_authority_allowed = _runtime_bool(
        ineligibility_detail.get("package_reduce_risk_replay_authority_allowed"),
        False,
    )
    unresolved_fill_floor_failures = [
        str(item)
        for item in (
            ineligibility_detail.get(
                "package_fill_floor_authority_unresolved_failures"
            )
            or ineligibility_detail.get("package_fill_floor_authority_failures")
            or []
        )
        if str(item or "").strip()
    ]
    resolved_fill_floor_probe_allowed = bool(
        package_reduce_risk_replay_authority_allowed
        and not unresolved_fill_floor_failures
    )
    vetoes = [
        str(item)
        for item in ineligibility_detail.get("vetoes") or []
        if str(item or "").strip()
    ]
    primary = str(ineligibility_detail.get("primary_runtime_ineligible_reason") or "")
    components = option.get("score_components") if isinstance(option, Mapping) else {}
    components = components if isinstance(components, Mapping) else {}
    decision_inputs = components.get("candidate_decision_inputs")
    decision_inputs = decision_inputs if isinstance(decision_inputs, Mapping) else {}
    soft_guard_contract = scheduler_terminal_vs_soft_guard_fields(
        option,
        components,
        decision_inputs,
        ineligibility_detail,
    )
    contract_soft_reasons = list(
        soft_guard_contract.get("reallocation_soft_guard_vetoes") or []
    )
    contract_terminal_vetoes = list(soft_guard_contract.get("terminal_vetoes") or [])
    contract_pool_eligible = _runtime_bool(
        soft_guard_contract.get("reallocation_soft_guard_pool_eligible"),
        False,
    )
    if contract_soft_reasons:
        vetoes = contract_terminal_vetoes
    explicit_package_executable_allowed_precheck = _runtime_bool(
        first_present(
            option.get("package_replay_executable_candidate_use_allowed"),
            decision_inputs.get("package_replay_executable_candidate_use_allowed"),
            candidate.get("package_replay_executable_candidate_use_allowed"),
            packets.get("package_replay_executable_candidate_use_allowed"),
        ),
        False,
    )
    explicit_package_source_bound_present_precheck = any(
        _runtime_bool(first_present(source.get(field)), False)
        for source in (option, decision_inputs, candidate, packets)
        for field in (
            "source_bound_package_candidate_use_allowed",
            "ultimate_package_source_bound_candidate_use_allowed",
            "package_replay_source_bound_candidate_use_allowed",
            "ultimate_package_effective_source_bound_candidate_use_allowed",
        )
        if isinstance(source, Mapping)
    )
    explicit_package_order_executable_allowed_precheck = _runtime_bool(
        first_present(
            option.get("package_replay_order_executable_candidate_use_allowed"),
            option.get(
                "package_new_entry_authority_package_replay_order_executable_candidate_use_allowed"
            ),
            decision_inputs.get(
                "package_replay_order_executable_candidate_use_allowed"
            ),
            decision_inputs.get(
                "package_new_entry_authority_package_replay_order_executable_candidate_use_allowed"
            ),
            candidate.get("package_replay_order_executable_candidate_use_allowed"),
            candidate.get(
                "package_new_entry_authority_package_replay_order_executable_candidate_use_allowed"
            ),
            packets.get("package_replay_order_executable_candidate_use_allowed"),
            packets.get(
                "package_new_entry_authority_package_replay_order_executable_candidate_use_allowed"
            ),
        ),
        False,
    )
    explicit_signed_new_entry_authority_valid_precheck = bool(
        _runtime_bool(
            first_present(
                option.get("package_new_entry_authority_valid"),
                decision_inputs.get("package_new_entry_authority_valid"),
                candidate.get("package_new_entry_authority_valid"),
                packets.get("package_new_entry_authority_valid"),
            ),
            False,
        )
        and not _runtime_bool(
            first_present(
                option.get("package_new_entry_authority_uses_outcome_fields"),
                decision_inputs.get("package_new_entry_authority_uses_outcome_fields"),
                candidate.get("package_new_entry_authority_uses_outcome_fields"),
                packets.get("package_new_entry_authority_uses_outcome_fields"),
            ),
            False,
        )
    )
    stop_hazard_risk_cap_pct = safe_float(
        first_present(
            option.get("predecision_stop_hazard_guard_risk_cap_pct"),
            decision_inputs.get("predecision_stop_hazard_guard_risk_cap_pct"),
            candidate.get("predecision_stop_hazard_guard_risk_cap_pct"),
            packets.get("predecision_stop_hazard_guard_risk_cap_pct"),
        ),
        0.0,
    )
    signed_order_executable_route_probe_allowed = bool(
        explicit_package_executable_allowed_precheck
        and explicit_package_order_executable_allowed_precheck
        and explicit_signed_new_entry_authority_valid_precheck
    )
    stale_selector_veto_aliases = [
        reason
        for reason in vetoes
        if any(
            reason == prefix or reason.startswith(prefix)
            for prefix in SIGNED_ORDER_STALE_SELECTOR_VETO_PREFIXES
        )
    ]
    stale_selector_disposition_value = first_present(
        decision_inputs.get("signed_order_stale_selector_veto_disposition"),
        components.get("signed_order_stale_selector_veto_disposition"),
        option.get("signed_order_stale_selector_veto_disposition"),
    )
    stale_selector_disposition = (
        stale_selector_disposition_value
        if isinstance(stale_selector_disposition_value, Mapping)
        else {}
    )
    stale_selector_disposition_declared_aliases = _list_text_values(
        stale_selector_disposition.get("stale_selector_veto_aliases")
    )
    if (
        not stale_selector_veto_aliases
        and stale_selector_disposition.get("applies") is True
        and stale_selector_disposition_declared_aliases
    ):
        stale_selector_veto_aliases = list(
            stale_selector_disposition_declared_aliases
        )
    stale_selector_disposition_probe_blockers = _list_text_values(
        stale_selector_disposition.get("probe_blockers")
    )
    stale_selector_disposition_contract_failures: list[str] = []
    if stale_selector_veto_aliases:
        if not isinstance(stale_selector_disposition_value, Mapping):
            stale_selector_disposition_contract_failures.append(
                "signed_order_stale_selector_disposition_missing"
            )
        if (
            stale_selector_disposition.get("schema_version")
            != "signed_order_stale_selector_veto_disposition_v1"
        ):
            stale_selector_disposition_contract_failures.append(
                "signed_order_stale_selector_disposition_schema_invalid"
            )
        if stale_selector_disposition.get("applies") is not True:
            stale_selector_disposition_contract_failures.append(
                "signed_order_stale_selector_disposition_not_applied"
            )
        if (
            stale_selector_disposition.get("finalizer_probe_soft_eligible")
            is not True
        ):
            stale_selector_disposition_contract_failures.append(
                "signed_order_stale_selector_disposition_not_probe_eligible"
            )
        if set(stale_selector_disposition_declared_aliases) != set(
            stale_selector_veto_aliases
        ):
            stale_selector_disposition_contract_failures.append(
                "signed_order_stale_selector_disposition_alias_mismatch"
            )
        if stale_selector_disposition_probe_blockers:
            stale_selector_disposition_contract_failures.append(
                "signed_order_stale_selector_disposition_probe_blockers_present"
            )
        if stale_selector_disposition.get("uses_outcome_fields") is not False:
            stale_selector_disposition_contract_failures.append(
                "signed_order_stale_selector_disposition_outcome_boundary_invalid"
            )
        disposition_source_boundary = str(
            stale_selector_disposition.get("source_boundary") or ""
        ).strip().lower()
        if not (
            "predecision" in disposition_source_boundary
            and "no_outcome" in disposition_source_boundary
        ):
            stale_selector_disposition_contract_failures.append(
                "signed_order_stale_selector_disposition_source_boundary_invalid"
            )
        for field in (
            "package_replay_executable_candidate_use_allowed",
            "package_replay_order_executable_candidate_use_allowed",
            "signed_new_entry_authority_valid",
            "broker_cost_executable",
            "source_complete",
        ):
            if stale_selector_disposition.get(field) is not True:
                stale_selector_disposition_contract_failures.append(
                    f"signed_order_stale_selector_disposition_{field}_not_true"
                )
        if (
            stale_selector_disposition.get(
                "off_configured_session_authority_missing"
            )
            is not False
        ):
            stale_selector_disposition_contract_failures.append(
                "signed_order_stale_selector_disposition_off_session_terminal"
            )
    stale_selector_disposition_contract_valid = bool(
        stale_selector_veto_aliases
        and not stale_selector_disposition_contract_failures
    )
    signed_order_stale_selector_alias_probe_allowed = bool(
        stale_selector_veto_aliases
        and signed_order_executable_route_probe_allowed
        and stale_selector_disposition_contract_valid
    )
    signed_source_bound_guard_probe_allowed = bool(
        signed_order_executable_route_probe_allowed
        and explicit_package_source_bound_present_precheck
    )
    action_intent = normalize_scheduler_action_intent(
        first_present(
            option.get("action_class"),
            option.get("scheduler_materialization_action_intent"),
            option.get("effective_action_intent"),
            option.get("action_intent"),
            decision_inputs.get("scheduler_materialization_action_intent"),
            decision_inputs.get("effective_action_intent"),
            decision_inputs.get("action_intent"),
            candidate.get("scheduler_materialization_action_intent"),
            candidate.get("same_symbol_lifecycle_action"),
            candidate.get("gtos_vnext_same_symbol_lifecycle_action"),
            candidate.get("lifecycle_action"),
            candidate.get("action_intent"),
            packets.get("scheduler_materialization_action_intent"),
            packets.get("same_symbol_lifecycle_action"),
            packets.get("gtos_vnext_same_symbol_lifecycle_action"),
            packets.get("lifecycle_action"),
            packets.get("action_intent"),
        )
    )
    pending_replacement = scheduler_option_pending_replacement(option)
    signed_lifecycle_pending_replacement_probe_allowed = bool(
        action_intent == "replace_pending"
        and pending_replacement_runtime_applied(pending_replacement)
        and pending_replacement_runtime_release_pending_ids(pending_replacement)
        and _runtime_bool(
            first_present(
                option.get("package_new_entry_authority_valid"),
                decision_inputs.get("package_new_entry_authority_valid"),
                candidate.get("package_new_entry_authority_valid"),
                packets.get("package_new_entry_authority_valid"),
            ),
            False,
        )
        and not _runtime_bool(
            first_present(
                option.get("package_new_entry_authority_uses_outcome_fields"),
                decision_inputs.get("package_new_entry_authority_uses_outcome_fields"),
                candidate.get("package_new_entry_authority_uses_outcome_fields"),
                packets.get("package_new_entry_authority_uses_outcome_fields"),
            ),
            False,
        )
    )

    def _is_soft_lifecycle_root_veto(reason: str) -> bool:
        if not signed_lifecycle_pending_replacement_probe_allowed:
            return False
        prefix = "package_lifecycle_root_authority_not_allowed:"
        if not reason.startswith(prefix):
            return False
        failure_blob = reason[len(prefix) :]
        failures = {
            item.strip()
            for item in failure_blob.split(",")
            if item.strip()
        }
        return bool(failures) and failures.issubset(
            {
                "pending_replacement_causal_gate_not_passed",
                "pending_replacement_release_ids_missing",
            }
        )

    def _is_soft_scheduler_veto(reason: str) -> bool:
        if any(
            reason.startswith(prefix)
            for prefix in SOFT_SCHEDULER_FINALIZER_VETO_PREFIXES
        ):
            return True
        if (
            signed_source_bound_guard_probe_allowed
            and any(
                reason == guard_reason or reason.startswith(f"{guard_reason}:")
                for guard_reason in SOFT_SCHEDULER_FINALIZER_GUARD_VETO_REASONS
            )
        ):
            return True
        if _is_soft_lifecycle_root_veto(reason):
            return True
        if (
            signed_order_stale_selector_alias_probe_allowed
            and any(
                reason == prefix or reason.startswith(prefix)
                for prefix in SIGNED_ORDER_STALE_SELECTOR_VETO_PREFIXES
            )
        ):
            return True
        if (
            resolved_fill_floor_probe_allowed
            and (
                "package_fill_floor_quality" in reason
                or "candidate_vetoed_package_fill_floor_quality_failed" in reason
            )
        ):
            return True
        if (
            resolved_fill_floor_probe_allowed
            and reason == "selected_cell_or_requested_risk_missing_nonpositive"
        ):
            return True
        return False

    soft_reasons = [
        reason
        for reason in vetoes or [primary, status]
        if _is_soft_scheduler_veto(reason)
    ]
    if contract_soft_reasons:
        soft_reasons = list(dict.fromkeys(contract_soft_reasons + soft_reasons))
        if (
            not contract_pool_eligible
            and not signed_order_stale_selector_alias_probe_allowed
        ):
            failures.append(
                "reallocation_soft_guard_pool_not_eligible:"
                + str(soft_guard_contract.get("reallocation_soft_guard_pool_reason"))
            )
    if not soft_reasons:
        if status == "scheduler_option_score_below_min_trade_score":
            soft_reasons = [status]
        elif status == "scheduler_option_status_not_executable:candidate_below_trade_score_floor":
            soft_reasons = [status]
        elif (
            status == "scheduler_option_runtime_ineligible"
            and explicit_package_executable_allowed_precheck
            and (
                resolved_fill_floor_probe_allowed
                or explicit_package_source_bound_present_precheck
            )
        ):
            soft_reasons = [status]
        else:
            failures.append(f"not_soft_scheduler_veto:{primary or status or 'missing'}")

    hard_vetoes = [
        reason
        for reason in vetoes
        if not _is_soft_scheduler_veto(reason)
    ]
    if hard_vetoes:
        failures.append("hard_scheduler_veto_present:" + "|".join(hard_vetoes))

    cost_block_reason = pretrade_cost_executable_block_reason(
        normalized_pretrade_cost_packet_from_packets(packets),
        enforce=True,
    )
    if cost_block_reason:
        failures.append(cost_block_reason)

    quality_inputs = _scheduler_option_quality_inputs(
        option,
        candidate=candidate,
        packets=packets,
    )
    selector_packet = packets.get("selector_packet")
    selector_packet = selector_packet if isinstance(selector_packet, Mapping) else {}
    pretrade_packet = normalized_pretrade_cost_packet_from_packets(packets)
    expected_net_r = quality_inputs.get("expected_net_r")
    probability = quality_inputs.get("probability")
    fill_probability = quality_inputs.get("fill_probability")
    source_completeness = quality_inputs.get("source_completeness")
    package_seed = {
        **scheduler_package_parity_fields(selector_packet),
        **ultimate_package_member_axis_parity_fields(candidate),
        **dict(candidate),
        **canonical_replay_candidate_instance_fields(candidate),
        "expected_net_r": expected_net_r,
        "candidate_expected_net_r": expected_net_r,
        "probability": probability,
        "candidate_probability": probability,
        "fill_probability": fill_probability,
        "candidate_fill_probability": fill_probability,
        "source_completeness": source_completeness,
        "source_completeness_status": "source_completeness_present",
        "pretrade_cost_packet_status": pretrade_packet.get("status"),
        "cost_authority": pretrade_packet.get("authority"),
        "cost_source_gap_status": pretrade_packet.get("cost_source_gap_status"),
        "candidate_cost_r_fallback_is_authority": pretrade_packet.get(
            "candidate_cost_r_fallback_is_authority"
        ),
    }
    effective_package_signal = ultimate_package_effective_signal_fields(package_seed)
    explicit_package_executable_allowed = _runtime_bool(
        first_present(
            option.get("package_replay_executable_candidate_use_allowed"),
            candidate.get("package_replay_executable_candidate_use_allowed"),
            packets.get("package_replay_executable_candidate_use_allowed"),
            package_seed.get("package_replay_executable_candidate_use_allowed"),
        ),
        False,
    )
    explicit_package_source_bound_present = any(
        _runtime_bool(source.get(field), False)
        for source in (option, candidate, packets, package_seed)
        for field in (
            "source_bound_package_candidate_use_allowed",
            "ultimate_package_source_bound_candidate_use_allowed",
            "package_replay_source_bound_candidate_use_allowed",
            "ultimate_package_effective_source_bound_candidate_use_allowed",
        )
        if isinstance(source, Mapping)
    )
    if (
        effective_package_signal.get("ultimate_package_scheduler_consumed_status")
        != "eligible_for_scheduler_consumption"
        and not (
            explicit_package_executable_allowed
            and explicit_package_source_bound_present
        )
    ):
        failures.append("package_not_executable_source_bound_admission")
    if safe_float(quality_inputs.get("expected_net_r"), 0.0) <= 0.0:
        failures.append("expected_net_r_not_positive")
    scheduler_score = safe_float(option.get("score"), 0.0)
    replacement_reallocation_quality = decision_inputs.get(
        "replacement_reallocation_quality"
    )
    replacement_reallocation_quality = (
        replacement_reallocation_quality
        if isinstance(replacement_reallocation_quality, Mapping)
        else {}
    )
    risk_admitted_scheduler_reallocation_score = safe_float(
        first_present(
            option.get("risk_admitted_scheduler_reallocation_score"),
            decision_inputs.get("risk_admitted_scheduler_reallocation_score"),
            replacement_reallocation_quality.get(
                "risk_admitted_scheduler_reallocation_score"
            ),
            replacement_reallocation_quality.get("score"),
            option.get("replacement_reallocation_quality_score"),
            decision_inputs.get("replacement_reallocation_quality_score"),
        ),
        math.nan,
    )
    risk_admitted_scheduler_reallocation_hard_failures = _list_text_values(
        first_present(
            option.get("risk_admitted_scheduler_reallocation_hard_failures"),
            decision_inputs.get("risk_admitted_scheduler_reallocation_hard_failures"),
            replacement_reallocation_quality.get(
                "risk_admitted_scheduler_reallocation_hard_failures"
            ),
            replacement_reallocation_quality.get("hard_gate_failures"),
            [],
        )
    )
    risk_admitted_scheduler_reallocation_eligible_value = first_present(
        option.get("risk_admitted_scheduler_reallocation_eligible"),
        decision_inputs.get("risk_admitted_scheduler_reallocation_eligible"),
        replacement_reallocation_quality.get(
            "risk_admitted_scheduler_reallocation_eligible"
        ),
    )
    if risk_admitted_scheduler_reallocation_eligible_value is None:
        risk_admitted_scheduler_reallocation_eligible = (
            not risk_admitted_scheduler_reallocation_hard_failures
        )
    else:
        risk_admitted_scheduler_reallocation_eligible = _runtime_bool(
            risk_admitted_scheduler_reallocation_eligible_value,
            False,
        )
    selected_policy_quality_gate = selected_policy_executable_quality_gate_fields(
        option,
        decision_inputs,
        candidate,
        packets,
        package_seed,
        runtime=runtime,
    )
    soft_cap_consumption = consume_soft_cap_executable_transfer_fields(
        selected_policy_quality_gate,
        reallocation_score=risk_admitted_scheduler_reallocation_score,
        reallocation_eligible=risk_admitted_scheduler_reallocation_eligible,
        reallocation_hard_failures=(
            risk_admitted_scheduler_reallocation_hard_failures
        ),
    )
    risk_admitted_scheduler_reallocation_eligible = _runtime_bool(
        soft_cap_consumption.get(
            "soft_cap_executable_transfer_effective_reallocation_eligible"
        ),
        risk_admitted_scheduler_reallocation_eligible,
    )
    risk_admitted_scheduler_reallocation_hard_failures = list(
        soft_cap_consumption.get(
            "soft_cap_executable_transfer_effective_reallocation_hard_failures"
        )
        or []
    )
    signed_order_stale_selector_reallocation_score_bypass_applied = False
    if signed_order_stale_selector_alias_probe_allowed:
        filtered_reallocation_failures = [
            failure
            for failure in risk_admitted_scheduler_reallocation_hard_failures
            if failure != SOFT_CAP_SYNTHETIC_SCORE_FAILURE
        ]
        signed_order_stale_selector_reallocation_score_bypass_applied = bool(
            len(filtered_reallocation_failures)
            != len(risk_admitted_scheduler_reallocation_hard_failures)
            or (
                math.isfinite(risk_admitted_scheduler_reallocation_score)
                and risk_admitted_scheduler_reallocation_score < 0.0
            )
        )
        risk_admitted_scheduler_reallocation_hard_failures = (
            filtered_reallocation_failures
        )
    if (
        math.isfinite(risk_admitted_scheduler_reallocation_score)
        and risk_admitted_scheduler_reallocation_score < 0.0
        and not soft_cap_consumption.get("soft_cap_executable_transfer_consumed")
        and not signed_order_stale_selector_alias_probe_allowed
    ):
        risk_admitted_scheduler_reallocation_eligible = False
        if (
            SOFT_CAP_SYNTHETIC_SCORE_FAILURE
            not in risk_admitted_scheduler_reallocation_hard_failures
        ):
            risk_admitted_scheduler_reallocation_hard_failures.append(
                SOFT_CAP_SYNTHETIC_SCORE_FAILURE
            )
        if SOFT_CAP_SYNTHETIC_SCORE_FAILURE not in failures:
            failures.append(SOFT_CAP_SYNTHETIC_SCORE_FAILURE)
    score_below_finalizer_floor = scheduler_score < min_trade_score
    reallocation_score_floor_override_applied = bool(
        math.isfinite(risk_admitted_scheduler_reallocation_score)
        and risk_admitted_scheduler_reallocation_score >= min_trade_score
        and risk_admitted_scheduler_reallocation_eligible
    )
    score_floor_override_applied = bool(
        score_below_finalizer_floor
        and soft_reasons
        and (
            reallocation_score_floor_override_applied
            or signed_source_bound_guard_probe_allowed
            or signed_order_stale_selector_alias_probe_allowed
            or soft_cap_consumption.get("soft_cap_executable_transfer_consumed")
        )
    )
    if score_below_finalizer_floor and not score_floor_override_applied:
        failures.append("scheduler_score_below_finalizer_floor")

    eligible = not failures
    return {
        "eligible": eligible,
        "failures": failures,
        "soft_reasons": soft_reasons,
        "status": status,
        "primary_runtime_ineligible_reason": primary or None,
        "scheduler_score": scheduler_score,
        "min_trade_score": min_trade_score,
        "scheduler_score_below_finalizer_floor": score_below_finalizer_floor,
        "scheduler_score_floor_replay_probe_override_applied": (
            score_floor_override_applied
        ),
        "risk_admitted_scheduler_reallocation_score": (
            None
            if not math.isfinite(risk_admitted_scheduler_reallocation_score)
            else risk_admitted_scheduler_reallocation_score
        ),
        "risk_admitted_scheduler_reallocation_score_floor_override_applied": (
            reallocation_score_floor_override_applied
        ),
        "risk_admitted_scheduler_reallocation_eligible": (
            risk_admitted_scheduler_reallocation_eligible
        ),
        "risk_admitted_scheduler_reallocation_hard_failures": (
            risk_admitted_scheduler_reallocation_hard_failures
        ),
        "risk_admitted_scheduler_guard_penalty": first_present(
            option.get("risk_admitted_scheduler_guard_penalty"),
            decision_inputs.get("risk_admitted_scheduler_guard_penalty"),
            replacement_reallocation_quality.get(
                "risk_admitted_scheduler_guard_penalty"
            ),
        ),
        "signed_order_executable_route_probe_allowed": (
            signed_order_executable_route_probe_allowed
        ),
        "signed_order_stale_selector_alias_probe_allowed": (
            signed_order_stale_selector_alias_probe_allowed
        ),
        "signed_order_stale_selector_disposition_contract_valid": (
            stale_selector_disposition_contract_valid
        ),
        "signed_order_stale_selector_disposition_contract_failures": list(
            dict.fromkeys(stale_selector_disposition_contract_failures)
        ),
        "signed_order_stale_selector_reallocation_score_bypass_applied": (
            signed_order_stale_selector_reallocation_score_bypass_applied
        ),
        "signed_order_stale_selector_veto_aliases": stale_selector_veto_aliases,
        "signed_order_stale_selector_veto_disposition": (
            dict(stale_selector_disposition) if stale_selector_disposition else None
        ),
        "signed_order_stale_selector_alias_probe_disposition": (
            "finalizer_probe_soft_current_quality_constraints_retained"
            if signed_order_stale_selector_alias_probe_allowed
            else "terminal_current_constraint"
            if stale_selector_veto_aliases
            else "not_applicable"
        ),
        "signed_order_stale_selector_alias_probe_remaining_terminal_vetoes": (
            hard_vetoes
        ),
        "signed_order_stale_selector_alias_probe_source_boundary": (
            "predecision_signed_order_authority_stale_selector_alias_"
            "finalizer_probe_no_outcome_fields"
        ),
        "signed_order_stale_selector_alias_probe_uses_outcome_fields": False,
        "signed_source_bound_guard_probe_allowed": (
            signed_source_bound_guard_probe_allowed
        ),
        "explicit_package_order_executable_allowed_precheck": (
            explicit_package_order_executable_allowed_precheck
        ),
        "explicit_signed_new_entry_authority_valid_precheck": (
            explicit_signed_new_entry_authority_valid_precheck
        ),
        **selected_policy_quality_gate,
        **soft_cap_consumption,
        **soft_guard_contract,
        "stop_hazard_route_risk_cap_pct": stop_hazard_risk_cap_pct,
        "quality_inputs": quality_inputs,
        **effective_package_signal,
    }


