def finalizer_admission_rank_fields(
    probe: Mapping[str, Any],
    option: Mapping[str, Any] | None = None,
    *,
    runtime: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Rank finalizer-admitted alternatives without outcome fields."""

    option = option if isinstance(option, Mapping) else {}
    option_components = option.get("score_components")
    option_components = option_components if isinstance(option_components, Mapping) else {}
    option_decision_inputs = option_components.get("candidate_decision_inputs")
    option_decision_inputs = (
        option_decision_inputs if isinstance(option_decision_inputs, Mapping) else {}
    )

    def _num(*values: Any, default: float = 0.0) -> float:
        for value in values:
            parsed = safe_float(value, math.nan)
            if math.isfinite(parsed):
                return parsed
        return default

    def _text(*values: Any) -> str:
        for value in values:
            if value not in (None, ""):
                return str(value)
        return ""

    risk_admitted = probe.get("risk_admitted") is True
    policy_blocked = bool(probe.get("policy_selection_block_reason"))
    package_executable = _runtime_bool(
        probe.get("package_replay_executable_candidate_use_allowed"),
        False,
    )
    cost_status = _text(
        probe.get("pretrade_cost_packet_status"),
        option.get("pretrade_cost_packet_status"),
    ).upper()
    cost_source_gap_status = _text(
        probe.get("cost_source_gap_status"),
        option.get("cost_source_gap_status"),
    )
    cost_authority = _text(
        probe.get("cost_authority"),
        probe.get("execution_cost_authority"),
        option.get("cost_authority"),
        option.get("execution_cost_authority"),
    )
    cost_fallback_authority = _runtime_bool(
        first_present(
            probe.get("candidate_cost_r_fallback_is_authority"),
            option.get("candidate_cost_r_fallback_is_authority"),
        ),
        False,
    )
    expected_net_r = _num(
        probe.get("causal_finalizer_candidate_expected_net_r"),
        probe.get("candidate_expected_net_r"),
        probe.get("expected_net_r"),
        option.get("candidate_expected_net_r"),
        option.get("expected_net_r"),
        option_decision_inputs.get("candidate_expected_net_r"),
        option_decision_inputs.get("expected_net_r"),
    )
    probability = _num(
        probe.get("causal_finalizer_candidate_probability"),
        probe.get("candidate_probability"),
        probe.get("probability"),
        option.get("candidate_probability"),
        option.get("probability"),
        option_decision_inputs.get("candidate_probability"),
        option_decision_inputs.get("probability"),
    )
    execution_fillability = execution_fillability_alias_fields(
        probe,
        option,
        option_decision_inputs,
    )
    execution_fill_probability_value = _optional_float(
        execution_fillability.get("execution_fill_probability")
    )
    execution_fill_probability_source = str(
        execution_fillability.get("execution_fill_probability_source") or ""
    )
    execution_fill_probability_authority_class = str(
        execution_fillability.get("execution_fill_probability_authority_class")
        or ""
    )
    if execution_fill_probability_value is None:
        atomic_failure = str(
            execution_fillability.get("execution_fillability_atomic_failure") or ""
        )
        if not execution_fill_probability_source:
            execution_fill_probability_source = (
                f"{UNSAFE_PREDECISION_EXECUTION_FILLABILITY_SOURCE}:{atomic_failure}"
                if atomic_failure
                else EXECUTION_FILLABILITY_MISSING_SOURCE
            )
        if not execution_fill_probability_authority_class:
            execution_fill_probability_authority_class = (
                UNSAFE_PREDECISION_EXECUTION_FILLABILITY_SOURCE
                if atomic_failure
                else EXECUTION_FILLABILITY_MISSING_SOURCE
            )
    fill_probability = (
        execution_fill_probability_value
        if execution_fill_probability_value is not None
        else 0.0
    )
    source_completeness = _num(
        probe.get("causal_finalizer_candidate_source_completeness"),
        probe.get("source_completeness"),
        option.get("source_completeness"),
        option_decision_inputs.get("source_completeness"),
    )
    scheduler_score = _num(
        probe.get("causal_finalizer_candidate_scheduler_score"),
        probe.get("scheduler_score"),
        probe.get("score"),
        option.get("score"),
    )
    risk_pct = _num(
        probe.get("final_approved_risk_pct"),
        probe.get("scheduler_approved_risk_pct"),
        option.get("approved_risk_pct"),
        option_decision_inputs.get("scheduler_approved_risk_pct"),
        option_decision_inputs.get("approved_risk_pct"),
    )
    authority_tier = _num(
        probe.get("risk_finalizer_authority_priority_tier"),
        option.get("risk_finalizer_authority_priority_tier"),
        default=0.0,
    )
    reallocation_candidate = _runtime_bool(
        probe.get("causal_finalizer_reallocation_candidate"),
        False,
    )
    zero_trade_conversion_candidate = _runtime_bool(
        probe.get("causal_finalizer_zero_trade_conversion_candidate"),
        False,
    )
    transfer_dominates_original_allowed = _runtime_bool(
        probe.get("risk_finalizer_transfer_dominates_original_allowed"),
        False,
    )
    signed_soft_transfer_displacement_allowed = _runtime_bool(
        probe.get("risk_finalizer_signed_soft_transfer_displacement_allowed"),
        False,
    )
    passive_limit_fallback_degraded = _runtime_bool(
        first_present(
            probe.get("passive_limit_fallback_envelope_degraded_to_passive_queue"),
            option.get("passive_limit_fallback_envelope_degraded_to_passive_queue"),
        ),
        False,
    )
    passive_limit_fallback_rank_penalty = (
        1
        if passive_limit_fallback_degraded
        and not transfer_dominates_original_allowed
        and not signed_soft_transfer_displacement_allowed
        else 0
    )
    original_scheduler_selection_priority = (
        1
        if reallocation_candidate
        and not zero_trade_conversion_candidate
        and not transfer_dominates_original_allowed
        and not signed_soft_transfer_displacement_allowed
        else 0
    )
    signed_soft_transfer_priority = (
        0 if signed_soft_transfer_displacement_allowed else 1
    )
    preserved_rank = _num(
        probe.get("rank"),
        probe.get("scheduler_preserved_rank"),
        option.get("scheduler_preserved_rank"),
        default=999999.0,
    )
    expected_transfer_score = (
        max(0.0, expected_net_r)
        * min(1.0, max(0.0, probability))
        * min(1.0, max(0.0, fill_probability))
        * min(1.0, max(0.0, source_completeness))
        * max(0.0, risk_pct)
    )
    executable_cost_ok = bool(
        cost_status in {"PASSED", "PASS", "OK"}
        and cost_source_gap_status == "source_bound_cost_authority_present"
        and cost_authority == "broker_calibrated_replay_cost"
        and not cost_fallback_authority
    )
    selected_policy_quality_gate = selected_policy_executable_quality_gate_fields(
        probe,
        option,
        option_decision_inputs,
        runtime=runtime,
    )
    sort_key = (
        0 if risk_admitted and not policy_blocked else 1,
        original_scheduler_selection_priority,
        passive_limit_fallback_rank_penalty,
        0 if package_executable else 1,
        0 if executable_cost_ok else 1,
        -round(expected_transfer_score, 12),
        signed_soft_transfer_priority,
        -round(expected_net_r, 12),
        -round(probability, 12),
        -round(fill_probability, 12),
        -round(source_completeness, 12),
        -round(scheduler_score, 12),
        int(authority_tier),
        int(preserved_rank),
        str(probe.get("candidate_id") or option.get("candidate_id") or ""),
        str(probe.get("decision_time_utc") or option.get("decision_time_utc") or ""),
    )
    return {
        "finalizer_admission_rank_key": list(sort_key),
        "finalizer_admission_expected_transfer_score": round(
            expected_transfer_score,
            12,
        ),
        "finalizer_admission_rank_reason": (
            "risk_admitted_signed_soft_transfer_ranked_by_expected_transfer_times_final_risk"
            if risk_admitted
            and not policy_blocked
            and signed_soft_transfer_displacement_allowed
            else
            "risk_admitted_transfer_dominates_original_replay_rank"
            if risk_admitted
            and not policy_blocked
            and transfer_dominates_original_allowed
            else "risk_admitted_original_scheduler_selection_then_predecision_quality_cost_rank"
            if risk_admitted and not policy_blocked
            else "not_rank_selectable"
        ),
        "finalizer_admission_original_scheduler_selection_priority": (
            original_scheduler_selection_priority
        ),
        "finalizer_admission_passive_limit_fallback_degraded_rank_penalty": (
            passive_limit_fallback_rank_penalty
        ),
        "finalizer_admission_passive_limit_fallback_degraded": (
            passive_limit_fallback_degraded
        ),
        "finalizer_admission_transfer_dominates_original_allowed": (
            transfer_dominates_original_allowed
        ),
        "finalizer_admission_signed_soft_transfer_displacement_allowed": (
            signed_soft_transfer_displacement_allowed
        ),
        "finalizer_admission_signed_soft_transfer_displacement_priority": (
            signed_soft_transfer_priority
        ),
        "finalizer_admission_reallocation_candidate": reallocation_candidate,
        "finalizer_admission_zero_trade_conversion_candidate": (
            zero_trade_conversion_candidate
        ),
        "finalizer_admission_rank_source_boundary": (
            FINALIZER_ADMISSION_RANK_SOURCE_BOUNDARY
        ),
        "finalizer_admission_rank_uses_outcome_fields": False,
        "finalizer_admission_executable_cost_ok": executable_cost_ok,
        "finalizer_admission_cost_authority": cost_authority or None,
        "finalizer_admission_cost_source_gap_status": cost_source_gap_status or None,
        "finalizer_admission_pretrade_cost_packet_status": cost_status or None,
        "finalizer_admission_execution_fill_probability": (
            execution_fill_probability_value
        ),
        "finalizer_admission_execution_fill_probability_source": (
            execution_fill_probability_source
        ),
        "finalizer_admission_execution_fill_probability_authority_class": (
            execution_fill_probability_authority_class
        ),
        "finalizer_admission_execution_fill_probability_source_time_utc": (
            execution_fillability.get("execution_fill_probability_source_time_utc")
        ),
        "finalizer_admission_execution_fill_probability_source_boundary": (
            execution_fillability.get("execution_fill_probability_source_boundary")
        ),
        "finalizer_admission_execution_fillability_atomic_surface": (
            execution_fillability.get("execution_fillability_atomic_surface")
        ),
        "finalizer_admission_execution_fillability_atomic_failure": (
            execution_fillability.get("execution_fillability_atomic_failure")
        ),
        **selected_policy_quality_gate,
    }


def scheduler_options_by_candidate_id(
    scheduler_packet: Mapping[str, Any],
) -> dict[str, dict[str, Any]]:
    out: dict[str, dict[str, Any]] = {}

    def source_rank(option: Mapping[str, Any]) -> int:
        source_type = str(
            option.get("source_type")
            or option.get("option_source_type")
            or option.get("scheduler_option_source_type")
            or ""
        )
        if source_type == "new_candidate":
            return 0
        components = option.get("score_components")
        components = components if isinstance(components, Mapping) else {}
        decision_inputs = components.get("candidate_decision_inputs")
        if isinstance(decision_inputs, Mapping) and decision_inputs:
            return 1
        if source_type in {"pending_order", "open_position"}:
            return 2
        action_class = str(option.get("action_class") or "")
        decision_status = str(option.get("decision_status") or "")
        reason = str(option.get("reason") or "")
        if (
            action_class.startswith("pending")
            or decision_status.startswith("pending")
            or reason.startswith("pending")
        ):
            return 2
        return 3

    source_ranks: dict[str, int] = {}
    ambiguous_occurrence_keys: set[str] = set()
    for option in scheduler_ranked_candidate_options(scheduler_packet):
        candidate_id = str(option.get("candidate_id") or "")
        if not candidate_id:
            continue
        option_rank = source_rank(option)
        explicit_instance_key = scheduler_all_options_preserved_option_instance_key(
            option
        )
        instance_keys = [explicit_instance_key] if explicit_instance_key else []
        if not explicit_instance_key.startswith("candidate_occurrence_"):
            instance_keys.extend(
                risk_finalizer_probe_instance_key(candidate_id, option_time)
                for option_time in scheduler_option_exact_time_values(option)
            )
        instance_keys = list(dict.fromkeys(instance_keys))
        for instance_key in instance_keys:
            if not instance_key or instance_key == candidate_id:
                continue
            if explicit_instance_key and instance_key == explicit_instance_key:
                if instance_key in out:
                    out.pop(instance_key, None)
                    source_ranks.pop(instance_key, None)
                    ambiguous_occurrence_keys.add(instance_key)
                    continue
                if instance_key in ambiguous_occurrence_keys:
                    continue
            current_instance_rank = source_ranks.get(instance_key, 99)
            if instance_key not in out or option_rank < current_instance_rank:
                out[instance_key] = option
                source_ranks[instance_key] = option_rank
        if candidate_id not in out or option_rank < source_ranks.get(candidate_id, 99):
            out[candidate_id] = option
            source_ranks[candidate_id] = option_rank
    return out


def scheduler_option_for_candidate(
    options_by_candidate_id: Mapping[str, Mapping[str, Any]],
    candidate_id: Any,
    decision_time_utc: Any = None,
    *,
    candidate_occurrence_key: Any = None,
) -> Mapping[str, Any] | None:
    occurrence_key = str(candidate_occurrence_key or "").strip()
    if occurrence_key:
        option = options_by_candidate_id.get(occurrence_key)
        return option if isinstance(option, Mapping) else None
    cid = str(candidate_id or "").strip()
    exact_key = risk_finalizer_probe_instance_key(candidate_id, decision_time_utc)
    if exact_key and exact_key != cid:
        option = options_by_candidate_id.get(exact_key)
        if isinstance(option, Mapping):
            return option
        seen: set[int] = set()
        for candidate_option in options_by_candidate_id.values():
            if not isinstance(candidate_option, Mapping):
                continue
            marker = id(candidate_option)
            if marker in seen:
                continue
            seen.add(marker)
            if str(candidate_option.get("candidate_id") or "").strip() != cid:
                continue
            if any(
                risk_finalizer_probe_instance_key(cid, option_time) == exact_key
                for option_time in scheduler_option_exact_time_values(candidate_option)
            ):
                return candidate_option
        return None
    option = options_by_candidate_id.get(cid)
    return option if isinstance(option, Mapping) else None


def scheduler_option_candidate_decision_inputs(
    option: Mapping[str, Any] | None,
) -> Mapping[str, Any]:
    if not isinstance(option, Mapping):
        return {}
    components = option.get("score_components")
    components = components if isinstance(components, Mapping) else {}
    decision_inputs = components.get("candidate_decision_inputs")
    return decision_inputs if isinstance(decision_inputs, Mapping) else {}


def scheduler_option_has_candidate_quality_inputs(
    option: Mapping[str, Any] | None,
) -> bool:
    return bool(scheduler_option_candidate_decision_inputs(option))


