def replay_lifecycle_action_resolution_applied(
    *surfaces: Mapping[str, Any] | None,
) -> bool:
    pending: list[Mapping[str, Any]] = [
        surface for surface in surfaces if isinstance(surface, Mapping)
    ]
    seen: set[int] = set()
    while pending:
        surface = pending.pop(0)
        surface_id = id(surface)
        if surface_id in seen:
            continue
        seen.add(surface_id)
        if any(
            _runtime_bool(surface.get(field), False)
            for field in REPLAY_LIFECYCLE_ACTION_RESOLVER_APPLIED_FIELDS
        ):
            return True
        lifecycle_root = surface.get("package_lifecycle_root_authority")
        if isinstance(lifecycle_root, Mapping):
            if (
                _runtime_bool(lifecycle_root.get("applies"), False)
                and _runtime_bool(lifecycle_root.get("allowed"), False)
                and normalize_scheduler_action_intent(
                    first_present(
                        lifecycle_root.get("root_action"),
                        lifecycle_root.get("effective_action_intent"),
                        lifecycle_root.get("target_action_intent"),
                    )
                )
                in SCHEDULER_LIFECYCLE_RECONCILE_ACTION_INTENTS
            ):
                return True
            pending.append(lifecycle_root)
        for nested_key in (
            "score_components",
            "component_scores",
            "candidate_decision_inputs",
            "scheduler_candidate_decision_inputs",
            "decision_inputs",
            "selector_packet",
            "lifecycle_packet",
            "package_same_direction_scale_in_lifecycle_reconcile",
            "package_opposite_side_close_reverse_lifecycle_reconcile",
            "package_pending_replacement_lifecycle_reconcile",
        ):
            nested = surface.get(nested_key)
            if isinstance(nested, Mapping):
                pending.append(nested)
    return False


def replay_current_lifecycle_action_intent(
    *surfaces: Mapping[str, Any] | None,
    allow_legacy_action_class: bool = True,
) -> str | None:
    pending: list[Mapping[str, Any]] = [
        surface for surface in surfaces if isinstance(surface, Mapping)
    ]
    seen: set[int] = set()
    ordered: list[Mapping[str, Any]] = []
    while pending:
        surface = pending.pop(0)
        surface_id = id(surface)
        if surface_id in seen:
            continue
        seen.add(surface_id)
        ordered.append(surface)
        for nested_key in (
            "score_components",
            "component_scores",
            "candidate_decision_inputs",
            "scheduler_candidate_decision_inputs",
            "decision_inputs",
            "selector_packet",
            "lifecycle_packet",
            "package_lifecycle_root_authority",
            "package_same_direction_scale_in_lifecycle_reconcile",
            "package_opposite_side_close_reverse_lifecycle_reconcile",
            "package_pending_replacement_lifecycle_reconcile",
        ):
            nested = surface.get(nested_key)
            if isinstance(nested, Mapping):
                pending.append(nested)
    for surface in ordered:
        lifecycle_root = surface.get("package_lifecycle_root_authority")
        if isinstance(lifecycle_root, Mapping):
            action = normalize_scheduler_action_intent(
                first_present(
                    lifecycle_root.get("root_action"),
                    lifecycle_root.get("effective_action_intent"),
                    lifecycle_root.get("target_action_intent"),
                )
            )
            if action:
                return action
        for key in REPLAY_LIFECYCLE_CURRENT_ACTION_FIELDS:
            raw = surface.get(key)
            terminal = scheduler_terminal_no_new_order_action(raw)
            if terminal:
                return terminal
            action = normalize_scheduler_action_intent(raw)
            if action:
                return action
    if allow_legacy_action_class:
        for surface in ordered:
            for key in REPLAY_LIFECYCLE_LEGACY_ACTION_FIELDS:
                raw = surface.get(key)
                terminal = scheduler_terminal_no_new_order_action(raw)
                if terminal:
                    return terminal
                action = normalize_scheduler_action_intent(raw)
                if action:
                    return action
    return None


def finalized_scheduler_packet_for_selection(
    scheduler_packet: Mapping[str, Any],
    selected_ids: Iterable[Any],
    *,
    finalizer_probe_rows: Iterable[Mapping[str, Any]] | None = None,
    current_candidates: Iterable[Mapping[str, Any]] = (),
    pristine_options_by_occurrence: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    current_candidate_rows = list(current_candidates)
    validate_pristine_scheduler_candidate_options_by_occurrence(
        scheduler_packet,
        current_candidate_rows,
        pristine_options_by_occurrence,
    )
    packet = copy.deepcopy(dict(scheduler_packet))
    selected_tokens = [str(item).strip() for item in selected_ids if str(item or "").strip()]
    packet_asof = first_present(
        packet.get("asof_utc"),
        packet.get("decision_time_utc"),
        packet.get("scheduler_asof_utc"),
    )
    raw_options = packet.get("all_options_preserved")
    all_options = (
        [row for row in raw_options if isinstance(row, Mapping)]
        if isinstance(raw_options, list)
        else []
    )
    options_by_instance: dict[str, list[Mapping[str, Any]]] = {}
    options_by_legacy_id: dict[str, list[Mapping[str, Any]]] = {}
    for candidate_option in all_options:
        option_key = scheduler_all_options_preserved_option_instance_key(
            candidate_option
        )
        option_candidate_id = str(
            candidate_option.get("candidate_id") or ""
        ).strip()
        if option_key:
            options_by_instance.setdefault(option_key, []).append(candidate_option)
        if option_candidate_id:
            options_by_legacy_id.setdefault(option_candidate_id, []).append(
                candidate_option
            )
    ranked_options = scheduler_ranked_candidate_options(packet)
    ranked_by_id: dict[str, Mapping[str, Any]] = {}
    ranked_by_instance: dict[str, Mapping[str, Any]] = {}
    finalizer_probe_by_instance = risk_finalizer_probe_rows_by_candidate_id(
        finalizer_probe_rows
    )
    for ranked_option in ranked_options:
        candidate_key = str(ranked_option.get("candidate_id") or "").strip()
        if candidate_key and candidate_key not in ranked_by_id:
            ranked_by_id[candidate_key] = ranked_option
        ranked_times = scheduler_option_exact_time_values(ranked_option)
        ranked_time = ranked_times[0] if ranked_times else None
        instance_key = scheduler_all_options_preserved_option_instance_key(
            ranked_option
        )
        if instance_key and instance_key not in ranked_by_instance:
            ranked_by_instance[instance_key] = ranked_option
    selected_options: list[Mapping[str, Any]] = []
    selected_id_list: list[str] = []
    selected_instance_keys: list[str] = []
    selected_option_lookup_statuses: list[dict[str, Any]] = []
    occurrence_owners: dict[str, Mapping[str, Any]] = {}
    for current_candidate in current_candidate_rows:
        projection = _candidate_occurrence_association_projection(
            current_candidate
        )
        if not projection:
            continue
        occurrence_key = str(projection[CANDIDATE_OCCURRENCE_KEY_FIELD])
        if occurrence_key in occurrence_owners:
            raise ValueError(
                "finalized_scheduler_candidate_occurrence_owner_not_unique"
            )
        occurrence_owners[occurrence_key] = current_candidate
    if len(selected_tokens) != len(set(selected_tokens)):
        raise ValueError("finalized_scheduler_selection_tokens_not_unique")
    selected_option_instance_keys: set[str] = set()
    for token in selected_tokens:
        candidate_id = token
        decision_time = packet_asof
        occurrence_token = (
            token if token.startswith("candidate_occurrence_") else ""
        )
        if "@@" in token:
            candidate_id, decision_time = token.split("@@", 1)
        candidate_id = str(candidate_id or "").strip()
        if not candidate_id:
            continue
        requested_instance_key = occurrence_token
        if not requested_instance_key and "@@" in token:
            requested_instance_key = token
        if not requested_instance_key and candidate_id and decision_time:
            requested_instance_key = risk_finalizer_probe_instance_key(
                candidate_id, decision_time
            )
        option_matches = (
            options_by_instance.get(requested_instance_key, [])
            if requested_instance_key
            else options_by_legacy_id.get(candidate_id, [])
        )
        legacy_id_fallback_used = False
        if not option_matches and not occurrence_token and "@@" not in token:
            option_matches = options_by_legacy_id.get(candidate_id, [])
            legacy_id_fallback_used = bool(option_matches)
        if len(option_matches) != 1:
            raise ValueError(
                "finalized_scheduler_selection_instance_"
                + ("missing" if not option_matches else "ambiguous")
            )
        option = option_matches[0]
        option_key = scheduler_all_options_preserved_option_instance_key(option)
        if option_key.startswith("candidate_occurrence_"):
            occurrence_owner = occurrence_owners.get(option_key)
            if occurrence_owner is None:
                raise ValueError(
                    "finalized_scheduler_candidate_occurrence_owner_missing"
                )
            association_failures = (
                scheduler_candidate_occurrence_association_failures(
                    option,
                    candidate=occurrence_owner,
                )
            )
            if association_failures:
                raise ValueError(
                    "finalized_scheduler_candidate_occurrence_association_invalid:"
                    + ",".join(association_failures)
                )
        if (
            requested_instance_key
            and not legacy_id_fallback_used
            and option_key != requested_instance_key
        ):
            raise ValueError("finalized_scheduler_selection_instance_mismatch")
        if not option_key or option_key in selected_option_instance_keys:
            raise ValueError("finalized_scheduler_selection_option_not_bijective")
        selected_option_instance_keys.add(option_key)
        lookup_status = (
            "unique_legacy_candidate_id_match_without_exact_selection_token"
            if legacy_id_fallback_used
            else "exact_instance_match"
        )
        if isinstance(option, Mapping):
            actual_candidate_id = str(
                option.get("candidate_id") or candidate_id
            ).strip()
            selected_id_list.append(actual_candidate_id)
            option_for_selection = dict(option)
            option_times_for_rank = scheduler_option_exact_time_values(
                option_for_selection
            )
            option_time_for_rank = (
                option_times_for_rank[0] if option_times_for_rank else None
            )
            option_instance_for_rank = scheduler_all_options_preserved_option_instance_key(
                option_for_selection
            )
            exact_finalizer_probe = (
                finalizer_probe_by_instance.get(option_instance_for_rank)
                if option_instance_for_rank
                else None
            )
            if (
                isinstance(exact_finalizer_probe, Mapping)
                and exact_finalizer_probe.get("selected") is True
            ):
                option_for_selection.update(copy.deepcopy(dict(exact_finalizer_probe)))
                option_for_selection[
                    "risk_finalizer_exact_selected_probe_bound"
                ] = True
                option_for_selection[
                    "risk_finalizer_exact_selected_probe_instance_key"
                ] = option_instance_for_rank
                option_for_selection[
                    "risk_finalizer_exact_selected_probe_hash_sha256"
                ] = stable_sha256(exact_finalizer_probe)
                sync_package_order_authority_into_scheduler_decision_inputs(
                    option_for_selection,
                    components=(
                        option_for_selection.get("score_components")
                        if isinstance(
                            option_for_selection.get("score_components"),
                            Mapping,
                        )
                        else None
                    ),
                )
            ranked_match = (
                ranked_by_instance.get(option_instance_for_rank)
                if option_instance_for_rank
                else None
            )
            if ranked_match is None and not option_instance_for_rank:
                ranked_match = ranked_by_id.get(actual_candidate_id)
            if isinstance(ranked_match, Mapping):
                for key in (
                    "risk_finalizer_transfer_rank",
                    "risk_finalizer_rank",
                    "risk_finalizer_rank_source",
                    "scheduler_original_preserved_rank",
                    "scheduler_preserved_rank",
                    "risk_finalizer_authority_priority_tier",
                    "risk_finalizer_expected_transfer_score",
                ):
                    if ranked_match.get(key) not in (None, ""):
                        option_for_selection[key] = ranked_match.get(key)
            option_for_selection = scheduler_option_with_risk_finalizer_selected_rank(
                option_for_selection,
                selected_rank=len(selected_options) + 1,
                source="finalized_scheduler_packet_for_selection",
            )
            decision_inputs_for_action = scheduler_option_candidate_decision_inputs(
                option
            )
            canonical_action = replay_current_lifecycle_action_intent(
                option_for_selection,
                decision_inputs_for_action,
            )
            if canonical_action:
                option_for_selection["action_class"] = canonical_action
                option_for_selection["scheduler_action_intent"] = canonical_action
                option_for_selection["scheduler_materialization_action_intent"] = (
                    canonical_action
                )
            selected_options.append(option_for_selection)
            option_times = scheduler_option_exact_time_values(option_for_selection)
            option_time = option_times[0] if option_times else None
            instance_key = scheduler_all_options_preserved_option_instance_key(
                option_for_selection
            )
            if instance_key:
                selected_instance_keys.append(instance_key)
            selected_option_lookup_statuses.append(
                {
                    "candidate_id": actual_candidate_id,
                    "requested_token": token,
                    "decision_time_utc": option_time,
                    "selected_instance_key": instance_key,
                    "lookup_status": lookup_status or "matched",
                    "risk_finalizer_exact_selected_probe_bound": (
                        option_for_selection.get(
                            "risk_finalizer_exact_selected_probe_bound"
                        )
                        is True
                    ),
                }
            )
    if len(selected_options) != len(selected_tokens):
        raise ValueError("finalized_scheduler_selection_not_bijective")
    selected_option = selected_options[0] if selected_options else None
    decision = dict(packet.get("decision") if isinstance(packet.get("decision"), Mapping) else {})
    decision.update(
        {
            "selected_option": selected_option,
            "selected_options": selected_options,
            "selected_candidate_id": selected_id_list[0] if selected_id_list else None,
            "selected_candidate_ids": selected_id_list,
            "selected_candidate_instance_key": (
                selected_instance_keys[0] if selected_instance_keys else None
            ),
            "selected_candidate_instance_keys": selected_instance_keys,
            "selected_option_lookup_statuses": selected_option_lookup_statuses,
            "selected_action_class": (
                selected_option.get("action_class")
                if isinstance(selected_option, Mapping)
                else "zero_trade"
            ),
            "selected_action_classes": [
                option.get("action_class") for option in selected_options
            ],
            "approved_risk_pct": (
                round(safe_float(selected_option.get("approved_risk_pct")), 9)
                if isinstance(selected_option, Mapping)
                else 0.0
            ),
            "window_approved_risk_pct": round(
                sum(safe_float(option.get("approved_risk_pct")) for option in selected_options),
                9,
            ),
            "risk_delta_pct": (
                round(safe_float(selected_option.get("risk_delta_pct")), 9)
                if isinstance(selected_option, Mapping)
                else 0.0
            ),
            "runtime_effect_now": False,
            "allocation_mode": (
                "risk_admitted_finalizer_multi_select"
                if len(selected_options) > 1
                else "risk_admitted_finalizer_single_select"
                if selected_options
                else "risk_admitted_finalizer_zero_trade"
            ),
        }
    )
    packet["decision"] = decision
    packet["risk_admitted_scheduler_finalizer_applied"] = True
    packet["risk_admitted_final_selected_candidate_ids"] = selected_id_list
    packet["risk_admitted_final_selected_candidate_instance_keys"] = (
        selected_instance_keys
    )
    packet["risk_admitted_final_selected_option_lookup_statuses"] = (
        selected_option_lookup_statuses
    )
    packet["runtime_effect_now"] = False
    packet["broker_operation"] = False
    packet["order_calls"] = 0
    return packet


def finalized_scheduler_packet_for_option(
    scheduler_packet: Mapping[str, Any],
    option: Mapping[str, Any],
    *,
    allocation_mode: str = "risk_admitted_finalizer_option_probe",
) -> dict[str, Any]:
    """Build a scheduler packet whose selected surface is exactly ``option``."""

    option_copy = scheduler_option_with_risk_finalizer_selected_rank(
        copy.deepcopy(dict(option)),
        selected_rank=1,
        source="finalized_scheduler_packet_for_option",
    )
    candidate_id = str(option_copy.get("candidate_id") or "").strip()
    option_components = option_copy.get("score_components")
    option_components = option_components if isinstance(option_components, Mapping) else {}
    option_decision_inputs = option_components.get("candidate_decision_inputs")
    option_decision_inputs = (
        option_decision_inputs if isinstance(option_decision_inputs, Mapping) else {}
    )
    exact_time_values = scheduler_option_exact_time_values(option_copy)
    option_time = exact_time_values[0] if exact_time_values else None
    identity_fields = canonical_replay_candidate_instance_fields(
        {
            **dict(option_decision_inputs),
            **dict(option_copy),
            "candidate_id": candidate_id,
        },
        decision_time_utc=option_time,
    )
    option_copy.update(identity_fields)
    if option_time:
        option_copy["decision_time_utc"] = option_time
    instance_key = str(
        identity_fields.get("canonical_replay_candidate_instance_key") or ""
    ).strip()
    selectable = bool(
        candidate_id
        and instance_key
        and identity_fields.get("candidate_instance_identity_status") == "materialized"
    )
    lookup_status = (
        "risk_finalizer_option_probe_direct"
        if selectable
        else "risk_finalizer_option_probe_identity_"
        + str(identity_fields.get("candidate_instance_identity_status") or "missing")
    )
    packet = copy.deepcopy(dict(scheduler_packet))
    decision = dict(packet.get("decision") if isinstance(packet.get("decision"), Mapping) else {})
    selected_options = [option_copy] if selectable else []
    decision.update(
        {
            "selected_option": option_copy if selectable else None,
            "selected_options": selected_options,
            "selected_candidate_id": candidate_id if selectable else None,
            "selected_candidate_ids": [candidate_id] if selectable else [],
            "selected_candidate_instance_key": instance_key or None,
            "selected_candidate_instance_keys": [instance_key] if selectable else [],
            "selected_option_lookup_statuses": [
                {
                    "candidate_id": candidate_id,
                    "requested_token": instance_key or candidate_id,
                    "decision_time_utc": option_time,
                    "selected_instance_key": instance_key or None,
                    "lookup_status": lookup_status,
                    "candidate_instance_identity_status": identity_fields.get(
                        "candidate_instance_identity_status"
                    ),
                }
            ]
            if candidate_id
            else [],
            "selected_action_class": (
                option_copy.get("action_class") if selectable else "zero_trade"
            ),
            "selected_action_classes": [
                option_copy.get("action_class")
            ]
            if selectable
            else [],
            "approved_risk_pct": (
                round(safe_float(option_copy.get("approved_risk_pct")), 9)
                if selectable
                else 0.0
            ),
            "window_approved_risk_pct": (
                round(safe_float(option_copy.get("approved_risk_pct")), 9)
                if selectable
                else 0.0
            ),
            "risk_delta_pct": (
                round(safe_float(option_copy.get("risk_delta_pct")), 9)
                if selectable
                else 0.0
            ),
            "runtime_effect_now": False,
            "allocation_mode": allocation_mode if selectable else "risk_admitted_finalizer_zero_trade",
        }
    )
    packet["decision"] = decision
    packet["risk_admitted_scheduler_finalizer_applied"] = True
    packet["risk_admitted_final_selected_candidate_ids"] = (
        [candidate_id] if selectable else []
    )
    packet["risk_admitted_final_selected_candidate_instance_keys"] = (
        [instance_key] if selectable else []
    )
    packet["risk_admitted_final_selected_option_lookup_statuses"] = decision.get(
        "selected_option_lookup_statuses",
        [],
    )
    packet["risk_admitted_finalizer_option_probe_direct"] = True
    packet["runtime_effect_now"] = False
    packet["broker_operation"] = False
    packet["order_calls"] = 0
    return packet


def terminal_no_new_order_scheduler_packet(
    scheduler_packet: Mapping[str, Any],
    terminal_detail: Mapping[str, Any],
) -> dict[str, Any]:
    packet = copy.deepcopy(dict(scheduler_packet))
    action = str(terminal_detail.get("terminal_action") or "").strip()
    decision = dict(packet.get("decision") if isinstance(packet.get("decision"), Mapping) else {})
    decision.update(
        {
            "selected_candidate_id": None,
            "selected_candidate_ids": [],
            "selected_action_class": action or "terminal_no_new_order",
            "selected_action_classes": [action] if action else [],
            "approved_risk_pct": 0.0,
            "window_approved_risk_pct": 0.0,
            "risk_delta_pct": 0.0,
            "runtime_effect_now": False,
            "allocation_mode": "terminal_no_new_order_lifecycle_action",
            "terminal_no_new_order_lifecycle_selected": True,
            "terminal_no_new_order_lifecycle_detail": dict(terminal_detail),
        }
    )
    packet["decision"] = decision
    packet["risk_admitted_scheduler_finalizer_applied"] = False
    packet["risk_admitted_final_selected_candidate_ids"] = []
    packet["terminal_no_new_order_lifecycle_selected"] = True
    packet["terminal_no_new_order_lifecycle_detail"] = dict(terminal_detail)
    packet["runtime_effect_now"] = False
    packet["broker_operation"] = False
    packet["order_calls"] = 0
    return packet


FINALIZER_QUALITY_POLICY_BLOCK_PREFIXES = (
    "causal_reallocation_quality_gate_failed:",
    "causal_zero_trade_conversion_quality_gate_failed:",
    "selected_policy_executable_quality_gate_failed:",
)


def risk_finalizer_policy_reason_is_quality_blocked(reason: Any) -> bool:
    return str(reason or "").strip().startswith(
        FINALIZER_QUALITY_POLICY_BLOCK_PREFIXES
    )


def finalize_scheduler_risk_admitted_selection(
    *,
    scheduler_packet: Mapping[str, Any],
    selected_ids: Iterable[Any],
    all_candidates: Iterable[Mapping[str, Any]],
    v4_packets: Mapping[str, Mapping[str, Any]],
    account: AccountState,
    day: str,
    config: Mapping[str, Any],
    pending_expiry_minutes: float | int | None = None,
    pristine_options_by_occurrence: Mapping[str, Any] | None = None,
) -> tuple[list[str], dict[str, Any]]:
    """Replace post-scheduler risk rejects with the best risk-admitted option."""

    candidate_rows = [
        candidate for candidate in all_candidates if isinstance(candidate, Mapping)
    ]
    validate_pristine_scheduler_candidate_options_by_occurrence(
        scheduler_packet,
        candidate_rows,
        pristine_options_by_occurrence,
    )
    runtime = config.get("gtos_vnext_runtime")
    runtime = runtime if isinstance(runtime, Mapping) else {}
    factorial_binding = b7_5_selection_sizing_factorial_runtime_binding(
        config,
        fail_on_invalid=True,
    )
    factorial_contract_bound = bool(factorial_binding.get("enabled"))
    factorial_r0_active = bool(
        factorial_contract_bound
        and factorial_binding.get("sizing_factor") == "R0"
    )
    factorial_r1_active = bool(
        factorial_contract_bound
        and factorial_binding.get("sizing_factor") == "R1"
    )
    if factorial_contract_bound and factorial_r0_active == factorial_r1_active:
        raise ValueError(
            "b7_5_selection_sizing_factorial_sizing_factor_not_exclusive"
        )
    factorial_neutral_selection_active = bool(
        factorial_contract_bound
        and factorial_binding.get("selection_factor") == "S0"
    )
    factorial_current_selection_active = bool(
        factorial_contract_bound
        and factorial_binding.get("selection_factor") == "S1"
    )
    if (
        factorial_contract_bound
        and factorial_neutral_selection_active
        == factorial_current_selection_active
    ):
        raise ValueError(
            "b7_5_selection_sizing_factorial_selection_factor_not_exclusive"
        )
    factorial_decision_window_id = str(
        scheduler_packet.get("decision_window_id") or ""
    ).strip()
    if factorial_contract_bound and not factorial_decision_window_id:
        raise ValueError(
            "b7_5_selection_sizing_factorial_decision_window_missing"
        )
    enabled = bool(
        runtime.get("scheduler_v4_best_trade_allocator_risk_admitted_finalizer_enabled")
    )
    if factorial_neutral_selection_active and not enabled:
        raise ValueError(
            "b7_5_selection_sizing_factorial_s0_risk_finalizer_disabled"
        )
    original_selected_ids = [str(item) for item in selected_ids if str(item or "").strip()]
