        if canonical_instance_key:
            existing = candidate_by_instance_key.get(canonical_instance_key)
            if existing is not None:
                candidate_by_instance_key.pop(canonical_instance_key, None)
                ambiguous_legacy_instance_keys.add(canonical_instance_key)
            elif canonical_instance_key not in ambiguous_legacy_instance_keys:
                candidate_by_instance_key[canonical_instance_key] = candidate_copy
        instance_time = str(
            first_present(
                candidate.get("decision_time_utc"),
                candidate.get("candle_close_utc"),
                candidate.get("source_candle_time_utc"),
            )
            or ""
        )
        if instance_time:
            candidate_time_key = (candidate_id, instance_time)
            if candidate_time_key in candidate_by_instance:
                candidate_by_instance.pop(candidate_time_key, None)
                ambiguous_candidate_time_keys.add(candidate_time_key)
            elif candidate_time_key not in ambiguous_candidate_time_keys:
                candidate_by_instance[candidate_time_key] = candidate_copy
            instance_key = risk_finalizer_probe_instance_key(candidate_id, instance_time)
