                    candidate.get("package_replay_order_executable_candidate_use_allowed"),
                    packets.get("package_replay_order_executable_candidate_use_allowed"),
                    option.get("package_replay_executable_candidate_use_allowed"),
                    candidate.get("package_replay_executable_candidate_use_allowed"),
                    packets.get("package_replay_executable_candidate_use_allowed"),
