                    option_decision_inputs.get(
                        "package_new_entry_authority_uses_outcome_fields"
                    ),
                    candidate.get("package_new_entry_authority_uses_outcome_fields"),
                    packets.get("package_new_entry_authority_uses_outcome_fields"),
