def segment_policy_asset_class(symbol: Any) -> str | None:
    key = str(symbol or "").strip().upper().replace(".", "_")
    if key in SEGMENT_POLICY_ASSET_CLASS_BY_SYMBOL:
        return SEGMENT_POLICY_ASSET_CLASS_BY_SYMBOL[key]
    if key.endswith("JPY"):
        return "jpy_fx"
    if key.endswith("USD") or key.startswith("USD") or key == "EURGBP":
        return "fx"
    return None


def _segment_policy_table_path(runtime: Mapping[str, Any]) -> str:
    return str(
        first_present(
            runtime.get("moonshot_dynamic_execution_router_segment_policy_table_path"),
            runtime.get(
                "moonshot_dynamic_execution_router_exit_policy_segment_table_path"
            ),
            runtime.get("ultimate_exit_policy_segment_table_path"),
        )
        or ""
    ).strip()


def _load_segment_policy_table_from_runtime(
    runtime: Mapping[str, Any],
) -> dict[str, Any] | None:
    table_path = _segment_policy_table_path(runtime)
    if not table_path:
        return None
    expected_sha = str(
        first_present(
            runtime.get(
                "moonshot_dynamic_execution_router_segment_policy_table_sha256"
            ),
            runtime.get("ultimate_exit_policy_segment_table_sha256"),
        )
        or ""
    ).strip() or None
    resolved_path = Path(table_path)
    if not resolved_path.is_absolute():
        resolved_path = REPO_ROOT / resolved_path
    cache_key = (str(resolved_path), expected_sha)
    if cache_key in _SEGMENT_POLICY_TABLE_CACHE:
        return _SEGMENT_POLICY_TABLE_CACHE[cache_key]
    try:
        table = load_segment_policy_table(resolved_path, expected_sha256=expected_sha)
    except (OSError, ValueError, json.JSONDecodeError):
        _SEGMENT_POLICY_TABLE_CACHE[cache_key] = None
        return None
    _SEGMENT_POLICY_TABLE_CACHE[cache_key] = table
    return table


def segment_policy_resolution_for_candidate(
    *,
    candidate: Mapping[str, Any],
    config: Mapping[str, Any],
    origin_family: Any,
) -> dict[str, Any] | None:
    runtime = config.get("gtos_vnext_runtime") if isinstance(config.get("gtos_vnext_runtime"), Mapping) else {}
    table_path = _segment_policy_table_path(runtime)
    if not table_path:
        return None
    table = _load_segment_policy_table_from_runtime(runtime)
    if table is None:
        return {
            "policy_id": None,
            "family": None,
            "params": {},
            "params_fidelity": None,
            "segment_id": "segment_policy_table_unavailable",
            "fallback_level": "segment_policy_table_unavailable",
            "promoted": False,
            "reason": "segment_policy_table_missing_or_invalid_fail_closed",
            "table_path": table_path,
        }
    source_fields = candidate.get("source_fields") if isinstance(candidate.get("source_fields"), Mapping) else {}
    session_bucket = first_present(
        candidate.get("session_bucket"),
        candidate.get("route_session"),
        candidate.get("session"),
        source_fields.get("session_at_candidate"),
    )
    return resolve_segment_policy(
        table,
        asset_class=segment_policy_asset_class(candidate.get("symbol")),
        origin_family=origin_family,
        session_bucket=session_bucket,
    )


GENERIC_PACKAGE_ORIGIN_KEYS = frozenset(
    {
        "",
        "unknown",
        "none",
        "null",
        "broader_origin",
        "origin_broader_origin",
        "package",
        "ultimate_candidate_package",
    }
)


def normalized_package_origin_family(value: Any) -> str:
    key = str(value or "").strip().lower().replace("-", "_").replace(" ", "_")
    if key.startswith("origin_"):
        key = key.removeprefix("origin_")
    return key


def _iter_text_values(value: Any) -> tuple[str, ...]:
    if value in (None, ""):
        return ()
    if isinstance(value, str):
        return tuple(part.strip() for part in value.split(",") if part.strip())
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        text = str(value).strip()
        return (text,) if text else ()
    if isinstance(value, (list, tuple, set, frozenset)):
        values: list[str] = []
        for item in value:
            if isinstance(item, str):
                values.extend(part.strip() for part in item.split(",") if part.strip())
            elif isinstance(item, (int, float)) and not isinstance(item, bool):
                text = str(item).strip()
                if text:
                    values.append(text)
        return tuple(values)
    return ()


def package_sleeve_origin_families_for_candidate(
    candidate: Mapping[str, Any],
) -> tuple[str, ...]:
    values: list[str] = []
    for source in (
        candidate,
        candidate.get("ultimate_candidate_package")
        if isinstance(candidate.get("ultimate_candidate_package"), Mapping)
        else {},
        candidate.get("ultimate_package")
        if isinstance(candidate.get("ultimate_package"), Mapping)
        else {},
    ):
        if not isinstance(source, Mapping):
            continue
        for key in (
            "ultimate_package_matched_sleeve_ids",
            "matched_sleeve_ids",
            "package_matched_sleeve_ids",
            "ultimate_package_matched_member_axis_ids",
            "matched_member_axis_ids",
        ):
            values.extend(_iter_text_values(source.get(key)))
    families: list[str] = []
    for sleeve_id in values:
        parts = [
            normalized_package_origin_family(part)
            for part in str(sleeve_id).split("__")
        ]
        parts = [part for part in parts if part]
        if len(parts) >= 3 and parts[-1] in {"long", "short"}:
            family = parts[-2]
            if family and family not in GENERIC_PACKAGE_ORIGIN_KEYS:
                families.append(family)
                continue
        for part in parts:
            if (
                part
                and part not in GENERIC_PACKAGE_ORIGIN_KEYS
                and not part.endswith("sleeve")
                and part not in {"long", "short", "buy", "sell"}
            ):
                families.append(part)
                break
    return tuple(dict.fromkeys(families))


def package_origin_family_for_candidate(candidate: Mapping[str, Any]) -> str:
    source_fields = (
        candidate.get("source_fields")
        if isinstance(candidate.get("source_fields"), Mapping)
        else {}
    )
    package_families = package_sleeve_origin_families_for_candidate(candidate)
    for value in (
        candidate.get("origin_family"),
        candidate.get("candidate_origin_family"),
        source_fields.get("generation_rule"),
    ):
        family = normalized_package_origin_family(value)
        if family and family not in GENERIC_PACKAGE_ORIGIN_KEYS:
            return family
    if package_families:
        return package_families[0]
    framework = normalized_package_origin_family(candidate.get("framework"))
    if framework and framework not in GENERIC_PACKAGE_ORIGIN_KEYS:
        return framework
    return "unknown"


def dynamic_policy_router_event(
    *,
    candidate: Mapping[str, Any],
    config: Mapping[str, Any],
    risk_pct: float,
) -> dict[str, Any]:
    runtime = config.get("gtos_vnext_runtime") if isinstance(config.get("gtos_vnext_runtime"), Mapping) else {}
    source_fields = candidate.get("source_fields") if isinstance(candidate.get("source_fields"), Mapping) else {}
    package_origin_families = package_sleeve_origin_families_for_candidate(candidate)
    origin_family = package_origin_family_for_candidate(candidate)
    if origin_family.startswith("origin_"):
        candidate_origin_family = origin_family
    else:
        candidate_origin_family = f"origin_{origin_family}"
    atr14 = safe_float(source_fields.get("atr14"), 0.0)
    displacement = None
    if atr14 > 0:
        displacement = abs(
            safe_float(source_fields.get("close")) - safe_float(source_fields.get("open"))
        ) / atr14
    event = {
        "symbol": candidate.get("symbol"),
        "side": candidate.get("side"),
        "decision_time_utc": candidate.get("decision_time_utc")
        or candidate.get("candle_close_utc"),
        "asof_utc": candidate.get("decision_time_utc") or candidate.get("candle_close_utc"),
        "utc_hour_bucket": candidate.get("utc_hour_bucket"),
        "route_session": candidate.get("route_session") or candidate.get("session"),
        "framework": candidate.get("framework") or origin_family,
        "route_family": candidate.get("route_family") or origin_family,
        "candidate_origin_family": candidate_origin_family,
        "package_origin_family": (
            package_origin_families[0] if package_origin_families else None
        ),
        "package_sleeve_origin_families": list(package_origin_families),
        "session_bucket": candidate.get("session_bucket") or source_fields.get("session_at_candidate"),
        "origin_family": origin_family,
        "current_bar_displacement_atr14": displacement,
        "candidate_quality_selector_enabled": runtime.get(
            "moonshot_candidate_quality_selector_enabled"
        ),
        "candidate_quality_selector_apply_to_execution": runtime.get(
            "moonshot_candidate_quality_selector_apply_to_execution"
        ),
        "candidate_quality_selector_tradeable_rules": (
            _moonshot_candidate_quality_selector_rules(dict(runtime))
        ),
        "spread_r_at_candidate": candidate.get("spread_r_at_candidate"),
        "candidate_quality_selector_max_spread_r": runtime.get(
            "moonshot_candidate_quality_selector_max_spread_r"
        ),
        "candidate_quality_selector_evidence_path": runtime.get(
            "moonshot_candidate_quality_selector_evidence_path"
        ),
        "candidate_quality_selector_package_path": runtime.get(
            "moonshot_candidate_quality_selector_package_path"
        ),
        "primary_policy": runtime.get("moonshot_dynamic_execution_router_policy"),
        "moonshot_dynamic_execution_router_policy": runtime.get(
            "moonshot_dynamic_execution_router_policy"
        ),
        "partial_exception_policy": runtime.get(
            "moonshot_dynamic_execution_router_momentum_exception_policy"
        ),
        "moonshot_dynamic_execution_router_momentum_exception_policy": runtime.get(
            "moonshot_dynamic_execution_router_momentum_exception_policy"
        ),
        "partial_exception_origin_families": runtime.get(
            "moonshot_dynamic_execution_router_momentum_exception_origin_families_to_partial_be_runner"
        ),
        "moonshot_dynamic_execution_router_momentum_exception_origin_families_to_partial_be_runner": runtime.get(
            "moonshot_dynamic_execution_router_momentum_exception_origin_families_to_partial_be_runner"
        ),
        "condition_challenger_enabled": runtime.get(
            "moonshot_dynamic_execution_router_condition_challenger_enabled"
        ),
        "policy_router_mode": runtime.get(
            "moonshot_dynamic_execution_router_condition_challenger_policy"
        ),
        "required_branch_labels": runtime.get(
            "moonshot_dynamic_execution_router_required_branch_labels"
        ),
        "activated_frameworks": runtime.get(
            "moonshot_dynamic_execution_router_activated_frameworks"
        ),
        "activated_origin_families": runtime.get(
            "moonshot_dynamic_execution_router_activated_origin_families"
        ),
        "broader_origin_allowed": True,
        "live_generation_status": "generated_live_asof_timewarp_replay",
        "source_mode": runtime.get(
            "moonshot_dynamic_execution_router_default_source_mode",
            "OHLC_MT5_FTMO_TIMEWARP_REPLAY",
        ),
        "source_path_feature_status": "computed_from_source_ohlc_asof_timewarp_replay",
        "source_window_complete": True,
        "ordered_path_status": "ordered_path_pending_postdecision_replay",
        "selected_policy_ordered_path_status": "ordered_path_pending_postdecision_replay",
        "selected_policy_same_bar_ambiguous": False,
        "kill_zone_position": router_kill_zone_position(candidate, source_fields),
        "require_configured_kill_zone": runtime.get(
            "moonshot_dynamic_execution_router_require_configured_kill_zone"
        ),
        "broker_native_eligible_symbols": runtime.get(
            "moonshot_dynamic_execution_router_broker_native_eligible_symbols"
        ),
        "broker_native_exact_excluded_symbols": runtime.get(
            "moonshot_dynamic_execution_router_broker_native_exact_excluded_symbols"
        ),
        "broker_native_eligible": True,
        "runtime_instrument_configured": True,
        "selected_cell_risk_required": True,
        "selected_cell_risk_allowed": risk_pct > 0,
        "selected_cell_risk_pct": risk_pct,
        "selected_cell_risk_cell_id": f"timewarp:{candidate.get('candidate_id')}",
        "selected_cell_risk_decision_basis": "simulated_replay_runtime_risk_authority",
    }
    segment_resolution = segment_policy_resolution_for_candidate(
        candidate=candidate,
        config=config,
        origin_family=origin_family,
    )
    if segment_resolution:
        event["segment_policy_resolution"] = segment_resolution
        event["segment_policy_params_consumer_ready"] = _runtime_bool(
            runtime.get(
                "moonshot_dynamic_execution_router_segment_policy_params_consumer_ready"
            )
            if "moonshot_dynamic_execution_router_segment_policy_params_consumer_ready"
            in runtime
            else runtime.get(
                "moonshot_dynamic_execution_router_segment_policy_apply_to_replay",
                False,
            ),
            False,
        )
    return event


def dynamic_policy_router_record(
    *,
    candidate: Mapping[str, Any],
    config: Mapping[str, Any],
    risk_pct: float,
) -> dict[str, Any]:
    runtime = config.get("gtos_vnext_runtime") if isinstance(config.get("gtos_vnext_runtime"), Mapping) else {}
    decision = route_moonshot_dynamic_execution(
        dynamic_policy_router_event(candidate=candidate, config=config, risk_pct=risk_pct),
        enabled=bool(runtime.get("moonshot_dynamic_execution_router_enabled", True)),
        apply_to_execution=bool(
            runtime.get("moonshot_dynamic_execution_router_apply_to_execution", True)
        ),
    )
    return decision.to_record()


def selected_policy_params_from_router_record(
    policy_router_record: Mapping[str, Any] | None,
) -> dict[str, Any]:
    if not isinstance(policy_router_record, Mapping):
        return {}
    dimensions = policy_router_record.get("route_dimensions")
    dimensions = dimensions if isinstance(dimensions, Mapping) else {}
    params = dimensions.get("selected_policy_params")
    if isinstance(params, Mapping):
        return dict(params)
    segment = dimensions.get("segment_exit_policy")
    segment = segment if isinstance(segment, Mapping) else {}
    params = segment.get("selected_policy_params")
    return dict(params) if isinstance(params, Mapping) else {}


def dynamic_geometry_trade_params_from_policy_params(
    policy_params: Mapping[str, Any] | None,
) -> dict[str, Any]:
    params = policy_params if isinstance(policy_params, Mapping) else {}
    if not params:
        return {}
    output: dict[str, Any] = {}
    final_target_r = first_present(params.get("final_target_r"), params.get("target_r"))
    trigger_r = first_present(
        params.get("trigger_r"),
        params.get("tp1_r"),
        params.get("trailing_trigger_r"),
        params.get("micro_partial_trigger_r"),
        params.get("min_mfe_r"),
    )
    trail_gap_r = first_present(params.get("trail_gap_r"), params.get("trailing_gap_r"))
    momentum_pullback_r = first_present(
        params.get("momentum_pullback_r"),
        params.get("pullback_r"),
        params.get("giveback_r"),
        params.get("giveback_close_r"),
        params.get("momentum_giveback_r"),
    )
    partial_close_ratio = first_present(
        params.get("partial_close_ratio"),
        params.get("micro_partial_close_ratio"),
    )
    time_stop_bars = first_present(
        params.get("time_stop_bars"),
        params.get("bars"),
        params.get("stale_thesis_bars"),
    )
    if final_target_r not in (None, ""):
        output["gtos_vnext_dynamic_final_target_r"] = final_target_r
    if trigger_r not in (None, ""):
        output["gtos_vnext_dynamic_be_trigger_r"] = trigger_r
    if trail_gap_r not in (None, ""):
        output["gtos_vnext_dynamic_trail_gap_r"] = trail_gap_r
    if momentum_pullback_r not in (None, ""):
        output["gtos_vnext_dynamic_momentum_pullback_r"] = momentum_pullback_r
    if partial_close_ratio not in (None, ""):
        output["gtos_vnext_dynamic_partial_close_ratio"] = partial_close_ratio
    if time_stop_bars not in (None, ""):
        output["gtos_vnext_dynamic_time_stop_bars"] = time_stop_bars
    output["gtos_vnext_dynamic_policy_params_source"] = (
        "segment_exit_policy_resolution"
    )
    return output


def build_probability_context(
    candidate: Mapping[str, Any],
    asof_utc: str,
    mso: Any,
    *,
    cost_r: float | None = None,
) -> dict[str, Any]:
    side_action = side_to_probability_action(str(candidate.get("side") or ""))
    signal = candidate_feature_signal(candidate, mso)
    rr = signal["rr"]
    follow_strength = signal["follow_strength"]
    reliability = signal["reliability"]
    source_complete = signal["source_completeness"]
    mso_follow = safe_float(signal["mso_signal"].get("follow_ratio"), 0.0)
    mixed = safe_float(signal["mso_signal"].get("mixed_ratio"), 1.0)
    cost_r = safe_float(
        cost_r,
        safe_float(
            candidate.get("broker_calibrated_expected_cost_r")
            or candidate.get("expected_cost_r")
            or candidate.get("cost_r"),
            0.12,
        ),
    )
    sources = [
        {
            "source_id": f"{candidate.get('candidate_id')}:selector",
            "source_family": "selector",
            "stance": "FOLLOW",
            "action": side_action,
            "direction": candidate.get("side"),
            "strength": follow_strength,
            "confidence": _clamp_float(reliability + 0.08, 0.20, 0.98),
            "reliability": reliability,
            "freshness": 1.0,
            "source_completeness": source_complete,
            "cost_sensitivity": cost_r,
            "evidence_class": SOURCE_BOUND_EVIDENCE_CLASS,
            "as_of_utc": asof_utc,
        },
        {
            "source_id": f"{candidate.get('candidate_id')}:market_state",
            "source_family": "market_state",
            "stance": "FOLLOW",
            "action": side_action,
            "direction": candidate.get("side"),
            "strength": _clamp_float(mso_follow, 0.05, 0.98),
            "confidence": _clamp_float(1.0 - mixed * 0.45, 0.20, 0.95),
            "reliability": _clamp_float(reliability + mso_follow * 0.10, 0.20, 0.98),
            "freshness": 1.0,
            "source_completeness": source_complete,
            "cost_sensitivity": cost_r * 0.75,
            "evidence_class": SOURCE_BOUND_EVIDENCE_CLASS,
            "as_of_utc": asof_utc,
        },
        {
            "source_id": f"{candidate.get('candidate_id')}:cost",
            "source_family": "cost",
            "stance": "MIXED",
            "action": "wait",
            "direction": candidate.get("side"),
            "strength": _clamp_float(cost_r, 0.01, 0.40),
            "confidence": _clamp_float(1.0 - cost_r, 0.35, 0.95),
            "reliability": _clamp_float(1.0 - cost_r * 2.0, 0.25, 0.90),
            "freshness": 1.0,
            "source_completeness": _clamp_float(source_complete - 0.15, 0.20, 1.0),
            "cost_sensitivity": cost_r,
            "evidence_class": SOURCE_BOUND_EVIDENCE_CLASS,
            "as_of_utc": asof_utc,
        },
        {
            "source_id": f"{candidate.get('candidate_id')}:lifecycle",
            "source_family": "lifecycle",
            "stance": "FOLLOW",
            "action": side_action,
            "direction": candidate.get("side"),
            "strength": _clamp_float(0.20 + follow_strength * 0.60, 0.05, 0.95),
            "confidence": _clamp_float(reliability, 0.20, 0.95),
            "reliability": _clamp_float(reliability, 0.20, 0.95),
            "freshness": 1.0,
            "source_completeness": _clamp_float(source_complete - 0.05, 0.20, 1.0),
            "cost_sensitivity": cost_r * 0.5,
            "evidence_class": SOURCE_BOUND_EVIDENCE_CLASS,
            "as_of_utc": asof_utc,
        },
        {
            "source_id": f"{candidate.get('candidate_id')}:source_completeness",
            "source_family": "source_completeness",
            "stance": "DIRECT",
            "action": side_action,
            "direction": candidate.get("side"),
            "strength": source_complete,
            "confidence": _clamp_float(source_complete, 0.20, 0.98),
            "reliability": _clamp_float(source_complete, 0.20, 0.98),
            "freshness": 1.0,
            "source_completeness": source_complete,
            "cost_sensitivity": cost_r * 0.25,
            "evidence_class": SOURCE_BOUND_EVIDENCE_CLASS,
            "as_of_utc": asof_utc,
        },
    ]
    return {
        "candidate_id": candidate.get("candidate_id"),
        "symbol": candidate.get("symbol"),
        "side": candidate.get("side"),
        "as_of_utc": asof_utc,
        "reward_r": rr,
        "loss_r": 1.0,
        "base_probability": _clamp_float(
            0.35 + follow_strength * 0.38 + reliability * 0.18 - cost_r * 0.15,
            0.20,
            0.88,
        ),
        "sources": sources,
        "source_boundary": "asof_closed_d1_h4_h1_m15_no_outcome_fields",
        "candidate_feature_signal": signal,
    }
def probability_thesis(record: Mapping[str, Any], action: str) -> dict[str, Any]:
    theses = record.get("theses") if isinstance(record.get("theses"), list) else []
    for thesis in theses:
        if isinstance(thesis, Mapping) and str(thesis.get("action")) == action:
            return dict(thesis)
    return {}


def build_selector_event(
    *,
    candidate: Mapping[str, Any],
    probability_record: Mapping[str, Any],
    lifecycle_packet: Mapping[str, Any],
    risk_pct: float,
    cost_r: float,
    pretrade_cost_packet: Mapping[str, Any] | None = None,
    asof_utc: str,
    mso: Any,
    policy_router_record: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    action = side_to_probability_action(str(candidate.get("side") or ""))
    thesis = probability_thesis(probability_record, action)
    ev = safe_float(thesis.get("EV") or thesis.get("ev_r"), 0.2)
    expected_net_r = round(ev - safe_float(cost_r, 0.0), 12)
    source_id = str(candidate.get("candidate_id"))
    signal = candidate_feature_signal(candidate, mso)
    follow_strength = safe_float(signal.get("follow_strength"), 0.5)
    reliability = safe_float(signal.get("reliability"), 0.5)
    source_complete = safe_float(signal.get("source_completeness"), 0.75)
    mso_follow = safe_float((signal.get("mso_signal") or {}).get("follow_ratio"), 0.0)
    mso_oppose = safe_float((signal.get("mso_signal") or {}).get("oppose_ratio"), 0.0)
    cost_strength = _clamp_float(cost_r, 0.01, 0.45)
    heuristic_fill_probability = _clamp_float(
        0.25
        + safe_float(thesis.get("probability"), 0.45) * 0.35
        + source_complete * 0.20
        + safe_float(signal.get("volatility_balance"), 0.5) * 0.20,
        0.05,
        0.95,
    )
    limit_fillability = candidate_predecision_limit_fillability_signal(candidate)
    limit_fillability_probability = (
        _clamp_float(
            safe_float(limit_fillability.get("fill_probability"), 0.0),
            0.03,
            0.95,
        )
        if limit_fillability.get("available") is True
        else None
    )
    entry_quality_fill_probability = heuristic_fill_probability
    fill_probability = entry_quality_fill_probability
    market_label = "FOLLOW" if mso_follow >= 0.50 else ("AVOID" if mso_oppose >= 0.50 else "MIXED")
    cost_label = "FOLLOW" if cost_r <= 0.08 else ("MIXED" if cost_r <= 0.14 else "AVOID")
    policy_router_record = (
        policy_router_record if isinstance(policy_router_record, Mapping) else {}
    )
    pretrade_cost_packet = (
        pretrade_cost_packet if isinstance(pretrade_cost_packet, Mapping) else {}
    )
    dynamic_policy = (
        candidate.get("dynamic_geometry_policy")
        or policy_router_record.get("selected_policy")
    )
    confluence_sources = [
        {
            "source_id": f"{source_id}:origin_family_follow",
            "label": "FOLLOW",
            "source_family": "selector",
            "direction": candidate.get("side"),
            "score": follow_strength,
            "strength": follow_strength,
            "confidence": _clamp_float(reliability + 0.05, 0.20, 0.98),
            "reliability": reliability,
            "reliability_history": reliability,
            "freshness": 1.0,
            "source_completeness": source_complete,
            "cost_sensitivity": cost_r,
            "evidence_class": SOURCE_BOUND_EVIDENCE_CLASS,
            "as_of_utc": asof_utc,
        },
        {
            "source_id": f"{source_id}:market_state_follow",
            "label": market_label,
            "source_family": "market_state",
            "direction": candidate.get("side"),
            "score": mso_follow if market_label == "FOLLOW" else max(mso_follow, mso_oppose),
            "strength": mso_follow if market_label == "FOLLOW" else max(mso_follow, mso_oppose),
            "confidence": _clamp_float(0.35 + mso_follow * 0.60, 0.20, 0.95),
            "reliability": _clamp_float(reliability + mso_follow * 0.10, 0.20, 0.98),
            "reliability_history": _clamp_float(reliability + mso_follow * 0.10, 0.20, 0.98),
            "freshness": 1.0,
            "source_completeness": source_complete,
            "cost_sensitivity": cost_r * 0.75,
            "conflict_reason": "mixed_mso_timeframe_alignment" if market_label == "MIXED" else None,
            "invalidation_type": "mso_opposes_candidate_direction" if market_label == "AVOID" else None,
            "evidence_class": SOURCE_BOUND_EVIDENCE_CLASS,
            "as_of_utc": asof_utc,
        },
        {
            "source_id": f"{source_id}:pretrade_cost_mixed",
            "label": cost_label,
            "source_family": "cost",
            "direction": candidate.get("side"),
            "score": cost_strength,
            "strength": cost_strength,
            "confidence": _clamp_float(1.0 - cost_r, 0.35, 0.95),
            "reliability": _clamp_float(1.0 - cost_r * 2.0, 0.25, 0.90),
            "reliability_history": _clamp_float(1.0 - cost_r * 2.0, 0.25, 0.90),
            "freshness": 1.0,
            "source_completeness": _clamp_float(source_complete - 0.15, 0.20, 1.0),
            "cost_sensitivity": cost_r,
            "conflict_reason": "proxy_cost_borderline_for_selector" if cost_label == "MIXED" else None,
            "invalidation_type": "expected_cost_above_clean_follow_band" if cost_label == "AVOID" else None,
            "evidence_class": SOURCE_BOUND_EVIDENCE_CLASS,
            "as_of_utc": asof_utc,
        },
        {
            "source_id": f"{source_id}:lifecycle_no_duplicate",
            "label": "FOLLOW",
            "source_family": "lifecycle",
            "direction": candidate.get("side"),
            "score": _clamp_float(0.20 + follow_strength * 0.60, 0.05, 0.95),
            "strength": _clamp_float(0.20 + follow_strength * 0.60, 0.05, 0.95),
            "confidence": reliability,
            "reliability": reliability,
            "reliability_history": reliability,
            "freshness": 1.0,
            "source_completeness": _clamp_float(source_complete - 0.05, 0.20, 1.0),
            "cost_sensitivity": cost_r * 0.50,
            "evidence_class": SOURCE_BOUND_EVIDENCE_CLASS,
            "as_of_utc": asof_utc,
        },
        {
            "source_id": f"{source_id}:source_complete",
            "label": "FOLLOW",
            "source_family": "source_completeness",
            "direction": candidate.get("side"),
            "score": source_complete,
            "strength": source_complete,
            "confidence": source_complete,
            "reliability": source_complete,
            "reliability_history": source_complete,
            "freshness": 1.0,
            "source_completeness": source_complete,
            "cost_sensitivity": cost_r * 0.25,
            "evidence_class": SOURCE_BOUND_EVIDENCE_CLASS,
            "as_of_utc": asof_utc,
        },
    ]
    package_origin_families = package_sleeve_origin_families_for_candidate(candidate)
    selector_origin_family = package_origin_family_for_candidate(candidate)
    selector_candidate_origin_family = first_present(
        candidate.get("candidate_origin_family"),
        f"origin_{selector_origin_family}" if selector_origin_family else None,
    )
    package_attribution = package_execution_attribution_fields(candidate)
    selected_policy_expected_net_attribution = {
        key: candidate.get(key)
        for key in OWNER_APPROVED_RECONSTRUCTED_PROXY_SELECTED_POLICY_EXPECTED_NET_KEYS
        if candidate.get(key) not in (None, "", [], {})
    }
    event = {
        "candidate_id": source_id,
        "symbol": candidate.get("symbol"),
        "side": candidate.get("side"),
        "direction": candidate.get("side"),
        "decision_time_utc": asof_utc,
        "asof_utc": asof_utc,
        "candle_close_utc": candidate.get("candle_close_utc") or asof_utc,
        "fill_probability": fill_probability,
        "heuristic_fill_probability": heuristic_fill_probability,
        "entry_quality_fill_probability": entry_quality_fill_probability,
        "limit_fillability_probability": limit_fillability_probability,
        "predecision_limit_fillability_probability": limit_fillability_probability,
        "predecision_limit_fillability": limit_fillability,
        "source_completeness": source_complete,
        "candidate_probability": safe_float(thesis.get("probability"), 0.55),
        "probability": safe_float(thesis.get("probability"), 0.55),
        "candidate_ev_r": ev,
        "ev_r": ev,
        "expectancy_r": ev,
        "expected_cost_r": cost_r,
        "cost_r": cost_r,
        "broker_calibrated_expected_cost_r": cost_r,
        "broker_pretrade_cost_r": cost_r,
        "candidate_expected_net_r": expected_net_r,
        "expected_net_r": expected_net_r,
        "route_session": candidate.get("route_session"),
        "session_bucket": candidate.get("session_bucket") or candidate.get("route_session"),
        "session": candidate.get("session") or candidate.get("route_session"),
        "framework": candidate.get("framework"),
        "origin_family": selector_origin_family,
        "candidate_origin_family": selector_candidate_origin_family,
        "package_origin_family": (
            package_origin_families[0] if package_origin_families else None
        ),
        "package_sleeve_origin_families": list(package_origin_families),
        "dynamic_geometry_policy": dynamic_policy,
        "moonshot_dynamic_execution_router_v4": dict(policy_router_record),
        **selected_policy_expected_net_attribution,
        "utc_hour_bucket": candidate.get("utc_hour_bucket"),
        "package_session_tokens": sorted(
            session_tokens_for_package_candidate(
                {
                    **dict(candidate),
                    "decision_time_utc": asof_utc,
                    "asof_utc": asof_utc,
                }
            )
        ),
        **package_attribution,
        "numeric_confluence": {
            "sources": confluence_sources,
            "source_event_hash_sha256": stable_sha256(confluence_sources),
        },
        "probability_debate": probability_record,
        "selected_cell": {
            "cell_id": f"timewarp:{source_id}",
            "broker_net_expectancy_r": ev,
            "stress_expectancy_r": max(0.0, ev - cost_r),
            "risk_pct": risk_pct,
            "source_completeness": source_complete,
            "evidence_class": SOURCE_BOUND_EVIDENCE_CLASS,
        },
        "cost": {
            "expected_total_cost_r": cost_r,
            "broker_net_cost_r": cost_r,
            "total_cost_r": cost_r,
            "spread_r": pretrade_cost_packet.get("spread_r"),
            "commission_r": pretrade_cost_packet.get("commission_r", 0.0),
            "swap_r": (
                (pretrade_cost_packet.get("swap_cost") or {}).get("cost_r")
                if isinstance(pretrade_cost_packet.get("swap_cost"), Mapping)
                else None
            ),
            "slippage_stress_r": pretrade_cost_packet.get("expected_slippage_r"),
            "pretrade_cost_model": pretrade_cost_packet.get("model_version")
            or "broker_calibrated_replay_cost_missing_packet",
            "pretrade_broker_net_cost_packet": dict(pretrade_cost_packet),
            "candidate_cost_r_fallback_diagnostic": pretrade_cost_packet.get(
                "old_timewarp_candidate_cost_r_fallback_diagnostic"
            ),
            "old_proxy_vs_broker_calibrated_delta_r": pretrade_cost_packet.get(
                "old_proxy_vs_broker_calibrated_delta_r"
            ),
            "source_completeness": 0.95,
            "evidence_class": SOURCE_BOUND_EVIDENCE_CLASS,
        },
        "lifecycle": {
            "duplicate_exposure": False,
            "same_symbol_conflict": "bound_by_same_symbol_lifecycle_v4_packet",
            "open_trade_competition_status": "candidate_vs_simulated_open_pending_state",
            "source_completeness": 0.85,
            "evidence_class": SOURCE_BOUND_EVIDENCE_CLASS,
            "same_symbol_lifecycle_v4_packet": lifecycle_packet,
        },
        "candidate_feature_signal": signal,
    }
    event = merge_predecision_market_snapshot_transfer_payload(
        event,
        predecision_market_snapshot_transfer_payload(candidate),
    )
    execution_fillability = execution_fillability_alias_fields(event)
    if (
        execution_fillability.get("execution_fill_probability") is not None
        and not execution_fillability.get("execution_fillability_atomic_failure")
    ):
        execution_fillability_fields = {
            key: copy.deepcopy(value)
            for key, value in execution_fillability.items()
            if value not in (None, "")
        }
        event.update(execution_fillability_fields)
        for inputs_key in (
            "candidate_decision_inputs",
            "scheduler_candidate_decision_inputs",
        ):
            decision_inputs = (
                dict(event.get(inputs_key))
                if isinstance(event.get(inputs_key), Mapping)
                else {}
            )
            decision_inputs.update(execution_fillability_fields)
            event[inputs_key] = decision_inputs
    return event


def build_lifecycle_packet(
    *,
    candidate: Mapping[str, Any],
    asof_utc: str,
    risk_pct: float,
    probability: float | None,
    ev_r: float | None,
    config: Mapping[str, Any],
    open_positions: Iterable[Mapping[str, Any]] = (),
    pending_orders: Iterable[Mapping[str, Any]] = (),
) -> dict[str, Any]:
    requested_action = normalize_scheduler_action_intent(
        first_present(
            candidate.get("action_intent"),
            candidate.get("lifecycle_action"),
            candidate.get("same_symbol_lifecycle_action"),
            candidate.get("gtos_vnext_same_symbol_lifecycle_action"),
            "new_position",
        )
    ) or "new_position"
    poi_state = (
        dict(candidate.get("poi_state"))
        if isinstance(candidate.get("poi_state"), Mapping)
        else {}
    )
    poi_id = str(candidate.get("poi_id") or poi_state.get("poi_id") or "").strip()
    context = CandidateLifecycleContext(
        symbol=str(candidate.get("symbol") or ""),
        aliases=[
            str(candidate.get("symbol") or ""),
            ftmo_symbol(str(candidate.get("symbol") or "")),
        ],
        side=str(candidate.get("side") or "").upper() or None,
        requested_action=requested_action,
        risk_pct=risk_pct,
        probability=probability,
        ev_r=ev_r,
        thesis_id=poi_id or str(candidate.get("candidate_id") or ""),
        candidate_id=str(candidate.get("candidate_id") or ""),
        freshness_status="asof_current_window",
        source_completeness_status="source_complete_for_timewarp_candidate",
        poi_id=poi_id or None,
        poi_state_hash_sha256=str(
            candidate.get("poi_state_hash_sha256")
            or poi_state.get("poi_state_hash_sha256")
            or ""
        )
        or None,
        poi_state=poi_state,
        proof={
            "asof_utc": asof_utc,
            "source_boundary": SOURCE_BOUND_EVIDENCE_CLASS,
            "broker_local_position_snapshot": "simulated_replay_snapshot_not_broker_real",
        },
    )
    open_snapshots = [
        TicketLifecycleSnapshot.from_position(row)
        for row in open_positions
        if isinstance(row, Mapping)
    ]
    pending_snapshots = [
        PendingLifecycleSnapshot.from_intent(
            row,
            source_path="timewarp_simulated_account_pending_state",
            source_status="simulated_replay_pending_intent_read",
        )
        for row in pending_orders
        if isinstance(row, Mapping)
    ]
    decision = evaluate_same_symbol_lifecycle_v4(
        candidate=context,
        open_positions=open_snapshots,
        pending_orders=pending_snapshots,
        pending_source_errors=[],
        config=dict(config),
    )
    packet = decision.to_packet()
    packet["broker_local_risk_result"] = {
        **packet.get("broker_local_risk_result", {}),
        "broker_lifecycle_truth_satisfied": False,
        "same_symbol_lifecycle_exposure_source": "timewarp_simulated_account_open_pending_state",
    }
    packet["evidence_class"] = "source_bound_timewarp_lifecycle_packet_not_broker_real_snapshot"
    return packet


def safe_float(value: Any, default: float = 0.0) -> float:
    try:
        number = float(value)
    except (TypeError, ValueError):
        return default
    if not math.isfinite(number):
        return default
    return number


def candidate_cost_r(candidate: Mapping[str, Any]) -> float:
    entry = safe_float(candidate.get("entry_price"))
    stop = safe_float(candidate.get("stop_loss"))
    risk = abs(entry - stop)
    if risk <= 0:
        return 0.12
    return min(0.18, max(0.03, 0.0005 * abs(entry) / risk))


def broker_replay_default_total_cost_r(config: Mapping[str, Any]) -> float:
    runtime = (
        config.get("gtos_vnext_runtime")
        if isinstance(config.get("gtos_vnext_runtime"), Mapping)
        else {}
    )
    return max(
        0.01,
        safe_float(
            runtime.get("broad_live_as_if_replay_broker_cost_default_total_cost_r"),
            0.12,
        ),
    )


def _broker_symbol_config_uncached(
    config: Mapping[str, Any],
    symbol: str,
) -> dict[str, Any]:
    instruments = config.get("instruments") if isinstance(config.get("instruments"), Mapping) else {}
    raw_symbol = str(symbol or "")
    broker_symbol = ftmo_symbol(raw_symbol)
    aliases = tuple(
        dict.fromkeys(
            alias
            for value in (
                raw_symbol,
                broker_symbol,
                raw_symbol.replace(".", "_"),
                broker_symbol.replace(".", "_"),
                raw_symbol.replace("_cash", ".cash"),
                broker_symbol.replace("_cash", ".cash"),
                raw_symbol.replace(".cash", "_cash"),
                broker_symbol.replace(".cash", "_cash"),
            )
            for alias in (value,)
            if alias
        )
    )
    for alias in aliases:
        row = instruments.get(str(alias)) if isinstance(instruments, Mapping) else None
        if isinstance(row, Mapping):
            market = row.get("market") if isinstance(row.get("market"), Mapping) else {}
            risk = row.get("risk") if isinstance(row.get("risk"), Mapping) else {}
            return {
                "instrument_key": str(alias),
                "market": dict(market),
                "risk": dict(risk),
            }
    return {"instrument_key": "", "market": {}, "risk": {}}


def _broker_symbol_config(config: Mapping[str, Any], symbol: str) -> dict[str, Any]:
    cache = active_campaign_exact_cache()
    if cache is not None:
        return cache.broker_symbol_config(config, symbol)
    return _broker_symbol_config_uncached(config, symbol)


def _broker_symbol_market_config(config: Mapping[str, Any], symbol: str) -> dict[str, Any]:
    return dict(_broker_symbol_config(config, symbol).get("market") or {})


def _broker_cost_tick_from_row(
    row: Mapping[str, Any],
    *,
    candidate: Mapping[str, Any],
    asof_utc: str,
    spread_floor_r: float | None,
) -> tuple[Mapping[str, Any], dict[str, Any]]:
    entry = safe_float(candidate.get("entry_price"))
    stop = safe_float(candidate.get("stop_loss"))
    risk = abs(entry - stop)
    bid = safe_float(row.get("bid"), 0.0)
    ask = safe_float(row.get("ask"), 0.0)
    tick_spread_r = (ask - bid) / risk if risk > 0 and bid > 0 and ask >= bid else None
    synthetic_floor_substituted = False
    if spread_floor_r is not None and risk > 0 and tick_spread_r is None:
        mid = (bid + ask) / 2.0 if bid > 0 and ask > 0 else entry
        spread_price = spread_floor_r * risk
        bid = max(0.0, mid - spread_price / 2.0)
        ask = mid + spread_price / 2.0
        tick_spread_r = spread_floor_r
        synthetic_floor_substituted = True
    tick = {
        "bid": bid,
        "ask": ask,
        "time_utc": row.get("time_utc") or row.get("time") or asof_utc,
    }
    return tick, {
        "quote_source": "historical_ftmo_predecision_tick",
        "historical_tick_time_utc": tick["time_utc"],
        "historical_tick_spread_r": tick_spread_r,
        "measured_tick_spread_floor_r": spread_floor_r,
        "measured_tick_spread_floor_enforced": False,
        "measured_tick_spread_floor_used_as_quote_substitute": synthetic_floor_substituted,
    }


def _broker_cost_tick_from_spread_r(
    *,
    candidate: Mapping[str, Any],
    asof_utc: str,
    spread_r: float,
    quote_source: str,
    extra: Mapping[str, Any] | None = None,
) -> tuple[Mapping[str, Any], dict[str, Any]]:
    entry = safe_float(candidate.get("entry_price"), 1.0)
    stop = safe_float(candidate.get("stop_loss"))
    risk = abs(entry - stop)
    spread_price = max(0.0, spread_r) * risk if risk > 0 else 0.0
    mid = entry if entry > 0 else 1.0
    tick = {
        "bid": max(0.0, mid - spread_price / 2.0),
        "ask": mid + spread_price / 2.0,
        "time_utc": asof_utc,
    }
    metadata = {
        "quote_source": quote_source,
        "synthetic_quote_spread_r": max(0.0, spread_r),
        "synthetic_quote_spread_price": spread_price,
    }
    if isinstance(extra, Mapping):
        metadata.update(dict(extra))
    return tick, metadata


_PREDECISION_TICK_QUERY_CACHE: dict[
    tuple[int, str, float],
    tuple[ResolvedSource, dict[str, Any] | None, dict[str, Any]],
] = {}


def _predecision_tick_for_cost(
    *,
    candidate: Mapping[str, Any],
    path_sources: Mapping[str, ResolvedSource] | None,
    asof_utc: str,
    config: Mapping[str, Any],
) -> tuple[Mapping[str, Any], dict[str, Any]]:
    symbol = str(candidate.get("symbol") or "")
    entry = safe_float(candidate.get("entry_price"))
    stop = safe_float(candidate.get("stop_loss"))
    risk = abs(entry - stop)
    floor_r = TICK_SPREAD_FLOOR_R.get(symbol)
    runtime = (
        config.get("gtos_vnext_runtime")
        if isinstance(config.get("gtos_vnext_runtime"), Mapping)
        else {}
    )
    lookback_minutes = max(
        1.0,
        safe_float(
            runtime.get("broad_live_as_if_replay_broker_cost_tick_lookback_minutes"),
            60.0,
        ),
    )
    asof = parse_utc(asof_utc)
    tick_source = path_sources.get("TICK") if isinstance(path_sources, Mapping) else None
    if tick_source is not None and asof is not None:
        cache_key = (id(tick_source), asof_utc, round(lookback_minutes, 8))
        cached = _PREDECISION_TICK_QUERY_CACHE.get(cache_key)
        if cached is None or cached[0] is not tick_source:
            query = PathTruthIndex(tick_source).query(
                after=asof - timedelta(minutes=lookback_minutes),
                until=asof,
            )
            tick_rows = [
                row
                for row in query.rows
                if safe_float(row.get("bid"), 0.0) > 0
                and safe_float(row.get("ask"), 0.0) > 0
            ]
            cached = (
                tick_source,
                dict(tick_rows[-1]) if tick_rows else None,
                {
                    "path_index_rows_returned": len(query.rows),
                    "path_index_source_path": query.metadata.get("path_index_source_path"),
                    "path_index_source_sha256": query.metadata.get("path_index_source_sha256"),
                    "path_index_lookup_mode": query.metadata.get("path_index_lookup_mode"),
                },
            )
            _PREDECISION_TICK_QUERY_CACHE[cache_key] = cached
        _cached_source, cached_row, cached_metadata = cached
        if cached_row:
            tick, metadata = _broker_cost_tick_from_row(
                cached_row,
                candidate=candidate,
                asof_utc=asof_utc,
                spread_floor_r=floor_r,
            )
            metadata.update(cached_metadata)
            return tick, metadata
    # No causal tick exists for most of the historical surface.  The old
    # fallback chain incorrectly promoted three unrelated values into quotes:
    # an Ultimate Book R-floor, a static profile snapshot, and
    # ``risk.max_spread_cents`` (an admission ceiling).  Price the same symbol
    # and decision instant through the existing era/hour-aware spread model.
    # If that authority cannot price the row, preserve a source gap and let the
    # four-component packet refuse; never manufacture a numeric fallback.
    profile = (
        config.get("broker_profile")
        if isinstance(config.get("broker_profile"), Mapping)
        else {}
    )
    try:
        if asof is None:
            raise SpreadModelError("unparseable decision time")
        if risk <= 0.0:
            raise SpreadModelError("non-positive candidate stop distance")
        account = account_for(
            server=str(profile.get("server") or "") or None,
            namespace=broker_account_namespace(dict(config)) or None,
        )
        estimate = spread_price(symbol, account, asof, band="mid")
        model_spread_price = safe_float(estimate.spread_price, math.nan)
        if not math.isfinite(model_spread_price) or model_spread_price <= 0.0:
            raise SpreadModelError("non-positive spread-model price")
    except (CostTruthError, SpreadModelError, SymbolAuthorityError) as exc:
        return {}, {
            "quote_source": "spread_model_source_gap",
            "source_gaps": [f"spread_model_unavailable:{type(exc).__name__}"],
            "spread_model_error": str(exc)[:240],
            "spread_model_account": None,
            "spread_model_band": "mid",
            "measured_tick_spread_floor_r": floor_r,
            "measured_tick_spread_floor_used_as_quote_substitute": False,
        }

    spread_r = model_spread_price / risk
    return _broker_cost_tick_from_spread_r(
        candidate=candidate,
        asof_utc=asof_utc,
        spread_r=spread_r,
        quote_source="spread_model_v1_hour_aware",
        extra={
            "spread_model_account": account,
            "spread_model_band": "mid",
            "spread_model_composition": estimate.composition,
            "spread_model_coverage": estimate.coverage.value,
            "spread_model_decidable": estimate.decidable,
            "spread_model_era": estimate.era,
            "spread_model_era_class": estimate.era_class,
            "spread_model_spread_price": model_spread_price,
            "spread_model_provenance": estimate.provenance,
            "spread_model_detail": dict(estimate.detail),
            "measured_tick_spread_floor_r": floor_r,
            "measured_tick_spread_floor_used_as_quote_substitute": False,
        },
    )


def broker_calibrated_replay_cost_packet(
    *,
    candidate: Mapping[str, Any],
    config: Mapping[str, Any],
    path_sources: Mapping[str, ResolvedSource] | None,
    risk_pct: float,
    asof_utc: str,
) -> dict[str, Any]:
    """Replay cost authority using broker profile/tick inputs, with old proxy diagnostic only."""

    fallback_cost_r = candidate_cost_r(candidate)
    symbol = str(candidate.get("symbol") or "")
    entry = safe_float(candidate.get("entry_price"))
    stop = safe_float(candidate.get("stop_loss"))
    risk = abs(entry - stop)
    tick, quote_metadata = _predecision_tick_for_cost(
        candidate=candidate,
        path_sources=path_sources,
        asof_utc=asof_utc,
        config=config,
    )
    market = _broker_symbol_market_config(config, symbol)
    runtime = (
        config.get("gtos_vnext_runtime")
        if isinstance(config.get("gtos_vnext_runtime"), Mapping)
        else {}
    )
    swap_time_stop_bars = first_present(
        candidate.get("gtos_vnext_dynamic_time_stop_bars"),
        candidate.get("dynamic_time_stop_bars"),
        candidate.get("time_stop_bars"),
        runtime.get("broad_live_as_if_replay_pretrade_swap_cost_time_stop_bars"),
        runtime.get("selected_cell_swap_cost_time_stop_bars"),
        32,
    )
    trade_params = {
        "direction": candidate.get("side"),
        "side": candidate.get("side"),
        "entry_price": entry,
        "stop_loss": stop,
        "take_profit_1": candidate.get("take_profit_1"),
        "risk_reward_ratio": candidate.get("risk_reward_ratio"),
        "gtos_vnext_production_execution_path": True,
        "gtos_vnext_selected_cell_risk_pct": risk_pct,
        "gtos_vnext_selected_cell_risk_cell_id": f"timewarp:{candidate.get('candidate_id')}",
        "gtos_vnext_selected_cell_risk_decision_basis": "broad_live_as_if_replay_broker_net_cost",
        "gtos_vnext_commission_model_status": "COMMISSION_INCLUDED_IN_SELECTED_CELL_RISK",
        "gtos_vnext_expected_slippage_r": (
            candidate.get("gtos_vnext_expected_slippage_r")
            or candidate.get("expected_slippage_r")
        ),
        "gtos_vnext_dynamic_time_stop_bars": swap_time_stop_bars,
    }
    cost_packet = build_pretrade_cost_packet(
        config=dict(config),
        trade_params=trade_params,
        tick=tick,
        symbol=symbol,
        broker_symbol=str(market.get("mt5_symbol") or ftmo_symbol(symbol)),
        entry_price=entry,
        stop_loss=stop,
        sl_distance=risk,
        risk_pct=risk_pct,
        symbol_info=market,
        asof_utc=asof_utc,
    )
    quote_source = str(quote_metadata.get("quote_source") or "")
    spread_source_gap = quote_source == "spread_model_source_gap"
    raw_total_cost_r = cost_packet.get("total_cost_r")
    total_cost_r = safe_float(raw_total_cost_r, math.nan)
    total_cost_complete = bool(
        not isinstance(raw_total_cost_r, bool)
        and math.isfinite(total_cost_r)
        and total_cost_r >= 0.0
    )
    tick_floor = TICK_SPREAD_FLOOR_R.get(symbol)
    cost_packet.update(
        {
            "authority": "broker_calibrated_replay_cost",
            "old_timewarp_candidate_cost_r_fallback_diagnostic": round(
                fallback_cost_r,
                9,
            ),
            "old_proxy_vs_broker_calibrated_delta_r": (
                round(total_cost_r - fallback_cost_r, 9)
                if total_cost_complete
                else None
            ),
            "quote_authority": quote_metadata,
            "cost_source_gap_status": (
                "SOURCE_GAP_NO_NUMERIC_SPREAD"
                if spread_source_gap
                else "source_bound_cost_authority_present"
            ),
            "cost_source_gap_allowed_by_replay_profile": False,
            "measured_tick_spread_floor_r": tick_floor,
            "tick_spread_floor_untradeable_r": TICK_SPREAD_FLOOR_UNTRADEABLE_R,
            "symbol_specific_untradeable_cost_floor": (
                bool(tick_floor is not None and tick_floor >= TICK_SPREAD_FLOOR_UNTRADEABLE_R)
            ),
            # Preserve the component the engine actually computed.  The prior
            # update overwrote this flat transport field with zero even when
            # ``total_cost_components.commission_r`` was non-zero.
            "commission_r": cost_packet.get("commission_r"),
            "commission_r_source": (
                (cost_packet.get("commission_cost") or {}).get("model_version")
                if isinstance(cost_packet.get("commission_cost"), Mapping)
                else None
            ),
            "candidate_cost_r_fallback_is_authority": False,
            "cost_component_total_status": (
                "complete_four_component_sum"
                if total_cost_complete
                else "not_evaluable_incomplete_component_sum"
            ),
            "replay_swap_cost_time_stop_bars": swap_time_stop_bars,
            "replay_swap_cost_time_stop_bars_source": (
                "candidate_or_runtime_time_stop_bars"
            ),
        }
    )
    if spread_source_gap:
        cost_packet["status"] = "REFUSED"
        cost_packet["source_gap_cost_fallback_blocked"] = True
        cost_packet.setdefault("refusal_reasons", []).append(
            "source_gap_spread_model_unavailable_no_numeric_imputation"
        )
    return cost_packet


class ReplayClock:
    """Historical accelerated clock for closed M15 decision events."""

    def __init__(self, days: Iterable[str], sources: Mapping[str, Mapping[str, ResolvedSource]]):
        self.days = tuple(days)
        self.sources = sources

    def decision_times_for_day(self, day: str, *, smoke_subset: bool = False) -> list[datetime]:
        # Partial-hydration days (e.g. half-session holidays dropping one
        # symbol below the M1 per-day floor) exclude that symbol from
        # ``sources``; the clock derives the decision grid from the symbols
        # that ARE resolved instead of crashing on the missing key.
        times = sorted(
            {
                row_time + timedelta(minutes=15)
                for symbol in INCLUDED_SYMBOLS
                if symbol in self.sources and "M15" in self.sources[symbol]
                for row in self.sources[symbol]["M15"].rows_by_day.get(day, ())
                if (row_time := parse_row_time(row)) is not None
            }
        )
        if smoke_subset:
            times = [ts for ts in times if ts.hour in {7, 8, 13, 14}][:16]
        return times


LIVE_INGESTION_FUNCTION_ID = "src.components.data_ingestion.ingest_live_data"
LIVE_REPLAY_RAW_DATA_MODE = "live_ingestion_with_historical_mt5_adapter"
_LIVE_TF_BY_CONST = {int(value): key for key, value in LIVE_TF_MAP.items()}


class MarketStateComputationError(RuntimeError):
    """Distinguish market-state compute failures from upstream source gaps."""

    def __init__(self, message: str, *, metadata: Mapping[str, Any]):
        super().__init__(message)
        self.metadata = dict(metadata)


def _replay_symbol_config_uncached(
    config: Mapping[str, Any],
    symbol: str,
) -> dict[str, Any]:
    """Return a per-symbol live config without changing the global route config."""

    output = json.loads(json.dumps(config, default=str))
    market = output.setdefault("market", {})
    if not isinstance(market, dict):
        market = {}
        output["market"] = market
    market["symbol"] = symbol
    market["mt5_symbol"] = ftmo_symbol(symbol)
    tick_features = output.setdefault("tick_features", {})
    if not isinstance(tick_features, dict):
        tick_features = {}
        output["tick_features"] = tick_features
    tick_features["enabled"] = False
    tick_features[
        "disabled_reason"
    ] = "replay_source_separation_predecision_uses_d1_h4_h1_m15_closed_bars_only"
    return output


def replay_symbol_config(config: Mapping[str, Any], symbol: str) -> dict[str, Any]:
    cache = active_campaign_exact_cache()
    if cache is not None:
        return cache.replay_symbol_config(config, symbol)
    return _replay_symbol_config_uncached(config, symbol)


class HistoricalMT5Adapter:
    """Read-only historical MT5 facade for replay-mode live ingestion."""

    def __init__(
        self,
        sources: Mapping[str, Mapping[str, ResolvedSource]],
        *,
        require_successor_witness: bool = False,
    ):
        self.sources = sources
        self.require_successor_witness = bool(require_successor_witness)
        self._symbol: str | None = None
        self._asof: datetime | None = None
        self._last_calls: dict[str, dict[str, Any]] = {}

    def set_replay_context(self, *, symbol: str, asof: datetime) -> None:
        if self.require_successor_witness and (
            asof.tzinfo is None or asof.utcoffset() is None
        ):
            raise SourceTimebaseError("replay_context_asof_naive")
        self._symbol = symbol
        self._asof = (
            asof.astimezone(timezone.utc)
            if asof.tzinfo
            else asof.replace(tzinfo=timezone.utc)
        )
        self._last_calls = {}

    def connect(self) -> bool:
        return True

    def disconnect(self) -> None:
        return None

    def is_connected(self) -> bool:
        return True

    def _context(self) -> tuple[str, datetime]:
        if self._symbol is None or self._asof is None:
            raise RuntimeError("HistoricalMT5Adapter replay context is not set")
        return self._symbol, self._asof

    def _timeframe_name(self, timeframe: int) -> str:
        tf_name = _LIVE_TF_BY_CONST.get(int(timeframe))
        if not tf_name:
            raise RuntimeError(f"Unsupported replay timeframe constant: {timeframe}")
        return tf_name

    def get_candles(self, symbol: str, timeframe: int, count: int) -> list[dict[str, Any]]:
        canonical_symbol, asof = self._context()
        tf_name = self._timeframe_name(timeframe)
        source = self.sources[canonical_symbol][tf_name]
        if self.require_successor_witness:
            try:
                rows = observed_successor_closed_bar_rows_until(
                    source.rows,
                    timeframe=tf_name,
                    asof=asof,
                    max_rows=int(count),
                    attach_witness=True,
                )
            except CompletedBarWitnessError as exc:
                message = str(exc)
                error_type = (
                    SourceTimebaseError
                    if any(
                        token in message
                        for token in ("naive", "invalid", "missing")
                    )
                    else SourceChronologyError
                )
                raise error_type(
                    f"{tf_name}_completed_bar_witness:{message}"
                ) from exc
        else:
            rows = closed_bar_rows_until(
                source.rows,
                timeframe=tf_name,
                asof=asof,
                max_rows=int(count),
            )
        selected = [dict(row) for row in rows[-int(count):]]
        latest_closed_time = (
            selected[-1].get("time_utc") if selected else None
        )
        self._last_calls[tf_name] = {
            "requested_broker_symbol": symbol,
            "canonical_symbol": canonical_symbol,
            "mapped_symbol": ftmo_symbol(canonical_symbol),
            "timeframe": tf_name,
            "requested_count": int(count),
            "returned_count": len(selected),
            "latest_closed_time": latest_closed_time,
            "source_path": str(source.spec.path),
            "source_hash": source.sha256,
            "source_broker": source.spec.source_broker,
            "source_role": source.spec.source_role,
            "manifest_path": source.spec.manifest_path,
            "export_tool": source.spec.export_tool,
        }
        return selected

    def get_candles_range(
        self,
        symbol: str,
        timeframe: int,
        date_from: datetime,
        date_to: datetime,
    ) -> list[dict[str, Any]]:
        canonical_symbol, _asof = self._context()
        tf_name = self._timeframe_name(timeframe)
        source = self.sources[canonical_symbol][tf_name]
        start = date_from.astimezone(timezone.utc) if date_from.tzinfo else date_from.replace(tzinfo=timezone.utc)
        end = date_to.astimezone(timezone.utc) if date_to.tzinfo else date_to.replace(tzinfo=timezone.utc)
        return [
            dict(row)
            for row in source.rows
            if (ts := parse_row_time(row)) is not None and start <= ts <= end
        ]

    def get_tick(self, symbol: str = "XAUUSD") -> None:
        # The replay predecision market-state contract is D1/H4/H1/M15 only.
        # M1/tick rows are reserved for postdecision path truth.
        return None

    def get_ticks_range(self, symbol: str, date_from: datetime, date_to: datetime) -> list[dict]:
        canonical_symbol, _asof = self._context()
        source = self.sources.get(canonical_symbol, {}).get("TICK")
        if source is None:
            return []
        start = date_from.astimezone(timezone.utc) if date_from.tzinfo else date_from.replace(tzinfo=timezone.utc)
        end = date_to.astimezone(timezone.utc) if date_to.tzinfo else date_to.replace(tzinfo=timezone.utc)
        return [
            dict(row)
            for row in source.rows
            if (ts := parse_row_time(row)) is not None and start <= ts <= end
        ]

    def get_positions(self, symbol: str = "XAUUSD") -> list[Any]:
        return []

    def get_account_balance(self) -> float:
        return STARTING_BALANCE

    def get_account_equity(self) -> float:
        return STARTING_BALANCE

    def get_margin_mode(self) -> str:
        return "hedging"

    def order_send(self, request: dict) -> Any:
        raise RuntimeError("HistoricalMT5Adapter is read-only; broker mutation is disabled")

    def get_history_deals(self, from_date: datetime, to_date: datetime, symbol: str = "XAUUSD") -> list[dict]:
        return []

    def decision_metadata(self, *, raw_data: Mapping[str, Any]) -> dict[str, Any]:
        canonical_symbol, asof = self._context()
        row_counts = {
            tf: int(meta.get("returned_count") or 0)
            for tf, meta in self._last_calls.items()
        }
        source_paths = {
            tf: str(meta.get("source_path") or "")
            for tf, meta in self._last_calls.items()
        }
        source_hashes = {
            tf: str(meta.get("source_hash") or "")
            for tf, meta in self._last_calls.items()
        }
        max_source_times = {
            tf: meta.get("latest_closed_time")
            for tf, meta in self._last_calls.items()
        }
        return {
            "decision_time_utc": iso(asof),
            "decision_timeframes_present": list(PRIMARY_DECISION_TIMEFRAMES),
            "decision_rows_used_by_timeframe": row_counts,
            "decision_max_source_time_utc_by_timeframe": max_source_times,
            "decision_max_source_time_utc": max(
                (value for value in max_source_times.values() if value),
                default=None,
            ),
            "source_paths_by_timeframe": source_paths,
            "source_hashes_by_timeframe": source_hashes,
            "raw_data_hash_sha256": predecision_raw_data_identity_hash(
                symbol=canonical_symbol,
                asof_utc=iso(asof),
                row_counts=row_counts,
                source_hashes=source_hashes,
                max_source_times=max_source_times,
                source_paths=source_paths,
            ),
            "m1_or_tick_attached_to_decision": False,
            "live_replay_mode": True,
            "live_ingestion_function": LIVE_INGESTION_FUNCTION_ID,
            "raw_data_construction_mode": LIVE_REPLAY_RAW_DATA_MODE,
            "route_local_raw_packet_used": False,
            "historical_adapter": "HistoricalMT5Adapter",
            "predecision_tick_features_enabled": False,
            "predecision_tick_features_disabled_reason": (
                "replay_source_separation_predecision_uses_d1_h4_h1_m15_closed_bars_only"
            ),
        }

    def last_decision_metadata(self) -> dict[str, Any]:
        return self.decision_metadata(raw_data={})

    def timeframe_source_identity(self, timeframe: str) -> dict[str, Any]:
        metadata = self._last_calls.get(str(timeframe))
        if not isinstance(metadata, Mapping):
            raise CampaignExactCacheError("d1_source_identity_missing")
        return {
            "source_path": str(metadata.get("source_path") or ""),
            "source_hash": str(metadata.get("source_hash") or ""),
            "source_broker": str(metadata.get("source_broker") or ""),
            "source_role": str(metadata.get("source_role") or ""),
            "requested_count": metadata.get("requested_count"),
            "returned_count": metadata.get("returned_count"),
            "latest_closed_time": metadata.get("latest_closed_time"),
        }


class ReplayFeed:
    """Live-equivalent replay feed exposing predecision raw data and MSO."""

    def __init__(
        self,
        adapter: HistoricalMT5Adapter,
        config: Mapping[str, Any],
        *,
        campaign_exact_cache: CampaignExactCache | None = None,
    ):
        if campaign_exact_cache is not None:
            if not isinstance(campaign_exact_cache, CampaignExactCache):
                raise CampaignExactCacheError("campaign_exact_cache_invalid")
            campaign_exact_cache._require_config(config)
        self.adapter = adapter
        self.config = config
        self.campaign_exact_cache = campaign_exact_cache

    def _timeframe_state_provider(
        self,
        *,
        symbol: str,
        symbol_config: Mapping[str, Any],
    ) -> Callable[..., TimeframeState] | None:
        cache = self.campaign_exact_cache
        if cache is None:
            return None
        market_state_config = symbol_config.get("market_state", {})
        market_state_config = (
            market_state_config
            if isinstance(market_state_config, Mapping)
            else {}
        )
        side_effect_writes_enabled = bool(
            market_state_config.get("side_effect_writes_enabled", True)
        )
        shadow_logging_enabled = bool(
            market_state_config.get(
                "structure_shadow_log_enabled",
                side_effect_writes_enabled,
            )
        )
        if side_effect_writes_enabled or shadow_logging_enabled:
            raise CampaignExactCacheError(
                "d1_market_state_side_effects_must_be_disabled"
            )

        def provide(
            *,
            timeframe: str,
            candles: Sequence[Mapping[str, Any]],
            build_parameters: Mapping[str, Any],
            builder: Callable[[], TimeframeState],
        ) -> TimeframeState:
            timeframe_key = str(timeframe).upper()
            if timeframe_key not in {"D1", "H4", "H1"}:
                raise CampaignExactCacheError(
                    "closed_timeframe_state_provider_scope_invalid"
                )
            return cache.closed_timeframe_state(
                self.config,
                timeframe=timeframe_key,
                symbol=symbol,
                candles=candles,
                source_identity=self.adapter.timeframe_source_identity(
                    timeframe_key
                ),
                build_parameters=build_parameters,
                side_effect_writes_enabled=side_effect_writes_enabled,
                builder=builder,
            )

        return provide

    def snapshot(
        self,
        *,
        symbol: str,
        asof: datetime,
        stage_profiler: Any | None = None,
    ) -> tuple[dict[str, Any], Any, dict[str, Any]]:
        with _replay_profile_stage(stage_profiler, "snapshots"):
            _replay_profile_call(stage_profiler, "replay_symbol_config")
            symbol_config = replay_symbol_config(self.config, symbol)
            self.adapter.set_replay_context(symbol=symbol, asof=asof)
            _replay_profile_call(stage_profiler, "ingest_live_data")
            raw = ingest_live_data(self.adapter, symbol_config, now_utc=asof)
            metadata = self.adapter.decision_metadata(raw_data=raw)
            raw["source_paths_by_timeframe"] = metadata["source_paths_by_timeframe"]
            raw["source_hashes_by_timeframe"] = metadata["source_hashes_by_timeframe"]
            raw["source_truth_scope"] = SOURCE_TRUTH_SCOPE
            raw["decision_input_timeframes"] = list(PRIMARY_DECISION_TIMEFRAMES)
            raw["post_decision_path_timeframes_available_but_not_attached"] = [
                tf
                for tf in POST_DECISION_PATH_TIMEFRAMES
                if tf in self.adapter.sources[symbol]
            ]
            raw["live_replay_mode"] = True
            raw["live_ingestion_function"] = LIVE_INGESTION_FUNCTION_ID
            raw["raw_data_construction_mode"] = LIVE_REPLAY_RAW_DATA_MODE
            raw["route_local_raw_packet_used"] = False
            raw["historical_adapter"] = "HistoricalMT5Adapter"
            raw["predecision_tick_features_enabled"] = False
            raw["predecision_tick_features_disabled_reason"] = (
                "replay_source_separation_predecision_uses_d1_h4_h1_m15_closed_bars_only"
            )
            raw.setdefault("data_quality", {})["decision_input_timeframes"] = list(
                PRIMARY_DECISION_TIMEFRAMES
            )
            raw.setdefault("data_quality", {})[
                "post_decision_timeframes_attached"
            ] = []
            raw.setdefault("data_quality", {})[
                "predecision_tick_features_enabled"
            ] = False
            raw.setdefault("data_quality", {})["replay_clock_utc"] = iso(asof)
            metadata = self.adapter.decision_metadata(raw_data=raw)
        try:
            with _replay_profile_stage(stage_profiler, "market_state"):
                _replay_profile_call(stage_profiler, "compute_market_state")
                mso = compute_market_state(
                    raw,
                    symbol_config,
                    timeframe_state_provider=self._timeframe_state_provider(
                        symbol=symbol,
                        symbol_config=symbol_config,
                    ),
                )
        except CampaignExactCacheError:
            raise
        except Exception as exc:  # noqa: BLE001
            raise MarketStateComputationError(str(exc), metadata=metadata) from exc
        return raw, mso, metadata


class LiveReplayMode:
    """Accelerated historical mode for live-path component invocation."""

    surface_contract = {
        "time_source": "ReplayClock",
        "data_source": "HistoricalMT5Adapter",
        "broker_adapter": "SimulatedBroker",
        "path_truth_index": "PathTruthIndex",
        "decision_cycle_core": "src.components.v4_live_replay_decision_core.V4DecisionCycleCore",
        "live_ingestion": LIVE_INGESTION_FUNCTION_ID,
        "market_state": "src.components.market_state.compute_market_state",
        "candidate_generation": "src.components.broader_origin_generators.generate_live_broader_origin_candidates",
        "probability_debate_v4": "src.components.probability_debate_v4.evaluate_probability_debate_team_v4",
        "selector_v4": "src.components.selector_v4.evaluate_selector_v4_admission",
        "scheduler_v4_best_trade_allocator": "src.research.moonshot_scheduler_v4_best_trade_allocator.allocate_decision_window",
        "same_symbol_lifecycle_v4": "src.components.same_symbol_lifecycle_v4.evaluate_same_symbol_lifecycle_v4",
        "prop_firm_headroom_v4": "src.components.prop_firm_headroom_v4.evaluate_prop_firm_headroom_snapshot_v4",
        "execution_manager_v4": "src.components.execution_manager_v4.evaluate_execution_manager_v4",
        "dynamic_target_stop_geometry_v4": "src.components.dynamic_target_stop_geometry_v4.build_target_stop_geometry_v4_contract",
        "exit_policy_v4": "src.components.exit_policy_v4.evaluate_exit_policy_v4",
        "live_decision_packet_v4": "src.components.live_decision_packet_v4.build_live_decision_packet_v4",
        "broker_order_lifecycle_capture_v4": "src.components.broker_order_lifecycle_capture_v4.build_broker_order_lifecycle_capture_v4",
        "broker_mutation": False,
        "remote_push": False,
        "paid_api": False,
    }

    def __init__(
        self,
        sources: Mapping[str, Mapping[str, ResolvedSource]],
        config: Mapping[str, Any],
        *,
        campaign_exact_cache: CampaignExactCache | None = None,
    ):
        self.sources = sources
        self.config = config
        self.feed = ReplayFeed(
            HistoricalMT5Adapter(
                sources,
                require_successor_witness=wave21_full_flow_truth_mode_enabled(
                    config
                ),
            ),
            config,
            campaign_exact_cache=campaign_exact_cache,
        )

    def snapshot(
        self,
        *,
        symbol: str,
        asof: datetime,
        stage_profiler: Any | None = None,
    ) -> tuple[dict[str, Any], Any, dict[str, Any]]:
        return self.feed.snapshot(
            symbol=symbol,
            asof=asof,
            stage_profiler=stage_profiler,
        )

    def contract_row(self) -> dict[str, Any]:
        return {
            "live_replay_mode": True,
            "raw_data_construction_mode": LIVE_REPLAY_RAW_DATA_MODE,
            "surface_contract": dict(self.surface_contract),
            "orchestrator_class_direct_instantiation": False,
            "orchestrator_adapter_reason": (
                "production Orchestrator boot wires live broker process, signal handlers, "
                "LLM backend, and persistent runtime logging; replay invokes the same live "
                "component surfaces through a read-only adapter with broker mutation disabled"
            ),
        }


def raw_data_for_asof(
    *,
    symbol: str,
    sources: Mapping[str, ResolvedSource],
    asof: datetime,
    config: Mapping[str, Any],
) -> tuple[dict[str, Any], dict[str, Any]]:
    candles: dict[str, list[dict[str, Any]]] = {}
    row_counts: dict[str, int] = {}
    source_paths: dict[str, str] = {}
    source_hashes: dict[str, str] = {}
    max_source_times: dict[str, str | None] = {}
    for timeframe in PRIMARY_DECISION_TIMEFRAMES:
        source = sources[timeframe]
        lookback = int(
            (config.get("data") or {})
            .get("lookback", DEFAULT_LOOKBACKS)
            .get(timeframe, DEFAULT_LOOKBACKS.get(timeframe, 500))
        )
        rows = closed_bar_rows_until(
            source.rows,
            timeframe=timeframe,
            asof=asof,
            max_rows=lookback,
        )
        selected = rows[-lookback:]
        candles[timeframe] = [dict(row) for row in selected]
        row_counts[timeframe] = len(selected)
        source_paths[timeframe] = str(source.spec.path)
        source_hashes[timeframe] = source.sha256
        max_source_times[timeframe] = selected[-1].get("time_utc") if selected else None

    m15_rows = candles.get("M15", [])
    target_date = asof.date()
    session_levels = compute_session_levels(m15_rows, target_date)
    london_rows: list[dict[str, Any]] = []
    session_rows: list[dict[str, Any]] = []
    for row in m15_rows:
        ts = parse_row_time(row)
        if ts is None or ts.date() != target_date:
            continue
        if ts.time() >= datetime(target_date.year, target_date.month, target_date.day, 7, 0, tzinfo=timezone.utc).time():
            session_rows.append(row)
        if 7 <= ts.hour < 13:
            london_rows.append(row)
    if session_rows:
        session_levels["session_high"] = max(row["high"] for row in session_rows)
        session_levels["session_low"] = min(row["low"] for row in session_rows)
    if london_rows:
        session_levels["london_high"] = max(row["high"] for row in london_rows)
        session_levels["london_low"] = min(row["low"] for row in london_rows)

    latest_m15_open = parse_row_time(m15_rows[-1]) if m15_rows else None
    latest_m15_close = latest_m15_open + timedelta(minutes=15) if latest_m15_open else None
    tolerance = safe_float((config.get("model_a") or {}).get("equal_level_tolerance"), 2.50)
    data_quality = {
        "all_timeframes_complete": all(row_counts.get(tf, 0) >= int(DEFAULT_LOOKBACKS.get(tf, 1) * 0.9) for tf in PRIMARY_DECISION_TIMEFRAMES),
        "closed_bar_filter": {
            tf: {
                "closed_count": row_counts.get(tf, 0),
                "latest_closed_time": max_source_times.get(tf),
                "source_path": source_paths.get(tf),
                "source_hash": source_hashes.get(tf),
            }
            for tf in PRIMARY_DECISION_TIMEFRAMES
        },
        "spread_normal": True,
        "mt5_connected": False,
        "timestamp_utc": iso(asof),
        "replay_clock_utc": iso(asof),
        "decision_timeframes_present": list(PRIMARY_DECISION_TIMEFRAMES),
        "post_decision_timeframes_attached": [],
    }
    raw_data = {
        "symbol": symbol,
        "timestamp_utc": iso(asof),
        "selected_closed_bar_open_utc": iso(latest_m15_open),
        "candle_close_utc": iso(latest_m15_close),
        "candles": candles,
        "session_levels": session_levels,
        "equal_highs_H4": detect_equal_levels(candles.get("H4", []), "high", tolerance),
        "equal_lows_H4": detect_equal_levels(candles.get("H4", []), "low", tolerance),
        "equal_highs_H1": detect_equal_levels(candles.get("H1", []), "high", tolerance),
        "equal_lows_H1": detect_equal_levels(candles.get("H1", []), "low", tolerance),
        "spread_cents": 20.0,
        "high_impact_events": [],
        "data_quality": data_quality,
        "source_paths_by_timeframe": source_paths,
        "source_hashes_by_timeframe": source_hashes,
        "source_truth_scope": SOURCE_TRUTH_SCOPE,
        "decision_input_timeframes": list(PRIMARY_DECISION_TIMEFRAMES),
        "post_decision_path_timeframes_available_but_not_attached": [
            tf for tf in POST_DECISION_PATH_TIMEFRAMES if tf in sources
        ],
    }
    metadata = {
        "decision_time_utc": iso(asof),
        "decision_timeframes_present": list(PRIMARY_DECISION_TIMEFRAMES),
        "decision_rows_used_by_timeframe": row_counts,
        "decision_max_source_time_utc_by_timeframe": max_source_times,
        "decision_max_source_time_utc": max(
            (value for value in max_source_times.values() if value),
            default=None,
        ),
        "source_paths_by_timeframe": source_paths,
        "source_hashes_by_timeframe": source_hashes,
        "raw_data_hash_sha256": predecision_raw_data_identity_hash(
            symbol=symbol,
            asof_utc=iso(asof),
            row_counts=row_counts,
            source_hashes=source_hashes,
            max_source_times=max_source_times,
            source_paths=source_paths,
        ),
        "m1_or_tick_attached_to_decision": False,
    }
    return raw_data, metadata


def predecision_market_snapshot_fields(
    raw_data: Mapping[str, Any],
    *,
    asof_utc: str | None = None,
) -> dict[str, Any]:
    """Closed-bar market fields available before the replay decision is made."""

    candles = raw_data.get("candles") if isinstance(raw_data, Mapping) else {}
    candles = candles if isinstance(candles, Mapping) else {}
    m15_rows = candles.get("M15")
    if not isinstance(m15_rows, Sequence) or isinstance(
        m15_rows, (str, bytes, bytearray)
    ):
        return {}
    asof_dt = parse_utc(asof_utc)
    latest = None
    latest_source_time = None
    for row in reversed(m15_rows):
        if not isinstance(row, Mapping):
            continue
        source_time = first_present(
            row.get("time_utc"),
            row.get("time"),
            raw_data.get("selected_closed_bar_open_utc"),
        )
        source_dt = parse_utc(source_time)
        if asof_dt is not None and source_dt is not None and source_dt > asof_dt:
            continue
        if asof_dt is not None and source_dt is None:
            continue
        latest = row
        latest_source_time = source_time
        break
    if latest is None:
        return {}
    close = safe_float(first_present(latest.get("close"), latest.get("Close")), math.nan)
    if not math.isfinite(close):
        return {}
    fields: dict[str, Any] = {
        "current_price": round(close, 8),
        "close": round(close, 8),
        "m15_close": round(close, 8),
        "current_price_source": "latest_closed_m15_close",
        "current_price_source_time_utc": latest_source_time,
        "current_price_source_boundary": (
            "closed_m15_predecision_asof_no_postdecision_path"
        ),
        "current_price_asof_utc": asof_utc,
    }
    for key in ("open", "high", "low", "volume"):
        value = safe_float(latest.get(key), math.nan)
        if math.isfinite(value):
            rounded = round(value, 8)
            fields[f"m15_{key}"] = rounded
            fields.setdefault(key, rounded)
    return fields


def enrich_candidate_with_predecision_market_snapshot(
    candidate: Mapping[str, Any],
    raw_data: Mapping[str, Any],
    *,
    asof_utc: str | None = None,
) -> dict[str, Any]:
    """Attach a snapshot and remint a singleton occurrence.

    Production candidate windows use the batch variant below so convergent
    transforms cannot collapse two parent occurrences.
    """

    return enrich_candidates_with_predecision_market_snapshot(
        [candidate],
        raw_data,
        asof_utc=asof_utc,
    )[0]


def _attach_predecision_market_snapshot(
    candidate: Mapping[str, Any],
    raw_data: Mapping[str, Any],
    *,
    asof_utc: str | None = None,
) -> dict[str, Any]:
    """Attach only source-safe snapshot fields; occurrence remint is batched."""

    enriched = dict(candidate)
    snapshot = predecision_market_snapshot_fields(raw_data, asof_utc=asof_utc)
    if not snapshot:
        return enriched
    source_fields = (
        dict(enriched.get("source_fields"))
        if isinstance(enriched.get("source_fields"), Mapping)
        else {}
    )
    for key, value in snapshot.items():
        if source_fields.get(key) in (None, "", [], {}):
            source_fields[key] = value
    enriched["source_fields"] = source_fields
    if enriched.get("current_price") in (None, "", [], {}):
        enriched["current_price"] = snapshot["current_price"]
    enriched["predecision_current_price"] = snapshot["current_price"]
    enriched["predecision_current_price_source"] = snapshot["current_price_source"]
    enriched["predecision_current_price_source_boundary"] = snapshot[
        "current_price_source_boundary"
    ]
    enriched["predecision_current_price_source_time_utc"] = snapshot.get(
        "current_price_source_time_utc"
    )
    return enriched


def enrich_candidates_with_predecision_market_snapshot(
    candidates: Iterable[Mapping[str, Any]],
    raw_data: Mapping[str, Any],
    *,
    asof_utc: str | None = None,
) -> list[dict[str, Any]]:
    """Attach the common snapshot and atomically remint claimed occurrences."""

    parents = [dict(candidate) for candidate in candidates]
    claimed_indexes: list[int] = []
    for index, parent in enumerate(parents):
        occurrence_claimed = bool(
            parent.get(CANDIDATE_OCCURRENCE_KEY_FIELD)
            or parent.get(CANDIDATE_SOURCE_SAFE_FINGERPRINT_FIELD)
        )
        if not occurrence_claimed:
            continue
        if candidate_occurrence_key_from_fields(parent) != parent.get(
            CANDIDATE_OCCURRENCE_KEY_FIELD
        ):
            raise ValueError(
                "candidate_occurrence_invalid_before_source_safe_enrichment"
            )
        claimed_indexes.append(index)

    enriched = [
        _attach_predecision_market_snapshot(
            parent,
            raw_data,
            asof_utc=asof_utc,
        )
        for parent in parents
    ]
    if claimed_indexes:
        reminted = remint_candidate_occurrences_after_source_safe_transform(
            [enriched[index] for index in claimed_indexes],
            parent_candidates=[parents[index] for index in claimed_indexes],
        )
        for index, candidate in zip(claimed_indexes, reminted):
            enriched[index] = candidate
        for index in claimed_indexes:
            identity_fields = canonical_replay_candidate_instance_fields(
                enriched[index]
            )
            if (
                identity_fields.get("candidate_instance_identity_status")
                != "materialized"
                or identity_fields.get("canonical_replay_candidate_instance_key")
                != enriched[index].get(CANDIDATE_OCCURRENCE_KEY_FIELD)
            ):
                raise ValueError(
                    "candidate_occurrence_invalid_after_source_safe_enrichment"
                )
    return enriched


