def preserve_predecision_market_snapshot_fields(
    candidate: Mapping[str, Any],
    source_candidate: Mapping[str, Any],
) -> dict[str, Any]:
    """Keep source-safe closed-bar fields after geometry canonicalization."""

    preserved = dict(candidate)
    source_fields = (
        dict(source_candidate.get("source_fields"))
        if isinstance(source_candidate.get("source_fields"), Mapping)
        else {}
    )
    if source_fields:
        merged_fields = (
            dict(preserved.get("source_fields"))
            if isinstance(preserved.get("source_fields"), Mapping)
            else {}
        )
        for key, value in source_fields.items():
            if value in (None, "", [], {}):
                continue
            if merged_fields.get(key) in (None, "", [], {}):
                merged_fields[key] = value
        preserved["source_fields"] = merged_fields
    for key in PREDECISION_MARKET_SNAPSHOT_PRESERVED_KEYS:
        value = source_candidate.get(key)
        if value in (None, "", [], {}):
            continue
        if preserved.get(key) in (None, "", [], {}):
            preserved[key] = value
    return preserved


def predecision_market_snapshot_transfer_payload(
    candidate: Mapping[str, Any],
) -> dict[str, Any]:
    """Build the compact source-safe payload consumed by scheduler/order layers."""

    source_fields = (
        candidate.get("source_fields")
        if isinstance(candidate.get("source_fields"), Mapping)
        else {}
    )
    compact_source_fields: dict[str, Any] = {}
    for key in PREDECISION_MARKET_SNAPSHOT_TRANSFER_SOURCE_FIELD_KEYS:
        value = source_fields.get(key)
        if value in (None, "", [], {}):
            continue
        compact_source_fields[key] = value
    if compact_source_fields.get("current_price") in (None, "", [], {}):
        value = candidate.get("current_price")
        if value not in (None, "", [], {}):
            compact_source_fields["current_price"] = value
    top_level_fields: dict[str, Any] = {}
    for key in PREDECISION_MARKET_SNAPSHOT_PRESERVED_KEYS:
        value = candidate.get(key)
        if value in (None, "", [], {}):
            continue
        top_level_fields[key] = value
    if not compact_source_fields and not top_level_fields:
        return {}
    payload: dict[str, Any] = dict(top_level_fields)
    if compact_source_fields:
        payload["source_fields"] = compact_source_fields
        payload["candidate_source_fields"] = dict(compact_source_fields)
        payload["predecision_market_snapshot_source_field_keys"] = sorted(
            compact_source_fields
        )
    if isinstance(payload.get("poi_state"), Mapping) or isinstance(
        compact_source_fields.get("poi_state"),
        Mapping,
    ):
        payload["poi_state_transfer_status"] = POI_STATE_TRANSFER_STATUS
    payload["predecision_market_snapshot_transfer_status"] = (
        PREDECISION_MARKET_SNAPSHOT_TRANSFER_STATUS
    )
    payload["predecision_market_snapshot_source_boundary"] = (
        PREDECISION_MARKET_SNAPSHOT_TRANSFER_BOUNDARY
    )
    return payload


def merge_predecision_market_snapshot_transfer_payload(
    row: Mapping[str, Any],
    payload: Mapping[str, Any],
) -> dict[str, Any]:
    """Attach compact market snapshot fields to scheduler-facing decision inputs."""

    merged = dict(row)
    if not payload:
        return merged
    for key, value in payload.items():
        if isinstance(value, Mapping):
            merged[key] = dict(value)
        elif isinstance(value, list):
            merged[key] = list(value)
        else:
            merged[key] = value
    for inputs_key in (
        "scheduler_candidate_decision_inputs",
        "candidate_decision_inputs",
    ):
        decision_inputs = (
            dict(merged.get(inputs_key))
            if isinstance(merged.get(inputs_key), Mapping)
            else {}
        )
        for field_key in ("source_fields", "candidate_source_fields"):
            fields = payload.get(field_key)
            if not isinstance(fields, Mapping) or not fields:
                continue
            input_fields = (
                dict(decision_inputs.get(field_key))
                if isinstance(decision_inputs.get(field_key), Mapping)
                else {}
            )
            for key, value in fields.items():
                if value in (None, "", [], {}):
                    continue
                if input_fields.get(key) in (None, "", [], {}):
                    input_fields[key] = value
            decision_inputs[field_key] = input_fields
        for key in (
            *PREDECISION_MARKET_SNAPSHOT_PRESERVED_KEYS,
            "predecision_market_snapshot_transfer_status",
            "predecision_market_snapshot_source_boundary",
            "predecision_market_snapshot_source_field_keys",
            "poi_state_transfer_status",
        ):
            value = payload.get(key)
            if value in (None, "", [], {}):
                continue
            if decision_inputs.get(key) in (None, "", [], {}):
                decision_inputs[key] = list(value) if isinstance(value, list) else value
        merged[inputs_key] = decision_inputs
    return merged


def account_row(
    *,
    campaign: str,
    phase: str,
    day: str,
    event: str,
    account: AccountState,
    candidate_id: str | None = None,
    order_id: str | None = None,
    trade_id: str | None = None,
    event_time_utc: str | None = None,
    balance_before: float | None = None,
    pnl_cash: float = 0.0,
    final_r: float | None = None,
    net_proxy_r: float | None = None,
    gross_r: float | None = None,
    expected_cost_r: float | None = None,
    risk_cash: float | None = None,
    risk_authority: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    start = account.ensure_day(day)
    daily_dd = 0.0 if start <= 0 else max(0.0, (start - account.balance) / start * 100.0)
    risk_authority = risk_authority if isinstance(risk_authority, Mapping) else {}
    r_identity_check = None
    if gross_r is not None and expected_cost_r is not None and net_proxy_r is not None:
        gross_value = safe_float(gross_r, math.nan)
        cost_value = safe_float(expected_cost_r, math.nan)
        net_value = safe_float(net_proxy_r, math.nan)
        if all(math.isfinite(value) for value in (gross_value, cost_value, net_value)):
            r_identity_check = round(gross_value - cost_value - net_value, 8)
    return {
        "campaign": campaign,
        "phase": phase,
        "trading_day": day,
        "event": event,
        "event_time_utc": event_time_utc,
        "candidate_id": candidate_id,
        "simulated_order_id": order_id,
        "simulated_trade_id": trade_id,
        "balance_before": round(balance_before if balance_before is not None else account.balance, 8),
        "balance_after": round(account.balance, 8),
        "equity_after": round(account.equity, 8),
        "peak_equity_after": round(account.peak_equity, 8),
        "pnl_cash": round(pnl_cash, 8),
        "final_r": final_r,
        "gross_r": gross_r,
        "expected_cost_r": expected_cost_r,
        "net_proxy_r": net_proxy_r,
        "r_identity_check": r_identity_check,
        "risk_cash": risk_cash,
        "risk_authority": dict(risk_authority),
        "risk_per_trade_pct": risk_authority.get("risk_per_trade_pct"),
        "risk_config_source": risk_authority.get("risk_config_source"),
        "selected_cell_risk_pct": risk_authority.get("selected_cell_risk_pct"),
        "scheduler_approved_risk_pct": risk_authority.get("scheduler_approved_risk_pct"),
        "portfolio_ceiling_pct": risk_authority.get("portfolio_ceiling_pct"),
        "cluster_correlation_ceiling_pct": risk_authority.get("cluster_correlation_ceiling_pct"),
        "open_risk_pct_before": risk_authority.get("open_risk_pct_before"),
        "pending_risk_pct_before": risk_authority.get("pending_risk_pct_before"),
        "same_symbol_lifecycle_exposure_risk_pct": risk_authority.get(
            "same_symbol_lifecycle_exposure_risk_pct"
        ),
        "daily_runtime_headroom_pct_before": risk_authority.get(
            "daily_runtime_headroom_pct_before"
        ),
        "overall_runtime_headroom_pct_before": risk_authority.get(
            "overall_runtime_headroom_pct_before"
        ),
        "daily_risk_order_budget_enabled": risk_authority.get(
            "daily_risk_order_budget_enabled"
        ),
        "daily_accepted_risk_order_count_before": risk_authority.get(
            "daily_accepted_risk_order_count_before"
        ),
        "daily_accepted_risk_order_count_after": account.accepted_risk_order_count(day),
        "daily_accepted_risk_order_limit": risk_authority.get(
            "daily_accepted_risk_order_limit"
        ),
        "daily_accepted_risk_order_remaining_before": risk_authority.get(
            "daily_accepted_risk_order_remaining_before"
        ),
        "daily_risk_order_budget_exhausted": risk_authority.get(
            "daily_risk_order_budget_exhausted"
        ),
        "daily_accepted_risk_pct_before": risk_authority.get(
            "daily_accepted_risk_pct_before"
        ),
        "daily_accepted_risk_pct_after": round(account.accepted_risk_pct(day), 12),
        "dynamic_daily_drawdown_budget_enabled": risk_authority.get(
            "dynamic_daily_drawdown_budget_enabled"
        ),
        "dynamic_daily_drawdown_budget_status": risk_authority.get(
            "dynamic_daily_drawdown_budget_status"
        ),
        "dynamic_daily_drawdown_budget_reason": risk_authority.get(
            "dynamic_daily_drawdown_budget_reason"
        ),
        "dynamic_daily_drawdown_budget_available_pct": risk_authority.get(
            "dynamic_daily_drawdown_budget_available_pct"
        ),
        "dynamic_daily_drawdown_budget_approved_risk_pct": risk_authority.get(
            "dynamic_daily_drawdown_budget_approved_risk_pct"
        ),
        "risk_decision": risk_authority.get("risk_decision"),
        "risk_decision_reason": risk_authority.get("risk_decision_reason"),
        "order_size_units_proxy": risk_authority.get("order_size_units_proxy"),
        "risk_authority_packet_hash_sha256": risk_authority.get("packet_hash_sha256"),
        "daily_start_balance": round(start, 8),
        "daily_drawdown_pct": round(daily_dd, 8),
        "max_drawdown_pct": round(account.max_drawdown_pct, 8),
        "evidence_class": SIM_EVIDENCE_CLASS,
        "broker_account_mutation": False,
    }


def ledger_event_sort_key(item: tuple[int, Mapping[str, Any]]) -> tuple[str, str, int]:
    index, row = item
    event_time = first_present(
        row.get("event_time_utc"),
        row.get("decision_time_utc"),
        row.get("asof_utc"),
        row.get("fill_time_utc"),
        row.get("close_time_utc"),
        row.get("expiry_utc"),
    )
    parsed = parse_utc(event_time)
    campaign = str(row.get("campaign") or row.get("phase") or "")
    return (campaign, iso(parsed) or "9999-12-31T00:00:00+00:00", index)


def sort_event_ledgers(ledgers: dict[str, list[dict[str, Any]]]) -> None:
    for key in ("account", "event", "order", "trade", "oracle", "exit"):
        if key not in ledgers:
            continue
        ledgers[key] = [
            row for _index, row in sorted(enumerate(ledgers[key]), key=ledger_event_sort_key)
        ]


