POST_WINDOW_CANDIDATE_RETAINED_CONTAINER_FIELDS: tuple[str, ...] = (
    "source_required_fields",
    "same_symbol_replay_exposure_context",
)


def post_window_candidate_retention_row(
    row: Mapping[str, Any],
) -> dict[str, Any]:
    """Keep only candidate truth consumed after its decision window closes."""

    retained = {
        key: value
        for key, value in row.items()
        if not isinstance(value, (Mapping, list, tuple, set, frozenset))
    }
    for field in POST_WINDOW_CANDIDATE_RETAINED_CONTAINER_FIELDS:
        if field in row:
            retained[field] = copy.deepcopy(row[field])
    return retained


def reconcile_terminal_package_execution_truth(
    ledgers: MutableMapping[str, list[dict[str, Any]]],
) -> dict[str, int]:
    """Project exact terminal bindings back to candidate and scorecard rows.

    Runtime decisions are complete before this function runs. The projection is
    ledger-only and prevents a stale pre-terminal false alias from contradicting
    an exact order/trade binding for the same candidate instance.
    """

    terminal_by_instance: dict[str, tuple[int, str, Mapping[str, Any]]] = {}

    def instance_key(row: Mapping[str, Any]) -> str:
        key = str(
            first_present(
                row.get("canonical_replay_candidate_instance_key"),
                row.get("risk_finalizer_probe_instance_key"),
                row.get("source_bound_replay_candidate_instance_key"),
            )
            or ""
        ).strip()
        if key:
            return key
        candidate_id = str(
            first_present(row.get("candidate_id"), row.get("selected_candidate_id"))
            or ""
        ).strip()
        decision_time = str(
            first_present(
                row.get("decision_time_utc"),
                row.get("candidate_instance_time_utc"),
            )
            or ""
        ).strip()
        return (
            risk_finalizer_probe_instance_key(candidate_id, decision_time)
            if candidate_id and decision_time
            else ""
        )

    def terminal_rank(row: Mapping[str, Any], ledger_name: str) -> int:
        status = str(
            row.get("package_replay_order_executable_transfer_status") or ""
        ).strip()
        if ledger_name == "trade" and status == "trade_bound":
            return 4
        if status == "trade_bound":
            return 3
        if status == "order_bound":
            return 2
        if status in {
            "final_blocked",
            "not_order_executable",
            "terminal_lifecycle_deferred_source_gap",
        }:
            return 1
        return 0

    for ledger_name in ("order", "trade"):
        for terminal_row in ledgers.get(ledger_name, []):
            canonical_terminal_row = normalize_package_new_entry_authority_ledger_row(
                copy.deepcopy(terminal_row)
            )
            key = instance_key(canonical_terminal_row)
            rank = terminal_rank(canonical_terminal_row, ledger_name)
            if not key or rank <= 0:
                continue
            previous = terminal_by_instance.get(key)
            if previous is None or rank >= previous[0]:
                terminal_by_instance[key] = (
                    rank,
                    ledger_name,
                    canonical_terminal_row,
                )

    counts: Counter[str] = Counter()
    for ledger_name in ("candidate", "scorecard"):
        for row in ledgers.get(ledger_name, []):
            if ledger_name == "scorecard":
                raw_selected_keys = first_present(
                    row.get("risk_admitted_final_selected_candidate_instance_keys"),
                    row.get("selected_candidate_instance_keys"),
                    (),
                )
                if not isinstance(raw_selected_keys, Sequence) or isinstance(
                    raw_selected_keys,
                    (str, bytes, bytearray),
                ):
                    raw_selected_keys = ()
                selected_keys = {
                    str(item).strip()
                    for item in raw_selected_keys
                    if str(item or "").strip()
                }
                selected_key = str(
                    first_present(
                        row.get("selected_candidate_instance_key"),
                        next(iter(selected_keys)) if len(selected_keys) == 1 else None,
                    )
                    or ""
                ).strip()
                if not selected_key:
                    selected_key = instance_key(row)
                key = selected_key
            else:
                key = instance_key(row)
            terminal = terminal_by_instance.get(key)
            if terminal is None:
                continue
            _rank, terminal_ledger, terminal_row = terminal
            changed_fields: list[str] = []
            terminal_transfer_status = str(
                terminal_row.get(
                    "package_replay_order_executable_transfer_status"
                )
                or ""
            ).strip()
            terminal_authority_fields = (
                package_new_entry_authority_attribution_fields(terminal_row)
                if terminal_transfer_status in {"order_bound", "trade_bound"}
                else {}
            )
            terminal_signed_authority_valid = bool(
                terminal_authority_fields.get(
                    "package_new_entry_authority_valid"
                )
                is True
                and str(
                    terminal_authority_fields.get(
                        "package_new_entry_authority_status"
                    )
                    or ""
                ).strip()
                == "valid_signed_predecision_new_entry_authority"
            )
            if terminal_signed_authority_valid:
                for field, value in terminal_authority_fields.items():
                    terminal_value = copy.deepcopy(value)
                    if row.get(field) == terminal_value:
                        continue
                    if field in row:
                        row.setdefault(
                            f"{field}_before_terminal_execution_truth_reconciliation",
                            copy.deepcopy(row.get(field)),
                        )
                    row[field] = terminal_value
                    changed_fields.append(field)
            for field in TERMINAL_PACKAGE_EXECUTION_TRUTH_FIELDS:
                if field not in terminal_row:
                    continue
                terminal_value = copy.deepcopy(terminal_row.get(field))
                if row.get(field) == terminal_value:
                    continue
                if field in row:
                    preterminal_value = copy.deepcopy(row.get(field))
                    if (
                        field in FINAL_SERIALIZATION_EFFECTIVE_EXECUTABLE_CLAIM_FIELDS
                        and _runtime_bool(preterminal_value, False)
                    ):
                        row.setdefault(
                            f"{field}_pre_finalization",
                            preterminal_value,
                        )
                    elif (
                        field
                        in FINAL_SERIALIZATION_EFFECTIVE_EXECUTABLE_PROVENANCE_FIELDS
                        and preterminal_value not in (None, "", [], {})
                        and not str(preterminal_value).startswith(
                            "final_transfer_blocked:"
                        )
                        and not (
                            field.endswith("authority_source")
                            and preterminal_value
                            == "package_replay_order_executable_transfer_status"
                        )
                    ):
                        row.setdefault(
                            f"{field}_pre_finalization",
                            preterminal_value,
                        )
                    row.setdefault(
                        f"{field}_before_terminal_execution_truth_reconciliation",
                        preterminal_value,
                    )
                row[field] = terminal_value
                changed_fields.append(field)
            if (
                not isinstance(row.get("same_symbol_replay_exposure_context"), Mapping)
                and isinstance(
                    terminal_row.get("same_symbol_replay_exposure_context"), Mapping
                )
            ):
                row["same_symbol_replay_exposure_context"] = copy.deepcopy(
                    terminal_row["same_symbol_replay_exposure_context"]
                )
                changed_fields.append("same_symbol_replay_exposure_context")
            row.update(
                {
                    "terminal_execution_truth_reconciliation_status": (
                        "exact_candidate_instance_terminal_binding_reconciled"
                    ),
                    "terminal_execution_truth_reconciliation_source_ledger": (
                        terminal_ledger
                    ),
                    "terminal_execution_truth_reconciliation_instance_key": key,
                    "terminal_execution_truth_reconciliation_changed_fields": sorted(
                        changed_fields
                    ),
                    "terminal_execution_truth_reconciliation_source_boundary": (
                        "postdecision_terminal_ledger_binding_no_runtime_authority_effect"
                    ),
                    "terminal_execution_truth_reconciliation_uses_outcome_fields": True,
                    "terminal_execution_truth_reconciliation_signed_authority_status": (
                        "exact_terminal_signed_authority_reconciled"
                        if terminal_signed_authority_valid
                        else "terminal_binding_without_valid_signed_authority"
                        if terminal_transfer_status in {"order_bound", "trade_bound"}
                        else "terminal_blocked_no_signed_authority_reconciliation_required"
                    ),
                }
            )
            counts[f"{ledger_name}_rows_reconciled"] += 1
            counts[f"{ledger_name}_fields_reconciled"] += len(changed_fields)
    counts["terminal_candidate_instances"] = len(terminal_by_instance)
    return {key: int(value) for key, value in sorted(counts.items())}


def path_final_r(
    *,
    oracle: Mapping[str, Any],
    partial_be_runner: bool,
    allow_unscoreable_terminal_diagnostic: bool = False,
) -> tuple[float | None, str, float | None]:
    fill_status = str(oracle.get("fill_status") or "")
    if not fill_status.startswith("filled"):
        return None, "not_filled_no_trade", None
    target_r = safe_float(oracle.get("target_r"), 0.0)
    if (
        oracle.get("terminal_r_scoreable") is False
        and not allow_unscoreable_terminal_diagnostic
    ):
        return (
            None,
            str(
                oracle.get("terminal_r_scoreability_status")
                or "entry_fill_executable_terminal_r_unscoreable"
            ),
            target_r,
        )
    terminal = str(oracle.get("terminal_outcome") or "")
    milestones = oracle.get("milestones") if isinstance(oracle.get("milestones"), Mapping) else {}
    one_r = (
        milestones.get("r_1")
        or milestones.get("r_1_0")
        or milestones.get("1r")
        or milestones.get("1.0r")
        or {}
    )
    one_r_hit = bool(
        isinstance(one_r, Mapping)
        and (one_r.get("touched") or one_r.get("reached"))
    )
    if terminal == "target_reached_before_stop":
        return target_r, "target_reached_before_stop", target_r
    if terminal == "stop_reached_before_target":
        if partial_be_runner and one_r_hit:
            return 0.5, "partial_be_runner_1r_harvest_then_breakeven_stop_simulated", target_r
        return -1.0, "stop_reached_before_target", target_r
    close_mark_r = oracle.get("close_mark_r")
    if (
        ("ambiguous" in terminal or oracle.get("same_bar_ambiguity"))
        and terminal != "filled_time_stop_close_mark"
    ):
        return -1.0, "same_bar_ambiguity_conservative_stop_close", target_r
    if isinstance(close_mark_r, (int, float)) and math.isfinite(float(close_mark_r)):
        source = str(oracle.get("close_mark_source") or oracle.get("source") or "postdecision_path")
        bounded_close_r = max(-1.0, min(float(close_mark_r), target_r if target_r else float(close_mark_r)))
        if partial_be_runner and one_r_hit:
            remaining_r = max(0.0, bounded_close_r)
            return round(0.5 + (0.5 * remaining_r), 8), f"time_stop_close_after_partial_harvest_from_{source}", target_r
        return round(bounded_close_r, 8), f"time_stop_close_mark_from_{source}", target_r
    return None, "source_required_filled_no_terminal_close_mark_missing", target_r


