def fill_realism_ledger_fields(
    oracle: Mapping[str, Any],
    *,
    prefix: str = "",
) -> dict[str, Any]:
    fields = {key: oracle.get(key) for key in FILL_REALISM_LEDGER_KEYS if key in oracle}
    if not prefix:
        return fields
    return {f"{prefix}{key}": value for key, value in fields.items()}


def classify_ordered_path_fill_realism(
    oracle: Mapping[str, Any],
    *,
    source: str | None = None,
    immediate_marketable_fill: bool = False,
) -> dict[str, Any]:
    """Separate entry-fill truth from terminal-R truth before materialization."""

    output = dict(oracle)
    source_lower = str(source or output.get("source") or "").strip().lower()
    fill_status = str(output.get("fill_status") or "").strip()
    filled = fill_status.startswith("filled")
    existing_class = str(output.get("fill_realism_class") or "").strip()
    source_gaps = {
        str(item).strip()
        for item in output.get("source_gaps") or ()
        if str(item or "").strip()
    }
    entry_not_touched = bool(
        not filled
        and source_lower in {"m1", "tick"}
        and f"entry_not_touched_in_post_asof_{source_lower}_path" in source_gaps
    )
    ordered_tick_sequence_gaps = tuple(
        item
        for item in sorted(source_gaps)
        if item
        in {
            "ordered_tick_required_for_adverse_before_profit_sequence",
            "ordered_tick_required_for_same_bar_target_stop_sequence",
        }
        and output.get("ordered_tick_truth_satisfied") is not True
    )

    def _demote_diagnostic(class_name: str, reason: str) -> None:
        original_fill_status = output.get("fill_status")
        original_fill_time = output.get("fill_time_utc")
        original_fill_price = output.get("fill_price")
        original_terminal = output.get("terminal_outcome")
        output.update(
            {
                "fill_realism_class": class_name,
                "fill_realism_executable": False,
                "fill_realism_reason": reason,
                "fill_realism_diagnostic_fill_status": original_fill_status,
                "fill_realism_diagnostic_fill_time_utc": original_fill_time,
                "fill_realism_diagnostic_fill_price": original_fill_price,
                "fill_realism_diagnostic_terminal_outcome": original_terminal,
                "entry_fill_executable": False,
                "entry_fill_authority_status": (
                    "entry_fill_diagnostic_non_executable"
                ),
                "entry_fill_authority_reason": reason,
                "terminal_r_scoreable": False,
                "terminal_r_scoreability_status": (
                    "entry_fill_not_executable_no_terminal_r"
                ),
                "terminal_r_scoreability_reason": reason,
                "fill_status": "not_filled_fill_realism_diagnostic_only",
                "fill_time_utc": None,
                "fill_price": None,
                "terminal_outcome": f"{class_name}_diagnostic_non_executable",
                "diagnostic_fill_only": True,
                "package_execution_result_scope": "diagnostic_counterfactual_only",
            }
        )

    if immediate_marketable_fill and filled:
        output.update(
            {
                "fill_realism_class": "source_safe_immediate_marketable",
                "fill_realism_executable": True,
                "fill_realism_reason": (
                    "filled_from_predecision_marketable_limit_source_time"
                ),
                "fill_realism_source_boundary": (
                    "predecision_market_price_source_time_at_or_before_decision"
                ),
                "entry_fill_executable": True,
                "entry_fill_authority_status": (
                    "source_safe_immediate_marketable_entry_fill"
                ),
                "entry_fill_authority_reason": (
                    "predecision_marketable_limit_route_confirmed"
                ),
                "entry_fill_authority_source_boundary": (
                    "predecision_marketable_limit_at_decision"
                ),
                "diagnostic_fill_only": False,
            }
        )
    elif source_lower == "m15_proxy":
        if filled:
            _demote_diagnostic(
                "m15_proxy",
                "postdecision_m15_proxy_not_executable_order_fill_truth",
            )
        else:
            output.update(
                {
                    "fill_realism_class": "m15_proxy",
                    "fill_realism_executable": False,
                    "fill_realism_reason": (
                        "postdecision_m15_proxy_diagnostic_path_not_executable"
                    ),
                    "diagnostic_fill_only": True,
                    "package_execution_result_scope": "diagnostic_counterfactual_only",
                }
            )
    elif entry_not_touched:
        output.update(
            {
                "fill_realism_class": "not_filled",
                "fill_realism_executable": False,
                "fill_realism_reason": (
                    "entry_not_touched_in_available_post_asof_ordered_path"
                ),
                "fill_realism_source_boundary": (
                    "post_asof_ordered_path_available_entry_not_touched"
                ),
                "diagnostic_fill_only": False,
                "entry_fill_executable": False,
                "entry_fill_authority_status": "entry_not_touched_before_expiry",
                "entry_fill_authority_reason": (
                    "entry_not_touched_in_available_post_asof_ordered_path"
                ),
                "entry_fill_authority_source_boundary": (
                    "post_asof_ordered_path_available_entry_not_touched"
                ),
            }
        )
        if (
            str(output.get("package_execution_result_scope") or "")
            == "diagnostic_counterfactual_only"
        ):
            output.pop("package_execution_result_scope", None)
    elif existing_class == "first_touch_optimistic":
        output["fill_realism_executable"] = False
        output.setdefault(
            "fill_realism_reason",
            "passive_limit_first_touch_without_queue_realism_confirmation",
        )
        output.setdefault("diagnostic_fill_only", True)
        output.setdefault(
            "package_execution_result_scope",
            "diagnostic_counterfactual_only",
        )
        if filled:
            _demote_diagnostic(
                "first_touch_optimistic",
                str(output.get("fill_realism_reason") or "first_touch_optimistic"),
            )
    elif existing_class:
        if existing_class == "guarded_market_fallback_elapsed_path" and source_lower == "m1":
            _demote_diagnostic(
                "guarded_market_fallback_m1_elapsed_path_no_queue_realism",
                "postdecision_m1_guarded_market_fallback_without_tick_or_queue_confirmation",
            )
            output["fill_realism_source_boundary"] = (
                "post_asof_m1_guarded_market_fallback_elapsed_path_diagnostic_only"
            )
            output["fill_realism_queue_model"] = "missing_market_or_queue_confirmation"
        elif existing_class in {
            "m15_proxy",
            "source_gap",
            "not_filled",
            "legacy_m1_first_touch_no_queue_realism",
        }:
            output.setdefault("fill_realism_executable", False)
            if filled and existing_class == "legacy_m1_first_touch_no_queue_realism":
                _demote_diagnostic(
                    "legacy_m1_first_touch_no_queue_realism",
                    "postdecision_m1_first_touch_without_tick_or_queue_confirmation",
                )
        else:
            output.setdefault("fill_realism_executable", filled)
    elif filled and source_lower == "tick":
        output.update(
            {
                "fill_realism_class": "ordered_tick_entry_touch",
                "fill_realism_executable": True,
                "fill_realism_reason": "ordered_tick_path_confirmed_entry_touch",
                "fill_realism_source_boundary": "post_asof_ordered_tick_path",
            }
        )
    elif filled and source_lower == "m1":
        _demote_diagnostic(
            "legacy_m1_first_touch_no_queue_realism",
            "postdecision_m1_first_touch_without_tick_or_queue_confirmation",
        )
        output["fill_realism_source_boundary"] = (
            "post_asof_ordered_m1_path_legacy_first_touch_diagnostic_only"
        )
        output["fill_realism_queue_model"] = "missing_passive_queue_confirmation"
    elif source_lower == "source_gap" or output.get("source_gaps"):
        output.update(
            {
                "fill_realism_class": "source_gap",
                "fill_realism_executable": False,
                "fill_realism_reason": "postdecision_ordered_path_source_gap_or_entry_not_touched",
            }
        )
    else:
        output.update(
            {
                "fill_realism_class": "not_filled",
                "fill_realism_executable": False,
                "fill_realism_reason": "entry_not_filled_before_expiry",
            }
        )

    fill_status = str(output.get("fill_status") or "").strip()
    filled = fill_status.startswith("filled")
    entry_fill_executable = bool(
        filled
        and output.get("fill_realism_executable") is not False
        and output.get("diagnostic_fill_only") is not True
    )
    output["entry_fill_executable"] = entry_fill_executable
    output.setdefault(
        "entry_fill_authority_status",
        "entry_fill_executable"
        if entry_fill_executable
        else "entry_fill_not_executable_or_not_filled",
    )
    output.setdefault(
        "entry_fill_authority_reason",
        output.get("fill_realism_reason"),
    )
    output.setdefault(
        "entry_fill_authority_source_boundary",
        output.get("fill_realism_source_boundary"),
    )

    terminal_source_gap = source_lower in {"m15_proxy", "source_gap", ""}
    terminal_r_scoreable = bool(
        entry_fill_executable
        and not ordered_tick_sequence_gaps
        and not terminal_source_gap
    )
    output["terminal_r_scoreable"] = terminal_r_scoreable
    if terminal_r_scoreable:
        output["terminal_r_scoreability_status"] = (
            "ordered_tick_terminal_r_scoreable"
            if source_lower == "tick"
            else "ordered_m1_proxy_terminal_r_scoreable"
        )
        output["terminal_r_scoreability_reason"] = None
    elif entry_fill_executable and ordered_tick_sequence_gaps:
        reason = ",".join(ordered_tick_sequence_gaps)
        output.update(
            {
                "terminal_r_scoreability_status": (
                    "entry_fill_executable_terminal_r_ordered_tick_sequence_required"
                ),
                "terminal_r_scoreability_reason": reason,
                "terminal_r_diagnostic_outcome": output.get("terminal_outcome"),
                "diagnostic_fill_only": False,
                "package_execution_result_scope": (
                    "entry_fill_executable_terminal_r_unscoreable"
                ),
            }
        )
    elif entry_fill_executable:
        output.update(
            {
                "terminal_r_scoreability_status": (
                    "entry_fill_executable_terminal_path_source_gap"
                ),
                "terminal_r_scoreability_reason": (
                    "postdecision_terminal_path_source_not_scoreable"
                ),
                "terminal_r_diagnostic_outcome": output.get("terminal_outcome"),
                "diagnostic_fill_only": False,
                "package_execution_result_scope": (
                    "entry_fill_executable_terminal_r_unscoreable"
                ),
            }
        )
    else:
        output.setdefault(
            "terminal_r_scoreability_status",
            "not_filled_no_terminal_r",
        )
        output.setdefault("terminal_r_scoreability_reason", None)
    return output


def selected_execution_policy_spec_for_replay(
    *,
    selected_policy: Any,
    geometry: Mapping[str, Any] | None,
    oracle: Mapping[str, Any],
):
    policy = str(selected_policy or "").strip().lower()
    geometry = geometry if isinstance(geometry, Mapping) else {}
    target_destination = geometry.get("target_destination")
    target_destination = (
        target_destination if isinstance(target_destination, Mapping) else {}
    )
    final_target_r = safe_float(
        first_present(
            target_destination.get("final_target_r"),
            geometry.get("final_target_r"),
            oracle.get("target_r"),
        ),
        0.0,
    )
    trigger_r = safe_float(target_destination.get("trigger_r"), 1.0)
    time_stop_bars = int(
        max(1, safe_float(target_destination.get("time_stop_bars"), 32.0))
    )
    if policy == "partial_be_runner":
        return partial_be_policy(
            tp1_r=trigger_r,
            final_target_r=final_target_r or 3.0,
            partial_close_ratio=safe_float(
                target_destination.get("partial_close_ratio"),
                0.5,
            ),
        )
    if policy == "be_after_trigger":
        return be_only_policy(
            trigger_r=trigger_r,
            final_target_r=final_target_r or 1.5,
        )
    if policy == "trailing_runner":
        return trailing_policy(
            trigger_r=trigger_r,
            gap_r=safe_float(target_destination.get("trail_gap_r"), 0.5),
            final_target_r=final_target_r if final_target_r > 0 else None,
        )
    if policy == "momentum_exhaustion":
        pullback_r = safe_float(
            first_present(
                target_destination.get("pullback_r"),
                target_destination.get("momentum_pullback_r"),
                geometry.get("pullback_r"),
                geometry.get("momentum_pullback_r"),
                oracle.get("momentum_pullback_r"),
            ),
            0.4,
        )
        momentum_time_stop_bars = first_present(
            target_destination.get("momentum_time_stop_bars"),
            target_destination.get("time_stop_bars"),
            geometry.get("momentum_time_stop_bars"),
            geometry.get("time_stop_bars"),
            oracle.get("momentum_time_stop_bars"),
        )
        return momentum_exhaustion_policy(
            trigger_r=trigger_r,
            pullback_r=pullback_r,
            final_target_r=final_target_r or 2.0,
            time_stop_bars=(
                int(max(1, safe_float(momentum_time_stop_bars, 0.0)))
                if momentum_time_stop_bars not in (None, "")
                else None
            ),
        )
    if policy == "time_stop":
        return time_stop_policy(
            bars=time_stop_bars,
            final_target_r=final_target_r if final_target_r > 0 else None,
        )
    return None


def selected_policy_replay_observations(
    *,
    oracle: Mapping[str, Any],
    rows: Iterable[Mapping[str, Any]],
    candidate: Mapping[str, Any],
    observation_quote_details: list[dict[str, Any]] | None = None,
) -> list[PathObservation]:
    fill_time = parse_utc(oracle.get("fill_time_utc"))
    if fill_time is None:
        return []
    side = str(candidate.get("side") or "").upper()
    entry = safe_float(candidate.get("entry_price"))
    stop = safe_float(candidate.get("stop_loss"))
    risk = abs(entry - stop)
    if risk <= 0 or side not in {"LONG", "SHORT"}:
        return []
    source = str(oracle.get("source") or "m1").lower()
    observations: list[PathObservation] = []
    for row in rows:
        ts = parse_row_time(row)
        if ts is None or ts <= fill_time:
            continue
        index = len(observations) + 1
        if source == "tick":
            price, price_source, quote_side, executable_close_side = (
                _tick_close_price_with_source(row, side=side)
            )
            if price is None:
                continue
            r_value = (price - entry) / risk if side == "LONG" else (entry - price) / risk
            observations.append(
                PathObservation(
                    index=index,
                    open_r=r_value,
                    high_r=r_value,
                    low_r=r_value,
                    close_r=r_value,
                    time_utc=iso(ts),
                    source_mode="tick",
                )
            )
            if observation_quote_details is not None:
                observation_quote_details.append(
                    {
                        "index": index,
                        "time_utc": iso(ts),
                        "price": price,
                        "price_source": price_source,
                        "quote_side": quote_side,
                        "executable_close_side": executable_close_side,
                    }
                )
            continue
        try:
            observation = observation_from_ohlc(
                index=index,
                row=row,
                entry=entry,
                stop=stop,
                side=side,
                time_key="time_utc" if row.get("time_utc") is not None else "time",
            )
        except (TypeError, ValueError, KeyError):
            continue
        observations.append(
            PathObservation(
                index=observation.index,
                open_r=observation.open_r,
                high_r=observation.high_r,
                low_r=observation.low_r,
                close_r=observation.close_r,
                time_utc=observation.time_utc,
                source_mode="m1",
            )
        )
        if observation_quote_details is not None:
            observation_quote_details.append(
                {
                    "index": observation.index,
                    "time_utc": observation.time_utc,
                    "price": None,
                    "price_source": "m1_ohlc_path",
                    "quote_side": "ohlc",
                    "executable_close_side": False,
                }
            )
    return observations


def selected_policy_replay_final_r_authority_detail(
    *,
    oracle: Mapping[str, Any],
    candidate: Mapping[str, Any],
    packets: Mapping[str, Any],
    same_bar_ambiguity: bool,
    exit_quote_detail: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Return whether selected-policy replay may overwrite terminal R.

    M1/M15 OHLC paths are useful diagnostics, but they are not ordered tick
    truth. They must not become terminal-R authority for selected execution
    policy replay.
    """

    source = str(
        first_present(
            oracle.get("source"),
            oracle.get("path_lookup_source"),
            oracle.get("terminal_r_source"),
            "",
        )
        or ""
    ).strip().lower()
    ordered_tick_truth = bool(
        source == "tick"
        and (
            oracle.get("ordered_tick_truth_satisfied") is True
            or oracle.get("ordered_tick_truth_satisfied_for_terminal_r") is True
        )
    )
    exit_quote_detail = (
        exit_quote_detail if isinstance(exit_quote_detail, Mapping) else {}
    )
    executable_close_side = exit_quote_detail.get("executable_close_side") is True
    quality_fields = candidate_decision_quality_fields(candidate, packets)
    selected_policy_calibration_failure = (
        selected_policy_expected_net_calibration_failure_reason(
            quality_fields
        )
    )
    if selected_policy_calibration_failure:
        return {
            "allowed": False,
            "status": (
                "selected_policy_replay_not_authoritative:"
                f"{selected_policy_calibration_failure}"
            ),
            "source_boundary": (
                "postdecision_selected_policy_replay_diagnostic_"
                "selected_policy_expected_net_uncalibrated_no_final_r_authority"
            ),
            "block_reason": selected_policy_calibration_failure,
            "ordered_tick_truth_satisfied": ordered_tick_truth,
        }
    if not ordered_tick_truth:
        reason = f"path_source_not_ordered_tick_truth:{source or 'unknown'}"
        if oracle.get("postdecision_path_proxy") is True:
            reason = f"postdecision_path_proxy_not_terminal_authority:{source or 'unknown'}"
        return {
            "allowed": False,
            "status": f"selected_policy_replay_not_authoritative:{reason}",
            "source_boundary": (
                "postdecision_selected_policy_replay_diagnostic_"
                "no_ordered_tick_terminal_r_authority"
            ),
            "block_reason": reason,
            "ordered_tick_truth_satisfied": ordered_tick_truth,
        }
    if not executable_close_side:
        reason = "ordered_tick_exit_missing_executable_close_quote_side"
        return {
            "allowed": False,
            "status": f"selected_policy_replay_not_authoritative:{reason}",
            "source_boundary": (
                "postdecision_ordered_tick_replay_missing_executable_close_side_"
                "no_final_r_authority"
            ),
            "block_reason": reason,
            "ordered_tick_truth_satisfied": ordered_tick_truth,
            "exit_price_source": exit_quote_detail.get("price_source"),
            "exit_quote_side": exit_quote_detail.get("quote_side"),
            "executable_close_side": False,
        }
    if same_bar_ambiguity:
        return {
            "allowed": False,
            "status": (
                "selected_policy_replay_not_authoritative:"
                "same_bar_ambiguity_requires_ordered_micro_path"
            ),
            "source_boundary": (
                "postdecision_selected_policy_replay_diagnostic_"
                "same_bar_ambiguity_no_final_r_authority"
            ),
            "block_reason": "same_bar_ambiguity_requires_ordered_micro_path",
            "ordered_tick_truth_satisfied": ordered_tick_truth,
        }
    return {
        "allowed": True,
        "status": "selected_policy_ordered_tick_replay_authority",
        "source_boundary": "postdecision_ordered_tick_replay_label_not_broker_ticket_truth",
        "block_reason": None,
        "ordered_tick_truth_satisfied": ordered_tick_truth,
        "exit_price_source": exit_quote_detail.get("price_source"),
        "exit_quote_side": exit_quote_detail.get("quote_side"),
        "executable_close_side": True,
    }


def apply_selected_execution_policy_replay_exit(
    *,
    oracle: dict[str, Any],
    rows: Iterable[Mapping[str, Any]],
    candidate: Mapping[str, Any],
    packets: Mapping[str, Any] | None,
    final_r: float | None,
    close_reason: str,
    target_r: float | None,
    runtime: Mapping[str, Any] | None = None,
) -> tuple[float | None, str, float | None, dict[str, Any] | None]:
    packets = packets if isinstance(packets, Mapping) else {}
    geometry = packets.get("geometry_contract")
    geometry = geometry if isinstance(geometry, Mapping) else {}
    selected_policy = (
        geometry.get("selected_policy")
        or candidate.get("dynamic_geometry_policy")
        or candidate.get("gtos_vnext_selected_cell_risk_selected_policy")
    )
    selected_policy_key = str(selected_policy or "").strip().lower()
    if not str(oracle.get("fill_status") or "").startswith("filled"):
        return final_r, close_reason, target_r, None
    if not selected_policy_key:
        return final_r, close_reason, target_r, None
    policy_spec = selected_execution_policy_spec_for_replay(
        selected_policy=selected_policy_key,
        geometry=geometry,
        oracle=oracle,
    )
    if policy_spec is None:
        return final_r, close_reason, target_r, None
    if (
        oracle.get("terminal_r_scoreable") is False
        and oracle.get("entry_fill_executable") is not True
    ):
        return final_r, close_reason, target_r, None
    selected_policy_quality_gate = selected_policy_executable_quality_gate_fields(
        candidate,
        geometry,
        packets,
        runtime=runtime,
    )
    entry_fill_terminal_r_unscoreable = bool(
        oracle.get("entry_fill_executable") is True
        and oracle.get("terminal_r_scoreable") is False
    )
    if (
        not entry_fill_terminal_r_unscoreable
        and selected_policy_quality_gate.get(
            "selected_policy_executable_quality_gate_status"
        )
        == "blocked"
    ):
        gate_failures = list(
            selected_policy_quality_gate.get(
                "selected_policy_executable_quality_gate_failures"
            )
            or []
        )
        block_reason = (
            "selected_policy_executable_quality_gate_failed:"
            + ",".join(str(item) for item in gate_failures)
            if gate_failures
            else "selected_policy_executable_quality_gate_failed"
        )
        payload = {
            "schema_version": "selected_execution_policy_replay_exit_v1",
            "selected_policy": selected_policy_key,
            "policy_name": policy_spec.name,
            "replay_status": "not_authoritative_predecision_quality_gate",
            "final_r": None,
            "exit_reason": "selected_policy_executable_quality_gate_failed",
            "exit_time_utc": None,
            "exit_index": None,
            "source_gap_reason": None,
            "observation_count": 0,
            "raw_fixed_target_final_r": final_r,
            "raw_fixed_target_close_reason": close_reason,
            "raw_fixed_target_target_r": target_r,
            "raw_selected_policy_replay_final_r_authority": False,
            "final_r_authority": False,
            "ordered_tick_final_r_authority": False,
            "m1_proxy_replay_authority": False,
            "headline_result_authority": False,
            "headline_result_authority_status": (
                "selected_policy_replay_not_headline_authority:"
                "selected_policy_executable_quality_gate_failed"
            ),
            "legacy_final_r_authority_semantics": (
                "final_r_authority_is_ordered_tick_terminal_authority_only"
            ),
            "final_r_authority_status": (
                "selected_policy_replay_not_authoritative:"
                "selected_policy_executable_quality_gate_failed"
            ),
            "final_r_authority_block_reason": block_reason,
            "ordered_tick_truth_satisfied_for_selected_policy_replay": False,
            "terminal_r_source": oracle.get("source"),
            "source_boundary": selected_policy_quality_gate.get(
                "selected_policy_executable_quality_gate_source_boundary"
            ),
            "live_broker_authority": False,
            "broker_mutation_enabled": False,
            **selected_policy_quality_gate,
        }
        oracle["selected_execution_policy_replay_exit"] = payload
        oracle["selected_execution_policy_replay_bound"] = False
        oracle["selected_execution_policy_replay_final_r_authority_status"] = payload[
            "final_r_authority_status"
        ]
        oracle["selected_execution_policy_replay_source_gap_status"] = (
            "selected_policy_executable_quality_gate_failed"
        )
        oracle["selected_policy_executable_quality_gate_status"] = (
            selected_policy_quality_gate.get(
                "selected_policy_executable_quality_gate_status"
            )
        )
        return final_r, close_reason, target_r, payload
    if entry_fill_terminal_r_unscoreable:
        terminal_status = str(
            oracle.get("terminal_r_scoreability_status")
            or "entry_fill_executable_terminal_r_unscoreable"
        )
        terminal_reason = first_present(
            oracle.get("terminal_r_scoreability_reason"),
            terminal_status,
        )
        final_r_authority_status = (
            f"selected_policy_replay_not_authoritative:{terminal_status}"
        )
        payload = {
            "schema_version": "selected_execution_policy_replay_exit_v1",
            "selected_policy": selected_policy_key,
            "policy_name": policy_spec.name,
            "selected_policy_supported": True,
            "replay_status": "diagnostic_terminal_r_unscoreable",
            "replay_attempted": False,
            "diagnostic_only": True,
            "final_r": None,
            "exit_reason": (
                "selected_policy_replay_not_attempted_terminal_r_unscoreable"
            ),
            "exit_time_utc": None,
            "exit_index": None,
            "source_gap_reason": terminal_reason,
            "observation_count": 0,
            "terminal_r_scoreable": False,
            "terminal_r_scoreability_status": terminal_status,
            "terminal_r_scoreability_reason": terminal_reason,
            "raw_fixed_target_final_r": None,
            "raw_fixed_target_close_reason": terminal_status,
            "raw_fixed_target_target_r": target_r,
            "raw_selected_policy_replay_final_r_authority": False,
            "final_r_authority": False,
            "ordered_tick_final_r_authority": False,
            "m1_proxy_replay_authority": False,
            "headline_result_authority": False,
            "headline_result_authority_status": (
                "selected_policy_replay_not_headline_authority:"
                "terminal_r_unscoreable"
            ),
            "legacy_final_r_authority_semantics": (
                "final_r_authority_is_ordered_tick_terminal_authority_only"
            ),
            "final_r_authority_status": final_r_authority_status,
            "final_r_authority_block_reason": terminal_status,
            "ordered_tick_truth_satisfied_for_selected_policy_replay": False,
            "terminal_r_source": oracle.get("source"),
            "source_boundary": (
                "postdecision_selected_policy_replay_diagnostic_"
                "terminal_r_unscoreable_no_final_r_authority"
            ),
            "live_broker_authority": False,
            "broker_mutation_enabled": False,
            **selected_policy_quality_gate,
        }
        oracle["selected_execution_policy_replay_exit"] = payload
        oracle["selected_execution_policy_replay_bound"] = False
        oracle["selected_execution_policy_replay_final_r_authority_status"] = (
            final_r_authority_status
        )
        oracle["selected_execution_policy_replay_source_gap_status"] = (
            terminal_status
        )
        oracle["selected_policy_executable_quality_gate_status"] = (
            selected_policy_quality_gate.get(
                "selected_policy_executable_quality_gate_status"
            )
        )
        return None, terminal_status, target_r, payload
    observation_quote_details: list[dict[str, Any]] = []
    observations = selected_policy_replay_observations(
        oracle=oracle,
        rows=rows,
        candidate=candidate,
        observation_quote_details=observation_quote_details,
    )
    if not observations:
        payload = {
            "schema_version": "selected_execution_policy_replay_exit_v1",
            "selected_policy": selected_policy_key,
            "policy_name": policy_spec.name,
            "replay_status": "not_replayable",
            "final_r": None,
            "exit_reason": "source_gap_no_post_fill_ordered_path_observations",
            "exit_time_utc": None,
            "exit_index": None,
            "source_gap_reason": "no_post_fill_ordered_path_observations",
            "observation_count": 0,
            "raw_fixed_target_final_r": final_r,
            "raw_fixed_target_close_reason": close_reason,
            "raw_fixed_target_target_r": target_r,
            "final_r_authority": False,
            "ordered_tick_final_r_authority": False,
            "m1_proxy_replay_authority": False,
            "headline_result_authority": False,
            "headline_result_authority_status": (
                "selected_policy_replay_not_headline_authority:not_replayable"
            ),
            "legacy_final_r_authority_semantics": (
                "final_r_authority_is_ordered_tick_terminal_authority_only"
            ),
            "final_r_authority_status": (
                "selected_policy_replay_not_authoritative:not_replayable"
            ),
            "terminal_r_source": oracle.get("source"),
            "source_boundary": (
                "postdecision_ordered_path_replay_source_gap_no_final_r_authority"
            ),
            "live_broker_authority": False,
            "broker_mutation_enabled": False,
            **selected_policy_quality_gate,
        }
        oracle["selected_execution_policy_replay_exit"] = payload
        oracle["selected_execution_policy_replay_bound"] = False
        oracle["selected_execution_policy_replay_final_r_authority_status"] = payload[
            "final_r_authority_status"
        ]
        oracle["selected_execution_policy_replay_source_gap_status"] = (
            "source_gap_no_post_fill_ordered_path_observations"
        )
        return final_r, close_reason, target_r, payload
    result = simulate_policy(policy_spec, observations, same_bar_policy="conservative")
    exit_quote_detail = next(
        (
            detail
            for detail in observation_quote_details
            if detail.get("index") == result.exit_index
        ),
        {},
    )
    raw_replay_final_r_authority = bool(
        result.final_r is not None and result.replay_status == "replayed"
    )
    authority_detail = selected_policy_replay_final_r_authority_detail(
        oracle=oracle,
        candidate=candidate,
        packets=packets,
        same_bar_ambiguity=bool(result.same_bar_ambiguity),
        exit_quote_detail=exit_quote_detail,
    )
    replay_final_r_authority = bool(
        raw_replay_final_r_authority and authority_detail.get("allowed") is True
    )
    terminal_r_source = str(oracle.get("source") or "").strip().lower()
    m1_proxy_replay_authority = bool(
        raw_replay_final_r_authority
        and not replay_final_r_authority
        and terminal_r_source == "m1"
    )
    payload = {
        "schema_version": "selected_execution_policy_replay_exit_v1",
        "selected_policy": selected_policy_key,
        "policy_name": result.policy_name,
        "replay_status": result.replay_status,
        "final_r": (
            round(float(result.final_r), 8)
            if isinstance(result.final_r, (int, float))
            and math.isfinite(float(result.final_r))
            else None
        ),
        "exit_reason": result.exit_reason,
        "exit_time_utc": result.exit_time_utc,
        "exit_index": result.exit_index,
        "mfe_r": result.mfe_r,
        "mae_r": result.mae_r,
        "partial_realized_r": result.partial_realized_r,
        "remaining_fraction": result.remaining_fraction,
        "stop_r_at_exit": result.stop_r_at_exit,
        "same_bar_ambiguity": result.same_bar_ambiguity,
        "source_gap_reason": result.source_gap_reason,
        "transition_count": len(result.transitions),
        "transitions": result.transitions,
        "observation_count": len(observations),
        "raw_fixed_target_final_r": final_r,
        "raw_fixed_target_close_reason": close_reason,
        "raw_fixed_target_target_r": target_r,
        "raw_selected_policy_replay_final_r_authority": raw_replay_final_r_authority,
        "final_r_authority": replay_final_r_authority,
        "ordered_tick_final_r_authority": replay_final_r_authority,
        "m1_proxy_replay_authority": m1_proxy_replay_authority,
        "headline_result_authority": replay_final_r_authority,
        "headline_result_authority_status": (
            "ordered_tick_final_r_headline_authority"
            if replay_final_r_authority
            else "m1_proxy_replay_diagnostic_not_headline_authority"
            if m1_proxy_replay_authority
            else "selected_policy_replay_not_headline_authority"
        ),
        "legacy_final_r_authority_semantics": (
            "final_r_authority_is_ordered_tick_terminal_authority_only"
        ),
        "final_r_authority_status": (
            str(authority_detail.get("status"))
            if raw_replay_final_r_authority
            else f"selected_policy_replay_not_authoritative:{result.replay_status}"
        ),
        "final_r_authority_block_reason": authority_detail.get("block_reason"),
        "ordered_tick_truth_satisfied_for_selected_policy_replay": (
            authority_detail.get("ordered_tick_truth_satisfied")
        ),
        "terminal_r_source": oracle.get("source"),
        "exit_price": exit_quote_detail.get("price"),
        "exit_price_source": exit_quote_detail.get("price_source"),
        "exit_quote_side": exit_quote_detail.get("quote_side"),
        "executable_close_side": exit_quote_detail.get(
            "executable_close_side"
        ),
        "source_boundary": (
            authority_detail.get("source_boundary")
            if raw_replay_final_r_authority
            else "postdecision_ordered_path_replay_source_gap_no_final_r_authority"
        ),
        "live_broker_authority": False,
        "broker_mutation_enabled": False,
        **selected_policy_quality_gate,
    }
    oracle["selected_execution_policy_replay_exit"] = payload
    oracle["selected_execution_policy_replay_bound"] = bool(
        payload["final_r_authority"]
    )
    oracle["selected_execution_policy_replay_final_r_authority_status"] = payload[
        "final_r_authority_status"
    ]
    if not payload["final_r_authority"]:
        return final_r, close_reason, target_r, payload
    replay_final_r = safe_float(payload["final_r"])
    oracle["raw_fixed_target_final_r_before_selected_policy_replay"] = final_r
    oracle["raw_fixed_target_close_reason_before_selected_policy_replay"] = close_reason
    oracle["raw_fixed_target_target_r_before_selected_policy_replay"] = target_r
    oracle["selected_policy_terminal_outcome"] = payload["exit_reason"]
    oracle["selected_policy_close_mark_time_utc"] = payload["exit_time_utc"]
    oracle["selected_policy_close_time_utc"] = payload["exit_time_utc"]
    oracle["selected_policy_exit_time_utc"] = payload["exit_time_utc"]
    oracle["selected_policy_close_mark_source"] = payload["exit_reason"]
    oracle["selected_policy_close_mark_r"] = replay_final_r
    return (
        round(replay_final_r, 8),
        f"selected_policy_replay:{payload['exit_reason']}",
        policy_spec.final_target_r if policy_spec.final_target_r is not None else target_r,
        payload,
    )


def _runtime_bool(value: Any, default: bool = False) -> bool:
    if value in (None, ""):
        return default
    if isinstance(value, bool):
        return value
    return str(value).strip().lower() in {"1", "true", "yes", "y", "on"}


def _profit_harvest_runtime_config(config: Mapping[str, Any]) -> Mapping[str, Any]:
    runtime = config.get("gtos_vnext_runtime") if isinstance(config, Mapping) else {}
    return runtime if isinstance(runtime, Mapping) else {}


def _profit_harvest_replay_observation(
    row: Mapping[str, Any],
    *,
    candidate: Mapping[str, Any],
    source: str,
) -> tuple[datetime, float, float, float] | None:
    ts = parse_row_time(row)
    if ts is None:
        return None
    side = str(candidate.get("side") or "").upper()
    entry = safe_float(candidate.get("entry_price"))
    stop = safe_float(candidate.get("stop_loss"))
    risk = abs(entry - stop)
    if risk <= 0 or side not in {"LONG", "SHORT"}:
        return None
    if source == "tick":
        price, _price_source, _quote_side, _executable = (
            _tick_close_price_with_source(row, side=side)
        )
        if price is None or not _executable:
            return None
        r_value = (price - entry) / risk if side == "LONG" else (entry - price) / risk
        return ts, r_value, r_value, r_value
    try:
        high_price = float(row.get("high", row.get("High")))
        low_price = float(row.get("low", row.get("Low")))
        close_price = float(row.get("close", row.get("Close")))
    except (TypeError, ValueError):
        return None
    if side == "LONG":
        high_r = (high_price - entry) / risk
        low_r = (low_price - entry) / risk
        close_r = (close_price - entry) / risk
    else:
        high_r = (entry - low_price) / risk
        low_r = (entry - high_price) / risk
        close_r = (entry - close_price) / risk
    return ts, high_r, low_r, close_r


def profit_harvest_mfe_capture_replay_exit(
    *,
    oracle: Mapping[str, Any],
    rows: Iterable[Mapping[str, Any]],
    candidate: Mapping[str, Any],
    config: Mapping[str, Any],
    packets: Mapping[str, Any] | None = None,
    selected_policy_replay_exit: Mapping[str, Any] | None = None,
) -> dict[str, Any] | None:
    """Replay the live profit-harvest MFE capture policy over ordered path rows.

    The live manager remains broker-ticket-bound. This helper only changes
    replay labels when post-decision ordered path rows can prove the local
    policy would have armed before the original fixed stop/target outcome.
    """

    runtime = _profit_harvest_runtime_config(config)
    if not _runtime_bool(runtime.get("profit_harvest_mfe_capture_v4_enabled"), False):
        return None
    if not str(oracle.get("fill_status") or "").startswith("filled"):
        return None
    fill_time = parse_utc(oracle.get("fill_time_utc"))
    if fill_time is None:
        return None

    packets = packets if isinstance(packets, Mapping) else {}
    geometry = packets.get("geometry_contract") if isinstance(packets.get("geometry_contract"), Mapping) else {}
    selected_policy = str(
        geometry.get("selected_policy")
        or candidate.get("dynamic_geometry_policy")
        or ""
    ).strip()
    require_dynamic = _runtime_bool(
        runtime.get("profit_harvest_mfe_capture_v4_require_vnext_dynamic_policy"),
        True,
    )
    if require_dynamic and not selected_policy:
        return None

    source = str(oracle.get("source") or "m1").lower()
    ordered_tick_truth_satisfied = (
        source == "tick" and oracle.get("ordered_tick_truth_satisfied") is True
    )
    intrabar_ordering_status = (
        "ordered_tick_truth_satisfied_fill_bar_allowed"
        if ordered_tick_truth_satisfied
        else "m1_or_unordered_path_fill_bar_excluded"
    )
    target_r_raw = oracle.get("target_r")
    target_r = (
        float(target_r_raw)
        if isinstance(target_r_raw, (int, float)) and math.isfinite(float(target_r_raw))
        else None
    )
    min_mfe_r = max(
        0.01,
        safe_float(runtime.get("profit_harvest_mfe_capture_v4_min_mfe_r"), 0.25),
    )
    stop_activation_mfe_r = max(
        min_mfe_r,
        safe_float(
            runtime.get("profit_harvest_mfe_capture_v4_stop_activation_mfe_r"),
            min_mfe_r,
        ),
    )
    target_activation_fraction = max(
        0.0,
        min(
            1.0,
            safe_float(
                runtime.get(
                    "profit_harvest_mfe_capture_v4_target_activation_fraction"
                ),
                0.0,
            ),
        ),
    )
    trail_activation_mfe_r = stop_activation_mfe_r
    if target_r is not None and target_activation_fraction > 0.0:
        trail_activation_mfe_r = max(
            trail_activation_mfe_r,
            target_r * target_activation_fraction,
        )
    trail_gap_r = max(
        0.01,
        safe_float(runtime.get("profit_harvest_mfe_capture_v4_trail_gap_r"), 0.35),
    )
    protect_floor_r = max(
        0.0,
        safe_float(runtime.get("profit_harvest_mfe_capture_v4_protect_floor_r"), 0.0),
    )
    base_protect_floor_r = protect_floor_r
    cost_aware_floor_enabled = _runtime_bool(
        runtime.get("profit_harvest_mfe_capture_v4_cost_aware_protect_floor_enabled"),
        False,
    )
    allow_m1_proxy_final_r_authority = _runtime_bool(
        runtime.get("profit_harvest_mfe_capture_v4_allow_m1_proxy_final_r_authority"),
        False,
    )
    expected_cost_r = max(
        0.0,
        safe_float(
            first_present(
                packets.get("cost_r"),
                candidate.get("expected_cost_r"),
                candidate.get("cost_r"),
            ),
            0.0,
        ),
    )
    cost_aware_margin_r = max(
        0.0,
        safe_float(
            runtime.get("profit_harvest_mfe_capture_v4_cost_aware_margin_r"),
            0.0,
        ),
    )
    if cost_aware_floor_enabled:
        protect_floor_r = max(
            protect_floor_r,
            expected_cost_r + cost_aware_margin_r,
        )
    close_on_giveback_r = max(
        0.01,
        safe_float(runtime.get("profit_harvest_mfe_capture_v4_close_on_giveback_r"), 0.50),
    )
    stale_minutes_raw = runtime.get("profit_harvest_mfe_capture_v4_stale_minutes")
    stale_minutes = (
        int(safe_float(stale_minutes_raw, 0.0))
        if stale_minutes_raw not in (None, "")
        else None
    )
    stale_min_mfe_r = max(
        0.01,
        safe_float(runtime.get("profit_harvest_mfe_capture_v4_stale_min_mfe_r"), min_mfe_r),
    )
    stale_close_below_r = safe_float(
        runtime.get("profit_harvest_mfe_capture_v4_stale_close_below_r"),
        0.0,
    )
    armed_stale_close_enabled = _runtime_bool(
        runtime.get("profit_harvest_mfe_capture_v4_armed_stale_close_enabled"),
        False,
    )
    armed_stale_minutes_raw = runtime.get(
        "profit_harvest_mfe_capture_v4_armed_stale_minutes"
    )
    armed_stale_minutes = (
        max(0, int(safe_float(armed_stale_minutes_raw, 0.0)))
        if armed_stale_minutes_raw not in (None, "")
        else None
    )
    armed_stale_min_mfe_r = max(
        0.01,
        safe_float(
            runtime.get("profit_harvest_mfe_capture_v4_armed_stale_min_mfe_r"),
            min_mfe_r,
        ),
    )
    armed_stale_close_below_r = safe_float(
        runtime.get("profit_harvest_mfe_capture_v4_armed_stale_close_below_r"),
        0.0,
    )
    min_hold_minutes_before_stop_raise = max(
        0.0,
        safe_float(
            runtime.get(
                "profit_harvest_mfe_capture_v4_min_hold_minutes_before_stop_raise"
            ),
            0.0,
        ),
    )
    selected_policy_replay_exit = (
        selected_policy_replay_exit
        if isinstance(selected_policy_replay_exit, Mapping)
        else {}
    )
    selected_policy_exit_time = parse_utc(
        selected_policy_replay_exit.get("exit_time_utc")
    )
    selected_policy_final_authority = (
        selected_policy_replay_exit.get("final_r_authority") is True
    )

    observations = [
        obs
        for obs in (
            _profit_harvest_replay_observation(row, candidate=candidate, source=source)
            for row in rows
        )
        if obs is not None
        and (
            obs[0] >= fill_time
            if ordered_tick_truth_satisfied
            else obs[0] > fill_time
        )
        and (
            selected_policy_exit_time is None
            or not selected_policy_final_authority
            or obs[0] <= selected_policy_exit_time
        )
    ]
    observations.sort(key=lambda item: item[0])
    target_time = parse_utc(oracle.get("target_first_touch_utc"))
    first_allowed_observation_time = observations[0][0] if observations else None
    target_touch_precedes_profit_harvest_observation = (
        source == "m1"
        and not ordered_tick_truth_satisfied
        and target_time is not None
        and (
            (
                first_allowed_observation_time is not None
                and target_time <= first_allowed_observation_time
            )
            or target_time <= fill_time
        )
        and str(
            first_present(
                oracle.get("close_reason_before_profit_harvest_replay"),
                oracle.get("close_mark_source"),
                oracle.get("terminal_outcome"),
                oracle.get("close_reason"),
            )
            or ""
        ).startswith("target_reached")
    )
    if target_touch_precedes_profit_harvest_observation:
        oracle["profit_harvest_mfe_capture_replay_bound"] = False
        oracle["profit_harvest_mfe_capture_replay_exit_final_r_authority"] = False
        oracle["profit_harvest_mfe_capture_replay_exit_ordered_tick_final_r_authority"] = False
        oracle["profit_harvest_mfe_capture_replay_exit_m1_proxy_replay_authority"] = False
        oracle["profit_harvest_mfe_capture_replay_exit_headline_result_authority"] = False
        oracle[
            "profit_harvest_mfe_capture_replay_exit_headline_result_authority_status"
        ] = "m1_target_before_profit_harvest_observation_not_headline_authority"
        oracle["profit_harvest_mfe_capture_replay_exit_final_r_authority_status"] = (
            "m1_target_touched_before_first_profit_harvest_observation_no_override"
        )
        oracle["profit_harvest_mfe_capture_replay_skip_reason"] = (
            "m1_target_touched_before_first_profit_harvest_observation"
        )
        oracle["profit_harvest_target_before_first_observation"] = True
        oracle["profit_harvest_target_after_exit"] = False
        oracle["profit_harvest_target_after_exit_status"] = (
            "target_before_profit_harvest_observation_no_override"
        )
        oracle["profit_harvest_target_after_exit_time_utc"] = iso(target_time)
        return None
    selected_policy_boundary_fields = {
        "profit_harvest_selected_policy_boundary_applied": bool(
            selected_policy_exit_time is not None and selected_policy_final_authority
        ),
        "profit_harvest_selected_policy_exit_time_utc": iso(
            selected_policy_exit_time
        ),
        "profit_harvest_selected_policy_final_r_authority": (
            selected_policy_final_authority
        ),
        "profit_harvest_selected_policy_boundary_semantics": (
            "sequential_overlay_truncated_at_selected_policy_exit"
            if selected_policy_exit_time is not None and selected_policy_final_authority
            else "not_applicable"
        ),
    }
    if selected_policy_boundary_fields[
        "profit_harvest_selected_policy_boundary_applied"
    ]:
        oracle.update(selected_policy_boundary_fields)
    if not observations:
        return None

    def replay_exit(payload: dict[str, Any]) -> dict[str, Any]:
        payload.update(
            {
                "profit_harvest_intrabar_ordering_status": intrabar_ordering_status,
                "ordered_tick_truth_satisfied": ordered_tick_truth_satisfied,
                "fill_bar_observation_allowed": ordered_tick_truth_satisfied,
                "ordered_tick_final_r_authority": False,
                "m1_proxy_replay_authority": False,
                "headline_result_authority": False,
                "headline_result_authority_status": (
                    "ordered_tick_final_r_headline_authority"
                    if ordered_tick_truth_satisfied
                    else "profit_harvest_replay_not_headline_authority"
                ),
                "legacy_final_r_authority_semantics": (
                    "final_r_authority_is_ordered_tick_terminal_authority_only"
                ),
                **selected_policy_boundary_fields,
            }
        )
        if payload.get("status") == "source_gap":
            payload["final_r_authority"] = False
            payload["ordered_tick_final_r_authority"] = False
            payload["m1_proxy_replay_authority"] = False
            payload["headline_result_authority"] = False
            payload["final_r_authority_status"] = "source_gap_no_deterministic_exit"
            payload["headline_result_authority_status"] = (
                "source_gap_no_headline_final_r_authority"
            )
            return payload
        if not ordered_tick_truth_satisfied:
            m1_proxy_authorized = (
                source == "m1"
                and allow_m1_proxy_final_r_authority
                and payload.get("status") == "replayed"
                and isinstance(payload.get("final_r"), (int, float))
                and math.isfinite(float(payload.get("final_r")))
            )
            if m1_proxy_authorized:
                proxy_final_r = round(float(payload["final_r"]), 8)
                payload["status"] = "diagnostic"
                payload["final_r"] = proxy_final_r
                payload["diagnostic_policy_gross_r"] = proxy_final_r
                payload["diagnostic_policy_close_reason"] = payload.get("close_reason")
                payload["diagnostic_policy_close_time_utc"] = payload.get(
                    "close_time_utc"
                )
                payload["m1_proxy_policy_gross_r"] = proxy_final_r
                payload["m1_proxy_policy_close_reason"] = payload.get("close_reason")
                payload["m1_proxy_policy_close_time_utc"] = payload.get("close_time_utc")
                payload["m1_proxy_profit_harvest_replay_authority"] = True
                payload["m1_proxy_profit_harvest_authority"] = True
                payload["m1_proxy_replay_authority"] = True
                payload["reason"] = (
                    "m1_ordered_path_profit_harvest_proxy_replay_authority_"
                    "not_terminal_final_r"
                )
                payload["final_r_authority"] = False
                payload["ordered_tick_final_r_authority"] = False
                payload["headline_result_authority"] = False
                payload["final_r_authority_status"] = (
                    "m1_ordered_path_proxy_replay_not_terminal_final_r_authority"
                )
                payload["m1_proxy_replay_authority_status"] = (
                    "m1_ordered_path_proxy_replay_authority_ordered_tick_proof_required"
                )
                payload["headline_result_authority_status"] = (
                    "m1_proxy_replay_diagnostic_not_headline_authority"
                )
                payload["source_boundary"] = (
                    "m1_ordered_path_profit_harvest_proxy_replay_authority_"
                    "not_terminal_headline_broker_live_or_final_selection"
                )
                return payload
            diagnostic_r = payload.pop("final_r", None)
            if isinstance(diagnostic_r, (int, float)) and math.isfinite(float(diagnostic_r)):
                payload["diagnostic_policy_gross_r"] = round(float(diagnostic_r), 8)
                if source == "m1" and payload.get("status") == "replayed":
                    payload["m1_proxy_profit_harvest_diagnostic"] = True
                    payload["reason"] = (
                        "m1_ordered_path_profit_harvest_proxy_diagnostic_not_authority"
                    )
                    payload["final_r_authority_status"] = (
                        "m1_ordered_path_proxy_final_r_diagnostic_not_authority"
                    )
            payload["diagnostic_policy_close_reason"] = payload.get("close_reason")
            payload["diagnostic_policy_close_time_utc"] = payload.get("close_time_utc")
            payload["status"] = "diagnostic"
            payload["reason"] = payload.get("reason") or (
                "unordered_path_profit_harvest_replay_not_final_r_authority"
            )
            payload["final_r_authority"] = False
            payload["ordered_tick_final_r_authority"] = False
            payload["headline_result_authority"] = False
            payload["final_r_authority_status"] = payload.get(
                "final_r_authority_status",
                "unordered_path_profit_harvest_replay_not_final_r_authority",
            )
            payload["headline_result_authority_status"] = (
                "profit_harvest_diagnostic_not_headline_authority"
            )
            payload["source_boundary"] = (
                "m1_or_unordered_path_profit_harvest_diagnostic_not_final_r_authority"
            )
            return payload
        payload["final_r_authority"] = True
        payload["ordered_tick_final_r_authority"] = True
        payload["m1_proxy_replay_authority"] = False
        payload["headline_result_authority"] = True
        payload["headline_result_authority_status"] = (
            "ordered_tick_final_r_headline_authority"
        )
        payload["final_r_authority_status"] = "ordered_tick_truth_final_r_authority"
        return payload

    def attainable_stop_ceiling(mfe_r: float) -> float:
        ceiling = mfe_r
        if target_r is not None:
            ceiling = min(ceiling, target_r)
        return ceiling

    def bounded_stop_r(stop_r: float, mfe_r: float) -> float:
        ceiling = attainable_stop_ceiling(mfe_r)
        if not math.isfinite(ceiling):
            return stop_r
        return min(stop_r, ceiling)

    armed = False
    armed_stale_deferred_until_protected = False
    stop_activation_confirmed = False
    best_mfe = float("-inf")
    active_stop_r = -1.0
    transitions: list[dict[str, Any]] = []
    for ts, high_r, low_r, close_r in observations:
        elapsed_minutes = max(0.0, (ts - fill_time).total_seconds() / 60.0)
        target_touched = target_r is not None and high_r >= target_r

        if low_r <= active_stop_r:
            if active_stop_r <= -1.0:
                return None
            if target_touched and not ordered_tick_truth_satisfied:
                return replay_exit({
                    "schema_version": "profit_harvest_mfe_capture_replay_exit_v1",
                    "status": "source_gap",
                    "reason": "unordered_m1_target_and_protective_stop_same_bar",
                    "policy": "profit_harvest_mfe_capture_v4",
                    "final_r": None,
                    "close_reason": None,
                    "close_time_utc": iso(ts),
                    "mfe_r": round(max(best_mfe, high_r), 8)
                    if math.isfinite(max(best_mfe, high_r))
                    else None,
                    "target_r": round(target_r, 8) if target_r is not None else None,
                    "active_stop_r": round(active_stop_r, 8),
                    "protect_floor_r": round(protect_floor_r, 8),
                    "base_protect_floor_r": round(base_protect_floor_r, 8),
                    "stop_activation_mfe_r": round(stop_activation_mfe_r, 8),
                    "transitions": transitions,
                    "source": source,
                    "source_boundary": (
                        "m1_intrabar_ordering_gap_no_deterministic_profit_harvest_exit"
                    ),
                })
            return replay_exit({
                "schema_version": "profit_harvest_mfe_capture_replay_exit_v1",
                "status": "replayed",
                "policy": "profit_harvest_mfe_capture_v4",
                "final_r": round(active_stop_r, 8),
                "close_reason": "profit_harvest_mfe_capture_v4_replay_protective_stop",
                "close_time_utc": iso(ts),
                "mfe_r": round(best_mfe, 8) if math.isfinite(best_mfe) else None,
                "active_stop_r": round(active_stop_r, 8),
                "protect_floor_r": round(protect_floor_r, 8),
                "base_protect_floor_r": round(base_protect_floor_r, 8),
                "stop_activation_mfe_r": round(stop_activation_mfe_r, 8),
                "cost_aware_protect_floor_enabled": cost_aware_floor_enabled,
                "expected_cost_r": round(expected_cost_r, 8),
                "cost_aware_margin_r": round(cost_aware_margin_r, 8),
                "transitions": transitions,
                "source": source,
                "source_boundary": "postdecision_ordered_path_replay_label_not_broker_ticket_truth",
            })

        if target_touched:
            return None

        if stop_activation_confirmed and math.isfinite(best_mfe):
            giveback_exit_r = best_mfe - close_on_giveback_r
            if low_r <= giveback_exit_r:
                return replay_exit({
                    "schema_version": "profit_harvest_mfe_capture_replay_exit_v1",
                    "status": "replayed",
                    "policy": "profit_harvest_mfe_capture_v4",
                    "final_r": round(max(active_stop_r, giveback_exit_r), 8),
                    "close_reason": "profit_harvest_mfe_capture_v4_replay_giveback_close",
                    "close_time_utc": iso(ts),
                    "mfe_r": round(best_mfe, 8),
                    "giveback_close_r": close_on_giveback_r,
                    "active_stop_r": round(active_stop_r, 8),
                    "protect_floor_r": round(protect_floor_r, 8),
                    "base_protect_floor_r": round(base_protect_floor_r, 8),
                    "stop_activation_mfe_r": round(stop_activation_mfe_r, 8),
                    "cost_aware_protect_floor_enabled": cost_aware_floor_enabled,
                    "expected_cost_r": round(expected_cost_r, 8),
                    "cost_aware_margin_r": round(cost_aware_margin_r, 8),
                    "transitions": transitions,
                    "source": source,
                    "source_boundary": "postdecision_ordered_path_replay_label_not_broker_ticket_truth",
                })
            if (
                stale_minutes is not None
                and elapsed_minutes >= stale_minutes
                and best_mfe >= stale_min_mfe_r
                and close_r <= stale_close_below_r
            ):
                return replay_exit({
                    "schema_version": "profit_harvest_mfe_capture_replay_exit_v1",
                    "status": "replayed",
                    "policy": "profit_harvest_mfe_capture_v4",
                    "final_r": round(max(active_stop_r, close_r), 8),
                    "close_reason": "profit_harvest_mfe_capture_v4_replay_stale_close",
                    "close_time_utc": iso(ts),
                    "mfe_r": round(best_mfe, 8),
                    "close_r": round(close_r, 8),
                    "active_stop_r": round(active_stop_r, 8),
                    "protect_floor_r": round(protect_floor_r, 8),
                    "base_protect_floor_r": round(base_protect_floor_r, 8),
                    "stop_activation_mfe_r": round(stop_activation_mfe_r, 8),
                    "cost_aware_protect_floor_enabled": cost_aware_floor_enabled,
                    "expected_cost_r": round(expected_cost_r, 8),
                    "cost_aware_margin_r": round(cost_aware_margin_r, 8),
                    "transitions": transitions,
                    "source": source,
                    "source_boundary": "postdecision_ordered_path_replay_label_not_broker_ticket_truth",
                })

        previous_best = best_mfe
        best_mfe = max(best_mfe, high_r)
        if best_mfe >= min_mfe_r and not armed:
            armed = True
            transitions.append(
                {
                    "event": "profit_harvest_mfe_capture_v4_armed",
                    "time_utc": iso(ts),
                    "mfe_r": round(best_mfe, 8),
                    "min_mfe_r": min_mfe_r,
                }
            )
        if (
            armed_stale_close_enabled
            and armed
            and armed_stale_minutes is not None
            and elapsed_minutes >= armed_stale_minutes
            and best_mfe >= armed_stale_min_mfe_r
            and close_r <= armed_stale_close_below_r
        ):
            if active_stop_r < protect_floor_r - 1e-12:
                if not armed_stale_deferred_until_protected:
                    armed_stale_deferred_until_protected = True
                    transitions.append(
                        {
                            "event": (
                                "profit_harvest_mfe_capture_v4_armed_stale_"
                                "close_deferred_until_protective_floor"
                            ),
                            "time_utc": iso(ts),
                            "mfe_r": round(best_mfe, 8),
                            "close_r": round(close_r, 8),
                            "active_stop_r": round(active_stop_r, 8),
                            "protect_floor_r": round(protect_floor_r, 8),
                            "armed_stale_minutes": armed_stale_minutes,
                            "reason": "armed_stale_close_illegal_while_naked",
                        }
                    )
                continue
            return replay_exit({
                "schema_version": "profit_harvest_mfe_capture_replay_exit_v1",
                "status": "replayed",
                "policy": "profit_harvest_mfe_capture_v4",
                "final_r": round(close_r, 8),
                "close_reason": "profit_harvest_mfe_capture_v4_replay_armed_stale_close",
                "close_time_utc": iso(ts),
                "mfe_r": round(best_mfe, 8),
                "close_r": round(close_r, 8),
                "active_stop_r": round(active_stop_r, 8),
                "protect_floor_r": round(protect_floor_r, 8),
                "base_protect_floor_r": round(base_protect_floor_r, 8),
                "stop_activation_mfe_r": round(stop_activation_mfe_r, 8),
                "target_activation_fraction": round(target_activation_fraction, 8),
                "armed_stale_minutes": armed_stale_minutes,
                "armed_stale_min_mfe_r": round(armed_stale_min_mfe_r, 8),
                "armed_stale_close_below_r": round(armed_stale_close_below_r, 8),
                "cost_aware_protect_floor_enabled": cost_aware_floor_enabled,
                "expected_cost_r": round(expected_cost_r, 8),
                "cost_aware_margin_r": round(cost_aware_margin_r, 8),
                "transitions": transitions,
                "source": source,
                "source_boundary": "postdecision_ordered_path_replay_label_not_broker_ticket_truth",
            })
        if armed and not stop_activation_confirmed and best_mfe >= stop_activation_mfe_r:
            stop_activation_confirmed = True
            transitions.append(
                {
                    "event": "profit_harvest_mfe_capture_v4_stop_activation_confirmed",
                    "time_utc": iso(ts),
                    "mfe_r": round(best_mfe, 8),
                    "stop_activation_mfe_r": round(stop_activation_mfe_r, 8),
                }
            )
        if stop_activation_confirmed and best_mfe > previous_best:
            if elapsed_minutes < min_hold_minutes_before_stop_raise:
                transitions.append(
                    {
                        "event": "profit_harvest_mfe_capture_v4_stop_raise_deferred_min_hold",
                        "time_utc": iso(ts),
                        "mfe_r": round(best_mfe, 8),
                        "elapsed_minutes": round(elapsed_minutes, 8),
                        "min_hold_minutes_before_stop_raise": round(
                            min_hold_minutes_before_stop_raise,
                            8,
                        ),
                    }
                )
                continue
            desired_stop_r = (
                max(protect_floor_r, best_mfe - trail_gap_r)
                if best_mfe >= trail_activation_mfe_r
                else protect_floor_r
            )
            unbounded_desired_stop_r = desired_stop_r
            desired_stop_r = bounded_stop_r(desired_stop_r, best_mfe)
            if desired_stop_r > active_stop_r + 1e-12:
                active_stop_r = desired_stop_r
                transitions.append(
                    {
                        "event": "profit_harvest_mfe_capture_v4_stop_raised",
                        "time_utc": iso(ts),
                        "mfe_r": round(best_mfe, 8),
                        "active_stop_r": round(active_stop_r, 8),
                        "unbounded_desired_stop_r": round(unbounded_desired_stop_r, 8),
                        "attainable_stop_ceiling_r": round(
                            attainable_stop_ceiling(best_mfe),
                            8,
                        ),
                        "stop_clamped_to_attainable_path": bool(
                            unbounded_desired_stop_r > desired_stop_r + 1e-12
                        ),
                        "trail_gap_r": trail_gap_r,
                        "protect_floor_r": protect_floor_r,
                        "base_protect_floor_r": base_protect_floor_r,
                        "stop_activation_mfe_r": round(stop_activation_mfe_r, 8),
                        "trail_activation_mfe_r": round(trail_activation_mfe_r, 8),
                        "target_activation_fraction": round(
                            target_activation_fraction,
                            8,
                        ),
                        "trail_escalation_active": (
                            best_mfe >= trail_activation_mfe_r
                        ),
                        "cost_aware_protect_floor_enabled": cost_aware_floor_enabled,
                        "expected_cost_r": round(expected_cost_r, 8),
                        "cost_aware_margin_r": round(cost_aware_margin_r, 8),
                    }
                )
    return None


def apply_profit_harvest_replay_exit(
    *,
    oracle: dict[str, Any],
    rows: Iterable[Mapping[str, Any]],
    candidate: Mapping[str, Any],
    config: Mapping[str, Any],
    packets: Mapping[str, Any] | None,
    final_r: float | None,
    close_reason: str,
    target_r: float | None,
    selected_policy_replay_exit: Mapping[str, Any] | None = None,
) -> tuple[float | None, str, float | None, dict[str, Any] | None]:
    runtime = _profit_harvest_runtime_config(config)
    selected_policy_replay_exit = (
        selected_policy_replay_exit
        if isinstance(selected_policy_replay_exit, Mapping)
        else {}
    )
    selected_policy_name = str(
        first_present(
            selected_policy_replay_exit.get("selected_policy"),
            candidate.get("dynamic_geometry_policy"),
            candidate.get("gtos_vnext_selected_cell_risk_selected_policy"),
        )
        or ""
    ).strip().lower()
    composition_mode = str(
        runtime.get("profit_harvest_mfe_capture_v4_composition_mode")
        or "sequential_overlay"
    ).strip().lower()
    configured_selected_only_policies = runtime.get(
        "profit_harvest_mfe_capture_v4_selected_policy_only_policy_names"
    )
    if isinstance(configured_selected_only_policies, str):
        configured_selected_only_policies = [configured_selected_only_policies]
    selected_only_policy_names = {
        str(item or "").strip().lower()
        for item in (configured_selected_only_policies or ["momentum_exhaustion"])
        if str(item or "").strip()
    }
    selected_policy_terminal_authority = bool(
        selected_policy_replay_exit.get("final_r_authority") is True
        and isinstance(selected_policy_replay_exit.get("final_r"), (int, float))
        and math.isfinite(float(selected_policy_replay_exit.get("final_r")))
    )
    selected_policy_only_applies = bool(
        composition_mode == "selected_policy_only"
        and selected_policy_name in selected_only_policy_names
        and selected_policy_terminal_authority
    )
    raw_fixed_target_r = selected_policy_replay_exit.get(
        "raw_fixed_target_final_r"
    )
    composition_fields = {
        "profit_harvest_composition_mode": composition_mode,
        "profit_harvest_composition_selected_policy": selected_policy_name or None,
        "profit_harvest_composition_selected_policy_terminal_authority": (
            selected_policy_terminal_authority
        ),
        "profit_harvest_composition_selected_policy_only_applies": (
            selected_policy_only_applies
        ),
        "exit_composition_raw_fixed_target_gross_r": raw_fixed_target_r,
        "exit_composition_selected_policy_gross_r": final_r,
        "exit_composition_selected_policy_close_reason": close_reason,
    }
    oracle.update(composition_fields)
    replay_exit = profit_harvest_mfe_capture_replay_exit(
        oracle=oracle,
        rows=rows,
        candidate=candidate,
        config=config,
        packets=packets,
        selected_policy_replay_exit=selected_policy_replay_exit,
    )
    if replay_exit is None:
        oracle.update(
            {
                "profit_harvest_composition_status": (
                    "selected_policy_terminal_preserved_no_harvest_counterfactual"
                    if selected_policy_only_applies
                    else "no_profit_harvest_exit"
                ),
                "profit_harvest_applied_to_terminal": False,
                "exit_composition_profit_harvest_counterfactual_gross_r": None,
                "exit_composition_terminal_gross_r": final_r,
            }
        )
        return final_r, close_reason, target_r, None
    if replay_exit.get("status") == "source_gap":
        replay_exit["final_r_authority"] = False
        replay_exit["ordered_tick_final_r_authority"] = False
        replay_exit["m1_proxy_replay_authority"] = False
        replay_exit["headline_result_authority"] = False
        replay_exit["final_r_authority_status"] = "source_gap_no_deterministic_exit"
        replay_exit["headline_result_authority_status"] = (
            "source_gap_no_headline_final_r_authority"
        )
        oracle["profit_harvest_mfe_capture_replay_exit_source_gap"] = replay_exit
        oracle["profit_harvest_mfe_capture_replay_exit_source_gap_status"] = str(
            replay_exit.get("reason") or "source_gap"
        )
        oracle["profit_harvest_mfe_capture_replay_exit_final_r_authority"] = False
        oracle["profit_harvest_mfe_capture_replay_exit_final_r_authority_status"] = (
            replay_exit["final_r_authority_status"]
        )
        oracle["profit_harvest_mfe_capture_replay_exit_ordered_tick_final_r_authority"] = False
        oracle["profit_harvest_mfe_capture_replay_exit_m1_proxy_replay_authority"] = False
        oracle["profit_harvest_mfe_capture_replay_exit_headline_result_authority"] = False
        oracle[
            "profit_harvest_mfe_capture_replay_exit_headline_result_authority_status"
        ] = replay_exit["headline_result_authority_status"]
        oracle["profit_harvest_target_after_exit_status"] = "source_gap"
        oracle.update(
            {
                "profit_harvest_composition_status": (
                    "selected_policy_terminal_preserved_harvest_source_gap"
                    if selected_policy_only_applies
                    else "profit_harvest_source_gap_no_terminal_override"
                ),
                "profit_harvest_applied_to_terminal": False,
                "exit_composition_profit_harvest_counterfactual_gross_r": None,
                "exit_composition_terminal_gross_r": final_r,
            }
        )
        return final_r, close_reason, target_r, None
    replay_final_r = replay_exit.get("final_r")
    if selected_policy_only_applies:
        diagnostic = dict(replay_exit)
        counterfactual_final_r = (
            round(float(replay_final_r), 8)
            if isinstance(replay_final_r, (int, float))
            and math.isfinite(float(replay_final_r))
            else None
        )
        diagnostic.update(
            {
                "counterfactual_final_r": counterfactual_final_r,
                "counterfactual_close_reason": diagnostic.get("close_reason"),
                "counterfactual_final_r_authority": diagnostic.get(
                    "final_r_authority"
                ),
                "counterfactual_final_r_authority_status": diagnostic.get(
                    "final_r_authority_status"
                ),
                "composition_mode": composition_mode,
                "composition_status": "selected_policy_terminal_authority_preserved",
                "composition_applied_to_terminal": False,
                "status": "diagnostic",
                "final_r_authority": False,
                "ordered_tick_final_r_authority": False,
                "m1_proxy_replay_authority": False,
                "headline_result_authority": False,
                "headline_result_authority_status": (
                    "selected_policy_only_harvest_counterfactual_not_headline"
                ),
                "final_r_authority_status": (
                    "selected_policy_only_harvest_counterfactual_not_terminal_authority"
                ),
                "source_boundary": (
                    "postdecision_profit_harvest_counterfactual_selected_policy_"
                    "terminal_authority_preserved"
                ),
            }
        )
        oracle.update(
            {
                "profit_harvest_mfe_capture_replay_exit_diagnostic": diagnostic,
                "profit_harvest_mfe_capture_replay_exit_diagnostic_only": True,
                "profit_harvest_mfe_capture_replay_bound": False,
                "profit_harvest_mfe_capture_replay_exit_final_r_authority": False,
                "profit_harvest_mfe_capture_replay_exit_final_r_authority_status": (
                    diagnostic["final_r_authority_status"]
                ),
                "profit_harvest_mfe_capture_replay_exit_ordered_tick_final_r_authority": False,
                "profit_harvest_mfe_capture_replay_exit_m1_proxy_replay_authority": False,
                "profit_harvest_mfe_capture_replay_exit_headline_result_authority": False,
                "profit_harvest_mfe_capture_replay_exit_headline_result_authority_status": (
                    diagnostic["headline_result_authority_status"]
                ),
                "profit_harvest_composition_status": (
                    "selected_policy_terminal_authority_preserved"
                ),
                "profit_harvest_applied_to_terminal": False,
                "exit_composition_profit_harvest_counterfactual_gross_r": (
                    counterfactual_final_r
                ),
                "exit_composition_profit_harvest_counterfactual_close_reason": (
                    diagnostic.get("counterfactual_close_reason")
                ),
                "exit_composition_profit_harvest_delta_vs_selected_policy_r": (
                    round(counterfactual_final_r - float(final_r), 8)
                    if counterfactual_final_r is not None
                    and isinstance(final_r, (int, float))
                    and math.isfinite(float(final_r))
                    else None
                ),
                "exit_composition_terminal_gross_r": final_r,
            }
        )
        return final_r, close_reason, target_r, None
    target_time = parse_utc(oracle.get("target_first_touch_utc"))
    close_time = parse_utc(replay_exit.get("close_time_utc"))
    target_after_exit = (
        target_time is not None
        and close_time is not None
        and target_time > close_time
        and isinstance(target_r, (int, float))
        and math.isfinite(float(target_r))
    )
    m1_proxy_replay_authority = bool(
        replay_exit.get("m1_proxy_replay_authority") is True
        or replay_exit.get("m1_proxy_profit_harvest_replay_authority") is True
        or replay_exit.get("m1_proxy_profit_harvest_authority") is True
        or replay_exit.get("final_r_authority_status")
        == "m1_ordered_path_proxy_final_r_authority_not_live"
    )
    m1_proxy_headline_requested = bool(
        m1_proxy_replay_authority
        and _runtime_bool(
            runtime.get("profit_harvest_mfe_capture_v4_allow_m1_proxy_final_r_authority"),
            False,
        )
    )
    m1_proxy_replay_headline_allowed = False
    if m1_proxy_headline_requested:
        replay_exit["m1_proxy_requested_headline_authority_blocked"] = True
        replay_exit["m1_proxy_requested_headline_authority_block_reason"] = (
            "m1_proxy_profit_harvest_requires_ordered_tick_truth_for_terminal_final_r"
        )
    if (
        m1_proxy_replay_authority
        or
        replay_exit.get("final_r_authority") is not True
    ):
        replay_exit["final_r_authority"] = False
        replay_exit["ordered_tick_final_r_authority"] = False
        replay_exit["headline_result_authority"] = False
        final_r_authority_status = str(
            replay_exit.get("final_r_authority_status")
            or (
                "m1_ordered_path_proxy_replay_not_terminal_final_r_authority"
                if m1_proxy_replay_authority
                else "unordered_path_profit_harvest_replay_not_final_r_authority"
            )
        )
        if (
            m1_proxy_replay_authority
            and final_r_authority_status
            == "m1_ordered_path_proxy_final_r_authority_not_live"
        ):
            final_r_authority_status = (
                "m1_ordered_path_proxy_replay_not_terminal_final_r_authority"
            )
        if m1_proxy_replay_authority:
            replay_exit["status"] = "diagnostic"
            replay_exit["m1_proxy_replay_authority"] = True
            replay_exit.setdefault(
                "m1_proxy_replay_authority_status",
                "m1_ordered_path_proxy_replay_authority_ordered_tick_proof_required",
            )
            replay_exit["headline_result_authority_status"] = (
                "m1_proxy_replay_diagnostic_not_headline_authority"
            )
            if isinstance(replay_final_r, (int, float)) and math.isfinite(
                float(replay_final_r)
            ):
                proxy_final_r = round(float(replay_final_r), 8)
                replay_exit.setdefault("diagnostic_policy_gross_r", proxy_final_r)
                replay_exit.setdefault("m1_proxy_policy_gross_r", proxy_final_r)
                replay_exit.setdefault(
                    "diagnostic_policy_close_reason",
                    replay_exit.get("close_reason"),
                )
                replay_exit.setdefault(
                    "diagnostic_policy_close_time_utc",
                    replay_exit.get("close_time_utc"),
                )
        else:
            replay_exit["status"] = "diagnostic"
            replay_exit["m1_proxy_replay_authority"] = False
            replay_exit["headline_result_authority_status"] = (
                "profit_harvest_diagnostic_not_headline_authority"
            )
        if m1_proxy_replay_authority and target_after_exit:
            final_r_authority_status = (
                "m1_ordered_path_proxy_target_after_exit_diagnostic_not_authority"
            )
            replay_exit["reason"] = (
                "m1_ordered_path_profit_harvest_proxy_target_after_exit_"
                "diagnostic_not_authority"
            )
            replay_exit["target_after_exit"] = True
            replay_exit["target_after_exit_status"] = "diagnostic_not_final_r_authority"
            replay_exit["target_after_exit_time_utc"] = iso(target_time)
        replay_exit["final_r_authority_status"] = final_r_authority_status
        oracle["profit_harvest_mfe_capture_replay_exit_diagnostic"] = replay_exit
        oracle["profit_harvest_mfe_capture_replay_exit_diagnostic_only"] = True
        oracle["profit_harvest_mfe_capture_replay_bound"] = False
        oracle["profit_harvest_mfe_capture_replay_exit_source_gap"] = replay_exit
        oracle["profit_harvest_mfe_capture_replay_exit_source_gap_status"] = (
            final_r_authority_status
        )
        oracle["profit_harvest_mfe_capture_replay_exit_final_r_authority"] = False
        oracle["profit_harvest_mfe_capture_replay_exit_final_r_authority_status"] = (
            final_r_authority_status
        )
        oracle["profit_harvest_mfe_capture_replay_exit_ordered_tick_final_r_authority"] = False
        oracle["profit_harvest_mfe_capture_replay_exit_m1_proxy_replay_authority"] = (
            m1_proxy_replay_authority
        )
        oracle["profit_harvest_mfe_capture_replay_exit_headline_result_authority"] = False
        oracle[
            "profit_harvest_mfe_capture_replay_exit_headline_result_authority_status"
        ] = replay_exit["headline_result_authority_status"]
        oracle["profit_harvest_target_after_exit_status"] = (
            "diagnostic_not_final_r_authority"
            if target_after_exit
            else "not_applicable"
        )
        if m1_proxy_replay_authority and target_after_exit:
            oracle["profit_harvest_target_after_exit"] = True
            oracle["profit_harvest_target_after_exit_time_utc"] = iso(target_time)
        return final_r, close_reason, target_r, None
    if not isinstance(replay_final_r, (int, float)) or not math.isfinite(float(replay_final_r)):
        return final_r, close_reason, target_r, None
    if m1_proxy_replay_headline_allowed:
        replay_exit["status"] = "replayed_proxy"
        replay_exit["final_r_authority"] = True
        replay_exit["ordered_tick_final_r_authority"] = False
        replay_exit["m1_proxy_replay_authority"] = True
        replay_exit["m1_proxy_profit_harvest_replay_authority"] = True
        replay_exit["headline_result_authority"] = True
        replay_exit["headline_result_authority_status"] = (
            "m1_proxy_replay_headline_authority_local_replay_only"
        )
        replay_exit["final_r_authority_status"] = (
            "m1_ordered_path_proxy_final_r_authority_replay_only"
        )
        replay_exit["m1_proxy_replay_authority_status"] = (
            "m1_ordered_path_proxy_replay_authority_local_replay_only_"
            "ordered_tick_or_broker_proof_still_required_for_live_final"
        )
        replay_exit["source_boundary"] = (
            "owner_approved_m1_ordered_path_proxy_replay_headline_authority_"
            "local_replay_only_no_broker_live_or_final_selection"
        )
    else:
        replay_exit["final_r_authority"] = True
        replay_exit["ordered_tick_final_r_authority"] = True
        replay_exit["m1_proxy_replay_authority"] = False
        replay_exit["headline_result_authority"] = True
        replay_exit["headline_result_authority_status"] = (
            "ordered_tick_final_r_headline_authority"
        )
        replay_exit["final_r_authority_status"] = (
            replay_exit.get("final_r_authority_status")
            or "ordered_tick_truth_final_r_authority"
        )
    oracle["profit_harvest_mfe_capture_replay_exit"] = replay_exit
    oracle["profit_harvest_mfe_capture_replay_bound"] = True
    oracle["profit_harvest_mfe_capture_replay_exit_final_r_authority"] = True
    oracle["profit_harvest_mfe_capture_replay_exit_final_r_authority_status"] = (
        replay_exit["final_r_authority_status"]
    )
    oracle["profit_harvest_mfe_capture_replay_exit_ordered_tick_final_r_authority"] = (
        replay_exit.get("ordered_tick_final_r_authority") is True
    )
    oracle["profit_harvest_mfe_capture_replay_exit_m1_proxy_replay_authority"] = (
        replay_exit.get("m1_proxy_replay_authority") is True
    )
    oracle["profit_harvest_mfe_capture_replay_exit_headline_result_authority"] = True
    oracle[
        "profit_harvest_mfe_capture_replay_exit_headline_result_authority_status"
    ] = replay_exit["headline_result_authority_status"]
    oracle.update(
        {
            "profit_harvest_composition_status": "sequential_harvest_overlay_applied",
            "profit_harvest_applied_to_terminal": True,
            "exit_composition_profit_harvest_counterfactual_gross_r": replay_final_r,
            "exit_composition_profit_harvest_counterfactual_close_reason": (
                replay_exit.get("close_reason")
            ),
            "exit_composition_profit_harvest_delta_vs_selected_policy_r": (
                round(float(replay_final_r) - float(final_r), 8)
                if isinstance(final_r, (int, float))
                and math.isfinite(float(final_r))
                else None
            ),
            "exit_composition_terminal_gross_r": replay_final_r,
        }
    )
    oracle["terminal_outcome_before_profit_harvest_replay"] = oracle.get("terminal_outcome")
    oracle["close_reason_before_profit_harvest_replay"] = close_reason
    oracle.setdefault(
        "profit_harvest_original_close_mark_time_utc",
        oracle.get("close_mark_time_utc"),
    )
    oracle.setdefault(
        "profit_harvest_original_close_time_utc",
        oracle.get("close_time_utc"),
    )
    oracle.setdefault(
        "profit_harvest_original_exit_time_utc",
        oracle.get("exit_time_utc"),
    )
    oracle.setdefault(
        "profit_harvest_original_close_mark_source",
        oracle.get("close_mark_source"),
    )
    oracle.setdefault(
        "profit_harvest_original_close_mark_r",
        oracle.get("close_mark_r"),
    )
    replay_close_time_utc = replay_exit.get("close_time_utc")
    oracle["profit_harvest_policy_terminal_outcome"] = replay_exit["close_reason"]
    oracle["terminal_outcome"] = replay_exit["close_reason"]
    oracle["terminal_outcome_authority"] = "profit_harvest_mfe_capture_replay_exit"
    oracle["profit_harvest_policy_close_mark_time_utc"] = replay_close_time_utc
    oracle["profit_harvest_policy_close_time_utc"] = replay_close_time_utc
    oracle["profit_harvest_policy_exit_time_utc"] = replay_close_time_utc
    oracle["profit_harvest_policy_close_mark_source"] = replay_exit["close_reason"]
    oracle["profit_harvest_policy_close_mark_r"] = replay_final_r
    expected_cost_r = safe_float(replay_exit.get("expected_cost_r"), 0.0)
    replay_net_r = round(float(replay_final_r) - expected_cost_r, 8)
    replay_exit["replay_net_r"] = replay_net_r
    oracle["profit_harvest_replay_net_r"] = replay_net_r
    if isinstance(final_r, (int, float)) and math.isfinite(float(final_r)):
        original_net_r = round(float(final_r) - expected_cost_r, 8)
        replay_exit.update(
            {
                "original_final_r": round(float(final_r), 8),
                "original_net_r": original_net_r,
                "original_close_reason": close_reason,
                "lost_original_exit_gross_r": max(
                    0.0,
                    round(float(final_r) - float(replay_final_r), 8),
                ),
                "lost_original_exit_net_r": max(
                    0.0,
                    round(original_net_r - replay_net_r, 8),
                ),
            }
        )
        oracle.update(
            {
                "profit_harvest_original_final_r": round(float(final_r), 8),
                "profit_harvest_original_net_r": original_net_r,
                "profit_harvest_original_close_reason": close_reason,
                "profit_harvest_lost_original_exit_gross_r": replay_exit[
                    "lost_original_exit_gross_r"
                ],
                "profit_harvest_lost_original_exit_net_r": replay_exit[
                    "lost_original_exit_net_r"
                ],
            }
        )
    if target_after_exit:
        target_r_value = float(target_r)
        lost_target_gross_r = round(target_r_value - float(replay_final_r), 8)
        target_net_r = round(target_r_value - expected_cost_r, 8)
        target_after_exit_status = "true" if lost_target_gross_r > 0.0 else "false"
        oracle.update(
            {
                "profit_harvest_target_after_exit": lost_target_gross_r > 0.0,
                "profit_harvest_target_after_exit_status": target_after_exit_status,
                "profit_harvest_target_after_exit_time_utc": iso(target_time),
                "profit_harvest_original_target_r": round(target_r_value, 8),
                "profit_harvest_target_net_r_if_held": target_net_r,
                "profit_harvest_replay_net_r": replay_net_r,
                "profit_harvest_lost_target_gross_r": max(0.0, lost_target_gross_r),
                "profit_harvest_lost_target_net_r": max(
                    0.0,
                    round(target_net_r - replay_net_r, 8),
                ),
            }
        )
        replay_exit.update(
            {
                "target_after_exit": lost_target_gross_r > 0.0,
                "target_after_exit_status": target_after_exit_status,
                "target_after_exit_time_utc": iso(target_time),
                "original_target_r": round(target_r_value, 8),
                "target_net_r_if_held": target_net_r,
                "replay_net_r": replay_net_r,
                "lost_target_gross_r": max(0.0, lost_target_gross_r),
                "lost_target_net_r": max(0.0, round(target_net_r - replay_net_r, 8)),
            }
        )
    else:
        target_after_exit_status = (
            "false"
            if target_time is not None
            and close_time is not None
            and target_time <= close_time
            else "not_applicable"
        )
        oracle.update(
            {
                "profit_harvest_target_after_exit": False,
                "profit_harvest_target_after_exit_status": target_after_exit_status,
                "profit_harvest_lost_target_gross_r": 0.0,
                "profit_harvest_lost_target_net_r": 0.0,
            }
        )
        replay_exit["target_after_exit"] = False
        replay_exit["target_after_exit_status"] = target_after_exit_status
    return (
        round(float(replay_final_r), 8),
        str(replay_exit["close_reason"]),
        target_r,
        replay_exit,
    )


