def order_event_terminal_policy_diagnostic_fields(
    oracle: Mapping[str, Any],
) -> dict[str, Any]:
    """Keep terminal R authority off accepted-order events."""

    fields = profit_harvest_policy_ledger_fields(oracle)
    if fields.get("profit_harvest_mfe_capture_replay_exit_final_r_authority") is True:
        fields["profit_harvest_mfe_capture_replay_exit_final_r_authority"] = False
        fields["profit_harvest_mfe_capture_replay_exit_final_r_authority_status"] = (
            "order_event_no_terminal_r_authority_trade_or_exit_row_only"
        )
        fields["profit_harvest_mfe_capture_replay_exit_headline_result_authority"] = (
            False
        )
        fields[
            "profit_harvest_mfe_capture_replay_exit_headline_result_authority_status"
        ] = "order_event_no_terminal_r_authority_trade_or_exit_row_only"
        fields["profit_harvest_mfe_capture_replay_exit_order_event_diagnostic"] = (
            oracle.get("profit_harvest_mfe_capture_replay_exit")
        )
    if (
        fields.get("terminal_r_replay_authority") is True
        or fields.get("terminal_r_proxy_replay_authority") is True
        or fields.get("terminal_r_ordered_tick_final_live_authority") is True
    ):
        fields["terminal_r_replay_authority"] = False
        fields["terminal_r_proxy_replay_authority"] = False
        fields["terminal_r_ordered_tick_final_live_authority"] = False
        fields["ordered_tick_final_r_authority"] = False
        fields["m1_proxy_replay_authority"] = False
        fields["headline_result_authority"] = False
        fields["final_r_authority"] = False
        fields["headline_result_authority_status"] = (
            "order_event_no_terminal_r_authority_trade_or_exit_row_only"
        )
        fields["terminal_r_authority_status"] = (
            "order_event_no_terminal_r_authority_trade_or_exit_row_only"
        )
    return fields


def build_trade_params(
    *,
    candidate: Mapping[str, Any],
    selector_packet: Mapping[str, Any],
    scheduler_packet: Mapping[str, Any],
    lifecycle_packet: Mapping[str, Any],
    geometry_contract: Mapping[str, Any],
    risk_pct: float,
    source_hash: str,
    source_path: str,
    cost_r: float,
    risk_authority: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    risk_authority = risk_authority if isinstance(risk_authority, Mapping) else {}
    selector_packet = selector_packet if isinstance(selector_packet, Mapping) else {}
    prop = risk_authority.get("prop_firm_headroom")
    prop = prop if isinstance(prop, Mapping) else {}
    decision_time_utc = (
        candidate.get("decision_time_utc")
        or candidate.get("asof_utc")
        or candidate.get("candle_close_utc")
    )
    selected_policy = str(
        geometry_contract.get("selected_policy")
        or candidate.get("dynamic_geometry_policy")
        or candidate.get("gtos_vnext_selected_cell_risk_selected_policy")
        or "momentum_exhaustion"
    )
    execution_policy_id = (
        geometry_contract.get("execution_policy_id")
        or candidate.get("dynamic_execution_policy_id")
        or f"timewarp_{selected_policy}_v4_research"
    )
    original_selector_action = selector_packet.get("action")
    original_selector_reason = first_present(
        selector_packet.get("reason"),
        selector_packet.get("final_reason"),
    )
    effective_selector_reason = first_present(
        risk_authority.get("package_new_entry_authority_selector_reason"),
        risk_authority.get("selector_reason"),
        effective_selector_reason_for_authority(
            candidate,
            risk_authority,
            selector_packet,
        ),
        candidate.get("scheduler_materialization_selector_reason"),
        candidate.get("selector_reason"),
        original_selector_reason,
    )
    effective_selector_action = normalize_selector_action_for_reason(
        first_present(
            risk_authority.get("package_new_entry_authority_selector_action"),
            risk_authority.get("selector_action_origin"),
            candidate.get("scheduler_materialization_selector_action"),
            candidate.get("selector_action"),
            risk_authority.get("risk_decision"),
            original_selector_action,
        ),
        effective_selector_reason,
    )
    if not effective_selector_action:
        effective_selector_action = original_selector_action
    execution_selector_packet = dict(selector_packet)
    if effective_selector_action not in (None, ""):
        execution_selector_packet["action"] = effective_selector_action
    if effective_selector_reason not in (None, ""):
        execution_selector_packet["reason"] = effective_selector_reason
    if original_selector_action not in (None, ""):
        execution_selector_packet["original_action"] = original_selector_action
    if original_selector_reason not in (None, ""):
        execution_selector_packet["original_reason"] = original_selector_reason
    return {
        "trade_id": candidate.get("candidate_id"),
        "candidate_id": candidate.get("candidate_id"),
        "gtos_vnext_candidate_id": candidate.get("candidate_id"),
        "decision_time_utc": decision_time_utc,
        "asof_utc": decision_time_utc,
        "symbol": candidate.get("symbol"),
        "direction": candidate.get("side"),
        "entry_price": candidate.get("entry_price"),
        "stop_loss": candidate.get("stop_loss"),
        "take_profit_1": candidate.get("take_profit_1"),
        "risk_reward_ratio": candidate.get("risk_reward_ratio"),
        "source_file": source_path,
        "source_path": source_path,
        "source_hash": source_hash,
        "gtos_vnext_source_hash": source_hash,
        "gtos_vnext_source_event_hash": stable_sha256(
            compact_payload(candidate)
        ),
        "gtos_vnext_source_event_details": {
            "candidate_id": candidate.get("candidate_id"),
            "asof_utc": candidate.get("candle_close_utc"),
            "evidence_class": SOURCE_BOUND_EVIDENCE_CLASS,
        },
        "gtos_vnext_selector_row_id": candidate.get("candidate_id"),
        "gtos_vnext_selector_proof_hash": selector_packet.get("packet_hash_sha256"),
        "gtos_vnext_dynamic_policy_selected": selected_policy,
        "gtos_vnext_dynamic_policy_applied": True,
        "gtos_vnext_execution_policy_id": execution_policy_id,
        "gtos_vnext_dynamic_be_trigger_r": 1.0,
        "gtos_vnext_dynamic_final_target_r": candidate.get("risk_reward_ratio"),
        "gtos_vnext_selected_cell_risk_cell_id": f"timewarp:{candidate.get('candidate_id')}",
        "gtos_vnext_selected_cell_risk_pct": risk_pct,
        "gtos_vnext_selected_cell_risk_selected_policy": selected_policy,
        "gtos_vnext_selected_cell_risk_policy_identity_status": "source_bound_research",
        "gtos_vnext_timewarp_runtime_risk_authority_v4": dict(risk_authority),
        "gtos_vnext_live_as_if_replay_no_broker_authority": True,
        "gtos_vnext_replay_broker_mutation_enabled": False,
        "gtos_vnext_replay_source_boundary": (
            "local_live_as_if_replay_selected_path_no_broker_order_authority"
        ),
        "gtos_vnext_prop_firm_headroom_snapshot_v4": prop.get("simulated_headroom"),
        "gtos_vnext_prop_firm_headroom_evaluation_v4": prop.get(
            "prop_firm_headroom_v4_evaluation"
        ),
        "gtos_vnext_selector_v4_packet": execution_selector_packet,
        "gtos_vnext_selector_v4_action": effective_selector_action,
        "gtos_vnext_selector_v4_reason": effective_selector_reason,
        "gtos_vnext_selector_v4_original_action": original_selector_action,
        "gtos_vnext_selector_v4_original_reason": original_selector_reason,
        "gtos_vnext_selector_v4_action_reconciled_from_package_authority": bool(
            effective_selector_action not in (None, "")
            and original_selector_action not in (None, "")
            and str(effective_selector_action) != str(original_selector_action)
        ),
        "gtos_vnext_selector_v4_reconciled_action_source": (
            "runtime_risk_package_authority"
            if effective_selector_action not in (None, "")
            and original_selector_action not in (None, "")
            and str(effective_selector_action) != str(original_selector_action)
            else "selector_packet"
        ),
        "gtos_vnext_selector_v4_packet_hash": selector_packet.get("packet_hash_sha256"),
        "gtos_vnext_scheduler_v4_packet": scheduler_packet,
        "gtos_vnext_scheduler_v4_action": (
            scheduler_packet.get("decision", {}).get("selected_action_class")
            if isinstance(scheduler_packet.get("decision"), Mapping)
            else None
        ),
        "gtos_vnext_scheduler_v4_packet_hash": stable_sha256(
            compact_payload(scheduler_packet)
        ),
        "gtos_vnext_same_symbol_lifecycle_v4_packet": lifecycle_packet,
        "gtos_vnext_same_symbol_lifecycle_action": lifecycle_packet.get("action"),
        "gtos_vnext_dynamic_target_stop_geometry_v4": geometry_contract,
        "gtos_vnext_target_stop_geometry_v4": geometry_contract,
        "gtos_vnext_dynamic_target_stop_geometry_v4_packet": geometry_contract,
        "gtos_vnext_target_stop_geometry_v4_packet": geometry_contract,
        "target_stop_geometry_v4": geometry_contract,
        "gtos_vnext_geometry_contract_hash": geometry_contract.get("packet_hash_sha256"),
        "gtos_vnext_expected_cost_r": cost_r,
        "gtos_vnext_commission_model_status": "COMMISSION_INCLUDED_IN_SELECTED_CELL_RISK",
        "gtos_vnext_production_execution_path": False,
    }


REPLAY_NONBLOCKING_EXECUTION_MANAGER_FATAL_REASONS: tuple[str, ...] = (
    "scheduler_v4_selected_action_not_runtime_eligible",
    "prop_firm_headroom_v4_snapshot_not_broker_real",
)

REPLAY_NONBLOCKING_EXECUTION_MANAGER_FATAL_PREFIXES: tuple[str, ...] = (
    "missing_broker_lifecycle_capture:",
    "missing_geometry_contract:",
    "missing_cost:",
)


def broad_live_as_if_no_broker_replay(config: Mapping[str, Any]) -> bool:
    harness = config.get("broad_live_as_if_replay_harness")
    if not isinstance(harness, Mapping):
        return False
    return (
        harness.get("live_broker_authority") is False
        and harness.get("broker_mutation_enabled") is False
        and harness.get("final_selection_claim") is False
    )


def broad_live_as_if_package_execution_result_scope(
    config: Mapping[str, Any],
) -> str:
    harness = config.get("broad_live_as_if_replay_harness")
    if isinstance(harness, Mapping):
        scope = harness.get("package_execution_result_scope")
        if scope not in (None, ""):
            return str(scope)
    runtime = config.get("gtos_vnext_runtime")
    if isinstance(runtime, Mapping):
        scope = runtime.get("broad_live_as_if_replay_package_execution_result_scope")
        if scope not in (None, ""):
            return str(scope)
    return ""


def broad_live_as_if_raw_baseline_diagnostic_only(config: Mapping[str, Any]) -> bool:
    harness = config.get("broad_live_as_if_replay_harness")
    if isinstance(harness, Mapping) and harness.get("raw_baseline_diagnostic_only") is True:
        return True
    return (
        broad_live_as_if_package_execution_result_scope(config)
        == "raw_baseline_diagnostic_only"
    )


def replay_lifecycle_signed_package_authority_valid(
    *surfaces: Mapping[str, Any] | None,
) -> bool:
    attribution = package_new_entry_authority_attribution_fields(*surfaces)
    payload = attribution.get("package_new_entry_authority_payload")
    if (
        attribution.get("package_new_entry_authority_valid") is not True
        or not isinstance(payload, Mapping)
        or package_new_entry_authority_payload_hash_sha256(payload)
        != str(
            attribution.get(PACKAGE_NEW_ENTRY_AUTHORITY_HASH_FIELD) or ""
        ).strip()
    ):
        return False
    signed_target_action = normalize_scheduler_action_intent(
        payload.get("target_action_intent")
    )
    if signed_target_action not in SIGNED_REDUCED_PACKAGE_NEW_ENTRY_ACTIONS:
        return False

    lifecycle_root_authority: Mapping[str, Any] = {}
    for surface in surfaces:
        if not isinstance(surface, Mapping):
            continue
        root = surface.get("package_lifecycle_root_authority")
        if isinstance(root, Mapping):
            lifecycle_root_authority = root
            break
    root_action = normalize_scheduler_action_intent(
        first_present(
            lifecycle_root_authority.get("root_action"),
            lifecycle_root_authority.get("effective_action_intent"),
            lifecycle_root_authority.get("target_action_intent"),
        )
    )
    root_applies = _runtime_bool(lifecycle_root_authority.get("applies"), False)
    if root_applies:
        root_boundary = str(lifecycle_root_authority.get("source_boundary") or "")
        if not _runtime_bool(lifecycle_root_authority.get("allowed"), False):
            return False
        if _runtime_bool(lifecycle_root_authority.get("uses_outcome_fields"), False):
            return False
        if "predecision" not in root_boundary or "no_outcome" not in root_boundary:
            return False
        if root_action not in SIGNED_REDUCED_PACKAGE_NEW_ENTRY_ACTIONS:
            return False
    if root_action and signed_target_action and signed_target_action != root_action:
        return False

    observed_lifecycle_actions: set[str] = set()
    for surface in surfaces:
        if not isinstance(surface, Mapping):
            continue
        for action_key in (
            "same_symbol_lifecycle_action",
            "gtos_vnext_same_symbol_lifecycle_action",
            "lifecycle_action",
            "scheduler_materialization_action_intent",
            "scheduler_materialization_replay_lifecycle_action_resolver_resolved_action_intent",
            "scheduler_action_class",
        ):
            observed_action = normalize_scheduler_action_intent(
                surface.get(action_key)
            )
            if observed_action:
                observed_lifecycle_actions.add(observed_action)
    if root_action:
        observed_lifecycle_actions.add(root_action)
    if not observed_lifecycle_actions or observed_lifecycle_actions != {
        signed_target_action
    }:
        return False
    if signed_target_action == "close_and_reverse" and not (
        root_applies
        and root_action == "close_and_reverse"
        and _runtime_bool(lifecycle_root_authority.get("allowed"), False)
    ):
        return False
    return True


def execution_manager_replay_admission(
    *,
    execution_decision: Any,
    config: Mapping[str, Any],
    risk_authority: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Classify execution-manager blocks for local no-broker replay.

    The production execution manager remains fail-closed. Broad live-as-if replay
    keeps those live-promotion defects visible, but it must not convert missing
    broker-real proof into a simulated no-trade when replay has no broker
    mutation authority.
    """

    fatal_reasons = [str(item) for item in getattr(execution_decision, "fatal_reasons", ())]
    if not getattr(execution_decision, "should_block", False):
        return {
            "status": "execution_manager_allowed",
            "replay_should_block": False,
            "live_should_block": False,
            "replay_override_applied": False,
            "live_promotion_blocker_reasons": [],
            "replay_blocking_reasons": [],
            "source_boundary": "execution_manager_v4_allowed",
        }
    if not broad_live_as_if_no_broker_replay(config):
        return {
            "status": "execution_manager_live_block_applied",
            "replay_should_block": True,
            "live_should_block": True,
            "replay_override_applied": False,
            "live_promotion_blocker_reasons": fatal_reasons,
            "replay_blocking_reasons": fatal_reasons,
            "source_boundary": "execution_manager_v4_apply_to_execution",
        }

    risk_authority = risk_authority if isinstance(risk_authority, Mapping) else {}
    source_required_reconcile_packet = risk_authority.get(
        "source_required_package_risk_lifecycle_reconcile"
    )
    source_required_reconcile_packet = (
        source_required_reconcile_packet
        if isinstance(source_required_reconcile_packet, Mapping)
        else {}
    )
    scale_in_reconcile_packet = risk_authority.get(
        "package_same_direction_scale_in_lifecycle_reconcile"
    )
    scale_in_reconcile_packet = (
        scale_in_reconcile_packet if isinstance(scale_in_reconcile_packet, Mapping) else {}
    )
    close_reverse_reconcile_packet = risk_authority.get(
        "package_opposite_side_close_reverse_lifecycle_reconcile"
    )
    close_reverse_reconcile_packet = (
        close_reverse_reconcile_packet
        if isinstance(close_reverse_reconcile_packet, Mapping)
        else {}
    )
    pending_replacement_reconcile_packet = risk_authority.get(
        "package_pending_replacement_lifecycle_reconcile"
    )
    pending_replacement_reconcile_packet = (
        pending_replacement_reconcile_packet
        if isinstance(pending_replacement_reconcile_packet, Mapping)
        else {}
    )
    same_symbol_lifecycle_reconcile_applied = _runtime_bool(
        first_present(
            risk_authority.get("same_symbol_lifecycle_permission_reconcile_applied"),
            source_required_reconcile_packet.get("applied"),
            scale_in_reconcile_packet.get("applied"),
            close_reverse_reconcile_packet.get("applied"),
            pending_replacement_reconcile_packet.get("applied"),
        ),
        False,
    )
    source_required_lifecycle_reconcile_applied = _runtime_bool(
        source_required_reconcile_packet.get("applied"),
        False,
    )
    scale_in_lifecycle_reconcile_applied = _runtime_bool(
        scale_in_reconcile_packet.get("applied"),
        False,
    )
    close_reverse_lifecycle_reconcile_applied = _runtime_bool(
        close_reverse_reconcile_packet.get("applied"),
        False,
    )
    pending_replacement_lifecycle_reconcile_applied = _runtime_bool(
        pending_replacement_reconcile_packet.get("applied"),
        False,
    )
    source_required_broker_lifecycle_truth_satisfied = _runtime_bool(
        first_present(
            risk_authority.get("broker_order_lifecycle_truth_satisfied"),
            risk_authority.get("broker_lifecycle_truth_satisfied"),
            risk_authority.get("source_required_broker_lifecycle_truth_satisfied"),
            source_required_reconcile_packet.get("broker_order_lifecycle_truth_satisfied"),
            source_required_reconcile_packet.get("broker_lifecycle_truth_satisfied"),
            source_required_reconcile_packet.get(
                "source_required_broker_lifecycle_truth_satisfied"
            ),
        ),
        False,
    )
    source_required_replay_signed_authority_valid = (
        replay_lifecycle_signed_package_authority_valid(
            risk_authority,
            source_required_reconcile_packet,
            scale_in_reconcile_packet,
            close_reverse_reconcile_packet,
            pending_replacement_reconcile_packet,
        )
    )
    replay_demoted_promotion_blockers: list[str] = []
    replay_blocking: list[str] = []
    promotion_blockers: list[str] = []
    for reason in fatal_reasons:
        source_required_lifecycle_fatal = reason.startswith(
            "same_symbol_lifecycle_v4_not_permitted:source_required_fail_closed"
        )
        source_required_lifecycle_replayed = (
            (
                source_required_lifecycle_reconcile_applied
                or scale_in_lifecycle_reconcile_applied
                or close_reverse_lifecycle_reconcile_applied
                or pending_replacement_lifecycle_reconcile_applied
                or same_symbol_lifecycle_reconcile_applied
            )
            and source_required_lifecycle_fatal
            and (
                source_required_broker_lifecycle_truth_satisfied
                or source_required_replay_signed_authority_valid
            )
        )
        same_symbol_lifecycle_replayed = (
            same_symbol_lifecycle_reconcile_applied
            and not source_required_lifecycle_fatal
            and reason.startswith("same_symbol_lifecycle_v4_not_permitted")
        )
        if (
            source_required_lifecycle_replayed
            or same_symbol_lifecycle_replayed
            or reason in REPLAY_NONBLOCKING_EXECUTION_MANAGER_FATAL_REASONS
            or any(
                reason.startswith(prefix)
                for prefix in REPLAY_NONBLOCKING_EXECUTION_MANAGER_FATAL_PREFIXES
            )
        ):
            promotion_blockers.append(reason)
            if source_required_lifecycle_replayed or same_symbol_lifecycle_replayed:
                replay_demoted_promotion_blockers.append(reason)
        else:
            replay_blocking.append(reason)
    replay_should_block = bool(replay_blocking)
    return {
        "status": (
            "execution_manager_live_promotion_blockers_recorded_replay_allowed"
            if not replay_should_block
            else "execution_manager_replay_block_applied"
        ),
        "replay_should_block": replay_should_block,
        "live_should_block": True,
        "replay_override_applied": not replay_should_block,
        "live_promotion_blocker_reasons": promotion_blockers,
        "replay_blocking_reasons": replay_blocking,
        "replay_demoted_live_promotion_blocker_reasons": (
            replay_demoted_promotion_blockers
        ),
        "source_required_package_risk_lifecycle_reconcile_applied": (
            source_required_lifecycle_reconcile_applied
        ),
        "source_required_broker_lifecycle_truth_satisfied": (
            source_required_broker_lifecycle_truth_satisfied
        ),
        "source_required_replay_signed_package_authority_valid": (
            source_required_replay_signed_authority_valid
        ),
        "package_same_direction_scale_in_lifecycle_reconcile_applied": (
            scale_in_lifecycle_reconcile_applied
        ),
        "package_opposite_side_close_reverse_lifecycle_reconcile_applied": (
            close_reverse_lifecycle_reconcile_applied
        ),
        "package_pending_replacement_lifecycle_reconcile_applied": (
            pending_replacement_lifecycle_reconcile_applied
        ),
        "same_symbol_lifecycle_permission_reconcile_applied": (
            same_symbol_lifecycle_reconcile_applied
        ),
        "same_symbol_lifecycle_permission_reconcile_reason": risk_authority.get(
            "same_symbol_lifecycle_permission_reconcile_reason"
        ),
        "source_boundary": (
            "broker_live_proof_gaps_recorded_no_broker_replay_order_simulation_allowed"
        ),
    }


def _tick_price(row: Mapping[str, Any], *, side: str, use_entry_fill_side: bool = False) -> float | None:
    bid = row.get("bid")
    ask = row.get("ask")
    last = row.get("last")
    try:
        bid_f = float(bid) if bid not in (None, "") else None
        ask_f = float(ask) if ask not in (None, "") else None
        last_f = float(last) if last not in (None, "") else None
    except (TypeError, ValueError):
        return None
    if use_entry_fill_side:
        if str(side).upper() == "LONG":
            return ask_f if ask_f is not None and ask_f > 0 else last_f
        return bid_f if bid_f is not None and bid_f > 0 else last_f
    if bid_f is not None and ask_f is not None and bid_f > 0 and ask_f > 0:
        return (bid_f + ask_f) / 2.0
    return last_f if last_f is not None and last_f > 0 else bid_f or ask_f


def _tick_entry_fill_price_with_source(
    row: Mapping[str, Any],
    *,
    side: str,
) -> tuple[float | None, str | None]:
    bid = row.get("bid")
    ask = row.get("ask")
    last = row.get("last")
    try:
        bid_f = float(bid) if bid not in (None, "") else None
        ask_f = float(ask) if ask not in (None, "") else None
        last_f = float(last) if last not in (None, "") else None
    except (TypeError, ValueError):
        return None, None
    if str(side).upper() == "LONG":
        if ask_f is not None and ask_f > 0:
            return ask_f, "tick_ask"
    elif bid_f is not None and bid_f > 0:
        return bid_f, "tick_bid"
    if last_f is not None and last_f > 0:
        return last_f, "tick_last"
    return None, None


def _tick_close_price_with_source(
    row: Mapping[str, Any],
    *,
    side: str,
) -> tuple[float | None, str | None, str | None, bool]:
    """Return the executable close quote for an open position.

    A long closes against bid and a short closes against ask. Last-price
    fallback remains diagnostic and cannot grant ordered-tick terminal-R
    authority.
    """

    bid = row.get("bid")
    ask = row.get("ask")
    last = row.get("last")
    try:
        bid_f = float(bid) if bid not in (None, "") else None
        ask_f = float(ask) if ask not in (None, "") else None
        last_f = float(last) if last not in (None, "") else None
    except (TypeError, ValueError):
        return None, None, None, False
    side_key = str(side or "").upper()
    if side_key == "LONG" and bid_f is not None and bid_f > 0:
        return bid_f, "tick_bid", "bid", True
    if side_key == "SHORT" and ask_f is not None and ask_f > 0:
        return ask_f, "tick_ask", "ask", True
    if last_f is not None and last_f > 0:
        return last_f, "tick_last_diagnostic", "last", False
    return None, None, None, False


def _positive_float_field(
    row: Mapping[str, Any],
    key: str,
) -> tuple[float, str] | None:
    value = row.get(key)
    if value in (None, ""):
        return None
    try:
        parsed = float(value)
    except (TypeError, ValueError):
        return None
    if parsed > 0:
        return parsed, key
    return None


def _m1_market_fallback_entry_price_with_source(
    row: Mapping[str, Any],
    *,
    side: str,
) -> tuple[float | None, str | None]:
    parsed_fields = [
        parsed
        for key in ("open", "high", "low", "close", "last", "bid", "ask")
        if (parsed := _positive_float_field(row, key)) is not None
    ]
    if not parsed_fields:
        return None, None
    side_key = str(side or "").upper()
    if side_key == "LONG":
        price, key = max(parsed_fields, key=lambda item: item[0])
        return price, f"m1_side_conservative_{key}"
    if side_key == "SHORT":
        price, key = min(parsed_fields, key=lambda item: item[0])
        return price, f"m1_side_conservative_{key}"
    return None, None


def _postdecision_row_price_with_source(
    row: Mapping[str, Any],
    *,
    source: str,
    side: str,
) -> tuple[float | None, str | None, str | None, bool]:
    if source == "tick":
        return _tick_close_price_with_source(row, side=side)
    for key in ("close", "last", "bid", "ask"):
        value = row.get(key)
        if value in (None, ""):
            continue
        try:
            parsed = float(value)
        except (TypeError, ValueError):
            continue
        if parsed > 0:
            return parsed, f"{source}_{key}", key, False
    return None, None, None, False


def _postdecision_row_price(
    row: Mapping[str, Any],
    *,
    source: str,
    side: str,
) -> float | None:
    price, _price_source, _quote_side, _executable = (
        _postdecision_row_price_with_source(
            row,
            source=source,
            side=side,
        )
    )
    return price


def attach_close_mark(
    *,
    oracle: Mapping[str, Any],
    rows: Iterable[Mapping[str, Any]],
    candidate: Mapping[str, Any],
    expiry: datetime,
) -> dict[str, Any]:
    output = dict(oracle)
    fill_time = parse_utc(output.get("fill_time_utc"))
    fill_status = str(output.get("fill_status") or "")
    if not fill_status.startswith("filled") or fill_time is None:
        return output
    terminal = str(output.get("terminal_outcome") or "")
    if terminal in {"target_reached_before_stop", "stop_reached_before_target"}:
        output.setdefault(
            "close_mark_time_utc",
            output.get("target_first_touch_utc") if terminal.startswith("target") else output.get("stop_first_touch_utc"),
        )
        output.setdefault("close_mark_source", terminal)
        return output
    if "ambiguous" in terminal or output.get("same_bar_ambiguity"):
        output["ambiguity_resolution"] = "conservative_stop_close_required_without_ordered_tick"
        return output
    source = str(output.get("source") or "m1")
    side = str(candidate.get("side") or "")
    entry = safe_float(candidate.get("entry_price"))
    stop = safe_float(candidate.get("stop_loss"))
    risk = abs(entry - stop)
    if risk <= 0:
        output.setdefault("source_gaps", [])
        gaps = list(output.get("source_gaps") or [])
        gaps.append("close_mark_invalid_entry_stop_geometry")
        output["source_gaps"] = list(dict.fromkeys(gaps))
        return output
    selected: tuple[
        datetime,
        Mapping[str, Any],
        float,
        str | None,
        str | None,
        bool,
    ] | None = None
    for row in rows:
        ts = parse_row_time(row)
        if ts is None or ts < fill_time or ts > expiry:
            continue
        price, price_source, quote_side, executable_close_side = (
            _postdecision_row_price_with_source(
                row,
                source=source,
                side=side,
            )
        )
        if price is None:
            continue
        selected = (
            ts,
            row,
            price,
            price_source,
            quote_side,
            executable_close_side,
        )
    if selected is None:
        gaps = list(output.get("source_gaps") or [])
        gaps.append("filled_no_terminal_close_mark_source_rows_missing_after_fill")
        output["source_gaps"] = list(dict.fromkeys(gaps))
        return output
    (
        close_time,
        _row,
        close_price,
        close_price_source,
        close_quote_side,
        close_executable_quote_side,
    ) = selected
    close_r = (
        (close_price - entry) / risk
        if str(side).upper() == "LONG"
        else (entry - close_price) / risk
    )
    output["close_mark_time_utc"] = iso(close_time)
    output["close_mark_price"] = close_price
    output["close_mark_r"] = round(close_r, 8)
    output["close_mark_source"] = source
    output["close_mark_price_source"] = close_price_source
    output["close_mark_quote_side"] = close_quote_side
    output["close_mark_executable_quote_side"] = (
        close_executable_quote_side
    )
    output["terminal_outcome"] = "filled_time_stop_close_mark"
    output["time_stop_close"] = True
    return output


TERMINAL_LIFECYCLE_CLOSE_SOURCE_PRIORITY = ("TICK", "M1", "M15")
TERMINAL_LIFECYCLE_CLOSE_MAX_STALENESS_MINUTES = {
    "TICK": 15,
    "M1": 2,
    "M15": 20,
}


def terminal_lifecycle_close_expected_cost_r(position: Mapping[str, Any]) -> Any:
    """Prefer close-side cost for terminal lifecycle closes."""

    return first_present(
        position.get("terminal_lifecycle_close_expected_cost_r"),
        position.get("terminal_close_expected_cost_r"),
        position.get("terminal_lifecycle_expected_cost_r"),
        position.get("predecision_expected_cost_r"),
        position.get("expected_cost_r"),
    )


def _terminal_lifecycle_close_source_authority(
    source: ResolvedSource,
    *,
    close_time: datetime | None = None,
) -> str:
    timeframe = str(source.spec.timeframe or "").upper()
    if timeframe == "TICK" and source.spec.ordered_tick_truth_satisfied is True:
        return "ordered_tick_truth_terminal_lifecycle_close_r_authority"
    if timeframe == "TICK":
        return "tick_source_terminal_lifecycle_close_r_authority"
    day_authority = resolved_source_day_authority(
        source,
        close_time.astimezone(timezone.utc).date().isoformat()
        if close_time is not None
        else "",
    )
    if day_authority.get("diagnostic_fallback_only") is True:
        return f"{timeframe.lower()}_diagnostic_proxy_terminal_lifecycle_close_r_authority"
    return f"{timeframe.lower()}_source_bound_terminal_lifecycle_close_r_authority"


def _terminal_lifecycle_close_mark_price(
    row: Mapping[str, Any],
    *,
    source: ResolvedSource,
    side: str,
) -> float | None:
    detail = _terminal_lifecycle_close_mark_detail(
        row,
        source=source,
        side=side,
    )
    return _optional_float(detail.get("price"))


def _terminal_lifecycle_close_mark_detail(
    row: Mapping[str, Any],
    *,
    source: ResolvedSource,
    side: str,
) -> dict[str, Any]:
    timeframe = str(source.spec.timeframe or "").upper()
    if timeframe == "TICK":
        price, price_source, quote_side, executable_close_side = (
            _tick_close_price_with_source(row, side=side)
        )
    else:
        price, price_source, quote_side, executable_close_side = (
            _postdecision_row_price_with_source(
                row,
                source=timeframe.lower(),
                side=side,
            )
        )
    return {
        "price": price,
        "price_source": price_source,
        "quote_side": quote_side,
        "executable_close_side": executable_close_side,
    }


def materialize_terminal_lifecycle_close_r_from_source(
    *,
    account: "AccountState",
    exposure_ids: Iterable[str],
    asof: datetime,
    path_sources: Mapping[str, ResolvedSource] | None,
    day: str,
) -> dict[str, Any]:
    """Stamp source-bound terminal close R on open exposures before mutation.

    The scheduler lifecycle mutator intentionally refuses to close exposure PnL
    without source-bound close R. This producer supplies that R from the same
    replay source map used by order fillability, preferring ordered ticks and
    falling back only to labelled lower-resolution replay sources.
    """

    if not isinstance(path_sources, Mapping) or not path_sources:
        return {
            "status": "source_gap_no_path_sources_for_terminal_lifecycle_close_r",
            "materialized_count": 0,
            "materialized_trade_ids": [],
            "exposure_results": [],
        }
    assert account.open_positions is not None
    materialized_trade_ids: list[str] = []
    exposure_results: list[dict[str, Any]] = []
    for exposure_id in dict.fromkeys(
        str(item) for item in exposure_ids if str(item or "").strip()
    ):
        matched_trade_id, position = account.open_exposure_for_scheduler_id(
            exposure_id
        )
        if matched_trade_id is None or position is None:
            exposure_results.append(
                {
                    "selected_exposure_id": exposure_id,
                    "status": "open_exposure_not_found_for_terminal_lifecycle_close_r",
                }
            )
            continue
        if _optional_float(position.get("terminal_lifecycle_close_net_proxy_r")) is not None:
            exposure_results.append(
                {
                    "selected_exposure_id": exposure_id,
                    "simulated_trade_id": matched_trade_id,
                    "status": "terminal_lifecycle_close_r_already_present",
                    "terminal_lifecycle_close_r_source_field": (
                        "terminal_lifecycle_close_net_proxy_r"
                    ),
                }
            )
            continue
        side = str(position.get("side") or "").upper()
        entry = _optional_float(
            first_present(
                position.get("entry_price"),
                position.get("fill_price"),
                position.get("requested_entry_price"),
            )
        )
        stop = _optional_float(
            first_present(
                position.get("stop_loss"),
                position.get("stop_price"),
                position.get("initial_stop_loss"),
            )
        )
        entry_time = parse_utc(
            first_present(
                position.get("entry_time_utc"),
                position.get("fill_time_utc"),
                position.get("decision_time_utc"),
                position.get("candle_close_utc"),
            )
        )
        if side not in {"LONG", "SHORT"} or entry is None or stop is None:
            exposure_results.append(
                {
                    "selected_exposure_id": exposure_id,
                    "simulated_trade_id": matched_trade_id,
                    "status": "source_gap_terminal_lifecycle_close_geometry_missing",
                    "side": side,
                    "entry_price_present": entry is not None,
                    "stop_loss_present": stop is not None,
                }
            )
            continue
        risk_distance = abs(entry - stop)
        if risk_distance <= 0:
            exposure_results.append(
                {
                    "selected_exposure_id": exposure_id,
                    "simulated_trade_id": matched_trade_id,
                    "status": "source_gap_terminal_lifecycle_close_invalid_risk_geometry",
                    "entry_price": entry,
                    "stop_loss": stop,
                }
            )
            continue
        if entry_time is None:
            exposure_results.append(
                {
                    "selected_exposure_id": exposure_id,
                    "simulated_trade_id": matched_trade_id,
                    "status": "source_gap_terminal_lifecycle_close_entry_time_missing",
                }
            )
            continue
        requested_day = date.fromisoformat(str(day))
        requested_day_start = datetime.combine(
            requested_day,
            datetime.min.time(),
            tzinfo=timezone.utc,
        )
        query_after = max(
            entry_time - timedelta(microseconds=1),
            requested_day_start - timedelta(microseconds=1),
        )
        selected: tuple[
            ResolvedSource,
            PathTruthQuery,
            datetime,
            dict[str, Any],
            float,
            dict[str, Any],
        ] | None = None
        source_attempts: list[dict[str, Any]] = []
        for timeframe in TERMINAL_LIFECYCLE_CLOSE_SOURCE_PRIORITY:
            source = path_sources.get(timeframe)
            if source is None:
                source_attempts.append(
                    {"timeframe": timeframe, "status": "source_missing"}
                )
                continue
            requested_day_authority = resolved_source_day_authority(
                source,
                str(day),
            )
            if (
                timeframe == "M1"
                and requested_day_authority.get(
                    "terminal_lifecycle_close_allowed"
                )
                is not True
            ):
                source_attempts.append(
                    {
                        "timeframe": timeframe,
                        "status": (
                            "source_day_not_authoritative_for_terminal_close"
                        ),
                        "source_day_authority": requested_day_authority,
                    }
                )
                continue
            query = PathTruthIndex(source).query(after=query_after, until=asof)
            source_attempts.append(
                {
                    "timeframe": timeframe,
                    "status": "queried",
                    "rows_returned": len(query.rows),
                    "source_path": str(source.spec.path),
                    "source_sha256": source.sha256,
                }
            )
            for row in query.rows:
                ts = parse_row_time(row)
                if (
                    ts is None
                    or ts < entry_time
                    or ts > asof
                    or ts.astimezone(timezone.utc).date() != requested_day
                ):
                    continue
                max_staleness = timedelta(
                    minutes=TERMINAL_LIFECYCLE_CLOSE_MAX_STALENESS_MINUTES[
                        timeframe
                    ]
                )
                if asof - ts > max_staleness:
                    continue
                close_mark_detail = _terminal_lifecycle_close_mark_detail(
                    row,
                    source=source,
                    side=side,
                )
                price = _optional_float(close_mark_detail.get("price"))
                if price is None or price <= 0:
                    continue
                selected = (
                    source,
                    query,
                    ts,
                    dict(row),
                    price,
                    close_mark_detail,
                )
            if selected is not None:
                break
        if selected is None:
            exposure_results.append(
                {
                    "selected_exposure_id": exposure_id,
                    "simulated_trade_id": matched_trade_id,
                    "status": "source_gap_terminal_lifecycle_close_mark_missing",
                    "entry_time_utc": iso(entry_time),
                    "close_asof_utc": iso(asof),
                    "source_attempts": source_attempts,
                }
            )
            continue
        (
            source,
            query,
            close_time,
            _row,
            close_price,
            close_mark_detail,
        ) = selected
        gross_r = (
            (close_price - entry) / risk_distance
            if side == "LONG"
            else (entry - close_price) / risk_distance
        )
        expected_cost_r = safe_float(
            terminal_lifecycle_close_expected_cost_r(position),
            0.0,
        )
        net_proxy_r = gross_r - expected_cost_r
        close_day_authority = resolved_source_day_authority(
            source,
            close_time.astimezone(timezone.utc).date().isoformat(),
        )
        authority = _terminal_lifecycle_close_source_authority(
            source,
            close_time=close_time,
        )
        if (
            str(source.spec.timeframe or "").upper() == "TICK"
            and close_mark_detail.get("executable_close_side") is not True
        ):
            authority = (
                "tick_last_diagnostic_proxy_terminal_lifecycle_close_r_authority"
            )
        authority_commit_allowed = bool(
            close_day_authority.get("diagnostic_fallback_only") is not True
            and "diagnostic_proxy" not in authority
            and close_time.astimezone(timezone.utc).date() == requested_day
        )
        if not authority_commit_allowed:
            exposure_results.append(
                {
                    "selected_exposure_id": exposure_id,
                    "simulated_trade_id": matched_trade_id,
                    "status": (
                        "source_gap_terminal_lifecycle_close_authority_not_"
                        "executable"
                    ),
                    "terminal_lifecycle_close_r_path_authority": authority,
                    "terminal_lifecycle_close_mark_time_utc": iso(close_time),
                    "source_day_authority": close_day_authority,
                }
            )
            continue
        position.update(
            {
                "terminal_lifecycle_close_gross_r": round(gross_r, 8),
                "terminal_lifecycle_close_expected_cost_r": round(
                    expected_cost_r,
                    8,
                ),
                "terminal_lifecycle_close_net_proxy_r": round(net_proxy_r, 8),
                "terminal_lifecycle_close_mark_time_utc": iso(close_time),
                "terminal_lifecycle_close_mark_price": close_price,
                "terminal_lifecycle_close_mark_price_source": (
                    close_mark_detail.get("price_source")
                ),
                "terminal_lifecycle_close_mark_quote_side": (
                    close_mark_detail.get("quote_side")
                ),
                "terminal_lifecycle_close_mark_executable_quote_side": (
                    close_mark_detail.get("executable_close_side")
                ),
                "terminal_lifecycle_close_mark_source": str(
                    source.spec.timeframe or ""
                ).lower(),
                "terminal_lifecycle_close_source_day_authority": (
                    close_day_authority
                ),
                "terminal_lifecycle_close_source_day_status": (
                    close_day_authority.get("status")
                ),
                "terminal_lifecycle_close_source_day_diagnostic_fallback_only": (
                    close_day_authority.get("diagnostic_fallback_only") is True
                ),
                "terminal_lifecycle_close_r_source_status": (
                    "source_bound_terminal_lifecycle_close_r_present"
                ),
                "terminal_lifecycle_close_r_source_field": (
                    "terminal_lifecycle_close_net_proxy_r"
                ),
                "terminal_lifecycle_close_r_path_authority": authority,
                "terminal_lifecycle_close_r_authority_commit_allowed": True,
                "terminal_lifecycle_close_requested_day": str(day),
                "terminal_lifecycle_close_r_source_boundary": (
                    "local_replay_source_bound_terminal_lifecycle_close_r"
                ),
                "terminal_lifecycle_close_mark_source_path": str(
                    source.spec.path
                ),
                "terminal_lifecycle_close_mark_source_sha256": source.sha256,
                "terminal_lifecycle_close_mark_source_timeframe": (
                    source.spec.timeframe
                ),
                "terminal_lifecycle_close_mark_lookup_mode": query.metadata.get(
                    "path_index_lookup_mode"
                ),
                "terminal_lifecycle_close_mark_rows_returned": query.metadata.get(
                    "path_index_rows_returned"
                ),
                "terminal_lifecycle_close_mark_ordered_tick_truth": (
                    source.spec.ordered_tick_truth_satisfied is True
                ),
            }
        )
        materialized_trade_ids.append(str(matched_trade_id))
        exposure_results.append(
            {
                "selected_exposure_id": exposure_id,
                "simulated_trade_id": matched_trade_id,
                "status": "source_bound_terminal_lifecycle_close_r_materialized",
                "terminal_lifecycle_close_r_path_authority": authority,
                "terminal_lifecycle_close_mark_time_utc": iso(close_time),
                "terminal_lifecycle_close_mark_price": close_price,
                "terminal_lifecycle_close_mark_price_source": (
                    close_mark_detail.get("price_source")
                ),
                "terminal_lifecycle_close_mark_quote_side": (
                    close_mark_detail.get("quote_side")
                ),
                "terminal_lifecycle_close_mark_executable_quote_side": (
                    close_mark_detail.get("executable_close_side")
                ),
                "terminal_lifecycle_close_gross_r": round(gross_r, 8),
                "terminal_lifecycle_close_expected_cost_r": round(
                    expected_cost_r,
                    8,
                ),
                "terminal_lifecycle_close_net_proxy_r": round(net_proxy_r, 8),
                "source_path": str(source.spec.path),
                "source_sha256": source.sha256,
                "source_timeframe": source.spec.timeframe,
                "source_day_authority": close_day_authority,
                "source_day_status": close_day_authority.get("status"),
                "source_day_diagnostic_fallback_only": (
                    close_day_authority.get("diagnostic_fallback_only") is True
                ),
            }
        )
    return {
        "status": (
            "source_bound_terminal_lifecycle_close_r_materialized"
            if materialized_trade_ids
            else "source_gap_terminal_lifecycle_close_r_not_materialized"
        ),
        "materialized_count": len(materialized_trade_ids),
        "materialized_trade_ids": materialized_trade_ids,
        "exposure_results": exposure_results,
    }


def infer_ordered_path_from_ticks(
    *,
    ticks: Iterable[Mapping[str, Any]],
    side: str,
    entry_price: float,
    stop_price: float,
    target_price: float,
    asof_utc: str,
    fill_already_confirmed: bool = False,
    fill_time_utc: str | None = None,
    passive_limit_queue_realism_enabled: bool = False,
    passive_limit_queue_min_penetration_r: float = 0.0,
    passive_limit_queue_min_touch_count: int = 1,
) -> dict[str, Any]:
    return infer_microstructure_ordered_path_from_ticks(
        ticks=ticks,
        side=side,
        entry_price=entry_price,
        stop_price=stop_price,
        target_price=target_price,
        asof_utc=asof_utc,
        fill_already_confirmed=fill_already_confirmed,
        fill_time_utc=fill_time_utc,
        passive_limit_queue_realism_enabled=passive_limit_queue_realism_enabled,
        passive_limit_queue_min_penetration_r=(
            passive_limit_queue_min_penetration_r
        ),
        passive_limit_queue_min_touch_count=passive_limit_queue_min_touch_count,
    ).as_dict()


def path_source_and_oracle(
    *,
    candidate: Mapping[str, Any],
    sources: Mapping[str, ResolvedSource],
    day: str,
    asof: datetime,
    expiry: datetime,
    prefer_tick: bool = True,
    config: Mapping[str, Any] | None = None,
    query_cache: MutableMapping[
        PathTruthQueryCacheKey,
        PathTruthQueryCacheValue,
    ]
    | None = None,
) -> tuple[dict[str, Any], ResolvedSource, tuple[dict[str, Any], ...]]:
    policy_config = replay_order_fillability_runtime_config(config or {})
    queue_realism_kwargs = {
        "passive_limit_queue_realism_enabled": bool(
            policy_config.get("passive_limit_queue_realism_enabled")
        ),
        "passive_limit_queue_min_penetration_r": safe_float(
            policy_config.get("passive_limit_queue_realism_min_penetration_r"),
            0.0,
        ),
        "passive_limit_queue_min_touch_count": int(
            max(
                1,
                safe_float(
                    policy_config.get("passive_limit_queue_realism_min_touch_count"),
                    1.0,
                ),
            )
        ),
    }
    candidate, _immediate_candidate_metadata = marketable_limit_immediate_fill_candidate(
        candidate,
        asof=asof,
    )
    immediate_marketable_fill = (
        candidate.get("limit_immediate_marketable_fill_at_decision_applied") is True
    )
    immediate_marketable_fill_time = (
        str(candidate.get("limit_immediate_marketable_fill_time_utc") or iso(asof) or "")
        if immediate_marketable_fill
        else None
    )
    immediate_marketable_fields = {
        key: value
        for key, value in candidate.items()
        if str(key).startswith("limit_immediate_marketable_")
        or str(key).startswith("limit_requested_")
        or str(key).startswith("original_limit_")
    }
    if immediate_marketable_fill:
        immediate_marketable_fields["effective_order_geometry_source"] = (
            "immediate_marketable_limit_at_decision"
        )
    source_gaps: list[str] = []
    tick_source = sources.get("TICK")
    tick_query: PathTruthQuery | None = None
    tick_rows: tuple[dict[str, Any], ...] = ()

    def _source_window_covers_candidate(source: ResolvedSource | None) -> bool:
        if source is None:
            return False
        start = parse_utc(source.spec.start_utc)
        end = parse_utc(source.spec.end_utc)
        return bool(start is not None and end is not None and start <= asof and end >= expiry)

    def _tick_coverage_fields(*, gap_reason: str | None = None) -> dict[str, Any]:
        tick_path = str(tick_source.spec.path) if tick_source is not None else None
        tick_start = tick_source.spec.start_utc if tick_source is not None else None
        tick_end = tick_source.spec.end_utc if tick_source is not None else None
        return {
            "tick_source_available": tick_source is not None,
            "tick_query_rows_returned": len(tick_rows),
            "tick_source_path": tick_path,
            "tick_source_start_utc": tick_start,
            "tick_source_end_utc": tick_end,
            "tick_window_covers_candidate": _source_window_covers_candidate(tick_source),
            "tick_gap_reason": gap_reason,
        }

    if prefer_tick and tick_source is not None:
        tick_query = cached_path_truth_query(
            tick_source,
            after=asof,
            until=expiry,
            query_cache=query_cache,
        )
        tick_rows = tick_query.rows
        if tick_rows:
            oracle = infer_ordered_path_from_ticks(
                ticks=tick_rows,
                side=str(candidate.get("side") or ""),
                entry_price=safe_float(candidate.get("entry_price")),
                stop_price=safe_float(candidate.get("stop_loss")),
                target_price=safe_float(candidate.get("take_profit_1")),
                asof_utc=iso(asof) or "",
                fill_already_confirmed=immediate_marketable_fill,
                fill_time_utc=immediate_marketable_fill_time,
                **queue_realism_kwargs,
            )
            ordered_tick_truth_satisfied = bool(
                tick_source.spec.ordered_tick_truth_satisfied is True
            )
            ordered_tick_truth_authority = {
                "source": "tick",
                "source_path": str(tick_source.spec.path),
                "source_sha256": tick_source.sha256,
                "source_timeframe": tick_source.spec.timeframe,
                "ordered_tick_truth_satisfied": ordered_tick_truth_satisfied,
                "query_after_utc": iso(asof),
                "query_until_utc": iso(expiry),
                "query_row_count": len(tick_rows),
                "source_boundary": "ordered_postdecision_tick_path_truth",
            }
            oracle["source"] = "tick"
            oracle["source_timeframe"] = tick_source.spec.timeframe
            oracle["ordered_tick_truth_satisfied"] = ordered_tick_truth_satisfied
            oracle["ordered_tick_truth_authority"] = ordered_tick_truth_authority
            oracle["ordered_tick_truth_authority_hash_sha256"] = stable_sha256(
                ordered_tick_truth_authority
            )
            oracle = attach_close_mark(
                oracle=oracle,
                rows=tick_rows,
                candidate=candidate,
                expiry=expiry,
            )
            oracle.update(immediate_marketable_fields)
            oracle.update(tick_query.metadata)
            oracle.update(_tick_coverage_fields(gap_reason=None))
            oracle = classify_ordered_path_fill_realism(
                oracle,
                source="tick",
                immediate_marketable_fill=immediate_marketable_fill,
            )
            return oracle, tick_source, tick_rows
        source_gaps.append("tick_path_rows_missing_for_candidate_window")
    m1_source = sources.get("M1")
    m1_day_authority: dict[str, Any] = {
        "trading_day": day,
        "authority_scope": "source_missing",
        "status": "m1_path_source_missing",
        "source_gaps": ["m1_path_source_missing"],
        "diagnostic_fallback_only": True,
    }
    m1_query: PathTruthQuery | None = None
    path_rows: tuple[dict[str, Any], ...] = ()
    if m1_source is not None:
        m1_day_authority = resolved_source_day_authority(m1_source, day)
        m1_query = cached_path_truth_query(
            m1_source,
            after=asof,
            until=expiry,
            query_cache=query_cache,
        )
        if m1_day_authority.get("diagnostic_fallback_only") is not True:
            path_rows = m1_query.rows
        else:
            source_gaps.extend(m1_day_authority.get("source_gaps") or ())
            source_gaps.append(
                "m1_symbol_day_source_authority_diagnostic_only"
            )
    if not path_rows:
        if m1_source is None:
            source_gaps.append("m1_path_source_missing")
        else:
            source_gaps.extend(m1_day_authority.get("source_gaps") or ())
            source_gaps.append("m1_path_rows_missing_or_below_floor_for_candidate_window")
    if not path_rows and sources.get("M15") is not None:
        m15_source = sources["M15"]
        m15_query = cached_path_truth_query(
            m15_source,
            after=asof,
            until=expiry,
            query_cache=query_cache,
        )
        m15_rows = m15_query.rows
        if m15_rows:
            proxy_source_gaps = tuple(
                dict.fromkeys(
                    (
                        *source_gaps,
                        *m15_source.source_gaps,
                        "postdecision_m15_path_proxy_used_because_m1_or_tick_path_unavailable",
                    )
                )
            )
            proxy_sha = stable_sha256(
                {
                    "source": "m15_postdecision_path_proxy",
                    "symbol": m15_source.spec.symbol,
                    "day": day,
                    "asof": iso(asof),
                    "expiry": iso(expiry),
                    "m15_source_sha256": m15_source.sha256,
                    "source_gaps": list(proxy_source_gaps),
                }
            )
            proxy_source = ResolvedSource(
                spec=SourceSpec(
                    symbol=m15_source.spec.symbol,
                    mapped_symbol=m15_source.spec.mapped_symbol,
                    timeframe="M15",
                    path=m15_source.spec.path,
                    source_family=f"{m15_source.spec.source_family}:postdecision_path_proxy",
                    source_broker=m15_source.spec.source_broker,
                    source_role=(
                        "owner_approved_reconstructed_postdecision_m15_path_proxy_"
                        "not_ordered_tick_truth"
                    ),
                    start_utc=m15_source.spec.start_utc,
                    end_utc=m15_source.spec.end_utc,
                    row_count=len(m15_rows),
                    sha256=proxy_sha,
                    export_tool=m15_source.spec.export_tool,
                    manifest_path=m15_source.spec.manifest_path,
                    source_server_redacted=m15_source.spec.source_server_redacted,
                    source_server_hash=m15_source.spec.source_server_hash,
                    source_account_redacted=m15_source.spec.source_account_redacted,
                    source_account_hash=m15_source.spec.source_account_hash,
                    diagnostic_fallback_only=True,
                    source_truth_scope=m15_source.spec.source_truth_scope,
                    not_redacted_account_native=m15_source.spec.not_redacted_account_native,
                    replaces_missing_frozen_path_source=True,
                    broker_lifecycle_truth_satisfied=False,
                    ordered_tick_truth_satisfied=False,
                ),
                rows=m15_rows,
                rows_by_day={day: m15_rows},
                sha256=proxy_sha,
                day_counts={day: len(m15_rows)},
                selected_status=(
                    "selected_m15_postdecision_path_proxy_m1_or_tick_unavailable"
                ),
                min_required_rows_per_day=1,
                source_gaps=proxy_source_gaps,
            )
            oracle = infer_ordered_path_from_m1(
                bars=m15_rows,
                side=str(candidate.get("side") or ""),
                entry_price=safe_float(candidate.get("entry_price")),
                stop_price=safe_float(candidate.get("stop_loss")),
                target_price=safe_float(candidate.get("take_profit_1")),
                asof_utc=iso(asof) or "",
                fill_already_confirmed=immediate_marketable_fill,
                fill_time_utc=immediate_marketable_fill_time,
                **queue_realism_kwargs,
            ).as_dict()
            if oracle.get("terminal_outcome") in {"source_gap", "entry_not_touched_in_post_asof_m1_path"}:
                oracle["terminal_outcome"] = "not_filled_entry_not_touched_before_expiry"
            if str(oracle.get("fill_status") or "").lower() in {"source_gap", ""}:
                oracle["fill_status"] = "not_filled_entry_not_touched_before_expiry"
            if immediate_marketable_fill and str(oracle.get("fill_status") or "").startswith("filled"):
                oracle["fill_status"] = "filled_immediate_marketable_limit_at_decision"
            oracle["source"] = "m15_proxy"
            oracle["source_timeframe"] = "M15"
            oracle["postdecision_path_proxy"] = True
            oracle["postdecision_path_proxy_timeframe"] = "M15"
            oracle["postdecision_path_proxy_reason"] = (
                "m1_or_tick_path_source_missing_or_below_floor"
            )
            oracle["ordered_tick_truth_satisfied"] = False
            oracle["source_gaps"] = list(proxy_source_gaps)
            oracle["m1_symbol_day_source_authority"] = m1_day_authority
            oracle["m1_symbol_day_source_status"] = m1_day_authority.get(
                "status"
            )
            oracle["m1_symbol_day_source_diagnostic_fallback_only"] = (
                m1_day_authority.get("diagnostic_fallback_only") is True
            )
            oracle.update(_tick_coverage_fields(
                gap_reason="tick_path_rows_missing_for_candidate_window"
                if "tick_path_rows_missing_for_candidate_window" in proxy_source_gaps
                else None
            ))
            oracle = attach_close_mark(
                oracle=oracle,
                rows=m15_rows,
                candidate=candidate,
                expiry=expiry,
            )
            oracle.update(immediate_marketable_fields)
            oracle.update(m15_query.metadata)
            oracle["path_lookup_source"] = "m15_proxy"
            oracle = classify_ordered_path_fill_realism(
                oracle,
                source="m15_proxy",
                immediate_marketable_fill=immediate_marketable_fill,
            )
            return oracle, proxy_source, m15_rows
    if not path_rows:
        source_gaps.append("m15_proxy_source_missing_or_empty")
        symbol = str(candidate.get("symbol") or "")
        missing_sha = stable_sha256(
            {
                "source": "missing_postdecision_path_source",
                "symbol": symbol,
                "day": day,
                "asof": iso(asof),
                "expiry": iso(expiry),
                "source_gaps": source_gaps,
            }
        )
        missing_source = ResolvedSource(
            spec=SourceSpec(
                symbol=symbol,
                mapped_symbol=symbol,
                timeframe="M1",
                path=Path(f"missing_postdecision_path_source/{symbol}_{day}_M1"),
                source_family="missing_postdecision_path_source",
                source_broker="FTMO",
                source_role="source_gap_no_m1_m15_or_tick_path_rows",
                row_count=0,
                sha256=missing_sha,
                diagnostic_fallback_only=True,
                source_truth_scope=SOURCE_TRUTH_SCOPE,
                not_redacted_account_native=True,
                broker_lifecycle_truth_satisfied=False,
                ordered_tick_truth_satisfied=False,
            ),
            rows=(),
            rows_by_day={},
            sha256=missing_sha,
            day_counts={day: 0},
            selected_status="postdecision_path_source_gap_no_rows",
            min_required_rows_per_day=1,
            source_gaps=tuple(dict.fromkeys(source_gaps)),
        )
        oracle = infer_ordered_path_from_m1(
            bars=(),
            side=str(candidate.get("side") or ""),
            entry_price=safe_float(candidate.get("entry_price")),
            stop_price=safe_float(candidate.get("stop_loss")),
            target_price=safe_float(candidate.get("take_profit_1")),
            asof_utc=iso(asof) or "",
            fill_already_confirmed=immediate_marketable_fill,
            fill_time_utc=immediate_marketable_fill_time,
            **queue_realism_kwargs,
        ).as_dict()
        oracle["source"] = "source_gap"
        oracle["source_gaps"] = list(missing_source.source_gaps)
        oracle["ordered_tick_truth_satisfied"] = False
        oracle["m1_symbol_day_source_authority"] = m1_day_authority
        oracle["m1_symbol_day_source_status"] = m1_day_authority.get(
            "status"
        )
        oracle["m1_symbol_day_source_diagnostic_fallback_only"] = (
            m1_day_authority.get("diagnostic_fallback_only") is True
        )
        oracle.update(_tick_coverage_fields(
            gap_reason="tick_path_rows_missing_for_candidate_window"
            if "tick_path_rows_missing_for_candidate_window" in missing_source.source_gaps
            else None
        ))
        oracle.update(immediate_marketable_fields)
        oracle = classify_ordered_path_fill_realism(
            oracle,
            source="source_gap",
            immediate_marketable_fill=immediate_marketable_fill,
        )
        return oracle, missing_source, ()
    oracle = infer_ordered_path_from_m1(
        bars=path_rows,
        side=str(candidate.get("side") or ""),
        entry_price=safe_float(candidate.get("entry_price")),
        stop_price=safe_float(candidate.get("stop_loss")),
        target_price=safe_float(candidate.get("take_profit_1")),
        asof_utc=iso(asof) or "",
        fill_already_confirmed=immediate_marketable_fill,
        fill_time_utc=immediate_marketable_fill_time,
        **queue_realism_kwargs,
    ).as_dict()
    if oracle.get("terminal_outcome") in {"source_gap", "entry_not_touched_in_post_asof_m1_path"}:
        oracle["terminal_outcome"] = "not_filled_entry_not_touched_before_expiry"
    if str(oracle.get("fill_status") or "").lower() in {"source_gap", ""}:
        oracle["fill_status"] = "not_filled_entry_not_touched_before_expiry"
    if immediate_marketable_fill and str(oracle.get("fill_status") or "").startswith("filled"):
        oracle["fill_status"] = "filled_immediate_marketable_limit_at_decision"
    oracle["source"] = "m1"
    oracle["ordered_tick_truth_satisfied"] = False
    oracle["m1_symbol_day_source_authority"] = m1_day_authority
    oracle["m1_symbol_day_source_status"] = m1_day_authority.get("status")
    oracle["m1_symbol_day_source_diagnostic_fallback_only"] = (
        m1_day_authority.get("diagnostic_fallback_only") is True
    )
    oracle.update(_tick_coverage_fields(
        gap_reason="tick_path_rows_missing_for_candidate_window"
        if "tick_path_rows_missing_for_candidate_window" in source_gaps
        else None
    ))
    oracle = attach_close_mark(
        oracle=oracle,
        rows=path_rows,
        candidate=candidate,
        expiry=expiry,
    )
    oracle.update(immediate_marketable_fields)
    if m1_query is not None:
        oracle.update(m1_query.metadata)
    oracle["source_gaps"] = list(
        dict.fromkeys([
            *source_gaps,
            *(oracle.get("source_gaps") or ()),
            *(m1_day_authority.get("source_gaps") or ()),
        ])
    )
    oracle = classify_ordered_path_fill_realism(
        oracle,
        source="m1",
        immediate_marketable_fill=immediate_marketable_fill,
    )
    return oracle, m1_source, path_rows


def terminal_event_time(oracle: Mapping[str, Any], *, expiry: datetime) -> datetime:
    if oracle.get("profit_harvest_mfe_capture_replay_exit_final_r_authority") is True:
        for key in (
            "profit_harvest_policy_close_mark_time_utc",
            "profit_harvest_policy_close_time_utc",
            "profit_harvest_policy_exit_time_utc",
        ):
            parsed = parse_utc(oracle.get(key))
            if parsed is not None:
                return parsed
    for key in (
        "close_mark_time_utc",
        "close_time_utc",
        "target_first_touch_utc",
        "stop_first_touch_utc",
    ):
        parsed = parse_utc(oracle.get(key))
        if parsed is not None:
            return parsed
    return expiry


def selected_ultimate_execution_policy_shadow(
    scheduler_packet: Mapping[str, Any],
    candidate_id: str,
    candidate: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    package = scheduler_packet.get("ultimate_candidate_package_shadow")
    package = package if isinstance(package, Mapping) else {}
    policy = package.get("execution_policy_shadow")
    policy = policy if isinstance(policy, Mapping) else {}
    shadow_selected = str(package.get("shadow_selected_candidate_id") or "")
    replay_policy = replay_execution_policy_from_package_candidate_fields(candidate)
    if shadow_selected and shadow_selected != str(candidate_id or ""):
        if replay_policy:
            return {
                "status": (
                    "ultimate_candidate_package_replay_execution_policy_available_"
                    "from_candidate_fields_shadow_selected_other_candidate"
                ),
                "shadow_selected_candidate_id": shadow_selected,
                "execution_policy_shadow": replay_policy,
                "source": "candidate_package_replay_fields",
            }
        return {
            "status": "ultimate_candidate_package_shadow_selected_other_candidate",
            "shadow_selected_candidate_id": shadow_selected,
            "execution_policy_shadow": dict(policy),
        }
    if replay_policy and policy and not shadow_selected:
        return {
            "status": (
                "ultimate_candidate_package_replay_execution_policy_available_"
                "from_candidate_fields_unbound_shadow"
            ),
            "shadow_selected_candidate_id": None,
            "execution_policy_shadow": replay_policy,
            "source": "candidate_package_replay_fields",
            "unbound_package_shadow_policy_present": True,
        }
    if policy:
        return {
            "status": "ultimate_candidate_package_execution_policy_available",
            "shadow_selected_candidate_id": shadow_selected or None,
            "execution_policy_shadow": dict(policy),
        }
    if replay_policy:
        return {
            "status": "ultimate_candidate_package_replay_execution_policy_available_from_candidate_fields",
            "shadow_selected_candidate_id": shadow_selected or None,
            "execution_policy_shadow": replay_policy,
        }
    return {
        "status": "ultimate_candidate_package_execution_policy_available"
        if policy
        else "ultimate_candidate_package_execution_policy_missing",
        "shadow_selected_candidate_id": shadow_selected or None,
        "execution_policy_shadow": dict(policy),
    }


def replay_execution_policy_from_package_candidate_fields(
    candidate: Mapping[str, Any] | None,
) -> dict[str, Any]:
    """Derive the replay-only order policy from package admission fields.

    The ultimate package shadow packet stays live-fail-closed. This fallback is
    only a local replay policy surface so fillability and missed-fill accounting
    can execute when the selected candidate already carries package admission
    evidence.
    """

    if not isinstance(candidate, Mapping):
        return {}
    effective_signal = ultimate_package_effective_signal_fields(candidate)
    admission_count = safe_float(
        first_present(
            candidate.get("ultimate_package_effective_admission_count"),
            effective_signal.get("ultimate_package_effective_admission_count"),
            candidate.get("ultimate_package_admission_sleeve_match_count"),
        )
    )
    allowed = _runtime_bool(
        first_present(
            candidate.get("ultimate_package_effective_source_bound_candidate_use_allowed"),
            effective_signal.get(
                "ultimate_package_effective_source_bound_candidate_use_allowed"
            ),
            candidate.get("ultimate_package_source_bound_candidate_use_allowed"),
            candidate.get("source_bound_package_candidate_use_allowed"),
            candidate.get("package_replay_candidate_use_allowed"),
        ),
        False,
    )
    role = str(candidate.get("ultimate_package_role_disposition") or "")
    if admission_count <= 0.0 and not allowed:
        return {}
    if role in {
        "source_required_hold",
        "redesign_repair_hold",
        "avoid_feature_only_veto",
    }:
        return {}
    reduced = role == "admission_with_avoid_feature_risk_control"
    selector_action = str(candidate.get("selector_action") or "").strip()
    selector_reason = str(candidate.get("selector_reason") or "").strip()
    open_reduced_risk = selector_action == "open-reduced-risk"
    router_refusal_open_reduced = (
        open_reduced_risk
        and (
            "router_refusal" in selector_reason
            or "dynamic_router_refused" in selector_reason
            or "admission_quality_dynamic_router_refused_candidate_use"
            in selector_reason
        )
    )
    reduced = reduced or open_reduced_risk
    architecture = (
        "limit_first_reduced_risk"
        if reduced
        else "limit_first_with_guarded_market_fallback"
    )
    fallback = (
        "guarded_market_reduced_risk_after_cost_proof"
        if open_reduced_risk
        else "guarded_market_after_fillability_cost_proof"
    )
    return {
        "policy_status": "replay_execution_policy_selected_not_live",
        "selected_order_type_architecture": architecture,
        "would_order_entry_policy": architecture,
        "primary_order_type": "limit",
        "would_primary_order_type": "limit",
        "guarded_market_fallback": fallback,
        "would_guarded_market_fallback": fallback,
        "open_reduced_risk_guarded_market_fallback_disabled": False,
        "router_refusal_open_reduced_risk": router_refusal_open_reduced,
        "execution_order_type_policy_selectable": True,
        "missed_fill_opportunity_cost_allowed": True,
        "limit_first_vs_guarded_market_comparison_allowed": True,
        "broker_real_expectancy_claim_allowed": False,
        "source": "candidate_package_replay_fields",
        "local_replay_effect_now": True,
        "runtime_effect_now": False,
        "live_execution_activation_allowed": False,
        "broker_account_order_history_deal_position_mutation_allowed": False,
        "broker_operation": False,
        "paid_api_or_vendor_call": False,
        "order_calls": 0,
    }


def replay_order_type_primitive(
    value: Any,
    *,
    architecture: Any = None,
) -> str:
    text = str(value or "").strip().lower()
    architecture_text = str(architecture or "").strip().lower()
    combined = " ".join(item for item in (text, architecture_text) if item)
    if not combined:
        return ""
    if "skip" in combined or "reject" in combined or "block" in combined:
        return "none"
    if "market" in text and "limit" not in text:
        return "market"
    if "limit" in combined or "pending" in combined or "queue" in combined:
        return "limit"
    if "guarded" in combined or "market" in combined:
        return "market"
    return text if text in {"limit", "market", "none"} else ""


def replay_order_policy_action_alias_fields(
    *,
    order_policy: Any = None,
    order_execution_path: Any = None,
    effective_order_type: Any = None,
    primary_order_type: Any = None,
    action: Any = None,
) -> dict[str, Any]:
    policy = first_present(order_policy, primary_order_type, effective_order_type)
    execution_path = str(order_execution_path or "").strip() or None
    effective_type = str(effective_order_type or "").strip() or None
    primary_type = str(primary_order_type or "").strip() or None
    action_text = first_present(action, execution_path)
    normalized_action = normalize_scheduler_action_intent(action_text)
    if normalized_action in (None, "") and action_text not in (None, ""):
        normalized_action = str(action_text).strip() or None
    return {
        "order_policy": str(policy).strip() if policy not in (None, "") else None,
        "action": normalized_action,
        "order_policy_action": execution_path,
        "order_execution_action": execution_path,
        "order_effective_action": effective_type,
        "order_primary_action": primary_type,
    }


def selected_execution_policy_alias_fields(
    *,
    order_policy: Mapping[str, Any] | None,
    selected_policy_replay_exit: Mapping[str, Any] | None,
    dynamic_geometry_policy: Any = None,
) -> dict[str, Any]:
    policy = order_policy if isinstance(order_policy, Mapping) else {}
    nested_policy = policy.get("package_execution_policy")
    nested_policy = nested_policy if isinstance(nested_policy, Mapping) else {}
    seed = {**nested_policy, **policy}
    architecture = first_present(
        seed.get("package_execution_policy_order_entry"),
        seed.get("selected_order_type_architecture"),
        seed.get("would_order_entry_policy"),
        seed.get("order_entry_architecture"),
    )
    primary_order_type = replay_order_type_primitive(
        first_present(
            seed.get("primary_order_type"),
            seed.get("package_execution_policy_primary_order_type"),
            seed.get("would_primary_order_type"),
        ),
        architecture=architecture,
    )
    fallback = first_present(
        seed.get("package_execution_policy_fallback"),
        seed.get("would_guarded_market_fallback"),
        seed.get("guarded_market_fallback"),
    )
    policy_hash = first_present(
        seed.get("policy_hash_sha256"),
        seed.get("replay_order_policy_hash_sha256"),
        seed.get("counterfactual_order_policy_hash_sha256"),
    )
    if not policy_hash and seed:
        policy_hash = stable_sha256(
            {
                "architecture": architecture,
                "primary_order_type": primary_order_type,
                "fallback": fallback,
                "policy": seed,
            }
        )
    exit_bound = bool(
        selected_policy_replay_exit
        and selected_policy_replay_exit.get("final_r_authority")
    )
    dynamic_policy = str(dynamic_geometry_policy or "").strip() or None
    if exit_bound:
        status = "selected_execution_policy_replay_exit_bound"
        exit_status = "path_exit_replay_bound"
    elif selected_policy_replay_exit and str(
        selected_policy_replay_exit.get("final_r_authority_status") or ""
    ).startswith("selected_policy_replay_unimplemented"):
        status = "selected_execution_policy_replay_unimplemented"
        exit_status = str(
            selected_policy_replay_exit.get("final_r_authority_status")
        )
    elif selected_policy_replay_exit:
        status = "selected_execution_policy_replay_not_authoritative"
        exit_status = str(
            selected_policy_replay_exit.get("final_r_authority_status")
            or selected_policy_replay_exit.get("replay_status")
            or "selected_policy_replay_not_authoritative"
        )
    elif seed:
        status = "selected_execution_policy_available"
        exit_status = (
            "path_exit_replay_not_applicable_for_dynamic_geometry_policy"
            if dynamic_policy and dynamic_policy != "partial_be_runner"
            else "path_exit_replay_not_bound"
        )
    else:
        status = "selected_execution_policy_missing"
        exit_status = "path_exit_replay_policy_missing"
    return {
        "selected_execution_policy_status": status,
        "selected_execution_policy_primary_order_type": primary_order_type,
        "selected_execution_policy_architecture": architecture,
        "selected_execution_policy_fallback": fallback,
        "selected_execution_policy_hash_sha256": policy_hash,
        "selected_execution_policy_dynamic_geometry_policy": dynamic_policy,
        "selected_execution_policy_exit_replay_status": exit_status,
    }


def selected_policy_replay_ledger_fields(
    selected_policy_replay_exit: Mapping[str, Any] | None,
) -> dict[str, Any]:
    replay = (
        selected_policy_replay_exit
        if isinstance(selected_policy_replay_exit, Mapping)
        else {}
    )
    bound = bool(replay and replay.get("final_r_authority"))
    raw_status = replay.get("replay_status")
    ledger_status = (
        "diagnostic_replayed_not_authoritative"
        if replay and not bound and raw_status == "replayed"
        else raw_status
    )
    quality_gate_fields = {
        key: replay.get(key) for key in SELECTED_POLICY_EXECUTABLE_QUALITY_TRACE_KEYS
    }
    prefixed_quality_gate_fields = {
        f"selected_execution_policy_replay_{key}": replay.get(key)
        for key in SELECTED_POLICY_EXECUTABLE_QUALITY_TRACE_KEYS
    }
    return {
        "selected_execution_policy_replay_bound": bound,
        "selected_execution_policy_replay_status": ledger_status,
        "selected_execution_policy_replay_raw_status": raw_status,
        "selected_execution_policy_replay_policy_name": replay.get("policy_name")
        or replay.get("selected_policy"),
        "selected_execution_policy_replay_final_r": replay.get("final_r"),
        "selected_execution_policy_replay_ordered_tick_final_r_authority": replay.get(
            "ordered_tick_final_r_authority"
        ),
        "selected_execution_policy_replay_m1_proxy_replay_authority": replay.get(
            "m1_proxy_replay_authority"
        ),
        "selected_execution_policy_replay_headline_result_authority": replay.get(
            "headline_result_authority"
        ),
        "selected_execution_policy_replay_headline_result_authority_status": replay.get(
            "headline_result_authority_status"
        ),
        "selected_execution_policy_replay_exit_reason": replay.get("exit_reason"),
        "selected_execution_policy_replay_exit_time_utc": replay.get("exit_time_utc"),
        "selected_execution_policy_replay_observation_count": replay.get(
            "observation_count"
        ),
        "selected_execution_policy_fill_bar_observation_allowed": replay.get(
            "fill_bar_observation_allowed"
        ),
        "selected_execution_policy_ordered_tick_truth_satisfied": first_present(
            replay.get("ordered_tick_truth_satisfied_for_selected_policy_replay"),
            replay.get("ordered_tick_truth_satisfied"),
        ),
        "selected_execution_policy_replay_source_gap_reason": replay.get(
            "source_gap_reason"
        ),
        "selected_execution_policy_replay_source_boundary": replay.get(
            "source_boundary"
        ),
        "selected_execution_policy_replay_final_r_authority_status": replay.get(
            "final_r_authority_status"
        ),
        **quality_gate_fields,
        **prefixed_quality_gate_fields,
    }


def split_selected_policy_replay_terminal_and_order_event_metadata(
    metadata: Mapping[str, Any],
    selected_policy_replay_exit: Mapping[str, Any] | None,
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Keep selected-policy terminal R authority off order-event rows only."""

    terminal_metadata = dict(metadata)
    order_event_metadata = dict(metadata)
    if (
        isinstance(selected_policy_replay_exit, Mapping)
        and selected_policy_replay_exit.get("final_r_authority") is True
    ):
        order_event_metadata.update(
            {
                "selected_execution_policy_replay_bound": False,
                "selected_execution_policy_replay_status": (
                    "order_event_diagnostic_not_terminal_r_authority"
                ),
                "selected_execution_policy_replay_final_r": None,
                "selected_execution_policy_replay_ordered_tick_final_r_authority": False,
                "selected_execution_policy_replay_m1_proxy_replay_authority": False,
                "selected_execution_policy_replay_headline_result_authority": False,
                "selected_execution_policy_replay_headline_result_authority_status": (
                    "order_event_no_terminal_r_authority_trade_or_exit_row_only"
                ),
                "selected_execution_policy_replay_final_r_authority_status": (
                    "order_event_no_terminal_r_authority_trade_or_exit_row_only"
                ),
                "selected_execution_policy_replay_order_event_diagnostic": (
                    selected_policy_replay_exit
                ),
                "selected_execution_policy_status": (
                    "selected_execution_policy_order_event_terminal_r_diagnostic"
                ),
                "selected_execution_policy_exit_replay_status": (
                    "order_event_no_terminal_r_authority_trade_or_exit_row_only"
                ),
            }
        )
    return terminal_metadata, order_event_metadata


def terminal_r_authority_ledger_fields(oracle: Mapping[str, Any]) -> dict[str, Any]:
    source = str(oracle.get("source") or oracle.get("close_mark_source") or "").lower()
    fill_status = str(oracle.get("fill_status") or "").lower()
    ordered_tick_truth = source == "tick" and oracle.get("ordered_tick_truth_satisfied") is True
    m1_proxy = source == "m1"
    filled = fill_status.startswith("filled")
    entry_fill_executable = bool(
        filled
        and first_present(
            oracle.get("entry_fill_executable"),
            oracle.get("fill_realism_executable"),
            True,
        )
        is not False
    )
    terminal_r_scoreable = bool(
        entry_fill_executable
        and first_present(oracle.get("terminal_r_scoreable"), True) is not False
    )
    if not entry_fill_executable:
        status = "not_filled_no_terminal_r_authority"
    elif not terminal_r_scoreable:
        status = str(
            oracle.get("terminal_r_scoreability_status")
            or "entry_fill_executable_terminal_r_unscoreable"
        )
    elif ordered_tick_truth:
        status = "ordered_tick_truth_terminal_r_authority"
    elif m1_proxy:
        status = "m1_proxy_replay_terminal_r_authority_not_final_live_proof"
    else:
        status = "terminal_r_source_gap_not_final_live_proof"
    headline_status = (
        "ordered_tick_final_r_headline_authority"
        if terminal_r_scoreable and ordered_tick_truth
        else "entry_fill_executable_terminal_r_unscoreable"
        if entry_fill_executable and not terminal_r_scoreable
        else "m1_proxy_replay_not_headline_authority_ordered_tick_required"
        if terminal_r_scoreable and m1_proxy
        else "not_headline_final_r_authority"
    )
    return {
        "terminal_r_source": source or None,
        "terminal_r_authority_status": status,
        "entry_fill_executable": entry_fill_executable,
        "terminal_r_scoreable": terminal_r_scoreable,
        "terminal_r_scoreability_status": oracle.get(
            "terminal_r_scoreability_status"
        ) or status,
        "terminal_r_scoreability_reason": oracle.get(
            "terminal_r_scoreability_reason"
        ),
        "terminal_r_replay_authority": terminal_r_scoreable and ordered_tick_truth,
        "terminal_r_proxy_replay_authority": terminal_r_scoreable and m1_proxy,
        "terminal_r_ordered_tick_final_live_authority": (
            terminal_r_scoreable and ordered_tick_truth
        ),
        "ordered_tick_truth_satisfied_for_terminal_r": ordered_tick_truth,
        "ordered_tick_final_r_authority": terminal_r_scoreable and ordered_tick_truth,
        "m1_proxy_replay_authority": terminal_r_scoreable and m1_proxy,
        "headline_result_authority": terminal_r_scoreable and ordered_tick_truth,
        "headline_result_authority_status": headline_status,
        "final_r_authority": terminal_r_scoreable and ordered_tick_truth,
        "legacy_final_r_authority_semantics": (
            "final_r_authority_is_ordered_tick_terminal_authority_only"
        ),
    }


def path_oracle_provenance_ledger_fields(
    *,
    oracle: Mapping[str, Any],
    path_source: ResolvedSource | None = None,
    path_rows: Sequence[Mapping[str, Any]] | None = None,
    prefix: str = "",
) -> dict[str, Any]:
    """Expose the concrete post-decision price-path source on executable rows."""

    source_name = str(
        first_present(
            oracle.get("source"),
            oracle.get("path_lookup_source"),
            path_source.spec.timeframe.lower() if path_source is not None else None,
        )
        or ""
    ).strip()
    source_name_lower = source_name.lower()
    timeframe = first_present(
        oracle.get("path_index_timeframe"),
        oracle.get("source_timeframe"),
        path_source.spec.timeframe if path_source is not None else None,
    )
    source_path = first_present(
        oracle.get("path_index_source_path"),
        oracle.get("source_path"),
        str(path_source.spec.path) if path_source is not None else None,
    )
    source_sha256 = first_present(
        oracle.get("path_index_source_sha256"),
        oracle.get("source_sha256"),
        path_source.sha256 if path_source is not None else None,
    )
    source_gaps = list(oracle.get("source_gaps") or [])
    m1_day_authority = oracle.get("m1_symbol_day_source_authority")
    m1_day_authority = (
        dict(m1_day_authority)
        if isinstance(m1_day_authority, Mapping)
        else None
    )
    if m1_day_authority is not None:
        source_gaps.extend(list(m1_day_authority.get("source_gaps") or ()))
    elif path_source is not None:
        source_gaps.extend(list(path_source.source_gaps or ()))
    source_gaps = list(dict.fromkeys(str(item) for item in source_gaps if str(item or "").strip()))
    ordered_tick_truth = bool(
        source_name_lower == "tick"
        and oracle.get("ordered_tick_truth_satisfied") is True
        and (
            path_source is None
            or path_source.spec.ordered_tick_truth_satisfied is True
        )
    )
    path_row_count = (
        len(path_rows)
        if path_rows is not None
        else first_present(oracle.get("path_row_count"), oracle.get("path_index_rows_returned"))
    )
    fields = {
        "path_source": source_name_lower or None,
        "path_source_timeframe": timeframe,
        "path_index_timeframe": timeframe,
        "path_index_source_path": source_path,
        "path_index_source_sha256": source_sha256,
        "path_index_rows_returned": first_present(
            oracle.get("path_index_rows_returned"),
            path_row_count,
        ),
        "path_row_count": path_row_count,
        "path_source_selected_status": (
            path_source.selected_status if path_source is not None else None
        ),
        "path_source_role": (
            path_source.spec.source_role if path_source is not None else None
        ),
        "path_source_truth_scope": first_present(
            oracle.get("source_truth_scope"),
            path_source.spec.source_truth_scope if path_source is not None else None,
        ),
        "path_source_gaps": source_gaps,
        "source_gaps": source_gaps,
        "m1_symbol_day_source_authority": m1_day_authority,
        "m1_symbol_day_source_status": oracle.get(
            "m1_symbol_day_source_status"
        ),
        "m1_symbol_day_source_diagnostic_fallback_only": oracle.get(
            "m1_symbol_day_source_diagnostic_fallback_only"
        ),
        "postdecision_path_proxy": bool(oracle.get("postdecision_path_proxy")),
        "postdecision_path_proxy_timeframe": oracle.get("postdecision_path_proxy_timeframe"),
        "postdecision_path_proxy_reason": oracle.get("postdecision_path_proxy_reason"),
        "ordered_tick_truth_satisfied": ordered_tick_truth,
        "ordered_tick_truth_oracle_satisfied": (
            oracle.get("ordered_tick_truth_satisfied") is True
        ),
        "ordered_tick_truth_source_satisfied": (
            path_source.spec.ordered_tick_truth_satisfied is True
            if path_source is not None
            else None
        ),
        "ordered_tick_truth_authority": oracle.get(
            "ordered_tick_truth_authority"
        ),
        "ordered_tick_truth_authority_hash_sha256": oracle.get(
            "ordered_tick_truth_authority_hash_sha256"
        ),
        "tick_source_available": oracle.get("tick_source_available"),
        "tick_query_rows_returned": oracle.get("tick_query_rows_returned"),
        "tick_source_path": oracle.get("tick_source_path"),
        "tick_source_start_utc": oracle.get("tick_source_start_utc"),
        "tick_source_end_utc": oracle.get("tick_source_end_utc"),
        "tick_window_covers_candidate": oracle.get("tick_window_covers_candidate"),
        "tick_gap_reason": oracle.get("tick_gap_reason"),
        "terminal_r_path_authority": terminal_r_authority_ledger_fields(
            {
                **dict(oracle),
                "source": source_name_lower or oracle.get("source"),
                "ordered_tick_truth_satisfied": ordered_tick_truth,
            }
        ).get("terminal_r_authority_status"),
        **fill_realism_ledger_fields(oracle),
    }
    if not prefix:
        return fields
    return {f"{prefix}{key}": value for key, value in fields.items()}


def counterfactual_order_policy_ledger_fields(
    *,
    candidate: Mapping[str, Any],
    packets: Mapping[str, Any],
    scheduler_packet: Mapping[str, Any],
    scheduler_option: Mapping[str, Any] | None = None,
    oracle: Mapping[str, Any] | None = None,
    expiry_utc: str | None = None,
) -> dict[str, Any]:
    candidate_id = str(candidate.get("candidate_id") or "")
    scheduler_option = scheduler_option if isinstance(scheduler_option, Mapping) else {}
    selected_components = (
        scheduler_option.get("score_components")
        if isinstance(scheduler_option.get("score_components"), Mapping)
        else {}
    )
    selected_inputs: dict[str, Any] = {}
    for generic_surface in (
        candidate.get("candidate_decision_inputs"),
        scheduler_option.get("candidate_decision_inputs"),
        selected_components.get("candidate_decision_inputs"),
    ):
        if isinstance(generic_surface, Mapping):
            selected_inputs.update(generic_surface)
    for scheduler_surface in (
        candidate.get("scheduler_candidate_decision_inputs"),
        selected_components.get("scheduler_candidate_decision_inputs"),
        scheduler_option.get("scheduler_candidate_decision_inputs"),
    ):
        if isinstance(scheduler_surface, Mapping):
            selected_inputs.update(scheduler_surface)
    package_policy = selected_ultimate_execution_policy_shadow(
        scheduler_packet,
        candidate_id,
        candidate=candidate,
    )
    execution_policy = package_policy.get("execution_policy_shadow")
    execution_policy = execution_policy if isinstance(execution_policy, Mapping) else {}
    order_entry_architecture = first_present(
        execution_policy.get("would_order_entry_policy"),
        execution_policy.get("selected_order_type_architecture"),
        candidate.get("selected_order_type_architecture"),
        candidate.get("package_execution_policy_order_entry"),
    )
    fallback_text = str(
        first_present(
            execution_policy.get("would_guarded_market_fallback"),
            execution_policy.get("guarded_market_fallback"),
            candidate.get("guarded_market_fallback"),
            candidate.get("package_execution_policy_fallback"),
        )
        or ""
    )
    primary_order_type = replay_order_type_primitive(
        first_present(
            execution_policy.get("would_primary_order_type"),
            execution_policy.get("primary_order_type"),
            candidate.get("primary_order_type"),
            "limit" if order_entry_architecture else "none",
        ),
        architecture=order_entry_architecture,
    )
    if not primary_order_type:
        primary_order_type = "none"
    fallback_configured = "guarded_market" in fallback_text
    policy_hash = stable_sha256(
        {
            "candidate_id": candidate_id,
            "package_policy_status": package_policy.get("status"),
            "execution_policy": execution_policy,
            "order_entry_architecture": order_entry_architecture,
            "primary_order_type": primary_order_type,
            "fallback_text": fallback_text,
        }
    )
    oracle = oracle if isinstance(oracle, Mapping) else {}
    selected_policy_aliases = selected_execution_policy_alias_fields(
        order_policy={
            **execution_policy,
            "status": (
                "package_execution_policy_available"
                if primary_order_type != "none"
                else "package_execution_policy_missing_or_not_orderable"
            ),
            "policy_hash_sha256": policy_hash,
            "package_execution_policy_order_entry": order_entry_architecture,
            "primary_order_type": primary_order_type,
            "package_execution_policy_fallback": fallback_text,
        },
        selected_policy_replay_exit=None,
        dynamic_geometry_policy=candidate.get("dynamic_geometry_policy"),
    )
    return {
        "counterfactual_order_policy_scored": True,
        "counterfactual_order_policy_status": (
            "package_execution_policy_available"
            if primary_order_type != "none"
            else "package_execution_policy_missing_or_not_orderable"
        ),
        "counterfactual_order_policy_package_status": package_policy.get("status"),
        "counterfactual_order_policy_hash_sha256": policy_hash,
        "selected_order_type_architecture": order_entry_architecture,
        "primary_order_type": primary_order_type,
        "effective_order_type": primary_order_type,
        "effective_order_type_status": "counterfactual_not_ordered_policy_plan",
        "order_execution_path": "counterfactual_not_selected_policy_plan",
        "limit_first_fill_status": oracle.get("fill_status"),
        "limit_first_terminal_outcome": oracle.get("terminal_outcome"),
        "limit_first_fill_time_utc": oracle.get("fill_time_utc"),
        "limit_first_entry_price": oracle.get("fill_price"),
        "limit_first_close_time_utc": first_present(
            oracle.get("close_time_utc"),
            oracle.get("close_mark_time_utc"),
            oracle.get("exit_time_utc"),
        ),
        "limit_first_close_mark_r": oracle.get("close_mark_r"),
        "limit_first_close_mark_source": first_present(
            oracle.get("close_mark_source"),
            oracle.get("source"),
        ),
        "limit_first_expiry_utc": expiry_utc,
        "counterfactual_order_fill_status": oracle.get("fill_status"),
        "counterfactual_order_terminal_outcome": oracle.get("terminal_outcome"),
        "counterfactual_order_fill_time_utc": oracle.get("fill_time_utc"),
        "counterfactual_order_fill_price": oracle.get("fill_price"),
        "counterfactual_order_close_time_utc": first_present(
            oracle.get("close_time_utc"),
            oracle.get("close_mark_time_utc"),
            oracle.get("exit_time_utc"),
        ),
        "counterfactual_order_close_mark_r": oracle.get("close_mark_r"),
        "counterfactual_order_close_mark_source": first_present(
            oracle.get("close_mark_source"),
            oracle.get("source"),
        ),
        "guarded_market_fallback_configured": fallback_configured,
        "guarded_market_fallback_attempted": False,
        "guarded_market_fallback_status": "not_attempted_candidate_not_selected",
        "guarded_market_fallback_reason": (
            "counterfactual_candidate_not_selected_or_not_ordered"
        ),
        "guarded_market_fallback_reasons": [
            "counterfactual_candidate_not_selected_or_not_ordered"
        ],
        "guarded_market_fallback_policy_hash_sha256": policy_hash,
        "guarded_market_fallback_applied": False,
        "guarded_market_fallback_extra_cost_r": 0.0,
        "guarded_market_fallback_used_only_predecision_fields": True,
        "fallback_eligibility_used_only_predecision_fields": True,
        "fallback_execution_used_elapsed_market_path": False,
        "replay_order_policy_hash_sha256": policy_hash,
        "replay_order_fillability_policy_v1": dict(execution_policy),
        **selected_policy_aliases,
        "entry_price": candidate.get("entry_price"),
        "stop_loss": candidate.get("stop_loss"),
        "take_profit_1": candidate.get("take_profit_1"),
        "risk_reward_ratio": first_present(
            candidate.get("risk_reward_ratio"),
            candidate.get("rr"),
        ),
        "counterfactual_fill_probability": first_present(
            selected_inputs.get("fill_probability"),
            scheduler_option.get("fill_probability"),
            packets.get("fill_probability"),
            candidate.get("fill_probability"),
        ),
        "counterfactual_source_completeness": first_present(
            selected_inputs.get("source_completeness"),
            scheduler_option.get("source_completeness"),
            packets.get("source_completeness"),
            candidate.get("source_completeness"),
        ),
    }


