def guarded_market_fallback_lifetime_window(
    *,
    asof: datetime,
    expiry: datetime,
    fallback_delay_minutes: float,
) -> dict[str, Any]:
    fallback_unclamped_time = asof + timedelta(minutes=fallback_delay_minutes)
    latest_usable_time = expiry - timedelta(minutes=1)
    window_exhausted = latest_usable_time <= asof
    fallback_time = (
        None
        if window_exhausted
        else min(fallback_unclamped_time, latest_usable_time)
    )
    return {
        "fallback_time": fallback_time,
        "fallback_unclamped_time": fallback_unclamped_time,
        "latest_usable_time": latest_usable_time,
        "fallback_time_clamped_inside_order_lifetime": bool(
            fallback_time is not None and fallback_time != fallback_unclamped_time
        ),
        "fallback_window_exhausted_by_expiry": window_exhausted,
    }


def terminal_guarded_market_fallback_proof_fields(
    row: Mapping[str, Any],
) -> dict[str, Any]:
    """Prove, but never execute, guarded fallback for a selected expired order."""

    candidate_id = str(row.get("candidate_id") or "").strip()
    selected_candidate_id = str(row.get("selected_candidate_id") or "").strip()
    selected_candidate_ids = row.get("selected_candidate_ids")
    selected_candidate_ids = (
        [str(item) for item in selected_candidate_ids]
        if isinstance(selected_candidate_ids, Sequence)
        and not isinstance(selected_candidate_ids, (str, bytes, bytearray))
        else []
    )
    selected_expired_order = bool(
        row.get("order_status") == "expired_unfilled"
        and candidate_id
        and (
            selected_candidate_id == candidate_id
            or candidate_id in selected_candidate_ids
        )
    )
    if not selected_expired_order:
        return {}

    policy = row.get("replay_order_fillability_policy_v1")
    policy = policy if isinstance(policy, Mapping) else {}
    signed_attribution = package_new_entry_authority_attribution_fields(row)
    signed_payload = signed_attribution.get("package_new_entry_authority_payload")
    signed_payload = (
        signed_payload
        if signed_attribution.get("package_new_entry_authority_valid") is True
        and isinstance(signed_payload, Mapping)
        else {}
    )
    signed_projection_conflicts: set[str] = set()
    for payload_field, row_field in (
        ("pretrade_cost_packet_status", "pretrade_cost_packet_status"),
        ("cost_source_gap_status", "cost_source_gap_status"),
        ("cost_authority", "cost_authority"),
        (
            "candidate_cost_r_fallback_is_authority",
            "candidate_cost_r_fallback_is_authority",
        ),
        ("source_completeness", "source_completeness"),
        ("source_completeness_status", "source_completeness_status"),
        (
            "package_replay_order_executable_candidate_use_allowed",
            "package_replay_order_executable_candidate_use_allowed",
        ),
    ):
        payload_value = signed_payload.get(payload_field)
        row_value = row.get(row_field)
        if payload_value in (None, "") or row_value in (None, ""):
            continue
        if package_new_entry_authority_payload_hash_sha256(
            {"value": payload_value}
        ) != package_new_entry_authority_payload_hash_sha256({"value": row_value}):
            signed_projection_conflicts.add(payload_field)
    if row.get("package_new_entry_authority_valid") is not True:
        signed_projection_conflicts.add("package_new_entry_authority_valid")
    decision_time = str(
        first_present(row.get("decision_time_utc"), row.get("created_time_utc")) or ""
    ).strip()
    candidate_instance_key = str(
        first_present(
            row.get("canonical_replay_candidate_instance_key"),
            row.get(CANDIDATE_OCCURRENCE_KEY_FIELD),
            row.get("source_bound_replay_candidate_instance_key"),
            risk_finalizer_probe_instance_key(candidate_id, decision_time),
        )
        or ""
    ).strip()
    canonical_instance_key = str(
        row.get("canonical_replay_candidate_instance_key") or ""
    ).strip()
    signed_candidate_id = str(
        signed_payload.get("candidate_id") or ""
    ).strip()
    signed_decision_time = str(
        signed_payload.get("decision_time_utc") or ""
    ).strip()
    signed_instance_key = str(
        first_present(
            signed_payload.get("canonical_replay_candidate_instance_key"),
            signed_payload.get("source_bound_replay_candidate_instance_key"),
        )
        or ""
    ).strip()
    exact_instance_binding = bool(
        candidate_instance_key
        and canonical_instance_key == candidate_instance_key
        and signed_candidate_id == candidate_id
        and signed_decision_time == decision_time
        and signed_instance_key == candidate_instance_key
    )

    cost_status = str(
        signed_payload.get("pretrade_cost_packet_status") or ""
    ).upper()
    cost_gap_status = str(signed_payload.get("cost_source_gap_status") or "")
    cost_authority = str(signed_payload.get("cost_authority") or "")
    cost_passed = bool(
        cost_status in {"PASSED", "PASS", "OK"}
        and cost_gap_status == "source_bound_cost_authority_present"
        and cost_authority == "broker_calibrated_replay_cost"
        and not _runtime_bool(
            signed_payload.get("candidate_cost_r_fallback_is_authority"),
            False,
        )
        and not signed_projection_conflicts.intersection(
            {
                "pretrade_cost_packet_status",
                "cost_source_gap_status",
                "cost_authority",
                "candidate_cost_r_fallback_is_authority",
            }
        )
    )

    source_completeness = safe_float(
        signed_payload.get("source_completeness"),
        math.nan,
    )
    source_status = str(
        signed_payload.get("source_completeness_status") or ""
    ).lower()
    quality_sources = signed_payload.get("candidate_decision_quality_field_sources")
    quality_sources = quality_sources if isinstance(quality_sources, Mapping) else {}
    quality_source_boundary = str(
        first_present(
            signed_payload.get("candidate_decision_quality_source_boundary"),
            row.get("candidate_decision_quality_source_boundary"),
            row.get("runtime_quality_contract_quality_source_boundary"),
            row.get("source_boundary"),
        )
        or ""
    )
    source_complete = bool(
        math.isfinite(source_completeness)
        and source_completeness >= 0.95
        and not _runtime_bool(
            first_present(
                (
                    signed_payload.get(
                        "candidate_decision_quality_degraded_default_flags"
                    )
                    or {}
                ).get("source_completeness")
                if isinstance(
                    signed_payload.get(
                        "candidate_decision_quality_degraded_default_flags"
                    ),
                    Mapping,
                )
                else None,
                row.get("source_completeness_missing_degraded_default_applied"),
            ),
            False,
        )
        and not any(
            token in source_status
            for token in (
                "missing",
                "degraded",
                "gap",
                "source_required",
                "incomplete",
                "prospective_capture",
            )
        )
        and bool(quality_sources)
        and bool(quality_source_boundary)
        and "outcome" not in quality_source_boundary.lower().replace("no_outcome", "")
        and not signed_projection_conflicts.intersection(
            {"source_completeness", "source_completeness_status"}
        )
    )

    signed_hash = str(
        signed_attribution.get("package_new_entry_authority_hash_sha256") or ""
    ).strip()
    signed_route_valid = bool(
        signed_attribution.get("package_new_entry_authority_valid") is True
        and signed_payload.get("uses_outcome_fields") is False
        and signed_hash
        and exact_instance_binding
        and signed_payload.get(
            "package_replay_order_executable_candidate_use_allowed"
        )
        is True
        and row.get("risk_finalizer_executable_finalized") is True
        and not signed_projection_conflicts
    )

    created_time = parse_utc(
        first_present(row.get("created_time_utc"), row.get("decision_time_utc"))
    )
    expiry_time = parse_utc(
        first_present(
            row.get("limit_first_expiry_utc"),
            row.get("expiry_utc"),
            row.get("event_time_utc"),
        )
    )
    fallback_time = parse_utc(
        first_present(
            policy.get("fallback_decision_time_utc"),
            row.get("guarded_market_fallback_decision_time_utc"),
        )
    )
    fallback_inside_order_lifetime = bool(
        created_time
        and expiry_time
        and fallback_time
        and created_time <= fallback_time < expiry_time
        and policy.get("fallback_window_exhausted_by_expiry") is not True
    )

    route_session = str(
        first_present(row.get("route_session"), policy.get("route_session")) or ""
    ).strip()
    off_session = bool(
        policy.get("off_configured_session") is True
        or route_session
        in {
            "off_configured",
            "off_configured_session",
            "off_kz",
            "off_kz_broad",
        }
    )
    off_session_config_allowed = bool(
        policy.get("off_configured_session_guarded_market_fallback_allowed") is True
    )
    authority_family = str(
        signed_payload.get("authority_family") or ""
    ).lower()
    off_session_signed_authority_granted = bool(
        signed_route_valid and "off_session" in authority_family
    )
    off_session_authorized = bool(
        not off_session
        or (
            off_session_config_allowed
            and off_session_signed_authority_granted
            and signed_route_valid
        )
    )

    policy_reasons = policy.get("reasons")
    policy_reasons = (
        [str(item) for item in policy_reasons if item not in (None, "")]
        if isinstance(policy_reasons, Sequence)
        and not isinstance(policy_reasons, (str, bytes, bytearray))
        else []
    )
    policy_reason = str(
        first_present(
            policy.get("reason"),
            row.get("guarded_market_fallback_reason"),
        )
        or ""
    ).strip()
    if policy.get("status") != "eligible" and policy_reason:
        policy_reasons = [policy_reason, *policy_reasons]
    blockers = list(dict.fromkeys(policy_reasons))
    if not cost_passed:
        blockers.append("terminal_fallback_broker_cost_authority_not_passed")
    if not source_complete:
        blockers.append("terminal_fallback_source_incomplete_or_provenance_missing")
    if not signed_route_valid:
        blockers.append("terminal_fallback_signed_route_authority_invalid")
    if not fallback_inside_order_lifetime:
        blockers.append("terminal_fallback_time_outside_order_lifetime")
    if off_session and not off_session_authorized:
        blockers.append(
            "off_session_signed_fallback_authority_not_explicitly_granted"
        )
    blockers = list(dict.fromkeys(blockers))
    eligible = not blockers
    primary_blocker = blockers[0] if blockers else None
    blocker_text = str(primary_blocker or "").lower()
    blocker_family = (
        "cost_authority"
        if "cost" in blocker_text
        else "exact_missing_source"
        if "source" in blocker_text
        else "off_session_authority"
        if "off_session" in blocker_text or "off_configured_session" in blocker_text
        else "signed_route_authority"
        if "signed" in blocker_text or "authority" in blocker_text
        else "lifecycle_time"
        if "lifetime" in blocker_text or "expiry" in blocker_text
        else "fill_or_geometry_policy"
    )
    return {
        "terminal_guarded_market_fallback_proof_schema_version": (
            "terminal_guarded_market_fallback_proof_v1"
        ),
        "terminal_guarded_market_fallback_proof_status": (
            "eligible_counterfactual_materialized"
            if eligible
            else "blocked_exact_reason_preserved"
        ),
        "terminal_guarded_market_fallback_counterfactual_eligible": eligible,
        "terminal_guarded_market_fallback_counterfactual_materialized": eligible,
        "terminal_guarded_market_fallback_executed": False,
        "terminal_guarded_market_fallback_broker_mutation_allowed": False,
        "terminal_guarded_market_fallback_blocker": primary_blocker,
        "terminal_guarded_market_fallback_blockers": blockers,
        "terminal_guarded_market_fallback_blocker_family": blocker_family,
        "terminal_guarded_market_fallback_candidate_id": candidate_id,
        "terminal_guarded_market_fallback_decision_time_utc": decision_time,
        "terminal_guarded_market_fallback_candidate_instance_key": (
            candidate_instance_key
        ),
        "terminal_guarded_market_fallback_exact_instance_binding": (
            exact_instance_binding
        ),
        "terminal_guarded_market_fallback_cost_passed": cost_passed,
        "terminal_guarded_market_fallback_source_complete": source_complete,
        "terminal_guarded_market_fallback_signed_route_valid": signed_route_valid,
        "terminal_guarded_market_fallback_fallback_time_utc": (
            iso(fallback_time) if fallback_time else None
        ),
        "terminal_guarded_market_fallback_created_time_utc": (
            iso(created_time) if created_time else None
        ),
        "terminal_guarded_market_fallback_expiry_time_utc": (
            iso(expiry_time) if expiry_time else None
        ),
        "terminal_guarded_market_fallback_time_inside_order_lifetime": (
            fallback_inside_order_lifetime
        ),
        "terminal_guarded_market_fallback_off_session": off_session,
        "terminal_guarded_market_fallback_off_session_config_allowed": (
            off_session_config_allowed
        ),
        "terminal_guarded_market_fallback_off_session_signed_authority_granted": (
            off_session_signed_authority_granted
        ),
        "terminal_guarded_market_fallback_source_boundary": (
            "selected_expired_order_terminal_counterfactual_predecision_authority_"
            "plus_elapsed_lifetime_no_broker_execution"
        ),
        "terminal_guarded_market_fallback_uses_future_or_terminal_outcome_for_eligibility": (
            False
        ),
        "terminal_guarded_market_fallback_uses_elapsed_path_to_fallback_for_eligibility": (
            policy.get("fallback_decision_used_elapsed_market_path") is True
        ),
    }


def replay_guarded_market_fallback_decision(
    *,
    config: Mapping[str, Any],
    candidate: Mapping[str, Any],
    packets: Mapping[str, Any],
    scheduler_packet: Mapping[str, Any],
    risk_authority: Mapping[str, Any],
    selected_option: Mapping[str, Any],
    selected_inputs: Mapping[str, Any],
    limit_oracle_until_fallback: Mapping[str, Any] | None,
    asof: datetime,
    expiry: datetime,
) -> dict[str, Any]:
    policy_config = replay_order_fillability_runtime_config(config)
    candidate_id = str(candidate.get("candidate_id") or "")
    fallback_authority_attribution = package_new_entry_authority_attribution_fields(
        selected_inputs,
        selected_option,
        candidate,
        packets,
        risk_authority,
    )
    fallback_authority_payload = fallback_authority_attribution.get(
        "package_new_entry_authority_payload"
    )
    fallback_authority_payload = (
        fallback_authority_payload
        if fallback_authority_attribution.get("package_new_entry_authority_valid")
        is True
        and isinstance(fallback_authority_payload, Mapping)
        else {}
    )
    package_policy = selected_ultimate_execution_policy_shadow(
        scheduler_packet,
        candidate_id,
        candidate=candidate,
    )
    execution_policy = package_policy.get("execution_policy_shadow")
    execution_policy = execution_policy if isinstance(execution_policy, Mapping) else {}
    fallback_text = str(
        execution_policy.get("would_guarded_market_fallback")
        or execution_policy.get("guarded_market_fallback")
        or ""
    )
    package_guarded_fallback_policy = bool(
        package_policy.get("status")
        in {
            "ultimate_candidate_package_execution_policy_available",
            "ultimate_candidate_package_replay_execution_policy_available_from_candidate_fields",
        }
        and "guarded_market" in fallback_text
    )
    architecture_text = str(
        execution_policy.get("would_order_entry_policy")
        or execution_policy.get("selected_order_type_architecture")
        or ""
    )
    fallback_window = guarded_market_fallback_lifetime_window(
        asof=asof,
        expiry=expiry,
        fallback_delay_minutes=policy_config["fallback_delay_minutes"],
    )
    fallback_time = fallback_window["fallback_time"]
    pretrade_cost_packet = normalized_pretrade_cost_packet_from_packets(packets)
    executable_cost_r, _, executable_cost_block_reason = (
        executable_broker_calibrated_cost_r_from_packets(packets)
    )
    expected_cost_r = safe_float(executable_cost_r, 0.0)
    candidate_probability = safe_float(
        first_present(
            fallback_authority_payload.get("probability"),
            selected_inputs.get("candidate_probability"),
            selected_inputs.get("probability"),
            selected_option.get("candidate_probability"),
            selected_option.get("probability"),
            packets.get("candidate_probability"),
            packets.get("probability"),
        ),
        0.0,
    )
    candidate_ev_r = safe_float(
        first_present(
            selected_inputs.get("candidate_ev_r"),
            selected_inputs.get("ev_r"),
            selected_inputs.get("expectancy_r"),
            selected_option.get("candidate_ev_r"),
            selected_option.get("ev_r"),
            selected_option.get("expectancy_r"),
            packets.get("candidate_ev_r"),
            packets.get("ev_r"),
            packets.get("expectancy_r"),
        ),
        0.0,
    )
    fill_probability_input = first_present(
        fallback_authority_payload.get("fill_probability"),
        selected_inputs.get("fill_probability"),
        selected_inputs.get("candidate_fill_probability"),
        selected_option.get("fill_probability"),
        selected_option.get("candidate_fill_probability"),
        candidate.get("fill_probability"),
        candidate.get("candidate_fill_probability"),
        packets.get("fill_probability"),
        packets.get("candidate_fill_probability"),
    )
    fill_probability_present = fill_probability_input not in (None, "")
    source_completeness_input = first_present(
        fallback_authority_payload.get("source_completeness"),
        selected_inputs.get("source_completeness"),
    )
    source_completeness_present = source_completeness_input not in (None, "")
    fill_probability = safe_float(fill_probability_input, 0.25)
    limit_wait_fillability_input = first_present(
        fallback_authority_payload.get(
            "predecision_limit_fillability_probability"
        ),
        fallback_authority_payload.get("limit_fillability_probability"),
        fallback_authority_payload.get("execution_fill_probability"),
        selected_inputs.get("predecision_limit_fillability_probability"),
        selected_inputs.get("limit_fillability_probability"),
        selected_inputs.get("package_new_entry_authority_limit_fillability_probability"),
        selected_option.get("predecision_limit_fillability_probability"),
        selected_option.get("limit_fillability_probability"),
        selected_option.get("package_new_entry_authority_limit_fillability_probability"),
        candidate.get("predecision_limit_fillability_probability"),
        candidate.get("limit_fillability_probability"),
        candidate.get("package_new_entry_authority_limit_fillability_probability"),
        packets.get("predecision_limit_fillability_probability"),
        packets.get("limit_fillability_probability"),
        packets.get("package_new_entry_authority_limit_fillability_probability"),
    )
    if limit_wait_fillability_input in (None, ""):
        for source in (selected_inputs, selected_option, candidate, packets):
            fillability_packet = source.get("predecision_limit_fillability")
            if isinstance(fillability_packet, Mapping):
                limit_wait_fillability_input = first_present(
                    fillability_packet.get("fill_probability"),
                    fillability_packet.get("probability"),
                    fillability_packet.get("limit_fillability_probability"),
                )
                if limit_wait_fillability_input not in (None, ""):
                    break
    if limit_wait_fillability_input in (None, ""):
        for source in (selected_inputs, selected_option, candidate, packets):
            for payload_key in (
                "candidate_decision_quality_payload",
                "candidate_decision_quality",
                "package_new_entry_authority_quality",
                "quality",
                "threshold_quality",
            ):
                payload = source.get(payload_key)
                if not isinstance(payload, Mapping):
                    continue
                limit_wait_fillability_input = first_present(
                    payload.get("predecision_limit_fillability_probability"),
                    payload.get("limit_fillability_probability"),
                    payload.get("package_new_entry_authority_limit_fillability_probability"),
                )
                if limit_wait_fillability_input not in (None, ""):
                    break
            if limit_wait_fillability_input not in (None, ""):
                break
    limit_wait_fillability_present = limit_wait_fillability_input not in (None, "")
    order_fillability_probability = safe_float(limit_wait_fillability_input, math.nan)
    limit_wait_fill_probability = order_fillability_probability
    source_completeness = safe_float(source_completeness_input, 0.25)
    fill_probability_degraded_default = bool(
        selected_inputs.get("fill_probability_missing_degraded_default_applied")
        or selected_option.get("fill_probability_missing_degraded_default_applied")
    )
    source_completeness_degraded_default = bool(
        selected_inputs.get("source_completeness_missing_degraded_default_applied")
        or selected_option.get("source_completeness_missing_degraded_default_applied")
    )
    guarded_extra_cost_r = policy_config["guarded_market_extra_cost_r"]
    candidate_expected_net_r_after_fallback = (
        safe_float(fallback_authority_payload.get("expected_net_r"), math.nan)
        - guarded_extra_cost_r
        if fallback_authority_payload.get("expected_net_r") not in (None, "")
        else candidate_ev_r - expected_cost_r - guarded_extra_cost_r
    )
    fallback_wait_ceiling_probability = limit_wait_fill_probability
    fallback_wait_ceiling_probability_source = (
        "predecision_limit_fillability_probability"
        if limit_wait_fillability_present
        else None
    )
    if (
        not math.isfinite(fallback_wait_ceiling_probability)
        and fill_probability_present
    ):
        fallback_wait_ceiling_probability = fill_probability
        fallback_wait_ceiling_probability_source = (
            "candidate_fill_probability_diagnostic_proxy"
        )
    selector_action = str(
        first_present(
            fallback_authority_payload.get("selector_action"),
            selected_inputs.get("selector_action"),
            selected_option.get("selector_action"),
            candidate.get("selector_action"),
            packets.get("selector_action"),
        )
        or ""
    ).strip()
    selector_reason = str(
        first_present(
            fallback_authority_payload.get("selector_reason"),
            selected_inputs.get("selector_reason"),
            selected_option.get("selector_reason"),
            candidate.get("selector_reason"),
            packets.get("selector_reason"),
        )
        or ""
    ).strip()
    router_refusal_open_reduced = bool(
        selector_action == "open-reduced-risk"
        and (
            execution_policy.get("router_refusal_open_reduced_risk") is True
            or "router_refusal" in selector_reason
            or "dynamic_router_refused" in selector_reason
            or "admission_quality_dynamic_router_refused_candidate_use"
            in selector_reason
        )
    )
    route_session = str(
        first_present(
            candidate.get("route_session"),
            candidate.get("session_bucket"),
            candidate.get("session"),
            selected_inputs.get("route_session"),
            selected_inputs.get("session_bucket"),
            selected_inputs.get("session"),
        )
        or ""
    ).strip()
    route_session_missing = not route_session
    off_configured_session = route_session in {
            "off_configured",
            "off_configured_session",
            "off_kz",
            "off_kz_broad",
        }
    reasons: list[str] = []
    no_broker_replay = broad_live_as_if_no_broker_replay(config)
    broker_cost_authority_block_reason = replay_order_cost_authority_block_reason(
        packets,
        config,
    )
    if not policy_config["enabled"]:
        reasons.append("replay_order_fillability_policy_v1_disabled")
    if (
        selector_action == "open-reduced-risk"
        and not policy_config["allow_open_reduced_risk_guarded_market_fallback"]
    ):
        reasons.append("open_reduced_risk_guarded_market_fallback_disabled")
    if (
        off_configured_session
        and not policy_config["allow_off_configured_session_guarded_market_fallback"]
    ):
        reasons.append("off_configured_session_guarded_market_fallback_disabled")
    if not no_broker_replay:
        reasons.append("not_broad_live_as_if_no_broker_replay")
    if broker_cost_authority_block_reason:
        reasons.append(
            "broker_cost_authority_not_executable_for_fallback:"
            f"{broker_cost_authority_block_reason}"
        )
    if executable_cost_block_reason and not broker_cost_authority_block_reason:
        reasons.append(
            "broker_cost_value_not_executable_for_fallback:"
            f"{executable_cost_block_reason}"
        )
    if policy_config["require_package_execution_policy"]:
        if package_policy.get("status") not in {
            "ultimate_candidate_package_execution_policy_available",
            "ultimate_candidate_package_replay_execution_policy_available_from_candidate_fields",
        }:
            reasons.append(str(package_policy.get("status") or "package_policy_missing"))
        if "guarded_market" not in fallback_text:
            reasons.append("package_execution_policy_has_no_guarded_market_fallback")
    if fallback_window["fallback_window_exhausted_by_expiry"]:
        reasons.append("fallback_window_exhausted_by_expiry")
    if risk_authority.get("risk_decision") not in {
        "trade",
        "reduce-risk",
        "open-reduced-risk",
    }:
        reasons.append("risk_authority_not_trade_or_reduce_risk")
    if candidate_probability < policy_config["min_candidate_probability"]:
        reasons.append("candidate_probability_below_fallback_floor")
    if candidate_ev_r < policy_config["min_candidate_ev_r"]:
        reasons.append("candidate_ev_r_below_fallback_floor")
    if (
        candidate_expected_net_r_after_fallback
        < policy_config["min_candidate_expected_net_r_after_fallback"]
    ):
        reasons.append("candidate_expected_net_r_after_fallback_below_floor")
    effective_min_fill_probability = (
        policy_config["package_min_fill_probability"]
        if package_guarded_fallback_policy
        else policy_config["min_fill_probability"]
    )
    effective_min_order_fillability_probability = (
        policy_config["package_min_order_fillability_probability_for_fallback"]
        if package_guarded_fallback_policy
        else policy_config["min_order_fillability_probability_for_fallback"]
    )
    if fill_probability < effective_min_fill_probability:
        reasons.append("fill_probability_below_fallback_floor")
    if (
        limit_wait_fillability_present
        and math.isfinite(order_fillability_probability)
        and order_fillability_probability < effective_min_order_fillability_probability
    ):
        reasons.append("order_fillability_probability_below_fallback_floor")
    limit_probe_filled_before_fallback = bool(
        isinstance(limit_oracle_until_fallback, Mapping)
        and str(limit_oracle_until_fallback.get("fill_status") or "").startswith("filled")
    )
    high_fill_probability_wait_ceiling_bypassed = False
    if (
        math.isfinite(fallback_wait_ceiling_probability)
        and
        fallback_wait_ceiling_probability
        > policy_config["max_limit_fill_probability_for_fallback"]
        and not high_fill_probability_wait_ceiling_bypassed
    ):
        reasons.append("limit_fill_probability_above_fallback_wait_ceiling")
    if not fill_probability_present:
        reasons.append("fill_probability_missing_source_bound_input")
    if not limit_wait_fillability_present:
        reasons.append("limit_wait_fillability_missing_source_bound_input")
        reasons.append("order_fillability_probability_missing_source_bound_input")
    if fill_probability_degraded_default:
        reasons.append("fill_probability_degraded_default_not_fallback_authority")
    if source_completeness < policy_config["min_source_completeness"]:
        reasons.append("source_completeness_below_fallback_floor")
    if not source_completeness_present:
        reasons.append("source_completeness_missing_source_bound_input")
    if source_completeness_degraded_default:
        reasons.append("source_completeness_degraded_default_not_fallback_authority")
    if expected_cost_r > policy_config["max_expected_cost_r"]:
        reasons.append("expected_cost_r_above_fallback_ceiling")
    if limit_oracle_until_fallback is None:
        reasons.append("limit_fillability_oracle_until_fallback_missing")
    elif limit_probe_filled_before_fallback:
        reasons.append("limit_order_filled_before_guarded_market_fallback_time")

    decision = {
        "schema_version": "replay_order_fillability_policy_v1",
        "enabled": policy_config["enabled"],
        "status": "eligible" if not reasons else "not_eligible",
        "reason": "eligible_guarded_market_fallback_after_limit_fillability_probe"
        if not reasons
        else reasons[0],
        "reasons": reasons,
        "fallback_decision_time_utc": iso(fallback_time),
        "fallback_unclamped_decision_time_utc": iso(
            fallback_window["fallback_unclamped_time"]
        ),
        "fallback_latest_usable_time_utc": iso(fallback_window["latest_usable_time"]),
        "fallback_time_clamped_inside_order_lifetime": fallback_window[
            "fallback_time_clamped_inside_order_lifetime"
        ],
        "fallback_window_exhausted_by_expiry": fallback_window[
            "fallback_window_exhausted_by_expiry"
        ],
        "fallback_delay_minutes": round(policy_config["fallback_delay_minutes"], 8),
        "candidate_id": candidate_id,
        "selector_action": selector_action or None,
        "selector_reason": selector_reason or None,
        "router_refusal_open_reduced_risk": router_refusal_open_reduced,
        "route_session": route_session or None,
        "route_session_missing": route_session_missing,
        "off_configured_session": off_configured_session,
        "open_reduced_risk_guarded_market_fallback_allowed": policy_config[
            "allow_open_reduced_risk_guarded_market_fallback"
        ],
        "off_configured_session_guarded_market_fallback_allowed": policy_config[
            "allow_off_configured_session_guarded_market_fallback"
        ],
        "candidate_probability": candidate_probability,
        "candidate_ev_r": candidate_ev_r,
        "fill_probability": fill_probability,
        "candidate_fill_probability": fill_probability,
        "order_fillability_probability": (
            order_fillability_probability
            if math.isfinite(order_fillability_probability)
            else None
        ),
        "limit_wait_fill_probability": (
            limit_wait_fill_probability
            if math.isfinite(limit_wait_fill_probability)
            else None
        ),
        "limit_wait_fill_probability_source": (
            "predecision_limit_fillability_probability"
            if limit_wait_fillability_present
            else "missing_predecision_order_fillability"
        ),
        "order_fillability_probability_source": (
            "predecision_limit_fillability_probability"
            if limit_wait_fillability_present
            else None
        ),
        "limit_wait_fill_probability_source_bound_input_present": (
            limit_wait_fillability_present
        ),
        "fallback_wait_ceiling_probability": (
            fallback_wait_ceiling_probability
            if math.isfinite(fallback_wait_ceiling_probability)
            else None
        ),
        "fallback_wait_ceiling_probability_source": (
            fallback_wait_ceiling_probability_source
        ),
        "fallback_wait_ceiling_probability_diagnostic_proxy_used": (
            fallback_wait_ceiling_probability_source
            == "candidate_fill_probability_diagnostic_proxy"
        ),
        "package_guarded_fallback_policy": package_guarded_fallback_policy,
        "effective_min_fill_probability": effective_min_fill_probability,
        "configured_min_fill_probability": policy_config["min_fill_probability"],
        "configured_package_min_fill_probability": policy_config[
            "package_min_fill_probability"
        ],
        "effective_min_order_fillability_probability_for_fallback": (
            effective_min_order_fillability_probability
        ),
        "configured_min_order_fillability_probability_for_fallback": policy_config[
            "min_order_fillability_probability_for_fallback"
        ],
        "configured_package_min_order_fillability_probability_for_fallback": (
            policy_config["package_min_order_fillability_probability_for_fallback"]
        ),
        "max_limit_fill_probability_for_fallback": policy_config[
            "max_limit_fill_probability_for_fallback"
        ],
        "allow_high_fill_probability_after_unfilled_probe": policy_config[
            "allow_high_fill_probability_after_unfilled_probe"
        ],
        "high_fill_probability_wait_ceiling_bypassed": (
            high_fill_probability_wait_ceiling_bypassed
        ),
        "high_fill_probability_wait_ceiling_bypass_disabled_reason": (
            "elapsed_unfilled_probe_not_causal_execution_authority"
            if policy_config["allow_high_fill_probability_after_unfilled_probe"]
            and math.isfinite(fallback_wait_ceiling_probability)
            and fallback_wait_ceiling_probability
            > policy_config["max_limit_fill_probability_for_fallback"]
            else None
        ),
        "source_completeness": source_completeness,
        "fill_probability_source_bound_input_present": fill_probability_present,
        "source_completeness_source_bound_input_present": (
            source_completeness_present
        ),
        "fill_probability_degraded_default_applied": (
            fill_probability_degraded_default
        ),
        "source_completeness_degraded_default_applied": (
            source_completeness_degraded_default
        ),
        "expected_cost_r": expected_cost_r,
        "broker_calibrated_expected_cost_r": expected_cost_r,
        "pretrade_cost_packet_status": pretrade_cost_packet.get("status"),
        "pretrade_cost_packet_authority": pretrade_cost_packet.get("authority"),
        "cost_source_gap_status": pretrade_cost_packet.get("cost_source_gap_status"),
        "broker_cost_authority_block_reason": broker_cost_authority_block_reason,
        "candidate_expected_net_r_after_fallback": round(
            candidate_expected_net_r_after_fallback,
            9,
        ),
        "min_candidate_expected_net_r_after_fallback": policy_config[
            "min_candidate_expected_net_r_after_fallback"
        ],
        "min_drift_adjusted_candidate_expected_net_r_after_fallback": policy_config[
            "min_drift_adjusted_candidate_expected_net_r_after_fallback"
        ],
        "min_effective_target_r_after_fallback": policy_config[
            "min_effective_target_r_after_fallback"
        ],
        "guarded_market_extra_cost_r": guarded_extra_cost_r,
        "max_adverse_entry_drift_r": policy_config["max_adverse_entry_drift_r"],
        "package_policy_status": package_policy.get("status"),
        "package_shadow_selected_candidate_id": package_policy.get(
            "shadow_selected_candidate_id"
        ),
        "package_execution_policy": dict(execution_policy),
        "package_execution_policy_fallback": fallback_text,
        "package_execution_policy_order_entry": architecture_text,
        "limit_probe_fill_status": (
            limit_oracle_until_fallback.get("fill_status")
            if isinstance(limit_oracle_until_fallback, Mapping)
            else None
        ),
        "limit_probe_terminal_outcome": (
            limit_oracle_until_fallback.get("terminal_outcome")
            if isinstance(limit_oracle_until_fallback, Mapping)
            else None
        ),
        "fallback_policy_thresholds_used_only_predecision_fields": True,
        "fallback_decision_used_elapsed_market_path": (
            isinstance(limit_oracle_until_fallback, Mapping)
        ),
        "fallback_execution_used_elapsed_market_path": False,
        "used_only_predecision_fields_plus_elapsed_limit_fillability": True,
        "source_boundary": (
            "local_replay_guarded_market_fallback_no_broker_authority_"
            "no_future_outcome_used_for_eligibility"
        ),
        "live_broker_authority": False,
        "broker_mutation_enabled": False,
        "final_selection_claim": False,
    }
    decision["policy_hash_sha256"] = stable_sha256(decision)
    return decision


def first_market_fallback_row(
    rows: Iterable[Mapping[str, Any]],
    *,
    fallback_time: datetime,
    expiry: datetime,
    source: str,
    side: str,
) -> tuple[datetime, Mapping[str, Any], float, str] | None:
    for row in rows:
        ts = parse_row_time(row)
        if ts is None or ts < fallback_time or ts > expiry:
            continue
        if source == "tick":
            price, price_source = _tick_entry_fill_price_with_source(row, side=side)
        else:
            price, price_source = _m1_market_fallback_entry_price_with_source(
                row,
                side=side,
            )
        if price is None or price <= 0:
            continue
        return ts, row, float(price), str(price_source or source)
    return None


def guarded_market_fallback_adverse_entry_drift_r(
    *,
    side: str,
    original_entry_price: float,
    fallback_entry_price: float,
    original_stop_price: float,
) -> float | None:
    risk_distance = abs(original_entry_price - original_stop_price)
    if risk_distance <= 0:
        return None
    side_key = str(side or "").upper()
    if side_key == "LONG":
        return round((fallback_entry_price - original_entry_price) / risk_distance, 9)
    if side_key == "SHORT":
        return round((original_entry_price - fallback_entry_price) / risk_distance, 9)
    return None


def market_fallback_geometry(
    *,
    side: str,
    fallback_entry_price: float,
    original_entry_price: float,
    original_stop_price: float,
    target_r: float,
    original_target_price: float | None = None,
) -> tuple[float, float]:
    if original_target_price is not None:
        return original_stop_price, original_target_price
    risk_distance = abs(original_entry_price - original_stop_price)
    if risk_distance <= 0:
        return original_stop_price, fallback_entry_price
    side_key = str(side or "").upper()
    if side_key == "LONG":
        return (
            original_stop_price,
            original_entry_price + (target_r * risk_distance),
        )
    return (
        original_stop_price,
        original_entry_price - (target_r * risk_distance),
    )


def market_fallback_effective_target_r(
    *,
    side: str,
    fallback_entry_price: float,
    fallback_stop_price: float,
    fallback_target_price: float,
) -> float | None:
    risk_distance = abs(fallback_entry_price - fallback_stop_price)
    if risk_distance <= 0:
        return None
    side_key = str(side or "").upper()
    if side_key == "LONG":
        return round((fallback_target_price - fallback_entry_price) / risk_distance, 9)
    if side_key == "SHORT":
        return round((fallback_entry_price - fallback_target_price) / risk_distance, 9)
    return None


def high_fill_unfilled_probe_counterfactual_fields(
    *,
    decision: Mapping[str, Any],
    config: Mapping[str, Any],
    candidate: Mapping[str, Any],
    packets: Mapping[str, Any],
    path_source: ResolvedSource,
    path_rows: tuple[dict[str, Any], ...],
    limit_oracle: Mapping[str, Any],
    expiry: datetime,
) -> dict[str, Any]:
    reasons = list(decision.get("reasons") or [])
    if "limit_fill_probability_above_fallback_wait_ceiling" not in reasons:
        return {}
    if str(limit_oracle.get("fill_status") or "").startswith("filled"):
        return {}
    if "guarded_market" not in str(
        decision.get("package_execution_policy_fallback") or ""
    ):
        return {}

    fields: dict[str, Any] = {
        "high_fill_unfilled_probe_counterfactual_status": "not_scoreable",
        "high_fill_unfilled_probe_counterfactual_reason": None,
        "high_fill_unfilled_probe_counterfactual_executed": False,
        "high_fill_unfilled_probe_counterfactual_source_boundary": (
            "diagnostic_replay_only_not_order_execution_authority"
        ),
        "high_fill_unfilled_probe_counterfactual_used_only_predecision_fields": True,
        "high_fill_unfilled_probe_counterfactual_fill_probability": (
            decision.get("fill_probability")
        ),
        "high_fill_unfilled_probe_counterfactual_max_fill_probability": (
            decision.get("max_limit_fill_probability_for_fallback")
        ),
        "high_fill_unfilled_probe_counterfactual_limit_probe_fill_status": (
            limit_oracle.get("fill_status")
        ),
    }
    fallback_time = parse_utc(decision.get("fallback_decision_time_utc"))
    if fallback_time is None or fallback_time >= expiry:
        fields["high_fill_unfilled_probe_counterfactual_reason"] = (
            "fallback_window_exhausted_by_expiry"
        )
        fields["high_fill_unfilled_probe_counterfactual_hash_sha256"] = stable_sha256(
            fields
        )
        return fields

    source = str(limit_oracle.get("source") or path_source.spec.timeframe or "m1").lower()
    source = "tick" if source == "tick" else "m1"
    fallback_row = first_market_fallback_row(
        path_rows,
        fallback_time=fallback_time,
        expiry=expiry,
        source=source,
        side=str(candidate.get("side") or ""),
    )
    if fallback_row is None:
        fields["high_fill_unfilled_probe_counterfactual_reason"] = (
            "no_market_row_available_at_or_after_fallback_time"
        )
        fields["high_fill_unfilled_probe_counterfactual_hash_sha256"] = stable_sha256(
            fields
        )
        return fields

    fallback_fill_time, _row, fallback_entry, fallback_fill_price_source = fallback_row
    original_entry = safe_float(candidate.get("entry_price"))
    original_stop = safe_float(candidate.get("stop_loss"))
    original_target = safe_float(
        first_present(candidate.get("take_profit_1"), candidate.get("target_price")),
        None,
    )
    target_r = safe_float(
        first_present(
            limit_oracle.get("target_r"),
            candidate.get("risk_reward_ratio"),
            candidate.get("rr"),
        ),
        1.0,
    )
    adverse_entry_drift_r = guarded_market_fallback_adverse_entry_drift_r(
        side=str(candidate.get("side") or ""),
        original_entry_price=original_entry,
        fallback_entry_price=fallback_entry,
        original_stop_price=original_stop,
    )
    max_adverse_entry_drift_r = min(
        replay_order_fillability_runtime_config(config)["max_adverse_entry_drift_r"],
        max(0.0, target_r),
    )
    fields.update(
        {
            "high_fill_unfilled_probe_counterfactual_fill_time_utc": (
                iso(fallback_fill_time)
            ),
            "high_fill_unfilled_probe_counterfactual_fill_price": round(
                fallback_entry,
                8,
            ),
            "high_fill_unfilled_probe_counterfactual_fill_price_source": (
                fallback_fill_price_source
            ),
            "high_fill_unfilled_probe_counterfactual_entry_adverse_drift_r": (
                adverse_entry_drift_r
            ),
            "high_fill_unfilled_probe_counterfactual_max_adverse_entry_drift_r": (
                max_adverse_entry_drift_r
            ),
            "high_fill_unfilled_probe_counterfactual_limit_requested_entry_price": (
                round(original_entry, 8)
            ),
            "high_fill_unfilled_probe_counterfactual_limit_requested_stop_loss": (
                round(original_stop, 8)
            ),
            "high_fill_unfilled_probe_counterfactual_limit_requested_take_profit_1": (
                round(original_target, 8) if original_target is not None else None
            ),
        }
    )
    if (
        adverse_entry_drift_r is None
        or adverse_entry_drift_r > max_adverse_entry_drift_r
    ):
        fields["high_fill_unfilled_probe_counterfactual_reason"] = (
            "fallback_entry_adverse_drift_above_thesis_geometry_ceiling"
        )
        fields["high_fill_unfilled_probe_counterfactual_hash_sha256"] = stable_sha256(
            fields
        )
        return fields

    fallback_stop, fallback_target = market_fallback_geometry(
        side=str(candidate.get("side") or ""),
        fallback_entry_price=fallback_entry,
        original_entry_price=original_entry,
        original_stop_price=original_stop,
        target_r=target_r,
        original_target_price=original_target,
    )
    fallback_geometry_mode = (
        "preserve_original_sl_tp"
        if original_target is not None
        else "derive_target_from_original_risk"
    )
    fallback_geometry_original_sl_tp_preserved = bool(
        original_target is not None
        and fallback_stop == original_stop
        and fallback_target == original_target
    )
    fallback_candidate = canonicalize_candidate_geometry(
        {
            **dict(candidate),
            "entry_price": fallback_entry,
            "stop_loss": fallback_stop,
            "take_profit_1": fallback_target,
            "risk_reward_ratio": target_r,
            "rr": target_r,
            "limit_requested_entry_price": original_entry,
            "limit_requested_stop_loss": original_stop,
            "limit_requested_take_profit_1": original_target,
            "original_limit_entry_price": original_entry,
            "original_limit_stop_loss": original_stop,
            "original_limit_take_profit_1": original_target,
            "fallback_entry_adverse_drift_r": adverse_entry_drift_r,
            "max_adverse_entry_drift_r": max_adverse_entry_drift_r,
            "fallback_geometry_mode": fallback_geometry_mode,
            "fallback_geometry_reanchored": False,
            "fallback_geometry_original_sl_tp_preserved": (
                fallback_geometry_original_sl_tp_preserved
            ),
        },
        source="high_fill_unfilled_probe_counterfactual_geometry",
    )
    if source == "tick":
        normalized_rows = []
        for row in path_rows:
            normalized = dict(row)
            normalized.setdefault(
                "ts_utc",
                normalized.get("time_utc") or normalized.get("time"),
            )
            normalized_rows.append(normalized)
        fallback_oracle = infer_microstructure_ordered_path_from_ticks(
            ticks=normalized_rows,
            side=str(candidate.get("side") or ""),
            entry_price=fallback_entry,
            stop_price=fallback_stop,
            target_price=fallback_target,
            asof_utc=iso(fallback_fill_time) or "",
            fill_already_confirmed=True,
            fill_time_utc=iso(fallback_fill_time),
        ).as_dict()
        fallback_oracle["source"] = "tick"
        fallback_oracle["ordered_tick_truth_satisfied"] = (
            path_source.spec.ordered_tick_truth_satisfied is True
        )
    else:
        fallback_oracle = infer_ordered_path_from_m1(
            bars=path_rows,
            side=str(candidate.get("side") or ""),
            entry_price=fallback_entry,
            stop_price=fallback_stop,
            target_price=fallback_target,
            asof_utc=iso(fallback_fill_time) or "",
            fill_already_confirmed=True,
            fill_time_utc=iso(fallback_fill_time),
        ).as_dict()
        fallback_oracle["source"] = "m1"
        fallback_oracle["ordered_tick_truth_satisfied"] = False
    fallback_oracle = attach_close_mark(
        oracle=fallback_oracle,
        rows=path_rows,
        candidate=fallback_candidate,
        expiry=expiry,
    )
    fallback_gross_r, fallback_close_reason, fallback_target_r = path_final_r(
        oracle=fallback_oracle,
        partial_be_runner=False,
    )
    (
        fallback_gross_r,
        fallback_close_reason,
        fallback_target_r,
        selected_policy_replay_exit,
    ) = apply_selected_execution_policy_replay_exit(
        oracle=fallback_oracle,
        rows=path_rows,
        candidate=fallback_candidate,
        packets=packets,
        final_r=fallback_gross_r,
        close_reason=fallback_close_reason,
        target_r=fallback_target_r,
        runtime=(
            config.get("gtos_vnext_runtime")
            if isinstance(config, Mapping)
            and isinstance(config.get("gtos_vnext_runtime"), Mapping)
            else {}
        ),
    )
    (
        fallback_gross_r,
        fallback_close_reason,
        fallback_target_r,
        profit_harvest_replay_exit,
    ) = apply_profit_harvest_replay_exit(
        oracle=fallback_oracle,
        rows=path_rows,
        candidate=fallback_candidate,
        config=config,
        packets=packets,
        final_r=fallback_gross_r,
        close_reason=fallback_close_reason,
        target_r=fallback_target_r,
        selected_policy_replay_exit=selected_policy_replay_exit,
    )
    base_expected_cost_r = safe_float(
        decision.get("expected_cost_r"),
        safe_float(packets.get("cost_r"), 0.0),
    )
    fallback_extra_cost_r = replay_order_fillability_runtime_config(config)[
        "guarded_market_extra_cost_r"
    ]
    fallback_expected_cost_r = round(base_expected_cost_r + fallback_extra_cost_r, 8)
    fallback_net_r = (
        None
        if fallback_gross_r is None
        else round(safe_float(fallback_gross_r) - fallback_expected_cost_r, 8)
    )
    fields.update(
        {
            "high_fill_unfilled_probe_counterfactual_status": "scored",
            "high_fill_unfilled_probe_counterfactual_reason": (
                "scored_guarded_market_fallback_counterfactual_after_high_fill_limit_probe_unfilled"
            ),
            "high_fill_unfilled_probe_counterfactual_source": source,
            "high_fill_unfilled_probe_counterfactual_stop_loss": round(
                fallback_stop,
                8,
            ),
            "high_fill_unfilled_probe_counterfactual_take_profit_1": round(
                fallback_target,
                8,
            ),
            "high_fill_unfilled_probe_counterfactual_geometry_mode": (
                fallback_geometry_mode
            ),
            "high_fill_unfilled_probe_counterfactual_geometry_reanchored": False,
            "high_fill_unfilled_probe_counterfactual_original_sl_tp_preserved": (
                fallback_geometry_original_sl_tp_preserved
            ),
            "high_fill_unfilled_probe_counterfactual_target_r": fallback_target_r,
            "high_fill_unfilled_probe_counterfactual_close_reason": (
                fallback_close_reason
            ),
            "high_fill_unfilled_probe_counterfactual_gross_r": fallback_gross_r,
            "high_fill_unfilled_probe_counterfactual_expected_cost_r": (
                fallback_expected_cost_r
            ),
            "high_fill_unfilled_probe_counterfactual_extra_cost_r": (
                fallback_extra_cost_r
            ),
            "high_fill_unfilled_probe_counterfactual_net_r": fallback_net_r,
            "high_fill_unfilled_probe_counterfactual_selected_policy_replay_exit": (
                selected_policy_replay_exit
            ),
            "high_fill_unfilled_probe_counterfactual_profit_harvest_replay_exit": (
                profit_harvest_replay_exit
            ),
        }
    )
    fields["high_fill_unfilled_probe_counterfactual_hash_sha256"] = stable_sha256(
        fields
    )
    return fields


def package_marketable_guarded_fallback_contract_required(
    risk_authority: Mapping[str, Any],
) -> bool:
    return (
        risk_authority.get("package_marketable_entry_guard_status")
        == "routed_to_replay_order_policy"
        and risk_authority.get("package_marketable_entry_guard_reason")
        == "package_marketable_limit_entry_routed_to_guarded_market_fallback"
    )


def package_marketable_guarded_fallback_contract_unmet_oracle(
    *,
    limit_oracle: Mapping[str, Any],
    decision: Mapping[str, Any],
) -> dict[str, Any]:
    oracle = dict(limit_oracle)
    decision_reason = str(
        decision.get("reason")
        or "guarded_market_fallback_not_applied_for_marketable_package_route"
    )
    decision_reasons = list(decision.get("reasons") or [])
    oracle.update(
        {
            "limit_first_fill_status": first_present(
                limit_oracle.get("fill_realism_diagnostic_fill_status"),
                limit_oracle.get("fill_status"),
            ),
            "limit_first_terminal_outcome": first_present(
                limit_oracle.get("fill_realism_diagnostic_terminal_outcome"),
                limit_oracle.get("terminal_outcome"),
            ),
            "limit_first_fill_time_utc": first_present(
                limit_oracle.get("fill_realism_diagnostic_fill_time_utc"),
                limit_oracle.get("fill_time_utc"),
            ),
            "limit_first_entry_price": first_present(
                limit_oracle.get("fill_realism_diagnostic_fill_price"),
                limit_oracle.get("fill_price"),
            ),
            "limit_first_fill_executable": bool(
                limit_oracle.get("fill_realism_executable") is not False
                and limit_oracle.get("diagnostic_fill_only") is not True
                and str(limit_oracle.get("package_execution_result_scope") or "")
                != "diagnostic_counterfactual_only"
            ),
            "fill_status": (
                "not_filled_marketable_entry_guard_fallback_contract_unmet"
            ),
            "terminal_outcome": (
                "not_filled_marketable_entry_guard_fallback_contract_unmet"
            ),
            "fill_time_utc": None,
            "fill_price": None,
            "close_mark_time_utc": None,
            "close_mark_price": None,
            "close_mark_source": None,
            "close_mark_r": None,
            "replay_order_fillability_policy_v1": dict(decision),
            "replay_order_fillability_policy_status": (
                "marketable_entry_guard_fallback_contract_unmet"
            ),
            "guarded_market_fallback_applied": False,
            "guarded_market_fallback_status": decision.get("status"),
            "guarded_market_fallback_reason": decision_reason,
            "guarded_market_fallback_reasons": decision_reasons,
            "fallback_fill_time_utc": decision.get("fallback_fill_time_utc"),
            "fallback_fill_price": decision.get("fallback_fill_price"),
            "fallback_fill_price_source": decision.get(
                "fallback_fill_price_source"
            ),
            "fallback_stop_loss": decision.get("fallback_stop_loss"),
            "fallback_take_profit_1": decision.get("fallback_take_profit_1"),
            "fallback_target_r": decision.get("fallback_target_r"),
            "fallback_effective_target_r": decision.get(
                "fallback_effective_target_r"
            ),
            "min_effective_target_r_after_fallback": decision.get(
                "min_effective_target_r_after_fallback"
            ),
            "fallback_entry_adverse_drift_r": decision.get(
                "fallback_entry_adverse_drift_r"
            ),
            "max_adverse_entry_drift_r": decision.get(
                "max_adverse_entry_drift_r"
            ),
            "fallback_geometry_mode": decision.get("fallback_geometry_mode"),
            "fallback_geometry_reanchored": decision.get(
                "fallback_geometry_reanchored"
            ),
            "fallback_geometry_original_sl_tp_preserved": decision.get(
                "fallback_geometry_original_sl_tp_preserved"
            ),
            "limit_requested_entry_price": decision.get(
                "limit_requested_entry_price"
            ),
            "limit_requested_stop_loss": decision.get("limit_requested_stop_loss"),
            "limit_requested_take_profit_1": decision.get(
                "limit_requested_take_profit_1"
            ),
            "package_marketable_guarded_fallback_contract_required": True,
            "package_marketable_guarded_fallback_contract_unmet": True,
            "package_marketable_guarded_fallback_contract_unmet_reason": (
                decision_reason
            ),
        }
    )
    return oracle


def maybe_apply_guarded_market_fallback(
    *,
    config: Mapping[str, Any],
    candidate: Mapping[str, Any],
    packets: Mapping[str, Any],
    scheduler_packet: Mapping[str, Any],
    risk_authority: Mapping[str, Any],
    selected_option: Mapping[str, Any],
    selected_inputs: Mapping[str, Any],
    path_sources: Mapping[str, ResolvedSource],
    day: str,
    asof: datetime,
    expiry: datetime,
    limit_oracle: Mapping[str, Any],
    path_source: ResolvedSource,
    path_rows: tuple[dict[str, Any], ...],
) -> dict[str, Any]:
    policy_config = replay_order_fillability_runtime_config(config)
    fallback_window = guarded_market_fallback_lifetime_window(
        asof=asof,
        expiry=expiry,
        fallback_delay_minutes=policy_config["fallback_delay_minutes"],
    )
    fallback_time = fallback_window["fallback_time"]
    limit_probe_oracle: dict[str, Any] | None = None
    if fallback_time is not None and fallback_time < expiry:
        limit_probe_oracle, _probe_source, _probe_rows = path_source_and_oracle(
            candidate=candidate,
            sources=path_sources,
            day=day,
            asof=asof,
            expiry=fallback_time,
            config=config,
        )
    decision = replay_guarded_market_fallback_decision(
        config=config,
        candidate=candidate,
        packets=packets,
        scheduler_packet=scheduler_packet,
        risk_authority=risk_authority,
        selected_option=selected_option,
        selected_inputs=selected_inputs,
        limit_oracle_until_fallback=limit_probe_oracle,
        asof=asof,
        expiry=expiry,
    )
    if (
        decision.get("status") == "eligible"
        and str(decision.get("selector_action") or "").strip() == "open-reduced-risk"
        and decision.get("open_reduced_risk_guarded_market_fallback_allowed") is False
    ):
        decision = dict(decision)
        decision.update(
            {
                "status": "not_eligible",
                "reason": "open_reduced_risk_guarded_market_fallback_disabled",
                "reasons": list(decision.get("reasons") or [])
                + ["open_reduced_risk_guarded_market_fallback_disabled"],
            }
        )
        decision["policy_hash_sha256"] = stable_sha256(decision)
    base_expected_cost_r = safe_float(
        decision.get("expected_cost_r"),
        safe_float(packets.get("cost_r"), 0.0),
    )
    broker_pretrade_cost_r = safe_float(
        packets.get("broker_pretrade_cost_r"),
        safe_float(
            packets.get("broker_calibrated_expected_cost_r"),
            base_expected_cost_r,
        ),
    )
    result = {
        "applied": False,
        "decision": decision,
        "oracle": dict(limit_oracle),
        "path_source": path_source,
        "path_rows": path_rows,
        "candidate_for_outcome": dict(candidate),
        "expected_cost_r": base_expected_cost_r,
        "broker_pretrade_cost_r": broker_pretrade_cost_r,
        "fallback_execution_surcharge_r": 0.0,
        "total_execution_cost_r": base_expected_cost_r,
        "fallback_extra_cost_r": 0.0,
    }
    counterfactual_limit_oracle = (
        limit_probe_oracle
        if isinstance(limit_probe_oracle, Mapping)
        else limit_oracle
    )
    high_fill_counterfactual = high_fill_unfilled_probe_counterfactual_fields(
        decision=decision,
        config=config,
        candidate=candidate,
        packets=packets,
        path_source=path_source,
        path_rows=path_rows,
        limit_oracle=counterfactual_limit_oracle,
        expiry=expiry,
    )
    if high_fill_counterfactual:
        decision = {**dict(decision), **high_fill_counterfactual}
        decision["policy_hash_sha256"] = stable_sha256(decision)
        result["decision"] = decision
        result["oracle"].update(high_fill_counterfactual)
    marketable_fallback_contract_required = (
        package_marketable_guarded_fallback_contract_required(risk_authority)
    )
    if decision.get("status") != "eligible":
        if marketable_fallback_contract_required:
            result["fallback_contract_unmet"] = True
            result["oracle"] = package_marketable_guarded_fallback_contract_unmet_oracle(
                limit_oracle=limit_oracle,
                decision=decision,
            )
        return result
    source = str(limit_oracle.get("source") or path_source.spec.timeframe or "m1").lower()
    source = "tick" if source == "tick" else "m1"
    fallback_row = first_market_fallback_row(
        path_rows,
        fallback_time=parse_utc(decision.get("fallback_decision_time_utc")) or fallback_time,
        expiry=expiry,
        source=source,
        side=str(candidate.get("side") or ""),
    )
    if fallback_row is None:
        decision = dict(decision)
        decision["status"] = "not_applied"
        decision["reason"] = "no_market_row_available_at_or_after_fallback_time"
        decision["policy_hash_sha256"] = stable_sha256(decision)
        result["decision"] = decision
        if marketable_fallback_contract_required:
            result["fallback_contract_unmet"] = True
            result["oracle"] = package_marketable_guarded_fallback_contract_unmet_oracle(
                limit_oracle=limit_oracle,
                decision=decision,
            )
        return result

    fallback_fill_time, _row, fallback_entry, fallback_fill_price_source = fallback_row
    original_entry = safe_float(candidate.get("entry_price"))
    original_stop = safe_float(candidate.get("stop_loss"))
    original_target = safe_float(
        first_present(candidate.get("take_profit_1"), candidate.get("target_price")),
        None,
    )
    target_r = safe_float(
        first_present(
            limit_oracle.get("target_r"),
            candidate.get("risk_reward_ratio"),
            candidate.get("rr"),
        ),
        1.0,
    )
    adverse_entry_drift_r = guarded_market_fallback_adverse_entry_drift_r(
        side=str(candidate.get("side") or ""),
        original_entry_price=original_entry,
        fallback_entry_price=fallback_entry,
        original_stop_price=original_stop,
    )
    max_adverse_entry_drift_r = min(
        policy_config["max_adverse_entry_drift_r"],
        max(0.0, target_r),
    )
    if (
        adverse_entry_drift_r is None
        or adverse_entry_drift_r > max_adverse_entry_drift_r
    ):
        decision = dict(decision)
        decision.update(
            {
                "status": "not_eligible",
                "reason": "fallback_entry_adverse_drift_above_thesis_geometry_ceiling",
                "reasons": list(decision.get("reasons") or [])
                + ["fallback_entry_adverse_drift_above_thesis_geometry_ceiling"],
                "fallback_fill_time_utc": iso(fallback_fill_time),
                "fallback_fill_price": round(fallback_entry, 8),
                "fallback_fill_price_source": fallback_fill_price_source,
                "fallback_entry_adverse_drift_r": adverse_entry_drift_r,
                "max_adverse_entry_drift_r": max_adverse_entry_drift_r,
                "fallback_policy_thresholds_used_only_predecision_fields": True,
                "fallback_decision_used_elapsed_market_path": True,
                "fallback_execution_used_elapsed_market_path": False,
                "guarded_market_fallback_used_only_predecision_fields": False,
                "limit_requested_entry_price": round(original_entry, 8),
                "limit_requested_stop_loss": round(original_stop, 8),
                "limit_requested_take_profit_1": (
                    round(original_target, 8) if original_target is not None else None
                ),
            }
        )
        decision["policy_hash_sha256"] = stable_sha256(decision)
        result["decision"] = decision
        if marketable_fallback_contract_required:
            result["fallback_contract_unmet"] = True
            result["oracle"] = package_marketable_guarded_fallback_contract_unmet_oracle(
                limit_oracle=limit_oracle,
                decision=decision,
            )
        return result
    fallback_stop, fallback_target = market_fallback_geometry(
        side=str(candidate.get("side") or ""),
        fallback_entry_price=fallback_entry,
        original_entry_price=original_entry,
        original_stop_price=original_stop,
        target_r=target_r,
        original_target_price=original_target,
    )
    fallback_geometry_mode = (
        "preserve_original_sl_tp"
        if original_target is not None
        else "derive_target_from_original_risk"
    )
    fallback_geometry_original_sl_tp_preserved = bool(
        original_target is not None
        and fallback_stop == original_stop
        and fallback_target == original_target
    )
    fallback_effective_target_r = market_fallback_effective_target_r(
        side=str(candidate.get("side") or ""),
        fallback_entry_price=fallback_entry,
        fallback_stop_price=fallback_stop,
        fallback_target_price=fallback_target,
    )
    min_effective_target_r_after_fallback = policy_config[
        "min_effective_target_r_after_fallback"
    ]
    if (
        fallback_effective_target_r is None
        or fallback_effective_target_r < min_effective_target_r_after_fallback
    ):
        decision = dict(decision)
        decision.update(
            {
                "status": "not_eligible",
                "reason": "fallback_effective_target_r_below_floor",
                "reasons": list(decision.get("reasons") or [])
                + ["fallback_effective_target_r_below_floor"],
                "fallback_fill_time_utc": iso(fallback_fill_time),
                "fallback_fill_price": round(fallback_entry, 8),
                "fallback_fill_price_source": fallback_fill_price_source,
                "fallback_stop_loss": round(fallback_stop, 8),
                "fallback_take_profit_1": round(fallback_target, 8),
                "fallback_target_r": round(target_r, 8),
                "fallback_effective_target_r": fallback_effective_target_r,
                "min_effective_target_r_after_fallback": (
                    min_effective_target_r_after_fallback
                ),
                "fallback_entry_adverse_drift_r": adverse_entry_drift_r,
                "max_adverse_entry_drift_r": max_adverse_entry_drift_r,
                "fallback_geometry_mode": fallback_geometry_mode,
                "fallback_geometry_reanchored": False,
                "fallback_geometry_original_sl_tp_preserved": (
                    fallback_geometry_original_sl_tp_preserved
                ),
                "fallback_policy_thresholds_used_only_predecision_fields": True,
                "fallback_decision_used_elapsed_market_path": True,
                "fallback_execution_used_elapsed_market_path": False,
                "guarded_market_fallback_used_only_predecision_fields": False,
                "limit_requested_entry_price": round(original_entry, 8),
                "limit_requested_stop_loss": round(original_stop, 8),
                "limit_requested_take_profit_1": (
                    round(original_target, 8) if original_target is not None else None
                ),
            }
        )
        decision["policy_hash_sha256"] = stable_sha256(decision)
        result["decision"] = decision
        if marketable_fallback_contract_required:
            result["fallback_contract_unmet"] = True
            result["oracle"] = package_marketable_guarded_fallback_contract_unmet_oracle(
                limit_oracle=limit_oracle,
                decision=decision,
            )
        return result
    fallback_extra_cost_r = policy_config["guarded_market_extra_cost_r"]
    candidate_ev_r = safe_float(decision.get("candidate_ev_r"), 0.0)
    drift_adjusted_expected_net_r_after_fallback = round(
        candidate_ev_r
        - base_expected_cost_r
        - fallback_extra_cost_r
        - max(0.0, safe_float(adverse_entry_drift_r, 0.0)),
        9,
    )
    min_drift_adjusted_expected_net_r_after_fallback = policy_config[
        "min_drift_adjusted_candidate_expected_net_r_after_fallback"
    ]
    if (
        drift_adjusted_expected_net_r_after_fallback
        < min_drift_adjusted_expected_net_r_after_fallback
    ):
        decision = dict(decision)
        decision.update(
            {
                "status": "not_eligible",
                "reason": "candidate_expected_net_r_after_fallback_adverse_drift_below_floor",
                "reasons": list(decision.get("reasons") or [])
                + [
                    "candidate_expected_net_r_after_fallback_adverse_drift_below_floor"
                ],
                "fallback_fill_time_utc": iso(fallback_fill_time),
                "fallback_fill_price": round(fallback_entry, 8),
                "fallback_fill_price_source": fallback_fill_price_source,
                "fallback_entry_adverse_drift_r": adverse_entry_drift_r,
                "max_adverse_entry_drift_r": max_adverse_entry_drift_r,
                "fallback_execution_surcharge_r": fallback_extra_cost_r,
                "candidate_expected_net_r_after_fallback_adverse_drift": (
                    drift_adjusted_expected_net_r_after_fallback
                ),
                "min_drift_adjusted_candidate_expected_net_r_after_fallback": (
                    min_drift_adjusted_expected_net_r_after_fallback
                ),
                "fallback_policy_thresholds_used_only_predecision_fields": True,
                "fallback_decision_used_elapsed_market_path": True,
                "fallback_execution_used_elapsed_market_path": False,
                "guarded_market_fallback_used_only_predecision_fields": False,
                "limit_requested_entry_price": round(original_entry, 8),
                "limit_requested_stop_loss": round(original_stop, 8),
                "limit_requested_take_profit_1": (
                    round(original_target, 8) if original_target is not None else None
                ),
            }
        )
        decision["policy_hash_sha256"] = stable_sha256(decision)
        result["decision"] = decision
        if marketable_fallback_contract_required:
            result["fallback_contract_unmet"] = True
            result["oracle"] = package_marketable_guarded_fallback_contract_unmet_oracle(
                limit_oracle=limit_oracle,
                decision=decision,
            )
        return result
    fallback_candidate = {
        **dict(candidate),
        "entry_price": fallback_entry,
        "stop_loss": fallback_stop,
        "take_profit_1": fallback_target,
        "limit_requested_entry_price": original_entry,
        "limit_requested_stop_loss": original_stop,
        "limit_requested_take_profit_1": original_target,
        "original_limit_entry_price": original_entry,
        "original_limit_stop_loss": original_stop,
        "original_limit_take_profit_1": original_target,
        "fallback_entry_adverse_drift_r": adverse_entry_drift_r,
        "max_adverse_entry_drift_r": max_adverse_entry_drift_r,
        "fallback_effective_target_r": fallback_effective_target_r,
        "min_effective_target_r_after_fallback": (
            min_effective_target_r_after_fallback
        ),
        "fallback_geometry_mode": fallback_geometry_mode,
        "fallback_geometry_reanchored": False,
        "fallback_geometry_original_sl_tp_preserved": (
            fallback_geometry_original_sl_tp_preserved
        ),
        "risk_reward_ratio": target_r,
        "rr": target_r,
    }
    fallback_candidate = canonicalize_candidate_geometry(
        fallback_candidate,
        source="guarded_market_fallback_replay_geometry",
    )
    if source == "tick":
        normalized_rows = []
        for row in path_rows:
            normalized = dict(row)
            normalized.setdefault(
                "ts_utc",
                normalized.get("time_utc") or normalized.get("time"),
            )
            normalized_rows.append(normalized)
        fallback_oracle = infer_microstructure_ordered_path_from_ticks(
            ticks=normalized_rows,
            side=str(candidate.get("side") or ""),
            entry_price=fallback_entry,
            stop_price=fallback_stop,
            target_price=fallback_target,
            asof_utc=iso(fallback_fill_time) or "",
            fill_already_confirmed=True,
            fill_time_utc=iso(fallback_fill_time),
        ).as_dict()
        fallback_oracle["source"] = "tick"
        fallback_oracle["ordered_tick_truth_satisfied"] = (
            path_source.spec.ordered_tick_truth_satisfied is True
        )
    else:
        fallback_oracle = infer_ordered_path_from_m1(
            bars=path_rows,
            side=str(candidate.get("side") or ""),
            entry_price=fallback_entry,
            stop_price=fallback_stop,
            target_price=fallback_target,
            asof_utc=iso(fallback_fill_time) or "",
            fill_already_confirmed=True,
            fill_time_utc=iso(fallback_fill_time),
        ).as_dict()
        fallback_oracle["source"] = "m1"
        fallback_oracle["ordered_tick_truth_satisfied"] = False
    fallback_oracle = attach_close_mark(
        oracle=fallback_oracle,
        rows=path_rows,
        candidate=fallback_candidate,
        expiry=expiry,
    )
    decision = dict(decision)
    decision.update(
        {
            "status": "applied",
            "reason": "guarded_market_fallback_simulated_after_limit_not_filled_by_probe_time",
            "fallback_fill_time_utc": iso(fallback_fill_time),
            "fallback_fill_price": round(fallback_entry, 8),
            "fallback_fill_price_source": fallback_fill_price_source,
            "fallback_stop_loss": round(fallback_stop, 8),
            "fallback_take_profit_1": round(fallback_target, 8),
            "fallback_target_r": round(target_r, 8),
            "fallback_effective_target_r": fallback_effective_target_r,
            "min_effective_target_r_after_fallback": (
                min_effective_target_r_after_fallback
            ),
            "fallback_source": source,
            "fallback_entry_adverse_drift_r": adverse_entry_drift_r,
            "max_adverse_entry_drift_r": max_adverse_entry_drift_r,
            "fallback_geometry_mode": fallback_geometry_mode,
            "fallback_geometry_reanchored": False,
            "fallback_geometry_original_sl_tp_preserved": (
                fallback_geometry_original_sl_tp_preserved
            ),
            "fallback_policy_thresholds_used_only_predecision_fields": True,
            "fallback_decision_used_elapsed_market_path": True,
            "fallback_execution_used_elapsed_market_path": True,
            "guarded_market_fallback_used_only_predecision_fields": False,
            "limit_requested_entry_price": round(original_entry, 8),
            "limit_requested_stop_loss": round(original_stop, 8),
            "limit_requested_take_profit_1": (
                round(original_target, 8) if original_target is not None else None
            ),
        }
    )
    decision["policy_hash_sha256"] = stable_sha256(decision)
    fallback_expected_cost_r = round(base_expected_cost_r + fallback_extra_cost_r, 8)
    fallback_candidate.update(
        {
            "expected_cost_r": fallback_expected_cost_r,
            "cost_r": fallback_expected_cost_r,
            "broker_pretrade_cost_r": broker_pretrade_cost_r,
            "fallback_execution_surcharge_r": fallback_extra_cost_r,
            "total_execution_cost_r": fallback_expected_cost_r,
            "guarded_market_fallback_extra_cost_r": fallback_extra_cost_r,
        }
    )
    fallback_oracle.update(
        {
            "limit_first_fill_status": limit_oracle.get("fill_status"),
            "limit_first_terminal_outcome": limit_oracle.get("terminal_outcome"),
            "limit_first_fill_time_utc": limit_oracle.get("fill_time_utc"),
            "limit_first_entry_price": candidate.get("entry_price"),
            "fill_status": "filled_by_guarded_market_fallback_at_fallback_time",
            "fill_realism_class": "guarded_market_fallback_elapsed_path",
            "fill_realism_executable": True,
            "fill_realism_reason": (
                "guarded_market_fallback_fill_at_elapsed_postdecision_row"
            ),
            "fill_realism_source_boundary": (
                "local_replay_guarded_market_fallback_elapsed_path_no_broker_authority"
            ),
            "fill_realism_queue_model": "market_fallback_not_passive_queue",
            "replay_order_fillability_policy_v1": decision,
            "replay_order_fillability_policy_status": "guarded_market_fallback_applied",
            "guarded_market_fallback_applied": True,
            "guarded_market_fallback_fill_time_utc": iso(fallback_fill_time),
            "guarded_market_fallback_fill_price": round(fallback_entry, 8),
            "guarded_market_fallback_fill_price_source": fallback_fill_price_source,
            "guarded_market_fallback_extra_cost_r": fallback_extra_cost_r,
            "guarded_market_fallback_expected_cost_r": fallback_expected_cost_r,
            "fallback_stop_loss": round(fallback_stop, 8),
            "fallback_take_profit_1": round(fallback_target, 8),
            "fallback_target_r": round(target_r, 8),
            "fallback_effective_target_r": fallback_effective_target_r,
            "min_effective_target_r_after_fallback": (
                min_effective_target_r_after_fallback
            ),
            "fallback_entry_adverse_drift_r": adverse_entry_drift_r,
            "max_adverse_entry_drift_r": max_adverse_entry_drift_r,
            "fallback_geometry_mode": fallback_geometry_mode,
            "fallback_geometry_reanchored": False,
            "fallback_geometry_original_sl_tp_preserved": (
                fallback_geometry_original_sl_tp_preserved
            ),
            "limit_requested_entry_price": round(original_entry, 8),
            "limit_requested_stop_loss": round(original_stop, 8),
            "limit_requested_take_profit_1": (
                round(original_target, 8) if original_target is not None else None
            ),
            "broker_pretrade_cost_r": broker_pretrade_cost_r,
            "fallback_execution_surcharge_r": fallback_extra_cost_r,
            "total_execution_cost_r": fallback_expected_cost_r,
            "guarded_market_fallback_policy_hash_sha256": decision[
                "policy_hash_sha256"
            ],
            "guarded_market_fallback_used_only_predecision_fields": False,
            "fallback_policy_thresholds_used_only_predecision_fields": (
                decision.get(
                    "fallback_policy_thresholds_used_only_predecision_fields"
                )
            ),
            "fallback_decision_used_elapsed_market_path": decision.get(
                "fallback_decision_used_elapsed_market_path"
            ),
            "fallback_eligibility_used_only_predecision_fields": False,
            "fallback_execution_used_elapsed_market_path": decision.get(
                "fallback_execution_used_elapsed_market_path"
            ),
        }
    )
    fallback_oracle = classify_ordered_path_fill_realism(
        fallback_oracle,
        source=str(fallback_oracle.get("source") or source or ""),
        immediate_marketable_fill=False,
    )
    fallback_fill_status = str(fallback_oracle.get("fill_status") or "")
    fallback_fill_executable = (
        fallback_fill_status.startswith("filled")
        and fallback_oracle.get("fill_realism_executable") is not False
        and fallback_oracle.get("diagnostic_fill_only") is not True
    )
    if not fallback_fill_executable:
        block_reason = (
            str(fallback_oracle.get("fill_realism_reason") or "").strip()
            or "guarded_market_fallback_fill_realism_not_executable"
        )
        decision = dict(decision)
        decision_reasons = list(decision.get("reasons") or [])
        if block_reason not in decision_reasons:
            decision_reasons.append(block_reason)
        if "guarded_market_fallback_fill_realism_not_executable" not in decision_reasons:
            decision_reasons.append("guarded_market_fallback_fill_realism_not_executable")
        decision.update(
            {
                "status": "not_eligible",
                "reason": "guarded_market_fallback_fill_realism_not_executable",
                "reasons": decision_reasons,
                "guarded_market_fallback_applied": False,
                "guarded_market_fallback_fill_realism_blocked": True,
                "guarded_market_fallback_fill_realism_class": fallback_oracle.get(
                    "fill_realism_class"
                ),
                "guarded_market_fallback_fill_realism_reason": block_reason,
                "fallback_execution_used_elapsed_market_path": False,
            }
        )
        decision["policy_hash_sha256"] = stable_sha256(decision)
        fallback_oracle.update(
            {
                "replay_order_fillability_policy_v1": decision,
                "replay_order_fillability_policy_status": (
                    "guarded_market_fallback_fill_realism_not_executable"
                ),
                "guarded_market_fallback_applied": False,
                "guarded_market_fallback_fill_realism_blocked": True,
                "guarded_market_fallback_fill_realism_class": fallback_oracle.get(
                    "fill_realism_class"
                ),
                "guarded_market_fallback_fill_realism_reason": block_reason,
                "guarded_market_fallback_policy_hash_sha256": decision[
                    "policy_hash_sha256"
                ],
                "fallback_execution_used_elapsed_market_path": False,
            }
        )
        result.update(
            {
                "applied": False,
                "decision": decision,
                "oracle": fallback_oracle,
                "path_source": path_source,
                "path_rows": path_rows,
                "candidate_for_outcome": fallback_candidate,
                "expected_cost_r": fallback_expected_cost_r,
                "broker_pretrade_cost_r": broker_pretrade_cost_r,
                "fallback_execution_surcharge_r": fallback_extra_cost_r,
                "total_execution_cost_r": fallback_expected_cost_r,
                "fallback_extra_cost_r": fallback_extra_cost_r,
            }
        )
        return result
    result.update(
        {
            "applied": True,
            "decision": decision,
            "oracle": fallback_oracle,
            "path_source": path_source,
            "path_rows": path_rows,
            "candidate_for_outcome": fallback_candidate,
            "expected_cost_r": fallback_expected_cost_r,
            "broker_pretrade_cost_r": broker_pretrade_cost_r,
            "fallback_execution_surcharge_r": fallback_extra_cost_r,
            "total_execution_cost_r": fallback_expected_cost_r,
            "fallback_extra_cost_r": fallback_extra_cost_r,
        }
    )
    return result


def evaluate_candidate_v4(
    *,
    candidate: Mapping[str, Any],
    config: Mapping[str, Any],
    source: ResolvedSource,
    path_sources: Mapping[str, ResolvedSource] | None = None,
    risk_pct: float,
    asof_utc: str,
    mso: Any,
    open_positions: Iterable[Mapping[str, Any]] = (),
    pending_orders: Iterable[Mapping[str, Any]] = (),
    defer_live_packet_hash: bool = False,
) -> dict[str, Any]:
    occurrence_claimed = candidate_occurrence_contract_claimed(candidate)
    if occurrence_claimed:
        verified_occurrence_key = candidate_occurrence_key_from_fields(candidate)
        if (
            not candidate.get(CANDIDATE_OCCURRENCE_KEY_FIELD)
            or not verified_occurrence_key
            or verified_occurrence_key
            != candidate.get(CANDIDATE_OCCURRENCE_KEY_FIELD)
        ):
            raise ValueError(
                "candidate_source_safe_occurrence_invalid_before_selector"
            )
        candidate = {
            **dict(candidate),
            "candidate_source_safe_admission_status": (
                "validated_immediately_preselector"
            ),
            "candidate_source_safe_admission_fingerprint_sha256": candidate.get(
                "candidate_source_safe_fingerprint_sha256"
            ),
        }
    probability_truth_mode = wave21_full_flow_truth_mode_enabled(config)
    supplied_outcome_calibration = (
        candidate.get(GEOMETRY_BOUND_OUTCOME_CALIBRATION_KEY)
        if probability_truth_mode
        else None
    )
    supplied_outcome_calibration = (
        supplied_outcome_calibration
        if isinstance(supplied_outcome_calibration, Mapping)
        else None
    )
    if probability_truth_mode:
        candidate = strip_probability_economic_authority(candidate)
        # Only this function's own accepted disposition may place the
        # calibration key downstream; a candidate-supplied wrapper -- even a
        # self-consistent replay of a previously accepted one -- must not
        # ride through as data while the stamps disagree.
        candidate.pop(GEOMETRY_BOUND_OUTCOME_CALIBRATION_KEY, None)
    pretrade_cost_packet = broker_calibrated_replay_cost_packet(
        candidate=candidate,
        config=config,
        path_sources=path_sources,
        risk_pct=risk_pct,
        asof_utc=asof_utc,
    )
    cost_r = safe_float(
        pretrade_cost_packet.get("total_cost_r"),
        broker_replay_default_total_cost_r(config),
    )
    candidate = {
        **dict(candidate),
        "expected_cost_r": cost_r,
        "cost_r": cost_r,
        "broker_calibrated_expected_cost_r": cost_r,
        "candidate_cost_r_fallback_diagnostic": pretrade_cost_packet.get(
            "old_timewarp_candidate_cost_r_fallback_diagnostic"
        ),
        "old_proxy_vs_broker_calibrated_delta_r": pretrade_cost_packet.get(
            "old_proxy_vs_broker_calibrated_delta_r"
        ),
        "spread_r_at_candidate": pretrade_cost_packet.get("spread_r"),
        "pretrade_broker_net_cost_packet": dict(pretrade_cost_packet),
    }
    probability_context = build_probability_context(
        candidate,
        asof_utc,
        mso,
        cost_r=cost_r,
    )
    probability_decision = evaluate_probability_debate_team_v4(probability_context, dict(config))
    probability_record = probability_decision.to_record()
    if probability_truth_mode:
        probability_record = strip_probability_economic_authority(probability_record)
    else:
        for thesis_row in probability_record.get("theses", []):
            if isinstance(thesis_row, dict) and isinstance(
                thesis_row.get("confidence_calibration"),
                Mapping,
            ):
                thesis_row["confidence_calibration"]["score"] = thesis_row[
                    "confidence_calibration"
                ].get("calibrated_probability", thesis_row.get("probability"))
                thesis_row["calibration"] = thesis_row["confidence_calibration"].get(
                    "calibrated_probability",
                    thesis_row.get("probability"),
                )
    action = side_to_probability_action(str(candidate.get("side") or ""))
    thesis = probability_thesis(probability_record, action)
    if probability_truth_mode:
        probability = None
        ev_r = None
        expected_net_r = None
    else:
        probability = safe_float(thesis.get("probability"), 0.55)
        ev_r = safe_float(thesis.get("EV") or thesis.get("ev_r"), 0.2)
        expected_net_r = round(ev_r - cost_r, 12)
    economic_risk_pct = 0.0 if probability_truth_mode else risk_pct
    lifecycle_packet = build_lifecycle_packet(
        candidate=candidate,
        asof_utc=asof_utc,
        risk_pct=economic_risk_pct,
        probability=probability,
        ev_r=ev_r,
        config=config,
        open_positions=open_positions,
        pending_orders=pending_orders,
    )
    pre_selector_policy_router_record = dynamic_policy_router_record(
        candidate=candidate,
        config=config,
        risk_pct=risk_pct,
    )
    runtime_config = (
        config.get("gtos_vnext_runtime")
        if isinstance(config.get("gtos_vnext_runtime"), Mapping)
        else {}
    )
    selector_event = build_selector_event(
        candidate=candidate,
        probability_record=probability_record,
        lifecycle_packet=lifecycle_packet,
        risk_pct=economic_risk_pct,
        cost_r=cost_r,
        pretrade_cost_packet=pretrade_cost_packet,
        asof_utc=asof_utc,
        mso=mso,
        policy_router_record=pre_selector_policy_router_record,
    )
    if probability_truth_mode:
        selector_event = apply_probability_truth_to_event(
            selector_event,
            probability_debate=probability_record,
        )
    selected_policy_expected_net_fields_builder = (
        (lambda **_kwargs: {})
        if probability_truth_mode
        else owner_approved_reconstructed_proxy_selected_policy_expected_net_fields
    )
    selected_policy_expected_net_fields = selected_policy_expected_net_fields_builder(
        candidate={
            **dict(candidate),
            **dict(selector_event),
        },
        expected_net_r=selector_event.get("expected_net_r") or expected_net_r,
        selected_policy=pre_selector_policy_router_record.get("selected_policy"),
        enabled=runtime_config.get(
            "broad_live_as_if_replay_owner_approved_reconstructed_proxy_selected_policy_expected_net_enabled"
        ),
        source_boundary_note=runtime_config.get(
            "broad_live_as_if_replay_owner_approved_reconstructed_proxy_selected_policy_expected_net_boundary"
        ),
        source_path=runtime_config.get(
            "broad_live_as_if_replay_owner_approved_reconstructed_proxy_selected_policy_expected_net_source_path"
        ),
        source_sha256=runtime_config.get(
            "broad_live_as_if_replay_owner_approved_reconstructed_proxy_selected_policy_expected_net_source_sha256"
        ),
        source_semantic_sha256=runtime_config.get(
            "broad_live_as_if_replay_owner_approved_reconstructed_proxy_selected_policy_expected_net_source_semantic_sha256"
        ),
        source_artifact_sha256=runtime_config.get(
            "broad_live_as_if_replay_owner_approved_reconstructed_proxy_selected_policy_expected_net_source_artifact_sha256"
        ),
        source_digest_semantics=runtime_config.get(
            "broad_live_as_if_replay_owner_approved_reconstructed_proxy_selected_policy_expected_net_source_digest_semantics"
        ),
    )
    if selected_policy_expected_net_fields:
        candidate = {
            **dict(candidate),
            **selected_policy_expected_net_fields,
        }
        selector_event = {
            **dict(selector_event),
            **selected_policy_expected_net_fields,
        }
    selector_decision = evaluate_selector_v4_admission(
        selector_event,
        config,
        package_generated_utc=asof_utc,
    )
    selector_record = selector_decision.to_record()
    selector_package_parity = scheduler_package_parity_fields(selector_record)
    selector_package_selected_policy_expected_net_fields = (
        selected_policy_expected_net_fields_builder(
            candidate={
                **dict(candidate),
                **dict(selector_event),
                **dict(selector_record),
                **dict(selector_package_parity),
            },
            expected_net_r=selector_event.get("expected_net_r") or expected_net_r,
            selected_policy=first_present(
                pre_selector_policy_router_record.get("selected_policy"),
                selector_event.get("selected_policy_for_expected_net_r"),
                selector_event.get("expected_net_r_selected_policy"),
                "momentum_exhaustion",
            ),
            enabled=runtime_config.get(
                "broad_live_as_if_replay_owner_approved_reconstructed_proxy_selected_policy_expected_net_enabled"
            ),
            source_boundary_note=runtime_config.get(
                "broad_live_as_if_replay_owner_approved_reconstructed_proxy_selected_policy_expected_net_boundary"
            ),
            source_path=runtime_config.get(
                "broad_live_as_if_replay_owner_approved_reconstructed_proxy_selected_policy_expected_net_source_path"
            ),
            source_sha256=runtime_config.get(
                "broad_live_as_if_replay_owner_approved_reconstructed_proxy_selected_policy_expected_net_source_sha256"
            ),
            source_semantic_sha256=runtime_config.get(
                "broad_live_as_if_replay_owner_approved_reconstructed_proxy_selected_policy_expected_net_source_semantic_sha256"
            ),
            source_artifact_sha256=runtime_config.get(
                "broad_live_as_if_replay_owner_approved_reconstructed_proxy_selected_policy_expected_net_source_artifact_sha256"
            ),
            source_digest_semantics=runtime_config.get(
                "broad_live_as_if_replay_owner_approved_reconstructed_proxy_selected_policy_expected_net_source_digest_semantics"
            ),
        )
    )
    if selector_package_selected_policy_expected_net_fields:
        selected_policy_expected_net_fields = {
            **selected_policy_expected_net_fields,
            **selector_package_selected_policy_expected_net_fields,
        }
        candidate = {
            **dict(candidate),
            **selector_package_selected_policy_expected_net_fields,
        }
        selector_event = {
            **dict(selector_event),
            **selector_package_selected_policy_expected_net_fields,
        }
        selector_decision = evaluate_selector_v4_admission(
            selector_event,
            config,
            package_generated_utc=asof_utc,
        )
        selector_record = {
            **selector_decision.to_record(),
            **selector_package_selected_policy_expected_net_fields,
        }
    policy_router_record = dynamic_policy_router_record(
        candidate=candidate,
        config=config,
        risk_pct=safe_float(
            selector_record.get("final_risk_pct"),
            economic_risk_pct,
        ),
    )
    selected_policy = str(policy_router_record.get("selected_policy") or "momentum_exhaustion")
    execution_policy_id = policy_router_record.get("execution_policy_id")
    selected_policy_params = selected_policy_params_from_router_record(
        policy_router_record
    )
    post_router_selected_policy_expected_net_fields = (
        selected_policy_expected_net_fields_builder(
            candidate={
                **dict(candidate),
                **dict(selector_event),
                **dict(selector_record),
                **scheduler_package_parity_fields(selector_record),
            },
            expected_net_r=selector_event.get("expected_net_r") or expected_net_r,
            selected_policy=selected_policy,
            enabled=runtime_config.get(
                "broad_live_as_if_replay_owner_approved_reconstructed_proxy_selected_policy_expected_net_enabled"
            ),
            source_boundary_note=runtime_config.get(
                "broad_live_as_if_replay_owner_approved_reconstructed_proxy_selected_policy_expected_net_boundary"
            ),
            source_path=runtime_config.get(
                "broad_live_as_if_replay_owner_approved_reconstructed_proxy_selected_policy_expected_net_source_path"
            ),
            source_sha256=runtime_config.get(
                "broad_live_as_if_replay_owner_approved_reconstructed_proxy_selected_policy_expected_net_source_sha256"
            ),
            source_semantic_sha256=runtime_config.get(
                "broad_live_as_if_replay_owner_approved_reconstructed_proxy_selected_policy_expected_net_source_semantic_sha256"
            ),
            source_artifact_sha256=runtime_config.get(
                "broad_live_as_if_replay_owner_approved_reconstructed_proxy_selected_policy_expected_net_source_artifact_sha256"
            ),
            source_digest_semantics=runtime_config.get(
                "broad_live_as_if_replay_owner_approved_reconstructed_proxy_selected_policy_expected_net_source_digest_semantics"
            ),
        )
    )
    if post_router_selected_policy_expected_net_fields:
        selected_policy_expected_net_fields = {
            **selected_policy_expected_net_fields,
            **post_router_selected_policy_expected_net_fields,
        }
        candidate = {
            **dict(candidate),
            **post_router_selected_policy_expected_net_fields,
        }
        selector_event = {
            **dict(selector_event),
            **post_router_selected_policy_expected_net_fields,
        }
        selector_record = {
            **dict(selector_record),
            **post_router_selected_policy_expected_net_fields,
        }
    dynamic_geometry_trade_params = {
        "entry_price": candidate.get("entry_price"),
        "stop_loss": candidate.get("stop_loss"),
        "direction": candidate.get("side"),
        **dynamic_geometry_trade_params_from_policy_params(selected_policy_params),
    }
    geometry_contract = build_target_stop_geometry_v4_contract(
        config=config,
        selected_policy=selected_policy,
        execution_policy_id=execution_policy_id,
        source_event={
            "source_path_feature_status": "computed_from_source_ohlc_asof_timewarp_replay",
            "source_window_complete": True,
            "ordered_path_status": "pending_post_asof_replay",
            "selected_policy_ordered_path_status": "ordered_path_pending_postdecision_replay",
            "selected_policy_same_bar_ambiguous": False,
            "moonshot_dynamic_execution_router_v4": policy_router_record,
            "selected_policy_params": selected_policy_params or None,
        },
        trade_params=dynamic_geometry_trade_params,
        entry_price=candidate.get("entry_price"),
        stop_loss=candidate.get("stop_loss"),
        direction=candidate.get("side"),
        final_target_r=selected_policy_params.get("final_target_r")
        if selected_policy_params
        else None,
        stage="timewarp_asof_candidate_decision",
    )
    geometry_destination = geometry_contract.get("target_destination")
    geometry_destination = geometry_destination if isinstance(geometry_destination, Mapping) else {}
    final_target_r = safe_float(
        first_present(
            geometry_contract.get("final_target_r"),
            geometry_destination.get("final_target_r"),
            candidate.get("risk_reward_ratio"),
        ),
        safe_float(candidate.get("risk_reward_ratio"), 1.5),
    )
    risk_distance = abs(safe_float(candidate.get("entry_price")) - safe_float(candidate.get("stop_loss")))
    dynamic_target = None
    if risk_distance > 0:
        if str(candidate.get("side") or "").upper() == "LONG":
            dynamic_target = safe_float(candidate.get("entry_price")) + final_target_r * risk_distance
        else:
            dynamic_target = safe_float(candidate.get("entry_price")) - final_target_r * risk_distance
    candidate = {
        **dict(candidate),
        "risk_reward_ratio": final_target_r,
        "rr": final_target_r,
        "take_profit_1": dynamic_target if dynamic_target is not None else candidate.get("take_profit_1"),
        "fill_probability": selector_event.get("fill_probability"),
        "heuristic_fill_probability": selector_event.get("heuristic_fill_probability"),
        "predecision_limit_fillability": selector_event.get(
            "predecision_limit_fillability"
        ),
        "dynamic_geometry_applied": True,
        "dynamic_geometry_policy": geometry_contract.get("selected_policy"),
        "dynamic_execution_policy_id": geometry_contract.get("execution_policy_id"),
        "moonshot_dynamic_execution_router_v4": policy_router_record,
    }
    candidate = canonicalize_candidate_geometry(
        candidate,
        source="timewarp_dynamic_target_stop_geometry_v4",
    )
    if probability_truth_mode:
        candidate = strip_probability_economic_authority(candidate)
        candidate.pop(GEOMETRY_BOUND_OUTCOME_CALIBRATION_KEY, None)
        outcome_model_supply = _configured_geometry_bound_outcome_model(config)
        if outcome_model_supply is not None:
            outcome_model, outcome_model_artifact_sha256 = outcome_model_supply
            outcome_calibration_packet = (
                build_geometry_bound_outcome_calibration_packet(
                    outcome_model,
                    origin_family=candidate.get("origin_family"),
                    utc_session=candidate.get("session_bucket")
                    or candidate.get("session"),
                    decision_action=candidate.get("side"),
                    decision_time_utc=candidate.get("decision_time_utc")
                    or asof_utc,
                    outcome_horizon_utc=candidate.get("limit_first_expiry_utc"),
                    geometry_contract_hash_sha256=geometry_contract.get(
                        "packet_hash_sha256"
                    ),
                    model_artifact_sha256=outcome_model_artifact_sha256,
                )
            )
            expected_outcome_model_artifact_sha256: str | None = (
                outcome_model_artifact_sha256
            )
        else:
            outcome_calibration_packet = supplied_outcome_calibration
            expected_outcome_model_artifact_sha256 = None
        probability_truth_disposition = geometry_bound_outcome_calibration_disposition(
            outcome_calibration_packet,
            geometry_contract,
            expected_model_artifact_sha256=(
                expected_outcome_model_artifact_sha256
            ),
        )
        candidate.update(
            {
                "probability_truth_status": probability_truth_disposition["status"],
                "probability_truth_reason": probability_truth_disposition["reason"],
                "probability_truth_source_required_field": (
                    probability_truth_disposition["source_required_field"]
                ),
                "probability_truth_economic_authority_allowed": (
                    probability_truth_disposition["economic_authority_allowed"]
                ),
            }
        )
        if (
            outcome_model_supply is not None
            and probability_truth_disposition["economic_authority_allowed"]
            is True
        ):
            candidate[GEOMETRY_BOUND_OUTCOME_CALIBRATION_KEY] = {
                "packet": outcome_calibration_packet,
                "disposition": dict(probability_truth_disposition),
            }
    else:
        probability_truth_disposition = None
    configured_symbol_risk_pct, configured_symbol_risk_source = risk_pct_for_symbol(
        config,
        candidate.get("symbol"),
    )
    configured_symbol_limits = configured_runtime_risk_limits(
        config,
        symbol=candidate.get("symbol"),
    )
    risk_authority_pre_scheduler = {
        "schema_version": "timewarp_v4_runtime_risk_authority_pre_scheduler_v1",
        "risk_authority_status": "pre_scheduler_risk_authority_materialized",
        "risk_per_trade_pct": configured_symbol_risk_pct,
        "risk_config_source": configured_symbol_risk_source,
        "selected_cell_risk_pct": safe_float(
            selector_record.get("final_risk_pct"),
            economic_risk_pct,
        ),
        "scheduler_allocation_status": "pending_scheduler_v4_window_allocation",
        "portfolio_ceiling_pct": configured_symbol_limits["portfolio_ceiling_pct"],
        "cluster_correlation_ceiling_pct": configured_symbol_limits[
            "cluster_correlation_ceiling_pct"
        ],
        "same_symbol_lifecycle_action": lifecycle_packet.get("action"),
        "same_symbol_lifecycle_permitted": lifecycle_packet.get("permitted_order_intent"),
        "prop_firm_headroom_status": "bound_after_scheduler_against_simulated_account",
        "source_boundary": "asof_decision_risk_config_bound_no_post_decision_path",
    }
    risk_authority_pre_scheduler["packet_hash_sha256"] = stable_sha256(
        risk_authority_pre_scheduler
    )
    live_decision_packet = build_live_decision_packet_v4(
        record={
            "decision_pipeline": {
                "probability_debate_v4": (
                    {} if probability_truth_mode else probability_record
                ),
                "selector_v4": selector_record,
                "same_symbol_lifecycle_v4": lifecycle_packet,
                "moonshot_dynamic_execution_router_v4": policy_router_record,
                "dynamic_target_stop_geometry_v4": geometry_contract,
            },
            "gtos_vnext_same_symbol_lifecycle_v4_packet": lifecycle_packet,
            "gtos_vnext_same_symbol_lifecycle_action": lifecycle_packet.get("action"),
            "trade_parameters": {
                "entry_price": candidate.get("entry_price"),
                "stop_loss": candidate.get("stop_loss"),
                "take_profit_1": candidate.get("take_profit_1"),
                "take_profit": candidate.get("take_profit_1"),
                "target_reference": candidate.get("target_reference"),
                "risk_reward_ratio": candidate.get("risk_reward_ratio"),
                "rr": candidate.get("rr"),
                "direction": candidate.get("side"),
                "side": candidate.get("side"),
                "gtos_vnext_same_symbol_lifecycle_v4_packet": lifecycle_packet,
                "gtos_vnext_same_symbol_lifecycle_action": lifecycle_packet.get("action"),
            },
        },
        legacy_packet={
            "candidate_identity": {
                "candidate_id": candidate.get("candidate_id"),
                "symbol": candidate.get("symbol"),
                "broker_symbol": ftmo_symbol(str(candidate.get("symbol") or "")),
            },
            "source_m15": {
                "candle_close_utc": asof_utc,
                "timeframe": "D1/H4/H1/M15",
                "source_path_feature_status": "source_window_complete_live_equivalent_htf_ltf",
                "source_window_complete": True,
            },
            "source_completeness": {"status": "captured"},
            "runtime_decision": {"event": "timewarp_asof_candidate_decision"},
            "final_order_decision": {
                "trade_id": candidate.get("candidate_id"),
                "order_path": "simulated_timewarp_only",
            },
            "selected_cell_risk_proof": risk_authority_pre_scheduler,
        },
        candidate=dict(candidate),
        raw_data={
            "symbol": candidate.get("symbol"),
            "candle_close_utc": asof_utc,
            "source_hash": source.sha256,
            "source_file": str(source.spec.path),
            "decision_input_timeframes": list(PRIMARY_DECISION_TIMEFRAMES),
        },
        runtime_config=dict(config.get("gtos_vnext_runtime") or {}),
        defer_packet_hash=defer_live_packet_hash,
    )
    if probability_truth_mode:
        assert probability_truth_disposition is not None
        live_decision_packet = strip_probability_economic_authority(
            live_decision_packet
        )
        probability_truth_group = live_decision_packet["field_groups"][
            "probability_debate_numeric_theses"
        ]
        probability_truth_group.update(
            {
                "probability_truth_status": probability_truth_disposition["status"],
                "probability_truth_reason": probability_truth_disposition["reason"],
                "probability_truth_source_required_field": (
                    probability_truth_disposition["source_required_field"]
                ),
                "probability_truth_economic_authority_allowed": (
                    probability_truth_disposition["economic_authority_allowed"]
                ),
            }
        )
        packet_hash_material = {
            key: live_decision_packet[key]
            for key in (
                "schema_version",
                "candidate_identity",
                "source_event_hash_sha256",
                "field_groups",
                "semantic_ownership",
                "forbidden_surface_boundary",
            )
        }
        packet_hash_preimage = _stable_sha256_material(packet_hash_material).encode(
            "utf-8"
        )
        if defer_live_packet_hash:
            live_decision_packet["packet_hash_sha256"] = None
            live_decision_packet[DEFERRED_PACKET_HASH_PREIMAGE_KEY] = (
                packet_hash_preimage
            )
        else:
            live_decision_packet["packet_hash_sha256"] = _sha256_hexdigest(
                packet_hash_preimage
            )
    result = {
        "probability_context": probability_context,
        "probability_packet": probability_record,
        "selector_event": selector_event,
        "selector_packet": selector_record,
        "lifecycle_packet": lifecycle_packet,
        "moonshot_dynamic_execution_router_v4": policy_router_record,
        "geometry_contract": geometry_contract,
        "candidate_after_geometry": candidate,
        "live_decision_packet_v4": live_decision_packet,
        "risk_authority_pre_scheduler": risk_authority_pre_scheduler,
        "risk_pct": selector_record.get("final_risk_pct") or risk_pct,
        "candidate_probability": probability,
        "probability": probability,
        "candidate_ev_r": ev_r,
        "ev_r": ev_r,
        "expectancy_r": ev_r,
        "cost_r": cost_r,
        "expected_cost_r": cost_r,
        "candidate_expected_net_r": expected_net_r,
        "expected_net_r": expected_net_r,
        "broker_calibrated_expected_cost_r": cost_r,
        "broker_pretrade_cost_r": cost_r,
        "fallback_execution_surcharge_r": 0.0,
        "total_execution_cost_r": cost_r,
        "candidate_cost_r_fallback_diagnostic": pretrade_cost_packet.get(
            "old_timewarp_candidate_cost_r_fallback_diagnostic"
        ),
        "old_proxy_vs_broker_calibrated_delta_r": pretrade_cost_packet.get(
            "old_proxy_vs_broker_calibrated_delta_r"
        ),
        "pretrade_broker_net_cost_packet": pretrade_cost_packet,
        **selected_policy_expected_net_fields,
        "source_path": str(source.spec.path),
        "source_hash": source.sha256,
    }
    if not probability_truth_mode:
        return result
    assert probability_truth_disposition is not None
    result = strip_probability_economic_authority(result)
    result["risk_pct"] = 0.0
    result.update(
        {
            "probability_truth_status": probability_truth_disposition["status"],
            "probability_truth_reason": probability_truth_disposition["reason"],
            "probability_truth_source_required_field": (
                probability_truth_disposition["source_required_field"]
            ),
            "probability_truth_economic_authority_allowed": (
                probability_truth_disposition["economic_authority_allowed"]
            ),
        }
    )
    return result


_REPLAY_PROOF_HASH_MAX_WORKERS = min(8, max(2, os.cpu_count() or 2))


@lru_cache(maxsize=1)
def _replay_proof_hash_executor() -> ThreadPoolExecutor:
    return ThreadPoolExecutor(
        max_workers=_REPLAY_PROOF_HASH_MAX_WORKERS,
        thread_name_prefix="gtos-replay-proof-hash",
    )


def _sha256_hexdigest(payload: bytes) -> str:
    return hashlib.sha256(payload).hexdigest()


def evaluate_symbol_candidates_with_batched_proof_hashes(
    *,
    candidates: Iterable[Mapping[str, Any]],
    raw_data: Mapping[str, Any],
    asof_utc: str,
    campaign: CampaignConfig,
    day: str,
    decision_core: V4DecisionCycleCore,
    symbol: str,
    config: Mapping[str, Any],
    mso: Any,
    open_snapshot: Iterable[Mapping[str, Any]],
    pending_snapshot: Iterable[Mapping[str, Any]],
    stage_profiler: Any | None,
) -> list[
    tuple[dict[str, Any], dict[str, Any], Any, dict[str, Any], str]
]:
    """Evaluate in source order while hashing proof-only packet bytes in parallel."""

    pending: list[
        tuple[
            dict[str, Any],
            dict[str, Any],
            Any,
            dict[str, Any],
            Future[str],
        ]
    ] = []
    executor = _replay_proof_hash_executor()
    enriched_candidates = enrich_candidates_with_predecision_market_snapshot(
        candidates,
        raw_data,
        asof_utc=asof_utc,
    )
    for candidate in enriched_candidates:
        pre_geometry_candidate = dict(candidate)
        source_candle_time = first_present(
            candidate.get("candle_close_utc"),
            candidate.get("time_utc"),
            candidate.get("source_time_utc"),
        )
        candidate["source_candle_time_utc"] = source_candle_time
        candidate["candle_close_utc"] = source_candle_time
        candidate["decision_time_utc"] = asof_utc
        candidate["candidate_instance_time_utc"] = asof_utc
        candidate["scheduler_asof_utc"] = asof_utc
        candidate["campaign"] = campaign.name
        candidate["phase"] = campaign.phase
        candidate["trading_day"] = day
        with _replay_profile_stage(stage_profiler, "evaluation"):
            _replay_profile_call(stage_profiler, "evaluate_candidate")
            packets = decision_core.evaluate_candidate(
                candidate=candidate,
                symbol=symbol,
                risk_pct=risk_pct_for_symbol(config, symbol)[0],
                asof_utc=asof_utc,
                mso=mso,
                open_positions=open_snapshot,
                pending_orders=pending_snapshot,
                defer_proof_hash=True,
            )
        live_packet = packets.get("live_decision_packet_v4")
        if not isinstance(live_packet, dict):
            raise ValueError("deferred_live_decision_packet_missing")
        preimage = live_packet.pop(
            DEFERRED_PACKET_HASH_PREIMAGE_KEY,
            None,
        )
        if not isinstance(preimage, bytes):
            raise ValueError("deferred_live_decision_packet_preimage_missing")
        future = executor.submit(_sha256_hexdigest, preimage)
        pending.append(
            (
                candidate,
                pre_geometry_candidate,
                source_candle_time,
                packets,
                future,
            )
        )

    packet_sidecar_pending: list[
        tuple[
            dict[str, Any],
            dict[str, Any],
            Any,
            dict[str, Any],
            Future[str],
        ]
    ] = []
    for (
        candidate,
        pre_geometry_candidate,
        source_candle_time,
        packets,
        future,
    ) in pending:
        live_packet = packets["live_decision_packet_v4"]
        live_packet["packet_hash_sha256"] = future.result()
        packet_sidecar_material = _stable_sha256_material(
            compact_payload(
                packets,
                max_bytes=campaign.candidate_ledger_packet_max_bytes,
            )
        ).encode("utf-8")
        packet_sidecar_future = executor.submit(
            _sha256_hexdigest,
            packet_sidecar_material,
        )
        packet_sidecar_pending.append(
            (
                candidate,
                pre_geometry_candidate,
                source_candle_time,
                packets,
                packet_sidecar_future,
            )
        )

    evaluated: list[
        tuple[dict[str, Any], dict[str, Any], Any, dict[str, Any], str]
    ] = []
    for (
        candidate,
        pre_geometry_candidate,
        source_candle_time,
        packets,
        packet_sidecar_future,
    ) in packet_sidecar_pending:
        evaluated.append(
            (
                candidate,
                pre_geometry_candidate,
                source_candle_time,
                packets,
                packet_sidecar_future.result(),
            )
        )
    return evaluated


def selector_ultimate_package_packet(selector_packet: Mapping[str, Any]) -> dict[str, Any]:
    component_scores = selector_packet.get("component_scores")
    component_scores = component_scores if isinstance(component_scores, Mapping) else {}
    package = component_scores.get("ultimate_candidate_package")
    return dict(package) if isinstance(package, Mapping) else {}


def scheduler_package_parity_fields(selector_packet: Mapping[str, Any]) -> dict[str, Any]:
    package = selector_ultimate_package_packet(selector_packet)
    matched_sleeves = package.get("matched_sleeves")
    matched_sleeves = matched_sleeves if isinstance(matched_sleeves, list) else []
    explicit_package_executable = first_present(
        package.get("package_replay_executable_candidate_use_allowed"),
        package.get("replay_candidate_use_allowed_now"),
    )
    raw_source_bound_admission = any(
        _runtime_bool(package.get(key), False)
        for key in (
            "source_bound_package_candidate_use_allowed",
            "ultimate_package_source_bound_candidate_use_allowed",
            "package_replay_source_bound_candidate_use_allowed",
        )
    )
    source_bound_use_allowed = package_source_bound_or_admission_alias_allowed(package)
    source_r_values = [
        safe_float(row.get("combined_source_bound_signal_r"), 0.0)
        for row in matched_sleeves
        if isinstance(row, Mapping)
    ]
    return {
        "ultimate_package_decision_status": package.get("decision_status"),
        "ultimate_package_matched_sleeve_count": safe_float(
            package.get("matched_sleeve_count"),
            0.0,
        ),
        "ultimate_package_admission_sleeve_match_count": safe_float(
            package.get("admission_sleeve_match_count"),
            0.0,
        ),
        "ultimate_package_non_admission_sleeve_match_count": safe_float(
            package.get("non_admission_sleeve_match_count"),
            0.0,
        ),
        "ultimate_package_selector_shadow_score": safe_float(
            package.get("selector_shadow_score"),
            0.0,
        ),
        "ultimate_package_role_disposition": package.get("role_disposition"),
        "ultimate_package_source_bound_candidate_use_allowed": source_bound_use_allowed,
        "package_source_bound_admission_diagnostic": raw_source_bound_admission,
        "package_source_bound_admission_diagnostic_source": (
            "selector_ultimate_candidate_package_packet"
            if raw_source_bound_admission
            else None
        ),
        "package_replay_executable_candidate_use_allowed": (
            _runtime_bool(explicit_package_executable, False)
            if explicit_package_executable is not None
            else None
        ),
        "package_replay_executable_candidate_use_allowed_reason": (
            package.get("package_replay_executable_candidate_use_allowed_reason")
            or (
                "missing_explicit_package_executable_authority"
                if explicit_package_executable is None
                else None
            )
        ),
        "ultimate_package_combined_source_bound_signal_r_sum": round(
            sum(source_r_values),
            9,
        ),
        "ultimate_package_max_combined_source_bound_signal_r": round(
            max(source_r_values) if source_r_values else 0.0,
            9,
        ),
        "ultimate_package_source_bound_r_additive_allowed": False,
        "ultimate_package_source_bound_r_additive_unit": (
            "matched_sleeve_signal_not_candidate_trace"
        ),
        "ultimate_package_source_bound_r_additive_scope": (
            "unique_source_bound_surface_claim"
        ),
        "ultimate_package_matched_sleeve_ids": [
            str(row.get("sleeve_id") or "")
            for row in matched_sleeves
            if isinstance(row, Mapping) and str(row.get("sleeve_id") or "").strip()
        ],
        "ultimate_package_matched_sleeve_authorities": [
            {
                "sleeve_id": str(row.get("sleeve_id") or ""),
                "row_hash_sha256": str(row.get("row_hash_sha256") or ""),
                "framework": str(row.get("framework") or ""),
                "origin_family": str(row.get("origin_family") or ""),
                "side": str(row.get("side") or ""),
                "package_role": str(row.get("package_role") or ""),
            }
            for row in matched_sleeves
            if isinstance(row, Mapping)
            and str(row.get("sleeve_id") or "").strip()
            and is_sha256(row.get("row_hash_sha256"))
        ],
        "ultimate_package_scheduler_parity_evidence_class": (
            "source_bound_package_replay_parity_scheduler_input"
        ),
    }


