def package_execution_attribution_fields(candidate: Mapping[str, Any]) -> dict[str, Any]:
    """Carry package sleeve attribution from candidates into execution ledgers."""

    out = {
        key: candidate.get(key)
        for key in PACKAGE_EXECUTION_ATTRIBUTION_KEYS
        if key in candidate
    }
    tokens = candidate.get("package_session_tokens")
    if isinstance(tokens, (list, tuple)):
        out["package_session_tokens"] = [str(token) for token in tokens]
    elif tokens:
        out["package_session_tokens"] = [str(tokens)]
    matched_ids = out.get("ultimate_package_matched_sleeve_ids")
    if isinstance(matched_ids, list):
        out["ultimate_package_matched_sleeve_ids"] = [str(item) for item in matched_ids]
    matched_member_axis_ids = out.get("ultimate_package_matched_member_axis_ids")
    if isinstance(matched_member_axis_ids, list):
        out["ultimate_package_matched_member_axis_ids"] = [
            str(item) for item in matched_member_axis_ids
        ]
    open_reduced_authority = candidate.get(
        "ultimate_candidate_package_open_reduced_risk_authority"
    )
    open_reduced_authority = (
        open_reduced_authority if isinstance(open_reduced_authority, Mapping) else {}
    )
    reduce_risk_authority = candidate.get("ultimate_candidate_package_reduce_risk_authority")
    reduce_risk_authority = (
        reduce_risk_authority if isinstance(reduce_risk_authority, Mapping) else {}
    )
    primary_family = first_present(
        package_authority_primary_family(
            open_reduced_authority,
            candidate.get("package_open_reduced_authority_family"),
            first_present(
                candidate.get("package_new_entry_authority_selector_reason"),
                candidate.get("selector_reason"),
            ),
        ),
        package_authority_primary_family(
            reduce_risk_authority,
            candidate.get("package_reduce_risk_authority_family"),
            candidate.get("selector_reason"),
        ),
    )
    if primary_family:
        out["package_authority_primary_family"] = primary_family
    for key in SOURCE_REQUIRED_REPLAY_PROOF_ATTRIBUTION_KEYS:
        if key in candidate:
            value = candidate.get(key)
            if isinstance(value, tuple):
                value = list(value)
            out[key] = value
    return out


def candidate_package_new_entry_authority_payload_fields(
    candidate: Mapping[str, Any],
) -> dict[str, Any]:
    """Carry candidate-owned signed authority payloads after scheduler overlays."""

    if not isinstance(candidate, Mapping):
        return {}
    out: dict[str, Any] = {}
    for key in (
        "ultimate_candidate_package_open_reduced_risk_authority",
        "ultimate_candidate_package_reduce_risk_authority",
    ):
        payload = candidate.get(key)
        if isinstance(payload, Mapping):
            out[key] = dict(payload)
    return out


