def executable_identity_fields(
    row: Mapping[str, Any],
    *,
    decision_time_utc: str | None = None,
    selected_candidate_ids: Iterable[Any] | None = None,
    selected_candidate_id: str | None = None,
) -> dict[str, Any]:
    """Top-level replay identity tuple used by parity and verifier ledgers."""

    decision_window_time = str(
        first_present(
            decision_time_utc,
            row.get("decision_time_utc"),
            row.get("candle_close_utc"),
            row.get("source_candle_time_utc"),
        )
        or ""
    )
    identity_fields = canonical_replay_candidate_instance_fields(
        row,
        decision_time_utc=decision_time_utc,
    )
    decision_time = str(
        identity_fields.get("candidate_instance_time_utc") or decision_window_time
    )
    symbol = str(row.get("symbol") or "").upper()
    side_value = str(row.get("side") or row.get("direction") or "").upper()
    raw_selected_ids = (
        selected_candidate_ids
        if selected_candidate_ids is not None
        else row.get("selected_candidate_ids")
    )
    if isinstance(raw_selected_ids, str):
        raw_selected_ids = [raw_selected_ids]
    selected_ids = [
        str(item)
        for item in (raw_selected_ids or [])
        if str(item or "").strip()
    ]
    selected_id = str(
        first_present(
            selected_candidate_id,
            row.get("selected_candidate_id"),
            selected_ids[0] if selected_ids else None,
        )
        or ""
    )
    out = {
        "decision_window_id": str(
            first_present(row.get("decision_window_id"), f"timewarp:{decision_time}")
            or ""
        ),
        "candidate_set_id": str(
            first_present(
                row.get("candidate_set_id"),
                f"timewarp_candidate_set:{decision_time}",
            )
            or ""
        ),
        "stable_decision_window_id": str(
            first_present(
                row.get("stable_decision_window_id"),
                f"decision_window:{symbol}:{side_value}:{decision_time}",
            )
            or ""
        ),
        "selected_candidate_id": selected_id or None,
        "selected_candidate_ids": selected_ids,
        "replay_identity_tuple_status": (
            identity_fields.get("candidate_instance_identity_status")
        ),
        **identity_fields,
    }
    for key in EXECUTABLE_IDENTITY_KEYS:
        if key in row and key not in out:
            out[key] = row.get(key)
    return out


def candidate_poi_state_ledger_fields(row: Mapping[str, Any]) -> dict[str, Any]:
    """Project one exact candidate POI atom onto terminal proof surfaces."""

    if not isinstance(row, Mapping):
        return {}
    containers: list[Mapping[str, Any]] = [row]
    for key in (
        "source_fields",
        "candidate_source_fields",
        "candidate_decision_inputs",
        "scheduler_candidate_decision_inputs",
        "trade_parameters",
    ):
        value = row.get(key)
        if isinstance(value, Mapping):
            containers.append(value)
    state: Mapping[str, Any] = {}
    for container in containers:
        value = container.get("poi_state")
        if isinstance(value, Mapping) and value:
            state = value
            break
    lifecycle = row_causal_poi_lifecycle_envelope(row)
    if not state and not lifecycle:
        return {}
    out: dict[str, Any] = {
        "poi_state_required": bool(row_poi_state_required(row)),
    }
    if state:
        out["poi_state"] = dict(state)
        out["poi_state_transfer_status"] = POI_STATE_TRANSFER_STATUS
    if lifecycle:
        lifecycle_failures = causal_poi_lifecycle_contract_failures(
            lifecycle,
            poi_state=state,
            decision_time_utc=first_present(
                row.get("decision_time_utc"),
                row.get("candle_close_utc"),
                lifecycle.get("decision_time_utc"),
            ),
        )
        out.update(
            {
                "causal_poi_lifecycle_required": bool(
                    row_causal_poi_lifecycle_required(row)
                ),
                "causal_poi_lifecycle": dict(lifecycle),
                "causal_poi_lifecycle_hash_sha256": lifecycle.get(
                    "lifecycle_hash_sha256"
                ),
                "causal_poi_lifecycle_contract_status": (
                    "valid_predecision_poi_lifecycle"
                    if not lifecycle_failures
                    else "invalid_predecision_poi_lifecycle"
                ),
                "causal_poi_lifecycle_contract_failures": list(
                    lifecycle_failures
                ),
                "poi_scheduler_rankable_now": lifecycle.get(
                    "scheduler_rankable_now"
                ),
                "poi_execution_allowed_by_lifecycle": lifecycle.get(
                    "execution_allowed_by_poi_lifecycle"
                ),
            }
        )
    for key in (
        *POI_STATE_ATOMIC_FIELDS,
        "poi_state_hash_sha256",
        "poi_state_contract_status",
        "poi_state_contract_failures",
        "poi_state_contract_valid",
        "poi_state_execution_allowed",
        "poi_distance_to_zone_price",
        "poi_distance_to_zone_atr",
        "poi_distance_to_midpoint_price",
        "poi_distance_to_midpoint_atr",
    ):
        value = None
        for container in containers:
            if container.get(key) not in (None, "", [], {}):
                value = container.get(key)
                break
        if value in (None, "", [], {}):
            value = state.get(key)
        if value in (None, "", [], {}):
            continue
        if isinstance(value, Mapping):
            out[key] = dict(value)
        elif isinstance(value, (list, tuple)):
            out[key] = list(value)
        else:
            out[key] = value
    return out


def exact_candidate_ledger_projection_source(
    candidate: Mapping[str, Any],
    candidate_rows: Sequence[Mapping[str, Any]],
    candidate_index_by_instance_key: Mapping[str, int],
) -> Mapping[str, Any]:
    """Return the exact scheduler-backfilled candidate row for terminal ledgers."""

    instance_key = str(
        candidate.get("canonical_replay_candidate_instance_key") or ""
    ).strip()
    row_index = candidate_index_by_instance_key.get(instance_key)
    if not instance_key or not isinstance(row_index, int):
        return candidate
    if row_index < 0 or row_index >= len(candidate_rows):
        return candidate
    projected = candidate_rows[row_index]
    if not isinstance(projected, Mapping):
        return candidate
    if str(
        projected.get("canonical_replay_candidate_instance_key") or ""
    ).strip() != instance_key:
        return candidate
    return projected


def candidate_route_provenance_fields(row: Mapping[str, Any]) -> dict[str, Any]:
    """Causal candidate context shared by trade, order, and missed ledgers."""

    source_fields = (
        row.get("source_fields") if isinstance(row.get("source_fields"), Mapping) else {}
    )
    generation_rule = first_present(
        row.get("generation_rule"),
        source_fields.get("generation_rule"),
    )
    origin_family = first_present(
        row.get("origin_family"),
        row.get("candidate_origin_family"),
        row.get("route_family"),
        row.get("current_framework"),
        row.get("framework"),
        generation_rule,
    )
    candidate_origin_family = first_present(
        row.get("candidate_origin_family"),
        (
            row.get("origin_family")
            if str(row.get("origin_family") or "").startswith("origin_")
            else None
        ),
        (
            row.get("framework")
            if str(row.get("framework") or "").startswith("origin_")
            else None
        ),
        f"origin_{generation_rule}" if generation_rule not in (None, "") else None,
        origin_family,
    )
    framework = first_present(
        row.get("framework"),
        row.get("current_framework"),
        candidate_origin_family,
        origin_family,
    )
    current_framework = first_present(
        row.get("current_framework"),
        row.get("framework"),
        candidate_origin_family,
        origin_family,
    )
    route_session = first_present(
        row.get("route_session"),
        row.get("session_bucket"),
        row.get("session"),
    )
    session = first_present(
        row.get("session"),
        row.get("session_bucket"),
        row.get("route_session"),
    )
    dynamic_geometry_policy = first_present(
        row.get("dynamic_geometry_policy"),
        row.get("candidate_dynamic_geometry_policy"),
        row.get("selected_execution_policy"),
        row.get("expected_net_r_selected_policy"),
        row.get("selected_policy_for_expected_net_r"),
    )
    out = {
        "route_session": route_session,
        "session": session,
        "session_bucket": first_present(
            row.get("session_bucket"),
            route_session,
            session,
        ),
        "framework": framework,
        "current_framework": current_framework,
        "route_family": first_present(row.get("route_family"), origin_family),
        "origin_family": origin_family,
        "candidate_origin_family": candidate_origin_family,
        "generation_rule": generation_rule,
        "setup_family": row.get("setup_family"),
        "dynamic_geometry_policy": dynamic_geometry_policy,
    }
    predecision_features = row.get("predecision_features")
    if isinstance(predecision_features, Mapping):
        out["predecision_features"] = copy.deepcopy(dict(predecision_features))
    out.update(candidate_poi_state_ledger_fields(row))
    return out


def selected_scheduler_instance_identity_fields(
    scheduler_packet: Mapping[str, Any],
    *,
    candidate_id: str | None = None,
    decision_time_utc: str | None = None,
    candidate_occurrence_key: str | None = None,
) -> dict[str, Any]:
    """Expose exact selected scheduler instance lookup metadata on ledger rows."""

    decision = scheduler_packet.get("decision")
    decision = decision if isinstance(decision, Mapping) else {}
    raw_selected_options = decision.get("selected_options")
    selected_options = (
        [row for row in raw_selected_options if isinstance(row, Mapping)]
        if isinstance(raw_selected_options, list)
        else [decision["selected_option"]]
        if isinstance(decision.get("selected_option"), Mapping)
        else []
    )
    derived_option_keys = [
        scheduler_all_options_preserved_option_instance_key(option)
        for option in selected_options
        if str(option.get("candidate_id") or "").strip()
    ]
    if selected_options and any(not key for key in derived_option_keys):
        derived_option_keys = []
    packet_instance_keys_raw = first_present(
        scheduler_packet.get("risk_admitted_final_selected_candidate_instance_keys"),
        decision.get("selected_candidate_instance_keys"),
        derived_option_keys,
    )
    if isinstance(packet_instance_keys_raw, str):
        packet_instance_keys = [packet_instance_keys_raw]
    else:
        packet_instance_keys = [
            str(item)
            for item in (packet_instance_keys_raw or [])
            if str(item or "").strip()
        ]
    selected_identity_conflict = bool(
        derived_option_keys
        and packet_instance_keys
        and derived_option_keys != packet_instance_keys
    )
    statuses_raw = first_present(
        scheduler_packet.get("risk_admitted_final_selected_option_lookup_statuses"),
        decision.get("selected_option_lookup_statuses"),
        [],
    )
    statuses = [
        dict(item)
        for item in (statuses_raw or [])
        if isinstance(item, Mapping)
    ]
    if not statuses and packet_instance_keys:
        statuses = [
            {
                "candidate_id": option.get("candidate_id"),
                "decision_time_utc": next(
                    iter(scheduler_option_exact_time_values(option)), None
                ),
                "selected_instance_key": key,
                "lookup_status": "derived_from_selected_scheduler_option_receipt",
            }
            for option, key in zip(selected_options, packet_instance_keys)
        ]
    candidate_text = str(candidate_id or "").strip()
    decision_time = str(decision_time_utc or "").strip()
    candidate_instance_key = str(candidate_occurrence_key or "").strip() or (
        risk_finalizer_probe_instance_key(candidate_text, decision_time)
        if candidate_text and decision_time
        else None
    )
    matched_statuses = [
        row
        for row in statuses
        if (
            candidate_instance_key
            and str(row.get("selected_instance_key") or "") == candidate_instance_key
        )
        or (
            not str(candidate_occurrence_key or "").strip()
            and
            candidate_text
            and str(row.get("candidate_id") or "") == candidate_text
            and (
                not decision_time
                or str(row.get("decision_time_utc") or "") == decision_time
            )
        )
    ]
    selected_instance_key = (
        first_present(
            matched_statuses[0].get("selected_instance_key")
            if matched_statuses
            else None,
            candidate_instance_key if candidate_instance_key in packet_instance_keys else None,
        )
        if candidate_text
        else first_present(
            decision.get("selected_candidate_instance_key"),
            packet_instance_keys[0] if packet_instance_keys else None,
        )
    )
    row_statuses = matched_statuses if candidate_text else statuses
    lookup_status = (
        row_statuses[0].get("lookup_status")
        if row_statuses
        else "selected_candidate_not_in_final_instance_lookup"
        if candidate_text
        else None
    )
    finalizer = scheduler_packet.get("risk_admitted_scheduler_finalizer")
    finalizer = finalizer if isinstance(finalizer, Mapping) else {}
    probe_rows_raw = first_present(
        finalizer.get("selected_probe_rows"),
        finalizer.get("probe_rows"),
        [],
    )
    probe_rows = [
        dict(row)
        for row in (probe_rows_raw or [])
        if isinstance(row, Mapping)
    ]
    matched_probe_rows = [
        row
        for row in probe_rows
        if (
            candidate_instance_key
            and str(row.get("risk_finalizer_probe_instance_key") or "")
            == candidate_instance_key
        )
        or (
            not str(candidate_occurrence_key or "").strip()
            and
            candidate_text
            and str(row.get("candidate_id") or "") == candidate_text
            and (
                not decision_time
                or str(row.get("decision_time_utc") or "") == decision_time
            )
        )
    ]
    finalizer_probe = matched_probe_rows[0] if matched_probe_rows else {}
    return {
        "selected_candidate_instance_key": selected_instance_key,
        "selected_candidate_instance_keys": packet_instance_keys,
        "selected_candidate_instance_lookup_status": lookup_status,
        "selected_candidate_instance_identity_status": (
            "conflicting_selected_option_instance_projection"
            if selected_identity_conflict
            else "materialized_from_selected_scheduler_options"
            if derived_option_keys
            else "legacy_selected_instance_projection"
        ),
        "selected_option_lookup_statuses": row_statuses,
        "risk_admitted_final_selected_candidate_instance_keys": packet_instance_keys,
        "risk_admitted_final_selected_option_lookup_statuses": statuses,
        "risk_admitted_finalizer_status": finalizer.get("status"),
        "risk_admitted_finalizer_reallocated": finalizer.get("reallocated"),
        "risk_admitted_finalizer_original_selected_candidate_ids": finalizer.get(
            "original_selected_candidate_ids"
        ),
        "risk_admitted_finalizer_final_selected_candidate_ids": finalizer.get(
            "final_selected_candidate_ids"
        ),
        "risk_admitted_finalizer_probe_count": finalizer.get("probe_count"),
        "risk_finalizer_probe_instance_key": (
            finalizer_probe.get("risk_finalizer_probe_instance_key")
            or candidate_instance_key
        ),
        "risk_finalizer_probe_selected": finalizer_probe.get("selected"),
        "risk_finalizer_probe_status": finalizer_probe.get("status"),
        "risk_finalizer_probe_rank": finalizer_probe.get("rank"),
        "risk_finalizer_probe_risk_decision": finalizer_probe.get("risk_decision"),
        "risk_finalizer_probe_risk_reason": first_present(
            finalizer_probe.get("risk_decision_reason"),
            finalizer_probe.get("reason"),
        ),
        "risk_finalizer_executable_finalized": first_present(
            finalizer_probe.get("risk_finalizer_executable_finalized"),
            risk_finalizer_probe_executable_finalized(finalizer_probe)
            if finalizer_probe
            else None,
        ),
        **risk_finalizer_extra_slot_attribution_fields(finalizer_probe),
    }


def selected_candidate_instance_execution_order(
    scheduler_packet: Mapping[str, Any],
) -> list[str]:
    """Return the finalizer/Scheduler order without set or hash reordering."""

    identity = selected_scheduler_instance_identity_fields(scheduler_packet)
    instance_keys = [
        str(item).strip()
        for item in identity.get("selected_candidate_instance_keys", [])
        if str(item or "").strip()
    ]
    if len(instance_keys) != len(set(instance_keys)):
        raise ValueError("finalized_scheduler_selected_instance_order_not_unique")
    if identity.get("selected_candidate_instance_identity_status") == (
        "conflicting_selected_option_instance_projection"
    ):
        raise ValueError("finalized_scheduler_selected_instance_projection_conflict")
    return instance_keys


def ledger_namespace_alias_fields(
    row: Mapping[str, Any],
    packets: Mapping[str, Any] | None = None,
    *,
    decision_time_utc: str | None = None,
) -> dict[str, Any]:
    """Canonical row aliases shared by candidate, scheduler, order, trade, and miss ledgers."""

    packets = packets if isinstance(packets, Mapping) else {}
    selector_packet = packets.get("selector_packet")
    selector_packet = selector_packet if isinstance(selector_packet, Mapping) else {}
    package_packet = selector_ultimate_package_packet(selector_packet)
    pretrade_packet = normalized_pretrade_cost_packet_from_packets(packets)
    decision_time = str(
        first_present(
            decision_time_utc,
            row.get("decision_time_utc"),
            row.get("candle_close_utc"),
            row.get("source_candle_time_utc"),
        )
        or ""
    )
    parsed_decision_time = parse_utc(decision_time) if decision_time else None
    authority_session = authority_execution_session_fields(
        row,
        decision_time_utc=decision_time,
    )
    raw_route_session = str(authority_session.get("route_session_raw") or "").strip()
    applied_route_session = str(
        first_present(authority_session.get("authority_session"), raw_route_session)
        or ""
    ).strip()
    raw_session_bucket = configured_execution_session_token(row.get("session_bucket"))
    raw_kill_zone = configured_execution_session_token(row.get("kill_zone"))
    session_bucket = str(
        first_present(raw_session_bucket, applied_route_session, raw_route_session) or ""
    ).strip()
    kill_zone = str(
        first_present(raw_kill_zone, raw_session_bucket, applied_route_session, raw_route_session)
        or ""
    ).strip()
    session_tokens = list(authority_session.get("authority_session_tokens") or [])
    utc_hour_bucket = str(authority_session.get("utc_hour_bucket") or "").strip()
    decision_timeframe = str(
        first_present(
            row.get("decision_timeframe"),
            row.get("timeframe"),
            row.get("market_timeframe"),
            row.get("primary_timeframe"),
            "M15",
        )
        or "M15"
    ).upper()
    side = str(first_present(row.get("side"), row.get("direction")) or "").upper()
    ev_r = first_present(
        row.get("candidate_ev_r"),
        row.get("ev_r"),
        row.get("expectancy_r"),
        packets.get("candidate_ev_r"),
        packets.get("ev_r"),
        packets.get("expectancy_r"),
    )
    expected_net_r = first_present(
        row.get("candidate_expected_net_r"),
        row.get("expected_net_r"),
        packets.get("candidate_expected_net_r"),
        packets.get("expected_net_r"),
    )
    probability = first_present(
        row.get("candidate_probability"),
        row.get("probability"),
        packets.get("candidate_probability"),
        packets.get("probability"),
    )
    confidence = first_present(
        row.get("candidate_confidence"),
        row.get("confidence"),
        packets.get("candidate_confidence"),
        packets.get("confidence"),
    )
    fill_probability = first_present(
        row.get("candidate_fill_probability"),
        row.get("fill_probability"),
        packets.get("candidate_fill_probability"),
        packets.get("fill_probability"),
    )
    source_completeness = first_present(
        row.get("source_completeness"),
        packets.get("source_completeness"),
        1.0 if row.get("source_window_complete") is True else None,
        0.0 if row.get("source_window_complete") is False else None,
    )
    source_completeness_status = str(
        first_present(
            row.get("source_completeness_status"),
            packets.get("source_completeness_status"),
            "source_completeness_present"
            if source_completeness not in (None, "")
            else "source_completeness_missing",
        )
    )
    candidate_quality_sources = first_present(
        row.get("candidate_decision_quality_field_sources"),
        packets.get("candidate_decision_quality_field_sources"),
        package_packet.get("candidate_decision_quality_field_sources"),
        {},
    )
    candidate_quality_sources = (
        candidate_quality_sources
        if isinstance(candidate_quality_sources, Mapping)
        else {}
    )
    candidate_quality_sources_complete = all(
        str(candidate_quality_sources.get(field) or "").strip()
        for field in (
            "expected_net_r",
            "probability",
            "fill_probability",
            "source_completeness",
        )
    )
    candidate_quality_source_boundary = first_present(
        row.get("candidate_decision_quality_source_boundary"),
        packets.get("candidate_decision_quality_source_boundary"),
        package_packet.get("candidate_decision_quality_source_boundary"),
    )
    raw_package_allowed = package_source_bound_or_admission_alias_allowed(
        row,
        packets,
        package_packet,
    )
    source_required_selector_hold_override_applied = _runtime_bool(
        row.get("scheduler_materialization_source_required_selector_hold_override_applied"),
        False,
    )
    source_required_fail_closed_override_applied = _runtime_bool(
        row.get("scheduler_materialization_source_required_fail_closed_override_applied"),
        False,
    )
    effective_selector_reason = effective_selector_reason_for_authority(
        row,
        packets,
        selector_packet,
    )
    selector_action = normalize_selector_action_for_reason(
        first_present(
            row.get("scheduler_materialization_selector_action"),
            row.get("effective_selector_action"),
            row.get("materialized_selector_action"),
            row.get("selector_action"),
            selector_packet.get("action"),
        ),
        effective_selector_reason,
    )
    source_required_selector_hold_override_valid = bool(
        source_required_selector_hold_override_applied
        and source_required_replay_override_currently_valid(
            override_kind="selector_hold",
            selector_action=selector_action,
            selector_packet=selector_packet,
            candidate=row,
            packets=packets,
        )
    )
    source_required_fail_closed_override_valid = bool(
        source_required_fail_closed_override_applied
        and source_required_replay_override_currently_valid(
            override_kind="fail_closed",
            selector_action=selector_action,
            selector_packet=selector_packet,
            candidate=row,
            packets=packets,
        )
    )
    source_required_lifecycle_resolver_override_applied = _runtime_bool(
        row.get("scheduler_materialization_replay_lifecycle_action_resolver_applied"),
        False,
    )
    source_required_lifecycle_resolver_override_valid = bool(
        source_required_lifecycle_resolver_override_applied
        and selector_action in RISK_BEARING_SELECTOR_ACTIONS
        and source_required_replay_override_currently_valid(
            override_kind="replay_lifecycle_action_resolver",
            selector_action=selector_action,
            selector_packet=selector_packet,
            candidate=row,
            packets=packets,
        )
    )
    source_required_replay_override_valid = bool(
        source_required_selector_hold_override_valid
        or source_required_fail_closed_override_valid
        or source_required_lifecycle_resolver_override_valid
    )
    raw_explicit_package_executable = first_present(
        row.get("package_replay_executable_candidate_use_allowed"),
        packets.get("package_replay_executable_candidate_use_allowed"),
        package_packet.get("package_replay_executable_candidate_use_allowed"),
        row.get("replay_candidate_use_allowed_now"),
        packets.get("replay_candidate_use_allowed_now"),
        package_packet.get("replay_candidate_use_allowed_now"),
    )
    raw_explicit_package_executable_reason = str(
        first_present(
            row.get("package_replay_executable_candidate_use_allowed_reason"),
            packets.get("package_replay_executable_candidate_use_allowed_reason"),
            package_packet.get("package_replay_executable_candidate_use_allowed_reason"),
            row.get("replay_candidate_use_allowed_now_reason"),
            packets.get("replay_candidate_use_allowed_now_reason"),
            package_packet.get("replay_candidate_use_allowed_now_reason"),
            "",
        )
        or ""
    ).strip()
    router_refusal_unsigned_namespace_block_reason = (
        source_bound_router_refusal_unsigned_namespace_block_reason(
            row,
            packets,
            package_packet,
            selector_reason=effective_selector_reason,
        )
    )
    explicit_package_executable = (
        True
        if source_required_replay_override_valid
        else raw_explicit_package_executable
    )
    explicit_package_executable_gate_value = (
        None
        if (
            explicit_package_executable is not None
            and not _runtime_bool(explicit_package_executable, False)
            and explicit_package_false_reason_can_be_rederived(
                raw_explicit_package_executable_reason,
                row,
                packets,
                package_packet,
            )
        )
        else explicit_package_executable
    )
    if router_refusal_unsigned_namespace_block_reason:
        explicit_package_executable_gate_value = False
    selector_executable_authority_allowed = bool(
        selector_action in RISK_BEARING_SELECTOR_ACTIONS
        or source_required_replay_override_valid
    )
    selector_executable_authority_block_reason = ""
    if not selector_executable_authority_allowed:
        selector_executable_authority_block_reason = (
            "selector_not_risk_bearing"
            + (
                f":{effective_selector_reason}"
                if effective_selector_reason
                else f":{selector_action}"
                if selector_action
                else ""
            )
        )
    if (
        explicit_package_executable_gate_value is not None
        and _runtime_bool(explicit_package_executable_gate_value, False)
        and not selector_executable_authority_allowed
    ):
        explicit_package_executable_gate_value = False
    package_evidence_present = bool(
        raw_package_allowed or explicit_package_executable is not None
    )
    if not pretrade_packet:
        row_cost_packet = {
            "status": row.get("pretrade_cost_packet_status"),
            "authority": first_present(
                row.get("cost_authority"),
                packets.get("cost_authority"),
                package_packet.get("cost_authority"),
                row.get("pretrade_cost_packet_authority"),
                packets.get("pretrade_cost_packet_authority"),
            ),
            "cost_source_gap_status": row.get("cost_source_gap_status"),
            "candidate_cost_r_fallback_is_authority": row.get(
                "candidate_cost_r_fallback_is_authority"
            ),
            "source_gap_cost_fallback_blocked": row.get(
                "source_gap_cost_fallback_blocked"
            ),
        }
        pretrade_packet = {
            key: value for key, value in row_cost_packet.items() if value not in (None, "")
        }
    expected_cost_r_alias = first_present(
        row.get("expected_cost_r"),
        row.get("cost_r"),
        packets.get("expected_cost_r"),
        packets.get("cost_r"),
        package_packet.get("expected_cost_r"),
        package_packet.get("cost_r"),
        pretrade_packet.get("total_cost_r"),
        pretrade_packet.get("expected_cost_r"),
        pretrade_packet.get("cost_r"),
    )
    risk_authority = row.get("risk_authority")
    pre_scheduler_risk_authority = packets.get("risk_authority_pre_scheduler")
    pre_scheduler_risk_authority = (
        pre_scheduler_risk_authority
        if isinstance(pre_scheduler_risk_authority, Mapping)
        else {}
    )
    nested_risk_authority_status = (
        first_present(
            risk_authority.get("risk_authority_status"),
            risk_authority.get("status"),
        )
        if isinstance(risk_authority, Mapping)
        else None
    )
    risk_authority_status_alias = first_present(
        nested_risk_authority_status,
        row.get("risk_authority_status"),
        pre_scheduler_risk_authority.get("risk_authority_status"),
        (
            "pre_scheduler_risk_authority_materialized"
            if pre_scheduler_risk_authority.get("schema_version")
            == "timewarp_v4_runtime_risk_authority_pre_scheduler_v1"
            else None
        ),
    )
    cost_status = str(
        first_present(
            pretrade_packet.get("status")
            if pretrade_cost_packet_current_executable(pretrade_packet)
            else None,
            row.get("pretrade_cost_packet_status"),
            packets.get("pretrade_cost_packet_status"),
            pretrade_packet.get("status"),
        )
        or ""
    ).upper()
    cost_refused = bool(
        row.get("pretrade_cost_packet_refused")
        or packets.get("pretrade_cost_packet_refused")
        or cost_status == "REFUSED"
    )
    cost_authority_block_reason = None
    if pretrade_packet or cost_status:
        cost_authority_block_reason = pretrade_cost_executable_block_reason(
            pretrade_packet,
            enforce=True,
        )
    if cost_authority_block_reason is None and cost_refused:
        cost_authority_block_reason = "broker_cost_refused"
    derived_quality_authority = bool(
        expected_net_r is not None
        and probability is not None
        and fill_probability is not None
        and source_completeness is not None
        and candidate_quality_sources_complete
        and candidate_decision_quality_boundary_is_predecision(
            candidate_quality_source_boundary
        )
        and cost_authority_block_reason is None
        and safe_float(source_completeness, 0.0) >= 0.95
        and not any(
            token in source_completeness_status.lower()
            for token in (
                "missing",
                "degraded",
                "gap",
                "source_required",
                "incomplete",
                "prospective_capture",
                "snapshot_incomplete",
            )
        )
    )
    package_allowed = bool(
        raw_package_allowed
        and not router_refusal_unsigned_namespace_block_reason
        and selector_executable_authority_allowed
        and (
            (
                explicit_package_executable_gate_value is not None
                and _runtime_bool(explicit_package_executable_gate_value, False)
            )
            or (
                explicit_package_executable_gate_value is None
                and derived_quality_authority
            )
        )
    )
    package_replay_allowed = package_allowed
    raw_source_bound_allowed = package_source_bound_or_admission_alias_allowed(
        row,
        packets,
        package_packet,
    )
    source_bound_allowed = bool(
        raw_source_bound_allowed
        and package_allowed
    )
    lifecycle_packet = packets.get("lifecycle_packet")
    lifecycle_packet = lifecycle_packet if isinstance(lifecycle_packet, Mapping) else {}
    raw_lifecycle_action = str(
        first_present(
            row.get("same_symbol_lifecycle_action"),
            row.get("gtos_vnext_same_symbol_lifecycle_action"),
            row.get("lifecycle_action"),
            lifecycle_packet.get("action"),
        )
        or ""
    ).strip()
    raw_source_required_fail_closed = raw_lifecycle_action == "source_required_fail_closed"
    effective_signal = ultimate_package_effective_signal_fields(
        {
            **dict(row),
            "package_source_bound_admission_diagnostic": raw_package_allowed,
            "source_bound_package_candidate_use_allowed": raw_source_bound_allowed,
            "ultimate_package_source_bound_candidate_use_allowed": raw_source_bound_allowed,
            "package_replay_executable_candidate_use_allowed": (
                explicit_package_executable_gate_value
            ),
            "pretrade_cost_packet_status": first_present(
                pretrade_packet.get("status")
                if pretrade_cost_packet_current_executable(pretrade_packet)
                else None,
                row.get("pretrade_cost_packet_status"),
                packets.get("pretrade_cost_packet_status"),
                pretrade_packet.get("status"),
            ),
            "cost_authority": first_present(
                row.get("cost_authority"),
                packets.get("cost_authority"),
                package_packet.get("cost_authority"),
                row.get("pretrade_cost_packet_authority"),
                packets.get("pretrade_cost_packet_authority"),
                pretrade_packet.get("authority"),
            ),
            "cost_source_gap_status": first_present(
                row.get("cost_source_gap_status"),
                packets.get("cost_source_gap_status"),
                pretrade_packet.get("cost_source_gap_status"),
            ),
            "candidate_cost_r_fallback_is_authority": first_present(
                row.get("candidate_cost_r_fallback_is_authority"),
                packets.get("candidate_cost_r_fallback_is_authority"),
                pretrade_packet.get("candidate_cost_r_fallback_is_authority"),
            ),
        }
    )
    effective_admission_count = first_present(
        row.get("ultimate_package_effective_admission_count"),
        effective_signal.get("ultimate_package_effective_admission_count"),
    )
    explicit_admission_candidate_use_allowed = first_present(
        row.get("ultimate_package_admission_candidate_use_allowed"),
        package_packet.get("admission_candidate_use_allowed"),
        package_packet.get("ultimate_package_admission_candidate_use_allowed"),
    )
    diagnostic_admission_candidate_use_allowed = bool(
        _runtime_bool(explicit_admission_candidate_use_allowed, False)
        or safe_float(effective_admission_count, 0.0) > 0.0
    )
    diagnostic_package_replay_allowed = bool(
        raw_source_bound_allowed and diagnostic_admission_candidate_use_allowed
    )
    derived_effective_admission_candidate_use_allowed = bool(
        source_bound_allowed
        and safe_float(effective_admission_count, 0.0) > 0.0
    )
    admission_candidate_use_allowed = bool(
        _runtime_bool(explicit_admission_candidate_use_allowed, False)
        or derived_effective_admission_candidate_use_allowed
    )
    effective_package_candidate_use_allowed = bool(
        source_bound_allowed
        and (
            admission_candidate_use_allowed
            or safe_float(effective_admission_count, 0.0) > 0.0
        )
    )
    executable_package_replay_allowed = bool(
        effective_package_candidate_use_allowed
        and not router_refusal_unsigned_namespace_block_reason
    )
    scheduler_skip_reason = str(
        first_present(
            row.get("scheduler_materialization_skip_reason"),
            packets.get("scheduler_materialization_skip_reason"),
        )
        or ""
    ).strip()
    scheduler_action_intent = str(
        first_present(
            row.get("scheduler_materialization_action_intent"),
            row.get("action_intent"),
            row.get("lifecycle_action"),
        )
        or ""
    ).strip()
    materialization_block_reason = None
    if scheduler_skip_reason:
        materialization_block_reason = (
            selector_executable_authority_block_reason
            if (
                scheduler_skip_reason == "selector_not_risk_bearing"
                and selector_executable_authority_block_reason
            )
            else f"scheduler_materialization_skipped:{scheduler_skip_reason}"
        )
    elif raw_source_required_fail_closed and not source_required_fail_closed_override_applied:
        materialization_block_reason = (
            "scheduler_materialization_source_required_fail_closed_without_override"
        )
    elif (
        scheduler_action_intent.startswith("invalid_action_intent:")
        and not (
            scheduler_action_intent
            == "invalid_action_intent:source_required_fail_closed"
            and source_required_fail_closed_override_applied
        )
    ):
        materialization_block_reason = (
            f"scheduler_materialization_invalid_action:{scheduler_action_intent}"
        )
    executable_package_allowed = bool(
        package_evidence_present
        and executable_package_replay_allowed
        and not cost_authority_block_reason
        and not materialization_block_reason
        and selector_executable_authority_allowed
    )
    risk_bearing_replay_allowed_now = bool(
        executable_package_allowed
        and selector_action in {"trade", "reduce-risk", "open-reduced-risk"}
    )
    source_required_selector_hold_replay_allowed_now = bool(
        executable_package_allowed
        and source_required_selector_hold_override_applied
    )
    source_required_fail_closed_replay_allowed_now = bool(
        executable_package_allowed
        and source_required_fail_closed_override_applied
    )
    source_required_lifecycle_resolver_replay_allowed_now = bool(
        executable_package_allowed
        and source_required_lifecycle_resolver_override_valid
    )
    replay_allowed_now = bool(
        risk_bearing_replay_allowed_now
        or source_required_selector_hold_replay_allowed_now
        or source_required_fail_closed_replay_allowed_now
        or source_required_lifecycle_resolver_replay_allowed_now
    )
    executable_package_allowed_value = (
        executable_package_allowed if package_evidence_present else None
    )
    replay_allowed_now_value = replay_allowed_now if package_evidence_present else None
    (
        open_reduced_authority,
        open_reduced_authority_allowed,
        open_reduced_authority_family,
    ) = open_reduced_authority_from_surfaces(row=row, packets=packets)
    ledger_namespace_executable_authority_source = (
        "no_package_executable_evidence"
        if not package_evidence_present
        else "source_bound_router_refusal_unsigned_namespace_demoted"
        if router_refusal_unsigned_namespace_block_reason
        else "explicit_package_replay_executable_or_replay_candidate_use_allowed_now"
        if explicit_package_executable_gate_value is not None
        else "derived_predecision_quality_source_cost_authority"
        if derived_quality_authority
        else "missing_explicit_package_executable_authority"
    )
    signed_order_executable_allowed = _runtime_bool(
        first_present(
            row.get("package_replay_order_executable_candidate_use_allowed"),
            packets.get("package_replay_order_executable_candidate_use_allowed"),
            package_packet.get(
                "package_replay_order_executable_candidate_use_allowed"
            ),
            row.get(
                "package_new_entry_authority_package_replay_order_executable_candidate_use_allowed"
            ),
            packets.get(
                "package_new_entry_authority_package_replay_order_executable_candidate_use_allowed"
            ),
        ),
        False,
    )
    signed_order_executable_authority_source = first_present(
        row.get("package_replay_order_executable_authority_source"),
        packets.get("package_replay_order_executable_authority_source"),
        package_packet.get("package_replay_order_executable_authority_source"),
        row.get(
            "package_new_entry_authority_package_replay_order_executable_authority_source"
        ),
        packets.get(
            "package_new_entry_authority_package_replay_order_executable_authority_source"
        ),
    )
    package_replay_executable_authority_source = first_present(
        row.get("package_replay_executable_authority_source"),
        packets.get("package_replay_executable_authority_source"),
        package_packet.get("package_replay_executable_authority_source"),
        (
            signed_order_executable_authority_source
            if signed_order_executable_allowed
            else None
        ),
        ledger_namespace_executable_authority_source,
    )
    return {
        "direction": side or None,
        "side": side or None,
        "timeframe": decision_timeframe,
        "market_timeframe": decision_timeframe,
        "decision_timeframe": decision_timeframe,
        "route_session_raw": raw_route_session or None,
        "route_session_applied": applied_route_session or None,
        "route_session": raw_route_session or None,
        "session": applied_route_session or session_bucket or raw_route_session or None,
        "session_bucket": session_bucket or applied_route_session or None,
        "kill_zone": kill_zone or session_bucket or applied_route_session or None,
        "authority_session": authority_session.get("authority_session"),
        "authority_session_source": authority_session.get("authority_session_source"),
        "authority_session_tokens": session_tokens,
        "utc_hour_bucket": utc_hour_bucket or None,
        "session_tokens": session_tokens,
        "candidate_ev_r": ev_r,
        "ev_r": ev_r,
        "expectancy_r": ev_r,
        "candidate_expected_net_r": expected_net_r,
        "expected_net_r": expected_net_r,
        "expected_cost_r": expected_cost_r_alias,
        "cost_r": expected_cost_r_alias,
        "candidate_probability": probability,
        "probability": probability,
        "candidate_confidence": confidence,
        "confidence": confidence,
        "scheduler_confidence": confidence,
        "candidate_fill_probability": fill_probability,
        "fill_probability": fill_probability,
        "source_completeness": source_completeness,
        "source_completeness_status": source_completeness_status,
        "risk_authority_status": risk_authority_status_alias,
        "source_bound_package_candidate_use_allowed": raw_source_bound_allowed,
        "ultimate_package_source_bound_candidate_use_allowed": raw_source_bound_allowed,
        "package_replay_source_bound_candidate_use_allowed": raw_source_bound_allowed,
        "package_replay_candidate_use_allowed": diagnostic_package_replay_allowed,
        "package_replay_executable_candidate_use_allowed": (
            executable_package_allowed_value
        ),
        "package_source_bound_admission_diagnostic": raw_package_allowed,
        "ledger_namespace_synthesized_executable_candidate_use_allowed": (
            executable_package_allowed_value
        ),
        "ledger_namespace_executable_authority_source": (
            ledger_namespace_executable_authority_source
        ),
        "package_replay_executable_authority_source": (
            package_replay_executable_authority_source
        ),
        "source_required_fail_closed_raw_lifecycle_action": raw_source_required_fail_closed,
        "source_required_fail_closed_replay_override_applied": (
            source_required_fail_closed_override_applied
        ),
        "source_required_selector_hold_replay_override_applied": (
            source_required_selector_hold_override_applied
        ),
        "source_required_lifecycle_resolver_replay_override_applied": (
            source_required_lifecycle_resolver_override_applied
        ),
        "source_required_lifecycle_resolver_replay_override_valid": (
            source_required_lifecycle_resolver_override_valid
        ),
        "ultimate_candidate_package_open_reduced_risk_authority": (
            open_reduced_authority
        ),
        "package_open_reduced_authority_allowed": (
            open_reduced_authority_allowed
        ),
        "package_open_reduced_authority_family": (
            open_reduced_authority_family
        ),
        "ultimate_package_open_reduced_authority_allowed": (
            open_reduced_authority_allowed
        ),
        "package_replay_executable_candidate_use_allowed_reason": (
            "no_package_executable_evidence"
            if not package_evidence_present
            else cost_authority_block_reason
            if cost_authority_block_reason
            else materialization_block_reason
            if materialization_block_reason
            else router_refusal_unsigned_namespace_block_reason
            if router_refusal_unsigned_namespace_block_reason
            else selector_executable_authority_block_reason
            if selector_executable_authority_block_reason
            else "broker_cost_and_scheduler_action_executable"
            if executable_package_allowed
            else "source_bound_package_replay_not_allowed"
        ),
        "ultimate_package_admission_candidate_use_allowed": (
            admission_candidate_use_allowed
        ),
        "ultimate_package_effective_source_bound_candidate_use_allowed": first_present(
            effective_signal.get(
                "ultimate_package_effective_source_bound_candidate_use_allowed"
            ),
            row.get("ultimate_package_effective_source_bound_candidate_use_allowed"),
        ),
        "ultimate_package_effective_admission_count": first_present(
            effective_signal.get("ultimate_package_effective_admission_count"),
            row.get("ultimate_package_effective_admission_count"),
        ),
        "ultimate_package_effective_matched_count": first_present(
            effective_signal.get("ultimate_package_effective_matched_count"),
            row.get("ultimate_package_effective_matched_count"),
        ),
        "ultimate_package_effective_source_bound_signal_r": first_present(
            effective_signal.get("ultimate_package_effective_source_bound_signal_r"),
            row.get("ultimate_package_effective_source_bound_signal_r"),
        ),
        "ultimate_package_effective_evidence_source": first_present(
            effective_signal.get("ultimate_package_effective_evidence_source"),
            row.get("ultimate_package_effective_evidence_source"),
        ),
        "ultimate_package_executable_admission_status": first_present(
            effective_signal.get("ultimate_package_executable_admission_status"),
            row.get("ultimate_package_executable_admission_status"),
        ),
        "ultimate_package_scheduler_consumed_status": first_present(
            effective_signal.get("ultimate_package_scheduler_consumed_status"),
            row.get("ultimate_package_scheduler_consumed_status"),
        ),
        "replay_candidate_use_allowed_now": replay_allowed_now_value,
        "replay_candidate_use_allowed_now_reason": (
            "source_required_selector_hold_package_replay_override_applied"
            if source_required_selector_hold_replay_allowed_now
            else "source_required_fail_closed_package_replay_override_applied"
            if source_required_fail_closed_replay_allowed_now
            else "replay_lifecycle_action_resolver_package_replay_override_applied"
            if source_required_lifecycle_resolver_replay_allowed_now
            else "risk_bearing_selector_and_broker_cost_passed"
            if risk_bearing_replay_allowed_now
            else cost_authority_block_reason
            if cost_authority_block_reason
            else materialization_block_reason
            if materialization_block_reason
            else "selector_not_risk_bearing"
            if selector_action and selector_action not in RISK_BEARING_SELECTOR_ACTIONS
            else "package_source_bound_not_allowed"
        ),
        "ledger_namespace_alias_status": "materialized",
    }


def normalized_pretrade_cost_packet(packet: Mapping[str, Any] | None) -> dict[str, Any]:
    """Merge compact scalar_fields packets with broker-cost envelope authority fields."""

    raw_packet = dict(packet) if isinstance(packet, Mapping) else {}
    scalar_fields = raw_packet.get("scalar_fields")
    scalar_fields = scalar_fields if isinstance(scalar_fields, Mapping) else {}
    if not scalar_fields:
        return raw_packet
    merged = dict(raw_packet)
    for key, value in scalar_fields.items():
        if value in (None, "", [], {}):
            continue
        if key in {
            "status",
            "authority",
            "cost_source_gap_status",
            "candidate_cost_r_fallback_is_authority",
            "source_gap_cost_fallback_blocked",
            "refusal_reasons",
        } and raw_packet.get(key) not in (None, "", [], {}):
            if raw_packet.get(key) != value:
                merged[f"scalar_conflict_{key}"] = value
            continue
        merged[key] = value
    return merged


def pretrade_cost_packet_current_executable(packet: Mapping[str, Any] | None) -> bool:
    packet = packet if isinstance(packet, Mapping) else {}
    return bool(
        str(packet.get("status") or "").strip().upper() in {"PASSED", "PASS", "OK"}
        and str(packet.get("authority") or "").strip()
        == "broker_calibrated_replay_cost"
        and str(packet.get("cost_source_gap_status") or "").strip()
        == "source_bound_cost_authority_present"
        and not _runtime_bool(packet.get("candidate_cost_r_fallback_is_authority"), False)
    )


def broker_cost_authority_from_surfaces(
    *,
    cost_authority: Any = None,
    pretrade_cost_packet_authority: Any = None,
    execution_cost_authority: Any = None,
) -> str | None:
    authority = first_present(cost_authority, pretrade_cost_packet_authority)
    authority_text = str(authority or "").strip()
    if authority_text:
        return authority_text
    execution_text = str(execution_cost_authority or "").strip()
    if execution_text == "broker_calibrated_replay_cost":
        return execution_text
    return None


def normalized_pretrade_cost_packet_from_packets(
    packets: Mapping[str, Any],
) -> dict[str, Any]:
    packet = first_present(
        packets.get("pretrade_broker_net_cost_packet"),
        packets.get("broker_net_cost_packet"),
    )
    normalized = normalized_pretrade_cost_packet(
        packet if isinstance(packet, Mapping) else {}
    )
    flat_packet = {
        "status": first_present(
            packets.get("pretrade_cost_packet_status"),
            packets.get("broker_net_cost_packet_status"),
        ),
        "authority": broker_cost_authority_from_surfaces(
            cost_authority=packets.get("cost_authority"),
            pretrade_cost_packet_authority=packets.get(
                "pretrade_cost_packet_authority"
            ),
            execution_cost_authority=packets.get("execution_cost_authority"),
        ),
        "cost_source_gap_status": packets.get("cost_source_gap_status"),
        "total_cost_r": first_present(
            packets.get("total_execution_cost_r"),
            packets.get("broker_pretrade_cost_r"),
            packets.get("broker_calibrated_expected_cost_r"),
            packets.get("expected_total_cost_r"),
            packets.get("expected_cost_r"),
            packets.get("cost_r"),
        ),
        "candidate_cost_r_fallback_is_authority": packets.get(
            "candidate_cost_r_fallback_is_authority"
        ),
        "source_gap_cost_fallback_blocked": packets.get(
            "source_gap_cost_fallback_blocked"
        ),
        "refusal_reasons": packets.get("pretrade_cost_refusal_reasons"),
        "model_version": packets.get("pretrade_cost_packet_model_version"),
        "spread_r": packets.get("spread_r"),
        "expected_slippage_r": packets.get("expected_slippage_r"),
        "commission_r": packets.get("commission_r"),
    }
    if not normalized:
        return {
            key: value
            for key, value in flat_packet.items()
            if value not in (None, "", [], {})
        }
    merged = dict(normalized)
    for key, value in flat_packet.items():
        if value in (None, "", [], {}):
            continue
        if merged.get(key) in (None, "", [], {}):
            merged[key] = value
            continue
        if key in {
            "status",
            "authority",
            "cost_source_gap_status",
            "candidate_cost_r_fallback_is_authority",
            "source_gap_cost_fallback_blocked",
            "refusal_reasons",
        } and merged.get(key) != value:
            merged[f"flat_conflict_{key}"] = value
    return merged


def package_effective_signal_seed(
    *,
    candidate: Mapping[str, Any] | None,
    packets: Mapping[str, Any] | None = None,
    scheduler_option: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Merge predecision package, quality, and broker-cost proof for replay gates."""

    candidate = candidate if isinstance(candidate, Mapping) else {}
    packets = packets if isinstance(packets, Mapping) else {}
    scheduler_option = (
        scheduler_option if isinstance(scheduler_option, Mapping) else {}
    )
    selector_packet = packets.get("selector_packet")
    selector_packet = selector_packet if isinstance(selector_packet, Mapping) else {}
    components = scheduler_option.get("score_components")
    components = components if isinstance(components, Mapping) else {}
    decision_inputs = components.get("candidate_decision_inputs")
    decision_inputs = decision_inputs if isinstance(decision_inputs, Mapping) else {}
    if not decision_inputs:
        maybe_inputs = scheduler_option.get("scheduler_candidate_decision_inputs")
        decision_inputs = maybe_inputs if isinstance(maybe_inputs, Mapping) else {}
    candidate_fillability = candidate.get("predecision_limit_fillability")
    candidate_fillability = (
        candidate_fillability if isinstance(candidate_fillability, Mapping) else {}
    )
    decision_fillability = decision_inputs.get("predecision_limit_fillability")
    decision_fillability = (
        decision_fillability if isinstance(decision_fillability, Mapping) else {}
    )
    selector_package_parity = scheduler_package_parity_fields(selector_packet)
    member_axis_parity = ultimate_package_member_axis_parity_fields(candidate)
    seed: dict[str, Any] = {
        **selector_package_parity,
        **dict(candidate),
        **canonical_replay_candidate_instance_fields(candidate),
    }
    seed.update(dict(decision_inputs))
    option_fields = {
        key: scheduler_option.get(key)
        for key in (
            "candidate_id",
            "symbol",
            "side",
            "direction",
            "decision_time_utc",
            "scheduler_asof_utc",
            "decision_timeframe",
            "timeframe",
            "route_session",
            "session",
            "session_bucket",
            "expected_net_r",
            "candidate_expected_net_r",
            "candidate_ev_r",
            "ev_r",
            "probability",
            "candidate_probability",
            "fill_probability",
            "candidate_fill_probability",
            "source_completeness",
            "source_completeness_status",
            "selector_action",
            "selector_reason",
            "source_bound_signal_r",
            "ultimate_package_source_bound_candidate_use_allowed",
            "source_bound_package_candidate_use_allowed",
            "package_replay_candidate_use_allowed",
            "package_replay_executable_candidate_use_allowed",
            "package_replay_executable_candidate_use_allowed_reason",
            "ultimate_package_admission_candidate_use_allowed",
            "ultimate_package_admission_sleeve_match_count",
            "ultimate_package_matched_sleeve_count",
            "ultimate_package_role_disposition",
            "ultimate_package_combined_source_bound_signal_r_sum",
            "ultimate_package_max_combined_source_bound_signal_r",
            "pretrade_cost_packet_status",
            "cost_authority",
            "execution_cost_authority",
            "cost_source_gap_status",
            "candidate_cost_r_fallback_is_authority",
            "source_gap_cost_fallback_blocked",
        )
        if scheduler_option.get(key) is not None
    }
    seed.update(option_fields)
    # Exact current-source member-axis parity outranks carried candidate,
    # scheduler-option, and decision-input aliases. The selector package's raw
    # admission assertion remains diagnostic until composed with this proof.
    seed.update(member_axis_parity)
    if selector_package_parity.get("package_source_bound_admission_diagnostic") is True:
        seed["package_source_bound_admission_diagnostic"] = True
        seed["package_source_bound_admission_diagnostic_source"] = (
            selector_package_parity.get(
                "package_source_bound_admission_diagnostic_source"
            )
        )

    pretrade_packet = normalized_pretrade_cost_packet_from_packets(packets)
    quality = (
        _scheduler_option_quality_inputs(
            scheduler_option,
            candidate=seed,
            packets=packets,
        )
        if scheduler_option
        else candidate_decision_quality_fields(seed, packets)
    )
    explicit_expected_net = first_present(
        decision_inputs.get("expected_net_r"),
        decision_inputs.get("candidate_expected_net_r"),
        scheduler_option.get("expected_net_r"),
        scheduler_option.get("candidate_expected_net_r"),
        candidate.get("expected_net_r"),
        candidate.get("candidate_expected_net_r"),
        packets.get("expected_net_r"),
        packets.get("candidate_expected_net_r"),
    )
    explicit_ev = first_present(
        decision_inputs.get("ev_r"),
        scheduler_option.get("candidate_ev_r"),
        scheduler_option.get("ev_r"),
        candidate.get("candidate_ev_r"),
        candidate.get("ev_r"),
        packets.get("candidate_ev_r"),
        packets.get("ev_r"),
    )
    explicit_cost = first_present(
        decision_inputs.get("cost_total_r"),
        scheduler_option.get("expected_cost_r"),
        scheduler_option.get("cost_r"),
        candidate.get("expected_cost_r"),
        candidate.get("cost_r"),
        packets.get("expected_cost_r"),
        packets.get("cost_r"),
        packets.get("broker_calibrated_expected_cost_r"),
        packets.get("broker_pretrade_cost_r"),
        pretrade_packet.get("total_cost_r"),
    )
    expected_net_r = (
        explicit_expected_net
        if explicit_expected_net is not None
        else (
            round(safe_float(explicit_ev, 0.0) - safe_float(explicit_cost, 0.0), 12)
            if explicit_ev is not None and explicit_cost is not None
            else None
        )
    )
    probability = first_present(
        decision_inputs.get("probability"),
        scheduler_option.get("probability"),
        scheduler_option.get("candidate_probability"),
        candidate.get("candidate_probability"),
        candidate.get("probability"),
        packets.get("candidate_probability"),
        packets.get("probability"),
    )
    fill_probability = first_present(
        decision_inputs.get("fill_probability"),
        decision_fillability.get("fill_probability"),
        scheduler_option.get("fill_probability"),
        scheduler_option.get("candidate_fill_probability"),
        candidate.get("fill_probability"),
        candidate.get("candidate_fill_probability"),
        candidate_fillability.get("fill_probability"),
        packets.get("fill_probability"),
        packets.get("candidate_fill_probability"),
    )
    source_completeness = first_present(
        decision_inputs.get("source_completeness"),
        scheduler_option.get("source_completeness"),
        candidate.get("source_completeness"),
        candidate.get("candidate_source_completeness"),
        candidate.get("selected_cell_source_completeness"),
        packets.get("source_completeness"),
        1.0 if candidate.get("source_window_complete") is True else None,
        0.0 if candidate.get("source_window_complete") is False else None,
    )
    if expected_net_r is not None:
        seed["expected_net_r"] = safe_float(
            expected_net_r,
            safe_float(quality.get("expected_net_r"), 0.0),
        )
        seed["candidate_expected_net_r"] = seed["expected_net_r"]
    if probability is not None:
        seed["probability"] = safe_float(probability, quality.get("probability"))
        seed["candidate_probability"] = seed["probability"]
    if fill_probability is not None:
        seed["fill_probability"] = safe_float(
            fill_probability,
            quality.get("fill_probability"),
        )
        seed["candidate_fill_probability"] = seed["fill_probability"]
    if source_completeness is not None:
        seed["source_completeness"] = safe_float(
            source_completeness,
            quality.get("source_completeness"),
        )
        seed["source_completeness_status"] = first_present(
            seed.get("source_completeness_status"),
            packets.get("source_completeness_status"),
            "source_completeness_present",
        )

    cost_status = first_present(
        pretrade_packet.get("status"),
        packets.get("pretrade_cost_packet_status"),
        seed.get("pretrade_cost_packet_status"),
    )
    cost_authority = first_present(
        pretrade_packet.get("authority"),
        broker_cost_authority_from_surfaces(
            cost_authority=packets.get("cost_authority"),
            pretrade_cost_packet_authority=packets.get(
                "pretrade_cost_packet_authority"
            ),
            execution_cost_authority=packets.get("execution_cost_authority"),
        ),
        broker_cost_authority_from_surfaces(
            cost_authority=seed.get("cost_authority"),
            pretrade_cost_packet_authority=seed.get("pretrade_cost_packet_authority"),
            execution_cost_authority=seed.get("execution_cost_authority"),
        ),
    )
    cost_source_gap_status = first_present(
        pretrade_packet.get("cost_source_gap_status"),
        packets.get("cost_source_gap_status"),
        seed.get("cost_source_gap_status"),
    )
    if cost_status is not None:
        seed["pretrade_cost_packet_status"] = cost_status
    if cost_authority is not None:
        seed["cost_authority"] = cost_authority
    execution_cost_authority = first_present(
        packets.get("execution_cost_authority"),
        seed.get("execution_cost_authority"),
    )
    if execution_cost_authority is not None:
        seed["execution_cost_authority"] = execution_cost_authority
    if cost_source_gap_status is not None:
        seed["cost_source_gap_status"] = cost_source_gap_status
    for key in (
        "candidate_cost_r_fallback_is_authority",
        "source_gap_cost_fallback_blocked",
    ):
        value = first_present(
            pretrade_packet.get(key),
            packets.get(key),
            seed.get(key),
        )
        if value is not None:
            seed[key] = value
    raw_package_membership = any(
        _runtime_bool(seed.get(key), False)
        for key in (
            "package_source_bound_admission_diagnostic",
            "ultimate_package_source_bound_candidate_use_allowed",
            "source_bound_package_candidate_use_allowed",
            "package_replay_source_bound_candidate_use_allowed",
            "package_replay_candidate_use_allowed",
        )
    )
    exact_member_axis_lineage = bool(
        raw_package_membership
        and seed.get("ultimate_package_member_axis_evidence_class")
        == EXACT_MEMBER_AXIS_EXECUTION_EVIDENCE_CLASS
        and seed.get("ultimate_package_member_axis_match_status")
        == EXACT_MEMBER_AXIS_CURRENT_MATCH_STATUS
        and safe_float(
            seed.get("ultimate_package_admission_member_axis_match_count"),
            0.0,
        )
        > 0.0
        and safe_float(
            seed.get("ultimate_package_member_axis_source_bound_signal_r_sum"),
            0.0,
        )
        > 0.0
        and package_member_axis_source_bound_identity_present(seed)
        and seed.get("candidate_instance_identity_status") == "materialized"
        and bool(seed.get("canonical_replay_candidate_instance_key"))
        and seed.get("canonical_replay_candidate_instance_key")
        == seed.get("source_bound_replay_candidate_instance_key")
        and candidate_decision_quality_boundary_is_predecision(
            first_present(
                seed.get("candidate_decision_quality_source_boundary"),
                seed.get("source_boundary"),
            )
        )
    )
    owner_family_root_detail = _owner_approved_family_root_admission_detail(seed)
    owner_approved_family_root_lineage = bool(
        owner_family_root_detail.get("allowed") is True
    )
    if exact_member_axis_lineage or owner_approved_family_root_lineage:
        seed["ultimate_package_source_bound_candidate_use_allowed"] = True
        seed["source_bound_package_candidate_use_allowed"] = True
        seed["package_replay_source_bound_candidate_use_allowed"] = True
        seed["package_source_bound_authority_status"] = (
            "selector_admission_composed_with_exact_current_member_axis_identity"
            if exact_member_axis_lineage
            else "owner_approved_research_family_root_identity_materialized"
        )
        seed["package_source_bound_authority_source"] = (
            "selector_ultimate_package_packet_plus_member_axis_parity"
            if exact_member_axis_lineage
            else "selector_ultimate_package_packet_plus_owner_approved_family_root"
        )
        if owner_approved_family_root_lineage:
            seed["package_source_bound_admission_diagnostic"] = True
            raw_package_membership = True
    source_bound_package_authority = package_source_bound_or_admission_alias_allowed(
        seed,
        candidate,
        packets,
        scheduler_option,
        decision_inputs,
    )
    if owner_approved_family_root_lineage:
        source_bound_package_authority = True
    if raw_package_membership:
        seed["package_source_bound_admission_diagnostic"] = True
    if source_bound_package_authority:
        seed["ultimate_package_source_bound_candidate_use_allowed"] = True
        seed["source_bound_package_candidate_use_allowed"] = True
    elif raw_package_membership:
        seed["ultimate_package_source_bound_candidate_use_allowed"] = False
        seed["source_bound_package_candidate_use_allowed"] = False
        seed["package_replay_source_bound_candidate_use_allowed"] = False
        seed["package_source_bound_authority_status"] = (
            "diagnostic_package_lineage_without_member_axis_or_signed_identity"
        )
    return seed


def pretrade_cost_attribution_fields(packets: Mapping[str, Any]) -> dict[str, Any]:
    """Compact broker-calibrated replay cost fields for behavior ledgers."""

    packet = normalized_pretrade_cost_packet_from_packets(packets)
    components = packet.get("total_cost_components")
    components = components if isinstance(components, Mapping) else {}
    quote = packet.get("quote_authority")
    quote = quote if isinstance(quote, Mapping) else {}
    swap_cost = packet.get("swap_cost")
    swap_cost = swap_cost if isinstance(swap_cost, Mapping) else {}
    fallback_execution_surcharge_r = safe_float(
        packets.get("fallback_execution_surcharge_r"),
        safe_float(packets.get("guarded_market_fallback_extra_cost_r"), 0.0),
    )
    broker_pretrade_cost_raw, broker_pretrade_cost_source, cost_block_reason = (
        executable_broker_calibrated_cost_r_from_packets(packets)
    )
    broker_pretrade_cost_r = (
        round(safe_float(broker_pretrade_cost_raw, 0.0), 8)
        if broker_pretrade_cost_raw is not None
        else None
    )
    total_execution_cost_r = (
        safe_float(broker_pretrade_cost_raw, 0.0) + fallback_execution_surcharge_r
        if broker_pretrade_cost_raw is not None
        else None
    )
    diagnostic_expected_cost_r = _optional_float(
        first_present(
            packet.get("total_cost_r"),
            packet.get("expected_total_cost_r"),
            packets.get("expected_cost_r"),
            packets.get("cost_r"),
        )
    )
    return {
        "broker_calibrated_expected_cost_r": broker_pretrade_cost_r,
        "broker_pretrade_cost_r": broker_pretrade_cost_r,
        "broker_pretrade_cost_source": broker_pretrade_cost_source,
        "broker_pretrade_cost_executable_block_reason": cost_block_reason,
        "fallback_execution_surcharge_r": fallback_execution_surcharge_r,
        "total_execution_cost_r": (
            round(total_execution_cost_r, 8)
            if total_execution_cost_r is not None
            else None
        ),
        "broker_pretrade_cost_non_executable_diagnostic_expected_cost_r": (
            round(diagnostic_expected_cost_r, 8)
            if broker_pretrade_cost_raw is None
            and diagnostic_expected_cost_r is not None
            else None
        ),
        "broker_pretrade_cost_executable": broker_pretrade_cost_raw is not None,
        "execution_cost_authority": (
            "non_executable_broker_cost_blocked"
            if broker_pretrade_cost_raw is None
            else
            "broker_pretrade_plus_guarded_market_fallback_surcharge"
            if fallback_execution_surcharge_r > 0
            else "broker_pretrade_cost_only"
        ),
        "net_cost_scope": (
            "non_executable_cost_not_in_net_proxy_r"
            if broker_pretrade_cost_raw is None
            else "broker_pretrade_plus_optional_fallback_surcharge_not_close_side_all_in"
        ),
        "close_side_all_in_cost_status": "not_joined_in_replay_net_proxy_r",
        "candidate_cost_r_fallback_diagnostic": packet.get(
            "old_timewarp_candidate_cost_r_fallback_diagnostic",
            packets.get("candidate_cost_r_fallback_diagnostic"),
        ),
        "old_proxy_vs_broker_calibrated_delta_r": packet.get(
            "old_proxy_vs_broker_calibrated_delta_r",
            packets.get("old_proxy_vs_broker_calibrated_delta_r"),
        ),
        "cost_authority": packet.get("authority"),
        "cost_source_gap_status": packet.get("cost_source_gap_status"),
        "cost_source_gap_allowed_by_replay_profile": bool(
            packet.get("cost_source_gap_allowed_by_replay_profile", False)
        ),
        "source_gap_cost_fallback_blocked": bool(
            packet.get("source_gap_cost_fallback_blocked", False)
        ),
        "candidate_cost_r_fallback_is_authority": bool(
            packet.get("candidate_cost_r_fallback_is_authority", False)
        ),
        "pretrade_cost_packet_status": packet.get("status"),
        "pretrade_cost_packet_model_version": packet.get("model_version"),
        "pretrade_cost_refusal_reasons": list(packet.get("refusal_reasons") or []),
        "cost_quote_source": quote.get("quote_source"),
        "historical_tick_time_utc": quote.get("historical_tick_time_utc"),
        "measured_tick_spread_floor_r": packet.get("measured_tick_spread_floor_r"),
        "measured_tick_spread_floor_enforced": quote.get(
            "measured_tick_spread_floor_enforced"
        ),
        "symbol_specific_untradeable_cost_floor": bool(
            packet.get("symbol_specific_untradeable_cost_floor", False)
        ),
        "spread_r": packet.get("spread_r"),
        "expected_slippage_r": packet.get("expected_slippage_r"),
        "swap_cost_r": swap_cost.get("cost_r"),
        "commission_r": packet.get("commission_r", 0.0),
        "total_cost_components": dict(components),
    }


def marketable_limit_rebased_cost_authority_fields(
    fallback_result: Mapping[str, Any],
    *,
    expected_cost_r: Any = None,
) -> dict[str, Any]:
    """Return execution-cost authority fields after marketable-limit R rebase.

    The broker-calibrated cost itself is measured before execution. When a
    nominal limit is marketable at decision time, the effective fill geometry can
    change the R-denominator. Net replay already uses that effective R cost; the
    ledgers must carry the same value so later verifier/bucket logic does not
    mix original-geometry cost with effective-fill net R.
    """

    if not _runtime_bool(
        fallback_result.get("marketable_limit_cost_r_rebased_to_effective_fill_geometry"),
        False,
    ):
        return {}
    effective_cost = _optional_float(
        fallback_result.get("marketable_limit_effective_expected_cost_r")
    )
    if effective_cost is None:
        effective_cost = _optional_float(expected_cost_r)
    if effective_cost is None:
        return {}
    effective_cost = round(safe_float(effective_cost, 0.0), 8)
    original_cost = _optional_float(
        fallback_result.get("marketable_limit_original_expected_cost_r")
    )
    out: dict[str, Any] = {
        "expected_cost_r": effective_cost,
        "cost_r": effective_cost,
        "execution_expected_cost_r": effective_cost,
        "broker_calibrated_expected_cost_r": effective_cost,
        "broker_pretrade_cost_r": effective_cost,
        "fallback_execution_surcharge_r": 0.0,
        "total_execution_cost_r": effective_cost,
        "execution_cost_authority": (
            "broker_calibrated_cost_rebased_to_marketable_limit_effective_fill_geometry"
        ),
        "net_cost_scope": (
            "broker_calibrated_pretrade_cost_rebased_to_effective_fill_r_not_close_side_all_in"
        ),
        "marketable_limit_effective_expected_cost_r": effective_cost,
        "marketable_limit_cost_r_rebased_to_effective_fill_geometry": True,
        "marketable_limit_cost_authority_rebased_to_effective_fill_geometry": True,
    }
    if original_cost is not None:
        out["marketable_limit_original_expected_cost_r"] = round(
            safe_float(original_cost, 0.0),
            8,
        )
    return out


def broker_calibrated_pretrade_cost_model_for_execution(
    packets: Mapping[str, Any],
) -> dict[str, Any]:
    packet = normalized_pretrade_cost_packet_from_packets(packets)
    total_cost_r, total_cost_source, executable_block_reason = (
        executable_broker_calibrated_cost_r_from_packets(packets)
    )
    total_cost_r = safe_float(total_cost_r, 0.0)
    status = str(packet.get("status") or "").upper() or None
    commission_status = (
        packet.get("commission_model_status")
        or packets.get("gtos_vnext_commission_model_status")
        or "COMMISSION_INCLUDED_IN_SELECTED_CELL_RISK"
    )
    return {
        "status": status,
        "authority": packet.get("authority"),
        "expected_total_cost_r": round(total_cost_r, 8),
        "total_cost_r": round(total_cost_r, 8),
        "total_cost_source": total_cost_source,
        "executable_cost_block_reason": executable_block_reason,
        "source_status": packet.get("cost_source_gap_status"),
        "cost_source_gap_status": packet.get("cost_source_gap_status"),
        "commission_model_status": commission_status,
        "spread_r": packet.get("spread_r"),
        "max_spread_r": packet.get("max_spread_r"),
        "expected_slippage_r": packet.get("expected_slippage_r"),
        "swap_cost": packet.get("swap_cost"),
        "commission_r": packet.get("commission_r", 0.0),
        "model_version": packet.get("model_version"),
        "refusal_reasons": list(packet.get("refusal_reasons") or []),
    }


def pretrade_cost_executable_block_reason(
    pretrade_cost_packet: Mapping[str, Any],
    *,
    enforce: bool,
) -> str | None:
    """Return why a broker-calibrated pretrade cost packet is non-executable."""

    if not enforce:
        return None
    packet = normalized_pretrade_cost_packet(pretrade_cost_packet)
    status = str(packet.get("status") or "").upper()
    if status != "PASSED":
        if status == "REFUSED":
            refusal_reasons = [
                str(reason)
                for reason in (packet.get("refusal_reasons") or [])
                if str(reason or "").strip()
            ]
            return (
                "broker_cost_packet_refused:"
                + ("|".join(refusal_reasons) if refusal_reasons else "unspecified")
            )
        return f"broker_cost_packet_not_passed:{status or 'missing'}"
    source_gap_status = str(packet.get("cost_source_gap_status") or "")
    if source_gap_status != "source_bound_cost_authority_present":
        return f"broker_cost_source_gap_not_executable:{source_gap_status or 'missing'}"
    if bool(packet.get("candidate_cost_r_fallback_is_authority", False)):
        return "candidate_cost_r_fallback_not_order_authority"
    authority = str(packet.get("authority") or "")
    if authority != "broker_calibrated_replay_cost":
        return f"broker_cost_authority_unexpected:{authority or 'missing'}"
    return None


def executable_broker_calibrated_cost_r_from_packets(
    packets: Mapping[str, Any],
    *,
    fallback_surcharge_r: float = 0.0,
) -> tuple[float | None, str | None, str | None]:
    """Return executable broker-calibrated cost only when authority is proven."""

    packet = normalized_pretrade_cost_packet_from_packets(packets)
    block_reason = pretrade_cost_executable_block_reason(packet, enforce=True)
    if block_reason:
        return None, None, block_reason
    scalar_fields = packet.get("scalar_fields")
    scalar_fields = scalar_fields if isinstance(scalar_fields, Mapping) else {}
    raw_cost, source = _present_value_with_source(
        ("pretrade_broker_net_cost_packet.total_cost_r", packet.get("total_cost_r")),
        (
            "pretrade_broker_net_cost_packet.expected_total_cost_r",
            packet.get("expected_total_cost_r"),
        ),
        (
            "pretrade_broker_net_cost_packet.scalar_fields.total_cost_r",
            scalar_fields.get("total_cost_r"),
        ),
        (
            "packets.broker_calibrated_expected_cost_r",
            packets.get("broker_calibrated_expected_cost_r"),
        ),
        ("packets.broker_pretrade_cost_r", packets.get("broker_pretrade_cost_r")),
    )
    cost_r = _optional_float(raw_cost)
    if cost_r is None:
        return None, None, "broker_cost_value_missing"
    surcharge = max(0.0, safe_float(fallback_surcharge_r, 0.0))
    return round(cost_r + surcharge, 12), source, None


def replay_order_cost_authority_block_reason(
    packets: Mapping[str, Any],
    config: Mapping[str, Any] | None,
) -> str | None:
    """Fail closed before replay order/trade materialization on weak cost authority."""

    config = config if isinstance(config, Mapping) else {}
    runtime = (
        config.get("gtos_vnext_runtime")
        if isinstance(config.get("gtos_vnext_runtime"), Mapping)
        else {}
    )
    enforce = _runtime_bool(
        runtime.get("broad_live_as_if_replay_enforce_broker_cost_packet_status"),
        broad_live_as_if_no_broker_replay(config),
    )
    packet = normalized_pretrade_cost_packet_from_packets(packets)
    return pretrade_cost_executable_block_reason(packet, enforce=enforce)


