        risk_authority[
            "risk_finalizer_probe_risk_authority"
        ] = finalizer_risk_authority.get("risk_authority")
        finalizer_atom_packet = bind_canonical_executable_final_risk_atom(
            dict(finalizer_risk_authority),
            final_risk_pct=finalizer_selected_final_risk_pct,
            authority_source="risk_admitted_finalizer_selected_probe",
            balance=account.balance,
            candidate=candidate,
        )
        finalizer_atom = finalizer_atom_packet.get(
            "canonical_executable_final_risk_atom"
        )
        if isinstance(finalizer_atom, Mapping):
            risk_authority["risk_finalizer_selected_final_risk_atom"] = dict(
                finalizer_atom
            )
