def verify_primary_ftmo_source_coverage(route_dir: Path) -> dict[str, Any]:
    manifest = load_json(route_dir / "TIMEWARP_SOURCE_MANIFEST.json")
    sources = manifest.get("sources") if isinstance(manifest.get("sources"), list) else []
    blockers = load_jsonl(route_dir / "TIMEWARP_FTMO_HYDRATION_BLOCKER_LEDGER.jsonl")
    bad = []
    if manifest.get("ftmo_primary_hydration_complete") is not True:
        bad.append(
            {
                "reason": "ftmo_primary_hydration_incomplete",
                "missing_symbols": manifest.get("missing_symbols"),
                "ftmo_blocker_rows": len(blockers),
            }
        )
    by_symbol_tf = {
        (str(row.get("symbol")), str(row.get("timeframe")).upper())
        for row in sources
        if row.get("source_broker") == "FTMO"
    }
    for symbol in GTOS_24_SYMBOL_SURFACE:
        for timeframe in PRIMARY_SOURCE_TIMEFRAMES:
            if (symbol, timeframe) not in by_symbol_tf:
                symbol_blockers = [
                    row
                    for row in blockers
                    if row.get("symbol") == symbol and row.get("timeframe") == timeframe
                ]
                if not symbol_blockers:
                    bad.append(
                        {
                            "symbol": symbol,
                            "timeframe": timeframe,
                            "reason": "missing_ftmo_source_without_exact_blocker",
                        }
                    )
    for window in PRIORITY_TICK_WINDOWS:
        matching = [
            row
            for row in sources
            if row.get("source_broker") == "FTMO"
            and row.get("symbol") == window["symbol"]
            and str(row.get("timeframe")).upper() == "TICK"
            and safe_float(row.get("row_count"), 0.0) > 0
        ]
        blocker = [
            row
            for row in blockers
            if row.get("symbol") == window["symbol"]
            and row.get("timeframe") == "TICK"
            and row.get("tick_window_label") == window["label"]
        ]
        if not matching and not blocker:
            bad.append(
                {
                    "symbol": window["symbol"],
                    "timeframe": "TICK",
                    "window": window["label"],
                    "reason": "missing_priority_tick_source_without_exact_blocker",
                }
            )
    if bad:
        return fail("primary_ftmo_source_coverage", bad[:40])
    return ok(
        "primary_ftmo_source_coverage",
        {"sources": len(sources), "symbols": len(GTOS_24_SYMBOL_SURFACE)},
    )


def verify_source_labels(route_dir: Path) -> dict[str, Any]:
    manifest = load_json(route_dir / "TIMEWARP_SOURCE_MANIFEST.json")
    bad = []
    for source in manifest.get("sources", []):
        missing = [field for field in REQUIRED_SOURCE_FIELDS if source.get(field) in (None, "", [], {})]
        if missing:
            bad.append({"path": source.get("path"), "reason": "missing_required_source_fields", "fields": missing})
        if source.get("source_broker") != "FTMO":
            bad.append({"path": source.get("path"), "reason": "primary_source_broker_not_FTMO"})
        if source.get("source_role") not in FTMO_ALLOWED_SOURCE_ROLES:
            bad.append({"path": source.get("path"), "reason": "source_role_not_owner_authorized"})
        if source.get("not_redacted_account_native") is not True:
            bad.append({"path": source.get("path"), "reason": "not_redacted_account_native_not_true"})
        if source.get("broker_lifecycle_truth_satisfied") is not False:
            bad.append({"path": source.get("path"), "reason": "broker_lifecycle_truth_satisfied_not_false"})
        if source.get("source_truth_scope") != SOURCE_TRUTH_SCOPE:
            bad.append({"path": source.get("path"), "reason": "wrong_source_truth_scope"})
        if source.get("timeframe") == "M1" and source.get("ordered_tick_truth_satisfied") is not False:
            bad.append({"path": source.get("path"), "reason": "m1_claimed_tick_truth"})
        if source.get("timeframe") == "M15" and source.get("source_role") == "ordered_tick_truth":
            bad.append({"path": source.get("path"), "reason": "m15_labeled_ordered_tick_truth"})
        if source.get("diagnostic_fallback_only") and source.get("selected_status") == "selected_source_meets_day_floor":
            bad.append({"path": source.get("path"), "reason": "diagnostic_fallback_selected_as_primary"})
    if bad:
        return fail("source_labels", bad[:20])
    return ok("source_labels", {"sources": len(manifest.get("sources", []))})


def verify_no_future_leakage(route_dir: Path) -> dict[str, Any]:
    bad = []
    for row in load_jsonl(route_dir / "TIMEWARP_ASOF_MARKET_DATA_LEDGER.jsonl"):
        decision = parse_utc(row.get("decision_time_utc"))
        max_source = parse_utc(row.get("decision_max_source_time_utc"))
        if decision is None or max_source is None or max_source > decision:
            bad.append(row)
        present = set(row.get("decision_timeframes_present") or [])
        if set(PRIMARY_DECISION_TIMEFRAMES) - present:
            bad.append({"symbol": row.get("symbol"), "reason": "missing_live_decision_timeframes", "present": sorted(present)})
        if row.get("m1_or_tick_attached_to_decision") is not False:
            bad.append({"symbol": row.get("symbol"), "reason": "m1_or_tick_attached_to_predecision_raw_data"})
    for row in load_jsonl(route_dir / "TIMEWARP_CANDIDATE_MICROSCOPE_LEDGER.jsonl"):
        present = set(row.get("decision_input_timeframes") or [])
        if set(PRIMARY_DECISION_TIMEFRAMES) - present:
            bad.append({"candidate_id": row.get("candidate_id"), "reason": "candidate_missing_live_decision_timeframes", "present": sorted(present)})
        for field in (
            "probability_packet",
            "selector_packet",
            "lifecycle_packet",
            "moonshot_dynamic_execution_router_v4",
            "geometry_contract",
        ):
            hits = contains_forbidden_decision_key(row.get(field))
            if hits:
                bad.append({"candidate_id": row.get("candidate_id"), "field": field, "hits": hits[:10]})
    if bad:
        return fail("no_future_leakage", bad[:20])
    return ok("no_future_leakage")


def verify_candidate_decision_variance(route_dir: Path) -> dict[str, Any]:
    rows = load_jsonl(route_dir / "TIMEWARP_CANDIDATE_MICROSCOPE_LEDGER.jsonl")
    if len(rows) < 25:
        return ok("candidate_decision_variance", {"rows": len(rows), "status": "too_small_for_flatness_gate"})
    probs = {round(safe_float(row.get("candidate_probability")), 12) for row in rows if row.get("candidate_probability") is not None}
    evs = {round(safe_float(row.get("candidate_ev_r")), 12) for row in rows if row.get("candidate_ev_r") is not None}
    rrs = {round(safe_float(row.get("risk_reward_ratio") or row.get("rr")), 8) for row in rows if row.get("risk_reward_ratio") is not None or row.get("rr") is not None}
    actions = {str(row.get("selector_action")) for row in rows if row.get("selector_action") not in (None, "")}
    reasons = {str(row.get("selector_reason")) for row in rows if row.get("selector_reason") not in (None, "")}
    bad = []
    if len(probs) <= 1:
        bad.append({"reason": "candidate_probability_flat", "unique": sorted(probs)})
    if len(evs) <= 1:
        bad.append({"reason": "candidate_ev_r_flat", "unique": sorted(evs)})
    if len(rrs) <= 1:
        bad.append({"reason": "risk_reward_ratio_flat", "unique": sorted(rrs)})
    if len(actions) <= 1 and not any(row.get("selector_uniformity_source_bound_proof") for row in rows):
        bad.append({"reason": "selector_action_uniform_without_source_bound_proof", "unique": sorted(actions)})
    if len(reasons) <= 1 and not any(row.get("selector_uniformity_source_bound_proof") for row in rows):
        bad.append({"reason": "selector_reason_uniform_without_source_bound_proof", "unique": sorted(reasons)})
    if bad:
        return fail("candidate_decision_variance", bad)
    return ok(
        "candidate_decision_variance",
        {
            "rows": len(rows),
            "unique_probabilities": len(probs),
            "unique_evs": len(evs),
            "unique_rrs": len(rrs),
            "unique_selector_actions": len(actions),
            "unique_selector_reasons": len(reasons),
        },
    )


def verify_simulated_exposure_state(route_dir: Path) -> dict[str, Any]:
    score_rows = load_jsonl(route_dir / "TIMEWARP_SELECTOR_SCHEDULER_SCORECARD.jsonl")
    order_rows = load_jsonl(route_dir / "TIMEWARP_SIMULATED_ORDER_LEDGER.jsonl")
    material_orders = [
        row
        for row in order_rows
        if row.get("order_status") not in {None, "", "risk_rejected"}
    ]
    if not material_orders:
        return ok("simulated_exposure_state", {"material_orders": 0})
    nonempty_seen = [
        row
        for row in score_rows
        if safe_float(row.get("open_position_count_seen"), 0.0) > 0
        or safe_float(row.get("pending_order_count_seen"), 0.0) > 0
    ]
    if not nonempty_seen:
        return fail(
            "simulated_exposure_state",
            "scheduler_lifecycle_always_received_empty_open_pending_state_after_orders_existed",
        )
    return ok("simulated_exposure_state", {"nonempty_windows": len(nonempty_seen)})


def verify_pending_replacement_cancel_after_admission(route_dir: Path) -> dict[str, Any]:
    order_rows = load_jsonl(route_dir / "TIMEWARP_SIMULATED_ORDER_LEDGER.jsonl")
    order_by_id = {
        str(row.get("simulated_order_id") or ""): row
        for row in order_rows
        if row.get("simulated_order_id")
    }
    bad = []
    for row in order_rows:
        if row.get("order_status") != "cancelled_replaced_by_scheduler_v4":
            continue
        replacement_id = str(row.get("replacement_simulated_order_id") or "")
        if not replacement_id:
            bad.append(
                {
                    "simulated_order_id": row.get("simulated_order_id"),
                    "reason": "replacement_simulated_order_id_missing",
                }
            )
            continue
        replacement = order_by_id.get(replacement_id)
        if replacement is None:
            bad.append(
                {
                    "simulated_order_id": row.get("simulated_order_id"),
                    "replacement_simulated_order_id": replacement_id,
                    "reason": "replacement_order_row_absent",
                }
            )
            continue
        replacement_status = str(replacement.get("order_status") or "")
        if replacement_status in {
            "risk_rejected",
            "execution_manager_blocked",
            "held_existing_live_candidate_duplicate",
        }:
            bad.append(
                {
                    "simulated_order_id": row.get("simulated_order_id"),
                    "replacement_simulated_order_id": replacement_id,
                    "replacement_order_status": replacement_status,
                    "reason": "cancelled_before_admitted_replacement",
                }
            )
        if row.get("cancel_before_replacement_admitted") is not False:
            bad.append(
                {
                    "simulated_order_id": row.get("simulated_order_id"),
                    "replacement_simulated_order_id": replacement_id,
                    "reason": "cancel_before_replacement_admitted_not_false",
                }
            )
        gate_status = str(
            row.get("pending_replacement_causal_quality_gate_status") or ""
        ).strip().lower()
        if gate_status != "passed":
            bad.append(
                {
                    "simulated_order_id": row.get("simulated_order_id"),
                    "replacement_simulated_order_id": replacement_id,
                    "pending_replacement_causal_quality_gate_status": (
                        gate_status or "missing"
                    ),
                    "reason": "pending_replacement_causal_quality_gate_not_passed",
                }
            )
    if bad:
        return fail("pending_replacement_cancel_after_admission", bad[:20])
    return ok(
        "pending_replacement_cancel_after_admission",
        {
            "cancelled_replaced_orders": len(
                [
                    row
                    for row in order_rows
                    if row.get("order_status") == "cancelled_replaced_by_scheduler_v4"
                ]
            )
        },
    )


def verify_fill_times(route_dir: Path) -> dict[str, Any]:
    bad = []
    for row in load_jsonl(route_dir / "TIMEWARP_ORDERED_PATH_ORACLE_LEDGER.jsonl"):
        decision = parse_utc(row.get("asof_utc"))
        fill = parse_utc(row.get("fill_time_utc"))
        if str(row.get("fill_status") or "").startswith("filled") and (
            decision is None or fill is None or fill <= decision
        ):
            bad.append(row)
        if row.get("source") == "m15":
            bad.append({"candidate_id": row.get("candidate_id"), "reason": "m15_used_for_ordered_path"})
        if row.get("source_broker") == "FTMO" and row.get("broker_lifecycle_truth_satisfied") is not False:
            bad.append({"candidate_id": row.get("candidate_id"), "reason": "ftmo_path_claimed_broker_lifecycle_truth"})
    for row in load_jsonl(route_dir / "TIMEWARP_SIMULATED_ORDER_LEDGER.jsonl"):
        decision = parse_utc(row.get("decision_time_utc"))
        fill = parse_utc(row.get("fill_time_utc"))
        if str(row.get("order_status") or "").startswith("filled") and (
            decision is None or fill is None or fill <= decision
        ):
            bad.append({"simulated_order_id": row.get("simulated_order_id"), "reason": "fill_not_after_decision"})
    if bad:
        return fail("fill_times_and_path_source", bad[:20])
    return ok("fill_times_and_path_source")


RISK_BINDING_REQUIRED_FIELDS = (
    "risk_per_trade_pct",
    "risk_config_source",
    "selected_cell_risk_pct",
    "scheduler_approved_risk_pct",
    "portfolio_ceiling_pct",
    "cluster_correlation_ceiling_pct",
    "open_risk_pct_before",
    "pending_risk_pct_before",
    "same_symbol_lifecycle_exposure_risk_pct",
    "daily_runtime_headroom_pct_before",
    "risk_decision",
    "order_size_units_proxy",
    "risk_authority_packet_hash_sha256",
)


def verify_risk_runtime_binding(route_dir: Path) -> dict[str, Any]:
    bad = []
    account_rows = load_jsonl(route_dir / "TIMEWARP_SIMULATED_ACCOUNT_LEDGER.jsonl")
    order_rows = load_jsonl(route_dir / "TIMEWARP_SIMULATED_ORDER_LEDGER.jsonl")
    candidate_rows = load_jsonl(route_dir / "TIMEWARP_CANDIDATE_MICROSCOPE_LEDGER.jsonl")
    if not account_rows or not order_rows or not candidate_rows:
        return fail(
            "risk_runtime_binding",
            {
                "reason": "materialized_risk_runtime_rows_missing",
                "account_rows": len(account_rows),
                "order_rows": len(order_rows),
                "candidate_rows": len(candidate_rows),
            },
        )
    for row in account_rows:
        missing = [field for field in RISK_BINDING_REQUIRED_FIELDS if row.get(field) in (None, "", [], {})]
        if missing:
            bad.append({"ledger": "account", "id": row.get("simulated_order_id"), "missing": missing})
    for row in order_rows:
        missing = [field for field in RISK_BINDING_REQUIRED_FIELDS if row.get(field) in (None, "", [], {})]
        if row.get("order_status") == "risk_rejected":
            missing = [field for field in missing if field != "order_size_units_proxy"]
        if missing:
            bad.append({"ledger": "order", "id": row.get("simulated_order_id"), "missing": missing})
        risk_authority = row.get("risk_authority") if isinstance(row.get("risk_authority"), Mapping) else {}
        prop = risk_authority.get("prop_firm_headroom") if isinstance(risk_authority, Mapping) else {}
        prop = prop if isinstance(prop, Mapping) else {}
        if prop.get("broker_real_headroom_satisfied") is not False:
            bad.append({"ledger": "order", "id": row.get("simulated_order_id"), "reason": "simulated_prop_headroom_not_marked_non_broker_real"})
    for row in candidate_rows:
        pre = row.get("risk_authority_pre_scheduler")
        if (
            not isinstance(pre, Mapping)
            or pre.get("risk_per_trade_pct") in (None, "")
            or pre.get("risk_config_source") in (None, "")
        ):
            bad.append({"ledger": "candidate", "candidate_id": row.get("candidate_id"), "reason": "pre_scheduler_risk_authority_missing"})
    if bad:
        return fail("risk_runtime_binding", bad[:30])
    return ok(
        "risk_runtime_binding",
        {
            "account_rows": len(account_rows),
            "order_rows": len(order_rows),
            "candidate_rows": len(candidate_rows),
        },
    )


def verify_account_math(route_dir: Path) -> dict[str, Any]:
    rows = load_jsonl(route_dir / "TIMEWARP_SIMULATED_ACCOUNT_LEDGER.jsonl")
    bad = []
    last_balance: dict[str, float] = {}
    last_event_time: dict[str, datetime] = {}
    for row in rows:
        campaign = str(row.get("campaign"))
        before = safe_float(row.get("balance_before"))
        after = safe_float(row.get("balance_after"))
        pnl = safe_float(row.get("pnl_cash"))
        event_time = parse_utc(row.get("event_time_utc"))
        if event_time is not None and campaign in last_event_time and event_time < last_event_time[campaign]:
            bad.append({"row": row, "reason": "account_event_time_decreased"})
        if event_time is not None:
            last_event_time[campaign] = event_time
        if row.get("event") != "simulated_trade_closed" and abs(pnl) > 1e-9:
            bad.append({"row": row, "reason": "pnl_applied_before_trade_close_event"})
        if row.get("event") == "simulated_trade_closed":
            if abs((before + pnl) - after) > 1e-6:
                bad.append(row)
        if campaign in last_balance and row.get("event") == "simulated_limit_order_placed":
            if abs(before - last_balance[campaign]) > 1e-6:
                bad.append({"row": row, "expected_previous_balance": last_balance[campaign]})
        last_balance[campaign] = after
    if bad:
        return fail("account_math", bad[:20])
    return ok("account_math", {"rows": len(rows)})


def verify_net_cost_reporting(route_dir: Path) -> dict[str, Any]:
    bad = []
    for path_name in ("TIMEWARP_SIMULATED_TRADE_LEDGER.jsonl", "TIMEWARP_DAILY_MICROSCOPE_SUMMARY.jsonl"):
        rows = load_jsonl(route_dir / path_name)
        for row in rows:
            for field in ("gross_r", "expected_cost_r", "net_proxy_r"):
                if row.get(field) in (None, ""):
                    bad.append({"path": path_name, "id": row.get("simulated_trade_id") or row.get("trading_day"), "missing": field})
            if row.get("total_r") is not None and row.get("net_proxy_r") is not None:
                if abs(safe_float(row.get("total_r")) - safe_float(row.get("net_proxy_r"))) > 1e-6:
                    bad.append({"path": path_name, "id": row.get("trading_day"), "reason": "summary_total_r_not_net_proxy_r"})
    if bad:
        return fail("net_cost_reporting", bad[:30])
    return ok("net_cost_reporting")


def verify_missed_opportunities_scored(route_dir: Path) -> dict[str, Any]:
    rows = load_jsonl(route_dir / "TIMEWARP_MISSED_OPPORTUNITY_LEDGER.jsonl")
    if not rows:
        return fail("missed_opportunities_scored", "missing_missed_opportunity_rows")
    bad = [
        row
        for row in rows
        if row.get("opportunity_path_scored") is not True
        or row.get("ordered_path_status") == "not_scored_for_nonselected_candidate_full_row_preserved"
    ]
    if bad:
        return fail("missed_opportunities_scored", bad[:20])
    return ok("missed_opportunities_scored", {"rows": len(rows)})


def verify_order_status_split(route_dir: Path) -> dict[str, Any]:
    daily = load_jsonl(route_dir / "TIMEWARP_DAILY_MICROSCOPE_SUMMARY.jsonl")
    bad = []
    for row in daily:
        if row.get("risk_rejected_orders") is None:
            bad.append({"day": row.get("trading_day"), "reason": "risk_rejected_orders_missing"})
        if row.get("expired_unfilled_orders") is None:
            bad.append({"day": row.get("trading_day"), "reason": "expired_unfilled_orders_missing"})
        if row.get("not_filled_orders") is None:
            bad.append({"day": row.get("trading_day"), "reason": "not_filled_orders_missing"})
    if bad:
        return fail("order_status_split", bad)
    return ok("order_status_split", {"days": len(daily)})


def verify_daily_inactive_balance(route_dir: Path) -> dict[str, Any]:
    rows = load_jsonl(route_dir / "TIMEWARP_DAILY_MICROSCOPE_SUMMARY.jsonl")
    previous_balance: dict[str, float] = {}
    bad = []
    for row in sorted(rows, key=lambda item: (str(item.get("campaign")), str(item.get("trading_day")))):
        campaign = str(row.get("campaign") or row.get("phase") or "")
        expected_before = previous_balance.get(campaign, STARTING_BALANCE)
        ending = safe_float(row.get("ending_balance"))
        inactive = all(
            safe_float(row.get(field), 0.0) == 0.0
            for field in (
                "candidate_rows",
                "simulated_orders",
                "filled_trades",
                "risk_rejected_orders",
                "expired_unfilled_orders",
                "not_filled_orders",
                "gross_r",
                "net_proxy_r",
                "total_r",
            )
        )
        if inactive and abs(ending - expected_before) > 1e-6:
            bad.append(
                {
                    "campaign": campaign,
                    "trading_day": row.get("trading_day"),
                    "ending_balance": ending,
                    "expected_unchanged_balance": expected_before,
                    "reason": "inactive_day_balance_changed",
                }
            )
        previous_balance[campaign] = ending
    if bad:
        return fail("daily_inactive_balance", bad[:20])
    return ok("daily_inactive_balance", {"days": len(rows)})


def verify_required_artifacts(route_dir: Path) -> dict[str, Any]:
    missing = [name for name in REQUIRED_ARTIFACTS if not (route_dir / name).exists()]
    if missing:
        return fail("required_artifacts", missing)
    return ok("required_artifacts", {"count": len(REQUIRED_ARTIFACTS)})


def verify_scratch_cleanup(route_dir: Path) -> dict[str, Any]:
    path = route_dir / "TIMEWARP_SCRATCH_CLEANUP_PROOF.json"
    if not path.exists():
        return fail("scratch_cleanup", "missing_scratch_cleanup_proof")
    proof = load_json(path)
    if proof.get("durable_artifacts_present_before_cleanup") is not True:
        return fail("scratch_cleanup", "durable_artifacts_not_proven_before_cleanup")
    if proof.get("scratch_exists_before_cleanup") is not True:
        return fail("scratch_cleanup", "scratch_existence_before_cleanup_not_proven")
    if proof.get("scratch_exists_after_cleanup") is not False:
        return fail("scratch_cleanup", "scratch_cleanup_not_completed")
    if proof.get("cleanup_status") != "completed_after_durable_artifacts":
        return fail("scratch_cleanup", proof)
    return ok("scratch_cleanup", {"scratch_path": proof.get("scratch_path")})


def verify_repair_ledger(route_dir: Path) -> dict[str, Any]:
    bad = []
    rows = load_jsonl(route_dir / "TIMEWARP_REPAIR_DECISION_LEDGER.jsonl")
    summary = load_json(route_dir / "TIMEWARP_REPAIR_BEFORE_AFTER_SUMMARY.json")
    counted_rows = 0
    for row in rows:
        status = str(row.get("status") or "")
        counts = row.get("counts_as_real_system_repair")
        if "diagnostic" in status and counts is not False:
            bad.append({"repair_id": row.get("repair_id"), "reason": "diagnostic_repair_counted_as_real"})
        if counts is True:
            counted_rows += 1
            missing = [
                field
                for field in ("repair_scope", "changed_paths", "tests", "replay_effect")
                if row.get(field) in (None, "", [], {})
            ]
            if missing:
                bad.append(
                    {
                        "repair_id": row.get("repair_id"),
                        "reason": "counted_repair_missing_proof_fields",
                        "missing": missing,
                    }
                )
            if not status.startswith("completed_real_"):
                bad.append({"repair_id": row.get("repair_id"), "reason": "counted_repair_status_not_real"})
            if row.get("repair_scope") not in {"research_infra", "v4_code", "config", "research_infra_and_v4_adapter"}:
                bad.append({"repair_id": row.get("repair_id"), "reason": "counted_repair_scope_not_allowed"})
        elif counts is not False:
            bad.append({"repair_id": row.get("repair_id"), "reason": "repair_count_flag_not_boolean"})
    if int(summary.get("repair_count") or 0) != counted_rows:
        bad.append(
            {
                "reason": "repair_summary_count_mismatch",
                "summary_repair_count": summary.get("repair_count"),
                "counted_rows": counted_rows,
            }
        )
    if counted_rows <= 0:
        bad.append({"reason": "no_real_research_infra_or_v4_repair_counted"})
    if bad:
        return fail("repair_ledger", bad[:20])
    return ok("repair_ledger", {"counted_real_repairs": counted_rows})


def verify_completion_audit(route_dir: Path) -> dict[str, Any]:
    path = route_dir / "COMPLETION_AUDIT.md"
    if not path.exists():
        return fail("completion_audit", "missing_completion_audit")
    text = path.read_text(encoding="utf-8")
    manifest = load_json(route_dir / "TIMEWARP_SOURCE_MANIFEST.json")
    repair_summary = load_json(route_dir / "TIMEWARP_REPAIR_BEFORE_AFTER_SUMMARY.json")
    required = [
        "Completion status:",
        "Baseline total R:",
        "Repaired total R:",
        "Holdout total R:",
        "Remaining Source Requirements",
        "Primary FTMO hydration complete:",
        "Real repairs completed:",
        "source_broker=FTMO",
        "row_count",
        "sha256",
        "export_tool",
        "manifest_path",
    ]
    missing = [item for item in required if item not in text]
    if missing:
        return fail("completion_audit", {"missing_text": missing})
    if "Completion status: COMPLETE" in text:
        if manifest.get("ftmo_primary_hydration_complete") is not True:
            return fail("completion_audit", "complete_claim_without_primary_ftmo_hydration")
        if int(repair_summary.get("repair_count") or 0) <= 0:
            return fail("completion_audit", "complete_claim_without_real_repairs")
    return ok("completion_audit")


def verify_live_replay_mode_contract(route_dir: Path) -> dict[str, Any]:
    anchor = load_json(route_dir / "TIMEWARP_CONTEXT_ANCHOR.json")
    parity = load_json(route_dir / "TIMEWARP_LIVE_REPLAY_PARITY_CHECKLIST.json")
    asof_rows = load_jsonl(route_dir / "TIMEWARP_ASOF_MARKET_DATA_LEDGER.jsonl")
    bad = []
    if anchor.get("full_live_replay_parity_claim") is not False:
        bad.append({"reason": "context_anchor_overclaims_full_live_replay_parity"})
    if "not_full" not in str(anchor.get("route_classification") or ""):
        bad.append({"reason": "context_anchor_missing_not_full_classification"})
    if anchor.get("owner_override_no_generate_live_state") is not None:
        bad.append({"reason": "stale_owner_override_no_generate_live_state_present"})
    if parity.get("route_classification") != "live_replay_mode_repair_in_progress_not_full_parity_complete":
        bad.append({"reason": "parity_checklist_wrong_route_classification"})
    for row in asof_rows:
        if row.get("live_replay_mode") is not True:
            bad.append({"symbol": row.get("symbol"), "reason": "asof_row_missing_live_replay_mode"})
        if row.get("live_ingestion_function") != LIVE_INGESTION_FUNCTION_ID:
            bad.append({"symbol": row.get("symbol"), "reason": "asof_row_not_bound_to_live_ingestion"})
        if row.get("raw_data_construction_mode") != LIVE_REPLAY_RAW_DATA_MODE:
            bad.append({"symbol": row.get("symbol"), "reason": "asof_row_wrong_raw_data_construction_mode"})
        if row.get("route_local_raw_packet_used") is not False:
            bad.append({"symbol": row.get("symbol"), "reason": "route_local_raw_packet_used"})
        if row.get("predecision_tick_features_enabled") is not False:
            bad.append(
                {
                    "symbol": row.get("symbol"),
                    "reason": "predecision_tick_features_not_disabled_for_htf_only_replay",
                }
            )
    if bad:
        return fail("live_replay_mode_contract", bad[:30])
    return ok("live_replay_mode_contract", {"asof_rows": len(asof_rows)})


def verify_packet_sidecars(route_dir: Path) -> dict[str, Any]:
    candidates = load_jsonl(route_dir / "TIMEWARP_CANDIDATE_MICROSCOPE_LEDGER.jsonl")
    scorecards = load_jsonl(route_dir / "TIMEWARP_SELECTOR_SCHEDULER_SCORECARD.jsonl")
    sidecars = load_jsonl(route_dir / "TIMEWARP_PACKET_SIDECAR_LEDGER.jsonl")
    sidecar_ids = {row.get("packet_sidecar_id") for row in sidecars}
    bad = []
    for row in candidates:
        if row.get("packet_sidecar_id") not in sidecar_ids:
            bad.append({"candidate_id": row.get("candidate_id"), "reason": "candidate_missing_lossless_sidecar"})
    for row in scorecards:
        if row.get("packet_sidecar_id") not in sidecar_ids:
            bad.append({"decision_time_utc": row.get("decision_time_utc"), "reason": "scheduler_missing_lossless_sidecar"})
    required_types = {"candidate_v4_decision_stack", "scheduler_v4_window"}
    seen_types = {str(row.get("sidecar_type")) for row in sidecars}
    missing_types = sorted(required_types - seen_types)
    if missing_types:
        bad.append({"reason": "missing_required_sidecar_types", "missing_types": missing_types})
    if bad:
        return fail("packet_sidecars", bad[:30])
    return ok(
        "packet_sidecars",
        {"candidate_rows": len(candidates), "scorecard_rows": len(scorecards), "sidecar_rows": len(sidecars)},
    )


def verify_tick_truth_usage(route_dir: Path) -> dict[str, Any]:
    manifest = load_json(route_dir / "TIMEWARP_SOURCE_MANIFEST.json")
    tick_sources = [
        row
        for row in manifest.get("sources", [])
        if str(row.get("timeframe")).upper() == "TICK"
        and safe_float(row.get("row_count"), 0.0) > 0
    ]
    oracle_rows = load_jsonl(route_dir / "TIMEWARP_ORDERED_PATH_ORACLE_LEDGER.jsonl")
    tick_truth_rows = [
        row for row in oracle_rows if row.get("ordered_tick_truth_satisfied") is True
    ]
    if tick_sources and not tick_truth_rows:
        return fail(
            "tick_truth_usage",
            {
                "reason": "tick_sources_present_but_no_selected_oracle_rows_used_ordered_tick_truth",
                "tick_sources": len(tick_sources),
                "oracle_rows": len(oracle_rows),
            },
        )
    return ok(
        "tick_truth_usage",
        {"tick_sources": len(tick_sources), "tick_truth_rows": len(tick_truth_rows)},
    )


def verify_microscopic_intelligence_artifacts(route_dir: Path) -> dict[str, Any]:
    winners = load_jsonl(route_dir / "TIMEWARP_WINNER_ANATOMY_LEDGER.jsonl")
    losers = load_jsonl(route_dir / "TIMEWARP_LOSER_ANATOMY_LEDGER.jsonl")
    rollups = load_jsonl(route_dir / "TIMEWARP_SYMBOL_SESSION_FRAMEWORK_POLICY_ROLLUP.jsonl")
    trades = load_jsonl(route_dir / "TIMEWARP_SIMULATED_TRADE_LEDGER.jsonl")
    bad = []
    if trades and not winners:
        bad.append({"reason": "winner_anatomy_missing_with_trade_rows"})
    if not rollups:
        bad.append({"reason": "symbol_session_framework_policy_rollups_missing"})
    required_trade_fields = (
        "entry_time_utc",
        "exit_time_utc",
        "duration_minutes",
        "gross_r",
        "expected_cost_r",
        "net_proxy_r",
        "mfe_r",
        "mae_r",
        "terminal_outcome",
        "close_reason",
    )
    for row in trades:
        missing = [field for field in required_trade_fields if row.get(field) in (None, "", [], {})]
        if missing:
            bad.append({"simulated_trade_id": row.get("simulated_trade_id"), "missing": missing})
    if bad:
        return fail("microscopic_intelligence_artifacts", bad[:30])
    return ok(
        "microscopic_intelligence_artifacts",
        {"winners": len(winners), "losers": len(losers), "rollups": len(rollups), "trades": len(trades)},
    )


def verify_no_proxy_exit_outcomes(route_dir: Path) -> dict[str, Any]:
    bad = []
    for path_name in (
        "TIMEWARP_SIMULATED_TRADE_LEDGER.jsonl",
        "TIMEWARP_EXIT_GEOMETRY_HARVEST_LEDGER.jsonl",
        "TIMEWARP_MISSED_OPPORTUNITY_LEDGER.jsonl",
    ):
        for row in load_jsonl(route_dir / path_name):
            reason = str(
                row.get("close_reason")
                or row.get("opportunity_close_reason")
                or row.get("terminal_outcome")
                or ""
            )
            if "filled_no_terminal_close_mark_proxy" in reason or "filled_no_terminal_partial_harvest_proxy" in reason:
                bad.append({"path": path_name, "id": row.get("candidate_id"), "reason": reason})
    if bad:
        return fail("no_proxy_exit_outcomes", bad[:30])
    return ok("no_proxy_exit_outcomes")


def verify_materialized_simulation_ledgers(route_dir: Path) -> dict[str, Any]:
    counts = {
        "orders": len(load_jsonl(route_dir / "TIMEWARP_SIMULATED_ORDER_LEDGER.jsonl")),
        "trades": len(load_jsonl(route_dir / "TIMEWARP_SIMULATED_TRADE_LEDGER.jsonl")),
        "events": len(load_jsonl(route_dir / "TIMEWARP_SIMULATED_EVENT_LEDGER.jsonl")),
        "account_rows": len(load_jsonl(route_dir / "TIMEWARP_SIMULATED_ACCOUNT_LEDGER.jsonl")),
        "missed_opportunities": len(
            load_jsonl(route_dir / "TIMEWARP_MISSED_OPPORTUNITY_LEDGER.jsonl")
        ),
        "daily_summaries": len(
            load_jsonl(route_dir / "TIMEWARP_DAILY_MICROSCOPE_SUMMARY.jsonl")
        ),
    }
    missing = [name for name, count in counts.items() if count <= 0]
    if missing:
        return fail("materialized_simulation_ledgers", {"counts": counts, "empty": missing})
    return ok("materialized_simulation_ledgers", counts)


def verify_route(
    *,
    repo_root: Path | str = Path("."),
    route_dir: Path | str | None = None,
    write_result: bool = False,
) -> dict[str, Any]:
    repo_root = Path(repo_root)
    if route_dir is None:
        route_dir = repo_root / ROUTE_DIR
    else:
        route_dir = Path(route_dir)
        if not route_dir.is_absolute():
            route_dir = repo_root / route_dir
    checks = [
        verify_campaign_bounds(route_dir),
        verify_primary_ftmo_source_coverage(route_dir),
        verify_source_labels(route_dir),
        verify_no_future_leakage(route_dir),
        verify_candidate_decision_variance(route_dir),
        verify_simulated_exposure_state(route_dir),
        verify_pending_replacement_cancel_after_admission(route_dir),
        verify_fill_times(route_dir),
        verify_risk_runtime_binding(route_dir),
        verify_account_math(route_dir),
        verify_net_cost_reporting(route_dir),
        verify_missed_opportunities_scored(route_dir),
        verify_order_status_split(route_dir),
        verify_daily_inactive_balance(route_dir),
        verify_required_artifacts(route_dir),
        verify_live_replay_mode_contract(route_dir),
        verify_packet_sidecars(route_dir),
        verify_tick_truth_usage(route_dir),
        verify_microscopic_intelligence_artifacts(route_dir),
        verify_no_proxy_exit_outcomes(route_dir),
        verify_scratch_cleanup(route_dir),
        verify_repair_ledger(route_dir),
        verify_completion_audit(route_dir),
        verify_materialized_simulation_ledgers(route_dir),
    ]
    failures = [check for check in checks if check["status"] != "passed"]
    result = {
        "route_id": ROUTE_ID,
        "generated_at_utc": utc_now(),
        "status": "passed" if not failures else "failed",
        "checks": checks,
        "failure_count": len(failures),
        "no_live_broker_mutation": True,
        "no_remote_push": True,
        "no_paid_api": True,
        "production_change_claim": False,
    }
    if write_result:
        atomic_write_json(route_dir / "TIMEWARP_VERIFICATION_RESULT.json", result)
    return result


